getgenv().SliceHub = getgenv().SliceHub or {}

local __SliceHubRawPrint = print
local __SliceHubRawWarn = warn
local __SliceHubRuntimeEnv =
    (type(getgenv) == "function" and getgenv())
    or _G

local function __SliceHubDebugEnabled()
    return type(__SliceHubRuntimeEnv) == "table"
        and __SliceHubRuntimeEnv.SliceHubDebug == true
end

local function print(...)
    if __SliceHubDebugEnabled() then
        __SliceHubRawPrint(...)
    end
end

local function warn(...)
    if __SliceHubDebugEnabled() then
        __SliceHubRawWarn(...)
    end
end

local function __SliceHubCritical(message)
    local resolved = tostring(message or "Unknown SliceHub error")
    __SliceHubRawWarn(resolved)

    pcall(function()
        game:GetService("StarterGui"):SetCore(
            "SendNotification",
            {
                Title = "SliceHub failed to start",
                Text = string.sub(resolved, 1, 220),
                Duration = 15,
            }
        )
    end)
end



