local function __SliceHubStallSafetyEvidence()
    local loadingDocksPlaces = {
        [17688739434] = true,
        [110415968652032] = true,
    }

    if loadingDocksPlaces[
        tonumber(game.PlaceId) or 0
    ] ~= true then
        return false
    end

    local function containsStall(value)
        local lower = string.lower(
            tostring(value or "")
        )
        lower = string.gsub(lower, "<.->", "")
        lower = string.gsub(lower, "%s+", " ")

        return lower == "stall"
            or string.find(
                lower,
                "stall bertholdt",
                1,
                true
            ) ~= nil
            or string.find(
                lower,
                "stall mission",
                1,
                true
            ) ~= nil
    end

    local function inspectObject(object)
        if not object then
            return false
        end

        if containsStall(object.Name) then
            return true
        end

        for _, key in ipairs({
            "Objective",
            "Mission",
            "Mode",
            "Detail",
            "Type",
            "State",
        }) do
            local value = nil
            pcall(function()
                value = object:GetAttribute(key)
            end)

            if containsStall(value) then
                return true
            end
        end

        if object:IsA("StringValue")
            or object:IsA("ObjectValue") then
            local value = nil
            pcall(function()
                value = object.Value
            end)

            if containsStall(value) then
                return true
            end
        end

        if object:IsA("TextLabel")
            or object:IsA("TextButton")
            or object:IsA("TextBox") then
            if containsStall(object.Text) then
                return true
            end
        end

        return false
    end

    local deadline = os.clock() + 3.25

    repeat
        local workspaceService =
            game:GetService("Workspace")

        if inspectObject(workspaceService) then
            return true
        end

        for _, rootName in ipairs({
            "Objective",
            "Objectives",
            "Data",
        }) do
            local root =
                workspaceService:FindFirstChild(
                    rootName
                )

            if root then
                if inspectObject(root) then
                    return true
                end

                for _, object in ipairs(
                    root:GetDescendants()
                ) do
                    if inspectObject(object) then
                        return true
                    end
                end
            end
        end

        local players =
            game:GetService("Players")
        local localPlayer =
            players.LocalPlayer
        local playerGui =
            localPlayer
            and localPlayer:FindFirstChildOfClass(
                "PlayerGui"
            )

        if playerGui then
            for _, object in ipairs(
                playerGui:GetDescendants()
            ) do
                if (
                    object:IsA("TextLabel")
                    or object:IsA("TextButton")
                    or object:IsA("TextBox")
                )
                    and object.Visible
                    and inspectObject(object) then
                    return true
                end
            end
        end

        if os.clock() >= deadline then
            break
        end

        task.wait(0.18)
    until false

    return false
end

