    local function ensureFolder()
        if type(makeFolder) ~= "function" then
            return false
        end

        local exists = false

        if type(isFolder) == "function" then
            local ok, result = pcall(
                isFolder,
                "SH"
            )
            exists = ok and result == true
        end

        if not exists then
            pcall(makeFolder, "SH")
        end

        return true
    end

    local function readTextFile(path)
        if type(readFile) ~= "function" then
            return nil
        end

        if type(isFile) == "function" then
            local okExists, exists =
                pcall(isFile, path)

            if not okExists or exists ~= true then
                return nil
            end
        end

        local ok, result =
            pcall(readFile, path)

        if ok and type(result) == "string" then
            return result
        end

        return nil
    end

    local function ensureApiConfiguration()
        -- The API file is runtime configuration, not a saved license.
        -- Create/repair it before any automatic or manual key validation.
        ensureFolder()

        local apiPath = "SH/license_api.txt"
        local savedApi = trim(readTextFile(apiPath) or "")
        local needsRepair =
            savedApi == ""
            or string.find(
                savedApi,
                "YOUR_RAILWAY_DOMAIN",
                1,
                true
            ) ~= nil

        if not needsRepair then
            return true
        end

        if type(writeFile) ~= "function" then
            return false
        end

        local apiUrl = trim(DefaultApiUrl)
        if apiUrl == ""
            or string.find(
                apiUrl,
                "YOUR_RAILWAY_DOMAIN",
                1,
                true
            ) then
            apiUrl = "https://slicebot-production.up.railway.app/api/validate"
        end

        local okWrite = pcall(
            writeFile,
            apiPath,
            apiUrl
        )

        return okWrite
    end

    ensureApiConfiguration()

    local function resolveApiUrl()
        local override = trim(
            Environment.SLICEHUB_KEY_API_URL
            or Environment.SliceHubKeyApiUrl
            or ""
        )

        if override ~= ""
            and not string.find(
                override,
                "YOUR_RAILWAY_DOMAIN",
                1,
                true
            ) then
            return override
        end

        local savedApi =
            trim(
                readTextFile(
                    "SH/license_api.txt"
                )
                or ""
            )

        if savedApi ~= "" then
            return savedApi
        end

        return trim(DefaultApiUrl)
    end

    local function normalizeUrlCandidates(raw)
        raw = trim(raw)

        if raw == ""
            or string.find(
                raw,
                "YOUR_RAILWAY_DOMAIN",
                1,
                true
            ) then
            return {}
        end

        if not string.match(
            string.lower(raw),
            "^https?://"
        ) then
            raw = "https://" .. raw
        end

        raw = string.gsub(raw, "/+$", "")

        local candidates = {}
        local seen = {}

        local function push(url)
            if url ~= ""
                and not seen[url] then
                seen[url] = true
                candidates[#candidates + 1] = url
            end
        end

        if string.find(
            string.lower(raw),
            "/api/",
            1,
            true
        )
            or string.match(
                string.lower(raw),
                "/validate[%w%-%_]*$"
            ) then
            push(raw)
        else
            push(raw .. "/api/validate")
            push(raw .. "/validate")
        end

        return candidates
    end

    local function savedLicense()
        local content =
            readTextFile("SH/license.json")

        if not content or content == "" then
            return nil
        end

        local ok, decoded = pcall(
            HttpService.JSONDecode,
            HttpService,
            content
        )

        if ok and type(decoded) == "table" then
            return decoded
        end

        return nil
    end

    local function saveLicense(key, data)
        if type(writeFile) ~= "function" then
            return false
        end

        ensureFolder()

        local payload = {
            key = key,
            tier = data and (
                data.tier
                or data.plan
                or data.licenseType
            ) or nil,
            expiresAt = data
                and tonumber(
                    data.expiresAt
                    or data.expires
                    or data.expiry
                )
                or nil,
            savedAt = os.time(),
        }

        local okEncode, encoded = pcall(
            HttpService.JSONEncode,
            HttpService,
            payload
        )

        if not okEncode then
            return false
        end

        local okWrite = pcall(
            writeFile,
            "SH/license.json",
            encoded
        )

        return okWrite
    end

    local function clearSavedLicense()
        if type(deleteFile) == "function" then
            pcall(
                deleteFile,
                "SH/license.json"
            )
        elseif type(writeFile) == "function" then
            pcall(
                writeFile,
                "SH/license.json",
                ""
            )
        end
    end

    local function requestStatus(response)
        if type(response) ~= "table" then
            return nil
        end

        return tonumber(
            response.StatusCode
            or response.Status
            or response.status_code
        )
    end

    local function requestBody(response)
        if type(response) == "string" then
            return response
        end

        if type(response) ~= "table" then
            return nil
        end

        return response.Body
            or response.body
            or response.Response
            or response.response
    end

    local function decodeResponse(body)
        body = trim(body)

        if body == "" then
            return nil, "Empty response"
        end

        local ok, decoded = pcall(
            HttpService.JSONDecode,
            HttpService,
            body
        )

        if ok and type(decoded) == "table" then
            return decoded
        end

        if string.lower(body) == "true" then
            return {valid = true}
        end

        return nil, "Invalid JSON response"
    end

    local function urlEncode(value)
        local ok, result = pcall(
            HttpService.UrlEncode,
            HttpService,
            tostring(value or "")
        )

        return ok and result or tostring(value or "")
    end

    local function resolveDeviceId()
        local value = ""

        local environment =
            type(getgenv) == "function"
            and getgenv()
            or _G

        local getHwid =
            environment
            and environment.gethwid
            or gethwid

        if type(getHwid) == "function" then
            pcall(function()
                value = tostring(getHwid())
            end)
        end

        if value == "" then
            pcall(function()
                value = tostring(
                    game:GetService(
                        "RbxAnalyticsService"
                    ):GetClientId()
                )
            end)
        end

        if value == "" then
            -- Stable fallback so teleports between AOT:R places do not
            -- create false HWID mismatches on limited executors.
            value = "roblox-user:" .. tostring(Player.UserId)
        end

        return value
    end

    local function validateAtUrl(url, key)
        local deviceId = resolveDeviceId()
        local requestPayload = {
            key = key,
            scriptKey = key,
            userId = tostring(Player.UserId),
            username = tostring(Player.Name),
            displayName = tostring(
                Player.DisplayName
                or Player.Name
            ),
            placeId = tonumber(game.PlaceId) or 0,
            jobId = tostring(game.JobId or ""),
            requestedTier = RequestedTier,
            buildTier = RequestedTier,
            deviceId = deviceId,
            hwid = deviceId,
            clientId = deviceId,
            client = "SliceHub",
            version = tostring(
                Config.Version or "9.8.4"
            ),
        }

        local encodedPayload =
            HttpService:JSONEncode(
                requestPayload
            )

        if type(Request) == "function" then
            local okPost, response = pcall(
                Request,
                {
                    Url = url,
                    Method = "POST",
                    Headers = {
                        ["Content-Type"] =
                            "application/json",
                        ["Accept"] =
                            "application/json",
                    },
                    Body = encodedPayload,
                }
            )

            if okPost then
                local status =
                    requestStatus(response)
                local body =
                    requestBody(response)

                if status == nil
                    or (
                        status >= 200
                        and status < 300
                    ) then
                    local decoded, decodeError =
                        decodeResponse(body)

                    if decoded then
                        return true, decoded
                    end

                    if status ~= nil then
                        return false, nil, decodeError
                    end
                elseif status ~= 404
                    and status ~= 405 then
                    local decoded =
                        select(
                            1,
                            decodeResponse(body)
                        )

                    local message =
                        decoded
                        and (
                            decoded.message
                            or decoded.error
                            or decoded.reason
                        )

                    return false, decoded,
                        tostring(
                            message
                            or ("HTTP " .. status)
                        )
                end
            end

            local joiner =
                string.find(url, "?", 1, true)
                and "&"
                or "?"

            local getUrl =
                url
                .. joiner
                .. "key="
                .. urlEncode(key)
                .. "&userId="
                .. urlEncode(Player.UserId)
                .. "&requestedTier="
                .. urlEncode(RequestedTier)
                .. "&deviceId="
                .. urlEncode(deviceId)

            local okGet, getResponse = pcall(
                Request,
                {
                    Url = getUrl,
                    Method = "GET",
                    Headers = {
                        ["Accept"] =
                            "application/json",
                    },
                }
            )

            if okGet then
                local status =
                    requestStatus(getResponse)
                local body =
                    requestBody(getResponse)

                if status == nil
                    or (
                        status >= 200
                        and status < 300
                    ) then
                    local decoded, decodeError =
                        decodeResponse(body)

                    if decoded then
                        return true, decoded
                    end

                    return false, nil, decodeError
                end

                local decoded =
                    select(
                        1,
                        decodeResponse(body)
                    )

                return false, decoded,
                    tostring(
                        decoded
                        and (
                            decoded.message
                            or decoded.error
                            or decoded.reason
                        )
                        or ("HTTP " .. tostring(status))
                    )
            end
        end

        local joiner =
            string.find(url, "?", 1, true)
            and "&"
            or "?"

        local getUrl =
            url
            .. joiner
            .. "key="
            .. urlEncode(key)
            .. "&userId="
            .. urlEncode(Player.UserId)
            .. "&requestedTier="
            .. urlEncode(RequestedTier)
            .. "&deviceId="
            .. urlEncode(deviceId)

        local okHttp, body = pcall(
            game.HttpGet,
            game,
            getUrl
        )

        if okHttp then
            local decoded, decodeError =
                decodeResponse(body)

            if decoded then
                return true, decoded
            end

            return false, nil, decodeError
        end

        return false, nil,
            "No supported HTTP request method"
    end

    local function responseIsValid(data)
        if type(data) ~= "table" then
            return false, "Invalid server response"
        end

        local valid =
            data.valid == true
            or data.success == true
            or data.authorized == true
            or data.allowed == true

        if not valid then
            return false,
                tostring(
                    data.message
                    or data.error
                    or data.reason
                    or "Key rejected"
                )
        end

        local expiresAt = tonumber(
            data.expiresAt
            or data.expires
            or data.expiry
        )

        if expiresAt
            and expiresAt > 0
            and expiresAt <= os.time() then
            return false, "Key expired"
        end

        if RequestedTier == "PREMIUM" then
            local responseTier =
                string.upper(
                    tostring(
                        data.tier
                        or data.plan
                        or data.licenseType
                        or ""
                    )
                )

            local premium =
                data.premium == true
                or responseTier == "PREMIUM"
                or responseTier == "PAID"
                or responseTier == "LIFETIME"

            if not premium then
                return false,
                    "This key does not unlock Premium"
            end
        end

        return true
    end

    local function validateKey(key)
        key = trim(key)

        if key == "" then
            return false, nil, "Enter your key"
        end

        local candidates =
            normalizeUrlCandidates(
                resolveApiUrl()
            )

        if #candidates == 0 then
            return false, nil,
                "Key server is not configured"
        end

        local lastError =
            "Unable to contact key server"

        for _, url in ipairs(candidates) do
            local transportOk, data, errorMessage =
                validateAtUrl(url, key)

            if transportOk and data then
                local accepted, reason =
                    responseIsValid(data)

                if accepted then
                    return true, data, nil
                end

                return false, data, reason
            end

            -- A decoded body from a non-2xx response is still an explicit
            -- license-server rejection, not a transport failure. Return it so
            -- the GUI can show purpose-built states such as HWID mismatch.
            if data ~= nil then
                return false, data,
                    tostring(
                        errorMessage
                        or "Key rejected"
                    )
            end

            lastError =
                tostring(
                    errorMessage
                    or lastError
                )
        end

        return false, nil, lastError
    end

    -- V9.8.2.8.1: resolve saved credentials before building the visible gate.
    -- A valid saved key keeps the gate hidden while automatic validation runs.
    local initialKey =
        trim(Environment.SCRIPT_KEY or "")
    local initialSavedLicense = nil

    if initialKey == "" then
        initialSavedLicense = savedLicense()

        if initialSavedLicense
            and type(initialSavedLicense.key) == "string" then
            local savedExpiry = tonumber(
                initialSavedLicense.expiresAt
            )

            if savedExpiry
                and savedExpiry > 0
                and savedExpiry <= os.time() then
                clearSavedLicense()
                initialSavedLicense = nil
            else
                initialKey = trim(
                    initialSavedLicense.key
                )
            end
        end
    end

    local silentInitialValidation =
        initialKey ~= ""

    local function safeGuiParent(gui)
        local parent = nil

        if type(gethui) == "function" then
            pcall(function()
                parent = gethui()
            end)
        end

        if not parent then
            parent = CoreGui
        end

        local ok = pcall(function()
            gui.Parent = parent
        end)

        if not ok or gui.Parent == nil then
            gui.Parent = PlayerGui
        end
    end

    local old =
        CoreGui:FindFirstChild(
            "SliceHubKeyGate"
        )
        or PlayerGui:FindFirstChild(
            "SliceHubKeyGate"
        )

    if old then
        old:Destroy()
    end

