V98330ConfigEcosystem = V98330ConfigEcosystem or {
    Format = "SliceHubConfig",
    Schema = 1,
    DraftPrefix = "SHCFG-DRAFT1:",
    ExportFolder = "SH/configs",
    ApiFallback = "https://slicebot-production.up.railway.app",
    PendingAutoloadName = nil,
    PendingAutoloadRecord = nil,
    PendingPreview = nil,
    PendingStart = false,
    Launching = false,
    Polling = false,
    LastInboxError = nil,
    LastInboxPollAt = 0,
}

function V98330ConfigEcosystem.DeepCopy(value)
    if type(value) ~= "table" then return value end
    local output = {}
    for key, child in pairs(value) do
        output[key] = V98330ConfigEcosystem.DeepCopy(child)
    end
    return output
end

function V98330ConfigEcosystem.EnsureFolders()
    local makeFolder = Env.makefolder
        or (type(makefolder) == "function" and makefolder or nil)
    local isFolder = Env.isfolder
        or (type(isfolder) == "function" and isfolder or nil)
    if type(makeFolder) ~= "function" then return false end

    for _, folder in ipairs({"SH", "SH/config", V98330ConfigEcosystem.ExportFolder}) do
        local exists = false
        if type(isFolder) == "function" then
            local ok, value = pcall(isFolder, folder)
            exists = ok and value == true
        end
        if not exists then pcall(makeFolder, folder) end
    end
    return true
end

function V98330ConfigEcosystem.NormalizeCategory(value)
    value = string.lower(tostring(value or ""))
    if value == "lobby" or value == "mission" or value == "raid" or value == "waves" then
        return value
    end
    return nil
end

function V98330ConfigEcosystem.CategoryLabel(value)
    value = V98330ConfigEcosystem.NormalizeCategory(value)
    if value == "mission" then return "Mission" end
    if value == "raid" then return "Raid" end
    if value == "waves" then return "Waves" end
    return "Lobby"
end

function V98330ConfigEcosystem.CategoryFromRun(run)
    run = type(run) == "table" and run or State
    local mode = tostring(run.CreateMode or "Mission")
    if mode == "Raid" then return "raid" end
    if mode == "Waves" then return "waves" end
    return "mission"
end

function V98330ConfigEcosystem.FormatDuration(value)
    local seconds = math.clamp(math.floor((tonumber(value) or 0) + 0.5), 0, 300)
    if seconds < 60 then
        return tostring(seconds) .. " second" .. (seconds == 1 and "" or "s")
    end
    local minutes = math.floor(seconds / 60)
    local remainder = seconds % 60
    local text = tostring(minutes) .. " minute" .. (minutes == 1 and "" or "s")
    if remainder > 0 then
        text = text .. " and " .. tostring(remainder) .. " second" .. (remainder == 1 and "" or "s")
    end
    return text
end

local function normalizeConfig(data)
    data = type(data) == "table" and data or {}

    local createMode = tostring(data.CreateMode or data.Mode or "Mission")
    if createMode ~= "Raid" and createMode ~= "Waves" then
        createMode = "Mission"
    end

    if createMode == "Waves" and not SliceHubLobbyWavesAllowed() then
        createMode = "Mission"
    end

    local raidChoice = tostring(data.RaidChoice or "Shiganshina (Arm)")
    if not V401LobbyRaid.Data[raidChoice] then
        for choice, info in pairs(V401LobbyRaid.Data) do
            if tostring(data.Map or "") == info.Map
                and tostring(data.Objective or "") == info.Objective then
                raidChoice = choice
                break
            end
        end
    end
    if not V401LobbyRaid.Data[raidChoice] then raidChoice = "Shiganshina (Arm)" end

    if createMode == "Raid"
        and type(SliceHubRaidChoiceAllowed) == "function"
        and not SliceHubRaidChoiceAllowed(raidChoice) then
        raidChoice = "Shiganshina (Col)"
    end

    local map
    local objective

    if createMode == "Raid" then
        local raid = V401LobbyRaid.Data[raidChoice]
        map = raid.Map
        objective = raid.Objective
    elseif createMode == "Waves" then
        map = "Trost"
        objective = "Waves"
    else
        map = tostring(data.Map or "Shiganshina")
        if not MissionData[map] then map = "Shiganshina" end

        objective = tostring(data.Objective or MissionData[map][1])
        local okObjective = false
        for _, obj in ipairs(MissionData[map]) do
            if obj == objective then okObjective = true break end
        end
        if not okObjective then objective = MissionData[map][1] end
    end

    local difficulty = tostring(data.Difficulty or "Easy")
    local okDifficulty = difficulty == V100HardestDifficulty.Name
    for _, d in ipairs(Difficulties) do
        if d.Name == difficulty then okDifficulty = true end
    end
    if not okDifficulty then difficulty = "Easy" end
    if createMode == "Waves" then difficulty = "Easy" end

    local minimum = nil
    if createMode == "Raid" then
        local raid = V401LobbyRaid.Data[raidChoice]
        minimum = raid and tonumber(raid.Minimum) or nil
        if difficulty ~= V100HardestDifficulty.Name
            and not V43RaidDifficultyAllowed(raidChoice, difficulty) then
            difficulty = raidChoice == "Shiganshina (Col)" and "Aberrant" or "Hard"
        end
    end

    local allowed = {}
    for _, modifier in ipairs(Modifiers) do allowed[modifier] = true end
    local mods = {}
    local seenModifiers = {}
    if createMode ~= "Waves" and type(data.Modifiers) == "table" then
        for _, modifier in ipairs(data.Modifiers) do
            modifier = tostring(modifier)
            if allowed[modifier] and not seenModifiers[modifier] then
                seenModifiers[modifier] = true
                mods[#mods + 1] = modifier
            end
        end
    end

    local autoStart = data.AutoStart == true
    local delay = math.clamp(math.floor((tonumber(data.Delay or data.LaunchDelay or data.AutoCreateDelay) or 5) + 0.5), 5, 300)

    return {
        CreateMode = createMode,
        RaidChoice = raidChoice,
        Map = map,
        Objective = objective,
        Difficulty = difficulty,
        Minimum = minimum,
        Modifiers = mods,
        AutoStart = autoStart,
        Delay = delay,
    }
end

local function captureConfig()
    local snapshot = V98330ConfigEcosystem.DeepCopy(State)
    if tostring(snapshot.CreateMode or "") == "Waves"
        and type(V98WavesUI) == "table" then
        snapshot.AutoStart = V98WavesUI.AutoStart == true
    end
    return normalizeConfig(snapshot)
end

function V98330ConfigEcosystem.Base64UrlEncode(data)
    data = tostring(data or "")
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local binary = data:gsub(".", function(character)
        local byte = character:byte()
        local bits = ""
        for index = 8, 1, -1 do
            bits = bits .. (byte % 2 ^ index - byte % 2 ^ (index - 1) > 0 and "1" or "0")
        end
        return bits
    end) .. "0000"
    local encoded = binary:gsub("%d%d%d?%d?%d?%d?", function(chunk)
        if #chunk < 6 then return "" end
        local value = 0
        for index = 1, 6 do
            if chunk:sub(index, index) == "1" then value = value + 2 ^ (6 - index) end
        end
        return alphabet:sub(value + 1, value + 1)
    end)
    encoded = encoded .. ({"", "==", "="})[#data % 3 + 1]
    encoded = encoded:gsub("%+", "-"):gsub("/", "_"):gsub("=+$", "")
    return encoded
end

function V98330ConfigEcosystem.Base64UrlDecode(data)
    data = tostring(data or ""):gsub("-", "+"):gsub("_", "/")
    local remainder = #data % 4
    if remainder > 0 then data = data .. string.rep("=", 4 - remainder) end
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    data = data:gsub("[^" .. alphabet .. "=]", "")
    local binary = data:gsub(".", function(character)
        if character == "=" then return "" end
        local position = alphabet:find(character, 1, true)
        if not position then return "" end
        local value = position - 1
        local bits = ""
        for index = 6, 1, -1 do
            bits = bits .. (value % 2 ^ index - value % 2 ^ (index - 1) > 0 and "1" or "0")
        end
        return bits
    end)
    return binary:gsub("%d%d%d?%d?%d?%d?%d?%d?", function(chunk)
        if #chunk ~= 8 then return "" end
        local value = 0
        for index = 1, 8 do
            if chunk:sub(index, index) == "1" then value = value + 2 ^ (8 - index) end
        end
        return string.char(value)
    end)
end

function V98330ConfigEcosystem.EncodeDraft(record)
    local ok, encoded = pcall(function()
        return HttpService:JSONEncode(record)
    end)
    if not ok then return nil, "Config JSON encode failed" end
    return V98330ConfigEcosystem.DraftPrefix
        .. V98330ConfigEcosystem.Base64UrlEncode(encoded)
end

function V98330ConfigEcosystem.DecodeDraft(value)
    local text = tostring(value or "")
    text = string.gsub(text, "^%s+", "")
    text = string.gsub(text, "%s+$", "")
    local fenced = string.match(text, "^```[%w]*%s*(.-)%s*```$")
    if fenced then text = fenced end

    local upper = string.upper(text)
    if string.sub(upper, 1, #V98330ConfigEcosystem.DraftPrefix)
        == V98330ConfigEcosystem.DraftPrefix then
        local raw = V98330ConfigEcosystem.Base64UrlDecode(
            string.sub(text, #V98330ConfigEcosystem.DraftPrefix + 1)
        )
        local ok, decoded = pcall(function() return HttpService:JSONDecode(raw) end)
        if ok and type(decoded) == "table" then return decoded end
        return nil, "Draft code could not be decoded"
    end

    local ok, decoded = pcall(function() return HttpService:JSONDecode(text) end)
    if ok and type(decoded) == "table" then return decoded end
    return nil, "Paste JSON, an SHCFG-DRAFT1 code, or a shared SHCFG1 token"
end

function V98330ConfigEcosystem.SafeFileName(value)
    local text = tostring(value or "config")
    text = string.gsub(text, "[^%w%-%_ ]", "")
    text = string.gsub(text, "%s+", "_")
    text = string.sub(text, 1, 48)
    return text ~= "" and text or "config"
end

function V98330ConfigEcosystem.ReadJsonFile(path)
    if type(readfileFn) ~= "function" then return nil end
    local ok, raw = pcall(readfileFn, path)
    if not ok or type(raw) ~= "string" or raw == "" then return nil end
    local decodedOk, decoded = pcall(function() return HttpService:JSONDecode(raw) end)
    return decodedOk and type(decoded) == "table" and decoded or nil
end

function V98330ConfigEcosystem.WriteJsonFile(path, document)
    if type(writefileFn) ~= "function" then return false, "file writing unavailable" end
    V98330ConfigEcosystem.EnsureFolders()
    local okEncode, encoded = pcall(function() return HttpService:JSONEncode(document) end)
    if not okEncode then return false, "JSON encode failed" end
    local okWrite, writeError = pcall(writefileFn, path, encoded)
    return okWrite, okWrite and "saved" or tostring(writeError)
end

V98330ConfigEcosystem.RuntimeWhitelist = {
    Toggles = {
        "FarmEnabled", "BladesEnabled", "TitanBlasterEnabled", "TitanRipperEnabled",
        "AutoRefillEnabled", "AutoSkipCutsceneEnabled", "PerformanceModeEnabled",
        "DisableEffectsEnabled", "EcoLoopModeEnabled", "MapPropsHiddenEnabled",
        "RemoveInjuryKillFlashEnabled", "RemoveDamageTextEnabled", "OptimizationPreset",
        "CleanupDeadTitansEnabled", "RemoveFogEnabled", "DisablePostProcessingEnabled",
        "Disable3DRenderingEnabled", "SimpleLightingEnabled", "LowDetailMapMaterialsEnabled",
        "SleepUIWhenHiddenEnabled", "DisableCameraEffectsEnabled", "FPSCap",
    },
