        "AutoUseEnabled", "OrderAdvanceEnabled", "BlackFlareEnabled", "OrderRageEnabled",
        "FoundersOrderEnabled", "OrderRevolutionEnabled",
    },
    Raids = {"AutoSkipEnabled", "OpenFreeChestEnabled", "OpenEmperorChestEnabled"},
    Waves = {"AutoFarmEnabled", "AutoSkipEnabled", "AutoPickupEnabled", "AutoDeliverEnabled", "AutoUpgradeGearEnabled", "GearTarget", "AutoUpgradeHQEnabled", "HQMaxEnabled", "HQRegenEnabled", "HQRefillsEnabled", "HQReplenishEnabled"},
    Automation = {"AutoRetryEnabled", "MissionLimit"},
    Safety = {"WaitBeforeLastTitan", "WaitBeforeRaidBossFinish"},
