}

function V98330ConfigEcosystem.CaptureMissionRuntime()
    local document = V98330ConfigEcosystem.ReadJsonFile("TitanControlSettings_v101.json")
    if type(document) ~= "table" and type(Env.TitanControlPersistentSettings) == "table" then
        document = Env.TitanControlPersistentSettings
    end
    document = type(document) == "table" and document or {}
    local output = {}
    for sectionName, keys in pairs(V98330ConfigEcosystem.RuntimeWhitelist) do
        local source = type(document[sectionName]) == "table" and document[sectionName] or {}
        local section = {}
        for _, key in ipairs(keys) do
            local value = source[key]
            if type(value) == "boolean" or type(value) == "number" or type(value) == "string" then
                section[key] = value
            end
        end
        if next(section) ~= nil then output[sectionName] = section end
    end
    return output
end

function V98330ConfigEcosystem.CaptureLobbyAutomation()
    local automation = V98320LobbyAutomation
    if type(automation) ~= "table" or type(automation.Settings) ~= "table" then return {} end
    local settings = V98330ConfigEcosystem.DeepCopy(automation.Settings)
    settings.LastAchievementSweepUnix = 0
    return settings
end

function V98330ConfigEcosystem.CaptureAutoUpgrade()
    local upgrade = V96LobbyAutoUpgrade
    if type(upgrade) ~= "table" then return {} end
    return {
        Enabled = upgrade.Enabled == true,
        Delay = math.clamp(tonumber(upgrade.Delay) or 0.55, 0.15, 2.0),
        Selected = V98330ConfigEcosystem.DeepCopy(upgrade.Selected or {}),
    }
end

function V98330ConfigEcosystem.CaptureAutoPrestige()
    local prestige = V962LobbyAutoPrestige
    if type(prestige) ~= "table" then return {} end
    local thresholds = {}
    for index = 0, 5 do thresholds[tostring(index)] = prestige.Thresholds and prestige.Thresholds[index] or nil end
    return {
        Enabled = prestige.Enabled == true,
        Buff = tostring(prestige.Buff or "Luck"),
        Thresholds = thresholds,
    }
end

function V98330ConfigEcosystem.CaptureSkillTree()
    local tree = V97LobbySkillTree
    if type(tree) ~= "table" then return {} end
    return {
        Enabled = tree.Enabled == true,
        Middle = tostring(tree.Middle or "Critical"),
        Left = tostring(tree.Left or "Cooldown Reduction"),
        Right = tostring(tree.Right or "Damage Reduction"),
        Priority = V98330ConfigEcosystem.DeepCopy(tree.Priority or {"Middle", "Left", "None"}),
    }
end

function V98330ConfigEcosystem.CaptureRecord(category, name)
    category = V98330ConfigEcosystem.NormalizeCategory(category)
        or V98330ConfigEcosystem.CategoryFromRun(State)
    local run = nil
    if category ~= "lobby" then
        run = captureConfig()
        local expectedMode = category == "raid" and "Raid"
            or category == "waves" and "Waves"
            or "Mission"
        if run.CreateMode ~= expectedMode then
            return nil, "Switch the Create tab to " .. expectedMode .. " before saving this config type"
        end
    end

    local tier = SliceHubLobbyIsPremium() and "PREMIUM" or "FREE"
    return {
        format = V98330ConfigEcosystem.Format,
        schema = V98330ConfigEcosystem.Schema,
        category = category,
        name = cleanName(name or "") ~= "" and cleanName(name) or (category == "lobby" and "Lobby Setup" or "SliceHub Config"),
        description = "",
        originTier = tier,
        sliceHubVersion = "9.8.4",
        createdAt = os.time(),
        settings = {
            Run = run,
            Launch = run and {
                AutoCreate = run.AutoStart == true,
                LaunchDelay = run.Delay,
            } or nil,
            LobbyAutomation = V98330ConfigEcosystem.CaptureLobbyAutomation(),
            AutoUpgrade = V98330ConfigEcosystem.CaptureAutoUpgrade(),
            AutoPrestige = V98330ConfigEcosystem.CaptureAutoPrestige(),
            SkillTree = V98330ConfigEcosystem.CaptureSkillTree(),
            MissionRuntime = V98330ConfigEcosystem.CaptureMissionRuntime(),
        },
    }
end

function V98330ConfigEcosystem.NormalizeRecord(raw, fallbackName)
    raw = type(raw) == "table" and raw or {}
    local settings = type(raw.settings) == "table" and raw.settings
        or type(raw.Settings) == "table" and raw.Settings
        or nil

    if not settings then
        local legacyRun = normalizeConfig(raw)
        settings = {
            Run = legacyRun,
            Launch = {
                AutoCreate = legacyRun.AutoStart == true,
                LaunchDelay = legacyRun.Delay,
            },
        }
        raw = {
            category = V98330ConfigEcosystem.CategoryFromRun(legacyRun),
            name = fallbackName,
            originTier = "FREE",
            sliceHubVersion = "Legacy",
        }
    end

    local category = V98330ConfigEcosystem.NormalizeCategory(raw.category or raw.type)
    local run = type(settings.Run) == "table" and normalizeConfig(settings.Run) or nil
    if not category then category = run and V98330ConfigEcosystem.CategoryFromRun(run) or "lobby" end
    if category == "lobby" then run = nil end

    local launch = type(settings.Launch) == "table" and settings.Launch or {}
    if run then
        if launch.AutoCreate ~= nil then run.AutoStart = launch.AutoCreate == true end
        if launch.LaunchDelay ~= nil then
            run.Delay = math.clamp(math.floor((tonumber(launch.LaunchDelay) or run.Delay or 5) + 0.5), 5, 300)
        end
    end

    return {
        format = V98330ConfigEcosystem.Format,
        schema = tonumber(raw.schema or raw.Schema) or V98330ConfigEcosystem.Schema,
        category = category,
        name = cleanName(raw.name or raw.Name or fallbackName or "Imported Config"),
        description = tostring(raw.description or raw.Description or ""),
        originTier = string.upper(tostring(raw.originTier or raw.OriginTier or raw.createdWith or "FREE")) == "PREMIUM" and "PREMIUM" or "FREE",
        sliceHubVersion = tostring(raw.sliceHubVersion or raw.version or "Unknown"),
        createdAt = tonumber(raw.createdAt) or os.time(),
        settings = {
            Run = run,
            Launch = run and {AutoCreate = run.AutoStart == true, LaunchDelay = run.Delay} or nil,
            LobbyAutomation = type(settings.LobbyAutomation) == "table" and V98330ConfigEcosystem.DeepCopy(settings.LobbyAutomation) or {},
            AutoUpgrade = type(settings.AutoUpgrade) == "table" and V98330ConfigEcosystem.DeepCopy(settings.AutoUpgrade) or {},
            AutoPrestige = type(settings.AutoPrestige) == "table" and V98330ConfigEcosystem.DeepCopy(settings.AutoPrestige) or {},
            SkillTree = type(settings.SkillTree) == "table" and V98330ConfigEcosystem.DeepCopy(settings.SkillTree) or {},
            MissionRuntime = type(settings.MissionRuntime) == "table" and V98330ConfigEcosystem.DeepCopy(settings.MissionRuntime) or {},
        },
    }
end

function V98330ConfigEcosystem.RecordSummary(record)
    record = V98330ConfigEcosystem.NormalizeRecord(record, record and record.name)
    local lines = {
        "Type: " .. V98330ConfigEcosystem.CategoryLabel(record.category),
        "Origin: " .. tostring(record.originTier),
    }
    local run = record.settings.Run
    if run then
        if run.CreateMode == "Raid" then
            lines[#lines + 1] = "Raid: " .. tostring(run.RaidChoice)
        elseif run.CreateMode == "Waves" then
            lines[#lines + 1] = "Run: Trost Waves"
        else
            lines[#lines + 1] = "Map: " .. tostring(run.Map)
            lines[#lines + 1] = "Objective: " .. tostring(run.Objective)
        end
        lines[#lines + 1] = "Difficulty: " .. tostring(run.Difficulty)
        lines[#lines + 1] = "Modifiers: " .. modsText(run.Modifiers)
        lines[#lines + 1] = "Auto Launch: " .. (run.AutoStart and "ON • " .. V98330ConfigEcosystem.FormatDuration(run.Delay) or "OFF")
    else
        lines[#lines + 1] = "Run setup: not included"
    end
    local automation = record.settings.LobbyAutomation
    local upgrade = record.settings.AutoUpgrade
    local prestige = record.settings.AutoPrestige
    lines[#lines + 1] = "Lobby Automation: " .. (type(automation) == "table" and automation.Enabled == true and "ON" or "OFF")
    lines[#lines + 1] = "Auto Upgrade: " .. (type(upgrade) == "table" and upgrade.Enabled == true and "ON" or "OFF")
    lines[#lines + 1] = "Auto Prestige: " .. (type(prestige) == "table" and prestige.Enabled == true and "ON" or "OFF")
    return table.concat(lines, "\n")
end

function V98330ConfigEcosystem.UrlEncode(value)
    local ok, encoded = pcall(HttpService.UrlEncode, HttpService, tostring(value or ""))
    return ok and encoded or tostring(value or "")
end

function V98330ConfigEcosystem.RequestFunction()
    return Env.request
        or Env.http_request
        or Env.httprequest
        or (type(syn) == "table" and syn.request or nil)
        or (type(http) == "table" and http.request or nil)
        or (type(fluxus) == "table" and fluxus.request or nil)
end

function V98330ConfigEcosystem.ApiBase()
    local raw = tostring(Env.SLICEHUB_KEY_API_URL or Env.SliceHubKeyApiUrl or "")
    if raw == "" and type(readfileFn) == "function" then
        local ok, saved = pcall(readfileFn, "SH/license_api.txt")
        if ok and type(saved) == "string" then raw = saved end
    end
    if raw == "" then raw = V98330ConfigEcosystem.ApiFallback end
    if not string.match(string.lower(raw), "^https?://") then raw = "https://" .. raw end
    raw = string.gsub(raw, "/+$", "")
    raw = string.gsub(raw, "/api/validate[%w%-%_]*$", "")
    raw = string.gsub(raw, "/validate[%w%-%_]*$", "")
    return raw
end

function V98330ConfigEcosystem.ScriptKey()
    local key = tostring(Env.SCRIPT_KEY or "")
    if key ~= "" then return key end
    local license = V98330ConfigEcosystem.ReadJsonFile("SH/license.json")
    return type(license) == "table" and tostring(license.key or "") or ""
end

function V98330ConfigEcosystem.DeviceId()
    local value = ""
    local getHwid = Env.gethwid or (type(gethwid) == "function" and gethwid or nil)
    if type(getHwid) == "function" then pcall(function() value = tostring(getHwid()) end) end
    if value == "" then
        pcall(function() value = tostring(game:GetService("RbxAnalyticsService"):GetClientId()) end)
    end
    if value == "" then value = "roblox-user:" .. tostring(player.UserId) end
    return value
end

function V98330ConfigEcosystem.AuthFields()
    local tier = SliceHubLobbyIsPremium() and "PREMIUM" or "FREE"
    local device = V98330ConfigEcosystem.DeviceId()
    return {
        key = V98330ConfigEcosystem.ScriptKey(),
        scriptKey = V98330ConfigEcosystem.ScriptKey(),
        userId = tostring(player.UserId),
        username = tostring(player.Name),
        requestedTier = tier,
        buildTier = tier,
        deviceId = device,
        hwid = device,
        clientId = device,
    }
end

function V98330ConfigEcosystem.Api(path, method, body)
    method = string.upper(tostring(method or "GET"))
    body = type(body) == "table" and V98330ConfigEcosystem.DeepCopy(body) or {}
    for key, value in pairs(V98330ConfigEcosystem.AuthFields()) do
        if body[key] == nil then body[key] = value end
    end
    if tostring(body.key or "") == "" then return nil, "No validated SliceHub key is available" end

    local url = V98330ConfigEcosystem.ApiBase() .. tostring(path or "")
    local request = V98330ConfigEcosystem.RequestFunction()
    local responseBody = nil
    local status = nil

    if method == "GET" then
        local query = {}
        for key, value in pairs(body) do
            if type(value) ~= "table" then
                query[#query + 1] = V98330ConfigEcosystem.UrlEncode(key) .. "=" .. V98330ConfigEcosystem.UrlEncode(value)
            end
        end
        table.sort(query)
        url = url .. (string.find(url, "?", 1, true) and "&" or "?") .. table.concat(query, "&")
    end

    if type(request) == "function" then
        local payload = {Url = url, Method = method, Headers = {Accept = "application/json"}}
        if method ~= "GET" then
            payload.Headers["Content-Type"] = "application/json"
            payload.Body = HttpService:JSONEncode(body)
        end
        local ok, response = pcall(request, payload)
        if not ok then return nil, tostring(response) end
        if type(response) == "table" then
            status = tonumber(response.StatusCode or response.Status or response.status_code)
            responseBody = response.Body or response.body or response.Response or response.response
        else
            responseBody = response
        end
    elseif method == "GET" then
        local ok, response = pcall(game.HttpGet, game, url)
        if not ok then return nil, tostring(response) end
        responseBody = response
    else
        return nil, "Executor HTTP request support is required"
    end

    local okDecode, decoded = pcall(function()
        return HttpService:JSONDecode(tostring(responseBody or ""))
    end)
    if not okDecode or type(decoded) ~= "table" then
        return nil, "Invalid config-server response"
    end
    if decoded.ok ~= true then
        return nil, tostring(decoded.message or decoded.error or (status and "HTTP " .. status) or "Request failed")
    end
    return decoded
end

function V98330ConfigEcosystem.ParseImport(value)
    local text = tostring(value or "")
    text = string.gsub(text, "^%s+", "")
    text = string.gsub(text, "%s+$", "")
    if string.match(string.upper(text), "^SHCFG1:") then
        local response, errorMessage = V98330ConfigEcosystem.Api(
            "/api/configs/resolve",
            "GET",
            {token = text}
        )
        if not response then return nil, errorMessage end
        local shared = response.config
        local payload = type(shared) == "table" and shared.payload or nil
        if type(payload) ~= "table" then return nil, "Shared config payload missing" end
        return V98330ConfigEcosystem.NormalizeRecord(payload, shared.name), {
            Source = "Clipboard",
            ConfigId = shared.id,
            Token = text,
            Creator = shared.creatorName,
            Activations = shared.activations,
        }
    end
    local decoded, errorMessage = V98330ConfigEcosystem.DecodeDraft(text)
    if not decoded then return nil, errorMessage end
    return V98330ConfigEcosystem.NormalizeRecord(decoded, decoded.name), {Source = "Local import"}
end

function V98330ConfigEcosystem.PollInbox()
    local response, errorMessage = V98330ConfigEcosystem.Api("/api/configs/inbox", "GET")
    if not response then return nil, errorMessage end
    if type(response.delivery) ~= "table" then return false end
    local delivery = response.delivery
    local shared = type(delivery.config) == "table" and delivery.config or nil
    local payload = shared and shared.payload or nil
    if type(payload) ~= "table" then return nil, "Easy Add payload missing" end
    return V98330ConfigEcosystem.NormalizeRecord(payload, shared.name), {
        Source = "Discord Easy Add",
        ConfigId = shared.id,
        DeliveryId = delivery.id,
        Creator = shared.creatorName,
        Activations = shared.activations,
    }
end

function V98330ConfigEcosystem.Activate(meta)
    meta = type(meta) == "table" and meta or {}
    if not meta.ConfigId and not meta.Token then return true end
    local response, errorMessage = V98330ConfigEcosystem.Api(
        "/api/configs/activate",
        "POST",
        {configId = meta.ConfigId, deliveryId = meta.DeliveryId, token = meta.Token}
    )
    return response ~= nil, response or errorMessage
end

function V98330ConfigEcosystem.Dismiss(meta)
    meta = type(meta) == "table" and meta or {}
    if not meta.DeliveryId then return true end
    local response, errorMessage = V98330ConfigEcosystem.Api(
        "/api/configs/dismiss",
        "POST",
        {deliveryId = meta.DeliveryId}
    )
    return response ~= nil, response or errorMessage
end

function V98330ConfigEcosystem.Publish(record)
    record = V98330ConfigEcosystem.NormalizeRecord(record, record and record.name)
    return V98330ConfigEcosystem.Api(
        "/api/configs/publish",
        "POST",
        {
            category = record.category,
            name = record.name,
            description = record.description or "",
            payload = record,
        }
    )
end


---------------------------------------------------------------------
-- V3 EXACT MISSION ENGINE
-- V3.0.1 register-pressure hotfix:
-- all Exact Engine helpers live on one namespace table rather than
-- consuming many top-level local registers in this already huge chunk.
---------------------------------------------------------------------

V3ExactMissionEngine = {
    Busy = false,
    TeleportSeen = false,
    LastStage = "Idle",
    LastError = nil,

    InternalMapNames = {
        ["Shiganshina"] = "Shiganshina",
        ["Trost"] = "Trost",
        ["Outskirts"] = "Outskirts",
        ["Giant Forest"] = "Forest",
        ["Utgard Castle"] = "Utgard",
        ["Loading Docks"] = "Docks",
        ["Stohess"] = "Stohess",
        ["Chapel"] = "Chapel",
    },
}

function V3ExactMissionEngine.Remote()
    local replicatedStorage = game:GetService("ReplicatedStorage")
    local assets = replicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("GET")

    if remote and remote:IsA("RemoteFunction") then
        return remote
    end

    return nil
end

function V3ExactMissionEngine.BuildPayload(config)
    config = type(config) == "table" and config or {}

    if tostring(config.CreateMode or "Mission") == "Waves" then
        return {
            Name = "Trost",
            Difficulty = "Easy",
            Type = "Waves",
            Objective = "Waves",
        }
    end

    if tostring(config.CreateMode or "Mission") == "Raid" then
        local raid = V401LobbyRaid.Data[tostring(config.RaidChoice or "")]
        local mapName = raid and raid.Map or tostring(config.Map or "Shiganshina")
        local objective = raid and raid.Objective or tostring(config.Objective or "Armored Titan")
        local minimum = raid and tonumber(raid.Minimum) or tonumber(config.Minimum)
        local difficulty = tostring(config.Difficulty or "Hard")

        if not V43RaidDifficultyAllowed(config.RaidChoice, difficulty) then
            difficulty = tostring(config.RaidChoice or "") == "Shiganshina (Col)"
                and "Aberrant"
                or "Hard"
        end

        return {
            Name = tostring(mapName),
            Difficulty = difficulty,
            Type = "Raids",
            Objective = tostring(objective),
            Minimum = minimum,
        }
    end

    return {
        Name = V3ExactMissionEngine.InternalMapNames[tostring(config.Map or "")]
            or tostring(config.Map or "Shiganshina"),
        Difficulty = tostring(config.Difficulty or "Easy"),
        Type = "Missions",
        Objective = tostring(config.Objective or "Skirmish"),
    }
end

function V3ExactMissionEngine.Invoke(action, ...)
    local remote = V3ExactMissionEngine.Remote()
    if not remote then
        return false, nil, "GET RemoteFunction missing"
    end

    local args = table.pack(...)
    local ok, result = pcall(function()
        return remote:InvokeServer(
            "S_Missions",
            action,
            table.unpack(args, 1, args.n)
        )
    end)

    if not ok then
        return false, nil, tostring(result)
    end

    return true, result, nil
end

player.OnTeleport:Connect(function()
    V3ExactMissionEngine.TeleportSeen = true
end)

function V3ExactMissionEngine.TeleportStarted()
    if V3ExactMissionEngine.TeleportSeen then
        return true
    end

    local value = player:GetAttribute("Teleporting")
    return value ~= nil and value ~= false
end

function V3ExactMissionEngine.Cleanup()
    pcall(function()
        V3ExactMissionEngine.Invoke("Leave")
    end)
end

function V3ExactMissionEngine.FindOwnedMission()
    local replicatedStorage =
        game:GetService("ReplicatedStorage")
    local missions =
        replicatedStorage:FindFirstChild("Missions")

    if not missions then
        return nil
    end

    for _, mission in ipairs(missions:GetChildren()) do
        local leader = mission:FindFirstChild("Leader")

        if leader
            and tostring(leader.Value)
                == tostring(player.Name) then

            return mission
        end
    end

    return nil
end

function V3ExactMissionEngine.WaitForOwnedMission(timeout)
    local startedAt = os.clock()
    local duration = math.max(0, tonumber(timeout) or 0)

    repeat
        local mission =
            V3ExactMissionEngine.FindOwnedMission()

        if mission then
            return mission
        end

        task.wait(0.05)
    until os.clock() - startedAt >= duration

    return V3ExactMissionEngine.FindOwnedMission()
end

function V3ExactMissionEngine.WaitForNoOwnedMission(timeout)
    local startedAt = os.clock()
    local duration = math.max(0, tonumber(timeout) or 0)

    repeat
        if not V3ExactMissionEngine.FindOwnedMission() then
            return true
        end

        task.wait(0.05)
    until os.clock() - startedAt >= duration

    return V3ExactMissionEngine.FindOwnedMission() == nil
end

function V3ExactMissionEngine.TryLaunch(config)
    config = type(config) == "table" and config or {}

    local resolvedConfig, _, resolveError =
        V100HardestDifficulty.ResolveConfig(config)
    if not resolvedConfig then
        return false,
            tostring(
                resolveError
                or "Hardest difficulty could not initialize"
            )
    end
    config = resolvedConfig

    if tostring(config.CreateMode or "") == "Waves"
        and not SliceHubLobbyWavesAllowed() then
        return false,
            "This tab unlocks only when you have Premium."
    end

    if tostring(config.CreateMode or "") == "Raid"
        and type(SliceHubRaidChoiceAllowed) == "function"
        and not SliceHubRaidChoiceAllowed(config.RaidChoice) then

        local reason =
            type(SliceHubRaidLockedReason) == "function"
            and SliceHubRaidLockedReason(config.RaidChoice)
            or "This raid is unsupported in the Free version."

        warn("[SliceHub Free] " .. tostring(reason))
        return false, tostring(reason)
    end

    if V3ExactMissionEngine.Busy then
        return false, "exact engine busy"
    end

    V3ExactMissionEngine.Busy = true
    V3ExactMissionEngine.TeleportSeen = false
    V3ExactMissionEngine.LastError = nil
    V3ExactMissionEngine.LastStage = "Create"

    local function fail(reason, created)
        V3ExactMissionEngine.LastError = tostring(reason)
        V3ExactMissionEngine.LastStage = "Failed"

        if created then
            V3ExactMissionEngine.Cleanup()
        end

        V3ExactMissionEngine.Busy = false
        return false, tostring(reason), nil
    end

    local wavesMode =
        tostring(config.CreateMode or "") == "Waves"

    local hardestRequested =
        tostring(config.Difficulty or "")
        == V100HardestDifficulty.Name

    local payload = nil
    local createdMission = nil

    if hardestRequested then
        V3ExactMissionEngine.LastStage =
            "HardestCleanup"

        -- Match the working server-authoritative flow: leave any stale owned
        -- mission once, then require the mission folder to disappear before
        -- probing. No native lobby UI is touched.
        V3ExactMissionEngine.Cleanup()

        if not V3ExactMissionEngine.WaitForNoOwnedMission(1.25) then
            return fail(
                "Could not clear the existing owned mission before Hardest probing.",
                false
            )
        end

        local order =
            V100HardestDifficulty.ServerOrder(
                config.CreateMode,
                config.RaidChoice
            )

        if #order == 0 then
            return fail(
                "No server-authoritative Hardest order is valid for this run.",
                false
            )
        end

        local attemptErrors = {}

        for _, difficulty in ipairs(order) do
            V3ExactMissionEngine.LastStage =
                "HardestCreate:" .. tostring(difficulty)

            local attemptConfig = copy(config)
            attemptConfig.Difficulty = difficulty
            attemptConfig.AdaptiveDifficulty = true
            attemptConfig.AdaptiveRequested =
                V100HardestDifficulty.Name
            attemptConfig.AdaptiveSource =
                "server-owned mission confirmation"

            local attemptPayload =
                V3ExactMissionEngine.BuildPayload(
                    attemptConfig
                )

            print(
                "[SliceHub Hardest][SERVER] TRY",
                tostring(difficulty),
                HttpService:JSONEncode(attemptPayload)
            )

            local createOk, createResponse, createErr =
                V3ExactMissionEngine.Invoke(
                    "Create",
                    attemptPayload
                )

            if not createOk then
                attemptErrors[#attemptErrors + 1] =
                    tostring(difficulty)
                    .. ": invoke failed: "
                    .. tostring(createErr)
            else
                local ownedMission =
                    V3ExactMissionEngine.WaitForOwnedMission(
                        1.50
                    )

                if ownedMission then
                    config = attemptConfig
                    payload = attemptPayload
                    createdMission = ownedMission

                    local requirement =
                        V100HardestDifficulty.Requirement(
                            config.CreateMode,
                            difficulty
                        )

                    V100HardestDifficulty.Last = {
                        ok = true,
                        pending = false,
                        mode =
                            tostring(
                                config.CreateMode
                                or "Mission"
                            ),
                        raidChoice = config.RaidChoice,
                        difficulty = difficulty,
                        requirement = requirement,
                        source =
                            "server-owned mission confirmation",
                        mission =
                            tostring(ownedMission.Name),
                    }

                    print(
                        "[SliceHub Hardest][SERVER] ACCEPTED",
                        tostring(difficulty),
                        "mission="
                            .. tostring(ownedMission.Name),
                        "response="
                            .. tostring(createResponse)
                    )

                    -- Do not call the lobby-local notify helper here.
                    -- This exact engine is declared before that local function,
                    -- so an early reference resolves as a nil global at runtime.
                    -- The outer launch flow sends the success notification after
                    -- TryLaunch returns.
                    print(
                        "[SliceHub Hardest][SERVER] RESOLVED",
                        tostring(difficulty),
                        requirement
                            and ("[" .. tostring(requirement) .. "]")
                            or ""
                    )

                    break
                end

                attemptErrors[#attemptErrors + 1] =
                    tostring(difficulty)
                    .. ": no owned mission appeared; response="
                    .. tostring(createResponse)

                print(
                    "[SliceHub Hardest][SERVER] REJECTED",
                    tostring(difficulty),
                    "response="
                        .. tostring(createResponse)
                )
            end

            task.wait(0.12)
        end

        if not createdMission then
            V100HardestDifficulty.Last = {
                ok = false,
                pending = false,
                mode =
                    tostring(
                        config.CreateMode
                        or "Mission"
                    ),
                raidChoice = config.RaidChoice,
                error =
                    "server rejected every difficulty",
                source =
                    "server-owned mission confirmation",
                attempts = attemptErrors,
            }

            return fail(
                "Hardest server probe failed: "
                    .. table.concat(
                        attemptErrors,
                        " | "
                    ),
                false
            )
        end
    else
        payload =
            V3ExactMissionEngine.BuildPayload(config)

        print(
            "[Slice V4.2][EXACT] CREATE",
            HttpService:JSONEncode(payload)
        )

        local createOk, createResponse, createErr =
            V3ExactMissionEngine.Invoke(
                "Create",
                payload
            )

        if not createOk then
            return fail(
                "Create invoke failed: "
                    .. tostring(createErr),
                false
            )
        end

        createdMission = createResponse

        -- Waves Create is server-accepted even when the RemoteFunction
        -- returns nil or the map name. Missions/Raids keep strict result
        -- validation when Hardest is not using folder confirmation.
        if not wavesMode then
            if createdMission == nil then
                return fail(
                    "Create returned nil",
                    false
                )
            end

            if type(createdMission) == "string" then
                return fail(
                    "Create rejected: "
                        .. tostring(createdMission),
                    false
                )
            end
        end
    end

    task.wait(0.045)

    V3ExactMissionEngine.LastStage = "Modifiers"

    for _, modifierName in ipairs(
        config.Modifiers or {}
    ) do
        local modifyOk, enabled, modifyErr =
            V3ExactMissionEngine.Invoke(
                "Modify",
                tostring(modifierName)
            )

        if not modifyOk then
            return fail(
                "Modify failed for "
                    .. tostring(modifierName)
                    .. ": "
                    .. tostring(modifyErr),
                true
            )
        end

        if enabled == nil then
            return fail(
                "Modify returned nil for "
                    .. tostring(modifierName),
                true
            )
        end

        print(
            "[Slice V4.2][EXACT] MODIFY",
            tostring(modifierName),
            "=>",
            tostring(enabled)
        )

        task.wait(0.018)
    end

    V3ExactMissionEngine.LastStage = "Start"

    local startOk, _, startErr =
        V3ExactMissionEngine.Invoke("Start")

    if not startOk then
        return fail(
            "Start invoke failed: "
                .. tostring(startErr),
            true
        )
    end

    local startedAt = os.clock()

    while os.clock() - startedAt < 3.0 do
        if V3ExactMissionEngine.TeleportStarted() then
            V3ExactMissionEngine.LastStage =
                "Teleporting"
            V3ExactMissionEngine.Busy = false

            return true,
                hardestRequested
                    and "server-confirmed Hardest launch"
                    or "exact direct launch",
                config
        end

        task.wait(0.035)
    end

    return fail(
        "Start sent but teleport was not detected",
        true
    )
end

local function applyConfig(config)
    local normalized = normalizeConfig(config)
    State.CreateMode = normalized.CreateMode
    State.RaidChoice = normalized.RaidChoice
    State.Map = normalized.Map
    State.Objective = normalized.Objective
    State.Difficulty = normalized.Difficulty
    State.Modifiers = normalized.Modifiers
    State.AutoStart = normalized.AutoStart
    State.Delay = normalized.Delay
    if normalized.CreateMode == "Waves" and type(V98WavesUI) == "table" then
        V98WavesUI.AutoStart = normalized.AutoStart == true
    end
end

function V98330ConfigEcosystem.AddAdjustment(adjustments, message)
    adjustments[#adjustments + 1] = tostring(message)
end

function V98330ConfigEcosystem.ApplyMissionRuntime(runtime, adjustments)
    runtime = type(runtime) == "table" and runtime or {}
    adjustments = type(adjustments) == "table" and adjustments or {}
    local document = V98330ConfigEcosystem.ReadJsonFile("TitanControlSettings_v101.json")
    if type(document) ~= "table" and type(Env.TitanControlPersistentSettings) == "table" then
        document = V98330ConfigEcosystem.DeepCopy(Env.TitanControlPersistentSettings)
    end
    document = type(document) == "table" and document or {}

    for sectionName, keys in pairs(V98330ConfigEcosystem.RuntimeWhitelist) do
        local incoming = type(runtime[sectionName]) == "table" and runtime[sectionName] or nil
        if incoming then
            document[sectionName] = type(document[sectionName]) == "table" and document[sectionName] or {}
            local allowed = {}
            for _, key in ipairs(keys) do allowed[key] = true end
            for key, value in pairs(incoming) do
                if allowed[key]
                    and (type(value) == "boolean" or type(value) == "number" or type(value) == "string") then
                    document[sectionName][key] = value
                end
            end
        end
    end

    local premium = SliceHubLobbyIsPremium()
    document.Config = type(document.Config) == "table" and document.Config or {}
    local requestedTitans = tonumber(document.Config.TitansPerHit)
    if requestedTitans ~= nil then
        local maximum = premium and 20 or 6
        local clamped = math.clamp(math.floor(requestedTitans + 0.5), 2, maximum)
        if clamped ~= requestedTitans then
            V98330ConfigEcosystem.AddAdjustment(
                adjustments,
                "Titans per hit: " .. tostring(requestedTitans) .. " → " .. tostring(clamped)
            )
        end
        document.Config.TitansPerHit = clamped
    end

    if not premium then
        document.Toggles = type(document.Toggles) == "table" and document.Toggles or {}
        document.Raids = type(document.Raids) == "table" and document.Raids or {}
        document.Waves = type(document.Waves) == "table" and document.Waves or {}
        if document.Toggles.AutoSkipCutsceneEnabled == true then
            document.Toggles.AutoSkipCutsceneEnabled = false
            V98330ConfigEcosystem.AddAdjustment(adjustments, "Premium Auto Skip Cutscene disabled")
        end
        if document.Raids.AutoSkipEnabled == true then
            document.Raids.AutoSkipEnabled = false
            V98330ConfigEcosystem.AddAdjustment(adjustments, "Premium Raid Auto Skip disabled")
        end
        for _, key in ipairs({"AutoFarmEnabled", "AutoSkipEnabled", "AutoPickupEnabled", "AutoDeliverEnabled", "AutoUpgradeGearEnabled", "AutoUpgradeHQEnabled"}) do
            if document.Waves[key] == true then
                document.Waves[key] = false
                V98330ConfigEcosystem.AddAdjustment(adjustments, "Premium Waves automation disabled")
                break
            end
        end
        document.Waves.AutoFarmEnabled = false
        document.Waves.AutoSkipEnabled = false
        document.Waves.AutoPickupEnabled = false
        document.Waves.AutoDeliverEnabled = false
        document.Waves.AutoUpgradeGearEnabled = false
        document.Waves.AutoUpgradeHQEnabled = false
        document.Waves.HQMaxEnabled = true
        document.Waves.HQRegenEnabled = true
        document.Waves.HQRefillsEnabled = true
        document.Waves.HQReplenishEnabled = true
        document.Waves.GearTarget = "Both"
    end

    Env.TitanControlPersistentSettings = document
    local ok, message = V98330ConfigEcosystem.WriteJsonFile("TitanControlSettings_v101.json", document)
    if not ok and type(writefileFn) == "function" then return false, message end

    if V98320SharedOptimization and type(V98320SharedOptimization.Load) == "function" then
        pcall(V98320SharedOptimization.Load)
        if type(V98320SharedOptimization.Apply) == "function" then pcall(V98320SharedOptimization.Apply) end
        if type(V98320SharedOptimization.Refresh) == "function" then pcall(V98320SharedOptimization.Refresh) end
    end
    return true
end

function V98330ConfigEcosystem.ApplyRecord(rawRecord, options)
    options = type(options) == "table" and options or {}
    local record = V98330ConfigEcosystem.NormalizeRecord(rawRecord, rawRecord and rawRecord.name)
    local settings = record.settings
    local adjustments = {}

    if type(settings.Run) == "table" then
        local requestedMode = tostring(settings.Run.CreateMode or "Mission")
        applyConfig(settings.Run)
        if State.CreateMode ~= requestedMode then
            V98330ConfigEcosystem.AddAdjustment(
                adjustments,
                requestedMode .. " is unavailable on this build; loaded " .. tostring(State.CreateMode) .. " instead"
            )
        end
        if requestedMode == "Raid"
            and tostring(settings.Run.RaidChoice or "") ~= tostring(State.RaidChoice or "") then
            V98330ConfigEcosystem.AddAdjustment(
                adjustments,
                "Unsupported Premium raid replaced with " .. tostring(State.RaidChoice)
            )
        end
    end

    local automationData = settings.LobbyAutomation
    if type(automationData) == "table" and next(automationData) ~= nil then
        if V98320LobbyAutomation and type(V98320LobbyAutomation.Merge) == "function" then
            V98320LobbyAutomation.Settings = V98320LobbyAutomation.Merge(
                V98320LobbyAutomation.Defaults,
                automationData
            )
            V98320LobbyAutomation.Settings.LastAchievementSweepUnix = 0
            V98320LobbyAutomation.Settings.GemReserve = math.max(
                0,
                math.floor((tonumber(V98320LobbyAutomation.Settings.GemReserve) or 500) + 0.5)
            )
            V98320LobbyAutomation.Settings.MaxPurchasesPerSession = math.clamp(
                math.floor((tonumber(V98320LobbyAutomation.Settings.MaxPurchasesPerSession) or 1) + 0.5),
                1,
                20
            )
            V98320LobbyAutomation.Settings.SerumKeepAtLeast = math.clamp(
                math.floor((tonumber(V98320LobbyAutomation.Settings.SerumKeepAtLeast) or 1) + 0.5),
                0,
                99
            )
            V98320LobbyAutomation.Settings.RaidDropKeepAtLeast = math.clamp(
                math.floor((tonumber(V98320LobbyAutomation.Settings.RaidDropKeepAtLeast) or 1) + 0.5),
                0,
                99
            )
            if type(V98320LobbyAutomation.Save) == "function" then pcall(V98320LobbyAutomation.Save) end
            if type(V98320LobbyAutomation.RefreshUI) == "function" then pcall(V98320LobbyAutomation.RefreshUI) end
        else
            V98330ConfigEcosystem.PendingLobbyAutomation = V98330ConfigEcosystem.DeepCopy(automationData)
        end
    end

    local upgradeData = settings.AutoUpgrade
    if type(upgradeData) == "table" and next(upgradeData) ~= nil then
        if V96LobbyAutoUpgrade then
            V96LobbyAutoUpgrade.Selected = type(upgradeData.Selected) == "table"
                and V98330ConfigEcosystem.DeepCopy(upgradeData.Selected)
                or V96LobbyAutoUpgrade.Selected
            V96LobbyAutoUpgrade.Delay = math.clamp(tonumber(upgradeData.Delay) or 0.55, 0.15, 2.0)
            V96LobbyAutoUpgrade.Enabled = upgradeData.Enabled == true
            V96LobbyAutoUpgrade.RunFinalized = not V96LobbyAutoUpgrade.Enabled
            if V96LobbyAutoUpgrade.Enabled and type(V96LobbyAutoUpgrade.BeginRun) == "function" then
                pcall(V96LobbyAutoUpgrade.BeginRun)
            end
            if V94LobbyRefresh and type(V94LobbyRefresh.AutoUpgrade) == "function" then pcall(V94LobbyRefresh.AutoUpgrade) end
        else
            V98330ConfigEcosystem.PendingAutoUpgrade = V98330ConfigEcosystem.DeepCopy(upgradeData)
        end
    end

    local prestigeData = settings.AutoPrestige
    if type(prestigeData) == "table" and next(prestigeData) ~= nil then
        if V962LobbyAutoPrestige then
            local premium = SliceHubLobbyIsPremium()
            if prestigeData.Enabled == true and not premium then
                V98330ConfigEcosystem.AddAdjustment(adjustments, "Premium Auto Prestige automation disabled on Free")
            end
            V962LobbyAutoPrestige.Enabled = premium and prestigeData.Enabled == true or false
            local requestedBuff = tostring(prestigeData.Buff or "Luck")
            V962LobbyAutoPrestige.Buff = V962LobbyAutoPrestige.NormalizeBuff(requestedBuff)
            if requestedBuff ~= V962LobbyAutoPrestige.Buff then
                V98330ConfigEcosystem.AddAdjustment(adjustments, "Prestige buff adjusted to " .. V962LobbyAutoPrestige.Buff)
            end
            if type(prestigeData.Thresholds) == "table" then
                for prestige = 0, 5 do
                    local rawValue = prestigeData.Thresholds[tostring(prestige)] or prestigeData.Thresholds[prestige]
                    local normalized = V962LobbyAutoPrestige.NormalizeThreshold(prestige, rawValue)
                    if normalized then V962LobbyAutoPrestige.Thresholds[prestige] = normalized end
                end
            end
            pcall(V962LobbyAutoPrestige.Save)
            if V962LobbyAutoPrestige.Refresh then pcall(V962LobbyAutoPrestige.Refresh) end
        else
            V98330ConfigEcosystem.PendingAutoPrestige = V98330ConfigEcosystem.DeepCopy(prestigeData)
        end
    end

    local treeData = settings.SkillTree
    if type(treeData) == "table" and next(treeData) ~= nil then
        if V97LobbySkillTree then
            V97LobbySkillTree.Enabled = treeData.Enabled == true
            V97LobbySkillTree.Middle = V97LobbySkillTree.NormalizeChoice("Middle", treeData.Middle)
            V97LobbySkillTree.Left = V97LobbySkillTree.NormalizeChoice("Left", treeData.Left)
            V97LobbySkillTree.Right = V97LobbySkillTree.NormalizeChoice("Right", treeData.Right)
            if type(treeData.Priority) == "table" then
                for index = 1, 3 do
                    V97LobbySkillTree.Priority[index] = V97LobbySkillTree.NormalizeChoice(
                        "Priority",
                        treeData.Priority[index]
                    )
                end
            end
            pcall(V97LobbySkillTree.Save)
            if V97LobbySkillTree.Refresh then pcall(V97LobbySkillTree.Refresh) end
        else
            V98330ConfigEcosystem.PendingSkillTree = V98330ConfigEcosystem.DeepCopy(treeData)
        end
    end

    if type(settings.MissionRuntime) == "table" then
        local okRuntime, runtimeError = V98330ConfigEcosystem.ApplyMissionRuntime(
            settings.MissionRuntime,
            adjustments
        )
        if not okRuntime then
            V98330ConfigEcosystem.AddAdjustment(adjustments, "Mission settings could not be saved: " .. tostring(runtimeError))
        end
    end

    if options.startCountdown == true
        and type(settings.Run) == "table"
        and State.AutoStart == true then
        if type(V98330ConfigEcosystem.StartCountdown) == "function" then
            task.defer(V98330ConfigEcosystem.StartCountdown)
        else
            V98330ConfigEcosystem.PendingStart = true
        end
    end

    return true, record, adjustments
end

local function saveConfigs()
    V98330ConfigEcosystem.EnsureFolders()
    local doc = {Version = 14, Format = V98330ConfigEcosystem.Format, Configs = SavedConfigs}
    if writefileFn then
        local okEncode, encoded = pcall(function() return HttpService:JSONEncode(doc) end)
        if not okEncode then return false, "JSON encode failed" end
        local okWrite = pcall(writefileFn, SaveFileName, encoded)
        if not okWrite then return false, "File write failed" end
        return true, "Saved to " .. SaveFileName
    end
    Env.LobbyCreatorDebugConfigs_v14 = doc
    return true, "Saved for this session"
end

local function loadConfigs()
    local doc = nil
    if readfileFn then
        for _, path in ipairs({SaveFileName, LegacySaveFileName}) do
            local okRead, raw = pcall(readfileFn, path)
            if okRead and type(raw) == "string" and raw ~= "" then
                local okDecode, decoded = pcall(function() return HttpService:JSONDecode(raw) end)
                if okDecode and type(decoded) == "table" then doc = decoded break end
            end
        end
    elseif type(Env.LobbyCreatorDebugConfigs_v14) == "table" then
        doc = Env.LobbyCreatorDebugConfigs_v14
    elseif type(Env.LobbyCreatorDebugConfigs_v11) == "table" then
        doc = Env.LobbyCreatorDebugConfigs_v11
    end
    if type(doc) ~= "table" then return end
    SavedConfigs = {}
    local configs = type(doc.Configs) == "table" and doc.Configs or doc
    for name, config in pairs(configs) do
        local clean = cleanName(name)
        if clean ~= "" then
            SavedConfigs[clean] = V98330ConfigEcosystem.NormalizeRecord(config, clean)
        end
    end
end

local function normalizeSettings(data)
    data = type(data) == "table" and data or {}

    local keyName = tostring(data.ToggleKeyName or Settings.ToggleKeyName or "RightShift")
    if not Enum.KeyCode[keyName] or keyName == "Unknown" then keyName = "RightShift" end

    local autoName = cleanName(data.AutoLoadConfigName or "")
    if autoName ~= "" and not SavedConfigs[autoName] then autoName = "" end

    return {
        ToggleKeyName = keyName,
        AutoLoadConfig = data.AutoLoadConfig == true,
        AutoLoadConfigName = autoName,
        MenuScale = math.clamp(math.floor((tonumber(data.MenuScale or Settings.MenuScale or 100) or 100) + 0.5), 80, 120),
    }
end

local function saveSettings()
    V98330ConfigEcosystem.EnsureFolders()
    local doc = {Version = 14, Settings = normalizeSettings(Settings)}
    if writefileFn then
        local okEncode, encoded = pcall(function() return HttpService:JSONEncode(doc) end)
        if not okEncode then return false, "JSON encode failed" end
        local okWrite = pcall(writefileFn, SettingsFileName, encoded)
        if not okWrite then return false, "File write failed" end
        return true, "Saved to " .. SettingsFileName
    end
    Env.LobbyCreatorStatusSettings_v14 = doc
    return true, "Saved for this session"
end

local function loadSettings()
    local doc = nil
    if readfileFn then
        for _, path in ipairs({SettingsFileName, LegacySettingsFileName}) do
            local okRead, raw = pcall(readfileFn, path)
            if okRead and type(raw) == "string" and raw ~= "" then
                local okDecode, decoded = pcall(function() return HttpService:JSONDecode(raw) end)
                if okDecode and type(decoded) == "table" then doc = decoded break end
            end
        end
    elseif type(Env.LobbyCreatorStatusSettings_v14) == "table" then
        doc = Env.LobbyCreatorStatusSettings_v14
    elseif type(Env.LobbyCreatorStatusSettings_v13) == "table" then
        doc = Env.LobbyCreatorStatusSettings_v13
    elseif type(Env.LobbyCreatorStatusSettings_v12) == "table" then
        doc = Env.LobbyCreatorStatusSettings_v12
    end

    if type(doc) == "table" then
        Settings = normalizeSettings(type(doc.Settings) == "table" and doc.Settings or doc)
    else
        Settings = normalizeSettings(Settings)
    end
end

local function getToggleKeyCode()
    local keyName = tostring(Settings.ToggleKeyName or "RightShift")
    return Enum.KeyCode[keyName] or Enum.KeyCode.RightShift
end

loadConfigs()
loadSettings()

if Settings.AutoLoadConfig and Settings.AutoLoadConfigName ~= "" and SavedConfigs[Settings.AutoLoadConfigName] then
    V98330ConfigEcosystem.PendingAutoloadName = Settings.AutoLoadConfigName
    V98330ConfigEcosystem.PendingAutoloadRecord = SavedConfigs[Settings.AutoLoadConfigName]
    local pendingRun = SavedConfigs[Settings.AutoLoadConfigName].settings
        and SavedConfigs[Settings.AutoLoadConfigName].settings.Run
    if type(pendingRun) == "table" then applyConfig(pendingRun) end
    SelectedConfig = Settings.AutoLoadConfigName
end

