local QuietLobbyToastTitles = {
    ["launch failed"] = true,
    ["teleport failed"] = true,
    ["out of blades"] = true,
    ["refill failed"] = true,
    ["premium only"] = true,
    ["premium locked"] = true,
    ["save failed"] = true,
    ["load failed"] = true,
    ["delete failed"] = true,
    ["storage failed"] = true,
    ["unsupported"] = true,
    ["webhook failed"] = true,
    ["no config selected"] = true,
    ["claimed"] = true,
    ["activated"] = true,
    ["bought"] = true,
    ["sold"] = true,
    ["automation paused"] = true,
    ["inventory scan"] = true,
}

local function normalizeLobbyToast(title, message, kind)
    local resolvedTitle = tostring(title or "")
    local lowerTitle = string.lower(resolvedTitle)

    if lowerTitle == "auto create stopped"
        or lowerTitle == "waves launch failed" then

        return "Launch failed",
            "Could not start the selected run.",
            "error"
    end

    if lowerTitle == "teleport failed" then
        return "Teleport failed",
            "Could not return to the lobby.",
            "error"
    end

    if not QuietLobbyToastTitles[lowerTitle] then
        return nil
    end

    return resolvedTitle, tostring(message or ""), kind
end

local toastOrder = 0
local function notify(title, message, kind)
    title, message, kind = normalizeLobbyToast(title, message, kind)
    if title == nil then return end
	toastOrder += 1
	local accent = kind == "error" and Theme.Danger or (kind == "success" and Theme.Success or Theme.Accent2)
	local toast = Instance.new("CanvasGroup")
	toast.LayoutOrder = toastOrder
	toast.Size = UDim2.fromOffset(292, 62)
	toast.Position = UDim2.fromOffset(28, 0)
	toast.BackgroundColor3 = Theme.Panel
	toast.BorderSizePixel = 0
	toast.GroupTransparency = 1
	toast.ZIndex = 101
	toast.Parent = notifyHolder
	corner(toast, 11); stroke(toast, accent, 0.1)

	local strip = Instance.new("Frame")
	strip.Size = UDim2.fromOffset(4, 42)
	strip.Position = UDim2.fromOffset(0, 10)
	strip.BackgroundColor3 = accent
	strip.BorderSizePixel = 0
	strip.ZIndex = 102
	strip.Parent = toast
	corner(strip, 4)

	local t = Instance.new("TextLabel")
	t.Position = UDim2.fromOffset(15, 8)
	t.Size = UDim2.new(1, -28, 0, 20)
	t.BackgroundTransparency = 1
	t.Font = Enum.Font.GothamBold
