local function runMissionFlow()
    if FlowRunning then
        notify("Already running", "Mission flow is already in progress.", "error")
        return
    end

    if State.CreateMode == "Raid"
        and type(SliceHubRaidChoiceAllowed) == "function"
        and not SliceHubRaidChoiceAllowed(State.RaidChoice) then
        warn("[SliceHub Free] " .. (type(SliceHubRaidLockedReason) == "function"
            and SliceHubRaidLockedReason(State.RaidChoice)
            or "This raid is unsupported in Free."))
        setOwnMenuVisible(true)
        refreshPreview()
        return
    end

    if State.CreateMode == "Raid" and State.RaidChoice == "Shiganshina (Col)" then
        notify(
            "Colossal Spears-only",
            type(SliceHubColossalModeText) == "function"
                and SliceHubColossalModeText()
                or "COLOSSAL • SPEARS ONLY",
            "info"
        )
        local ready, reason = V95LobbyWeaponPolicy.ColossalReady()
        if not ready then
            notify(
                "Colossal is Spears-only",
                tostring(reason) .. ". Blades are unsupported for Colossal in V9.5.",
                "error"
            )
            setOwnMenuVisible(true)
            refreshPreview()
            return
        end
    end

    if CurrentMode ~= "Lobby"
        and CurrentMode ~= "MainMenu"
        and CurrentMode ~= "Unknown" then
        notify("Blocked by mode", "Current mode is " .. CurrentMode .. ".", "error")
        return
    end

    FlowRunning = true
    setOwnMenuVisible(false)

    local ok, err = pcall(function()
        local launchConfig = captureConfig()
        local adaptiveMeta = nil
        local resolveError = nil

        launchConfig, adaptiveMeta, resolveError =
            V100HardestDifficulty.ResolveConfig(launchConfig)

        if not launchConfig then
            error(tostring(resolveError or "Hardest difficulty could not resolve"))
        end

        if adaptiveMeta then
            print(
                "[SliceHub Hardest]",
                adaptiveMeta.pending == true and "resolving" or tostring(adaptiveMeta.difficulty),
                "source=" .. tostring(adaptiveMeta.source)
            )
        end

        if launchConfig.CreateMode == "Raid" then
            if type(SliceHubRaidChoiceAllowed) == "function"
                and not SliceHubRaidChoiceAllowed(launchConfig.RaidChoice) then
                error(type(SliceHubRaidLockedReason) == "function"
                    and SliceHubRaidLockedReason(launchConfig.RaidChoice)
                    or "This raid is unsupported in Free.")
            end

            if not V401LobbyRaid.Data[launchConfig.RaidChoice] then
                error("Unknown raid choice: " .. tostring(launchConfig.RaidChoice))
            end
        end

        local runType = launchConfig.CreateMode == "Raid" and "Raid" or "Mission"
        print(
            "[LobbyCreator V9.8.4] Starting exact-only "
                .. string.lower(runType) .. " flow:",
            HttpService:JSONEncode(launchConfig)
        )

        saveLastMissionInfo(launchConfig)

        local callOk, exactOk, exactReason, launchedConfig =
            pcall(
                V3ExactMissionEngine.TryLaunch,
                launchConfig
            )

        if not callOk then
            -- Never leave the engine permanently locked after an unexpected
            -- runtime exception.
            V3ExactMissionEngine.Busy = false
            V3ExactMissionEngine.LastStage = "Failed"
            V3ExactMissionEngine.LastError =
                tostring(exactOk)

            error(
                runType
                    .. " exact launch runtime error: "
                    .. tostring(exactOk)
            )
        end

        if not exactOk then
            error(
                runType
                    .. " exact launch failed: "
                    .. tostring(exactReason)
            )
        end

        if type(launchedConfig) == "table" then
            saveLastMissionInfo(launchedConfig)
        end

    end)

    FlowRunning = false

    if not ok then
        warn("[LobbyCreator V9.8.4] Exact-only flow failed:", err)
        setOwnMenuVisible(true)
        notify("Auto Launch stopped", tostring(err), "error")
    end
end
local function startCountdown()
    if State.CreateMode == "Waves" and not SliceHubLobbyWavesAllowed() then
        notify("Premium only", "This tab unlocks only when you have Premium.", "info")
        return
    end

    CountdownToken += 1
    local token = CountdownToken
    State.Delay = math.clamp(math.floor((tonumber(State.Delay) or 5) + 0.5), 5, 300)

    local function markLaunching(active)
        V98330ConfigEcosystem.Launching = active == true
    end

    local function launchWaves()
        if FlowRunning then
            notify("Already running", "A lobby launch is already in progress.", "info")
            return
        end

        markLaunching(true)
        FlowRunning = true
        setOwnMenuVisible(false)
        saveLastMissionInfo()

        task.spawn(function()
            local ok, reason = V3ExactMissionEngine.TryLaunch({
                CreateMode = "Waves",
                Map = "Trost",
                Objective = "Waves",
                Difficulty = "Easy",
                Modifiers = {},
            })

            FlowRunning = false
            if not ok then
                markLaunching(false)
                setOwnMenuVisible(true)
                warn("[SliceHub Waves] direct launch failed:", reason)
                notify("Waves launch failed", tostring(reason), "error")
            end
        end)
    end

    local function launchSelected()
        markLaunching(true)
        runMissionFlow()
        task.delay(1.25, function()
            if gui.Parent and not FlowRunning then markLaunching(false) end
        end)
    end

    local isWaves = State.CreateMode == "Waves"
    local autoEnabled = isWaves and V98WavesUI.AutoStart or State.AutoStart
    if not autoEnabled then
        if isWaves then launchWaves() else launchSelected() end
        return
    end

    task.spawn(function()
        for remain = State.Delay, 1, -1 do
            if token ~= CountdownToken then
                countdownLabel.Text = "Ready"
                markLaunching(false)
                return
            end
            countdownLabel.Text = "Countdown: " .. V98330ConfigEcosystem.FormatDuration(remain)
            task.wait(1)
        end
        if token ~= CountdownToken then return end
        countdownLabel.Text = isWaves and "Launching Waves..." or "Launching..."
        if isWaves then launchWaves() else launchSelected() end
        task.wait(0.8)
        if token == CountdownToken and gui.Parent then countdownLabel.Text = "Ready" end
    end)
end
V98330ConfigEcosystem.StartCountdown = startCountdown

local function consumeMissionLimitRelaunch()
    if type(readfileFn) ~= "function" then return end
    local pendingPath = "SH/state/relaunch_after_limit_v984.json"
    local okPending, pendingRaw = pcall(readfileFn, pendingPath)
    if not okPending or type(pendingRaw) ~= "string" or pendingRaw == "" then return end

    if deletefileFn then pcall(deletefileFn, pendingPath) end

    -- Reset the persisted mission counter only after the lobby has actually loaded.
    pcall(function()
        local settingsPath = "TitanControlSettings_v101.json"
        local raw = readfileFn(settingsPath)
        local document = HttpService:JSONDecode(raw)
        document.Automation = type(document.Automation) == "table" and document.Automation or {}
        document.Automation.MissionCount = 0
        if type(writefileFn) == "function" then
            writefileFn(settingsPath, HttpService:JSONEncode(document))
        end
    end)

    local okLast, lastRaw = pcall(readfileFn, LastMissionInfoFileName)
    if okLast and type(lastRaw) == "string" and lastRaw ~= "" then
        local okDecode, last = pcall(function() return HttpService:JSONDecode(lastRaw) end)
        if okDecode and type(last) == "table" then
            applyConfig({
                CreateMode = last.CreateMode,
                RaidChoice = last.RaidChoice,
                Map = last.Map,
                Objective = last.Objective,
                Difficulty = last.Difficulty,
                Modifiers = last.Modifiers,
                AutoStart = false,
                Delay = 5,
            })
            refreshAll()
        end
    end

    task.delay(1.25, function()
        if gui and gui.Parent and not FlowRunning then
            countdownLabel.Text = "Launching..."
            startCountdown()
        end
    end)
end

task.defer(consumeMissionLimitRelaunch)
createBtn.Activated:Connect(startCountdown)
cancelBtn.Activated:Connect(function()
    CountdownToken += 1
    V98330ConfigEcosystem.Launching = false
    countdownLabel.Text = "Ready"
end)

