local function adjustmentsText(adjustments)
    if type(adjustments) ~= "table" or #adjustments == 0 then return "No compatibility adjustments." end
    local output = {}
    for index = 1, math.min(5, #adjustments) do output[#output + 1] = "• " .. tostring(adjustments[index]) end
    if #adjustments > 5 then output[#output + 1] = "• +" .. tostring(#adjustments - 5) .. " more" end
    return table.concat(output, "\n")
end

