function V98330ConfigEcosystem.ShowImportPreview(record, meta)
    record = V98330ConfigEcosystem.NormalizeRecord(record, record and record.name)
    V98330ConfigEcosystem.PendingPreview = {Record = record, Meta = meta or {}}
    overlay.Visible = true
    importCode.Visible = false
    importPreview.Visible = true
    parseBtn.Visible = false
    applySaveBtn.Visible = true
    applyOnceBtn.Visible = true
    importName.Text = cleanName(record.name) ~= "" and cleanName(record.name) or "Imported Config"
    local source = meta and meta.Source or "Import"
    local creator = meta and tostring(meta.Creator or "") or ""
    importTitle.Text = source == "Discord Easy Add" and "DISCORD EASY ADD" or "CONFIG PREVIEW"
    importSource.Text = source .. (creator ~= "" and (" • Shared by " .. creator) or "")
    importPreview.Text = V98330ConfigEcosystem.RecordSummary(record)
        .. "\n\nFree/Premium limits will be applied before saving."
end

local function showManualImport(initialText)
    overlay.Visible = true
    importTitle.Text = "IMPORT CONFIG"
    importSource.Text = "Paste a clipboard code, Discord token, or exported JSON."
    importCode.Visible = true
    importPreview.Visible = false
    parseBtn.Visible = true
    applySaveBtn.Visible = false
    applyOnceBtn.Visible = false
    importCode.Text = tostring(initialText or "")
    importName.Text = "Imported Config"
    V98330ConfigEcosystem.PendingPreview = nil
end

parseBtn.Activated:Connect(function()
    parseBtn.Text = "CHECKING..."
    task.spawn(function()
        local record, metaOrError = V98330ConfigEcosystem.ParseImport(importCode.Text)
        parseBtn.Text = "PREVIEW CODE"
        if not record then
            notify("Import failed", tostring(metaOrError), "error")
            return
        end
        V98330ConfigEcosystem.ShowImportPreview(record, metaOrError)
    end)
end)

local function applyPending(saveAfter)
    local pending = V98330ConfigEcosystem.PendingPreview
    if type(pending) ~= "table" or type(pending.Record) ~= "table" then return end
    local desiredName = cleanName(importName.Text)
    if desiredName == "" then desiredName = cleanName(pending.Record.name) end
    if desiredName == "" then desiredName = "Imported Config" end
    pending.Record.name = desiredName

    local ok, appliedRecord, adjustments = V98330ConfigEcosystem.ApplyRecord(
        pending.Record,
        {startCountdown = true}
    )
    if not ok then
        notify("Config failed", "The imported config could not be applied.", "error")
        return
    end

    if saveAfter then
        SavedConfigs[desiredName] = appliedRecord
        SelectedConfig = desiredName
        saveConfigs()
    end

    local meta = pending.Meta
    hideImportOverlay()
    refreshAll()
    if V94LobbyRefresh.Configs then V94LobbyRefresh.Configs() end
    notify(
        "Config applied",
        desiredName .. "\n" .. adjustmentsText(adjustments),
        "success"
    )
    task.spawn(function()
        local activated, activationResult = V98330ConfigEcosystem.Activate(meta)
        if not activated and meta and (meta.ConfigId or meta.Token) then
            warn("[SliceHub Configs] activation report failed:", activationResult)
        end
    end)
end

applySaveBtn.Activated:Connect(function() applyPending(true) end)
applyOnceBtn.Activated:Connect(function() applyPending(false) end)
