    if pending and pending.Meta and pending.Meta.DeliveryId then
        task.spawn(function() V98330ConfigEcosystem.Dismiss(pending.Meta) end)
    end
    hideImportOverlay()
end)

V94LobbyRefresh.Configs = function()
    for _, child in ipairs(configList:GetChildren()) do
        if child:IsA("TextButton") then child:Destroy() end
    end
    local names = {}
    for name, rawRecord in pairs(SavedConfigs) do
        local record = V98330ConfigEcosystem.NormalizeRecord(rawRecord, name)
        SavedConfigs[name] = record
        if configFilter == "all" or record.category == configFilter then names[#names + 1] = name end
    end
    table.sort(names, function(leftName, rightName) return string.lower(leftName) < string.lower(rightName) end)
    for index, name in ipairs(names) do
        local record = SavedConfigs[name]
        local run = record.settings.Run
        local runName = "Lobby automation"
        if run then
            runName = run.CreateMode == "Raid" and run.RaidChoice
                or run.CreateMode == "Waves" and "Trost Waves"
                or (run.Map .. " • " .. run.Objective)
        end
        local prefix = Settings.AutoLoadConfig and Settings.AutoLoadConfigName == name and "★ " or ""
        local object = button(
            configList,
            prefix .. name .. "\n" .. V98330ConfigEcosystem.CategoryLabel(record.category) .. " • " .. runName,
            UDim2.new(),
            UDim2.new(1, -8, 0, 50),
            SelectedConfig == name and Theme.Accent or Theme.Card
        )
        object.LayoutOrder = index
        object.TextSize = 9
        object.Activated:Connect(function()
            SelectedConfig = name
            nameBox.Text = name
            saveCategory = record.category
            setCategoryVisual()
            configPreview.Text = "Selected: " .. name
                .. (Settings.AutoLoadConfig and Settings.AutoLoadConfigName == name and "  [AUTO LOAD]" or "")
                .. "\n\n" .. V98330ConfigEcosystem.RecordSummary(record)
            if V94LobbyRefresh.Configs then V94LobbyRefresh.Configs() end
        end)
    end
    if SelectedConfig and SavedConfigs[SelectedConfig] then
        local record = SavedConfigs[SelectedConfig]
        configPreview.Text = "Selected: " .. SelectedConfig
            .. (Settings.AutoLoadConfig and Settings.AutoLoadConfigName == SelectedConfig and "  [AUTO LOAD]" or "")
            .. "\n\n" .. V98330ConfigEcosystem.RecordSummary(record)
    else
        configPreview.Text = "Selected: none\n\nChoose a type, save the current setup, or import a community config."
    end
    setCategoryVisual()
end

