copyBtn.Activated:Connect(function()
    local record, _, errorMessage = selectedRecordOrCurrent()
    if not record then notify("Export failed", tostring(errorMessage), "error"); return end
    local code, encodeError = V98330ConfigEcosystem.EncodeDraft(record)
    if not code then notify("Export failed", tostring(encodeError), "error"); return end
    local clipboard = Env.setclipboard or Env.toclipboard or (type(setclipboard) == "function" and setclipboard or nil)
    if type(clipboard) ~= "function" then
        showManualImport(code)
        notify("Clipboard unavailable", "The code is shown in the import box so you can copy it manually.", "info")
        return
    end
    local ok, copyError = pcall(clipboard, code)
    notify(ok and "Config copied" or "Copy failed", ok and ("Draft code copied • " .. tostring(#code) .. " characters") or tostring(copyError), ok and "success" or "error")
end)

