end)

exportBtn.Activated:Connect(function()
    local record, recordName, errorMessage = selectedRecordOrCurrent()
    if not record then notify("Export failed", tostring(errorMessage), "error"); return end
    local code, encodeError = V98330ConfigEcosystem.EncodeDraft(record)
    if not code then notify("Export failed", tostring(encodeError), "error"); return end
    local path = V98330ConfigEcosystem.ExportFolder .. "/"
        .. V98330ConfigEcosystem.SafeFileName(recordName or record.name) .. ".shcfg"
    V98330ConfigEcosystem.EnsureFolders()
    if type(writefileFn) ~= "function" then notify("Export failed", "File writing is unavailable.", "error"); return end
    local ok, writeError = pcall(writefileFn, path, code)
    notify(ok and "Config exported" or "Export failed", ok and path or tostring(writeError), ok and "success" or "error")
end)

importBtn.Activated:Connect(function()
    if type(readfileFn) ~= "function" then notify("Import failed", "File reading is unavailable.", "error"); return end
    local requested = tostring(nameBox.Text or "")
    local path = requested
    if not string.find(requested, "/", 1, true)
        and not string.find(requested, "\\", 1, true) then
        local baseName = requested ~= "" and requested or "config"
        baseName = string.gsub(baseName, "%.%a+$", "")
        path = V98330ConfigEcosystem.ExportFolder .. "/"
            .. V98330ConfigEcosystem.SafeFileName(baseName)
            .. ".shcfg"
    end
    local ok, raw = pcall(readfileFn, path)
    if not ok or type(raw) ~= "string" then notify("Import failed", "Could not read " .. path, "error"); return end
    showManualImport(raw)
    parseBtn.Text = "PREVIEW CODE"
end)

