-- Auto Upgrade tab.
;(function()
local upgradePage = PageFrames["Auto Upgrade"]
local upgradePanel = panel(upgradePage, UDim2.fromOffset(0, 0), UDim2.fromScale(1, 1))

V96LobbyAutoUpgrade = V96LobbyAutoUpgrade or {
    Enabled = false,
    Busy = false,
    Weapon = "Unknown",
    LastWeapon = "Unknown",
    LastAction = "Idle",
    Clicks = 0,
    Passes = 0,
    Delay = 0.55,
    Selected = {},
    LastLevels = {},
    LastGold = nil,
    LastPrestige = nil,
    LastResultType = "Idle",
    SuccessToastAt = 0,
    RunStartGold = nil,
    RunStartGrade = "Unknown",
    RunStartWeapon = "Unknown",
    RunStartedAt = 0,
    RunFinalized = true,
    UI = {},
}

V96LobbyAutoUpgrade.BladeStats = {
    {Key = "ODMDamage", RemoteKey = "ODM_Damage", Label = "ODM Damage", Aliases = {"odm damage", "odm dmg"}},
    {Key = "BladeDurability", RemoteKey = "Blade_Durability", Label = "Blade Durability", Aliases = {"blade durability", "durability"}},
    {Key = "ODMGas", RemoteKey = "ODM_Gas", Label = "ODM Gas", Aliases = {"odm gas", "gas capacity"}},
    {Key = "CritChance", RemoteKey = "Crit_Chance", Label = "Crit Chance", Aliases = {"crit chance", "critical chance"}},
    {Key = "ODMRange", RemoteKey = "ODM_Range", Label = "ODM Range", Aliases = {"odm range"}},
    {Key = "CritDamage", RemoteKey = "Crit_Damage", Label = "Crit Damage", Aliases = {"crit damage", "critical damage"}},
    {Key = "ODMControl", RemoteKey = "ODM_Control", Label = "ODM Control", Aliases = {"odm control"}},
    {Key = "ODMSpeed", RemoteKey = "ODM_Speed", Label = "ODM Speed", Aliases = {"odm speed"}},
}

V96LobbyAutoUpgrade.SpearStats = {
    {Key = "TSDamage", RemoteKey = "TS_Damage", Label = "TS Damage", Aliases = {"ts damage", "thunder spear damage", "spear damage"}},
    {Key = "BlastRadius", RemoteKey = "Blast_Radius", Label = "Blast Radius", Aliases = {"blast radius", "explosion radius"}},
    {Key = "CritChance", RemoteKey = "Crit_Chance", Label = "Crit Chance", Aliases = {"crit chance", "critical chance"}},
    {Key = "TSGas", RemoteKey = "TS_Gas", Label = "TS Gas", Aliases = {"ts gas", "thunder spear gas", "spear gas"}},
    {Key = "TSRange", RemoteKey = "TS_Range", Label = "TS Range", Aliases = {"ts range", "thunder spear range", "spear range"}},
    {Key = "TSSpeed", RemoteKey = "TS_Speed", Label = "TS Speed", Aliases = {"ts speed", "thunder spear speed", "spear speed"}},
    {Key = "TSControl", RemoteKey = "TS_Control", Label = "TS Control", Aliases = {"ts control", "thunder spear control", "spear control"}},
    {Key = "CritDamage", RemoteKey = "Crit_Damage", Label = "Crit Damage", Aliases = {"crit damage", "critical damage"}},
}

function V96LobbyAutoUpgrade.StatsForWeapon(weapon)
    if weapon == "Spears" then return V96LobbyAutoUpgrade.SpearStats end
    if weapon == "Blades" then return V96LobbyAutoUpgrade.BladeStats end
    return {}
end

function V96LobbyAutoUpgrade.IsSelected(key)
    if V96LobbyAutoUpgrade.Selected[key] == nil then
        V96LobbyAutoUpgrade.Selected[key] = true
    end
    return V96LobbyAutoUpgrade.Selected[key] == true
end

function V96LobbyAutoUpgrade.Match(text, aliases)
    local value = cleanText(text)
    for _, alias in ipairs(aliases or {}) do
        alias = cleanText(alias)
        if value == alias then return true end
        if string.find(value, alias, 1, true) and #value <= #alias + 18 then return true end
    end
    return false
end

function V96LobbyAutoUpgrade.DetectWeapon(liveOnly)
    local spearScore, bladeScore = 0, 0

    local function scoreText(raw, weight)
        local value = string.lower(tostring(raw or ""))
        if value == "" then return end

        if string.find(value, "thunder spear", 1, true)
            or string.find(value, "thunderspear", 1, true)
            or string.find(value, "spear", 1, true) then
            spearScore += weight
        end

        if string.find(value, "blade", 1, true)
            or string.find(value, "sword", 1, true) then
            bladeScore += weight
        end
    end

    local liveCharacter = player.Character
    local liveBackpack = player:FindFirstChildOfClass("Backpack")

    for _, root in ipairs({liveCharacter, liveBackpack}) do
        if root then
            scoreText(root.Name, 1)
            for _, object in ipairs(root:GetDescendants()) do
                scoreText(object.Name, object:IsA("Tool") and 8 or 2)
                if object:IsA("StringValue") then scoreText(object.Value, 5) end
            end
        end
    end

    if liveCharacter then
        if liveCharacter:GetAttribute("Spears") ~= nil then spearScore += 12 end
        if liveCharacter:GetAttribute("Max_Spears") ~= nil then spearScore += 12 end
        if liveCharacter:GetAttribute("BladeDurability") ~= nil then bladeScore += 8 end
        if liveCharacter:GetAttribute("Blades") ~= nil then bladeScore += 8 end
    end

    for key, value in pairs(player:GetAttributes()) do
        scoreText(key, 4)
        scoreText(value, 4)
    end

    -- Native lobby equipment text is strong evidence only when it actually says
    -- equipped/loadout/current, so our own Auto Upgrade labels cannot bias detection.
    for _, object in ipairs(visibleGameTextObjects()) do
        local value = cleanText(object.Text)
        if string.find(value, "equipped", 1, true)
            or string.find(value, "loadout", 1, true)
            or string.find(value, "current gear", 1, true) then
            scoreText(value, 10)
        end
    end

    if spearScore >= bladeScore + 3 and spearScore >= 6 then
        return "Spears", spearScore, bladeScore
    end
    if bladeScore >= spearScore + 3 and bladeScore >= 6 then
        return "Blades", spearScore, bladeScore
    end

    if liveOnly == true then
        return "Unknown", spearScore, bladeScore
    end

    -- Mission settings are only a last-resort hint; live equipment evidence above wins.
    local spearReady, bladesSaved = V95LobbyWeaponPolicy.Read()
    if spearReady == true and bladesSaved ~= true then return "Spears", spearScore, bladeScore end
    if bladesSaved == true and spearReady ~= true then return "Blades", spearScore, bladeScore end

    return V96LobbyAutoUpgrade.LastWeapon ~= "Unknown" and V96LobbyAutoUpgrade.LastWeapon or "Unknown", spearScore, bladeScore
end

function V96LobbyAutoUpgrade.Remote()
    local replicatedStorage = game:GetService("ReplicatedStorage")
    local assets = replicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("GET")
    if remote and remote:IsA("RemoteFunction") then return remote end
    return nil
end

function V96LobbyAutoUpgrade.SelectedRemoteKeys(weapon)
    local keys = {}
    for _, stat in ipairs(V96LobbyAutoUpgrade.StatsForWeapon(weapon)) do
        if V96LobbyAutoUpgrade.IsSelected(stat.Key) and stat.RemoteKey then
            keys[#keys + 1] = stat.RemoteKey
        end
    end
    return keys
end

function V96LobbyAutoUpgrade.CopyLevels(source)
    local output = {}
    if type(source) == "table" then
        for key, value in pairs(source) do
            if type(value) == "number" then output[tostring(key)] = value end
        end
    end
    return output
end

function V96LobbyAutoUpgrade.ParseProfile(result, weapon)
    if type(result) ~= "table" then return nil, nil, nil end

    local currentSlot = tostring(result.Current_Slot or "")
    local slots = type(result.Slots) == "table" and result.Slots or nil
    local slot = slots and slots[currentSlot] or nil
    if type(slot) ~= "table" then return nil, nil, nil end

    local upgrades = type(slot.Upgrades) == "table" and slot.Upgrades or nil
    local weaponLevels = upgrades and upgrades[weapon] or nil
    local levels = V96LobbyAutoUpgrade.CopyLevels(weaponLevels)

    local currency = type(slot.Currency) == "table" and slot.Currency or nil
    local progression = type(slot.Progression) == "table" and slot.Progression or nil
    local gold = currency and tonumber(currency.Gold) or nil
    local prestige = progression and tonumber(progression.Prestige) or nil

    return levels, gold, prestige
end

function V96LobbyAutoUpgrade.LevelGain(beforeLevels, afterLevels, keys)
    if type(beforeLevels) ~= "table" or type(afterLevels) ~= "table" then return nil end
    local gain = 0
    for _, key in ipairs(keys or {}) do
        local before = tonumber(beforeLevels[key])
        local after = tonumber(afterLevels[key])
        if before ~= nil and after ~= nil and after > before then
            gain += after - before
        end
    end
    return gain
end

function V96LobbyAutoUpgrade.ParseNumber(value)
    local digits = string.gsub(tostring(value or ""), "[^%d%-]", "")
    return tonumber(digits)
end

function V96LobbyAutoUpgrade.FormatNumber(value)
    value = tonumber(value)
    if value == nil then return "Unknown" end

    local negative = value < 0
    local digits = tostring(math.floor(math.abs(value) + 0.5))
    local reversed = string.reverse(digits)
    reversed = string.gsub(reversed, "(%d%d%d)", "%1,")
    digits = string.reverse(reversed)
    digits = string.gsub(digits, "^,", "")
    return (negative and "-" or "") .. digits
end

function V96LobbyAutoUpgrade.ReadNativeGold()
    local interface = playerGui:FindFirstChild("Interface")
    local topbar = interface and interface:FindFirstChild("Topbar")
    local main = topbar and topbar:FindFirstChild("Main")
    local currencies = main and main:FindFirstChild("Currencies")
    local gold = currencies and currencies:FindFirstChild("Gold")
    local amount = gold and gold:FindFirstChild("Amount")

    if amount and (
        amount:IsA("TextLabel")
        or amount:IsA("TextButton")
        or amount:IsA("TextBox")
    ) then
        local parsed = V96LobbyAutoUpgrade.ParseNumber(amount.Text)
        if parsed ~= nil then return parsed end
    end

    return tonumber(V96LobbyAutoUpgrade.LastGold)
end

function V96LobbyAutoUpgrade.ParseGradeText(raw)
    local value = string.upper(tostring(raw or ""))
    local grade = string.match(
        value,
        "UPGRADES%s*%[%s*([^%]]-)%s+GRADE%s*%]"
    )
    if not grade then return nil end
    grade = string.gsub(grade, "^%s+", "")
    grade = string.gsub(grade, "%s+$", "")
    return grade ~= "" and grade or nil
end

function V96LobbyAutoUpgrade.ReadNativeGrade()
    local interface = playerGui:FindFirstChild("Interface")
    local equipment = interface and interface:FindFirstChild("Equipment")
    local categories = equipment and equipment:FindFirstChild("Categories")
    local upgrades = categories and categories:FindFirstChild("Upgrades")
    local main = upgrades and upgrades:FindFirstChild("Main")
    local title = main and main:FindFirstChild("Title")

    if title and (
        title:IsA("TextLabel")
        or title:IsA("TextButton")
        or title:IsA("TextBox")
    ) then
        local grade = V96LobbyAutoUpgrade.ParseGradeText(title.Text)
        if grade then return grade end
    end

    for _, object in ipairs(playerGui:GetDescendants()) do
        if object:IsDescendantOf(gui) then continue end
        if object:IsA("TextLabel")
            or object:IsA("TextButton")
            or object:IsA("TextBox") then
            local grade = V96LobbyAutoUpgrade.ParseGradeText(object.Text)
            if grade then return grade end
        end
    end

    return nil
end

function V96LobbyAutoUpgrade.DetectNativeStopReason()
    for _, object in ipairs(visibleGameTextObjects()) do
        if object:IsDescendantOf(gui) then continue end
        local value = string.lower(tostring(object.Text or ""))
        value = string.gsub(value, "<.->", "")
        value = string.gsub(value, "%s+", " ")

        if string.find(value, "not enough gold", 1, true)
            or string.find(value, "insufficient gold", 1, true)
            or string.find(value, "cannot afford", 1, true) then
            return "NO_GOLD", "Not enough Gold"
        end

        if string.find(value, "maxed", 1, true)
            or string.find(value, "maximum level", 1, true)
            or string.find(value, "max level", 1, true) then
            return "MAXED", "Selected gear stats are maxed"
        end
    end
    return nil, nil
end

function V96LobbyAutoUpgrade.BeginRun()
    V96LobbyAutoUpgrade.RunStartGold =
        V96LobbyAutoUpgrade.ReadNativeGold()
    V96LobbyAutoUpgrade.RunStartGrade =
        V96LobbyAutoUpgrade.ReadNativeGrade()
        or "Unknown"
    V96LobbyAutoUpgrade.RunStartWeapon =
        V96LobbyAutoUpgrade.DetectWeapon()
    V96LobbyAutoUpgrade.RunStartedAt = os.clock()
    V96LobbyAutoUpgrade.RunFinalized = false
    V96LobbyAutoUpgrade.Clicks = 0
    V96LobbyAutoUpgrade.Passes = 0
    V96LobbyAutoUpgrade.LastLevels = {}
end

function V96LobbyAutoUpgrade.NotifySuccess(weapon, gain, gold, manual)
    if manual ~= true then return end

    local detail
    if type(gain) == "number" and gain > 0 then
        detail = tostring(weapon)
            .. " • "
            .. tostring(gain)
            .. " confirmed level gain"
    else
        detail = tostring(weapon)
            .. " • server confirmed upgrade pass"
    end
    if gold ~= nil then
        detail ..= " • Gold "
            .. V96LobbyAutoUpgrade.FormatNumber(gold)
    end
    notify("Gear successfully upgraded", detail, "success")
end

function V96LobbyAutoUpgrade.NotifyFinal(resultType, reason, kind)
    if V96LobbyAutoUpgrade.RunFinalized == true then return end
    V96LobbyAutoUpgrade.RunFinalized = true

    local goldLeft =
        V96LobbyAutoUpgrade.ReadNativeGold()
        or tonumber(V96LobbyAutoUpgrade.LastGold)
    local startGold =
        tonumber(V96LobbyAutoUpgrade.RunStartGold)
    local goldSpent = nil
    if startGold ~= nil and goldLeft ~= nil then
        goldSpent = math.max(0, startGold - goldLeft)
    end

    local grade =
        V96LobbyAutoUpgrade.ReadNativeGrade()
        or V96LobbyAutoUpgrade.RunStartGrade
        or "Unknown"
    local weapon =
        V96LobbyAutoUpgrade.Weapon ~= "Unknown"
        and V96LobbyAutoUpgrade.Weapon
        or V96LobbyAutoUpgrade.RunStartWeapon
        or V96LobbyAutoUpgrade.LastWeapon
        or "Unknown"

    local completed = tostring(resultType) == "MAXED"
    local title = completed
        and "GEAR UPGRADE COMPLETE"
        or "GEAR UPGRADE PAUSED"
    local detail =
        tostring(reason or "Upgrade run stopped")
        .. "\nCurrent Grade: "
        .. tostring(grade)
        .. " • Gold Spent: "
        .. V96LobbyAutoUpgrade.FormatNumber(goldSpent)
        .. " • Gold Left: "
        .. V96LobbyAutoUpgrade.FormatNumber(goldLeft)
        .. "\nEquipment: "
        .. tostring(weapon)
        .. " • Confirmed Levels: "
        .. tostring(V96LobbyAutoUpgrade.Clicks)
        .. " • Passes: "
        .. tostring(V96LobbyAutoUpgrade.Passes)

    notify(
        title,
        detail,
        kind or (completed and "success" or "info")
    )
end

function V96LobbyAutoUpgrade.ClassifyResponse(result)
    if type(result) == "table" then return "SUCCESS" end
    if type(result) == "string" then
        local value = string.lower(result)
        if string.find(value, "max", 1, true) then return "MAXED" end
        if string.find(value, "gold", 1, true)
            or string.find(value, "fund", 1, true)
            or string.find(value, "currency", 1, true)
            or string.find(value, "afford", 1, true) then
            return "NO_GOLD"
        end
        return "REJECTED"
    end
    if result == false then return "REJECTED" end
    return "NO_PROGRESS"
end

function V96LobbyAutoUpgrade.InvokeBatch(keys)
    local remote = V96LobbyAutoUpgrade.Remote()
    if not remote then
        return false, nil, "GET RemoteFunction missing"
    end

    local ok, result = pcall(function()
        return remote:InvokeServer(
            "S_Equipment",
            "Upgrade",
            keys
        )
    end)

    if not ok then return false, nil, tostring(result) end
    return true, result, nil
end

function V96LobbyAutoUpgrade.StopAuto(
    resultType,
    reason,
    kind
)
    V96LobbyAutoUpgrade.Enabled = false
    V96LobbyAutoUpgrade.LastResultType =
        tostring(resultType or "STOPPED")
    V96LobbyAutoUpgrade.NotifyFinal(
        resultType,
        reason,
        kind
    )
end

function V96LobbyAutoUpgrade.RunPass(manual)
    if V96LobbyAutoUpgrade.Busy then return 0, "busy" end
    V96LobbyAutoUpgrade.Busy = true

    if V96LobbyAutoUpgrade.RunFinalized == true
        or (tonumber(V96LobbyAutoUpgrade.RunStartedAt) or 0) <= 0 then
        V96LobbyAutoUpgrade.BeginRun()
    end

    local weapon = V96LobbyAutoUpgrade.DetectWeapon()
    V96LobbyAutoUpgrade.Weapon = weapon
    if weapon ~= "Unknown" then
        V96LobbyAutoUpgrade.LastWeapon = weapon
    end

    if weapon == "Unknown" then
        V96LobbyAutoUpgrade.LastAction =
            "Waiting for equipped loadout detection"
        V96LobbyAutoUpgrade.Busy = false
        return 0, "unknown loadout"
    end

    local keys =
        V96LobbyAutoUpgrade.SelectedRemoteKeys(weapon)
    if #keys == 0 then
        V96LobbyAutoUpgrade.LastAction =
            "No stats selected"
        V96LobbyAutoUpgrade.Busy = false
        return 0, "no stats selected"
    end

    V96LobbyAutoUpgrade.Passes += 1
    V96LobbyAutoUpgrade.LastAction =
        "Sending "
        .. tostring(#keys)
        .. " selected "
        .. tostring(weapon)
        .. " stats"

    local ok, result, remoteError =
        V96LobbyAutoUpgrade.InvokeBatch(keys)
    if not ok then
        V96LobbyAutoUpgrade.LastAction =
            "Remote error • "
            .. tostring(remoteError)
        V96LobbyAutoUpgrade.StopAuto(
            "ERROR",
            "Remote error: " .. tostring(remoteError),
            "error"
        )
        V96LobbyAutoUpgrade.Busy = false
        return 0, V96LobbyAutoUpgrade.LastAction
    end

    local resultType =
        V96LobbyAutoUpgrade.ClassifyResponse(result)
    if resultType == "NO_PROGRESS" then
        local nativeType =
            V96LobbyAutoUpgrade.DetectNativeStopReason()
        if nativeType then resultType = nativeType end
    end
    V96LobbyAutoUpgrade.LastResultType = resultType

    if resultType == "SUCCESS" then
        local levels, gold, prestige =
            V96LobbyAutoUpgrade.ParseProfile(
                result,
                weapon
            )
        local before =
            V96LobbyAutoUpgrade.LastLevels[weapon]
        local gain =
            V96LobbyAutoUpgrade.LevelGain(
                before,
                levels,
                keys
            )

        if type(levels) == "table" then
            V96LobbyAutoUpgrade.LastLevels[weapon] =
                levels
        end
        if gold ~= nil then
            V96LobbyAutoUpgrade.LastGold = gold
        end
        if prestige ~= nil then
            V96LobbyAutoUpgrade.LastPrestige = prestige
        end

        local confirmed =
            (
                type(gain) == "number"
                and gain > 0
            )
            and gain
            or 1
        V96LobbyAutoUpgrade.Clicks += confirmed

        if type(gain) == "number" and gain > 0 then
            V96LobbyAutoUpgrade.LastAction =
                string.format(
                    "Pass %d • +%d confirmed level%s",
                    V96LobbyAutoUpgrade.Passes,
                    gain,
                    gain == 1 and "" or "s"
                )
        else
            V96LobbyAutoUpgrade.LastAction =
                "Pass "
                .. tostring(
                    V96LobbyAutoUpgrade.Passes
                )
                .. " • server confirmed upgrade"
        end

        V96LobbyAutoUpgrade.NotifySuccess(
            weapon,
            gain,
            gold,
            manual == true
        )

        if manual == true then
            V96LobbyAutoUpgrade.RunFinalized = true
            V96LobbyAutoUpgrade.RunStartedAt = 0
        end

        V96LobbyAutoUpgrade.Busy = false
        return confirmed,
            V96LobbyAutoUpgrade.LastAction
    end

    if resultType == "MAXED" then
        V96LobbyAutoUpgrade.LastAction =
            "Selected gear stats MAXED"
        V96LobbyAutoUpgrade.StopAuto(
            "MAXED",
            "Selected gear stats are maxed",
            "success"
        )
    elseif resultType == "NO_GOLD" then
        V96LobbyAutoUpgrade.LastAction =
            "Upgrade paused • Not enough Gold"
        V96LobbyAutoUpgrade.StopAuto(
            "NO_GOLD",
            "Not enough Gold for the next selected upgrade",
            "error"
        )
    elseif resultType == "REJECTED" then
        V96LobbyAutoUpgrade.LastAction =
            "Upgrade request rejected"
        V96LobbyAutoUpgrade.StopAuto(
            "REJECTED",
            tostring(result or "Upgrade request rejected"),
            "error"
        )
    else
        local goldText =
            V96LobbyAutoUpgrade.LastGold ~= nil
            and (
                " • Last known Gold "
                .. V96LobbyAutoUpgrade.FormatNumber(
                    V96LobbyAutoUpgrade.LastGold
                )
            )
            or ""
        V96LobbyAutoUpgrade.LastAction =
            "No upgrade accepted • maxed or unaffordable"
            .. goldText
        V96LobbyAutoUpgrade.StopAuto(
            "NO_PROGRESS",
            "No upgrade accepted; selected stats are maxed or the next level is unaffordable",
            "info"
        )
    end

    V96LobbyAutoUpgrade.Busy = false
    return 0, V96LobbyAutoUpgrade.LastAction
end

label(upgradePanel, "Auto Upgrade", UDim2.fromOffset(14, 10), UDim2.new(1, -28, 0, 22), true)
local info = label(
    upgradePanel,
    "No weapon tabs: V9.6.1 detects the equipped loadout, sends selected stat keys through the grounded S_Equipment Upgrade remote, and verifies server responses. Auto starts OFF.",
    UDim2.fromOffset(14, 34),
