actionLabel.TextSize = 10

local autoButton = button(upgradePanel, "AUTO UPGRADE: OFF", UDim2.fromOffset(14, 160), UDim2.new(0.5, -18, 0, 38), Theme.Card)
local passButton = button(upgradePanel, "RUN ONE PASS", UDim2.new(0.5, 4, 0, 160), UDim2.new(0.5, -18, 0, 38), Theme.Accent)

local selectAllButton = button(upgradePanel, "SELECT ALL", UDim2.fromOffset(14, 208), UDim2.new(0.5, -18, 0, 32), Theme.Card)
local clearAllButton = button(upgradePanel, "CLEAR ALL", UDim2.new(0.5, 4, 0, 208), UDim2.new(0.5, -18, 0, 32), Theme.Card)

local statHolder = Instance.new("Frame")
statHolder.Position = UDim2.fromOffset(14, 252)
statHolder.Size = UDim2.new(1, -28, 0, 206)
statHolder.BackgroundTransparency = 1
statHolder.Parent = upgradePanel

local statGrid = Instance.new("UIGridLayout")
statGrid.CellPadding = UDim2.fromOffset(7, 7)
statGrid.CellSize = UDim2.new(0.5, -4, 0, 45)
statGrid.SortOrder = Enum.SortOrder.LayoutOrder
