        Epic = false,
        Legendary = false,
        Mythic = false,
    },
    SelectedItems = {},
}

function A.DeepCopy(value)
    if type(value) ~= "table" then return value end
    local output = {}
    for key, child in pairs(value) do
        output[key] = A.DeepCopy(child)
    end
    return output
end

function A.Merge(defaults, loaded)
    local result = A.DeepCopy(defaults)
    if type(loaded) ~= "table" then return result end
    for key, value in pairs(loaded) do
        if type(value) == "table" and type(result[key]) == "table" then
            result[key] = A.Merge(result[key], value)
        else
            result[key] = value
        end
    end
    return result
end

function A.EnsureFolders()
    if type(makefolder) ~= "function" then return end
    pcall(makefolder, "SH")
    pcall(makefolder, "SH/config")
end

function A.Load()
    local loaded = nil
    if readfileFn then
        local okRead, raw = pcall(readfileFn, A.FileName)
        if okRead and type(raw) == "string" and raw ~= "" then
            local okDecode, document = pcall(function()
                return HttpService:JSONDecode(raw)
            end)
            if okDecode and type(document) == "table" then
                loaded = type(document.Settings) == "table"
                    and document.Settings
                    or document
            end
        end
    elseif type(Env.SliceHubLobbyAutomationSettings) == "table" then
        loaded = Env.SliceHubLobbyAutomationSettings
    end

    A.Settings = A.Merge(A.Defaults, loaded)
    A.Settings.GemReserve = math.max(0, math.floor((tonumber(A.Settings.GemReserve) or 500) + 0.5))
    A.Settings.MaxPurchasesPerSession = math.clamp(math.floor((tonumber(A.Settings.MaxPurchasesPerSession) or 1) + 0.5), 1, 20)
    A.Settings.SerumKeepAtLeast = math.clamp(math.floor((tonumber(A.Settings.SerumKeepAtLeast) or 1) + 0.5), 0, 99)
    A.Settings.RaidDropKeepAtLeast = math.clamp(math.floor((tonumber(A.Settings.RaidDropKeepAtLeast) or 1) + 0.5), 0, 99)
    return A.Settings
end

function A.Save()
    A.EnsureFolders()
    Env.SliceHubLobbyAutomationSettings = A.Settings
    if not writefileFn then return true, "saved for session" end

    local okEncode, encoded = pcall(function()
        return HttpService:JSONEncode({
            Version = 1,
            Settings = A.Settings,
        })
    end)
    if not okEncode then return false, "JSON encode failed" end
    local okWrite, err = pcall(writefileFn, A.FileName, encoded)
    return okWrite, okWrite and "saved" or tostring(err)
end

function A.Clean(value)
    local text = tostring(value or "")
    text = string.gsub(text, "<.->", "")
    text = string.gsub(text, "%s+", " ")
    text = string.gsub(text, "^%s+", "")
    text = string.gsub(text, "%s+$", "")
    return text
end

function A.Lower(value)
    return string.lower(A.Clean(value))
end

function A.Path(object)
    local parts = {}
    local node = object
    for _ = 1, 16 do
        if not node then break end
        table.insert(parts, 1, tostring(node.Name))
        if node == playerGui then break end
        node = node.Parent
    end
    return table.concat(parts, ".")
end

function A.Visible(object)
    if not object or not object:IsA("GuiObject") then return false end
    if not object.Visible or object.AbsoluteSize.X <= 0 or object.AbsoluteSize.Y <= 0 then return false end
    local node = object.Parent
    while node and node ~= playerGui do
        if node:IsA("GuiObject") and not node.Visible then return false end
        if node:IsA("LayerCollector") and not node.Enabled then return false end
        node = node.Parent
    end
    return true
end

function A.ButtonAncestor(object)
    local node = object
    for _ = 1, 10 do
        if not node or node == playerGui then break end
        if node:IsA("GuiButton") then return node end
        node = node.Parent
    end
    return nil
end

function A.CardRoot(object)
    if not object or not object:IsA("GuiObject") then return nil end

    -- Prefer the nearest real native button. Never climb to a whole inventory
    -- panel, because selecting the wrong ancestor could target the wrong item.
    local buttonRoot = A.ButtonAncestor(object)
    if buttonRoot then return buttonRoot end

    local node = object.Parent
    for _ = 1, 7 do
        if not node or node == playerGui then break end
        if node:IsA("GuiObject") then
            local size = node.AbsoluteSize
            if size.X >= 45 and size.Y >= 34
                and size.X <= 460 and size.Y <= 190 then
                return node
            end
        end
        node = node.Parent
    end
    return object
end

function A.Activate(object)
    if not object or not object.Parent then return false end
    local target = A.ButtonAncestor(object) or object
    local fired = false
    local getConnections = type(getconnections) == "function" and getconnections or nil

    if target:IsA("GuiButton") and getConnections then
        for _, signalName in ipairs({"Activated", "MouseButton1Click", "TouchTap"}) do
            local okSignal, signal = pcall(function() return target[signalName] end)
            if okSignal and signal then
                local okList, list = pcall(getConnections, signal)
                if okList and type(list) == "table" then
                    for _, connection in ipairs(list) do
                        if connection and type(connection.Fire) == "function" then
                            fired = pcall(function() connection:Fire() end) or fired
                        end
                    end
                end
            end
        end
    end

    if target:IsA("GuiButton") then
        pcall(function() target:Activate() end)
