    end

    if not fired and target:IsA("GuiObject") then
        local vim = game:GetService("VirtualInputManager")
        local inset = Vector2.zero
        pcall(function() inset = game:GetService("GuiService"):GetGuiInset() end)
        local pos = target.AbsolutePosition
        local size = target.AbsoluteSize
        local x = math.floor(pos.X + size.X * 0.5 + inset.X + 0.5)
        local y = math.floor(pos.Y + size.Y * 0.5 + inset.Y + 0.5)
        pcall(function() vim:SendMouseMoveEvent(x, y, game) end)
        pcall(function() vim:SendMouseButtonEvent(x, y, 0, true, game, 0) end)
        task.wait(0.03)
        pcall(function() vim:SendMouseButtonEvent(x, y, 0, false, game, 0) end)
        fired = true
    end
    return fired
end

function A.FindText(needle, pathNeedle, exact)
    needle = A.Lower(needle)
    pathNeedle = pathNeedle and A.Lower(pathNeedle) or nil
    for _, object in ipairs(playerGui:GetDescendants()) do
        if object:IsDescendantOf(gui) then continue end
        if (object:IsA("TextButton") or object:IsA("TextLabel") or object:IsA("TextBox"))
            and A.Visible(object) then
            local value = A.Lower(object.Text)
            local match = exact and value == needle or string.find(value, needle, 1, true)
            if match then
                local path = A.Lower(A.Path(object))
                if not pathNeedle or string.find(path, pathNeedle, 1, true) then
                    return object
                end
            end
        end
    end
    return nil
end

function A.FindActionButton(words, pathNeedle)
    for _, word in ipairs(words) do
        local found = A.FindText(word, pathNeedle, true)
        if found then return A.ButtonAncestor(found) or found end
    end
    return nil
end

function A.OpenPage(name)
    local object = A.FindText(name, nil, true)
    if not object then object = A.FindText(name, nil, false) end
    if not object then return false end
    return A.Activate(object)
end

function A.NearbyTexts(object)
    local card = A.CardRoot(object)
    local output = {}
    local seen = {}
    if not card then return output end
    for _, descendant in ipairs(card:GetDescendants()) do
        if (descendant:IsA("TextLabel") or descendant:IsA("TextButton")) then
            local value = A.Clean(descendant.Text)
            local key = A.Lower(value)
            if value ~= "" and not seen[key] then
                seen[key] = true
                output[#output + 1] = value
            end
        end
    end
    return output
end

function A.BestTitle(object)
    local generic = {
        claim=true, claimed=true, equip=true, select=true, use=true,
        activate=true, sell=true, yes=true, no=true, delete=true,
        close=true, inventory=true, equipment=true, perks=true,
        artifacts=true, quantity=true,
    }
    for _, value in ipairs(A.NearbyTexts(object)) do
        local lower = A.Lower(value)
        if #value >= 3 and #value <= 64 and not generic[lower]
            and not string.match(lower, "^%d+[%d,]*/%d") then
            return value
        end
    end
    return "Unknown"
end

function A.ActivityLog(message, kind, toastTitle)
    local entry = {
        Time = os.date("%H:%M:%S"),
        Message = tostring(message or ""),
        Kind = tostring(kind or "info"),
    }
    table.insert(A.Activity, 1, entry)
    while #A.Activity > 24 do table.remove(A.Activity) end

    if A.Settings.ActivityToasts == true and toastTitle then
        notify(toastTitle, entry.Message, kind == "error" and "error" or "success")
    end
    if A.RefreshUI then A.RefreshUI() end
end


function A.Remote()
    if V97LobbySkillTree
        and type(V97LobbySkillTree.Remote) == "function" then
        local remote = V97LobbySkillTree.Remote()
        if remote and remote:IsA("RemoteFunction") then
            return remote
        end
    end

    local replicatedStorage = game:GetService("ReplicatedStorage")
    local assets = replicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("GET")
    if remote and remote:IsA("RemoteFunction") then
        return remote
    end
    return nil
end

function A.ResolveSlotTable(value)
    if type(value) ~= "table" then return nil end

    if type(value.Perks) == "table"
        and type(value.Inventory) == "table" then
        return value
    end

    if type(value.Slots) == "table" then
        if V97LobbySkillTree
            and type(V97LobbySkillTree.ResolveSlot) == "function" then
            local _, slot = V97LobbySkillTree.ResolveSlot(value)
            if type(slot) == "table" then return slot end
        end

        local key = player:GetAttribute("Slot")
            or value.Current_Slot
        if key ~= nil and type(value.Slots[key]) == "table" then
            return value.Slots[key]
        end
        if key ~= nil
            and type(value.Slots[tostring(key)]) == "table" then
            return value.Slots[tostring(key)]
        end
    end

    return nil
end

function A.CacheResponse(value)
    if type(value) ~= "table" then return end

    if type(value.Slots) == "table" then
        A.LastProfile = value
        if V97LobbySkillTree then
            V97LobbySkillTree.LastProfile = value
            V97LobbySkillTree.ControllerProfile = value
            V97LobbySkillTree.ControllerProfileAt = os.clock()
        end
    end

    local slot = A.ResolveSlotTable(value)
    if type(slot) == "table" then
        A.LastSlot = slot
        if type(value.Slots) ~= "table" then
            -- S_Inventory/Item returns the authoritative slot directly.
            -- Do not let an older full-profile snapshot hide that update.
            A.LastProfile = nil
        end
    end
end

function A.CurrentProfile()
    if type(A.LastProfile) == "table" then
        local slot = A.ResolveSlotTable(A.LastProfile)
        if type(slot) == "table" then
            return A.LastProfile, slot, "remote response"
        end
    end

    if V97LobbySkillTree
        and type(V97LobbySkillTree.FindCachedProfile) == "function" then
        local ok, profile, source = pcall(
            V97LobbySkillTree.FindCachedProfile
        )
        if ok and type(profile) == "table" then
            local slot = A.ResolveSlotTable(profile)
            if type(slot) == "table" then
                A.LastProfile = profile
                A.LastSlot = slot
                return profile, slot, source or "client cache"
            end
        end
    end

    if type(A.LastSlot) == "table" then
        return nil, A.LastSlot, "last slot response"
    end

    return nil, nil, nil
end

function A.FindController()
    if type(A.Controller) == "table" then
        local cache = rawget(A.Controller, "Cache")
        local modules = rawget(A.Controller, "Modules")
        if type(cache) == "table"
            and type(modules) == "table"
            and type(rawget(modules, "Perk")) == "table" then
            return A.Controller
        end
    end

    if type(getgc) ~= "function" then return nil end
    local ok, objects = pcall(getgc, true)
    if not ok or type(objects) ~= "table" then return nil end

    for _, object in ipairs(objects) do
        if type(object) == "table" then
            local cache = rawget(object, "Cache")
            local modules = rawget(object, "Modules")
            local perk = type(modules) == "table"
                and rawget(modules, "Perk")
                or nil
            if type(cache) == "table"
                and type(perk) == "table"
                and type(rawget(perk, "Get_Rarity_And_Type"))
                    == "function" then
                A.Controller = object
                return object
            end
        end
    end

    return nil
end

function A.ResolvePerkRarity(name)
    local controller = A.FindController()
    local modules = controller and rawget(controller, "Modules")
    local perk = type(modules) == "table"
        and rawget(modules, "Perk")
        or nil
    local resolver = type(perk) == "table"
        and rawget(perk, "Get_Rarity_And_Type")
        or nil

    if type(resolver) == "function" then
        local ok, rarity = pcall(
            resolver,
            controller,
            tostring(name or "")
        )
        if ok and type(rarity) == "string" then
            local normalized = string.upper(
                string.sub(rarity, 1, 1)
            ) .. string.lower(string.sub(rarity, 2))
            if table.find(
                {"Common", "Rare", "Epic", "Legendary", "Mythic"},
                normalized
            ) then
                return normalized
            end
        end
    end

    return nil
end

function A.ReadSlotCurrency(name)
    local _, slot = A.CurrentProfile()
    local currency = slot and slot.Currency
    return type(currency) == "table"
        and tonumber(currency[name])
        or nil
end

function A.ReadOwnedItemQuantity(itemName)
    local _, slot = A.CurrentProfile()
    local inventory = slot and slot.Inventory
    local items = type(inventory) == "table"
        and inventory.Items
        or nil
    if type(items) ~= "table" then return nil end
    return tonumber(items[itemName]) or 0
end

function A.ReadValue(name)
    local target = nil
    for _, root in ipairs({
        player,
        player:FindFirstChild("leaderstats"),
        player:FindFirstChild("Data"),
        player:FindFirstChild("Stats"),
        player:FindFirstChild("Currency"),
        player:FindFirstChild("Boosts"),
    }) do
        if root then
            local object = root:FindFirstChild(name, true)
            if object and (object:IsA("IntValue") or object:IsA("NumberValue")) then
                target = object
                break
            end
        end
    end
    return target and tonumber(target.Value) or nil
end

function A.ReadVisibleNumber(labelName)
    local needle = A.Lower(labelName)
    for _, object in ipairs(playerGui:GetDescendants()) do
        if object:IsDescendantOf(gui) then continue end
        if (object:IsA("TextLabel") or object:IsA("TextButton")) and A.Visible(object) then
            local text = A.Clean(object.Text)
            local lower = A.Lower(text)
            if string.find(lower, needle, 1, true) then
                local numberText = string.match(text, "([%d,]+)")
                if numberText then
                    return tonumber((string.gsub(numberText, ",", "")))
                end
            end
        end
    end
    return nil
end

function A.ReadBoost(kind)
    local boosts = player:FindFirstChild("Boosts")
    local object = boosts and boosts:FindFirstChild(kind)
    if object and (object:IsA("IntValue") or object:IsA("NumberValue")) then
        return tonumber(object.Value) or 0
    end
    return A.ReadValue(kind) or 0
end

function A.AchievementListRoot()
    local interface =
        playerGui:FindFirstChild("Interface")
    local achievements =
        interface
        and interface:FindFirstChild("Achievements")
    local list =
        achievements
        and achievements:FindFirstChild("List")
    local inner =
        list
        and list:FindFirstChild("Inner")

    return inner
end

function A.AchievementEntryState(entry)
    if not entry then return "", nil, nil end
    local inner = entry:FindFirstChild("Inner")
    local state =
        inner
        and inner:FindFirstChild("A_State")
    local title =
        state
        and state:FindFirstChild("Title")

    local text = ""
    if title and (
        title:IsA("TextLabel")
        or title:IsA("TextButton")
        or title:IsA("TextBox")
    ) then
        text = string.upper(A.Clean(title.Text))
    end

    return text, state, title
end

function A.AchievementEntryName(entry)
    local inner = entry and entry:FindFirstChild("Inner")
    local title = inner and inner:FindFirstChild("Title")
    if title and (
        title:IsA("TextLabel")
        or title:IsA("TextButton")
        or title:IsA("TextBox")
    ) then
        return A.Clean(title.Text)
    end
    return entry and tostring(entry.Name) or "Unknown"
end

function A.FindClaimableAchievementIds()
    local root = A.AchievementListRoot()
    if not root then return {}, nil end

    local ids = {}
    for _, entry in ipairs(root:GetChildren()) do
        local achievementId = tonumber(entry.Name)
        if achievementId then
            local state = A.AchievementEntryState(entry)
            if state == "CLAIM" then
                ids[#ids + 1] = achievementId
            end
        end
    end

    table.sort(ids)
    return ids, root
end

function A.AchievementClaimVerified(achievementId)
    local root = A.AchievementListRoot()
    local entry =
        root
        and root:FindFirstChild(
            tostring(achievementId)
        )
    if not entry then return false end

    local state = A.AchievementEntryState(entry)
    if state ~= "" and state ~= "CLAIM" then
        return true
    end

    for _, object in ipairs(entry:GetDescendants()) do
        if object.Name == "Claimed" then
            if not object:IsA("GuiObject")
                or object.Visible then
                return true
            end
        elseif object.Name == "Checkmark"
            and object:IsA("GuiObject")
            and object.Visible then
            return true
        end
    end

    return false
end

function A.TryClaimAchievements(manual)
    if A.AchievementBusy then
        return false, 0, "busy"
    end
    A.AchievementBusy = true

    local function finish(ok, count, reason)
        A.AchievementBusy = false
        A.LastAchievementClaimCount =
            tonumber(count) or 0
        return ok, count, reason
    end

    local remote = A.Remote()
    if not remote then
        A.ActivityLog(
            "Achievement claim remote is unavailable.",
            "error",
            "Automation Paused"
        )
        return finish(false, 0, "remote unavailable")
    end

    local ids, root =
        A.FindClaimableAchievementIds()
    if not root then
        if manual == true
            or os.clock()
                - (A.LastProtocolNoticeAt or 0)
                > A.AchievementRetryCooldown then
            A.LastProtocolNoticeAt = os.clock()
            A.ActivityLog(
                "Open the native Achievements page once so SliceHub can discover exact CLAIM entries.",
                "info",
                manual == true
                    and "Achievements Not Ready"
                    or nil
            )
        end
        return finish(false, 0, "native list unavailable")
    end

    if #ids == 0 then
        A.ActivityLog(
            "No claimable achievements detected.",
            "info",
            manual == true
                and "Achievements Checked"
                or nil
        )
        return finish(true, 0, "nothing claimable")
    end

    local beforeGems =
        A.ReadValue("Gems")
        or A.ReadVisibleNumber("Gems")
        or A.ReadSlotCurrency("Gems")
    local beforeGold =
        A.ReadValue("Gold")
        or A.ReadVisibleNumber("Gold")
        or A.ReadSlotCurrency("Gold")

    local invoked = 0
    local verified = 0
    local claimedNames = {}

    for _, achievementId in ipairs(ids) do
        local currentRoot =
            A.AchievementListRoot()
        local entry =
            currentRoot
            and currentRoot:FindFirstChild(
                tostring(achievementId)
            )
        local state =
            A.AchievementEntryState(entry)

        if state == "CLAIM" then
            local achievementName =
                A.AchievementEntryName(entry)
            local okInvoke = pcall(function()
                return remote:InvokeServer(
                    "S_Achievements",
                    "Claim",
                    achievementId
                )
            end)

            if okInvoke then
                invoked += 1
                local deadline =
                    os.clock() + 1.10
                repeat
                    task.wait(
                        A.AchievementVerifyDelay
                    )
                    if A.AchievementClaimVerified(
                        achievementId
                    ) then
                        verified += 1
                        claimedNames[#claimedNames + 1] =
                            achievementName
                        break
                    end
                until os.clock() >= deadline
            end
        end

        task.wait(A.AchievementRequestDelay)
    end

    task.wait(0.16)

    local afterGems =
        A.ReadValue("Gems")
        or A.ReadVisibleNumber("Gems")
        or A.ReadSlotCurrency("Gems")
    local afterGold =
        A.ReadValue("Gold")
        or A.ReadVisibleNumber("Gold")
        or A.ReadSlotCurrency("Gold")

    local gemGain =
        beforeGems and afterGems
        and math.max(0, afterGems - beforeGems)
        or 0
    local goldGain =
        beforeGold and afterGold
        and math.max(0, afterGold - beforeGold)
        or 0

    if verified > 0 then
        local details = {
            "Claimed "
                .. tostring(verified)
                .. " achievement"
                .. (verified == 1 and "" or "s"),
        }
        if gemGain > 0 then
            details[#details + 1] =
                tostring(gemGain) .. " Gems"
        end
        if goldGain > 0 then
            details[#details + 1] =
                tostring(goldGain) .. " Gold"
        end
        if #claimedNames > 0 then
            local preview = {}
            for index = 1,
                math.min(3, #claimedNames) do
                preview[#preview + 1] =
                    claimedNames[index]
            end
            details[#details + 1] =
                table.concat(preview, ", ")
                .. (
                    #claimedNames > #preview
                    and "..."
                    or ""
                )
        end

        A.ActivityLog(
            table.concat(details, " • "),
            "success",
            "Achievements Claimed"
        )
        return finish(true, verified, "verified")
    end

    if invoked > 0 then
        A.ActivityLog(
            "Claim requests were sent, but no native CLAIM → EQUIP/claimed transition was verified.",
            "error",
            manual == true
                and "Achievement Verification Failed"
                or nil
        )
        return finish(false, 0, "not verified")
    end

    A.ActivityLog(
        "Claimable entries changed before SliceHub could send them.",
        "info",
        nil
    )
    return finish(true, 0, "state changed")
end

function A.TryClaim(pathNeedle, labelName)
    if A.Settings.AutoClaimAchievements == true then
        return A.TryClaimAchievements()
    end

    if A.Settings.AutoClaimQuests == true
        and os.clock() - (A.LastProtocolNoticeAt or 0) > 20 then
        A.LastProtocolNoticeAt = os.clock()
        A.ActivityLog(
            "Quest claiming remains protocol pending.",
            "info",
            nil
        )
    end

    return false
end

A.BoostDurations = {
    {Tag = "15m", Minutes = 15},
    {Tag = "30m", Minutes = 30},
    {Tag = "1h", Minutes = 60},
    {Tag = "2h", Minutes = 120},
}

function A.FindOwnedBoost(kind)
    local wanted = tostring(kind or "XP")

    for _, duration in ipairs(A.BoostDurations) do
        local itemName =
            "2x " .. wanted .. " Boost ["
                .. duration.Tag .. "]"
        local quantity = A.ReadOwnedItemQuantity(itemName)
        if quantity and quantity > 0 then
            return {
                Text = itemName,
                Name = itemName,
                Duration = duration.Minutes,
                Quantity = quantity,
                Source = "profile inventory",
            }
        end
    end

    -- Hidden native inventory cards are an exact fallback and do not require
    -- opening or switching the Inventory page.
    local interface = playerGui:FindFirstChild("Interface")
    local inventory = interface
        and interface:FindFirstChild("Inventory")
    local items = inventory
        and inventory:FindFirstChild("Items", true)

    if items then
        for _, duration in ipairs(A.BoostDurations) do
            local itemName =
                "2x " .. wanted .. " Boost ["
                    .. duration.Tag .. "]"
            for _, object in ipairs(items:GetDescendants()) do
                local value = object:GetAttribute("Item")
                if value == itemName then
                    local root = A.NativeItemRoot(object)
                    local quantity = 1
                    local quantityObject =
                        root and root:FindFirstChild(
                            "Quantity",
                            true
                        )
                    if quantityObject
                        and quantityObject:IsA("TextLabel") then
                        quantity =
                            tonumber(quantityObject.Text)
                            or quantity
                    end
                    return {
                        Object = root or object,
                        Text = itemName,
                        Name = itemName,
                        Duration = duration.Minutes,
                        Quantity = quantity,
                        Source = "hidden native inventory",
                    }
                end
            end
        end
    end

    return nil
end

function A.TryUseBoost(kind)
    if A.ReadBoost(kind) > 0 then return false end

    local candidate = A.FindOwnedBoost(kind)
    if not candidate then return false end

    local remote = A.Remote()
    if not remote then return false end

    local beforeBoost = A.ReadBoost(kind)
    local beforeQuantity =
        A.ReadOwnedItemQuantity(candidate.Name)
        or tonumber(candidate.Quantity)
        or 0

    local ok, response = pcall(function()
        return remote:InvokeServer(
            "S_Inventory",
            "Item",
            candidate.Name
        )
    end)
    if not ok then return false end

    A.CacheResponse(response)

    local responseSlot = A.ResolveSlotTable(response)
    local responseItems =
        responseSlot
        and responseSlot.Inventory
        and responseSlot.Inventory.Items
    local responseQuantity =
        type(responseItems) == "table"
        and (tonumber(responseItems[candidate.Name]) or 0)
        or nil

    local deadline = os.clock() + 2.2
    repeat
        task.wait(0.08)
        local afterBoost = A.ReadBoost(kind)
        local timerStarted = afterBoost > beforeBoost
        local itemConsumed =
            responseQuantity ~= nil
            and responseQuantity < beforeQuantity

        if timerStarted or itemConsumed then
            A.ActivityLog(
                "Activated " .. candidate.Name,
                "success",
                "Boost Activated"
            )
            return true
        end
    until os.clock() >= deadline

    return false
end

A.BoostPrices = {
    ["30m"] = 4499,
    ["1h"] = 7999,
    ["2h"] = 13999,
}

function A.ExactBoostName()
    return "2x " .. tostring(A.Settings.BoostPurchaseType or "XP")
        .. " Boost [" .. tostring(A.Settings.BoostPurchaseDuration or "30m") .. "]"
end

function A.TryBuyBoost()
    if A.SessionPurchases >= A.Settings.MaxPurchasesPerSession then return false end
    local product = A.ExactBoostName()
    local price = A.BoostPrices[A.Settings.BoostPurchaseDuration]
    if not price then return false end

    local gems = A.ReadValue("Gems") or A.ReadVisibleNumber("Gems")
    if gems and gems - price < A.Settings.GemReserve then return false end

    -- V9.8.4: guarded purchase beta never changes native pages.
    -- It may act only when the exact product is already visible in Market.
    local productText = A.FindText(product, "market", true)
    if not productText then return false end
    A.Activate(A.CardRoot(productText) or productText)
    task.wait(0.16)

    local prompt = playerGui:FindFirstChild("Interface")
    prompt = prompt and prompt:FindFirstChild("Buying")
    prompt = prompt and prompt:FindFirstChild("Prompt")
    local main = prompt and prompt:FindFirstChild("Main")
    if not main or not main.Visible then return false end

    local titleMatches = false
    for _, object in ipairs(main:GetDescendants()) do
        if (object:IsA("TextLabel") or object:IsA("TextButton"))
            and string.find(A.Lower(object.Text), A.Lower(product), 1, true) then
            titleMatches = true
            break
        end
    end
    if not titleMatches then return false end

    local yes = prompt:FindFirstChild("Yes_Buy", true)
        or A.FindActionButton({"buy", "yes"}, "buying.prompt")
    if not yes then return false end
    local beforeGems = gems
    A.Activate(yes)

    local deadline = os.clock() + 2.0
    repeat
        task.wait(0.10)
        local afterGems = A.ReadValue("Gems") or A.ReadVisibleNumber("Gems")
        if beforeGems and afterGems and afterGems < beforeGems then
            A.SessionPurchases += 1
            A.ActivityLog("Bought " .. product, "success", "Bought")
            return true
        end
    until os.clock() >= deadline
    return false
end

function A.ReadAttributeUp(object, names)
    local wanted = {}
    for _, name in ipairs(names or {}) do
        wanted[A.Lower(name)] = true
    end

    local node = object
    for _ = 1, 10 do
        if not node then break end
        for key, value in pairs(node:GetAttributes()) do
            if wanted[A.Lower(key)] then
                return value, node, key
            end
        end
        node = node.Parent
    end
    return nil, nil, nil
end

function A.NativeItemRoot(object)
    local node = object
    local fallback = A.CardRoot(object) or object
    for _ = 1, 10 do
        if not node or node == playerGui then break end
        if node:IsA("GuiObject") then
            local itemValue = node:GetAttribute("Item")
                or node:GetAttribute("ItemName")
                or node:GetAttribute("PerkName")
                or node:GetAttribute("ArtifactName")
            local rarityValue = node:GetAttribute("Rarity")
            if itemValue ~= nil or rarityValue ~= nil then
                return node
            end
            if string.find(tostring(node.Name), " - ", 1, true)
                and node.AbsoluteSize.X >= 35
                and node.AbsoluteSize.Y >= 25 then
                fallback = node
            end
        end
        node = node.Parent
    end
    return fallback
end

function A.InferCategory(object, texts, name)
    local path = A.Lower(A.Path(object))
    local joined = A.Lower(table.concat(texts or {}, " "))
    local rawCategory = A.ReadAttributeUp(
        object,
        {"Category", "ItemType", "Type", "Class", "Section"}
    )
    local categoryText = A.Lower(rawCategory)
    local combined = path .. " " .. joined .. " " .. categoryText

    if string.find(combined, "perk", 1, true) then
        return "Perk"
    end
    if string.find(combined, "artifact", 1, true) then
        return "Artifact"
    end
    if string.find(combined, "serum", 1, true)
        or string.find(A.Lower(name), "serum", 1, true) then
        return "Serum"
    end
    if name and A.RaidDropWhitelist[name] then
        return "RaidDrop"
    end
    return nil
end

function A.ExactItemName(object, texts)
    local value = A.ReadAttributeUp(
        object,
        {"Item", "ItemName", "DisplayName", "PerkName", "ArtifactName", "Tag"}
    )
    if type(value) == "string" and #A.Clean(value) >= 3 then
        return A.Clean(value)
    end
    return A.InferItemName(object, texts)
end

function A.InferRarity(object, texts)
    local allowed = {Common=true, Rare=true, Epic=true, Legendary=true, Mythic=true}
    local node = object
    for _ = 1, 7 do
        if not node then break end
        for key, value in pairs(node:GetAttributes()) do
            if A.Lower(key) == "rarity" then
                local normalized = A.Clean(value)
                normalized = string.upper(string.sub(normalized,1,1)) .. string.lower(string.sub(normalized,2))
                if allowed[normalized] then return normalized end
            end
        end
        node = node.Parent
    end
    for _, textValue in ipairs(texts) do
        for rarity in pairs(allowed) do
            if A.Lower(textValue) == string.lower(rarity)
                or string.find(A.Lower(textValue), string.lower(rarity), 1, true) then
                return rarity
            end
        end
    end
    return "Unknown"
end

function A.InferProtection(object, texts)
    local output = {Locked=false, Favorited=false, Equipped=false, Paid=false, Limited=false, Leaderboard=false}
    local combined = A.Lower(table.concat(texts, " "))
    local node = object
    for _ = 1, 8 do
        if not node then break end
        combined = combined .. " " .. A.Lower(node.Name)
        for key, value in pairs(node:GetAttributes()) do
            local lowerKey = A.Lower(key)
            if value == true then
                if string.find(lowerKey, "lock", 1, true) then output.Locked = true end
                if string.find(lowerKey, "favor", 1, true) then output.Favorited = true end
                if string.find(lowerKey, "equip", 1, true) then output.Equipped = true end
                if string.find(lowerKey, "paid", 1, true) then output.Paid = true end
                if string.find(lowerKey, "limited", 1, true) then output.Limited = true end
                if string.find(lowerKey, "leader", 1, true) then output.Leaderboard = true end
            end
        end
        node = node.Parent
    end
    if string.find(combined, "locked", 1, true) then output.Locked = true end
    if string.find(combined, "favorite", 1, true) or string.find(combined, "favourite", 1, true) then output.Favorited = true end
    if string.find(combined, "equipped", 1, true) then output.Equipped = true end
    if string.find(combined, "limited", 1, true) then output.Limited = true end
    if string.find(combined, "leaderboard", 1, true) then output.Leaderboard = true end
    return output
end

function A.Protected(protection)
    for _, key in ipairs({"Locked","Favorited","Equipped","Paid","Limited","Leaderboard"}) do
        if protection and protection[key] == true then return true end
    end
    return false
end

function A.InferItemName(object, texts)
    local generic = {
        ["select"]=true,["sell"]=true,["delete"]=true,["equip"]=true,
        ["unequip"]=true,["perks"]=true,["artifacts"]=true,["inventory"]=true,
        ["quantity."]=true,["+"]=true,["-"]=true,["close"]=true,
    }
    local node = object
    for _ = 1, 7 do
        if not node then break end
        for _, key in ipairs({"ItemName","DisplayName","PerkName","ArtifactName","Tag"}) do
            local value = node:GetAttribute(key)
            if type(value) == "string" and #A.Clean(value) >= 3 then return A.Clean(value) end
        end
        node = node.Parent
    end
    for _, textValue in ipairs(texts) do
        local clean = A.Clean(textValue)
        local lower = A.Lower(clean)
        local stripped = string.gsub(clean, "%s*%([xX]%d+%)%s*$", "")
        stripped = string.gsub(stripped, "%s*[xX]%d+%s*$", "")
        if #stripped >= 3 and #stripped <= 64 and not generic[lower]
            and not string.match(lower, "^perks:%s*%d")
            and not string.match(lower, "^artifacts:%s*%d")
            and not string.match(lower, "^%d+[%d,]*$") then
            return stripped
        end
    end
    return nil
end

function A.InferQuantity(texts)
    for _, textValue in ipairs(texts) do
        local number = string.match(textValue, "[%(%[]?[xX](%d+)[%]%) ]?")
        if number then return tonumber(number) end
    end
    return 1
end


function A.AddProfilePerks(discovered)
    local _, slot = A.CurrentProfile()
    local perks = slot and slot.Perks
    local storage = type(perks) == "table"
        and perks.Storage
        or nil
    if type(storage) ~= "table" then return 0 end

    local equipped = {}
    if type(perks.Equipped) == "table" then
        for _, id in pairs(perks.Equipped) do
            if type(id) == "string" and id ~= "" then
                equipped[id] = true
            end
        end
    end

    local groups = {}
    for id, data in pairs(storage) do
        if type(id) == "string"
            and type(data) == "table"
            and type(data.Name) == "string" then
            local name = A.Clean(data.Name)
            local group = groups[name]
            if not group then
                group = {
                    Name = name,
                    IDs = {},
                    EquippedCount = 0,
                    TotalCount = 0,
                }
                groups[name] = group
            end
            group.TotalCount += 1
            if equipped[id] then
                group.EquippedCount += 1
            else
                group.IDs[#group.IDs + 1] = id
            end
        end
    end

    local added = 0
    for name, group in pairs(groups) do
        local rarity = A.ResolvePerkRarity(name)
        local key = "Perk:" .. name
        local existing = discovered[key]
        local existingRarity =
            existing and existing.Rarity
            or nil
        rarity = rarity or existingRarity or "Unknown"

        if #group.IDs > 0 then
            discovered[key] = {
                Key = key,
                Name = name,
                Category = "Perk",
                Rarity = rarity,
                Quantity = #group.IDs,
                IDs = group.IDs,
                EquippedCount = group.EquippedCount,
                TotalCount = group.TotalCount,
                Protection = {
                    Locked = false,
                    Favorited = false,
                    Equipped = false,
                    Paid = false,
                    Limited = false,
                    Leaderboard = false,
                },
                Object = existing and existing.Object or nil,
                Path = existing and existing.Path
                    or "Profile.Perks.Storage",
                Source = "live profile",
            }
            added += 1
        end
    end

    return added
end

function A.ScanCatalog(silent)
    local discovered = {}
    local interface = playerGui:FindFirstChild("Interface")
    if not interface then return 0 end

    local visited = {}
    for _, object in ipairs(interface:GetDescendants()) do
        if not object:IsA("GuiObject") then continue end
        local path = A.Lower(A.Path(object))
        if not (
            string.find(path, "equipment", 1, true)
            or string.find(path, "inventory.main.holder.items", 1, true)
            or string.find(path, "inventory", 1, true)
        ) then
            continue
        end

        local root = A.NativeItemRoot(object)
        if not root or visited[root] then continue end
        visited[root] = true

        local texts = A.NearbyTexts(root)
        local name = A.ExactItemName(root, texts)
        if not name or name == "Unknown" then continue end

        local category = A.InferCategory(root, texts, name)
        if not category then continue end

        local rarity = A.InferRarity(root, texts)
        local protection = A.InferProtection(root, texts)
        local quantity = A.InferQuantity(texts)
        local rawQuantity = A.ReadAttributeUp(
            root,
            {"Quantity", "Amount", "Count", "Stack"}
        )
        if tonumber(rawQuantity) then
            quantity = math.max(1, math.floor(tonumber(rawQuantity)))
        end

        local key = category .. ":" .. name
        local existing = discovered[key]
        if not existing or A.Visible(root) then
            discovered[key] = {
                Key = key,
                Name = name,
                Category = category,
                Rarity = rarity,
                Quantity = quantity,
                Protection = protection,
                Object = root,
                Path = A.Path(root),
            }
        end
    end

    -- Merge server-authoritative profile perks so remote perk selling never
    -- depends on opening Equipment or Inventory.
    A.AddProfilePerks(discovered)

    -- Replace live objects instead of retaining stale page references.
    A.Catalog = discovered
    A.LastCatalogScanAt = os.clock()
    local count = 0
    for _ in pairs(discovered) do count += 1 end

    if not silent then
        A.ActivityLog(
            "Native item scan found " .. tostring(count) .. " exact candidates.",
            "success",
            "Inventory Scan"
        )
    end
    if A.RefreshCatalogUI then A.RefreshCatalogUI() end
    return count
end

function A.FindLiveEquipmentItem(item)
    local interface = playerGui:FindFirstChild("Interface")
    local equipment = interface and interface:FindFirstChild("Equipment")
    if not equipment then return nil end

    local visited = {}
    for _, object in ipairs(equipment:GetDescendants()) do
        if not object:IsA("GuiObject") or not A.Visible(object) then continue end
        local root = A.NativeItemRoot(object)
        if not root or visited[root] then continue end
        visited[root] = true

        local texts = A.NearbyTexts(root)
        local name = A.ExactItemName(root, texts)
        local rarity = A.InferRarity(root, texts)
        local category = A.InferCategory(root, texts, name)
        if category == item.Category
            and name == item.Name
            and (item.Rarity == "Unknown" or rarity == item.Rarity) then
            return root
        end
    end
    return nil
end

function A.NativeAutoSellConflict(category)
    local profile = A.CurrentProfile()
    local categoryKey =
        category == "Perk" and "Perks"
        or category == "Artifact" and "Artifacts"
        or nil
    local profileSettings =
        type(profile) == "table"
        and type(profile.Auto_Sell) == "table"
        and categoryKey
        and profile.Auto_Sell[categoryKey]
        or nil
    local raritySettings =
        category == "Perk"
            and A.Settings.PerkRarities
        or category == "Artifact"
            and A.Settings.ArtifactRarities
        or {}

    if type(profileSettings) == "table" then
        for rarity, enabled in pairs(raritySettings) do
            if enabled == true
                and profileSettings[rarity] == true then
                return true, rarity
            end
        end
    end

    local interface = playerGui:FindFirstChild("Interface")
    local autoSell = interface and interface:FindFirstChild("Auto_Sell")
    local prompt = autoSell and autoSell:FindFirstChild("Prompt")
    local main = prompt and prompt:FindFirstChild("Main")
    local sectionName = category == "Perk" and "Perks" or category == "Artifact" and "Artifacts" or nil
    local section = sectionName and main and main:FindFirstChild(sectionName)
    if not section then return false end

    for rarity, enabled in pairs(raritySettings) do
        if enabled then
            local row = section:FindFirstChild(rarity)
            local buttons = row and row:FindFirstChild("Buttons")
            local on = buttons and buttons:FindFirstChild("On")
            local off = buttons and buttons:FindFirstChild("Off")
            if on and off and on:IsA("GuiObject") and off:IsA("GuiObject") then
                local onSelected = false
                pcall(function()
                    onSelected = on.BackgroundTransparency + 0.08 < off.BackgroundTransparency
                        or on.TextTransparency + 0.08 < off.TextTransparency
                        or (
                            math.abs(on.BackgroundColor3.R - off.BackgroundColor3.R)
                            + math.abs(on.BackgroundColor3.G - off.BackgroundColor3.G)
                            + math.abs(on.BackgroundColor3.B - off.BackgroundColor3.B)
                        ) > 0.18 and on.BackgroundTransparency < 0.75
                end)
                if onSelected then return true, rarity end
            end
        end
    end
    return false
end

function A.ItemEligible(item)
    if not item or item.Rarity == "Unknown" or A.Protected(item.Protection) then return false end
    if A.Settings.SelectedItems[item.Key] ~= true then return false end
    if item.Rarity == "Mythic" and A.Settings.ConfirmMythic ~= true then return false end

    if item.Category == "Perk" then
        if A.Settings.AutoSellPerks ~= true or A.Settings.PerkRarities[item.Rarity] ~= true then return false end
        local conflict = A.NativeAutoSellConflict("Perk")
        if conflict then return false, "Native Perk Auto Sell overlaps " .. tostring(item.Rarity) end
    elseif item.Category == "Artifact" then
        if A.Settings.AutoSellArtifacts ~= true or A.Settings.ArtifactRarities[item.Rarity] ~= true then return false end
        local conflict = A.NativeAutoSellConflict("Artifact")
        if conflict then return false, "Native Artifact Auto Sell overlaps " .. tostring(item.Rarity) end
    elseif item.Category == "Serum" then
        if A.Settings.AutoSellSerums ~= true or item.Quantity <= A.Settings.SerumKeepAtLeast then return false end
    elseif item.Category == "RaidDrop" then
        if A.Settings.AutoSellRaidDrops ~= true or not A.RaidDropWhitelist[item.Name]
            or item.Quantity <= A.Settings.RaidDropKeepAtLeast then return false end
    else
        return false
    end
    return true
end

function A.ReadCategoryCount(category)
    local needle = category == "Perk" and "perks:" or category == "Artifact" and "artifacts:" or nil
    if not needle then return nil end
    for _, object in ipairs(playerGui:GetDescendants()) do
        if (object:IsA("TextLabel") or object:IsA("TextButton")) and A.Visible(object) then
            local lower = A.Lower(object.Text)
            if string.find(lower, needle, 1, true) then
                local n = string.match(lower, needle .. "%s*(%d[%d,]*)")
                if n then return tonumber((string.gsub(n, ",", ""))) end
            end
        end
    end
    return nil
end

function A.ConfirmWarning()
    local interface = playerGui:FindFirstChild("Interface")
    local warning = interface and interface:FindFirstChild("Warning")
    local prompt = warning and warning:FindFirstChild("Prompt")
    local main = prompt and prompt:FindFirstChild("Main")
    if not main or not main.Visible then return false end
    local yes = main:FindFirstChild("Yes", true)
        or main:FindFirstChild("Yes_1", true)
        or A.FindActionButton({"yes", "confirm"}, "warning.prompt")
    return yes and A.Activate(yes) or false
end


function A.BuildPerkDeleteBatch()
    if A.Settings.AutoSellPerks ~= true then
        return {}, {}
    end

    local conflict, rarity =
        A.NativeAutoSellConflict("Perk")
    if conflict then
        return {}, {
            Error =
                "Native Perk Auto Sell overlaps "
                .. tostring(rarity),
        }
    end

    if os.clock() - A.LastCatalogScanAt > 3 then
        A.ScanCatalog(true)
    end

    local ids = {}
    local names = {}
    local seen = {}

    local keys = {}
    for key in pairs(A.Catalog) do
        keys[#keys + 1] = key
    end
    table.sort(keys)

    for _, key in ipairs(keys) do
        local item = A.Catalog[key]
        if item
            and item.Category == "Perk"
            and A.Settings.SelectedItems[item.Key] == true
            and item.Rarity ~= "Unknown"
            and A.Settings.PerkRarities[item.Rarity] == true
            and (
                item.Rarity ~= "Mythic"
                or A.Settings.ConfirmMythic == true
            )
            and type(item.IDs) == "table" then

            for _, id in ipairs(item.IDs) do
                if type(id) == "string"
                    and id ~= ""
                    and not seen[id] then
                    seen[id] = true
                    ids[#ids + 1] = id
                    names[item.Name] =
                        (names[item.Name] or 0) + 1
                    if #ids >= A.MaxPerkBatch then
                        return ids, names
                    end
                end
            end
        end
    end

    return ids, names
end

function A.TrySellPerkBatch()
    local ids, names = A.BuildPerkDeleteBatch()
    if type(names) == "table" and names.Error then
        if os.clock() - (A.LastConflictToastAt or 0) > 8 then
            A.LastConflictToastAt = os.clock()
            A.ActivityLog(
                names.Error
                    .. ". Turn the game's native Auto Sell off.",
                "error",
                "Automation Paused"
            )
        end
        return false
    end
    if #ids == 0 then return false end

    local remote = A.Remote()
    if not remote then return false end

    local expected = {}
    for _, id in ipairs(ids) do expected[id] = true end

    local ok, response = pcall(function()
        return remote:InvokeServer(
            "S_Equipment",
            "Delete",
            "Perk",
            ids
        )
    end)
    if not ok then return false end

    A.CacheResponse(response)

    local function removedCount(slot)
        local perks = slot and slot.Perks
        local storage = type(perks) == "table"
            and perks.Storage
            or nil
        if type(storage) ~= "table" then return 0 end

        local removed = 0
        for id in pairs(expected) do
            if storage[id] == nil then
                removed += 1
            end
        end
        return removed
    end

    local removed = removedCount(
        A.ResolveSlotTable(response)
    )
    local deadline = os.clock() + 2.2
    while removed <= 0 and os.clock() < deadline do
        task.wait(0.10)
        local _, slot = A.CurrentProfile()
        removed = removedCount(slot)
    end

    if removed <= 0 then return false end

    local summary = {}
    for name, count in pairs(names) do
        summary[#summary + 1] =
            tostring(name) .. " x" .. tostring(count)
    end
    table.sort(summary)

    A.ActivityLog(
        "Sold "
            .. tostring(removed)
            .. " perk"
            .. (removed == 1 and "" or "s")
            .. " in one verified batch"
            .. (
                removed == #ids and #summary > 0
                and ": " .. table.concat(summary, ", ")
                or ""
            ),
        "success",
        "Perks Sold"
    )

    A.ScanCatalog(true)
    return true
end

function A.TrySellEquipmentItem(item)
    -- V9.8.4: no page navigation and no stale Inventory-card click.
    -- Re-resolve the exact Perk/Artifact card from the visible Equipment page.
    local liveItem = A.FindLiveEquipmentItem(item)
    if not liveItem then return false end

    local before = A.ReadCategoryCount(item.Category)
    local originalParent = liveItem.Parent
    if not A.Activate(liveItem) then return false end
    task.wait(0.16)

    local interface = playerGui:FindFirstChild("Interface")
    local equipment = interface and interface:FindFirstChild("Equipment")
    local delete = equipment and equipment:FindFirstChild("Delete_1", true)
    if not delete then
        local deleteRoot = equipment and equipment:FindFirstChild("Delete")
        delete = deleteRoot and A.FindActionButton(
            {"delete", "sell"},
            "equipment.delete"
        )
    end
    if not delete or not A.Visible(delete) or not A.Activate(delete) then
        return false
    end

    task.wait(0.12)
    if not A.ConfirmWarning() then return false end

    local deadline = os.clock() + 2.2
    repeat
        task.wait(0.10)
        local after = A.ReadCategoryCount(item.Category)
        if before and after and after < before then
            A.ActivityLog(
                "Sold " .. item.Category .. ": " .. item.Name
                    .. " [" .. item.Rarity .. "]",
                "success",
                "Sold"
            )
            A.Catalog[item.Key] = nil
            return true
        end

        if not liveItem.Parent
            or liveItem.Parent ~= originalParent
            or not A.Visible(liveItem) then
            A.ActivityLog(
                "Sold " .. item.Category .. ": " .. item.Name
                    .. " [" .. item.Rarity .. "]",
                "success",
                "Sold"
            )
            A.Catalog[item.Key] = nil
            return true
        end
    until os.clock() >= deadline

    return false
end

function A.TrySellInventoryItem(item)
    if not item.Object or not item.Object.Parent or not A.Visible(item.Object) then
        return false
    end
    local beforeQuantity = item.Quantity
    A.Activate(item.Object)
    task.wait(0.15)
    local sell = A.FindActionButton({"sell"}, "inventory")
    if not sell or not A.Activate(sell) then return false end
    task.wait(0.12)

    local interface = playerGui:FindFirstChild("Interface")
    local buying = interface and interface:FindFirstChild("Buying")
    local prompt = buying and buying:FindFirstChild("Prompt")
    local main = prompt and prompt:FindFirstChild("Main")
    if not main or not main.Visible then return false end

    local quantity = main:FindFirstChild("Interact", true)
    if quantity and quantity:IsA("TextBox") then
        quantity.Text = "1"
        pcall(function() quantity:ReleaseFocus() end)
    end
    local yes = prompt:FindFirstChild("Yes_Buy", true)
        or A.FindActionButton({"sell", "yes"}, "buying.prompt")
    if not yes or not A.Activate(yes) then return false end

    task.wait(0.65)
    A.ScanCatalog(true)
    local refreshed = A.Catalog[item.Key]
    if not refreshed or (tonumber(refreshed.Quantity) or 0) < beforeQuantity then
        A.ActivityLog("Sold " .. item.Category .. ": " .. item.Name, "success", "Sold")
        return true
    end
    return false
end

function A.TrySellOne()
    if A.Settings.AutoSellPerks == true
        and A.TrySellPerkBatch() then
        return true
    end

    if os.clock() - A.LastCatalogScanAt > 15 then A.ScanCatalog(true) end
    local keys = {}
    for key in pairs(A.Catalog) do keys[#keys + 1] = key end
    table.sort(keys)
    for _, key in ipairs(keys) do
        local item = A.Catalog[key]
        local eligible, reason = A.ItemEligible(item)
        if eligible then
            A.LastSellAt = os.clock()
            if item.Category == "Artifact" then
                return A.TrySellEquipmentItem(item)
            elseif item.Category == "Perk" then
                continue
            end
            return A.TrySellInventoryItem(item)
        elseif reason and os.clock() - (A.LastConflictToastAt or 0) > 8 then
            A.LastConflictToastAt = os.clock()
            A.ActivityLog(reason .. ". Turn the game's native Auto Sell off for that category.", "error", "Automation Paused")
        end
    end
    return false
end

function A.RunWorker()
    if A.Busy or A.Settings.Enabled ~= true then return end
    A.Busy = true
    local ok, err = xpcall(function()
        local now = os.clock()

        local lastAchievementUnix =
            tonumber(A.Settings.LastAchievementSweepUnix) or 0
        if A.Settings.AutoClaimAchievements == true
            and now - (A.LastAchievementSweepAt or 0)
                >= A.AchievementRetryCooldown
            and (
                lastAchievementUnix <= 0
                or os.time() - lastAchievementUnix
                    >= A.AchievementSweepCooldown
            ) then
            A.LastAchievementSweepAt = now
            local completed =
                A.TryClaimAchievements(false)
            if completed == true then
                A.Settings.LastAchievementSweepUnix =
                    os.time()
                A.Save()
            end
        elseif A.Settings.AutoClaimQuests == true
            and now - A.LastClaimSweepAt > 20 then
            A.LastClaimSweepAt = now
            A.TryClaim(nil, "Quest")
        end

        if A.Settings.AutoUseBoosts and now - A.LastBoostAt > 8.0 then
            A.LastBoostAt = now
            if A.Settings.UseXPBoosts and A.TryUseBoost("XP") then return end
            if A.Settings.UseGoldBoosts and A.TryUseBoost("Gold") then return end
            if A.Settings.UseLuckBoosts and A.TryUseBoost("Luck") then return end
        end

        if A.Settings.AutoBuyBoosts and now - A.LastPurchaseAt > 12.0 then
            A.LastPurchaseAt = now
            if A.TryBuyBoost() then return end
        end

        if (A.Settings.AutoSellPerks or A.Settings.AutoSellSerums
            or A.Settings.AutoSellArtifacts or A.Settings.AutoSellRaidDrops)
            and now - A.LastSellAt > 1.1 then
            A.TrySellOne()
        end
    end, debug.traceback)
    A.Busy = false
    if not ok then
        A.LastError = tostring(err)
    end
end

A.Load()
if A.Settings.Remote222Migrated ~= true then
    A.Settings.AutoClaimAchievements = true
    A.Settings.Remote222Migrated = true
end
A.Settings.AutoClaimQuests = false
A.Save()

local automationPage = PageFrames["Lobby Automation"]
local automationScroll = Instance.new("ScrollingFrame")
automationScroll.Size = UDim2.fromScale(1, 1)
automationScroll.BackgroundTransparency = 1
automationScroll.BorderSizePixel = 0
automationScroll.ScrollBarThickness = 5
automationScroll.ScrollBarImageColor3 = Theme.Accent
automationScroll.CanvasSize = UDim2.fromOffset(0, 1840)
