function A.MakeCard(order, height, heading, body)
    local card = Instance.new("Frame")
    card.LayoutOrder = order
    card.Size = UDim2.new(1, 0, 0, height)
    card.BackgroundColor3 = Theme.Panel
    card.BorderSizePixel = 0
    card.Parent = automationScroll
    corner(card, 6); stroke(card, Theme.Stroke, 0.42)
    local title = label(card, heading, UDim2.fromOffset(12, 9), UDim2.new(1,-24,0,20), true)
    local description = label(card, "", UDim2.fromOffset(12, 31), UDim2.new(1,-24,0,32), false)
    description.TextSize = 9
    description.Visible = false
    return card, title, description
end

function A.ToggleButton(parent, textValue, key, position, size, nested)
    local b = button(parent, "", position, size, Theme.Card)
    local function read()
        if nested then
            A.Settings[nested] = type(A.Settings[nested]) == "table" and A.Settings[nested] or {}
            return A.Settings[nested][key] == true
        end
        return A.Settings[key] == true
    end
    local function write(value)
        if nested then A.Settings[nested][key] = value else A.Settings[key] = value end
    end
    local function refresh()
        local enabled = read()
        b.Text = textValue .. ": " .. (enabled and "ON" or "OFF")
        b.BackgroundColor3 = enabled and Theme.Accent or Theme.Card
    end
    b.Activated:Connect(function()
        local nextValue = not read()
        if key == "Mythic" and nextValue and A.Settings.ConfirmMythic ~= true then
            A.ActivityLog("Enable MYTHIC CONFIRMATION before selecting Mythic selling.", "error", "Automation Paused")
            return
        end
        write(nextValue)
        A.Save()
        refresh()
    end)
    refresh()
    return b, refresh
end

