function A.RefreshCatalogUI()
    for _, child in ipairs(catalogScroll:GetChildren()) do
        if child:IsA("GuiButton") then child:Destroy() end
    end
    local query = A.Lower(searchBox.Text)
    local keys = {}
    for key, item in pairs(A.Catalog) do
        local hay = A.Lower(item.Category .. " " .. item.Rarity .. " " .. item.Name)
        if query == "" or string.find(hay, query, 1, true) then keys[#keys+1]=key end
    end
    table.sort(keys)
    local shown = 0
    for _, key in ipairs(keys) do
        if shown >= 60 then break end
        shown += 1
        local item = A.Catalog[key]
        local selected = A.Settings.SelectedItems[key] == true
        local protected = A.Protected(item.Protection)
        local row = button(catalogScroll,
            (selected and "✓ " or "○ ") .. item.Category .. " • " .. item.Rarity .. " • " .. item.Name
                .. (protected and " • PROTECTED" or ""),
            UDim2.new(), UDim2.new(1,-4,0,30), selected and Theme.Accent or Theme.Card)
        row.LayoutOrder = shown
        row.TextXAlignment = Enum.TextXAlignment.Left
        row.Activated:Connect(function()
            if protected or item.Rarity == "Unknown" then
                A.ActivityLog("That item is protected or has Unknown rarity.", "error", "Automation Paused")
                return
            end
            if item.Rarity == "Mythic" and A.Settings.ConfirmMythic ~= true then
                A.ActivityLog("Enable MYTHIC CONFIRMATION before selecting it.", "error", "Automation Paused")
                return
            end
            A.Settings.SelectedItems[key] = not selected
            A.Save();A.RefreshCatalogUI()
        end)
    end
    catalogScroll.CanvasSize = UDim2.fromOffset(0, math.max(0, shown*34))
end
searchBox:GetPropertyChangedSignal("Text"):Connect(function() A.RefreshCatalogUI() end)
commonRare.Activated:Connect(function()
    for key,item in pairs(A.Catalog) do
        if (item.Rarity=="Common" or item.Rarity=="Rare") and not A.Protected(item.Protection) then
            A.Settings.SelectedItems[key]=true
        end
    end
    A.Save();A.RefreshCatalogUI()
end)
clearSelected.Activated:Connect(function() A.Settings.SelectedItems={};A.Save();A.RefreshCatalogUI() end)

