function A.RefreshUI()
    local refreshers = {
        A.UI.RefreshMaster,A.UI.RefreshClaimAchievements,A.UI.RefreshClaimQuests,
        A.UI.RefreshUseBoosts,A.UI.RefreshUseXP,A.UI.RefreshUseGold,A.UI.RefreshUseLuck,
        A.UI.RefreshBuyBoosts,A.UI.RefreshBuySpins,A.UI.RefreshSellPerks,
        A.UI.RefreshSellArtifacts,A.UI.RefreshSellSerums,A.UI.RefreshSellDrops,
        A.UI.RefreshConfirmMythic,A.UI.RefreshActivityToasts,
    }
    for _, refresh in ipairs(refreshers) do if refresh then refresh() end end
    for _, refresh in ipairs(rarityRefreshers) do refresh() end
    refreshPurchaseButtons();refreshKeepButtons()
    local lines = {}
    for index=1,math.min(10,#A.Activity) do
        local entry=A.Activity[index]
        lines[#lines+1]=entry.Time .. " • " .. entry.Message
    end
    activityText.Text = #lines>0 and table.concat(lines,"\n") or "No verified actions yet."
end
A.RefreshCatalogUI();A.RefreshUI()

