---------------------------------------------------------------------
-- V9.8.4 • SHARED OPTIMIZATION
-- Lobby and Main Menu edit the same mission settings document, so the exact
-- choices carry into missions without maintaining a second profile.
---------------------------------------------------------------------
;(function()
local O = V98320SharedOptimization or {}
V98320SharedOptimization = O
O.FileName = "TitanControlSettings_v101.json"
O.Defaults = {
    OptimizationPreset="Default",
    PerformanceModeEnabled=false,
    DisableEffectsEnabled=false,
    EcoLoopModeEnabled=false,
    MapPropsHiddenEnabled=false,
    RemoveInjuryKillFlashEnabled=false,
    RemoveDamageTextEnabled=false,
    CleanupDeadTitansEnabled=false,
    RemoveFogEnabled=false,
    DisablePostProcessingEnabled=false,
    Disable3DRenderingEnabled=false,
    SimpleLightingEnabled=false,
    LowDetailMapMaterialsEnabled=false,
    SleepUIWhenHiddenEnabled=false,
    DisableCameraEffectsEnabled=false,
    FPSCap=60,
}
O.Values = O.Values or {}
O.Original = O.Original or {Effects=setmetatable({}, {__mode="k"}), Parts=setmetatable({}, {__mode="k"}), Post=setmetatable({}, {__mode="k"})}

function O.Copy(value)
    if type(value)~="table" then return value end
    local output={};for key,child in pairs(value) do output[key]=O.Copy(child) end;return output
end
function O.Load()
    O.Document={}
    if readfileFn then
        local ok,raw=pcall(readfileFn,O.FileName)
        if ok and type(raw)=="string" and raw~="" then
            local ok2,doc=pcall(function() return HttpService:JSONDecode(raw) end)
            if ok2 and type(doc)=="table" then O.Document=doc end
        end
    elseif type(Env.TitanControlPersistentSettings)=="table" then O.Document=Env.TitanControlPersistentSettings end
    local toggles=type(O.Document.Toggles)=="table" and O.Document.Toggles or {}
    O.Values=O.Copy(O.Defaults)
    for key,value in pairs(toggles) do if O.Values[key]~=nil then O.Values[key]=value end end
    O.Values.FPSCap=math.clamp(math.floor((tonumber(O.Values.FPSCap) or 60)+0.5),30,999)
end
function O.Save()
    O.Document=type(O.Document)=="table" and O.Document or {}
    O.Document.Toggles=type(O.Document.Toggles)=="table" and O.Document.Toggles or {}
    for key,value in pairs(O.Values) do O.Document.Toggles[key]=value end
    Env.TitanControlPersistentSettings=O.Document
    if not writefileFn then return true end
    local ok,encoded=pcall(function() return HttpService:JSONEncode(O.Document) end)
    if not ok then return false end
    return pcall(writefileFn,O.FileName,encoded)
end

function O.ProtectedPart(part)
    local text=A and A.Lower(A.Path(part)) or string.lower(part:GetFullName())
    for _,word in ipairs({"objective","titan","boss","cannon","refill","gas","station","interact","prompt","wave","cutscene","eren","player","character","spawn","mission"}) do
        if string.find(text,word,1,true) then return true end
    end
    return false
end

function O.Apply()
    local Lighting=game:GetService("Lighting")
    local WorkspaceService=game:GetService("Workspace")
    local v=O.Values
    pcall(function()
        local cap=v.FPSCap==999 and 999 or v.FPSCap
        if type(setfpscap)=="function" then setfpscap(cap) end
    end)
    pcall(function() game:GetService("RunService"):Set3dRenderingEnabled(v.Disable3DRenderingEnabled~=true) end)

    if O.Original.GlobalShadows==nil then O.Original.GlobalShadows=Lighting.GlobalShadows end
    if O.Original.FogEnd==nil then O.Original.FogEnd=Lighting.FogEnd;O.Original.FogStart=Lighting.FogStart end
    Lighting.GlobalShadows = not (v.PerformanceModeEnabled or v.SimpleLightingEnabled)
    if v.RemoveFogEnabled or v.SimpleLightingEnabled then Lighting.FogStart=0;Lighting.FogEnd=1000000 else Lighting.FogStart=O.Original.FogStart;Lighting.FogEnd=O.Original.FogEnd end

    for _,object in ipairs(Lighting:GetChildren()) do
        if object:IsA("PostEffect") then
            if O.Original.Post[object]==nil then O.Original.Post[object]=object.Enabled end
            object.Enabled = not (v.DisablePostProcessingEnabled or v.SimpleLightingEnabled or v.DisableCameraEffectsEnabled)
        end
    end

    if v.DisableEffectsEnabled then
        local processed=0
        for _,object in ipairs(WorkspaceService:GetDescendants()) do
            processed+=1;if processed>5000 then break end
            if object:IsA("ParticleEmitter") or object:IsA("Trail") or object:IsA("Beam")
                or object:IsA("Smoke") or object:IsA("Fire") or object:IsA("Sparkles") then
                if O.Original.Effects[object]==nil then O.Original.Effects[object]=object.Enabled end
                object.Enabled=false
            end
        end
    else
        for object,enabled in pairs(O.Original.Effects) do
            if object and object.Parent then pcall(function() object.Enabled=enabled end) end
        end
    end

    if v.LowDetailMapMaterialsEnabled then
        local processed=0
        for _,object in ipairs(WorkspaceService:GetDescendants()) do
            processed+=1;if processed>5000 then break end
            if object:IsA("BasePart") and not O.ProtectedPart(object) then
                if O.Original.Parts[object]==nil then O.Original.Parts[object]={Material=object.Material,Reflectance=object.Reflectance} end
                object.Material=Enum.Material.SmoothPlastic;object.Reflectance=0
            end
        end
    else
        for object,original in pairs(O.Original.Parts) do
            if object and object.Parent then
                pcall(function() object.Material=original.Material;object.Reflectance=original.Reflectance end)
            end
        end
    end
end

function O.Preset(name)
    O.Values.OptimizationPreset=name
    local function set(key,value) O.Values[key]=value end
    if name=="Default" then
        for key,value in pairs(O.Defaults) do if key~="FPSCap" and key~="OptimizationPreset" then set(key,value) end end
    elseif name=="Balanced" then
        set("PerformanceModeEnabled",true);set("DisableEffectsEnabled",true);set("EcoLoopModeEnabled",false)
        set("CleanupDeadTitansEnabled",true);set("RemoveFogEnabled",true);set("DisablePostProcessingEnabled",true)
        set("SimpleLightingEnabled",true);set("LowDetailMapMaterialsEnabled",false);set("SleepUIWhenHiddenEnabled",true);set("DisableCameraEffectsEnabled",true)
    elseif name=="Max FPS" then
        for key in pairs(O.Defaults) do if string.find(key,"Enabled",1,true) then set(key,true) end end
    end
    O.Save();O.Apply();if O.Refresh then O.Refresh() end
end

O.Load();O.Apply()
