-- V9.8.4 • CONFIG STARTUP ORCHESTRATOR
-- Apply the complete autoload record only after Auto Upgrade, Auto Prestige,
-- Skill Tree, and Lobby Automation have finished constructing. Easy Add then
-- polls the signed backend inbox without blocking normal lobby work.
task.defer(function()
    task.wait(0.45)

    local autoloadName = V98330ConfigEcosystem.PendingAutoloadName
    local autoloadRecord = V98330ConfigEcosystem.PendingAutoloadRecord
    V98330ConfigEcosystem.PendingAutoloadName = nil
    V98330ConfigEcosystem.PendingAutoloadRecord = nil

    if type(autoloadRecord) == "table" then
        local okApply, _, adjustments = V98330ConfigEcosystem.ApplyRecord(
            autoloadRecord,
            {startCountdown = true}
        )
        refreshAll()
        if V94LobbyRefresh.Configs then V94LobbyRefresh.Configs() end
        if V94LobbyRefresh.AutoUpgrade then V94LobbyRefresh.AutoUpgrade() end
        if V94LobbyRefresh.Settings then V94LobbyRefresh.Settings() end

        if okApply then
            local adjustmentCount = type(adjustments) == "table" and #adjustments or 0
            notify(
                "Config auto-loaded",
                tostring(autoloadName or "Saved config")
                    .. (adjustmentCount > 0
                        and (" • " .. tostring(adjustmentCount) .. " compatibility adjustment"
                            .. (adjustmentCount == 1 and "" or "s"))
                        or ""),
                "success"
            )
        else
            notify("Config auto-load failed", tostring(autoloadName or "Saved config"), "error")
        end
    elseif V98330ConfigEcosystem.PendingStart == true then
        V98330ConfigEcosystem.PendingStart = false
        if type(V98330ConfigEcosystem.StartCountdown) == "function" then
            task.defer(V98330ConfigEcosystem.StartCountdown)
        end
    end
end)

if not V98330ConfigEcosystem.Polling then
    V98330ConfigEcosystem.Polling = true
    task.spawn(function()
        task.wait(3.0)
        while gui.Parent do
            if not V98330ConfigEcosystem.Launching
                and V98330ConfigEcosystem.PendingPreview == nil then
                local record, metaOrError = V98330ConfigEcosystem.PollInbox()
                if type(record) == "table" then
                    V98330ConfigEcosystem.LastInboxError = nil
                    if type(V98330ConfigEcosystem.ShowImportPreview) == "function" then
                        V98330ConfigEcosystem.ShowImportPreview(record, metaOrError)
                        notify(
                            "Discord config received",
                            tostring(record.name or "Community config") .. " is ready to preview.",
                            "info"
                        )
                    end
                elseif record == nil then
                    -- Network, auth, or unlinked-license errors stay quiet so
                    -- the lobby is never spammed. Debug mode still records them.
                    local resolvedError = tostring(metaOrError or "Unknown inbox error")
                    if resolvedError ~= V98330ConfigEcosystem.LastInboxError then
                        V98330ConfigEcosystem.LastInboxError = resolvedError
                        warn("[SliceHub Configs] Easy Add inbox:", resolvedError)
                    end
                else
                    V98330ConfigEcosystem.LastInboxError = nil
                end
            end
            task.wait(8.0)
        end
        V98330ConfigEcosystem.Polling = false
    end)
end

refreshAll()
if V94LobbyRefresh.Configs then V94LobbyRefresh.Configs() end
if V94LobbyRefresh.AutoUpgrade then V94LobbyRefresh.AutoUpgrade() end
if V94LobbyRefresh.Settings then V94LobbyRefresh.Settings() end
