local MAINMENU_SOURCE = [====[

local __SliceHubRawPrint = print
local __SliceHubRawWarn = warn
local __SliceHubRuntimeEnv =
    (type(getgenv) == "function" and getgenv())
    or _G

local function __SliceHubDebugEnabled()
    return type(__SliceHubRuntimeEnv) == "table"
        and __SliceHubRuntimeEnv.SliceHubDebug == true
end

local function print(...)
    if __SliceHubDebugEnabled() then
        __SliceHubRawPrint(...)
    end
end

local function warn(...)
    if __SliceHubDebugEnabled() then
        __SliceHubRawWarn(...)
    end
end

local function __SliceHubCritical(message)
    local resolved = tostring(message or "Unknown SliceHub error")
    __SliceHubRawWarn(resolved)

    pcall(function()
        game:GetService("StarterGui"):SetCore(
            "SendNotification",
            {
                Title = "SliceHub failed to start",
                Text = string.sub(resolved, 1, 220),
                Duration = 15,
            }
        )
    end)
end


-- SliceHub Main Menu Director V5.9.0 • V9.8.4 shared optimization
-- Lightweight main-menu only script. No mission farm loops here.
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")
local VirtualInputManager = game:GetService("VirtualInputManager")
local TeleportService = game:GetService("TeleportService")
local HttpService = game:GetService("HttpService")
local Lighting = game:GetService("Lighting")
local RunService = game:GetService("RunService")

local player = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")

-- V9.8.2.9.8: cached teleports launch this source as an isolated chunk. Recover
-- the generated tier from the key-gate config before any UI or queue logic runs.
local RuntimeEnv = type(getgenv) == "function" and getgenv() or _G
RuntimeEnv.SliceHub = type(RuntimeEnv.SliceHub) == "table" and RuntimeEnv.SliceHub or {}
local ActiveBuildTier = string.upper(tostring(
    RuntimeEnv.SliceHub.BuildTier
    or (type(RuntimeEnv.SliceHubKeyGateConfig) == "table"
        and RuntimeEnv.SliceHubKeyGateConfig.BuildTier)
    or RuntimeEnv.SliceHubExpectedTier
    or "FREE"
))
if ActiveBuildTier ~= "PREMIUM" then ActiveBuildTier = "FREE" end
RuntimeEnv.SliceHub.BuildTier = ActiveBuildTier
RuntimeEnv.SliceHub.IsPremium = ActiveBuildTier == "PREMIUM"
RuntimeEnv.SliceHubExpectedTier = ActiveBuildTier
local ActiveBuildVersion = tostring(
    type(RuntimeEnv.SliceHubKeyGateConfig) == "table"
    and RuntimeEnv.SliceHubKeyGateConfig.Version
    or "9.8.3.4.5"
)

local MainMenuSettingsFile = "AOT_MainMenuSettings_v1.json"
local MainMenuScalePercent = 100
local MainMenuAutoSlotEnabled = false
local MainMenuAutoSlotName = "slot a"
local MainMenuAutoSlotDestination = "Town"
local mainMenuReadFile = type(RuntimeEnv.readfile) == "function" and RuntimeEnv.readfile
    or (type(readfile) == "function" and readfile or nil)
local mainMenuWriteFile = type(RuntimeEnv.writefile) == "function" and RuntimeEnv.writefile
    or (type(writefile) == "function" and writefile or nil)

local function loadMainMenuSettings()
    if type(mainMenuReadFile) ~= "function" then return end
    local okRead, raw = pcall(mainMenuReadFile, MainMenuSettingsFile)
    if not okRead or type(raw) ~= "string" or raw == "" then return end
    local okDecode, document = pcall(function() return HttpService:JSONDecode(raw) end)
    if okDecode and type(document) == "table" then
        MainMenuScalePercent = math.clamp(
            math.floor((tonumber(document.MenuScale) or 100) + 0.5),
            80,
            120
        )
        MainMenuAutoSlotEnabled = document.AutoSlotEnabled == true
        local savedSlot = string.lower(tostring(document.AutoSlotName or "slot a"))
        if savedSlot ~= "slot a" and savedSlot ~= "slot b" and savedSlot ~= "slot c" then
            savedSlot = "slot a"
        end
        MainMenuAutoSlotName = savedSlot
        local savedDestination = tostring(document.AutoSlotDestination or "Town")
        MainMenuAutoSlotDestination = savedDestination == "Trade" and "Trade" or "Town"
    end
end

local function saveMainMenuSettings()
    if type(mainMenuWriteFile) ~= "function" then return false, "file write unavailable" end
    local okEncode, encoded = pcall(function()
        return HttpService:JSONEncode({
            Version = 2,
            MenuScale = math.clamp(math.floor((tonumber(MainMenuScalePercent) or 100) + 0.5), 80, 120),
            AutoSlotEnabled = MainMenuAutoSlotEnabled == true,
            AutoSlotName = tostring(MainMenuAutoSlotName or "slot a"),
            AutoSlotDestination = tostring(MainMenuAutoSlotDestination or "Town"),
        })
    end)
    if not okEncode then return false, "JSON encode failed" end
    local okWrite, writeError = pcall(mainMenuWriteFile, MainMenuSettingsFile, encoded)
    return okWrite, okWrite and "saved" or tostring(writeError)
end

loadMainMenuSettings()

-- V9.8.4 shared optimization state. This reads and writes the exact same
-- TitanControlSettings document used by mission runtime and the Lobby tab.
local MainMenuOptimization = {
    FileName = "TitanControlSettings_v101.json",
    Defaults = {
        OptimizationPreset="Default", PerformanceModeEnabled=false,
        DisableEffectsEnabled=false, EcoLoopModeEnabled=false,
        MapPropsHiddenEnabled=false, RemoveInjuryKillFlashEnabled=false,
        RemoveDamageTextEnabled=false, CleanupDeadTitansEnabled=false,
        RemoveFogEnabled=false, DisablePostProcessingEnabled=false,
        Disable3DRenderingEnabled=false, SimpleLightingEnabled=false,
        LowDetailMapMaterialsEnabled=false, SleepUIWhenHiddenEnabled=false,
        DisableCameraEffectsEnabled=false, FPSCap=60,
    },
    Values = {}, Document = {},
    Original = {Effects=setmetatable({}, {__mode="k"}), Parts=setmetatable({}, {__mode="k"}), Post=setmetatable({}, {__mode="k"})},
}

function MainMenuOptimization:Load()
    self.Document={}
    if mainMenuReadFile then
        local ok,raw=pcall(mainMenuReadFile,self.FileName)
        if ok and type(raw)=="string" and raw~="" then
            local ok2,doc=pcall(function() return HttpService:JSONDecode(raw) end)
            if ok2 and type(doc)=="table" then self.Document=doc end
        end
    elseif type(RuntimeEnv.TitanControlPersistentSettings)=="table" then self.Document=RuntimeEnv.TitanControlPersistentSettings end
    self.Values={};for key,value in pairs(self.Defaults) do self.Values[key]=value end
    local toggles=type(self.Document.Toggles)=="table" and self.Document.Toggles or {}
    for key,value in pairs(toggles) do if self.Values[key]~=nil then self.Values[key]=value end end
    self.Values.FPSCap=math.clamp(math.floor((tonumber(self.Values.FPSCap) or 60)+0.5),30,999)
end

function MainMenuOptimization:Save()
    self.Document=type(self.Document)=="table" and self.Document or {}
    self.Document.Toggles=type(self.Document.Toggles)=="table" and self.Document.Toggles or {}
    for key,value in pairs(self.Values) do self.Document.Toggles[key]=value end
    RuntimeEnv.TitanControlPersistentSettings=self.Document
    if not mainMenuWriteFile then return true end
    local ok,encoded=pcall(function() return HttpService:JSONEncode(self.Document) end)
    if not ok then return false end
    return pcall(mainMenuWriteFile,self.FileName,encoded)
end

function MainMenuOptimization:ProtectedPart(part)
    local path=string.lower(part:GetFullName())
    for _,word in ipairs({"objective","titan","boss","cannon","refill","gas","station","interact","prompt","wave","cutscene","eren","player","character","spawn","mission"}) do
        if string.find(path,word,1,true) then return true end
    end
    return false
end

function MainMenuOptimization:Apply()
    local v=self.Values
    pcall(function() if type(setfpscap)=="function" then setfpscap(v.FPSCap) end end)
    pcall(function() RunService:Set3dRenderingEnabled(v.Disable3DRenderingEnabled~=true) end)
    if self.Original.GlobalShadows==nil then self.Original.GlobalShadows=Lighting.GlobalShadows end
    if self.Original.FogEnd==nil then self.Original.FogEnd=Lighting.FogEnd;self.Original.FogStart=Lighting.FogStart end
    Lighting.GlobalShadows=not (v.PerformanceModeEnabled or v.SimpleLightingEnabled)
    if v.RemoveFogEnabled or v.SimpleLightingEnabled then Lighting.FogStart=0;Lighting.FogEnd=1000000 else Lighting.FogStart=self.Original.FogStart;Lighting.FogEnd=self.Original.FogEnd end
    for _,object in ipairs(Lighting:GetChildren()) do
        if object:IsA("PostEffect") then
            if self.Original.Post[object]==nil then self.Original.Post[object]=object.Enabled end
            object.Enabled=not (v.DisablePostProcessingEnabled or v.SimpleLightingEnabled or v.DisableCameraEffectsEnabled)
        end
    end
    if v.DisableEffectsEnabled then
        local processed=0
        for _,object in ipairs(workspace:GetDescendants()) do
            processed+=1;if processed>3500 then break end
            if object:IsA("ParticleEmitter") or object:IsA("Trail") or object:IsA("Beam") or object:IsA("Smoke") or object:IsA("Fire") or object:IsA("Sparkles") then
                if self.Original.Effects[object]==nil then self.Original.Effects[object]=object.Enabled end
                object.Enabled=false
            end
        end
    else
        for object,enabled in pairs(self.Original.Effects) do
            if object and object.Parent then pcall(function() object.Enabled=enabled end) end
        end
    end
    if v.LowDetailMapMaterialsEnabled then
        local processed=0
        for _,object in ipairs(workspace:GetDescendants()) do
            processed+=1;if processed>3500 then break end
            if object:IsA("BasePart") and not self:ProtectedPart(object) then
                if self.Original.Parts[object]==nil then self.Original.Parts[object]={Material=object.Material,Reflectance=object.Reflectance} end
                object.Material=Enum.Material.SmoothPlastic;object.Reflectance=0
            end
        end
    else
        for object,original in pairs(self.Original.Parts) do
            if object and object.Parent then pcall(function() object.Material=original.Material;object.Reflectance=original.Reflectance end) end
        end
    end
end

function MainMenuOptimization:Preset(name)
    self.Values.OptimizationPreset=name
    if name=="Default" then
        for key,value in pairs(self.Defaults) do if key~="FPSCap" and key~="OptimizationPreset" then self.Values[key]=value end end
    elseif name=="Balanced" then
        self.Values.PerformanceModeEnabled=true;self.Values.DisableEffectsEnabled=true;self.Values.EcoLoopModeEnabled=false
        self.Values.CleanupDeadTitansEnabled=true;self.Values.RemoveFogEnabled=true;self.Values.DisablePostProcessingEnabled=true
        self.Values.SimpleLightingEnabled=true;self.Values.LowDetailMapMaterialsEnabled=false;self.Values.SleepUIWhenHiddenEnabled=true;self.Values.DisableCameraEffectsEnabled=true
    elseif name=="Max FPS" then
        for key in pairs(self.Defaults) do if string.find(key,"Enabled",1,true) then self.Values[key]=true end end
    end
    self:Save();self:Apply();if self.Refresh then self:Refresh() end
end
MainMenuOptimization:Load()
MainMenuOptimization:Apply()


