-- Mobile fit: the family-spinner/main-menu panel was designed for desktop.
-- Keep desktop unchanged, but scale and vertically center it on phones/tablets.
local function updateMainMenuMobileFit()
    local camera = workspace.CurrentCamera
    if not camera or not root then return end

    local viewport = camera.ViewportSize
    if viewport.X < 240 or viewport.Y < 200 then return end

    local scaleObject = root:FindFirstChild("SliceHubMainMenuMobileFit")
    if not scaleObject then
        scaleObject = Instance.new("UIScale")
        scaleObject.Name = "SliceHubMainMenuMobileFit"
        scaleObject.Parent = root
    end

    local designWidth = math.max(1, root.Size.X.Offset)
    local designHeight = math.max(1, root.Size.Y.Offset)
    local compact = UserInputService.TouchEnabled or viewport.Y < 620 or viewport.X < 900
    local margin = compact and 16 or 44
    local requestedScale = math.clamp((tonumber(MainMenuScalePercent) or 100) / 100, 0.80, 1.20)
    local maxViewportScale = math.min(
        math.max(0.25, (viewport.X - margin) / designWidth),
        math.max(0.25, (viewport.Y - margin) / designHeight)
    )
    maxViewportScale = compact
        and math.clamp(maxViewportScale, 0.30, 0.78)
        or math.clamp(maxViewportScale, 0.60, 1.20)

    scaleObject.Scale = math.min(requestedScale, maxViewportScale)
    root.AnchorPoint = Vector2.new(0.5, 0.5)
    root.Position = UDim2.fromScale(0.5, 0.5)
end

updateMainMenuMobileFit()
if workspace.CurrentCamera then
    workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(updateMainMenuMobileFit)
end
workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
    task.defer(updateMainMenuMobileFit)
end)

