    local delta = input.Position - rootDragStart
    root.Position = UDim2.new(
        rootStartPosition.X.Scale, rootStartPosition.X.Offset + delta.X,
        rootStartPosition.Y.Scale, rootStartPosition.Y.Offset + delta.Y
    )
end)

