end)

local function cleanText(value)
	local text = tostring(value or "")
	text = string.gsub(text, "<.->", "")
	text = string.gsub(text, "%s+", " ")
	text = string.gsub(text, "^%s+", "")
	text = string.gsub(text, "%s+$", "")
	return string.lower(text)
end

local function visibleTextObject(object)
	if not object or not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then return false end
	if not object.Visible or object.AbsoluteSize.X <= 0 or object.AbsoluteSize.Y <= 0 then return false end
	local node = object.Parent
	while node and node ~= playerGui do
		if node:IsA("GuiObject") and not node.Visible then return false end
		if node:IsA("LayerCollector") and not node.Enabled then return false end
		node = node.Parent
	end
	return true
end

local function clickAt(x, y)
	local inset = Vector2.new(0, 0)
	pcall(function() inset = GuiService:GetGuiInset() end)
	local cx = math.floor(x + inset.X + 0.5)
	local cy = math.floor(y + inset.Y + 0.5)
	pcall(function() VirtualInputManager:SendMouseMoveEvent(cx, cy, game) end)
	task.wait(0.03)
	pcall(function() VirtualInputManager:SendMouseButtonEvent(cx, cy, 0, true, game, 0) end)
	task.wait(0.05)
	pcall(function() VirtualInputManager:SendMouseButtonEvent(cx, cy, 0, false, game, 0) end)
end

local function buttonAncestor(object)
	local node = object
	for _ = 1, 9 do
		if not node or node == playerGui then break end
		if node:IsA("GuiButton") then return node end
		node = node.Parent
	end
	return nil
end

local function cardRoot(object)
	if not object or not object:IsA("GuiObject") then return nil end
	local best = object
	local node = object.Parent
	for _ = 1, 10 do
		if not node or node == playerGui then break end
		if node:IsA("GuiObject") then
			local size = node.AbsoluteSize
			if size.X >= 110 and size.Y >= 70 and size.X <= 620 and size.Y <= 520 then
				best = node
			end
		end
		node = node.Parent
	end
	return best
end

local function fireNativeButtonConnections(target)
    if not target or not target:IsA("GuiButton") then return false end

    local getConnections = RuntimeEnv.getconnections
        or (type(getconnections) == "function" and getconnections or nil)
    local fired = false

    if type(getConnections) == "function" then
        for _, signalName in ipairs({"Activated", "MouseButton1Click", "TouchTap"}) do
            local okSignal, signal = pcall(function() return target[signalName] end)
            if okSignal and signal then
                local okConnections, connections = pcall(getConnections, signal)
                if okConnections and type(connections) == "table" then
                    for _, connection in ipairs(connections) do
                        if connection and type(connection.Fire) == "function" then
                            local okFire = pcall(function() connection:Fire() end)
                            fired = fired or okFire
                        end
                    end
                end
            end
        end
    end

    if not fired then
        pcall(function() target:Activate() end)
    end

    return fired
end

local function clickGuiObject(object, preferCard)
	if not object or not object:IsA("GuiObject") then return false end
	local target = preferCard and (cardRoot(object) or object) or (buttonAncestor(object) or object)

    -- Hidden/native main-menu controls often ignore synthetic mouse input on
    -- mobile. Fire their existing local callback first, then retain coordinate
    -- input as a compatibility fallback.
    if target:IsA("GuiButton") and fireNativeButtonConnections(target) then
        return true
    end

	local pos = target.AbsolutePosition
	local size = target.AbsoluteSize
	clickAt(pos.X + size.X / 2, pos.Y + size.Y / 2)
	return true
end

local function findText(wanted)
	local needle = cleanText(wanted)
	for _, object in ipairs(playerGui:GetDescendants()) do
		if helperGui and object:IsDescendantOf(helperGui) then continue end
		if visibleTextObject(object) then
			local hay = cleanText(object.Text)
			if hay == needle or string.find(hay, needle, 1, true) then
				return object
			end
		end
	end
	return nil
end

local function clickText(wanted, preferCard)
	local object = findText(wanted)
	if object then return clickGuiObject(object, preferCard) end
	return false
end

local function clickSlot(slotName)
	local slotTitle = findText(slotName)
	if not slotTitle then return false end
	local card = cardRoot(slotTitle)
	local selectObj = nil
	if card then
		for _, object in ipairs(card:GetDescendants()) do
			if visibleTextObject(object) and string.find(cleanText(object.Text), "select", 1, true) then
				selectObj = object
				break
			end
		end
	end
	if selectObj then return clickGuiObject(selectObj, false) end
	if card then
		local pos = card.AbsolutePosition
		local size = card.AbsoluteSize
		clickAt(pos.X + size.X / 2, pos.Y + size.Y * 0.86)
		return true
	end
	return clickGuiObject(slotTitle, false)
end

local function inspectNativeSlot(slotName)
    slotName = string.lower(tostring(slotName or "slot a"))
    local slotTitle = findText(slotName)
    if not slotTitle then
        return "unknown", nil, "native slot card not found"
    end

    local card = cardRoot(slotTitle)
    if not card then
        return "unknown", nil, "native slot card root not found"
    end

    local sawSelect = false
    local sawLocked = false
    local lockEvidence = nil

    local objects = {card}
    for _, descendant in ipairs(card:GetDescendants()) do
        table.insert(objects, descendant)
    end

    for _, object in ipairs(objects) do
        local objectName = string.lower(tostring(object.Name or ""))
        local visibleLockObject = false
        if object:IsA("GuiObject") and object.Visible
            and object.AbsoluteSize.X > 0 and object.AbsoluteSize.Y > 0 then
            visibleLockObject = true
            local node = object.Parent
            while node and node ~= playerGui do
                if node:IsA("GuiObject") and not node.Visible then
                    visibleLockObject = false
                    break
                end
                if node:IsA("LayerCollector") and not node.Enabled then
                    visibleLockObject = false
                    break
                end
                node = node.Parent
            end
        end
        if visibleLockObject and string.find(objectName, "lock", 1, true) then
            sawLocked = true
            lockEvidence = lockEvidence or ("visible object " .. tostring(object.Name))
        end

        if visibleTextObject(object) then
            local value = cleanText(object.Text)
            if string.find(value, "select", 1, true) then
                sawSelect = true
            end
            if string.find(value, "locked", 1, true)
                or string.find(value, "unlock at", 1, true)
                or string.find(value, "prestige required", 1, true)
                or string.find(value, "requires prestige", 1, true) then
                sawLocked = true
                lockEvidence = lockEvidence or value
            end
        end
    end

    if sawLocked and not sawSelect then
        return "locked", card, lockEvidence or "native lock evidence"
    end
    if sawSelect then
        return "available", card, "native SELECT control found"
    end

    -- Some selected/unlocked cards do not keep the SELECT text visible. A card
    -- without any lock evidence is treated as available, while the actual click
    -- still remains the final runtime confirmation.
    return "available", card, "slot card visible without lock evidence"
end

local function queueCurrentTierBootstrap()
    local readFn = RuntimeEnv.readfile or (type(readfile) == "function" and readfile or nil)
    local deleteFn = RuntimeEnv.delfile or (type(delfile) == "function" and delfile or nil)
    local queueFn = RuntimeEnv.queue_on_teleport
        or RuntimeEnv.queueonteleport
        or RuntimeEnv.queue_on_tp
        or (RuntimeEnv.syn and RuntimeEnv.syn.queue_on_teleport)

    if type(readFn) ~= "function" or type(queueFn) ~= "function" then
        return false, "teleport queue or cache read unavailable"
    end

    local bootstrapPath = ActiveBuildTier == "PREMIUM"
        and "SH/bootstrap_premium.shc"
        or "SH/bootstrap_free.shc"

    if ActiveBuildTier == "PREMIUM" and type(deleteFn) == "function" then
        -- A stale queued Free cache was the source of the automatic downgrade.
        pcall(deleteFn, "SH/bootstrap_free.shc")
        pcall(deleteFn, "SH/bootstrap.shc")
    end

    local code = string.format([[
local environment = type(getgenv) == "function" and getgenv() or _G
environment.SliceHubExpectedTier = %q
environment.SliceHub = type(environment.SliceHub) == "table" and environment.SliceHub or {}
environment.SliceHub.BuildTier = %q
environment.SliceHub.IsPremium = %s
local p = %q
local loader = loadstring or load
if type(readfile) == "function" and type(loader) == "function" then
    local ok, source = pcall(readfile, p)
    if ok and type(source) == "string" then
        local chunk = loader(source)
        if type(chunk) == "function" then chunk() end
    end
end
]], ActiveBuildTier, ActiveBuildTier, tostring(ActiveBuildTier == "PREMIUM"), bootstrapPath)

    local ok, result = pcall(queueFn, code)
    return ok, result
end

