local SelectedDestination = MainMenuAutoSlotDestination == "Trade" and "Trade" or "Town"
local DestinationButtons = {}

local function destinationPlaceId(destination)
    local byGame = DestinationPlaces[tonumber(game.GameId) or 0]
    return byGame and byGame[destination] or nil
end

local DirectorBusy = false
local updateDirectorStatus = function() end

local function directDestination(destination)
    if DirectorBusy then
        updateDirectorStatus("Another Main Menu action is already running.", "warning")
        return false
    end

    local placeId = destinationPlaceId(destination)
    if not placeId then
        updateDirectorStatus("No destination PlaceId is configured for this AOT:R universe.", "error")
        warn("[AOT MainMenu V5.9] no grounded destination PlaceId for GameId", game.GameId)
        return false
    end

    DirectorBusy = true
    RuntimeEnv.SliceHubExpectedTier = ActiveBuildTier
    updateDirectorStatus("Queuing " .. ActiveBuildTier .. " loader for " .. destination .. " Central...", "working")

    local queued, queueError = queueCurrentTierBootstrap()
    if not queued then
        updateDirectorStatus("Could not queue the " .. ActiveBuildTier .. " loader: " .. tostring(queueError), "error")
        DirectorBusy = false
        return false
    end

    task.wait(0.18)
    updateDirectorStatus("Teleporting to " .. destination .. " Central...", "working")

    local ok, err = pcall(function()
        TeleportService:TeleportAsync(placeId, {player})
    end)

    if not ok then
        ok, err = pcall(function()
            TeleportService:Teleport(placeId, player)
        end)
    end

    if not ok then
        DirectorBusy = false
        updateDirectorStatus("Teleport failed: " .. tostring(err), "error")
        warn("[AOT MainMenu V5.9] direct destination failed", destination, err)
    end
    return ok
end

local function refreshDestinationButtons()
    for name, button in pairs(DestinationButtons) do
