end

local function presetFlow(slotName)
    if DirectorBusy then
        updateDirectorStatus("Another Main Menu action is already running.", "warning")
        return false
    end

    updateDirectorStatus("Selecting " .. string.upper(tostring(slotName or "slot a")) .. "...", "working")
    local selected = clickSlot(slotName or "slot a")
    if not selected then
        updateDirectorStatus("Could not find the native " .. tostring(slotName) .. " SELECT control.", "error")
        warn("[AOT MainMenu V5.9] slot selection failed", slotName)
        return false
    end

    task.wait(0.35)
    return directDestination(SelectedDestination)
end

