local function refreshMainMenuScaleUI()
    local value = math.clamp(math.floor((tonumber(MainMenuScalePercent) or 100) + 0.5), 80, 120)
    local ratio = (value - 80) / 40
    mainScaleLabel.Text = "Menu Scale: " .. tostring(value) .. "%"
    mainScaleFill.Size = UDim2.fromScale(ratio, 1)
    mainScaleKnob.Position = UDim2.fromScale(ratio, 0.5)
end

local draggingMainMenuScale = false
local function setMainMenuScaleFromX(x)
    local ratio = math.clamp(
        (x - mainScaleTrack.AbsolutePosition.X) / math.max(1, mainScaleTrack.AbsoluteSize.X),
        0,
        1
    )
    MainMenuScalePercent = math.clamp(math.floor(80 + ratio * 40 + 0.5), 80, 120)
    updateMainMenuMobileFit()
    refreshMainMenuScaleUI()
end

