    if shellDragging and shellDragStart and shellStartPosition
        and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
        local delta = input.Position - shellDragStart
        local scaleObject = shell:FindFirstChild("SliceHubMainMenuMobileFit")
        local divisor = scaleObject and math.max(0.25, scaleObject.Scale) or 1
        shell.Position = UDim2.new(
            shellStartPosition.X.Scale,
            shellStartPosition.X.Offset + delta.X / divisor,
            shellStartPosition.Y.Scale,
            shellStartPosition.Y.Offset + delta.Y / divisor
        )
    end
end)
UserInputService.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        shellDragging = false
    end
end)

