local MISSION_SOURCE = [====[

local __SliceHubRawPrint = print
local __SliceHubRawWarn = warn
local __SliceHubRuntimeEnv =
    (type(getgenv) == "function" and getgenv())
    or _G

local function __SliceHubDebugEnabled()
    return type(__SliceHubRuntimeEnv) == "table"
        and __SliceHubRuntimeEnv.SliceHubDebug == true
end

local function print(...)
    if __SliceHubDebugEnabled() then
        __SliceHubRawPrint(...)
    end
end

local function warn(...)
    if __SliceHubDebugEnabled() then
        __SliceHubRawWarn(...)
    end
end

local function __SliceHubCritical(message)
    local resolved = tostring(message or "Unknown SliceHub error")
    __SliceHubRawWarn(resolved)

    pcall(function()
        game:GetService("StarterGui"):SetCore(
            "SendNotification",
            {
                Title = "SliceHub failed to start",
                Text = string.sub(resolved, 1, 220),
                Duration = 15,
            }
        )
    end)
end


-- SLICE HUB V2.0.0 • PERFORMANCE CORE
local V577LaunchStartedAt = os.clock()
-- Place inside StarterPlayerScripts as a LocalScript.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")
local HttpService = game:GetService("HttpService")
local UserInputService = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")
local Workspace = game:GetService("Workspace")
local VirtualInputManager = game:GetService("VirtualInputManager")
local TeleportService = game:GetService("TeleportService")

-- The mission runtime is a separate loadstring chunk, so outer locals are
-- not inherited. Use a short scoped block and assign PROFILE globally. This
-- avoids adding long-lived top-level locals to this register-heavy chunk.
do
    local environment = _G
    pcall(function()
        if type(getgenv) == "function" then
            environment = getgenv()
        end
    end)

    local hub = type(environment) == "table" and environment.SliceHub or nil
    local resolvedProfile = type(hub) == "table" and hub.Profile or nil
    if type(resolvedProfile) ~= "table" then
        resolvedProfile = {}
    end
    if type(resolvedProfile.Spears) ~= "table" then
        resolvedProfile.Spears = {}
    end
    PROFILE = resolvedProfile
end

-- Mission-local tier helpers. These read the generated profile directly so
-- Free always exposes/uses up to 6 and Premium always exposes/uses up to 20.
function SliceHubMissionTPSMin()
    local combat = PROFILE and PROFILE.Combat or nil
    local value = combat and tonumber(combat.TitansPerSwingMin) or 2
    value = math.floor(value + 0.5)
    if value < 1 then value = 1 end
    return value
end

function SliceHubMissionTPSMax()
    local blade = PROFILE and PROFILE.Blade or nil
    local combat = PROFILE and PROFILE.Combat or nil
    local minimum = SliceHubMissionTPSMin()
    local value = blade and tonumber(blade.MaxTitansPerSwing)
        or (combat and tonumber(combat.TitansPerSwingMax))
        or 20
    value = math.floor(value + 0.5)
    if value < minimum then value = minimum end
    return value
end

function SliceHubMissionClampTPS(value, fallback)
    local minimum = SliceHubMissionTPSMin()
    local maximum = SliceHubMissionTPSMax()
    local resolved = tonumber(value)
    if resolved == nil then
        resolved = tonumber(fallback) or maximum
    end
    return math.clamp(math.floor(resolved + 0.5), minimum, maximum)
end

