-- STATE CONTROL
---------------------------------------------------------------------


-- V9.8.4: build-time mission tier bridge.
-- Key-gated source chunks can run in isolated loadstring environments, so
-- mission feature gates must not depend on outer-master globals.
SliceHubMissionBuildV9144 = {
    IsPremium = false,
    PremiumWave = false,
    FastChestOpen = false,
}

function SliceHubIsPremium()
    return SliceHubMissionBuildV9144.IsPremium == true
end

function SliceHubFeatureEnabled(featureName)
    local name = tostring(featureName or "")

    if name == "ColossalRaid" then
        return true
    end

    if name == "AutoSkipCutscene"
        or name == "AutoRaidQueue"
        or name == "RaidAutomation"
        or name == "FemaleRaid"
        or name == "AttackRaid"
        or name == "ArmoredRaid"
        or name == "AutoOpenRaidChests"
        or name == "PrestigeThresholds"
        or name == "PrestigeBuffSelection"
        or name == "WaveAutomation" then
        return SliceHubIsPremium()
    end

    return true
end

function SliceHubAutoSkipCutsceneAllowed()
    return SliceHubFeatureEnabled("AutoSkipCutscene")
end

function SliceHubClampAutoSkipCutscene(value)
    return SliceHubAutoSkipCutsceneAllowed()
        and value == true
        or false
end

function SliceHubWaveAutomationAllowed()
    return SliceHubIsPremium()
        and SliceHubMissionBuildV9144.PremiumWave == true
end

function SliceHubMissionFastChestOpenAllowed()
    return SliceHubIsPremium()
        and SliceHubMissionBuildV9144.FastChestOpen == true
end

function SliceHubRaidRuntimeAllowed(raidName)
    raidName = tostring(raidName or "")

    if raidName == "Colossal Raid" then
        return true
    end

    if raidName == "Armored Raid"
        or raidName == "Attack Raid"
        or raidName == "Female Raid" then
        return SliceHubIsPremium()
    end

    return true
end

