	if character == oldCharacter then
		character = nil; humanoid = nil; rootPart = nil
	end
end)

---------------------------------------------------------------------
-- HARDWARE INPUT & EMULATION UTILITIES
---------------------------------------------------------------------

local function resolvePath(root, path)
	local current = root
	for _, name in ipairs(path) do
		current = current:FindFirstChild(name)
		if not current then return nil end
	end
	return current
end

local function scanNetworkForRemote(keywords)
	for _, item in ipairs(ReplicatedStorage:GetDescendants()) do
		if item:IsA("RemoteEvent") or item:IsA("RemoteFunction") then
			local lowerName = string.lower(item.Name)
			for _, keyword in ipairs(keywords) do
				if string.find(lowerName, keyword, 1, true) then
					return item
				end
			end
		end
	end
	return nil
end

local function simulateHumanKeyPress(keyCode)
	task.wait(0.02) 
	VirtualInputManager:SendKeyEvent(true, keyCode, false, game)
	task.wait(0.04) 
	VirtualInputManager:SendKeyEvent(false, keyCode, false, game)
end

local function simulateCenterMouseClick(targetPart)
	local camera = Workspace.CurrentCamera
	if not camera then return end

	local aimTarget = targetPart or currentTargetPart
	local aimPosition = nil
	if typeof(aimTarget) == "Vector3" then
		aimPosition = aimTarget
	elseif aimTarget and aimTarget.Parent then
		aimPosition = aimTarget.Position
	end

	if aimPosition then
		pcall(function()
			local cameraPosition = camera.CFrame.Position
			if (aimPosition - cameraPosition).Magnitude > 0.1 then
				camera.CFrame = CFrame.lookAt(cameraPosition, aimPosition)
			end
		end)
		task.wait(0.01)
	end
	
	local x = camera.ViewportSize.X / 2
	local y = camera.ViewportSize.Y / 2

	VirtualInputManager:SendMouseButtonEvent(x, y, 0, true, game, 0)
	task.wait(0.012)
	VirtualInputManager:SendMouseButtonEvent(x, y, 0, false, game, 0)
end

local function nameContainsKeyword(name, keywords)
	local lowerName = string.lower(name)
	for _, keyword in ipairs(keywords) do
		if string.find(lowerName, string.lower(keyword), 1, true) then return true end
	end
	return false
end

local function findMatchingTool(keywords)
	if character then
		for _, item in ipairs(character:GetChildren()) do
			if item:IsA("Tool") and nameContainsKeyword(item.Name, keywords) then return item end
		end
	end
	for _, item in ipairs(backpack:GetChildren()) do
		if item:IsA("Tool") and nameContainsKeyword(item.Name, keywords) then return item end
	end
	return nil
end

local function bladeToolScore(tool)
	if not tool or not tool:IsA("Tool") then return -math.huge end
	local name = string.lower(tostring(tool.Name or ""))
	if string.find(name, "ripper", 1, true)
		or string.find(name, "skill", 1, true)
		or string.find(name, "ability", 1, true) then
		return -math.huge
	end

	local score = 0
	if string.find(name, "blade", 1, true) then score += 120 end
	if string.find(name, "sword", 1, true) then score += 100 end
	if string.find(name, "katana", 1, true) then score += 100 end
	if string.find(name, "odm", 1, true) then score += 35 end
	if string.find(name, "gear", 1, true) then score += 12 end
	if string.find(name, "weapon", 1, true) then score += 6 end
	if character and tool:IsDescendantOf(character) then score += 10 end
	return score
end

local function findBladeTool(forceRescan)
	if not forceRescan and CachedBladeTool and CachedBladeTool.Parent and (
		CachedBladeTool:IsDescendantOf(backpack) or
		(character and CachedBladeTool:IsDescendantOf(character))
	) and bladeToolScore(CachedBladeTool) > 0 then
		return CachedBladeTool
	end

	local bestTool, bestScore = nil, -math.huge
	local function consider(container)
		if not container then return end
		for _, item in ipairs(container:GetChildren()) do
			local score = bladeToolScore(item)
			if score > bestScore then
				bestTool, bestScore = item, score
			end
		end
	end
	consider(character)
	consider(backpack)

	CachedBladeTool = bestScore > 0 and bestTool or nil
	return CachedBladeTool
end

-- Fixed Grip Logic: Prevents constant un-equipping glitches
local function equipTool(tool)
	if not humanoid or humanoid.Health <= 0 then return false end
	if not tool or not tool.Parent then return false end
	if tool.Parent ~= character then 
		humanoid:EquipTool(tool) 
	end
	return tool.Parent == character
end

local function tryFastReloadOnBladeToolMiss()
    -- V2.1.1: intentionally disabled.
    -- A missing Tool is not proof of empty blade segments.
    BladeToolMissingSince = nil
    return false
end

local function prepareBladeWaveTool()
    local tool = findBladeTool(false)

    if not tool then
        CachedBladeTool = nil
        tool = findBladeTool(true)
    end

    BladeToolMissingSince = nil
    BladeDiag.LastTool = tool and tool:GetFullName() or "nil"

    if not tool then
        BladeDiag.Reason = "NO_BLADE_TOOL"
        return nil
    end

    if not equipTool(tool) then
        task.wait(0.012)
        CachedBladeTool = nil
        tool = findBladeTool(true)

        if not tool or not equipTool(tool) then
            return nil
        end
    end

    pcall(function()
        tool:Activate()
    end)
    return tool
end


---------------------------------------------------------------------
-- AUTO BLADE REFILL (EXACT 0/6 EDGE TRIGGER)
---------------------------------------------------------------------

local BladeCounterKeywords = {
	"blade", "blades", "segment", "segments", "durability", "ammo", "sword", "weapon"
}

local function normalizeCounterText(value)
	local textValue = tostring(value or "")
	textValue = string.gsub(textValue, "<.->", "") -- Remove RichText tags.
	textValue = string.gsub(textValue, "%s+", "")
	return textValue
end

local function parseCounterTextForMaximum(value, expectedMaximum)
    local normalized = normalizeCounterText(value)
    local currentText, maximumText = string.match(normalized, "(%d+)/(%d+)")
    if not currentText or not maximumText then return nil, nil end

    local current = tonumber(currentText)
    local maximum = tonumber(maximumText)
    if current == nil or maximum ~= expectedMaximum then return nil, nil end
    if current < 0 or current > maximum then return nil, nil end
    return current, maximum
end

local function parseBladeCounterText(value)
    return parseCounterTextForMaximum(value, Config.BladeSegmentMaximum)
end

local function parseBladeSetCounterText(value)
    return parseCounterTextForMaximum(value, Config.BladeSetMaximum)
end

local function getCounterObjectText(object)
	if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
		return object.Text
	end
	return nil
end

local function bladeCounterCandidateScore(object, current, maximum)
	local score = 0
	local normalized = normalizeCounterText(getCounterObjectText(object))
	if normalized == string.format("%d/%d", current, maximum) then
		score += 8
	end

	if object:IsA("GuiObject") then
		if object.Visible then score += 2 end
		if object.AbsoluteSize.X > 0 and object.AbsoluteSize.Y > 0 then score += 2 end
	end

	local node = object
	for _ = 1, 5 do
		if not node then break end
		local lowerName = string.lower(node.Name)
		for _, keyword in ipairs(BladeCounterKeywords) do
			if string.find(lowerName, keyword, 1, true) then
				score += 5
				break
			end
		end
		node = node.Parent
	end

	return score
end


local function bladeCounterInsideSliceHub(object)
    local node = object
    while node do
        if node.Name == "TitanControlMenu" then
            return true
        end
        node = node.Parent
    end
    return false
end

local function bladeCounterActuallyVisible(object)
    if not object or not object:IsA("GuiObject") then
        return false
    end
    if not object.Visible or object.AbsoluteSize.X <= 0 or object.AbsoluteSize.Y <= 0 then
        return false
    end

    local node = object.Parent
    while node and node ~= playerGui do
        if node:IsA("GuiObject") and not node.Visible then
            return false
        end
        if node:IsA("LayerCollector") and not node.Enabled then
            return false
        end
        node = node.Parent
    end
    return true
end

local function getTrustedBladesHudRoot()
    return resolvePath(playerGui, {"Interface", "HUD", "Main", "Top", "7", "Blades"})
end

local function findBladeFillGradient()
    local bladesRoot = getTrustedBladesHudRoot()
    if not bladesRoot then
        cachedBladeFillGradient = nil
        return nil
    end

    if cachedBladeFillGradient
        and cachedBladeFillGradient.Parent
        and cachedBladeFillGradient:IsDescendantOf(bladesRoot)
        and cachedBladeFillGradient:IsA("UIGradient") then
        return cachedBladeFillGradient
    end

    cachedBladeFillGradient = nil

    local inner = bladesRoot:FindFirstChild("Inner")
    local bar = inner and inner:FindFirstChild("Bar")
    local direct = bar and bar:FindFirstChild("Gradient")
    if direct and direct:IsA("UIGradient") then
        cachedBladeFillGradient = direct
        return direct
    end

    -- Fallback for small UI hierarchy changes: select the horizontal fill gradient
    -- under the blade bar, never the decorative vertical Inner gradient.
    local best, bestScore = nil, -math.huge
    for _, object in ipairs(bladesRoot:GetDescendants()) do
        if object:IsA("UIGradient") then
            local score = 0
            local parentName = string.lower(tostring(object.Parent and object.Parent.Name or ""))
            if parentName == "bar" then score += 60 end
            if math.abs((tonumber(object.Rotation) or 0) - 30) <= 2 then score += 35 end
            if object.Parent and object.Parent:IsA("CanvasGroup") then score += 20 end
            if score > bestScore then
                best, bestScore = object, score
            end
        end
    end

    if best and bestScore >= 40 then
        cachedBladeFillGradient = best
        return best
    end
    return nil
end

local function readBladeFillOffset()
    local gradient = findBladeFillGradient()
    if not gradient then return nil, nil end

    local ok, offset = pcall(function()
        return gradient.Offset
    end)
    if not ok or typeof(offset) ~= "Vector2" then
        cachedBladeFillGradient = nil
        return nil, nil
    end

    local value = tonumber(offset.X)
    if value == nil then return nil, gradient end

    local path = gradient:GetFullName()
    if BladeDiag.LastSegmentSource ~= path then
        BladeDiag.LastSegmentSource = path
        print("[SliceHub V9.6][AMMO] blade fill source ->", path)
    end
    return value, gradient
end

local function bladeFillIsBroken(offset)
    return tonumber(offset) ~= nil
        and tonumber(offset) <= (tonumber(Config.V96BladeBrokenOffset) or -0.12)
end

local function bladeFillIsReady(offset)
    return tonumber(offset) ~= nil
        and tonumber(offset) >= (tonumber(Config.V96BladeReadyOffset) or 0.82)
end

local function readBladeRefillCharges()
    local value = nil
    pcall(function()
        value = player:GetAttribute("Refills")
    end)
    return tonumber(value)
end

local function findBladeCounter()
    -- V2: only trust the game's actual Blades HUD subtree.
    -- Never scan all of PlayerGui, because mission objectives can contain values like 0/6.
    local bladesRoot = getTrustedBladesHudRoot()
    if not bladesRoot then
        BladeDiag.LastNoCounterPrintAt = BladeDiag.LastNoCounterPrintAt or 0
        if os.clock() - BladeDiag.LastNoCounterPrintAt >= 4 then
            BladeDiag.LastNoCounterPrintAt = os.clock()
            print("[SliceHub V3][BLADE-COUNTER] trusted Blades HUD root missing; combat not ammo-gated")
        end
        return nil
    end

    local bestObject = nil
    local bestScore = -math.huge

    local function consider(object)
        local textValue = getCounterObjectText(object)
        if textValue == nil then return end

        local current, maximum = parseBladeCounterText(textValue)
        if current == nil or maximum ~= Config.BladeSegmentMaximum then return end

        local score = bladeCounterCandidateScore(object, current, maximum)

        local lowerName = string.lower(tostring(object.Name or ""))
        if string.find(lowerName, "segment", 1, true) then score += 25 end
        if string.find(lowerName, "durability", 1, true) then score += 20 end
        if string.find(lowerName, "blade", 1, true) then score += 10 end

        if score > bestScore then
            bestScore = score
            bestObject = object
        end
    end

    consider(bladesRoot)
    for _, object in ipairs(bladesRoot:GetDescendants()) do
        consider(object)
    end

    if bestObject then
        local path = bestObject:GetFullName()
        if BladeDiag.LastSegmentSource ~= path then
            BladeDiag.LastSegmentSource = path
            print("[SliceHub V3][AMMO] segment source ->", path)
        end
    else
        BladeDiag.LastNoCounterPrintAt = BladeDiag.LastNoCounterPrintAt or 0
        if os.clock() - BladeDiag.LastNoCounterPrintAt >= 8 then
            BladeDiag.LastNoCounterPrintAt = os.clock()
            print("[SliceHub V3][AMMO] trusted segment counter missing; combat not ammo-gated")
        end
    end

    return bestObject
end

local function readBladeSegments()
    -- V9.6: the game does not expose a dependable 0/N text counter. The horizontal
    -- blade-bar gradient is normalized by the UI and therefore survives different
    -- account durability upgrades. Only the broken/usable boundary is authoritative.
    local fillOffset = readBladeFillOffset()
    if fillOffset ~= nil then
        local maximum = math.max(1, math.floor(tonumber(Config.BladeSegmentMaximum) or 6))
        if bladeFillIsBroken(fillOffset) then
            return 0, maximum
        end

        -- Estimated value is diagnostics-only. Refill decisions use bladeFillIsBroken.
        local brokenOffset = tonumber(Config.V96BladeBrokenOffset) or -0.12
        local ratio = math.clamp((fillOffset - brokenOffset) / math.max(0.01, 1 - brokenOffset), 0, 1)
        local estimated = math.clamp(math.ceil(ratio * maximum), 1, maximum)
        return estimated, maximum
    end

    -- Compatibility fallback for game variants that restore an actual text counter.
    local bladesRoot = getTrustedBladesHudRoot()

    if cachedBladeCounter
        and cachedBladeCounter:IsDescendantOf(playerGui)
        and bladesRoot
        and cachedBladeCounter:IsDescendantOf(bladesRoot) then

        local current, maximum = parseBladeCounterText(getCounterObjectText(cachedBladeCounter))
        if current ~= nil then
            return current, maximum
        end
    end

    cachedBladeCounter = nil
    cachedBladeCounter = findBladeCounter()
    if not cachedBladeCounter then
        return nil, nil
    end

    return parseBladeCounterText(getCounterObjectText(cachedBladeCounter))
end

local function readBladeSets()
    local bladesRoot = getTrustedBladesHudRoot()
    if not bladesRoot then
        return nil, nil
    end

    if cachedBladeSetCounter
        and cachedBladeSetCounter:IsDescendantOf(playerGui)
        and cachedBladeSetCounter:IsDescendantOf(bladesRoot) then

        local current, maximum = parseBladeSetCounterText(getCounterObjectText(cachedBladeSetCounter))
        if current ~= nil then
            return current, maximum
        end
    end

    cachedBladeSetCounter = nil

    local bestObject = nil
    local bestScore = -math.huge

    local function consider(object)
        local textValue = getCounterObjectText(object)
        if textValue == nil then return end

        local current, maximum = parseBladeSetCounterText(textValue)
        if current == nil then return end

        local score = 0
        local lowerName = string.lower(tostring(object.Name or ""))
        if string.find(lowerName, "set", 1, true) then score += 40 end
        if string.find(lowerName, "stock", 1, true) then score += 30 end
        if string.find(lowerName, "blade", 1, true) then score += 10 end

        local node = object.Parent
        for _ = 1, 5 do
            if not node or node == bladesRoot.Parent then break end
            local lower = string.lower(tostring(node.Name or ""))
            if string.find(lower, "set", 1, true) then score += 25 end
            if string.find(lower, "blade", 1, true) then score += 8 end
            node = node.Parent
        end

        if score > bestScore then
            bestScore = score
            bestObject = object
        end
    end

    -- Prefer the known Sets subtree, whether it is itself text or contains a text child.
    local directSets = bladesRoot:FindFirstChild("Sets", true)
    if directSets then
        consider(directSets)
        for _, object in ipairs(directSets:GetDescendants()) do
            consider(object)
        end
    end

    if not bestObject then
        consider(bladesRoot)
        for _, object in ipairs(bladesRoot:GetDescendants()) do
            consider(object)
        end
    end

    if not bestObject then
        return nil, nil
    end

    cachedBladeSetCounter = bestObject
    local path = bestObject:GetFullName()
    if BladeDiag.LastSetSource ~= path then
        BladeDiag.LastSetSource = path
        print("[SliceHub V3][AMMO] set source ->", path)
    end

    return parseBladeSetCounterText(getCounterObjectText(bestObject))
end

local function findGasStationPart()
	-- v102: use the confirmed AOT refill path first. The old scorer could pick a random "Refill" part.
	local direct = resolvePath(Workspace, {"Climbable", "_Walls", "Gate", "GasTanks", "Refill"})
	if direct and direct:IsA("BasePart") then
		StationRefill.LastStationPart = direct
		return direct
	end

	if StationRefill.LastStationPart and StationRefill.LastStationPart.Parent then return StationRefill.LastStationPart end
	local bestPart, bestScore = nil, -math.huge
	for _, object in ipairs(Workspace:GetDescendants()) do
		if object:IsA("BasePart") then
			local lowerName = string.lower(object.Name)
			local score = lowerName == "refill" and 60 or 0
			local node = object.Parent
			for _ = 1, 8 do
				if not node then break end
				local lower = string.lower(tostring(node.Name or ""))
				if string.find(lower, "gastank", 1, true) or string.find(lower, "gas", 1, true) then score += 18 end
				if string.find(lower, "station", 1, true) or string.find(lower, "supply", 1, true) then score += 10 end
				node = node.Parent
			end
			if score > bestScore then bestScore = score; bestPart = object end
		end
	end
	StationRefill.LastStationPart = bestPart
	return bestPart
end

function stationRefillKeyHold()
    local key = Config.AutoRefillKey or Enum.KeyCode.R
    local holdTime = math.max(0.08, tonumber(Config.StationRefillHoldTime) or 0.42)
    local usedExecutorKey = type(keypress) == "function" and type(keyrelease) == "function"

    if usedExecutorKey then
        pcall(function() keypress(key.Value or key) end)
    else
        pcall(function() VirtualInputManager:SendKeyEvent(true, key, false, game) end)
    end

    task.wait(holdTime)

    if usedExecutorKey then
        pcall(function() keyrelease(key.Value or key) end)
    else
        pcall(function() VirtualInputManager:SendKeyEvent(false, key, false, game) end)
    end
end

V51AdaptiveRefill = V51AdaptiveRefill or {
    RemoteFailures = 0,
    StationCyclesSinceTest = 0,
    SkipRemoteUntilCycle = 0,
    Status = "Learning",
}

function V51AdaptiveRefill.ShouldTestRemote()
    if V51AdaptiveRefill.RemoteFailures < 2 then return true end
    return V51AdaptiveRefill.StationCyclesSinceTest >= 3
end

function V51AdaptiveRefill.MarkRemoteSuccess()
    V51AdaptiveRefill.RemoteFailures = 0
    V51AdaptiveRefill.StationCyclesSinceTest = 0
    V51AdaptiveRefill.Status = "Remote refill learned: working"
end

function V51AdaptiveRefill.MarkRemoteFailure()
    V51AdaptiveRefill.RemoteFailures += 1
    V51AdaptiveRefill.StationCyclesSinceTest = 0
    V51AdaptiveRefill.Status = V51AdaptiveRefill.RemoteFailures >= 2
        and "Skipping remote preflight for 3 station cycles"
        or "Remote preflight failed once"
end

V52RefillSafety = V52RefillSafety or {
    Phase = "Idle",
    HoldCFrame = nil,
    Active = false,
    StartedAt = 0,
}

function V52RefillSafety.SetPhase(phase)
    V52RefillSafety.Phase = tostring(phase or "Idle")
    if V51AdaptiveRefill then
        V51AdaptiveRefill.Status = "Refill hold: " .. V52RefillSafety.Phase
    end
end

function V96BladeBackgroundRefill.Start(holdCFrame)
    if Config.V96BladeBackgroundRefillEnabled ~= true or typeof(holdCFrame) ~= "CFrame" then
        return false
    end

    V96BladeBackgroundRefill.Serial += 1
    local serial = V96BladeBackgroundRefill.Serial
    V96BladeBackgroundRefill.Active = true
    V96BladeBackgroundRefill.HoldCFrame = holdCFrame
    V96BladeBackgroundRefill.Status = "HOLDING COMBAT POSITION"
    V52RefillSafety.Active = true
    V52RefillSafety.HoldCFrame = holdCFrame
    V52RefillSafety.SetPhase("BLADE BACKGROUND HOLD")

    task.spawn(function()
        while V96BladeBackgroundRefill.Active
            and V96BladeBackgroundRefill.Serial == serial do
            pcall(function()
                if character and character.Parent
                    and rootPart and rootPart.Parent
                    and typeof(V96BladeBackgroundRefill.HoldCFrame) == "CFrame" then

                    character:PivotTo(V96BladeBackgroundRefill.HoldCFrame)
                    rootPart.Anchored = false
                    rootPart.AssemblyLinearVelocity = Vector3.zero
                    rootPart.AssemblyAngularVelocity = Vector3.zero

                    if humanoid and humanoid.Parent then
                        humanoid.PlatformStand = false
                        humanoid.Sit = false
                        humanoid.AutoRotate = true
                        local state = humanoid:GetState()
                        if state == Enum.HumanoidStateType.FallingDown
                            or state == Enum.HumanoidStateType.Ragdoll
                            or state == Enum.HumanoidStateType.PlatformStanding then
                            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
                        end
                    end
                end
            end)
            task.wait(math.max(0.015, tonumber(Config.V96BladeBackgroundHoldInterval) or 0.025))
        end
    end)

    return true
end

function V96BladeBackgroundRefill.Stop(reason)
    V96BladeBackgroundRefill.Active = false
    V96BladeBackgroundRefill.Serial += 1
    V96BladeBackgroundRefill.HoldCFrame = nil
    V96BladeBackgroundRefill.Status = tostring(reason or "IDLE")

    pcall(function()
        if rootPart and rootPart.Parent then
            rootPart.Anchored = false
            rootPart.AssemblyLinearVelocity = Vector3.zero
            rootPart.AssemblyAngularVelocity = Vector3.zero
        end
        if humanoid and humanoid.Parent then
            humanoid.PlatformStand = false
            humanoid.Sit = false
            humanoid.AutoRotate = true
        end
    end)

    V52RefillSafety.Active = false
    V52RefillSafety.HoldCFrame = nil
    V52RefillSafety.SetPhase("Idle")
end

function V917BladeStationRecovery.RememberFarmCFrame()
    if Config.V917BladeStationRecoveryEnabled ~= true
        or V917BladeStationRecovery.Active
        or (StationRefill and StationRefill.Running)
        or State.FarmEnabled ~= true
        or State.BladesEnabled ~= true
        or not character
        or not character.Parent
        or not rootPart
        or not rootPart.Parent
        or not humanoid
        or humanoid.Health <= 0 then
        return false
    end

    local state = humanoid:GetState()
    if state == Enum.HumanoidStateType.Freefall
        or state == Enum.HumanoidStateType.FallingDown
        or state == Enum.HumanoidStateType.Ragdoll
        or state == Enum.HumanoidStateType.Dead then
        return false
    end

    V917BladeStationRecovery.SavedFarmCFrame = rootPart.CFrame
    V917BladeStationRecovery.SavedFarmAt = os.clock()
    return true
end

function V917BladeStationRecovery.GetSavedFarmCFrame(fallback)
    local saved = V917BladeStationRecovery.SavedFarmCFrame
    local age = os.clock() - (tonumber(V917BladeStationRecovery.SavedFarmAt) or 0)
    local maximumAge = math.max(
        1.0,
        tonumber(Config.V917BladeFarmSnapshotMaxAge) or 8.0
    )

    if typeof(saved) == "CFrame" and age <= maximumAge then
        return saved
    end

    return typeof(fallback) == "CFrame" and fallback or nil
end

function V917BladeStationRecovery.SetHoldCFrame(targetCFrame, status)
    if not V917BladeStationRecovery.Active
        or typeof(targetCFrame) ~= "CFrame" then
        return false
    end

    V917BladeStationRecovery.HoldCFrame = targetCFrame
    V917BladeStationRecovery.Status = tostring(status or "HOLDING")

    local heldCharacter = V917BladeStationRecovery.HoldCharacter
    local heldRoot = V917BladeStationRecovery.HoldRoot

    if not heldCharacter
        or not heldCharacter.Parent
        or not heldRoot
        or not heldRoot.Parent then
        return false
    end

    pcall(function()
        heldCharacter:PivotTo(targetCFrame)
        heldRoot.Anchored = true
        heldRoot.AssemblyLinearVelocity = Vector3.zero
        heldRoot.AssemblyAngularVelocity = Vector3.zero
    end)

    return true
end

function V917BladeStationRecovery.Start(fallbackCFrame)
    if Config.V917BladeStationRecoveryEnabled ~= true
        or V917BladeStationRecovery.Active
        or not character
        or not character.Parent
        or not rootPart
        or not rootPart.Parent
        or not humanoid
        or humanoid.Health <= 0 then
        return false
    end

    local savedCFrame =
        V917BladeStationRecovery.GetSavedFarmCFrame(fallbackCFrame)

    if typeof(savedCFrame) ~= "CFrame" then
        return false
    end

    V917BladeStationRecovery.Serial += 1
    local serial = V917BladeStationRecovery.Serial
    V917BladeStationRecovery.Active = true
    V917BladeStationRecovery.HoldCharacter = character
    V917BladeStationRecovery.HoldRoot = rootPart
    V917BladeStationRecovery.HoldCFrame = savedCFrame
    V917BladeStationRecovery.SavedFarmCFrame = savedCFrame
    V917BladeStationRecovery.SavedFarmAt = os.clock()
    V917BladeStationRecovery.Status = "PAUSED • SAVED FARM POSITION"
    V917BladeStationRecovery.LastResult = "RUNNING"

    V52RefillSafety.Active = true
    V52RefillSafety.StartedAt = os.clock()
    V52RefillSafety.HoldCFrame = savedCFrame
    V52RefillSafety.SetPhase("BLADE STATION RECOVERY")

    V917BladeStationRecovery.SetHoldCFrame(
        savedCFrame,
        "PAUSED • SAVED FARM POSITION"
    )

    task.spawn(function()
        while V917BladeStationRecovery.Active
            and V917BladeStationRecovery.Serial == serial do

            local heldCharacter = V917BladeStationRecovery.HoldCharacter
            local heldRoot = V917BladeStationRecovery.HoldRoot
            local holdCFrame = V917BladeStationRecovery.HoldCFrame

            if character ~= heldCharacter
                or rootPart ~= heldRoot
                or not heldCharacter
                or not heldCharacter.Parent
                or not heldRoot
                or not heldRoot.Parent
                or not humanoid
                or humanoid.Health <= 0 then

                local abortReason =
                    humanoid
                    and humanoid.Health <= 0
                    and "ABORTED • CHARACTER DIED"
                    or "ABORTED • CHARACTER CHANGED"

                V917BladeStationRecovery.Stop(
                    abortReason,
                    true
                )
                break
            end

            pcall(function()
                if typeof(holdCFrame) == "CFrame" then
                    heldRoot.Anchored = true

                    -- Anchored roots do not need a full Model:PivotTo on every
                    -- guard tick. Recommit only after meaningful drift.
                    local positionDrift =
                        (heldRoot.Position - holdCFrame.Position).Magnitude
                    local lookDrift =
                        (heldRoot.CFrame.LookVector - holdCFrame.LookVector).Magnitude

                    if positionDrift > 0.08 or lookDrift > 0.02 then
                        heldRoot.CFrame = holdCFrame
                    end

                    heldRoot.AssemblyLinearVelocity = Vector3.zero
                    heldRoot.AssemblyAngularVelocity = Vector3.zero
                    V52RefillSafety.HoldCFrame = holdCFrame
                end

                humanoid.PlatformStand = false
                humanoid.Sit = false
                humanoid.AutoRotate = true
            end)

            if State.AutoRefillEnabled ~= true
                or State.BladesEnabled ~= true then
                V917BladeStationRecovery.Stop(
                    "CANCELLED • BLADE REFILL DISABLED",
                    true
                )
                break
            end

            task.wait(0.05)
        end
    end)

    return true
end

function V917BladeStationRecovery.Stop(reason, releasePosition)
    local heldRoot = V917BladeStationRecovery.HoldRoot

    V917BladeStationRecovery.Active = false
    V917BladeStationRecovery.Serial += 1
    V917BladeStationRecovery.HoldCFrame = nil
    V917BladeStationRecovery.HoldCharacter = nil
    V917BladeStationRecovery.HoldRoot = nil
    V917BladeStationRecovery.Status = tostring(reason or "IDLE")
    V917BladeStationRecovery.LastResult =
        V917BladeStationRecovery.Status

    if releasePosition ~= false then
        pcall(function()
            if heldRoot and heldRoot.Parent then
                heldRoot.Anchored = false
                heldRoot.AssemblyLinearVelocity = Vector3.zero
                heldRoot.AssemblyAngularVelocity = Vector3.zero
            end
        end)
    end

    V52RefillSafety.Active = false
    V52RefillSafety.HoldCFrame = nil
    V52RefillSafety.SetPhase("Idle")
end

function V917BladeStationRecovery.RefillPromptVisible()
    if not playerGui then
        return false
    end

    for _, object in ipairs(playerGui:GetDescendants()) do
        if object:IsA("TextLabel")
            or object:IsA("TextButton")
            or object:IsA("TextBox") then

            local visible = object.Visible == true
                and object.AbsoluteSize.X > 0
                and object.AbsoluteSize.Y > 0

            if visible then
                local text = string.lower(tostring(object.Text or ""))
                text = string.gsub(text, "<.->", "")
                text = string.gsub(text, "%s+", " ")

                if string.find(text, "refills", 1, true)
                    and (
                        string.find(text, "[r]", 1, true)
                        or string.find(text, "refill", 1, true)
                    ) then
                    return true
                end
            end
        end
    end

    return false
end

function V917BladeStationRecovery.InvokeExactStationReload(station)
    if not station or not station.Parent then
        return false, nil, "Refill station missing"
    end

    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("GET")

    if not remote or not remote:IsA("RemoteFunction") then
        return false, nil,
            "ReplicatedStorage.Assets.Remotes.GET missing"
    end

    local called = table.pack(pcall(function()
        return remote:InvokeServer(
            "Attacks",
            "Reload",
            station
        )
    end))

    if not called[1] then
        V917BladeStationRecovery.LastStationError =
            tostring(called[2])
        return false, nil, tostring(called[2])
    end

    V917BladeStationRecovery.LastStationResponse = called[2]
    V917BladeStationRecovery.LastStationError = nil
    return true, called[2], nil
end

function V917BladeStationRecovery.VerifyUsableBladeAfterRestock()
    local beforeFill, beforeSets =
        V96BladeReloadCore.ReadFresh()

    if beforeFill ~= nil
        and not bladeFillIsBroken(beforeFill) then
        return true, false, beforeFill, beforeSets, nil
    end

    if beforeSets == nil or beforeSets <= 0 then
        return false, false, beforeFill, beforeSets,
            "No spare blade set after station refill"
    end

    local serial, transactionError =
        V918BladeRecoveryTransaction.Begin(
            "POST_STATION",
            beforeSets
        )

    if not serial then
        return false, false, beforeFill, beforeSets,
            tostring(transactionError or "Blade recovery transaction busy")
    end

    local finalFill = beforeFill
    local finalSets = beforeSets
    local reloadAttempted = true
    local invokeOk, response, invokeError =
        V96BladeReloadCore.InvokeExact()

    V917BladeStationRecovery.LastPostReloadResponse =
        response
    V917BladeStationRecovery.LastPostReloadError =
        invokeError
    V917BladeStationRecovery.Status =
        "POST-STATION BLADES/RELOAD • OBSERVING"

    V94RunRecorder.Record(
        "BLADE_RELOAD",
        "POST-STATION SINGLE ATTEMPT",
        {
            serial = serial,
            ok = invokeOk,
            response = tostring(response),
            error = tostring(invokeError),
            beforeFill = beforeFill,
            beforeSets = beforeSets,
        }
    )

    local observeSeconds = math.max(
        1.20,
        tonumber(
            Config.V918BladeTransactionObserveSeconds
        ) or 3.20
    )
    local observeUntil = os.clock() + observeSeconds
    local accepted = response == true

    repeat
        task.wait(0.05)

        if not V918BladeRecoveryTransaction.IsCurrent(serial) then
            break
        end

        finalFill, finalSets =
            V96BladeReloadCore.ReadFresh()

        if finalFill ~= nil
            and not bladeFillIsBroken(finalFill) then
            break
        end

        if finalSets ~= nil
            and finalSets < beforeSets then
            accepted = true
        end
    until os.clock() >= observeUntil

    finalFill, finalSets =
        V96BladeReloadCore.ReadFresh()

    local usable = finalFill ~= nil
        and not bladeFillIsBroken(finalFill)
    local spent = beforeSets ~= nil
        and finalSets ~= nil
        and math.max(0, beforeSets - finalSets)
        or 0

    local result = usable
        and "POST-STATION BLADE READY"
        or (
            spent > 1
            and "POST-STATION MULTI-SET LOSS"
            or (
                accepted
                and "POST-STATION ACCEPTED • FILL PENDING"
                or "POST-STATION NO CHANGE"
            )
        )

    V918BladeRecoveryTransaction.Finish(
        serial,
        result,
        finalSets,
        usable
    )

    if spent > 1 then
        return false, reloadAttempted, finalFill, finalSets,
            "Multiple blade sets disappeared during one recovery"
    end

    return usable,
        reloadAttempted,
        finalFill,
        finalSets,
        usable and nil or (
            accepted
            and "Blade renewal accepted but fill remained broken"
            or tostring(invokeError or "Current blade remained broken")
        )
end

local beginBladeRefill
local activateNativeMobileRefillButton

local function beginStationRefill(reason, manual, refillMode, targetAmmo)
    local requestedMode = tostring(refillMode or "Blades")
	if StationRefill.Running then return false end
    if V912BladeRenewAuthority and V912BladeRenewAuthority.Active then
        return false
    end
    if V918BladeRecoveryTransaction and V918BladeRecoveryTransaction.Active then
        return false
    end
    if requestedMode == "Blades"
        and Config.V93BladeAmmoDirectorEnabled == true
        and V93BladeAmmoDirector.StationExhausted == true then
        local now = os.clock()
        local retryAt = tonumber(V93BladeAmmoDirector.StationRetryAfter) or 0
        if now < retryAt then
            V93BladeAmmoDirector.BladelessHold = true
            V93BladeAmmoDirector.Status = string.format("STATION RETRY HOLD • %.1fs", math.max(0, retryAt - now))
            statusText = V93BladeAmmoDirector.Status
            return false
        end

        -- V9.5: station failure is no longer a permanent mission-long death sentence.
        V93BladeAmmoDirector.StationExhausted = false
        V93BladeAmmoDirector.BladelessHold = false
        bladeRefillArmed = true
        V93BladeAmmoDirector.Status = "STATION RETRY REARMED"
    end
	local station = findGasStationPart()
	if not station and requestedMode ~= "Blades" then
		if manual then showNotification("Refill failed", "No GasTanks.Refill part found.", "error") end
		return false
	end
	if not character or not character.Parent or not rootPart then
		if manual then showNotification("Refill failed", "Character/root not ready.", "error") end
		return false
	end
	StationRefill.Running = true
	StationRefill.LastReason = tostring(reason or "station refill")
    StationRefill.Mode = requestedMode
    StationRefill.TargetAmmo = tonumber(targetAmmo)
	task.spawn(function()
		local resumeFarm = State.FarmEnabled == true
        local postStationBladeRenew = false
        local bladeStationRefillVerified = false
        local bladeStationBladeUsable = false
        local bladeStationPostReloadAttempted = false
        local bladeStationFinalFill = nil
        local bladeStationFinalSets = nil
        local bladeStationRenewError = nil
        local bladeStationActionStarted = false
        local bladeStationReturnedAfterStart = false
        local bladeStationStartSignal = nil
        local preRefillCFrame = nil
        local preRefillCameraSubject = nil
        local preRefillCameraType = nil

        pcall(function()
            local liveCFrame = rootPart and rootPart.CFrame or nil
            if StationRefill.Mode == "Blades"
                and V917BladeStationRecovery
                and type(V917BladeStationRecovery.GetSavedFarmCFrame)
                    == "function" then
                preRefillCFrame =
                    V917BladeStationRecovery.GetSavedFarmCFrame(
                        liveCFrame
                    )
            else
                preRefillCFrame = liveCFrame
            end
        end)

        pcall(function()
            local camera = Workspace.CurrentCamera
            if camera then
                preRefillCameraSubject = camera.CameraSubject
                preRefillCameraType = camera.CameraType
            end
        end)

        local spearHoldCFrame = preRefillCFrame
        local spearHoverActive = StationRefill.Mode == "Spears" and typeof(spearHoldCFrame) == "CFrame"
        local bladeBackgroundHoldActive = StationRefill.Mode == "Blades"
            and Config.V917BladeStationRecoveryEnabled == true
            and typeof(preRefillCFrame) == "CFrame"
            and V917BladeStationRecovery.Start(preRefillCFrame) == true

        if spearHoverActive then
            -- V5.2: the refill pipeline owns the character from trigger until combat has
            -- resumed. Gravity never gets a free frame between PRELIGHT/RELOAD/RETURN.
            V52RefillSafety.Active = true
            V52RefillSafety.StartedAt = os.clock()
            V52RefillSafety.HoldCFrame = spearHoldCFrame
            V52RefillSafety.SetPhase("HOVER HOLD")

            pcall(function()
                if rootPart and rootPart.Parent then
                    rootPart.Anchored = true
                    rootPart.AssemblyLinearVelocity = Vector3.zero
                    rootPart.AssemblyAngularVelocity = Vector3.zero
                end
            end)

            task.spawn(function()
                while spearHoverActive and StationRefill.Running do
                    pcall(function()
                        if character and character.Parent
                            and rootPart and rootPart.Parent
                            and typeof(spearHoldCFrame) == "CFrame" then

                            character:PivotTo(spearHoldCFrame)
                            rootPart.Anchored = true
                            rootPart.AssemblyLinearVelocity = Vector3.zero
                            rootPart.AssemblyAngularVelocity = Vector3.zero
                            V52RefillSafety.HoldCFrame = spearHoldCFrame
                        end
                    end)
                    task.wait(0.02)
                end
            end)
        end

		State.FarmEnabled = false
        if StationRefill.Mode == "Spears" then
            clearCurrentTarget(false)
            speedPulseForward = false
            CombatAnchorRuntime.Position = nil
            CombatAnchorRuntime.GroundCenter = nil
            CombatAnchorRuntime.AimPosition = nil
            CombatAnchorRuntime.TargetCount = 0
            CombatAnchorRuntime.PulseUntil = 0
            CombatAnchorRuntime.PulseSerial += 1
        elseif bladeBackgroundHoldActive then
            -- V9.8.4: releaseCombatLock intentionally pushes the
            -- player downward. The 0/3 recovery owns movement instead,
            -- so clear combat state without ever releasing gravity.
            clearCurrentTarget(false)
            speedPulseForward = false
            CombatAnchorRuntime.Position = nil
            CombatAnchorRuntime.GroundCenter = nil
            CombatAnchorRuntime.AimPosition = nil
            CombatAnchorRuntime.TargetCount = 0
            CombatAnchorRuntime.PulseUntil = 0
            CombatAnchorRuntime.PulseSerial += 1
            State.IsGrabbed = false

            pcall(function()
                if rootPart and rootPart.Parent then
                    rootPart.Anchored = true
                    rootPart.AssemblyLinearVelocity =
                        Vector3.zero
                    rootPart.AssemblyAngularVelocity =
                        Vector3.zero
                end
            end)
        else
		    releaseCombatLock()
        end
		statusText = "Gas station refill: " .. StationRefill.LastReason


		local function readAnyAmmo()
            if StationRefill.Mode == "Spears" then
                local spearValue = nil
                pcall(function()
                    spearValue = V35Spears and V35Spears.ReadAmmo and V35Spears.ReadAmmo() or nil
                end)
                return tonumber(spearValue)
            end

			local bladeValue = nil
			pcall(function() bladeValue = select(1, readBladeSets()) end)
			return bladeValue
		end

        local function targetReached(value)
            if StationRefill.Mode ~= "Spears" then
                return false
            end

            local target = math.max(1, math.floor(tonumber(StationRefill.TargetAmmo) or 8))
            return tonumber(value) ~= nil and tonumber(value) >= target
        end

        local function returnFromSpearRefill()
            if StationRefill.Mode ~= "Spears" then
                return true
            end

            if not character or not character.Parent or not rootPart or not rootPart.Parent then
                return false
            end

            local returnCFrame = preRefillCFrame
            local targetPosition = nil
            local targetPart = nil
            local packCount = 0

            pcall(function()
                if V35Spears and V35Spears.GetBestCluster then
                    targetPosition, targetPart, packCount = V35Spears.GetBestCluster()
                end
            end)

            if typeof(targetPosition) == "Vector3" then
                local height = tonumber(Config.SpearSkyHeight) or 430
                local returnPosition = targetPosition + Vector3.new(0, height, 0)
                local lookAt = targetPosition

                if (lookAt - returnPosition).Magnitude > 0.1 then
                    returnCFrame = CFrame.lookAt(returnPosition, lookAt)
                else
                    returnCFrame = CFrame.new(returnPosition)
                end

                print(
                    "[SliceHub V3.6][TS-RETURN]",
                    "fresh pack=" .. tostring(packCount),
                    "height=" .. tostring(height)
                )
            else
                print(
                    "[SliceHub V3.6][TS-RETURN]",
                    "no fresh pack; using pre-refill position"
                )
            end

            if typeof(returnCFrame) ~= "CFrame" then
                return false
            end

            local okReturn = pcall(function()
                character:PivotTo(returnCFrame)

                rootPart.Anchored = true
                rootPart.AssemblyLinearVelocity = Vector3.zero
                rootPart.AssemblyAngularVelocity = Vector3.zero

                if humanoid then
                    humanoid.PlatformStand = false
                    humanoid.Sit = false
                    humanoid.AutoRotate = true
                end

                spearHoldCFrame = returnCFrame
                V52RefillSafety.SetPhase("RETURN HOLD")
            end)

            task.wait(0.12)

            pcall(function()
                local camera = Workspace.CurrentCamera
                if camera then
                    camera.CameraType = Enum.CameraType.Custom

                    if humanoid and humanoid.Parent then
                        camera.CameraSubject = humanoid
                    elseif preRefillCameraSubject then
                        camera.CameraSubject = preRefillCameraSubject
                    end
                end
            end)

            pcall(function()
                clearCurrentTarget(false)

                CombatAnchorRuntime.Position = nil
                CombatAnchorRuntime.GroundCenter = nil
                CombatAnchorRuntime.AimPosition = nil
                CombatAnchorRuntime.TargetCount = 0
                CombatAnchorRuntime.LastRefresh = 0
                CombatAnchorRuntime.PulseUntil = 0
                CombatAnchorRuntime.PulseSerial += 1
            end)

            return okReturn == true
        end

		local beforeAmmo = readAnyAmmo()
        if StationRefill.Mode == "Blades" and Config.V93BladeAmmoDirectorEnabled == true then
            V93BladeAmmoDirector.LastStationBeforeSets = beforeAmmo
            V93BladeAmmoDirector.Status = "STATION VERIFY • BEFORE " .. tostring(beforeAmmo) .. "/" .. tostring(Config.BladeSetMaximum)
        end

		pcall(function()
			if rootPart then
                rootPart.Anchored = StationRefill.Mode == "Spears"
                    or bladeBackgroundHoldActive
				rootPart.AssemblyLinearVelocity = Vector3.zero
				rootPart.AssemblyAngularVelocity = Vector3.zero
			end
			if humanoid then
				humanoid.PlatformStand = false
				humanoid.Sit = false
				humanoid.AutoRotate = true
                if StationRefill.Mode ~= "Spears" then
                    humanoid:ChangeState(Enum.HumanoidStateType.Running)
                end
			end
		end)

		local function groundAt(pos)
			local params = RaycastParams.new()
			params.FilterType = Enum.RaycastFilterType.Blacklist
			params.FilterDescendantsInstances = character and {character} or {}
			local result = Workspace:Raycast(pos + Vector3.new(0, 35, 0), Vector3.new(0, -90, 0), params)
			if result and result.Position then
				return result.Position + Vector3.new(0, 3.1, 0)
			end
			return pos
		end

		local function spotList()
			local dist = math.max(0.75, tonumber(Config.StationRefillSpotDistance) or 1.8)
			local sx, sz = 2, 2
			pcall(function()
				sx = math.max(1.5, station.Size.X * 0.5)
				sz = math.max(1.5, station.Size.Z * 0.5)
			end)
			local raw = {
				-- close edge spots: prompt range without burying inside the tank
				(station.CFrame * CFrame.new(0, 0, -(sz + dist))).Position,
				(station.CFrame * CFrame.new(0, 0, sz + dist)).Position,
				(station.CFrame * CFrame.new(-(sx + dist), 0, 0)).Position,
				(station.CFrame * CFrame.new(sx + dist, 0, 0)).Position,
				-- touch-zone fallbacks: some servers only show [R] when the root is basically touching
				(station.CFrame * CFrame.new(0, 1.5, -(sz + 0.35))).Position,
				(station.CFrame * CFrame.new(0, 1.5, sz + 0.35)).Position,
				(station.CFrame * CFrame.new(-(sx + 0.35), 1.5, 0)).Position,
				(station.CFrame * CFrame.new(sx + 0.35, 1.5, 0)).Position,
				station.Position + Vector3.new(0, 2.8, 0),
			}
			local list = {}
			for _, pos in ipairs(raw) do
				table.insert(list, groundAt(pos))
			end
			return list
		end

		local function faceStation()
			pcall(function()
				if rootPart then
					local p = rootPart.Position
					local look = Vector3.new(station.Position.X, p.Y, station.Position.Z)
					if (look - p).Magnitude > 0.1 then
						rootPart.CFrame = CFrame.lookAt(p, look)
					end
				end
			end)
		end

		local function moveToSpot(pos)
			if not humanoid or not rootPart then return false end

            if StationRefill.Mode == "Blades"
                and bladeBackgroundHoldActive then
                local look = Vector3.new(
                    station.Position.X,
                    pos.Y,
                    station.Position.Z
                )
                local targetCFrame = (look - pos).Magnitude > 0.1
                    and CFrame.lookAt(pos, look)
                    or CFrame.new(pos)

                V52RefillSafety.SetPhase("BLADE STATION APPROACH")
                local moved =
                    V917BladeStationRecovery.SetHoldCFrame(
                        targetCFrame,
                        "AT REFILL STATION"
                    )

                task.wait(
                    math.max(
                        0.10,
                        tonumber(
                            Config.V917BladeStationArrivalSettleSeconds
                        ) or 0.22
                    )
                )

                if moved and rootPart and rootPart.Parent then
                    faceStation()
                    return (rootPart.Position - pos).Magnitude <= 4.0
                end

                return false
            end

            if StationRefill.Mode == "Spears" then
                V52RefillSafety.SetPhase("STATION APPROACH")
                local hoverOffset = Vector3.new(0, 7.5, 0)
                local holdPosition = pos + hoverOffset
                local look = Vector3.new(station.Position.X, holdPosition.Y, station.Position.Z)
                spearHoldCFrame = (look - holdPosition).Magnitude > 0.1
                    and CFrame.lookAt(holdPosition, look)
                    or CFrame.new(holdPosition)

                pcall(function()
                    character:PivotTo(spearHoldCFrame)
                    rootPart.Anchored = true
                    rootPart.AssemblyLinearVelocity = Vector3.zero
                    rootPart.AssemblyAngularVelocity = Vector3.zero
                end)

                task.wait(0.10)
                return rootPart and rootPart.Parent and (rootPart.Position - holdPosition).Magnitude <= 3.5
            end

			pcall(function()
				rootPart.Anchored = false
				rootPart.AssemblyLinearVelocity = Vector3.zero
				rootPart.AssemblyAngularVelocity = Vector3.zero
			end)
			pcall(function() humanoid:MoveTo(pos) end)
			local started = os.clock()
			local timeout = tonumber(Config.StationRefillMoveTimeout) or 2.6
			while os.clock() - started < timeout do
				if not rootPart or not rootPart.Parent then return false end
				faceStation()
				if (rootPart.Position - pos).Magnitude <= 5.5 then return true end
				task.wait(0.05)
			end

            -- V9.6: both blade and spear farms can leave the character far above or
            -- away from the station. Snap only after normal MoveTo has genuinely failed.
            if character
                and character.Parent
                and rootPart
                and rootPart.Parent then

                pcall(function()
                    local look = Vector3.new(
                        station.Position.X,
                        pos.Y,
                        station.Position.Z
                    )

                    character:PivotTo(CFrame.lookAt(pos, look))
                    rootPart.Anchored = StationRefill.Mode == "Spears"
                    rootPart.AssemblyLinearVelocity = Vector3.zero
                    rootPart.AssemblyAngularVelocity = Vector3.zero
                end)

                task.wait(0.16)

                if rootPart and rootPart.Parent then
                    faceStation()
                    return (rootPart.Position - pos).Magnitude <= 8.5
                end
            end

			return false
		end

        local skipStationMovement = false

        -- V9.8.4: runtime testing proved that the native
        -- blade restock is rejected away from the refill station.
        -- Skip all same-position attempts and go directly to the
        -- anchored station visit below.

        if StationRefill.Mode == "Spears" and V51AdaptiveRefill.ShouldTestRemote() then
            local preflightBefore = readAnyAmmo()

            statusText = "TS safety refill: adaptive remote preflight"

            if V35Spears and V35Spears.DirectReload then
                V35Spears.DirectReload(station)
            end

            local preflightStarted = os.clock()
            local lastSeenAmmo = preflightBefore

            repeat
                task.wait(0.06)

                local liveAmmo = readAnyAmmo()

                if liveAmmo ~= nil then
                    lastSeenAmmo = liveAmmo
                end

                print(
                    "[SliceHub V3.6.1][TS-PREFLIGHT]",
                    "ammo=" .. tostring(liveAmmo),
                    "target=" .. tostring(math.floor(tonumber(StationRefill.TargetAmmo) or 8))
                )

                if targetReached(liveAmmo) then
                    skipStationMovement = true
                    break
                end

                if preflightBefore ~= nil
                    and liveAmmo ~= nil
                    and liveAmmo > preflightBefore then

                    -- Reload was accepted remotely. Keep polling without moving the character.
                    local restoreStarted = os.clock()

                    repeat
                        task.wait(0.06)
                        liveAmmo = readAnyAmmo()

                        if targetReached(liveAmmo) then
                            skipStationMovement = true
                            break
                        end
                    until os.clock() - restoreStarted >= 2.2

                    if not skipStationMovement
                        and V35Spears
                        and V35Spears.DirectReload then

                        V35Spears.DirectReload(station)

                        local retryStarted = os.clock()
                        repeat
                            task.wait(0.06)
                            liveAmmo = readAnyAmmo()

                            if targetReached(liveAmmo) then
                                skipStationMovement = true
                                break
                            end
                        until os.clock() - retryStarted >= 1.6
                    end

                    break
                end
            until os.clock() - preflightStarted >= 0.55

            if skipStationMovement then
                V51AdaptiveRefill.MarkRemoteSuccess()
                statusText = "TS refill complete without station travel"
                print(
                    "[SliceHub V3.6.1][TS-PREFLIGHT]",
                    "remote refill succeeded; station movement skipped"
                )
            else
                V51AdaptiveRefill.MarkRemoteFailure()
                print(
                    "[SliceHub V3.6.1][TS-PREFLIGHT]",
                    "no remote ammo increase; using station fallback"
                )
            end
        elseif StationRefill.Mode == "Spears" then
            V51AdaptiveRefill.Status = "Adaptive skip: direct station fallback"
            V51AdaptiveRefill.StationCyclesSinceTest += 1
            print("[SliceHub V5.1][TS-ADAPTIVE] skipping remote preflight; station cycle", V51AdaptiveRefill.StationCyclesSinceTest, "/3")
        end

        if not skipStationMovement and not station then
            StationRefill.Running = false
            bladeRefillArmed = false
            V93BladeAmmoDirector.BladelessHold = true
            V93BladeAmmoDirector.Status =
                "STATION NOT FOUND • FARM PAUSED"
            V96BladeRefillController.Status =
                V93BladeAmmoDirector.Status
            statusText = V93BladeAmmoDirector.Status

            if bladeBackgroundHoldActive
                and typeof(preRefillCFrame) == "CFrame" then
                V917BladeStationRecovery.SetHoldCFrame(
                    preRefillCFrame,
                    "STATION NOT FOUND • FARM PAUSED"
                )
            end

            showNotification(
                "Blade refill paused",
                "The refill station was not found. Disable Auto Blade Refill to release the saved position.",
                "error"
            )
            return
        end

        if not skipStationMovement and bladeBackgroundHoldActive then
            V917BladeStationRecovery.Status =
                "TRAVELLING TO REFILL STATION"
            V52RefillSafety.SetPhase("BLADE STATION TRAVEL")
            task.wait(0.04)
        end

		local spots = skipStationMovement and {} or spotList()
        if not skipStationMovement then
            if StationRefill.Mode == "Spears" then
                V52RefillSafety.SetPhase("STATION FALLBACK")
            end
            task.wait(0.04)
		for index, pos in ipairs(spots) do
			statusText = "Gas station refill: spot " .. tostring(index)
			local reachedSpot = moveToSpot(pos)
            if not reachedSpot then
                continue
            end
			faceStation()
			task.wait(Config.StationRefillPressDelay or 0.16)

            local reachedTarget = false

            if StationRefill.Mode == "Spears" then
                V52RefillSafety.SetPhase("RELOAD POLLING")
                for reloadAttempt = 1, 3 do
                    if V35Spears and V35Spears.DirectReload then
                        V35Spears.DirectReload(station)
                    end

                    local pollStarted = os.clock()

                    repeat
                        task.wait(0.06)

                        local liveAmmo = readAnyAmmo()

                        print(
                            "[SliceHub V3.6][TS-RELOAD]",
                            "attempt=" .. tostring(reloadAttempt),
                            "ammo=" .. tostring(liveAmmo),
                            "target=" .. tostring(math.floor(tonumber(StationRefill.TargetAmmo) or 8))
                        )

                        if targetReached(liveAmmo) then
                            reachedTarget = true
                            statusText = "Gas station refill: Spears "
                                .. tostring(liveAmmo)
                                .. "/"
                                .. tostring(math.floor(tonumber(StationRefill.TargetAmmo) or 8))
                            break
                        end
                    until os.clock() - pollStarted >= 1.6

                    if reachedTarget then
                        break
                    end
                end
            else
                local bladeAttempts = math.clamp(
                    math.floor(
                        (
                            tonumber(
                                Config.V917BladeStationActionAttempts
                            )
                            or 4
                        )
                        + 0.5
                    ),
                    1,
                    6
                )
                local pollSeconds = math.max(
                    0.80,
                    tonumber(
                        Config.V96BladeStationPollSeconds
                    )
                    or 2.60
                )
                local actionPollSeconds = math.max(
                    0.55,
                    tonumber(
                        Config.V917BladeStationActionPollSeconds
                    )
                    or 1.35
                )
                local beforeSpotRefills =
                    readBladeRefillCharges()
                local beforeSpotSets = readAnyAmmo()

                -- V9.8.4: hold the 0/3 character at the exact
                -- station spot only until the refill action is accepted.
                -- Replication finishes after the immediate farm return.
                local bladeStationHoldActive = true
                local bladeStationHoldCFrame =
                    rootPart and rootPart.CFrame or nil

                if bladeBackgroundHoldActive
                    and typeof(bladeStationHoldCFrame) == "CFrame" then
                    V917BladeStationRecovery.SetHoldCFrame(
                        bladeStationHoldCFrame,
                        "AT REFILL STATION • WAITING FOR [R]"
                    )
                end

                task.spawn(function()
                    while bladeStationHoldActive
                        and StationRefill.Running do
                        pcall(function()
                            if character and character.Parent
                                and rootPart and rootPart.Parent
                                and typeof(
                                    bladeStationHoldCFrame
                                ) == "CFrame" then

                                character:PivotTo(
                                    bladeStationHoldCFrame
                                )
                                rootPart.Anchored = true
                                rootPart.AssemblyLinearVelocity =
                                    Vector3.zero
                                rootPart.AssemblyAngularVelocity =
                                    Vector3.zero

                                if humanoid
                                    and humanoid.Parent then
                                    humanoid.PlatformStand = false
                                    humanoid.Sit = false
                                    humanoid.AutoRotate = true
                                end
                            end
                        end)

                        task.wait(0.02)
                    end
                end)

                local function waitForBladeStationProgress(
                    seconds
                )
                    local started = os.clock()

                    repeat
                        task.wait(0.04)

                        local liveSets = readAnyAmmo()
                        local liveRefills =
                            readBladeRefillCharges()
                        local setsRestored =
                            liveSets ~= nil
                            and liveSets
                                >= Config.BladeSetMaximum
                        local chargeSpent =
                            beforeSpotRefills ~= nil
                            and liveRefills ~= nil
                            and liveRefills
                                < beforeSpotRefills
                        local setsIncreased =
                            beforeSpotSets ~= nil
                            and liveSets ~= nil
                            and liveSets > beforeSpotSets

                        if setsRestored then
                            return true, true, "SETS_FULL"
                        end

                        if chargeSpent then
                            -- The server accepted the refill. Do not wait
                            -- at the station for the HUD to reach 3/3.
                            return false, true, "REFILL_CHARGE_SPENT"
                        end

                        if setsIncreased then
                            -- Replication has started; immediately return
                            -- and finish observing it from the farm CFrame.
                            return false, true, "SETS_INCREASING"
                        end
                    until os.clock() - started >= seconds

                    return false, false, nil
                end

                local stationActionAccepted = false
                local exactTransportWorked = false
                local progressSignal = nil

                for refillAttempt = 1, bladeAttempts do
                    V917BladeStationRecovery.Status =
                        "EXACT STATION RELOAD "
                        .. tostring(refillAttempt)
                        .. "/"
                        .. tostring(bladeAttempts)

                    local invokeOk,
                        invokeResponse,
                        invokeError =
                            V917BladeStationRecovery
                                .InvokeExactStationReload(
                                    station
                                )

                    exactTransportWorked =
                        exactTransportWorked or invokeOk

                    V94RunRecorder.Record(
                        "BLADE_STATION",
                        "EXACT ATTACKS/RELOAD ATTEMPT",
                        {
                            attempt = refillAttempt,
                            maximumAttempts = bladeAttempts,
                            ok = invokeOk,
                            response = tostring(
                                invokeResponse
                            ),
                            error = tostring(invokeError),
                            station = tostring(
                                station and station:GetFullName()
                            ),
                            beforeRefills =
                                beforeSpotRefills,
                            beforeSets =
                                beforeSpotSets,
                        }
                    )

                    if invokeOk and invokeResponse == true then
                        stationActionAccepted = true
                        progressSignal = "REMOTE_TRUE"
                    else
                        reachedTarget,
                        stationActionAccepted,
                        progressSignal =
                            waitForBladeStationProgress(
                                math.max(
                                    0.12,
                                    tonumber(
                                        Config
                                            .V917BladeTouchSignalPollSeconds
                                    )
                                    or actionPollSeconds
                                )
                            )
                    end

                    if stationActionAccepted then
                        bladeStationActionStarted = true
                        bladeStationStartSignal =
                            progressSignal or "STATE_ACCEPTED"
                        break
                    end

                    task.wait(
                        math.max(
                            0.04,
                            tonumber(
                                Config
                                    .V917BladeStationExactRetryDelay
                            )
                            or 0.08
                        )
                    )
                end

                -- Exact GET is trace-confirmed. Keep one native prompt pass
                -- only when the route was unavailable or produced no state
                -- change, so executor/game variants still fail safely.
                if not reachedTarget
                    and not stationActionAccepted then

                    local promptDeadline =
                        os.clock()
                        + math.max(
                            0.15,
                            tonumber(
                                Config
                                    .V917BladeStationPromptWaitSeconds
                            )
                            or 0.70
                        )

                    repeat
                        if V917BladeStationRecovery
                            .RefillPromptVisible() then
                            break
                        end
                        task.wait(0.05)
                    until os.clock() >= promptDeadline

                    stationRefillKeyHold()
                    reachedTarget,
                    stationActionAccepted,
                    progressSignal =
                        waitForBladeStationProgress(
                            math.max(
                                actionPollSeconds,
                                exactTransportWorked and 0.55 or 0.90
                            )
                        )

                    if not reachedTarget
                        and not stationActionAccepted
                        and V97ActivateStationPrompt then
                        V97ActivateStationPrompt(station)
                        reachedTarget,
                        stationActionAccepted,
                        progressSignal =
                            waitForBladeStationProgress(
                                math.max(
                                    actionPollSeconds,
                                    0.70
                                )
                            )
                    end
                end

                if stationActionAccepted then
                    bladeStationActionStarted = true
                    bladeStationStartSignal =
                        bladeStationStartSignal
                        or progressSignal
                        or "NATIVE_STATE_ACCEPTED"
                end

                if bladeStationActionStarted
                    and Config.V917BladeTouchReturnEnabled == true
                    and bladeBackgroundHoldActive
                    and typeof(preRefillCFrame) == "CFrame" then

                    -- Stop station-position ownership before switching the
                    -- persistent recovery hold back to the farm snapshot.
                    bladeStationHoldActive = false

                    V52RefillSafety.SetPhase(
                        "BLADE REFILL STARTED • RETURNING"
                    )

                    local returnStarted =
                        V917BladeStationRecovery.SetHoldCFrame(
                            preRefillCFrame,
                            "REFILL STARTED • VERIFYING AT FARM"
                        )

                    pcall(function()
                        if character and character.Parent then
                            character:PivotTo(preRefillCFrame)
                        end

                        if rootPart and rootPart.Parent then
                            rootPart.CFrame = preRefillCFrame
                            rootPart.Anchored = true
                            rootPart.AssemblyLinearVelocity =
                                Vector3.zero
                            rootPart.AssemblyAngularVelocity =
                                Vector3.zero
                        end
                    end)

                    bladeStationReturnedAfterStart =
                        returnStarted == true

                    V94RunRecorder.Record(
                        "BLADE_STATION",
                        "TOUCH ACCEPTED • RETURNED TO FARM",
                        {
                            signal = tostring(
                                bladeStationStartSignal
                            ),
                            returned =
                                bladeStationReturnedAfterStart,
                            beforeSets =
                                beforeSpotSets,
                            beforeRefills =
                                beforeSpotRefills,
                        }
                    )

                    task.wait(
                        math.max(
                            0.02,
                            tonumber(
                                Config
                                    .V917BladeTouchReturnSettleSeconds
                            )
                            or 0.04
                        )
                    )
                end

                bladeStationHoldActive = false
            end

			local afterAmmo = readAnyAmmo()

            if reachedTarget
                or (
                    StationRefill.Mode == "Blades"
                    and bladeStationActionStarted
                ) then
                break
            end

            if StationRefill.Mode == "Spears" then
                if targetReached(afterAmmo) then
                    break
                end
            elseif beforeAmmo ~= nil and afterAmmo ~= nil and afterAmmo > beforeAmmo then
				break
			end

			-- V3.5.5: Spear mode uses exact Attacks/Reload remote; blades keep normal R input.
		end
        end

        if StationRefill.Mode == "Spears" then
            task.wait(0.15)
        elseif bladeStationReturnedAfterStart then
            -- Already back at the saved farming CFrame. Begin verification
            -- immediately while the accepted station refill replicates.
            task.wait(0.04)
        else
		    task.wait(Config.StationRefillVerifyDelay or 1.2)
        end

        if StationRefill.Mode == "Blades" and Config.V93BladeAmmoDirectorEnabled == true then
            local verifySeconds =
                math.max(
                    0.60,
                    tonumber(Config.V93StationVerifySeconds)
                        or 2.20
                )

            if bladeStationActionStarted then
                verifySeconds =
                    math.max(
                        verifySeconds,
                        tonumber(
                            Config.V917BladeAwayReplicationSeconds
                        )
                            or 4.50
                    )
            end

            local verifyDeadline =
                os.clock() + verifySeconds
            local observedSets = nil
            local observedSegments = nil

            repeat
                cachedBladeCounter = nil
                cachedBladeSetCounter = nil
                observedSegments = select(1, readBladeSegments())
                observedSets = select(1, readBladeSets())

                local setsRestored = observedSets ~= nil
                    and observedSets >= Config.BladeSetMaximum
                if setsRestored then
                    break
                end
                task.wait(0.08)
            until os.clock() >= verifyDeadline

            V93BladeAmmoDirector.LastStationAfterSets = observedSets

            local stationSetsRestored = observedSets ~= nil
                and observedSets >= Config.BladeSetMaximum

            if stationSetsRestored then
                bladeStationRefillVerified = true

                bladeStationBladeUsable,
                    bladeStationPostReloadAttempted,
                    bladeStationFinalFill,
                    bladeStationFinalSets,
                    bladeStationRenewError =
                        V917BladeStationRecovery
                            .VerifyUsableBladeAfterRestock()

                V93BladeAmmoDirector.StationExhausted = false
                V93BladeAmmoDirector.StationFailures = 0
                V93BladeAmmoDirector.StationRetryAfter = 0
                bladeRefillArmed = true
                postStationBladeRenew = false
                V96BladeRefillController
                    .PendingPostStationRenew = false
                V93BladeAmmoDirector.BladelessHold =
                    not bladeStationBladeUsable

                if bladeStationBladeUsable then
                    V917BladeStationRecovery
                        .PostRestockGraceUntil =
                        os.clock()
                        + math.max(
                            1.5,
                            tonumber(
                                Config
                                    .V917BladePostRestockGraceSeconds
                            )
                            or 4.0
                        )

                    local finalSets =
                        bladeStationFinalSets
                        or observedSets

                    V93BladeAmmoDirector.Status =
                        bladeStationPostReloadAttempted
                        and (
                            "STATION + BLADE RENEW VERIFIED • "
                            .. tostring(finalSets)
                            .. "/"
                            .. tostring(
                                Config.BladeSetMaximum
                            )
                            .. " • RETURNING"
                        )
                        or (
                            "STATION REFILL VERIFIED • "
                            .. tostring(finalSets)
                            .. "/"
                            .. tostring(
                                Config.BladeSetMaximum
                            )
                            .. " • BLADE READY"
                        )

                    V96BladeRefillController.State =
                        "STATION_READY"
                else
                    V93BladeAmmoDirector.Status =
                        "STATION RESTOCKED • BLADE RENEW FAILED"
                    V96BladeRefillController.State =
                        "STATION_RENEW_FAILED"
                end

                V96BladeRefillController.Status =
                    V93BladeAmmoDirector.Status
                statusText = V93BladeAmmoDirector.Status

                V94RunRecorder.Record(
                    "BLADE_STATION",
                    V93BladeAmmoDirector.Status,
                    {
                        segments = observedSegments,
                        stationSets = observedSets,
                        finalSets = bladeStationFinalSets,
                        stationFillOffset =
                            readBladeFillOffset(),
                        finalFillOffset =
                            bladeStationFinalFill,
                        postStationReload =
                            bladeStationPostReloadAttempted,
                        bladeUsable =
                            bladeStationBladeUsable,
                        renewError = tostring(
                            bladeStationRenewError
                        ),
                    }
                )

                print(
                    "[SliceHub V9.8.4][AMMO]",
                    V93BladeAmmoDirector.Status
                )

            elseif observedSets ~= nil then
                V93BladeAmmoDirector.StationFailures += 1
                local threshold = math.max(2, math.floor(tonumber(Config.V95StationFailureThreshold) or 3))
                local reachedThreshold = V93BladeAmmoDirector.StationFailures >= threshold

                V93BladeAmmoDirector.StationExhausted = reachedThreshold
                V93BladeAmmoDirector.StationRetryAfter = reachedThreshold
                    and (os.clock() + math.max(1.0, tonumber(Config.V95StationRetryCooldown) or 2.50))
                    or 0
                V93BladeAmmoDirector.BladelessHold = (observedSegments == nil or observedSegments <= 0)
                bladeRefillArmed = true

                if reachedThreshold then
                    V93BladeAmmoDirector.Status = "STATION RETRY COOLDOWN • "
                        .. tostring(V93BladeAmmoDirector.StationFailures) .. "/" .. tostring(threshold)
                else
                    V93BladeAmmoDirector.Status = "STATION REFILL UNCONFIRMED • RETRY "
                        .. tostring(V93BladeAmmoDirector.StationFailures) .. "/" .. tostring(threshold)
                end

                V94RunRecorder.Record("BLADE_STATION", V93BladeAmmoDirector.Status, {
                    segments = observedSegments,
                    sets = observedSets,
                })
                statusText = V93BladeAmmoDirector.Status
                print(
                    "[SliceHub V9.5][AMMO] station refill unconfirmed; bounded retry policy",
                    "sets=" .. tostring(observedSets),
                    "segments=" .. tostring(observedSegments),
                    "failures=" .. tostring(V93BladeAmmoDirector.StationFailures)
                )
            else
                -- Counter vanished entirely: do not permanently condemn the station, but
                -- also do not immediately loop movement again from this same attempt.
                V93BladeAmmoDirector.Status = "STATION VERIFY UNKNOWN • HOLD"
                statusText = V93BladeAmmoDirector.Status
                V93BladeAmmoDirector.BladelessHold = observedSegments == nil or observedSegments <= 0
                print("[SliceHub V9.3][AMMO] station verification unknown; repeated loop suppressed by hold state")
            end
        end

		cachedBladeCounter = nil
		cachedBladeSetCounter = nil

        local returnedToFarm = true

        if StationRefill.Mode == "Spears" then
            if skipStationMovement then
                statusText =
                    "TS refill complete: resuming in place"

                pcall(function()
                    if rootPart and rootPart.Parent then
                        rootPart.AssemblyLinearVelocity =
                            Vector3.zero
                        rootPart.AssemblyAngularVelocity =
                            Vector3.zero
                    end

                    local camera = Workspace.CurrentCamera
                    if camera
                        and humanoid
                        and humanoid.Parent then
                        camera.CameraType =
                            Enum.CameraType.Custom
                        camera.CameraSubject = humanoid
                    end
                end)
            else
                statusText =
                    "TS refill complete: returning to combat"
                returnedToFarm =
                    returnFromSpearRefill()
            end
        elseif StationRefill.Mode == "Blades"
            and bladeBackgroundHoldActive then

            -- Always leave the station and return to the exact farming
            -- CFrame that was captured before the 0/3 transition.
            if typeof(preRefillCFrame) == "CFrame" then
                V52RefillSafety.SetPhase(
                    "BLADE RETURN TO FARM"
                )
                returnedToFarm =
                    V917BladeStationRecovery.SetHoldCFrame(
                        preRefillCFrame,
                        bladeStationRefillVerified
                            and bladeStationBladeUsable
                            and "BLADES READY • RETURNING"
                            or "REFILL/RENEW FAILED • RETURNING PAUSED"
                    )

                task.wait(
                    math.max(
                        0.10,
                        tonumber(
                            Config.V917BladeReturnSettleSeconds
                        )
                        or 0.22
                    )
                )
            else
                returnedToFarm = false
            end

            pcall(function()
                local camera = Workspace.CurrentCamera
                if camera
                    and humanoid
                    and humanoid.Parent then
                    camera.CameraType =
                        Enum.CameraType.Custom
                    camera.CameraSubject = humanoid
                end
            end)
        end

        if manual then
            if StationRefill.Mode == "Spears" then
                showNotification(
                    "Spear refill attempted",
                    "Used the existing Spear refill route.",
                    "info"
                )
            elseif bladeStationRefillVerified
                and bladeStationBladeUsable then
                showNotification(
                    "Blades ready",
                    bladeStationPostReloadAttempted
                        and "Station refill and current-blade renewal verified. Returning to farm."
                        or "Station refill produced a usable blade. Returning to farm.",
                    "success"
                )
            else
                showNotification(
                    "Blade refill paused",
                    bladeStationRefillVerified
                        and "The station reached 3/3, but the current blade did not become usable."
                        or "The station did not verify a restock. Farm remains paused.",
                    "error"
                )
            end
        end

        if StationRefill.Mode == "Spears" then
            V52RefillSafety.SetPhase("COMBAT HANDOFF")
        elseif StationRefill.Mode == "Blades"
            and bladeStationRefillVerified
            and bladeStationBladeUsable then
            V52RefillSafety.SetPhase(
                "BLADE COMBAT HANDOFF"
            )
        end

		StationRefill.Running = false

        -- V9.8.4: exact station restock and any required
        -- current-blade renewal are complete before movement ownership is
        -- released. No second asynchronous renewal owner is started here.
        postStationBladeRenew = false
        V96BladeRefillController
            .PendingPostStationRenew = false

        if StationRefill.Mode == "Blades" then
            if bladeStationRefillVerified
                and bladeStationBladeUsable then

                local readySets =
                    bladeStationFinalSets
                    or select(1, readBladeSets())
                    or 0
                local heldCharacter =
                    V917BladeStationRecovery.HoldCharacter
                local heldRoot =
                    V917BladeStationRecovery.HoldRoot

                -- V9.8.4: never derive the return point from the live
                -- root after station travel. Use the immutable snapshot owned
                -- by the recovery controller, with preRefillCFrame only as a
                -- startup fallback.
                local returnCFrame =
                    V917BladeStationRecovery.SavedFarmCFrame

                if typeof(returnCFrame) ~= "CFrame" then
                    returnCFrame = preRefillCFrame
                end

                if typeof(returnCFrame) == "CFrame" then
                    returnedToFarm =
                        V917BladeStationRecovery.SetHoldCFrame(
                            returnCFrame,
                            "BLADES READY • FARM POSITION LOCKED"
                        )

                    pcall(function()
                        if heldCharacter
                            and heldCharacter.Parent then
                            heldCharacter:PivotTo(returnCFrame)
                        end

                        if heldRoot and heldRoot.Parent then
                            heldRoot.CFrame = returnCFrame
                            heldRoot.Anchored = true
                            heldRoot.AssemblyLinearVelocity =
                                Vector3.zero
                            heldRoot.AssemblyAngularVelocity =
                                Vector3.zero
                        end
                    end)
                else
                    returnedToFarm = false
                end

                if resumeFarm then
                    State.FarmEnabled = true
                    clearCurrentTarget(false)
                    cachedTitanCandidatesAt = 0
                    CombatAnchorRuntime.Position = nil
                    CombatAnchorRuntime.GroundCenter = nil
                    CombatAnchorRuntime.AimPosition = nil
                    CombatAnchorRuntime.TargetCount = 0
                    CombatAnchorRuntime.PulseUntil = 0
                    CombatAnchorRuntime.PulseSerial += 1
                end

                -- Farm is now live, but station movement does not get another
                -- frame to pull the player back. The existing recovery owner
                -- and this explicit guard both pin the original character to
                -- the exact saved farm CFrame until combat has restarted.
                local returnAnchorSeconds = math.max(
                    0.35,
                    tonumber(
                        Config.V917BladeReturnAnchorSeconds
                    ) or 1.25
                )
                local returnAnchorInterval = math.max(
                    0.01,
                    tonumber(
                        Config.V917BladeReturnAnchorInterval
                    ) or 0.02
                )
                local returnAnchorUntil =
                    os.clock() + returnAnchorSeconds

                while typeof(returnCFrame) == "CFrame"
                    and heldCharacter
                    and heldCharacter.Parent
                    and heldRoot
                    and heldRoot.Parent
                    and character == heldCharacter
                    and rootPart == heldRoot
                    and humanoid
                    and humanoid.Parent
                    and humanoid.Health > 0
                    and os.clock() < returnAnchorUntil do

                    pcall(function()
                        V917BladeStationRecovery.HoldCFrame =
                            returnCFrame
                        V917BladeStationRecovery.Status =
                            "FARM RESTART • POSITION LOCKED"
                        V52RefillSafety.HoldCFrame =
                            returnCFrame

                        heldCharacter:PivotTo(returnCFrame)
                        heldRoot.CFrame = returnCFrame
                        heldRoot.Anchored = true
                        heldRoot.AssemblyLinearVelocity =
                            Vector3.zero
                        heldRoot.AssemblyAngularVelocity =
                            Vector3.zero

                        humanoid.PlatformStand = false
                        humanoid.Sit = false
                        humanoid.AutoRotate = true
                    end)

                    task.wait(returnAnchorInterval)
                end

                -- Final return commit happens before releasing the anchor.
                pcall(function()
                    if heldCharacter
                        and heldCharacter.Parent
                        and typeof(returnCFrame) == "CFrame" then
                        heldCharacter:PivotTo(returnCFrame)
                    end

                    if heldRoot and heldRoot.Parent then
                        if typeof(returnCFrame) == "CFrame" then
                            heldRoot.CFrame = returnCFrame
                        end
                        heldRoot.AssemblyLinearVelocity =
                            Vector3.zero
                        heldRoot.AssemblyAngularVelocity =
                            Vector3.zero
                    end
                end)

                V917BladeStationRecovery.Stop(
                    resumeFarm
                        and "RESTOCK COMPLETE • FARM RESUMED"
                        or "RESTOCK COMPLETE",
                    true
                )
                bladeBackgroundHoldActive = false

                pcall(function()
                    if heldCharacter
                        and heldCharacter.Parent
                        and typeof(returnCFrame) == "CFrame" then
                        heldCharacter:PivotTo(returnCFrame)
                    end

                    if heldRoot and heldRoot.Parent then
                        if typeof(returnCFrame) == "CFrame" then
                            heldRoot.CFrame = returnCFrame
                        end
                        heldRoot.Anchored = false
                        heldRoot.AssemblyLinearVelocity =
                            Vector3.zero
                        heldRoot.AssemblyAngularVelocity =
                            Vector3.zero
                    end

                    if humanoid and humanoid.Parent then
                        humanoid.PlatformStand = false
                        humanoid.Sit = false
                        humanoid.AutoRotate = true
                        humanoid:ChangeState(
                            Enum.HumanoidStateType.Running
                        )
                    end

                    local camera = Workspace.CurrentCamera
                    if camera and humanoid and humanoid.Parent then
                        camera.CameraType = Enum.CameraType.Custom
                        camera.CameraSubject = humanoid
                    end
                end)

                -- Last-resort handoff watchdog: recommit the farm CFrame
                -- before clearing any stale anchor. It never targets or
                -- returns to the station.
                task.delay(
                    math.max(
                        0.30,
                        tonumber(
                            Config.V917BladeHandoffWatchdogSeconds
                        ) or 0.75
                    ),
                    function()
                        if heldRoot
                            and heldRoot.Parent
                            and heldCharacter
                            and heldCharacter.Parent
                            and character == heldCharacter
                            and State.FarmEnabled == true
                            and StationRefill.Running ~= true then
                            pcall(function()
                                if typeof(returnCFrame) == "CFrame" then
                                    heldCharacter:PivotTo(returnCFrame)
                                    heldRoot.CFrame = returnCFrame
                                end

                                heldRoot.Anchored = false
                                heldRoot.AssemblyLinearVelocity =
                                    Vector3.zero
                                heldRoot.AssemblyAngularVelocity =
                                    Vector3.zero
                            end)
                        end
                    end
                )

                statusText = resumeFarm
                    and (
                        "BLADES READY "
                        .. tostring(readySets)
                        .. "/"
                        .. tostring(Config.BladeSetMaximum)
                        .. " • FARM RESUMED"
                    )
                    or (
                        "BLADES READY "
                        .. tostring(readySets)
                        .. "/"
                        .. tostring(Config.BladeSetMaximum)
                    )
            else
                State.FarmEnabled = false
                bladeRefillArmed = false
                V93BladeAmmoDirector.BladelessHold = true
                V93BladeAmmoDirector.Status =
                    bladeStationRefillVerified
                    and "STATION 3/3 • CURRENT BLADE UNUSABLE"
                    or "STATION REFILL FAILED • FARM PAUSED"
                V96BladeRefillController.Status =
                    V93BladeAmmoDirector.Status
                statusText = V93BladeAmmoDirector.Status

                showNotification(
                    "Blade recovery paused",
                    bladeStationRefillVerified
                        and "The station restocked, but exact Blades/Reload did not verify a usable blade. Disable Auto Blade Refill to release the saved position."
                        or "No station restock was verified. Disable Auto Blade Refill to release the saved position.",
                    "error"
                )
            end
        elseif resumeFarm then
            State.FarmEnabled = true
            clearCurrentTarget(false)
            cachedTitanCandidatesAt = 0

            if StationRefill.Mode == "Spears" then
                statusText = returnedToFarm
                    and "TS refill complete: Farm resumed"
                    or "TS refill complete: Farm resumed from fallback position"
            end
        end

        if StationRefill.Mode == "Spears" then
            task.wait(0.10)
            spearHoverActive = false
            pcall(function()
                if rootPart and rootPart.Parent then
                    rootPart.AssemblyLinearVelocity =
                        Vector3.zero
                    rootPart.AssemblyAngularVelocity =
                        Vector3.zero
                    rootPart.Anchored = false
                end
            end)
            V52RefillSafety.Active = false
            V52RefillSafety.HoldCFrame = nil
            V52RefillSafety.SetPhase("Idle")
        else
            spearHoverActive = false
        end
	end)
	return true
end

activateNativeMobileRefillButton = function()
    local button = resolvePath(playerGui, {"Interface", "Layout", "Movable", "Refill"})
    if not button or not button:IsA("GuiButton") then return false end

    -- Prefer the game's existing signal. Never move the cursor or synthesize a click.
    if type(firesignal) == "function" then
        local ok = pcall(function()
            firesignal(button.Activated)
        end)
        if ok then return true end
    end

    if type(getconnections) == "function" then
        local ok, connections = pcall(function()
            return getconnections(button.Activated)
        end)
        if ok and type(connections) == "table" then
            for _, connection in ipairs(connections) do
                local callback = connection and connection.Function
                if type(callback) == "function" then
                    local fired = pcall(callback)
                    if fired then return true end
                end
            end
        end
    end

    return false
end

V97ActivateStationPrompt = function(station)
    local invoked = false

    -- The same native mobile action exists on many PC layouts too. Calling its
    -- existing callback is passive with respect to the cursor and preserves the
    -- game's own proximity validation.
    if activateNativeMobileRefillButton and activateNativeMobileRefillButton() then
        invoked = true
    end

    -- Some maps expose a real ProximityPrompt under/near the refill part.
    if type(fireproximityprompt) == "function" and station then
        local roots = {station}
        local node = station.Parent
        for _ = 1, 4 do
            if not node then break end
            roots[#roots + 1] = node
            node = node.Parent
        end

        local seen = {}
        for _, root in ipairs(roots) do
            local objects = {root}
            for _, descendant in ipairs(root:GetDescendants()) do
                objects[#objects + 1] = descendant
            end
            for _, object in ipairs(objects) do
                if object:IsA("ProximityPrompt") and not seen[object] then
                    seen[object] = true
                    local lowerName = string.lower(tostring(object.Name or ""))
                    local lowerAction = string.lower(tostring(object.ActionText or ""))
                    local lowerObject = string.lower(tostring(object.ObjectText or ""))
                    if string.find(lowerName, "refill", 1, true)
                        or string.find(lowerAction, "refill", 1, true)
                        or string.find(lowerObject, "refill", 1, true)
                        or string.find(lowerObject, "gas", 1, true) then
                        local ok = pcall(function() fireproximityprompt(object) end)
                        invoked = ok or invoked
                    end
                end
            end
        end
    end

    return invoked
end

local function triggerNativeBladeRenewInput()
    local key = Config.AutoRefillKey or Enum.KeyCode.R
    local usedExecutorKey = type(keypress) == "function" and type(keyrelease) == "function"

    if usedExecutorKey then
        pcall(function() keypress(key.Value or key) end)
    else
        pcall(function() VirtualInputManager:SendKeyEvent(true, key, false, game) end)
    end

    task.wait(0.07)

    if usedExecutorKey then
        pcall(function() keyrelease(key.Value or key) end)
    else
        pcall(function() VirtualInputManager:SendKeyEvent(false, key, false, game) end)
    end
end

V96BladeReloadCore = V96BladeReloadCore or {}

function V96BladeReloadCore.ReadFresh()
    cachedBladeCounter = nil
    cachedBladeSetCounter = nil
    local fillOffset = readBladeFillOffset()
    local sets = select(1, readBladeSets())
    return fillOffset, sets
end

function V96BladeReloadCore.Accepted(beforeFillOffset, beforeSets, afterFillOffset, afterSets)
    local setSpent = beforeSets ~= nil and afterSets ~= nil and afterSets < beforeSets
    local fillMoved = tonumber(beforeFillOffset) ~= nil
        and tonumber(afterFillOffset) ~= nil
        and tonumber(afterFillOffset) >= tonumber(beforeFillOffset) + 0.25
    return setSpent or fillMoved
end

function V96BladeReloadCore.Progressed(beforeFillOffset, beforeSets, afterFillOffset, afterSets)
    local setSpent = beforeSets ~= nil and afterSets ~= nil and afterSets < beforeSets
    local fillRecovered = bladeFillIsReady(afterFillOffset)
        or (tonumber(beforeFillOffset) ~= nil
            and tonumber(afterFillOffset) ~= nil
            and tonumber(afterFillOffset) >= tonumber(beforeFillOffset) + 0.55)
    return setSpent and fillRecovered
end

function V96BladeReloadCore.WaitForProgress(beforeFillOffset, beforeSets, seconds)
    local deadline = os.clock() + math.max(0.40, tonumber(seconds) or 3.20)
    local afterFillOffset, afterSets = nil, nil
    repeat
        afterFillOffset, afterSets = V96BladeReloadCore.ReadFresh()
        if V96BladeReloadCore.Progressed(beforeFillOffset, beforeSets, afterFillOffset, afterSets) then
            return true, afterFillOffset, afterSets
        end
        task.wait(0.05)
    until os.clock() >= deadline
    return false, afterFillOffset, afterSets
end

function V96BladeReloadCore.InvokeExact()
    local assets =
        ReplicatedStorage:FindFirstChild("Assets")
    local remotes =
        assets and assets:FindFirstChild("Remotes")
    local remote =
        remotes and remotes:FindFirstChild("GET")

    if not remote
        or not remote:IsA("RemoteFunction") then

        return false, nil,
            "ReplicatedStorage.Assets.Remotes.GET missing"
    end

    local called =
        table.pack(
            pcall(function()
                return remote:InvokeServer(
                    "Blades",
                    "Reload"
                )
            end)
        )

    if not called[1] then
        return false, nil, tostring(called[2])
    end

    return true, called[2], nil
end

function V918BladeRecoveryTransaction.CanStart(owner)
    local now = os.clock()
    local resolvedOwner = tostring(owner or "NORMAL")
    local stationOwner = string.find(
        resolvedOwner,
        "STATION",
        1,
        true
    ) ~= nil

    if V918BladeRecoveryTransaction.Active then
        return false,
            "Blade recovery busy • "
            .. tostring(V918BladeRecoveryTransaction.Owner)
    end

    if now < (tonumber(V918BladeRecoveryTransaction.EmergencyUntil) or 0) then
        return false, "Blade recovery emergency cooldown"
    end

    if now < (tonumber(V918BladeRecoveryTransaction.CooldownUntil) or 0) then
        return false, "Blade recovery cooldown"
    end

    if not stationOwner
        and (
            (StationRefill and StationRefill.Running)
            or (
                V917BladeStationRecovery
                and V917BladeStationRecovery.Active
            )
        ) then
        return false, "Blade station recovery owns refill"
    end

    if stationOwner
        and V912BladeRenewAuthority
        and V912BladeRenewAuthority.Active then
        return false, "Normal blade renewal owns refill"
    end

    return true
end

function V918BladeRecoveryTransaction.Begin(owner, baselineSets)
    local allowed, reason =
        V918BladeRecoveryTransaction.CanStart(owner)

    if not allowed then
        return nil, reason
    end

    V918BladeRecoveryTransaction.Serial += 1
    V918BladeRecoveryTransaction.Active = true
    V918BladeRecoveryTransaction.Owner =
        tostring(owner or "NORMAL")
    V918BladeRecoveryTransaction.BaselineSets =
        tonumber(baselineSets)
    V918BladeRecoveryTransaction.StartedAt = os.clock()
    V918BladeRecoveryTransaction.LastResult = "RUNNING"
    V918BladeRecoveryTransaction.LastSpent = 0

    return V918BladeRecoveryTransaction.Serial
end

function V918BladeRecoveryTransaction.IsCurrent(serial)
    return V918BladeRecoveryTransaction.Active == true
        and tonumber(serial)
            == tonumber(V918BladeRecoveryTransaction.Serial)
end

function V918BladeRecoveryTransaction.Finish(
    serial,
    result,
    finalSets,
    success
)
    if not V918BladeRecoveryTransaction.IsCurrent(serial) then
        return false
    end

    local baseline =
        tonumber(V918BladeRecoveryTransaction.BaselineSets)
    local resolvedFinal = tonumber(finalSets)
    local spent = baseline ~= nil
        and resolvedFinal ~= nil
        and math.max(0, baseline - resolvedFinal)
        or 0
    local now = os.clock()

    V918BladeRecoveryTransaction.Active = false
    V918BladeRecoveryTransaction.Owner = "IDLE"
    V918BladeRecoveryTransaction.BaselineSets = nil
    V918BladeRecoveryTransaction.LastSpent = spent
    V918BladeRecoveryTransaction.LastResult =
        tostring(result or "FINISHED")

    local normalCooldown = math.max(
        0.80,
        tonumber(
            Config.V918BladeTransactionCooldownSeconds
        ) or 2.40
    )
    local repairCooldown = math.max(
        normalCooldown,
        tonumber(
            Config.V918BladePostRepairCooldownSeconds
        ) or 3.80
    )

    V918BladeRecoveryTransaction.CooldownUntil =
        now + (success == true and repairCooldown or normalCooldown)

    if spent > 1 then
        local emergencySeconds = math.max(
            repairCooldown,
            tonumber(
                Config.V918BladeEmergencyCooldownSeconds
            ) or 8.00
        )
        V918BladeRecoveryTransaction.EmergencyUntil =
            now + emergencySeconds
        V918BladeRecoveryTransaction.CooldownUntil =
            V918BladeRecoveryTransaction.EmergencyUntil

        V93BladeAmmoDirector.BladelessHold = true
        V93BladeAmmoDirector.DirectRetryAfter =
            V918BladeRecoveryTransaction.EmergencyUntil
        V96BladeRefillController.State =
            "MULTI_SET_SAFETY"
        V96BladeRefillController.Status =
            "BLADE RECOVERY PAUSED • MULTIPLE SETS LOST"
        V93BladeAmmoDirector.Status =
            V96BladeRefillController.Status

        showNotification(
            "Blade recovery",
            "Paused after multiple blade sets disappeared.",
            "error"
        )
    end

    V94RunRecorder.Record(
        "BLADE_RELOAD",
        V918BladeRecoveryTransaction.LastResult,
        {
            serial = serial,
            spent = spent,
            finalSets = finalSets,
            success = success == true,
            cooldownUntil =
                V918BladeRecoveryTransaction.CooldownUntil,
        }
    )

    return true, spent
end


-- V9.8.4: normal blade renewal has one serialized owner. It bypasses
-- the old layered Trained Cadet / exact / R / mobile sequence, issues at most
-- one exact request per transaction, and observes HUD replication before a
-- later watchdog pass may begin a completely separate retry.
V912BladeRenewAuthority = V912BladeRenewAuthority or {
    Active = false,
    Attempt = 0,
    StartedAt = 0,
    TransactionSerial = nil,
    LastResponse = nil,
    LastError = nil,
    LastStatus = "Idle",
}

function V912BladeRenewAuthority.Finish(success, status, fillOffset, sets)
    local serial =
        V912BladeRenewAuthority.TransactionSerial

    V912BladeRenewAuthority.Active = false
    V912BladeRenewAuthority.TransactionSerial = nil
    V912BladeRenewAuthority.LastStatus =
        tostring(
            status
            or (success and "Renewed" or "Retry pending")
        )
    refillSequenceRunning = false
    V93BladeAmmoDirector.DirectSequenceStartedAt = 0
    V96BladeRefillController.LastFillOffset = fillOffset
    V96BladeRefillController.LastSets = sets
    V96BladeRefillController.LastRefills =
        readBladeRefillCharges()
    bladeRefillArmed = true

    local _, spent =
        V918BladeRecoveryTransaction.Finish(
            serial,
            V912BladeRenewAuthority.LastStatus,
            sets,
            success
        )

    local emergency = tonumber(spent) ~= nil
        and tonumber(spent) > 1

    if success then
        V93BladeAmmoDirector.DirectFailures = 0
        V93BladeAmmoDirector.DirectRetryAfter =
            tonumber(
                V918BladeRecoveryTransaction.CooldownUntil
            ) or 0
        V93BladeAmmoDirector.BladelessHold = false
        V91BladeRefillGuard.HoldUntil = 0
        V96BladeRefillController.PendingPostStationRenew = false
        V96BladeRefillController.State = "USABLE"
        V96BladeRefillController.Status = "BLADE RENEWED"
        V93BladeAmmoDirector.Status =
            V96BladeRefillController.Status
    elseif not emergency then
        V93BladeAmmoDirector.DirectFailures += 1
        V93BladeAmmoDirector.DirectRetryAfter = math.max(
            tonumber(
                V918BladeRecoveryTransaction.CooldownUntil
            ) or 0,
            os.clock()
                + math.max(
                    0.35,
                    tonumber(
                        Config.V96BladeRenewRetryDelay
                    ) or 0.85
                )
        )
        V93BladeAmmoDirector.BladelessHold = true
        V91BladeRefillGuard.HoldUntil =
            V93BladeAmmoDirector.DirectRetryAfter
        V96BladeRefillController.State = "RENEW_RETRY"
        V96BladeRefillController.Status =
            "BLADE RENEW RETRY"
        V93BladeAmmoDirector.Status =
            V96BladeRefillController.Status
    end

    V94RunRecorder.Record(
        "BLADE_RELOAD",
        V912BladeRenewAuthority.LastStatus,
        {
            success = success == true,
            attempts = V912BladeRenewAuthority.Attempt,
            fillOffset = fillOffset,
            sets = sets,
            spent = spent,
            response = tostring(
                V912BladeRenewAuthority.LastResponse
            ),
            error = tostring(
                V912BladeRenewAuthority.LastError
            ),
        }
    )
end

function V912BladeRenewAuthority.Start(reason)
    if Config.V912BladeRenewAuthorityEnabled ~= true then
        return false
    end

    if V912BladeRenewAuthority.Active then
        return true
    end

    if (StationRefill and StationRefill.Running)
        or (
            V917BladeStationRecovery
            and V917BladeStationRecovery.Active
        ) then
        return false
    end

    local beforeFillOffset, beforeSets =
        V96BladeReloadCore.ReadFresh()

    if beforeFillOffset == nil
        or not bladeFillIsBroken(beforeFillOffset)
        or beforeSets == nil
        or beforeSets <= 0 then
        return false
    end

    local serial, transactionError =
        V918BladeRecoveryTransaction.Begin(
            "NORMAL",
            beforeSets
        )

    if not serial then
        V912BladeRenewAuthority.LastStatus =
            tostring(transactionError or "Recovery busy")
        return false
    end

    V912BladeRenewAuthority.Active = true
    V912BladeRenewAuthority.Attempt = 0
    V912BladeRenewAuthority.StartedAt = os.clock()
    V912BladeRenewAuthority.TransactionSerial = serial
    V912BladeRenewAuthority.LastResponse = nil
    V912BladeRenewAuthority.LastError = nil
    V912BladeRenewAuthority.LastStatus = "Renewing"

    bladeRefillArmed = false
    refillSequenceRunning = true
    V93BladeAmmoDirector.DirectSequenceStartedAt = os.clock()
    V93BladeAmmoDirector.BladelessHold = true
    V91BladeRefillGuard.HoldUntil = os.clock()
        + math.max(
            3.0,
            tonumber(
                Config.V918BladeTransactionObserveSeconds
            ) or 3.20
        )
    V96BladeRefillController.State = "NEEDS_RENEW"
    V96BladeRefillController.Status =
        "RENEWING BLADES • SINGLE REQUEST"
    V93BladeAmmoDirector.Status =
        V96BladeRefillController.Status
    V96BladeRefillController.RenewAttempts += 1

    V94RunRecorder.Record(
        "BLADE_RELOAD",
        "TRANSACTION START",
        {
            serial = serial,
            reason = tostring(reason or "broken blade"),
            fillOffset = beforeFillOffset,
            sets = beforeSets,
        }
    )

    task.spawn(function()
        local success = false
        local accepted = false
        local finalFill = beforeFillOffset
        local finalSets = beforeSets

        local okRun, runError = xpcall(function()
            -- Let a native auto-renew begin first. Any set movement closes the
            -- transaction to additional requests immediately.
            local graceUntil = os.clock() + 0.65
            repeat
                if not V918BladeRecoveryTransaction.IsCurrent(serial) then
                    return
                end

                finalFill, finalSets =
                    V96BladeReloadCore.ReadFresh()

                if finalFill ~= nil
                    and not bladeFillIsBroken(finalFill) then
                    success = true
                    return
                end

                if finalSets ~= nil
                    and finalSets < beforeSets then
                    accepted = true
                    break
                end

                task.wait(0.05)
            until os.clock() >= graceUntil

            if not success and not accepted then
                if not State.AutoRefillEnabled
                    or not character
                    or not character.Parent
                    or not humanoid
                    or humanoid.Health <= 0 then
                    return
                end

                V912BladeRenewAuthority.Attempt = 1
                V93BladeAmmoDirector.LastReloadMethod =
                    "EXACT BLADES/RELOAD • SINGLE"

                local invokeOk, response, invokeError =
                    V96BladeReloadCore.InvokeExact()

                V912BladeRenewAuthority.LastResponse = response
                V912BladeRenewAuthority.LastError = invokeError
                accepted = response == true

                V94RunRecorder.Record(
                    "BLADE_RELOAD",
                    "TRANSACTION SINGLE ATTEMPT",
                    {
                        serial = serial,
                        ok = invokeOk,
                        response = tostring(response),
                        error = tostring(invokeError),
                        fillOffset = finalFill,
                        sets = finalSets,
                    }
                )
            end

            local observeSeconds = math.max(
                1.20,
                tonumber(
                    Config.V918BladeTransactionObserveSeconds
                ) or 3.20
            )
            local observeUntil = os.clock() + observeSeconds

            repeat
                task.wait(0.05)

                if not V918BladeRecoveryTransaction.IsCurrent(serial) then
                    return
                end

                finalFill, finalSets =
                    V96BladeReloadCore.ReadFresh()

                if finalFill ~= nil
                    and not bladeFillIsBroken(finalFill) then
                    success = true
                    break
                end

                if finalSets ~= nil
                    and finalSets < beforeSets then
                    accepted = true
                end
            until os.clock() >= observeUntil
        end, function(err)
            return tostring(err)
        end)

        if not okRun then
            V912BladeRenewAuthority.LastError =
                tostring(runError)
        end

        finalFill, finalSets =
            V96BladeReloadCore.ReadFresh()
        success = success
            or (
                finalFill ~= nil
                and not bladeFillIsBroken(finalFill)
            )

        local spent = beforeSets ~= nil
            and finalSets ~= nil
            and math.max(0, beforeSets - finalSets)
            or 0
        local status = success
            and "TRANSACTION RENEWED"
            or (
                spent > 1
                and "TRANSACTION MULTI-SET LOSS"
                or (
                    accepted
                    and "TRANSACTION ACCEPTED • FILL PENDING"
                    or "TRANSACTION NO CHANGE • RETRY LATER"
                )
            )

        V912BladeRenewAuthority.Finish(
            success,
            status,
            finalFill,
            finalSets
        )
    end)

    return true
end

beginBladeRefill = function(reason, allowMissingHudProbe)
    if Config.V96BladeRefillControllerEnabled ~= true then return false end
    if not State.AutoRefillEnabled or not bladeRefillArmed or refillSequenceRunning then return false end
    if os.clock() < (tonumber(V93BladeAmmoDirector.DirectRetryAfter) or 0) then return false end
    if not character or not character.Parent or not humanoid or humanoid.Health <= 0 then return false end

    local gateFillOffset = readBladeFillOffset()
    local gateSets, gateSetMaximum = readBladeSets()
    local refillCharges = readBladeRefillCharges()

    if V917BladeStationRecovery
        and os.clock()
            < (
                tonumber(
                    V917BladeStationRecovery
                        .PostRestockGraceUntil
                )
                or 0
            )
        and gateSets ~= nil
        and gateSetMaximum == Config.BladeSetMaximum
        and gateSets >= Config.BladeSetMaximum then

        V96BladeRefillController.State =
            "POST_STATION_READY"
        V96BladeRefillController.Status =
            "POST-STATION READY • "
            .. tostring(gateSets)
            .. "/"
            .. tostring(Config.BladeSetMaximum)
        V93BladeAmmoDirector.BladelessHold = false
        V93BladeAmmoDirector.Status =
            V96BladeRefillController.Status
        bladeRefillArmed = true
        return false
    end

    if gateFillOffset == nil then
        V96BladeRefillController.State = "HUD_UNKNOWN"
        V96BladeRefillController.Status = "BLADE FILL UNKNOWN • NO ACTION"
        V93BladeAmmoDirector.Status = V96BladeRefillController.Status
        return false
    end

    if not bladeFillIsBroken(gateFillOffset) then
        V96BladeRefillController.State = "USABLE"
        V96BladeRefillController.Status = string.format("READY • FILL %.3f", gateFillOffset)
        V93BladeAmmoDirector.BladelessHold = false
        V93BladeAmmoDirector.Status = V96BladeRefillController.Status
        bladeRefillArmed = true
        if V96BladeBackgroundRefill.Active then
            V96BladeBackgroundRefill.Stop("BLADE ALREADY USABLE")
        end
        return false
    end

    if gateSets ~= nil
        and gateSetMaximum == Config.BladeSetMaximum
        and gateSets <= 0 then

        bladeRefillArmed = false
        V93BladeAmmoDirector.BladelessHold = true

        if refillCharges ~= nil and refillCharges <= 0 then
            V96BladeRefillController.State = "EXHAUSTED"
            V96BladeRefillController.Status = "OUT OF BLADES • 0/3 SETS • 0 REFILLS"
            V93BladeAmmoDirector.Status = V96BladeRefillController.Status
            statusText = V96BladeRefillController.Status
            showNotification("Out of blades", "No spare blade sets or station refills remain.", "error")
            return false
        end

        V96BladeRefillController.State = "NEEDS_STATION"
        V96BladeRefillController.Status = "STATION REFILL • BROKEN + 0/3"
        V93BladeAmmoDirector.Status = V96BladeRefillController.Status
        V96BladeRefillController.StationAttempts += 1
        local stationStarted = beginStationRefill(
            "V9.6 broken blade + 0/" .. tostring(Config.BladeSetMaximum),
            false,
            "Blades"
        ) == true
        if not stationStarted then
            bladeRefillArmed = true
            V93BladeAmmoDirector.DirectRetryAfter = os.clock()
                + math.max(0.35, tonumber(Config.V96BladeRenewRetryDelay) or 0.85)
            V96BladeRefillController.Status = "STATION START FAILED • RETRY ARMED"
            V93BladeAmmoDirector.Status = V96BladeRefillController.Status
        end
        return stationStarted
    end

    if gateSets == nil or gateSetMaximum ~= Config.BladeSetMaximum then
        V96BladeRefillController.State = "SETS_UNKNOWN"
        V96BladeRefillController.Status = "BLADE SET COUNT UNKNOWN • NO ACTION"
        V93BladeAmmoDirector.Status = V96BladeRefillController.Status
        return false
    end

    if V912BladeRenewAuthority
        and type(V912BladeRenewAuthority.Start) == "function" then
        return V912BladeRenewAuthority.Start(reason)
    end

    bladeRefillArmed = false
    refillSequenceRunning = true
    V93BladeAmmoDirector.DirectSequenceStartedAt = os.clock()
    V93BladeAmmoDirector.BladelessHold = true
    V91BladeRefillGuard.HoldUntil = os.clock() + 4.0
    V96BladeRefillController.State = "NEEDS_RENEW"
    V96BladeRefillController.Status = "NATIVE RENEW • VERIFYING"
    V93BladeAmmoDirector.Status = V96BladeRefillController.Status
    V96BladeRefillController.LastActionAt = os.clock()
    V96BladeRefillController.RenewAttempts += 1

    task.spawn(function()
        local sequenceOk, sequenceError = xpcall(function()
            local waitStarted = os.clock()
            while StationRefill.Running and os.clock() - waitStarted < 5 do
                task.wait(0.05)
            end

            if not State.AutoRefillEnabled or not character or not character.Parent then
                return
            end

            local beforeFillOffset, beforeSets = V96BladeReloadCore.ReadFresh()
            if beforeFillOffset == nil or not bladeFillIsBroken(beforeFillOffset) then
                V96BladeRefillController.State = "USABLE"
                V96BladeRefillController.Status = "RENEW CANCELLED • BLADE ALREADY USABLE"
                V93BladeAmmoDirector.BladelessHold = false
                V93BladeAmmoDirector.Status = V96BladeRefillController.Status
                V91BladeRefillGuard.HoldUntil = 0
                bladeRefillArmed = true
                return
            end

            if beforeSets == nil or beforeSets <= 0 then
                V96BladeRefillController.State = "NEEDS_STATION"
                V96BladeRefillController.Status = "RENEW ROUTED TO STATION • 0/3"
                V93BladeAmmoDirector.Status = V96BladeRefillController.Status
                bladeRefillArmed = false
                task.defer(function()
                    local stationStarted = beginStationRefill(
                        "V9.6 native renew found 0/3",
                        false,
                        "Blades"
                    ) == true
                    if not stationStarted then
                        bladeRefillArmed = true
                        V93BladeAmmoDirector.DirectRetryAfter = os.clock()
                            + math.max(0.35, tonumber(Config.V96BladeRenewRetryDelay) or 0.85)
                        V96BladeRefillController.Status = "STATION START FAILED • RETRY ARMED"
                        V93BladeAmmoDirector.Status = V96BladeRefillController.Status
                    end
                end)
                return
            end

            V94RunRecorder.Record("BLADE_RELOAD", V96BladeRefillController.Status, {
                reason = tostring(reason or "broken blade"),
                fillOffset = beforeFillOffset,
                sets = beforeSets,
            })

            -- First allow the game's own Trained Cadet auto-renew to act.
            -- This avoids consuming a second set when the skill works normally.
            V93BladeAmmoDirector.LastReloadMethod = "NATIVE AUTO GRACE"
            V96BladeRefillController.Status = "AUTO RENEW GRACE • VERIFYING"
            V93BladeAmmoDirector.Status = V96BladeRefillController.Status

            local verified, afterFillOffset, afterSets =
                V96BladeReloadCore.WaitForProgress(
                    beforeFillOffset,
                    beforeSets,
                    math.max(
                        0.80,
                        tonumber(
                            Config.V910BladeNativeAutoGraceSeconds
                        ) or 1.35
                    )
                )

            if not verified then
                local nativeAccepted =
                    V96BladeReloadCore.Accepted(
                        beforeFillOffset,
                        beforeSets,
                        afterFillOffset,
                        afterSets
                    )

                -- A set drop or fill movement means native renewal is already
                -- in flight. Wait for its animation instead of firing again.
                if nativeAccepted then
                    V93BladeAmmoDirector.LastReloadMethod =
                        "NATIVE AUTO • ACCEPTED"
                    verified, afterFillOffset, afterSets =
                        V96BladeReloadCore.WaitForProgress(
                            beforeFillOffset,
                            beforeSets,
                            math.max(
                                0.80,
                                tonumber(
                                    Config.V910BladeNativeAcceptedFinishSeconds
                                ) or 1.75
                            )
                        )
                end
            end

            if not verified then
                afterFillOffset, afterSets =
                    V96BladeReloadCore.ReadFresh()

                local renewalAlreadyAccepted =
                    V96BladeReloadCore.Accepted(
                        beforeFillOffset,
                        beforeSets,
                        afterFillOffset,
                        afterSets
                    )

                -- Never call another renewal after a set has already been
                -- consumed, even if the fill animation is slow.
                if renewalAlreadyAccepted then
                    V93BladeAmmoDirector.LastReloadMethod =
                        "RENEW ALREADY IN FLIGHT"

                    verified, afterFillOffset, afterSets =
                        V96BladeReloadCore.WaitForProgress(
                            beforeFillOffset,
                            beforeSets,
                            math.max(
                                0.80,
                                tonumber(
                                    Config.V910BladeNativeAcceptedFinishSeconds
                                ) or 1.75
                            )
                        )
                elseif afterFillOffset ~= nil
                    and not bladeFillIsBroken(afterFillOffset) then

                    -- Blade became usable without a detectable set transition.
                    -- Treat it as recovered and avoid double renewal.
                    verified = true
                elseif afterSets ~= nil and afterSets <= 0 then
                    -- A concurrent native renewal may have spent the last set.
                    -- Do not issue a second call; let verification finish.
                    V93BladeAmmoDirector.LastReloadMethod =
                        "LAST SET ALREADY SPENT"

                    verified, afterFillOffset, afterSets =
                        V96BladeReloadCore.WaitForProgress(
                            beforeFillOffset,
                            beforeSets,
                            math.max(
                                0.80,
                                tonumber(
                                    Config.V910BladeNativeAcceptedFinishSeconds
                                ) or 1.75
                            )
                        )
                else
                    local bladeTool = findBladeTool()

                    if bladeTool then
                        equipTool(bladeTool)
                        task.wait(
                            math.max(
                                0.02,
                                tonumber(
                                    Config.AutoRefillEquipDelay
                                ) or 0.04
                            )
                        )
                    end

                    V93BladeAmmoDirector.LastReloadMethod =
                        "EXACT BLADES/RELOAD"
                    V96BladeRefillController.Status =
                        "EXACT BLADE RENEW • VERIFYING"
                    V93BladeAmmoDirector.Status =
                        V96BladeRefillController.Status

                    local maximumAttempts =
                        math.max(
                            1,
                            math.floor(
                                tonumber(
                                    Config.V911BladeExactAttempts
                                ) or 5
                            )
                        )

                    local attemptWindow =
                        math.max(
                            0.35,
                            tonumber(
                                Config.V911BladeExactAttemptWindowSeconds
                            ) or 0.72
                        )

                    local exactAccepted = false
                    local exactResponseAccepted = false
                    local exactInvokeWorked = false

                    for attempt = 1, maximumAttempts do
                        afterFillOffset, afterSets =
                            V96BladeReloadCore.ReadFresh()

                        if V96BladeReloadCore.Progressed(
                            beforeFillOffset,
                            beforeSets,
                            afterFillOffset,
                            afterSets
                        ) then
                            verified = true
                            exactAccepted = true
                            break
                        end

                        if V96BladeReloadCore.Accepted(
                            beforeFillOffset,
                            beforeSets,
                            afterFillOffset,
                            afterSets
                        ) then
                            exactAccepted = true
                            break
                        end

                        if afterFillOffset ~= nil
                            and not bladeFillIsBroken(
                                afterFillOffset
                            ) then

                            verified = true
                            exactAccepted = true
                            break
                        end

                        if afterSets ~= nil
                            and afterSets < beforeSets then

                            exactAccepted = true
                            break
                        end

                        if afterSets ~= nil and afterSets <= 0 then
                            break
                        end

                        V93BladeAmmoDirector.LastReloadMethod =
                            "EXACT BLADES/RELOAD "
                            .. tostring(attempt)
                            .. "/"
                            .. tostring(maximumAttempts)

                        local invokeOk,
                            invokeResponse,
                            invokeError =
                                V96BladeReloadCore.InvokeExact()

                        exactInvokeWorked =
                            exactInvokeWorked or invokeOk

                        if invokeOk
                            and invokeResponse == true then

                            exactResponseAccepted = true
                        end

                        print(
                            "[SliceHub V9.8.4][AMMO] exact renew attempt",
                            tostring(attempt)
                                .. "/"
                                .. tostring(maximumAttempts),
                            "response="
                                .. tostring(invokeResponse),
                            "error="
                                .. tostring(invokeError),
                            "fill="
                                .. tostring(afterFillOffset),
                            "sets="
                                .. tostring(afterSets)
                        )

                        V94RunRecorder.Record(
                            "BLADE_RELOAD",
                            "EXACT BLADES/RELOAD ATTEMPT",
                            {
                                attempt = attempt,
                                maximumAttempts =
                                    maximumAttempts,
                                ok = invokeOk,
                                response =
                                    tostring(invokeResponse),
                                error =
                                    tostring(invokeError),
                                beforeFill =
                                    beforeFillOffset,
                                beforeSets =
                                    beforeSets,
                                liveFill =
                                    afterFillOffset,
                                liveSets =
                                    afterSets,
                            }
                        )

                        if not invokeOk then
                            warn(
                                "[SliceHub V9.8.4][AMMO] exact Blades/Reload failed:",
                                tostring(invokeError)
                            )
                        end

                        verified,
                            afterFillOffset,
                            afterSets =
                                V96BladeReloadCore.WaitForProgress(
                                    beforeFillOffset,
                                    beforeSets,
                                    attemptWindow
                                )

                        if verified then
                            exactAccepted = true
                            break
                        end

                        if V96BladeReloadCore.Accepted(
                            beforeFillOffset,
                            beforeSets,
                            afterFillOffset,
                            afterSets
                        ) then
                            exactAccepted = true
                            break
                        end

                        if afterFillOffset ~= nil
                            and not bladeFillIsBroken(
                                afterFillOffset
                            ) then

                            verified = true
                            exactAccepted = true
                            break
                        end
                    end

                    if not verified and exactAccepted then
                        V93BladeAmmoDirector.LastReloadMethod =
                            exactResponseAccepted
                            and "EXACT BLADES/RELOAD • SERVER ACCEPTED"
                            or "EXACT BLADES/RELOAD • HUD ACCEPTED"

                        verified,
                            afterFillOffset,
                            afterSets =
                                V96BladeReloadCore.WaitForProgress(
                                    beforeFillOffset,
                                    beforeSets,
                                    math.max(
                                        0.70,
                                        tonumber(
                                            Config.V911BladeExactAcceptedFinishSeconds
                                        ) or 1.35
                                    )
                                )
                    end

                    if not verified
                        and not exactAccepted
                        and exactInvokeWorked then

                        afterFillOffset, afterSets =
                            V96BladeReloadCore.ReadFresh()
                    end
                end
            end

            -- Retain one bounded legacy input fallback only when neither the
            -- native skill nor the exact server route changed any blade state.
            if not verified then
                local actionAccepted =
                    V96BladeReloadCore.Accepted(
                        beforeFillOffset,
                        beforeSets,
                        afterFillOffset,
                        afterSets
                    )

                if not actionAccepted then
                    V93BladeAmmoDirector.LastReloadMethod =
                        "NATIVE R FALLBACK"
                    triggerNativeBladeRenewInput()

                    verified, afterFillOffset, afterSets =
                        V96BladeReloadCore.WaitForProgress(
                            beforeFillOffset,
                            beforeSets,
                            math.max(
                                0.80,
                                tonumber(
                                    Config.V96BladeRenewVerifySeconds
                                ) or 3.20
                            )
                        )
                end

                if not verified then
                    local fallbackAccepted =
                        V96BladeReloadCore.Accepted(
                            beforeFillOffset,
                            beforeSets,
                            afterFillOffset,
                            afterSets
                        )

                    if not fallbackAccepted then
                        V93BladeAmmoDirector.LastReloadMethod =
                            "MOBILE NATIVE CALLBACK"
                        activateNativeMobileRefillButton()

                        verified, afterFillOffset, afterSets =
                            V96BladeReloadCore.WaitForProgress(
                                beforeFillOffset,
                                beforeSets,
                                1.20
                            )
                    end
                end
            end

            V96BladeRefillController.LastFillOffset = afterFillOffset
            V96BladeRefillController.LastSets = afterSets
            V96BladeRefillController.LastRefills = readBladeRefillCharges()
            V93BladeAmmoDirector.LastDirectBeforeSets = beforeSets
            V93BladeAmmoDirector.LastDirectAfterSets = afterSets

            if verified then
                V93BladeAmmoDirector.DirectFailures = 0
                V93BladeAmmoDirector.DirectRetryAfter = 0
                V93BladeAmmoDirector.BladelessHold = false
                V91BladeRefillGuard.HoldUntil = 0
                V96BladeRefillController.PendingPostStationRenew = false
                V96BladeRefillController.State = "USABLE"
                V96BladeRefillController.Status = string.format(
                    "BLADE RENEWED • %s/%s SETS • FILL %.3f",
                    tostring(afterSets),
                    tostring(Config.BladeSetMaximum),
                    tonumber(afterFillOffset) or -9
                )
                V93BladeAmmoDirector.Status = V96BladeRefillController.Status
                V94RunRecorder.Record("BLADE_RELOAD", V96BladeRefillController.Status, {
                    fillOffset = afterFillOffset,
                    sets = afterSets,
                })
                if V96BladeBackgroundRefill.Active then
                    V96BladeBackgroundRefill.Stop("BACKGROUND REFILL COMPLETE")
                end
                print("[SliceHub V9.6][AMMO]", V96BladeRefillController.Status)
            else
                V93BladeAmmoDirector.DirectFailures += 1
                V93BladeAmmoDirector.DirectRetryAfter = os.clock()
                    + math.max(0.35, tonumber(Config.V96BladeRenewRetryDelay) or 0.85)
                V93BladeAmmoDirector.BladelessHold = true
                V91BladeRefillGuard.HoldUntil = V93BladeAmmoDirector.DirectRetryAfter
                V96BladeRefillController.State = "RENEW_RETRY"
                V96BladeRefillController.Status = "NATIVE RENEW UNCONFIRMED • RETRY ARMED"
                V93BladeAmmoDirector.Status = V96BladeRefillController.Status
                V94RunRecorder.Record("BLADE_RELOAD", V96BladeRefillController.Status, {
                    fillOffset = afterFillOffset,
                    sets = afterSets,
                })
                bladeRefillArmed = true
                if V96BladeBackgroundRefill.Active then
                    V96BladeBackgroundRefill.Stop("NATIVE RENEW UNCONFIRMED")
                end
                warn(
                    "[SliceHub V9.6][AMMO] native renew unconfirmed",
                    "beforeFill=" .. tostring(beforeFillOffset),
                    "afterFill=" .. tostring(afterFillOffset),
                    "beforeSets=" .. tostring(beforeSets),
                    "afterSets=" .. tostring(afterSets)
                )
            end
        end, function(err)
            return tostring(err)
        end)

        refillSequenceRunning = false
        V93BladeAmmoDirector.DirectSequenceStartedAt = 0

        if not sequenceOk then
            bladeRefillArmed = true
            V93BladeAmmoDirector.BladelessHold = true
            V93BladeAmmoDirector.DirectFailures += 1
            V93BladeAmmoDirector.DirectRetryAfter = os.clock()
                + math.max(0.35, tonumber(Config.V96BladeRenewRetryDelay) or 0.85)
            V91BladeRefillGuard.HoldUntil = V93BladeAmmoDirector.DirectRetryAfter
            V96BladeRefillController.State = "ERROR"
            V96BladeRefillController.Status = "NATIVE RENEW ERROR • RETRY ARMED"
            V93BladeAmmoDirector.Status = V96BladeRefillController.Status
            if V96BladeBackgroundRefill.Active then
                V96BladeBackgroundRefill.Stop("NATIVE RENEW ERROR")
            end
            warn("[SliceHub V9.6][AMMO] native renew task recovered:", tostring(sequenceError))
        end
    end)

    return true
end

-- V9.1 Blade refill ownership. The exact queue can stay alive even when the trusted
-- segment HUD disappears, so refill is driven by two safe signals:
--   1) trusted 0/3 set count -> station refill
--   2) recent exact Slash activity + sustained no-damage progress -> direct reload probe
V91BladeRefillGuard = V91BladeRefillGuard or {
    LastBreakAt = 0,
    LastProgressAt = os.clock(),
    LastTriggerAt = 0,
    HoldUntil = 0,
    Connection = nil,
    Status = "Idle",
}

function V91BladeRefillGuard.Trigger(reason)
    if Config.V91BladeBreakReloadEnabled ~= true then return false end
    if not State.AutoRefillEnabled then return false end
    if refillSequenceRunning or (StationRefill and StationRefill.Running) then return false end

    local now = os.clock()
    if now - (tonumber(V91BladeRefillGuard.LastTriggerAt) or 0)
        < math.max(0.50, tonumber(Config.V91BladeBreakReloadCooldown) or 0.45) then
        return false
    end

    local segments, segmentMaximum = readBladeSegments()
    local bladeSets, setMaximum = readBladeSets()

    if Config.V93BladeAmmoDirectorEnabled == true then
        if segments ~= nil and segmentMaximum == Config.BladeSegmentMaximum then
            -- Never spend or seek ammo while the current blade still has usable segments.
            if segments > 0 then
                V91BladeRefillGuard.LastTriggerAt = now
                V91BladeRefillGuard.HoldUntil = now + 0.18
                V93BladeAmmoDirector.Status = "NO-PROGRESS IGNORED • " .. tostring(segments) .. "/" .. tostring(segmentMaximum)
                V91BladeRefillGuard.Status = V93BladeAmmoDirector.Status
                return false
            end

            V91BladeRefillGuard.LastTriggerAt = now
            V91BladeRefillGuard.HoldUntil = now + 1.20

            if bladeSets ~= nil
                and setMaximum == Config.BladeSetMaximum
                and bladeSets <= 0 then
                bladeRefillArmed = false

                if V93BladeAmmoDirector.StationExhausted == true then
                    V93BladeAmmoDirector.BladelessHold = true
                    V93BladeAmmoDirector.Status = "BLADELESS HOLD • 0/6 + 0/3"
                    V91BladeRefillGuard.Status = V93BladeAmmoDirector.Status
                    statusText = V93BladeAmmoDirector.Status
                    return false
                end

                V93BladeAmmoDirector.Status = "STATION REFILL • CONFIRMED 0/6 + 0/3"
                V91BladeRefillGuard.Status = V93BladeAmmoDirector.Status
                return beginStationRefill("V9.3 confirmed 0/6 + 0/" .. tostring(Config.BladeSetMaximum), false) == true
            end

            bladeRefillArmed = true
            V93BladeAmmoDirector.Status = "DIRECT RELOAD • CONFIRMED 0/6"
            V91BladeRefillGuard.Status = V93BladeAmmoDirector.Status
            return beginBladeRefill(reason or "confirmed 0/6", false) == true
        end

        -- Segment HUD missing: require both a recent Break hint and a longer no-progress window.
        local breakRecent = now - (tonumber(V91BladeRefillGuard.LastBreakAt) or 0)
            <= math.max(0.35, tonumber(Config.V93MissingHudBreakWindow) or 1.10)
        local noProgressFor = now - (tonumber(V91BladeRefillGuard.LastProgressAt) or now)
        local enoughNoProgress = noProgressFor
            >= math.max(1.20, tonumber(Config.V93MissingHudNoProgressSeconds) or 1.80)

        V91BladeRefillGuard.LastTriggerAt = now

        if not breakRecent or not enoughNoProgress then
            V93BladeAmmoDirector.Status = "HUD UNKNOWN • HOLDING AMMO"
            V91BladeRefillGuard.Status = V93BladeAmmoDirector.Status
            return false
        end

        V91BladeRefillGuard.HoldUntil = now + 1.20

        if bladeSets ~= nil
            and setMaximum == Config.BladeSetMaximum
            and bladeSets <= 0 then
            bladeRefillArmed = false

            if V93BladeAmmoDirector.StationExhausted == true then
                V93BladeAmmoDirector.BladelessHold = true
                V93BladeAmmoDirector.Status = "BLADELESS HOLD • HUD MISSING + 0/3"
                V91BladeRefillGuard.Status = V93BladeAmmoDirector.Status
                statusText = V93BladeAmmoDirector.Status
                return false
            end

            V93BladeAmmoDirector.Status = "STATION REFILL • HUD MISSING + BREAK + STALL"
            V91BladeRefillGuard.Status = V93BladeAmmoDirector.Status
            return beginStationRefill("V9.3 HUD-missing empty evidence", false) == true
        end

        bladeRefillArmed = true
        V93BladeAmmoDirector.Status = "CAUTIOUS DIRECT RELOAD • HUD MISSING"
        V91BladeRefillGuard.Status = V93BladeAmmoDirector.Status
        return beginBladeRefill(reason or "HUD-missing evidence", true) == true
    end

    -- Legacy V9.1 behavior when the V9.3 director is explicitly disabled.
    V91BladeRefillGuard.LastTriggerAt = now
    V91BladeRefillGuard.HoldUntil = now + 1.20

    if bladeSets ~= nil
        and setMaximum == Config.BladeSetMaximum
        and bladeSets <= 0 then
        bladeRefillArmed = false
        V91BladeRefillGuard.Status = "STATION REFILL • " .. tostring(reason or "empty sets")
        return beginStationRefill("V9.1 refill guard 0/" .. tostring(Config.BladeSetMaximum), false) == true
    end

    bladeRefillArmed = true
    V91BladeRefillGuard.Status = "DIRECT RELOAD PROBE • " .. tostring(reason or "no progress")
    return beginBladeRefill(reason or "legacy probe", true) == true
end

do
    local post = resolvePath(ReplicatedStorage, {"Assets", "Remotes", "POST"})
    if post and post:IsA("RemoteEvent") then
        V91BladeRefillGuard.Connection = post.OnClientEvent:Connect(function(category, action, arg3, arg4)
            local cat = tostring(category or "")
            local act = tostring(action or "")

            if cat == "Zones" and act == "Damage_Check" and (tonumber(arg3) or 0) > 0 then
                V91BladeRefillGuard.LastProgressAt = os.clock()
                return
            end

            if cat == "Effects" then
                if act == "Hit" or act == "Blood" then
                    V91BladeRefillGuard.LastProgressAt = os.clock()
                elseif act == "Sound" and tostring(arg3 or "") == "Break" then
                    -- Break is only a hint; it is too noisy to reload from by itself.
                    V91BladeRefillGuard.LastBreakAt = os.clock()
                end
            end
        end)
    end
end

task.spawn(function()
    while true do
        task.wait(0.12)

        if Config.V91BladeBreakReloadEnabled ~= true
            or not State.AutoRefillEnabled
            or not State.BladesEnabled
            or not State.FarmEnabled
            or refillSequenceRunning
            or (StationRefill and StationRefill.Running) then
            continue
        end

        if V91RaidBossGuard and V91RaidBossGuard.Blocked and V91RaidBossGuard.Blocked() then
            continue
        end

        local now = os.clock()
        local exactActive = V6ExactBlade
            and now - (tonumber(V6ExactBlade.LastSlashAt) or 0) <= 0.75
        local noProgressFor = now - (tonumber(V91BladeRefillGuard.LastProgressAt) or now)

        if exactActive
            and noProgressFor >= 1.15
            and now - (tonumber(V91BladeRefillGuard.LastTriggerAt) or 0) >= 2.25 then
            pcall(V91BladeRefillGuard.Trigger, "1.15s exact queue no-progress")
        end
    end
end)

task.spawn(function()
    local lastPrintedAmmoState = nil

    while true do
        task.wait(Config.AutoRefillCheckDelay)

        if not State.AutoRefillEnabled then
            continue
        end

        local current, maximum = readBladeSegments()
        local bladeSets, setMaximum = readBladeSets()

        if V917BladeStationRecovery
            and type(
                V917BladeStationRecovery
                    .RememberFarmCFrame
            ) == "function"
            and not refillSequenceRunning
            and not (
                StationRefill
                and StationRefill.Running
            )
            and (
                current == nil
                or current > 0
                or (
                    bladeSets ~= nil
                    and bladeSets > 0
                )
            ) then
            V917BladeStationRecovery
                .RememberFarmCFrame()
        end

        lastBladeSegments = current
        lastBladeSets = bladeSets

        if Config.V96BladeRefillControllerEnabled == true then
            local liveFillOffset = readBladeFillOffset()
            V96BladeRefillController.LastFillOffset = liveFillOffset
            V96BladeRefillController.LastSets = bladeSets
            V96BladeRefillController.LastRefills = readBladeRefillCharges()

            if liveFillOffset ~= nil and not bladeFillIsBroken(liveFillOffset)
                and not refillSequenceRunning and not StationRefill.Running then
                V96BladeRefillController.State = "USABLE"
                V96BladeRefillController.Status = string.format("READY • FILL %.3f", liveFillOffset)
                V93BladeAmmoDirector.BladelessHold = false
                V93BladeAmmoDirector.Status = V96BladeRefillController.Status
            end
        end

        -- V9.3.1: the one-shot latch must never strand a freshly confirmed empty
        -- current blade while trusted spare sets still exist. This does not infer
        -- emptiness: only the real 0/6 HUD counter can arm recovery.
        local confirmedEmptyWithSpare = Config.V93BladeAmmoDirectorEnabled == true
            and current == 0
            and maximum == Config.BladeSegmentMaximum
            and bladeSets ~= nil
            and setMaximum == Config.BladeSetMaximum
            and bladeSets > 0

        if confirmedEmptyWithSpare then
            local now = os.clock()
            V93BladeAmmoDirector.ConfirmedEmptyWithSpareSince =
                V93BladeAmmoDirector.ConfirmedEmptyWithSpareSince or now

            local emptyFor = now - V93BladeAmmoDirector.ConfirmedEmptyWithSpareSince
            local recoveryDelay = math.max(
                0.25,
                tonumber(Config.V931ConfirmedEmptyRecoverySeconds) or 0.35
            )

            if emptyFor >= recoveryDelay
                and not refillSequenceRunning
                and not (StationRefill and StationRefill.Running)
                and now >= (tonumber(V93BladeAmmoDirector.DirectRetryAfter) or 0) then

                if not bladeRefillArmed then
                    bladeRefillArmed = true
                    BladeZeroObservedAt = nil
                    V93BladeAmmoDirector.ReloadLatchRecoveries += 1
                    V93BladeAmmoDirector.LastReloadLatchRecoveryAt = now
                end

                V93BladeAmmoDirector.BladelessHold = false
                V93BladeAmmoDirector.ConfirmedEmptyWithSpareSince = now
                V93BladeAmmoDirector.Status = "CONFIRMED EMPTY RECOVERY • START DIRECT RELOAD • 0/6 + "
                    .. tostring(bladeSets) .. "/" .. tostring(Config.BladeSetMaximum)
                V91BladeRefillGuard.Status = V93BladeAmmoDirector.Status
                print("[SliceHub V9.5][AMMO]", V93BladeAmmoDirector.Status)

                -- Trusted 0/6 is authoritative. Start recovery directly instead of
                -- relying on a later latch pass that can be starved by raid routing.
                beginBladeRefill("V9.4.2 trusted 0/6 watchdog", false)
            end
        else
            V93BladeAmmoDirector.ConfirmedEmptyWithSpareSince = nil
        end

        local ammoState = tostring(current) .. "/" .. tostring(maximum)
            .. "|" .. tostring(bladeSets) .. "/" .. tostring(setMaximum)
        if ammoState ~= lastPrintedAmmoState then
            lastPrintedAmmoState = ammoState
            V94RunRecorder.Record("BLADE_AMMO", ammoState, {
                segments = current,
                sets = bladeSets,
            })
            print(
                "[SliceHub V3][AMMO]",
                "segments=" .. tostring(current) .. "/" .. tostring(maximum),
                "sets=" .. tostring(bladeSets) .. "/" .. tostring(setMaximum)
            )
        end

        -- V9.1: if the segment counter is unavailable, still honor a trusted empty
        -- Blade-set counter. The old branch ignored 0/3 completely and could leave
        -- Exact Blade spamming forever with no way for station refill to take ownership.
        if current == nil then
            if Config.V93BladeAmmoDirectorEnabled == true then
                local now = os.clock()
                local exactActive = V6ExactBlade
                    and now - (tonumber(V6ExactBlade.LastSlashAt) or 0) <= 0.75
                local breakRecent = now - (tonumber(V91BladeRefillGuard.LastBreakAt) or 0)
                    <= math.max(0.35, tonumber(Config.V93MissingHudBreakWindow) or 1.10)
                local noProgressFor = now - (tonumber(V91BladeRefillGuard.LastProgressAt) or now)
                local enoughNoProgress = noProgressFor
                    >= math.max(1.20, tonumber(Config.V93MissingHudNoProgressSeconds) or 1.80)

                if bladeSets ~= nil
                    and setMaximum == Config.BladeSetMaximum
                    and bladeSets <= 0
                    and exactActive
                    and breakRecent
                    and enoughNoProgress
                    and not refillSequenceRunning
                    and not (StationRefill and StationRefill.Running) then
                    bladeRefillArmed = false
                    V91BladeRefillGuard.HoldUntil = now + 2.0

                    if V93BladeAmmoDirector.StationExhausted == true then
                        V93BladeAmmoDirector.BladelessHold = true
                        V93BladeAmmoDirector.Status = "BLADELESS HOLD • HUD UNKNOWN + 0/3"
                        statusText = V93BladeAmmoDirector.Status
                    else
                        print("[SliceHub V9.3][REFILL] HUD missing + Break + stall + 0/3 -> station")
                        beginStationRefill("V9.3 HUD-missing confirmed empty evidence", false)
                    end
                else
                    V93BladeAmmoDirector.Status = "HUD UNKNOWN • HOLDING AMMO"
                end
            else
                if bladeSets ~= nil
                    and setMaximum == Config.BladeSetMaximum
                    and bladeSets <= 0
                    and not refillSequenceRunning
                    and not (StationRefill and StationRefill.Running) then
                    bladeRefillArmed = false
                    V91BladeRefillGuard.HoldUntil = os.clock() + 2.0
                    beginStationRefill("V9.1 trusted sets 0/" .. tostring(Config.BladeSetMaximum), false)
                end
            end
            continue
        end

        if current > 0 then
            BladeZeroObservedAt = nil

            if Config.V93BladeAmmoDirectorEnabled == true then
                V93BladeAmmoDirector.BladelessHold = false
                if bladeSets ~= nil and bladeSets > 0 and V93BladeAmmoDirector.StationExhausted == true then
                    V93BladeAmmoDirector.StationExhausted = false
                    V93BladeAmmoDirector.StationFailures = 0
                    V93BladeAmmoDirector.Status = "AMMO RESTORED • STATION REARMED"
                elseif not refillSequenceRunning and not StationRefill.Running then
                    V93BladeAmmoDirector.Status = "READY • " .. tostring(current) .. "/" .. tostring(maximum)
                end
            end

            if not bladeCounterPositiveSince then
                bladeCounterPositiveSince = os.clock()
            end

            if not bladeRefillArmed
                and os.clock() - bladeCounterPositiveSince >= Config.AutoRefillRearmDelay then
                bladeRefillArmed = true
            end
        else
            bladeCounterPositiveSince = nil

            if current == 0
                and maximum == Config.BladeSegmentMaximum
                and bladeRefillArmed
                and os.clock() >= (tonumber(V93BladeAmmoDirector.DirectRetryAfter) or 0) then

                BladeZeroObservedAt = BladeZeroObservedAt or os.clock()

                local zeroStableFor = os.clock() - BladeZeroObservedAt
                if zeroStableFor >= (tonumber(Config.BladeZeroConfirmDuration) or 0.14) then
                    local verifyCurrent, verifyMaximum = readBladeSegments()

                    if verifyCurrent == 0
                        and verifyMaximum == Config.BladeSegmentMaximum then

                        BladeZeroObservedAt = nil

                        if bladeSets ~= nil
                            and setMaximum == Config.BladeSetMaximum
                            and bladeSets <= 0 then

                            bladeRefillArmed = false

                            local refillCharges = readBladeRefillCharges()
                            if refillCharges ~= nil and refillCharges <= 0 then
                                V93BladeAmmoDirector.BladelessHold = true
                                V96BladeRefillController.State = "EXHAUSTED"
                                V96BladeRefillController.Status = "OUT OF BLADES • 0/3 SETS • 0 REFILLS"
                                V93BladeAmmoDirector.Status = V96BladeRefillController.Status
                                statusText = V96BladeRefillController.Status
                            elseif Config.V93BladeAmmoDirectorEnabled == true
                                and V93BladeAmmoDirector.StationExhausted == true then
                                V93BladeAmmoDirector.BladelessHold = true
                                V93BladeAmmoDirector.Status = "BLADELESS HOLD • BROKEN + 0/3 + STATION RETRY"
                                statusText = V93BladeAmmoDirector.Status
                                print("[SliceHub V9.6][AMMO] station retry hold armed")
                            else
                                print("[SliceHub V9.6][REFILL] broken + 0/3 -> station")
                                local stationStarted = beginStationRefill(
                                    "V9.6 broken + 0/" .. tostring(Config.BladeSetMaximum),
                                    false,
                                    "Blades"
                                ) == true
                                if not stationStarted then
                                    bladeRefillArmed = true
                                    V93BladeAmmoDirector.DirectRetryAfter = os.clock()
                                        + math.max(0.35, tonumber(Config.V96BladeRenewRetryDelay) or 0.85)
                                    V96BladeRefillController.Status = "STATION START FAILED • RETRY ARMED"
                                    V93BladeAmmoDirector.Status = V96BladeRefillController.Status
                                end
                            end
                        else
                            print(
                                "[SliceHub V9.3][REFILL] confirmed 0/6 -> direct reload",
                                "sets=" .. tostring(bladeSets)
                            )
                            beginBladeRefill("ammo loop confirmed 0/6", false)
                        end
                    else
                        -- transient / stale zero reading: cancel instead of wasting a blade set
                        BladeZeroObservedAt = nil
                    end
                end
            else
                BladeZeroObservedAt = nil
            end
        end
    end
end)

---------------------------------------------------------------------
-- V9.8.2.9.8 FILL-BASED BLADE RENEW WATCHDOG
-- The legacy 0/6 text can lag or disappear. The actual fill gradient is
-- authoritative and account-independent, so sustained broken + spare sets
-- always rearms one bounded native renew attempt.
---------------------------------------------------------------------

V97BladeRenewWatchdog = V97BladeRenewWatchdog or {
    BrokenWithSpareSince = nil,
    LastTriggerAt = 0,
    Recoveries = 0,
}

task.spawn(function()
    while true do
        task.wait(0.10)

        if Config.V96BladeRefillControllerEnabled ~= true
            or not State.AutoRefillEnabled
            or not State.BladesEnabled
            or not State.FarmEnabled
            or refillSequenceRunning
            or (StationRefill and StationRefill.Running)
            or (
                V917BladeStationRecovery
                and os.clock()
                    < (
                        tonumber(
                            V917BladeStationRecovery
                                .PostRestockGraceUntil
                        )
                        or 0
                    )
            )
            or not character
            or not character.Parent
            or not humanoid
            or humanoid.Health <= 0 then
            V97BladeRenewWatchdog.BrokenWithSpareSince = nil
            continue
        end

        local fillOffset = readBladeFillOffset()
        local sets, setMaximum = readBladeSets()
        local brokenWithSpare = fillOffset ~= nil
            and bladeFillIsBroken(fillOffset)
            and sets ~= nil
            and setMaximum == Config.BladeSetMaximum
            and sets > 0

        if not brokenWithSpare then
            V97BladeRenewWatchdog.BrokenWithSpareSince = nil
            continue
        end

        local now = os.clock()
        V97BladeRenewWatchdog.BrokenWithSpareSince = V97BladeRenewWatchdog.BrokenWithSpareSince or now
        local brokenFor = now - V97BladeRenewWatchdog.BrokenWithSpareSince
        local delay = math.max(0.35, tonumber(Config.V97BladeRenewWatchdogSeconds) or 0.65)
        local cooldown = math.max(0.80, tonumber(Config.V97BladeRenewWatchdogCooldown) or 1.25)

        if brokenFor >= delay
            and now - (tonumber(V97BladeRenewWatchdog.LastTriggerAt) or 0) >= cooldown then
            V97BladeRenewWatchdog.LastTriggerAt = now
            V97BladeRenewWatchdog.BrokenWithSpareSince = now
            V97BladeRenewWatchdog.Recoveries += 1

            bladeRefillArmed = true
            BladeZeroObservedAt = nil
            V93BladeAmmoDirector.DirectRetryAfter = 0
            V93BladeAmmoDirector.BladelessHold = true
            V96BladeRefillController.State = "WATCHDOG_RENEW"
            V96BladeRefillController.Status = "FILL WATCHDOG • BROKEN + "
                .. tostring(sets) .. "/" .. tostring(Config.BladeSetMaximum)
            V93BladeAmmoDirector.Status = V96BladeRefillController.Status

            print("[SliceHub V9.8.2.9.8][AMMO] fill watchdog rearming native renew", "sets=" .. tostring(sets))
            beginBladeRefill("V9.7 fill watchdog broken + spare", false)
        end
    end
end)

---------------------------------------------------------------------
-- AUTO CUTSCENE SKIP (DETECTED + ONE E PRESS PER CUTSCENE)
---------------------------------------------------------------------

local CutsceneKeywords = {
	"cutscene", "cinematic", "sequence", "story", "dialogue", "dialog", "skip"
}

local function guiObjectIsActuallyVisible(object)
	if not object:IsA("GuiObject") or not object.Visible then return false end
	if object.AbsoluteSize.X <= 0 or object.AbsoluteSize.Y <= 0 then return false end

	local ancestor = object.Parent
	while ancestor and ancestor ~= playerGui do
		if ancestor:IsA("GuiObject") and not ancestor.Visible then
			return false
		end
		if ancestor:IsA("LayerCollector") and not ancestor.Enabled then
			return false
		end
		ancestor = ancestor.Parent
	end
	return true
end

local function containsCutsceneKeyword(value)
	local lower = string.lower(tostring(value or ""))
	for _, keyword in ipairs(CutsceneKeywords) do
		if string.find(lower, keyword, 1, true) then
			return true
		end
	end
	return false
end

local function getVisibleGuiText(object)
	if not guiObjectIsActuallyVisible(object) then return nil end
	if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
		local text = tostring(object.Text or "")
		text = string.gsub(text, "<.->", "")
		return string.lower(text)
	end
	return nil
end

local function hasCutsceneNamedAncestor(object)
	local node = object
	for _ = 1, 7 do
		if not node or node == playerGui then break end
		if containsCutsceneKeyword(node.Name) then return true end
		node = node.Parent
	end
	return false
end

local function detectCutsceneActiveRaw()
	local camera = Workspace.CurrentCamera
	local score = 0
	if camera and camera.CameraType == Enum.CameraType.Scriptable then
		score += 2
	end

	local controlGui = playerGui:FindFirstChild("TitanControlMenu")
	for _, object in ipairs(playerGui:GetDescendants()) do
		-- Never treat this script's own "Auto Skip Cutscene" toggle as a game cutscene.
		if controlGui and object:IsDescendantOf(controlGui) then
			continue
		end

		if object:IsA("GuiObject") and guiObjectIsActuallyVisible(object) then
			local compactName = string.gsub(string.lower(object.Name), "%s+", "")
			if (compactName == "e" or compactName == "ekey" or string.find(compactName, "skip", 1, true))
				and ((camera and camera.CameraType == Enum.CameraType.Scriptable) or hasCutsceneNamedAncestor(object)) then
				return true
			end
		end

		local text = getVisibleGuiText(object)
		if text then
			local compact = string.gsub(text, "%s+", " ")
			local exact = string.gsub(text, "%s+", "")

			-- A visible skip instruction is strong enough by itself.
			if string.find(compact, "press e", 1, true)
				or string.find(compact, "hold e", 1, true)
				or (string.find(compact, "skip", 1, true) and string.find(compact, "e", 1, true)) then
				return true
			end

			-- A lone E is accepted inside a cutscene-named UI tree, or while the
			-- camera is Scriptable (the usual state during a cinematic).
			if exact == "e" and (hasCutsceneNamedAncestor(object)
				or (camera and camera.CameraType == Enum.CameraType.Scriptable)) then
				return true
			end

			if hasCutsceneNamedAncestor(object) then
				score += 1
				if string.find(compact, "skip", 1, true) then
					score += 2
				end
			end
		elseif object:IsA("GuiObject") and guiObjectIsActuallyVisible(object) and hasCutsceneNamedAncestor(object) then
			score += 1
		end

		if score >= 3 then
			return true
		end
	end

	return score >= 3
end

local cutsceneDetectCacheAt = 0
local cutsceneDetectCacheValue = false

local function detectCutsceneActive(force)
    local now = os.clock()
    if not force and now - cutsceneDetectCacheAt < 0.20 then
        return cutsceneDetectCacheValue
    end

    local active = false
    local ok = pcall(function()
        active = detectCutsceneActiveRaw() == true
    end)

    cutsceneDetectCacheAt = now
    cutsceneDetectCacheValue = ok and active or false
    return cutsceneDetectCacheValue
end

V91CutsceneRemoteSkip = V91CutsceneRemoteSkip or {
    LastSentAt = 0,
    LastTarget = nil,
    Status = "Idle",
    Attempts = 0,
}

V94CutsceneDirector = {
    State = "IDLE",
    StateAt = os.clock(),
    EvidenceSince = nil,
    InactiveSince = nil,
    Attempts = 0,
    LastAttemptAt = 0,
    Status = "Waiting for live cutscene evidence",
}

-- Waves initializes Workspace.Waves before its Crates folder. Finishing the
-- cutscene during that small gap makes the game's own Zones module index
-- Workspace.Waves.Crates too early and permanently error for that session.
-- Never manufacture a client-side Crates folder; wait for the server-owned
-- folder and use the game's normal E-key route instead of double-sending the
-- generic Finished remote plus E.
local wavesCratesReadySince = nil

local function wavesCutsceneSetupState()
    local waves = Workspace:FindFirstChild("Waves")
    if not waves then
        wavesCratesReadySince = nil
        return false, true, "Not a Waves runtime"
    end

    -- Workspace.Waves alone is enough to classify this as Waves. The game can
    -- create that folder before Objective.Waves and Crates, which is exactly
    -- the unsafe initialization window we must not skip through.
    local unclimbable = Workspace:FindFirstChild("Unclimbable")
    local objective = unclimbable and unclimbable:FindFirstChild("Objective")
    local waveObjective = objective and objective:FindFirstChild("Waves")
    if not waveObjective then
        wavesCratesReadySince = nil
        return true, false, "Waiting for Waves objective setup"
    end

    local crates = waves:FindFirstChild("Crates")
    if not crates or not crates:IsA("Folder") then
        wavesCratesReadySince = nil
        return true, false, "Waiting for server Waves.Crates setup"
    end

    local now = os.clock()
    wavesCratesReadySince = wavesCratesReadySince or now
    if now - wavesCratesReadySince < 0.75 then
        return true, false, "Waves.Crates found; stabilizing setup"
    end

    return true, true, "Waves setup ready"
end

function V91CutsceneRemoteSkip.Target()
    local unclimbable = Workspace:FindFirstChild("Unclimbable")
    local cutscene = unclimbable and unclimbable:FindFirstChild("Cutscene")
    if not cutscene then return nil end

    local useMiddle = V4RaidDirector
        and V4RaidDirector.RaidName == "Colossal Raid"
        and V55ColossalDirector
        and (
            V55ColossalDirector.TransitionActive == true
            or V55ColossalDirector.P2Confirmed == true
            or V55ColossalDirector.Stage == "P2 BOSS"
        )

    if useMiddle then
        return cutscene:FindFirstChild("Middle") or cutscene:FindFirstChild("Start")
    end
    return cutscene:FindFirstChild("Start") or cutscene:FindFirstChild("Middle")
end

function V91CutsceneRemoteSkip.Try(reason)
    if Config.V91CutsceneRemoteBurstEnabled ~= true then return false end

    local inWaves, wavesReady, wavesReason = wavesCutsceneSetupState()
    if inWaves then
        -- Waves uses one safe input path only. Sending both the generic
        -- Finished remote and E can complete initialization twice.
        V91CutsceneRemoteSkip.Status = wavesReady
            and "Waves safe key-only skip"
            or tostring(wavesReason or "Waiting for Waves setup")
        return false
    end

    local target = V91CutsceneRemoteSkip.Target()
    if not target then return false end

    local now = os.clock()
    if target == V91CutsceneRemoteSkip.LastTarget
        and now - (tonumber(V91CutsceneRemoteSkip.LastSentAt) or 0)
            < math.max(0.18, (tonumber(Config.V94CutsceneRetryGap) or 0.55) * 0.65) then
        return false
    end

    local post = resolvePath(ReplicatedStorage, {"Assets", "Remotes", "POST"})
    if not post or not post:IsA("RemoteEvent") then return false end

    V91CutsceneRemoteSkip.LastTarget = target
    V91CutsceneRemoteSkip.LastSentAt = now
    local sent = pcall(function()
        post:FireServer("Functions", "Finished", target)
    end)

    if sent then
        V91CutsceneRemoteSkip.Attempts += 1
    end
    V91CutsceneRemoteSkip.Status = string.format(
        "%s attempt %d • %s",
        tostring(target.Name),
        tonumber(V91CutsceneRemoteSkip.Attempts) or 0,
        tostring(reason or "verified")
    )
    V94RunRecorder.Record("CUTSCENE_REMOTE", V91CutsceneRemoteSkip.Status)
    print("[SliceHub V9.4][CUTSCENE]", V91CutsceneRemoteSkip.Status)
    return sent == true
end

task.spawn(function()
    local function setState(nextState)
        if V94CutsceneDirector.State ~= nextState then
            V94RunRecorder.Record(
                "CUTSCENE_STATE",
                tostring(V94CutsceneDirector.State) .. " -> " .. tostring(nextState),
                {attempts = V94CutsceneDirector.Attempts}
            )
        end
        V94CutsceneDirector.State = nextState
        V94CutsceneDirector.StateAt = os.clock()
    end

    while true do
        task.wait(Config.CutsceneCheckDelay)

        local enabled = State.AutoSkipCutsceneEnabled
            or (V4RaidDirector and V4RaidDirector.Enabled and State.RaidAutoSkipEnabled)

        if type(SliceHubClampAutoSkipCutscene) == "function" then
            enabled = SliceHubClampAutoSkipCutscene(enabled)
        end

        if not enabled then
            cutsceneDetectedSince = nil
            cutsceneInactiveSince = nil
            cutsceneSkipSent = false
            V94CutsceneDirector.EvidenceSince = nil
            V94CutsceneDirector.InactiveSince = nil
            V94CutsceneDirector.Attempts = 0
            V94CutsceneDirector.LastAttemptAt = 0
            V94CutsceneDirector.Status = "Disabled"
            V91CutsceneRemoteSkip.Attempts = 0
            setState("IDLE")
            continue
        end

        local active = false
        local ok = pcall(function()
            active = detectCutsceneActive(V94CutsceneDirector.State ~= "IDLE")
        end)
        if not ok then active = false end

        local now = os.clock()
        local state = V94CutsceneDirector.State

        if state == "IDLE" then
            if active then
                cutsceneDetectedSince = now
                V94CutsceneDirector.EvidenceSince = now
                V94CutsceneDirector.Status = "Verifying live cutscene evidence"
                setState("DETECTING")
            end

        elseif state == "DETECTING" then
            if not active then
                cutsceneDetectedSince = nil
                V94CutsceneDirector.EvidenceSince = nil
                V94CutsceneDirector.Status = "Evidence vanished before confirmation"
                setState("IDLE")
            elseif now - (V94CutsceneDirector.EvidenceSince or now)
                >= math.max(0.25, tonumber(Config.CutsceneStableTime) or 0.40) then
                cutsceneSkipSent = true
                V94CutsceneDirector.Attempts = 0
                V94CutsceneDirector.LastAttemptAt = 0
                V91CutsceneRemoteSkip.Attempts = 0
                V94CutsceneDirector.Status = "Live evidence confirmed"
                setState("ACTIVE_CONFIRMED")
            end

        elseif state == "ACTIVE_CONFIRMED" then
            if not active then
                cutsceneInactiveSince = now
                V94CutsceneDirector.InactiveSince = now
                V94CutsceneDirector.Status = "Release detected"
                setState("VERIFY_RELEASE")
            else
                local inWaves, wavesReady, wavesReason = wavesCutsceneSetupState()
                local maxAttempts = inWaves
                    and 2
                    or math.max(1, math.floor(tonumber(Config.V94CutsceneMaxAttempts) or 4))
                local retryGap = inWaves
                    and 0.90
                    or math.max(0.30, tonumber(Config.V94CutsceneRetryGap) or 0.55)

                if inWaves and not wavesReady then
                    -- Do not spend attempts while the server is still creating
                    -- the Crates folder required by the game's Zones module.
                    V94CutsceneDirector.Status = tostring(
                        wavesReason or "Waiting for Waves setup"
                    )
                elseif V94CutsceneDirector.Attempts < maxAttempts
                    and now - (tonumber(V94CutsceneDirector.LastAttemptAt) or 0)
                        >= retryGap then

                    V94CutsceneDirector.Attempts += 1
                    V94CutsceneDirector.LastAttemptAt = now

                    if not inWaves then
                        pcall(
                            V91CutsceneRemoteSkip.Try,
                            "verified attempt " .. tostring(V94CutsceneDirector.Attempts)
                        )
                    end

                    -- Waves intentionally uses only the native E-key route.
                    simulateHumanKeyPress(Config.CutsceneKey)
                    V94CutsceneDirector.Status = (inWaves and "Waves safe skip attempt " or "Skip attempt ")
                        .. tostring(V94CutsceneDirector.Attempts)
                        .. "/" .. tostring(maxAttempts)

                elseif V94CutsceneDirector.Attempts >= maxAttempts
                    and now - (tonumber(V94CutsceneDirector.LastAttemptAt) or now)
                        >= math.max(0.50, tonumber(Config.V94CutsceneRecoveryDelay) or 0.85) then
                    V94CutsceneDirector.Status = "Attempts exhausted; restoring control"
                    setState("RECOVER")
                end
            end

        elseif state == "RECOVER" then
            -- Restore local control once after all spaced attempts. Do not spam E.
            pcall(function()
                if V55ColossalDirector and V55ColossalDirector.RestoreControl then
                    V55ColossalDirector.RestoreControl()
                end
            end)
            V94RunRecorder.Record("CUTSCENE_RECOVERY", "Bounded attempts exhausted")
            setState("WAIT_CLEAR")

        elseif state == "WAIT_CLEAR" then
            if not active then
                cutsceneInactiveSince = now
                V94CutsceneDirector.InactiveSince = now
                V94CutsceneDirector.Status = "Release detected after recovery"
                setState("VERIFY_RELEASE")
            end

        elseif state == "VERIFY_RELEASE" then
            if active then
                V94CutsceneDirector.InactiveSince = nil
                setState("WAIT_CLEAR")
            elseif now - (V94CutsceneDirector.InactiveSince or cutsceneInactiveSince or now)
                >= math.max(0.30, tonumber(Config.CutsceneReleaseDelay) or 0.45) then
                cutsceneDetectedSince = nil
                cutsceneInactiveSince = nil
                cutsceneSkipSent = false
                V94CutsceneDirector.EvidenceSince = nil
                V94CutsceneDirector.InactiveSince = nil
                V94CutsceneDirector.Attempts = 0
                V94CutsceneDirector.LastAttemptAt = 0
                V94CutsceneDirector.Status = "Released and rearmed"
                V91CutsceneRemoteSkip.Attempts = 0
                setState("IDLE")
            end
        end
    end
end)


