-- OBJECTIVE BRAIN + COMBAT PRESETS
---------------------------------------------------------------------

local MissionObjectiveHistory = {
    Order = {},
    LatestByKey = {},
    LastUpdatedAt = 0,
    SelectedObjective = nil,
    SelectedMap = nil,
    MetadataUpdatedAt = 0,
}

local function readLastMissionInfoForWebhook()
    local document = nil

    pcall(function()
        local environment = nil
        if type(getgenv) == "function" then
            environment = getgenv()
        end

        if type(environment) == "table"
            and type(environment.AOT_LastMissionInfo) == "table" then
            document = environment.AOT_LastMissionInfo
        elseif type(_G) == "table"
            and type(_G.AOT_LastMissionInfo) == "table" then
            document = _G.AOT_LastMissionInfo
        end
    end)

    if type(document) ~= "table" then
        local readFile = nil

        pcall(function()
            if type(getgenv) == "function" then
                local environment = getgenv()
                if type(environment) == "table"
                    and type(environment.readfile) == "function" then
                    readFile = environment.readfile
                end
            end
        end)

        if not readFile and type(_G) == "table" and type(_G.readfile) == "function" then
            readFile = _G.readfile
        end

        if readFile then
            local okRead, raw = pcall(readFile, "AOT_LastMissionInfo_v1.json")
            if okRead and type(raw) == "string" and raw ~= "" then
                local okDecode, decoded = pcall(function()
                    return HttpService:JSONDecode(raw)
                end)

                if okDecode and type(decoded) == "table" then
                    document = decoded
                end
            end
        end
    end

    if type(document) == "table" then
        local objective = tostring(document.Objective or "")
        local mapName = tostring(document.Map or "")
        MissionObjectiveHistory.SelectedCreateMode = tostring(document.CreateMode or document.Mode or "Mission")
        MissionObjectiveHistory.SelectedRaidChoice = tostring(document.RaidChoice or "")
        MissionObjectiveHistory.SelectedDifficulty = tostring(document.Difficulty or "")

        if objective ~= "" then
            MissionObjectiveHistory.SelectedObjective = objective
        end

        if mapName ~= "" then
            MissionObjectiveHistory.SelectedMap = mapName
        end

        MissionObjectiveHistory.MetadataUpdatedAt = tonumber(document.UpdatedAt) or 0
    end

    return document
end

V3MissionIdentity = V3MissionIdentity or {}

function V3MissionIdentity.CombinedTasksLower()
    local lines = {}
    for _, key in ipairs(MissionObjectiveHistory.Order) do
        local value = MissionObjectiveHistory.LatestByKey[key]
        if value then
            lines[#lines + 1] = string.lower(tostring(value))
        end
    end
    return table.concat(lines, " | ")
end

function V3MissionIdentity.InferSpecialMissionTypeFromTasks()
    local value = V3MissionIdentity.CombinedTasksLower()

    local function has(word)
        return string.find(value, string.lower(word), 1, true) ~= nil
    end

    if has("escort convoy") or has("escort supplies") then return "Escort" end
    if has("breach") or has("barricade") then return "Breach" end
    if has("stall") then return "Stall" end
    if has("protect") then return "Protect" end
    if has("guard") then return "Guard" end
    if has("defend hq") or has("defend headquarters") or has("beacon") then return "Defend" end
    if has("raid") then return "Raid" end

    return nil
end

function V3MissionIdentity.TasksLookLikeNormalSkirmish()
    local value = V3MissionIdentity.CombinedTasksLower()
    local generic = {
        "slay titans",
        "most kills",
        "avoid damage",
        "heal injuries",
        "escape grabs",
        "blind titans",
        "no refills",
        "no grabs",
        "injure titans",
    }

    for _, phrase in ipairs(generic) do
        if string.find(value, phrase, 1, true) then
            return true
        end
    end

    return false
end

function V3MissionIdentity.GetSpecialMissionTypeForWebhook()
    local liveSpecial = V3MissionIdentity.InferSpecialMissionTypeFromTasks()
    if liveSpecial then
        return liveSpecial
    end

    if V3MissionIdentity.TasksLookLikeNormalSkirmish() then
        return nil
    end

    if not MissionObjectiveHistory.SelectedObjective then
        readLastMissionInfoForWebhook()
    end

    local selected = tostring(MissionObjectiveHistory.SelectedObjective or "")
    local lowerSelected = string.lower(selected)

    local updatedAt = tonumber(MissionObjectiveHistory.MetadataUpdatedAt) or 0
    local age = updatedAt > 0 and math.max(0, os.time() - updatedAt) or math.huge

    if age <= 900
        and selected ~= ""
        and lowerSelected ~= "skirmish"
        and lowerSelected ~= "random"
        and lowerSelected ~= "general"
        and lowerSelected ~= "objective" then
        return selected
    end

    return nil
end

V3MissionIdentity.KnownMapAliases = {
    ["Shiganshina"] = {"shiganshina"},
    ["Trost"] = {"trost"},
    ["Outskirts"] = {"outskirts"},
    ["Giant Forest"] = {"giant forest", "giantforest", "forest"},
    ["Utgard Castle"] = {"utgard castle", "utgardcastle", "utgard"},
    ["Loading Docks"] = {"loading docks", "loadingdocks", "docks"},
    ["Stohess"] = {"stohess"},
    ["Chapel"] = {"chapel"},
}

V3MissionIdentity.MapTracker = {
    ObservedMap = nil,
    ObservedAt = 0,
    PendingConsumed = false,
}

V3MissionIdentity.PlaceIdMaps = {
    -- Primary universe map places
    [13379349730] = "Shiganshina",
    [14012874501] = "Trost",
    [14638336319] = "Giant Forest",
    [13904207646] = "Outskirts",
    [15220308770] = "Utgard Castle",
    [17688739434] = "Loading Docks",
    [15824912319] = "Stohess",
    [126678335159530] = "Chapel",

    -- Alternate universe/place set
    [17373821193] = "Shiganshina",
    [15393230324] = "Trost",
    [17373828240] = "Giant Forest",
    [17373824844] = "Outskirts",
    [18182863694] = "Utgard Castle",
    [110415968652032] = "Loading Docks",
    [139092911630535] = "Stohess",
    [133979984250876] = "Chapel",
}

function V3MissionIdentity.CanonicalMapFromText(value)
    local lowerValue = string.lower(tostring(value or ""))
    if lowerValue == "" then return nil end

    for mapName, aliases in pairs(V3MissionIdentity.KnownMapAliases) do
        for _, alias in ipairs(aliases) do
            local lowerAlias = string.lower(alias)
            if lowerValue == lowerAlias
                or string.find(lowerValue, lowerAlias, 1, true) then
                return mapName
            end
        end
    end

    return nil
end

function V3MissionIdentity.ExactWorkspaceMap()
    local rawMap = Workspace:GetAttribute("Map")
    local canonical = V3MissionIdentity.CanonicalMapFromText(rawMap)

    if not canonical then
        canonical = V3MissionIdentity.PlaceIdMaps[game.PlaceId]
    end

    if canonical then
        V3MissionIdentity.MapTracker.ObservedMap = canonical
        V3MissionIdentity.MapTracker.ObservedAt = os.clock()
        return canonical
    end

    return nil
end

function V3MissionIdentity.ObserveMapFromVisibleGui()
    local best = nil

    for _, object in ipairs(playerGui:GetDescendants()) do
        if object:IsA("TextLabel")
            or object:IsA("TextButton")
            or object:IsA("TextBox") then

            local visible = object.Visible
                and object.AbsoluteSize.X > 0
                and object.AbsoluteSize.Y > 0

            if visible then
                local textValue = tostring(object.Text or "")
                local canonical = V3MissionIdentity.CanonicalMapFromText(textValue)

                if canonical then
                    -- Prefer labels whose entire text is the map name.
                    local cleaned = string.lower(string.gsub(textValue, "^%s*(.-)%s*$", "%1"))
                    local exact = false
                    for _, alias in ipairs(V3MissionIdentity.KnownMapAliases[canonical] or {}) do
                        if cleaned == string.lower(alias) then
                            exact = true
                            break
                        end
                    end

                    if exact then
                        return canonical
                    end

                    best = best or canonical
                end
            end
        end
    end

    return best
end

function V3MissionIdentity.ObserveMapFromExplicitMetadata()
    local candidateObjects = {
        Workspace,
        game:GetService("ReplicatedStorage"),
    }

    local attributeNames = {
        "Map",
        "MapName",
        "MissionMap",
        "CurrentMap",
        "LevelName",
    }

    for _, root in ipairs(candidateObjects) do
        for _, attributeName in ipairs(attributeNames) do
            local value = nil
            pcall(function()
                value = root:GetAttribute(attributeName)
            end)

            local canonical = V3MissionIdentity.CanonicalMapFromText(value)
            if canonical then
                return canonical
            end
        end

        local checked = 0
        for _, object in ipairs(root:GetDescendants()) do
            checked += 1
            if checked > 3500 then break end

            local lowerName = string.lower(tostring(object.Name or ""))
            local looksLikeMapMetadata =
                lowerName == "map"
                or lowerName == "mapname"
                or lowerName == "missionmap"
                or lowerName == "currentmap"
                or lowerName == "levelname"

            if looksLikeMapMetadata and object:IsA("StringValue") then
                local canonical = V3MissionIdentity.CanonicalMapFromText(object.Value)
                if canonical then
                    return canonical
                end
            end
        end
    end

    return nil
end

task.spawn(function()
    while true do
        task.wait(0.35)

        if not isMissionRuntimePlace() then
            continue
        end

        local observed = V3MissionIdentity.ExactWorkspaceMap()
            or V3MissionIdentity.ObserveMapFromVisibleGui()
            or V3MissionIdentity.ObserveMapFromExplicitMetadata()

        if observed then
            V3MissionIdentity.MapTracker.ObservedMap = observed
            V3MissionIdentity.MapTracker.ObservedAt = os.clock()
        end
    end
end)

function V3MissionIdentity.GetTrackedMissionMap()
    if V3MissionIdentity.MapTracker.ObservedMap then
        return V3MissionIdentity.MapTracker.ObservedMap
    end

    local guiMap = V3MissionIdentity.ObserveMapFromVisibleGui()
    if guiMap then
        V3MissionIdentity.MapTracker.ObservedMap = guiMap
        V3MissionIdentity.MapTracker.ObservedAt = os.clock()
        return guiMap
    end

    local metadataMap = V3MissionIdentity.ObserveMapFromExplicitMetadata()
    if metadataMap then
        V3MissionIdentity.MapTracker.ObservedMap = metadataMap
        V3MissionIdentity.MapTracker.ObservedAt = os.clock()
        return metadataMap
    end

    return nil
end

function V3MissionIdentity.GetMissionMapForWebhook()
    -- V3: the game's Host reads Workspace:GetAttribute("Map").
    -- This is authoritative and beats GUI text or saved lobby metadata.
    local exactMap = V3MissionIdentity.ExactWorkspaceMap()
    if exactMap then
        return exactMap
    end

    -- Secondary current-run evidence.
    local tracked = V3MissionIdentity.GetTrackedMissionMap()
    if tracked then
        return tracked
    end

    -- 2. Fresh launcher metadata is consumed once for this mission runtime.
    if not MissionObjectiveHistory.SelectedMap then
        readLastMissionInfoForWebhook()
    end

    local updatedAt = tonumber(MissionObjectiveHistory.MetadataUpdatedAt) or 0
    local age = updatedAt > 0 and math.max(0, os.time() - updatedAt) or math.huge
    local selectedMap = V3MissionIdentity.CanonicalMapFromText(MissionObjectiveHistory.SelectedMap)

    if not V3MissionIdentity.MapTracker.PendingConsumed
        and age <= 300
        and selectedMap then

        V3MissionIdentity.MapTracker.PendingConsumed = true
        V3MissionIdentity.MapTracker.ObservedMap = selectedMap
        V3MissionIdentity.MapTracker.ObservedAt = os.clock()
        return selectedMap
    end

    -- Never guess from arbitrary Workspace object names.
    return nil
end

function V3MissionIdentity.GetRunMetadataForWebhook()
    local document = readLastMissionInfoForWebhook()
    local createMode = tostring(MissionObjectiveHistory.SelectedCreateMode or (document and document.CreateMode) or "Mission")
    local objective = tostring(MissionObjectiveHistory.SelectedObjective or (document and document.Objective) or "")
    local raidChoice = tostring(MissionObjectiveHistory.SelectedRaidChoice or (document and document.RaidChoice) or "")
    local difficulty = tostring(MissionObjectiveHistory.SelectedDifficulty or (document and document.Difficulty) or "Unknown")

    local liveRaid = V4RaidDirector and V4RaidDirector.Enabled and tostring(V4RaidDirector.RaidName or "") or ""
    local liveMap = V3MissionIdentity.ExactWorkspaceMap and V3MissionIdentity.ExactWorkspaceMap() or nil
    local liveSpecial = V3MissionIdentity.InferSpecialMissionTypeFromTasks and V3MissionIdentity.InferSpecialMissionTypeFromTasks() or nil
    local explicitLiveMission = liveMap == "Loading Docks" and liveSpecial == "Stall" and liveRaid == ""

    -- Live runtime evidence is authoritative. Saved lobby selection is only fallback
    -- while the live run has not identified itself yet.
    local isRaid = not explicitLiveMission and (
        liveRaid ~= ""
        or (createMode == "Raid" and liveSpecial == nil)
        or (raidChoice ~= "" and liveSpecial == nil)
    )

    local raidName = liveRaid ~= "" and liveRaid or objective
    if raidName == "" then raidName = raidChoice end
    raidName = string.gsub(raidName, " Raid$", "")

    return {
        RunType = isRaid and "Raid" or "Mission",
        RaidName = isRaid and (raidName ~= "" and raidName or nil) or nil,
        Difficulty = difficulty,
        RaidChoice = isRaid and raidChoice or "",
    }
end

function V3MissionIdentity.GetMissionDisplayForWebhook()
    local specialType = V3MissionIdentity.GetSpecialMissionTypeForWebhook()
    local mapName = V3MissionIdentity.GetMissionMapForWebhook()

    if specialType and mapName then
        return specialType .. "\n" .. mapName
    elseif specialType then
        return specialType
    elseif mapName then
        return mapName
    end

    return "Unknown mission"
end

function V3MissionIdentity.CleanMissionObjectiveLine(raw)
    local textValue = tostring(raw or "")
    textValue = string.gsub(textValue, "<.->", "")
    textValue = string.gsub(textValue, "^%s+", "")
    textValue = string.gsub(textValue, "%s+$", "")
    textValue = string.gsub(textValue, "%s+", " ")

    if textValue == "" then
        return nil, nil
    end

    local lower = string.lower(textValue)

    -- Skip headers/status noise and keep actual mission objective rows.
    if lower == "objectives"
        or string.find(lower, "reward boost", 1, true)
        or string.find(lower, "mission completed", 1, true)
        or string.find(lower, "mission failed", 1, true)
        or string.find(lower, "brain:", 1, true)
        or string.find(lower, "webhook + perf", 1, true)
        or string.find(lower, "settings reload automatically", 1, true) then
        return nil, nil
    end

    local objectiveWords = {
        "escort convoy",
        "escort supplies",
        "titan assists",
        "injure titans",
        "slay titans",
        "avoid damage",
        "most kills",
        "heal injuries",
        "escape grabs",
        "execute",
        "blind titans",
        "no refills",
        "no grabs",
        "defend",
        "protect",
        "stall",
        "capture",
        "repair",
        "breach",
    }

    local matched = false
    for _, word in ipairs(objectiveWords) do
        if string.find(lower, word, 1, true) then
            matched = true
            break
        end
    end

    if not matched then
        return nil, nil
    end

    -- Key ignores progress so [0/2] updates replace earlier [0/2]/[1/2] entries.
    local key = string.gsub(lower, "%s*%[%s*%d+%s*/%s*%d+%s*%]", "")
    key = string.gsub(key, "%s+", " ")
    key = string.gsub(key, "^%s+", "")
    key = string.gsub(key, "%s+$", "")

    return key, textValue
end

function V3MissionIdentity.RememberMissionObjectiveLine(raw)
    local key, cleaned = V3MissionIdentity.CleanMissionObjectiveLine(raw)
    if not key or not cleaned then return end

    if MissionObjectiveHistory.LatestByKey[key] == nil then
        table.insert(MissionObjectiveHistory.Order, key)
    end

    MissionObjectiveHistory.LatestByKey[key] = cleaned
    MissionObjectiveHistory.LastUpdatedAt = os.clock()
end

function V3MissionIdentity.GetMissionObjectiveSummary()
    local lines = {}

    for _, key in ipairs(MissionObjectiveHistory.Order) do
        local value = MissionObjectiveHistory.LatestByKey[key]
        if value and value ~= "" then
            table.insert(lines, "• " .. value)
        end
    end

    if #lines == 0 then
        return "No objectives detected"
    end

    return table.concat(lines, "\n")
end

;(function() -- scoped objective/preset helpers
	local objectiveState = {
		LastScan = 0,
		LastPositionScan = 0,
		Text = "",
		Mode = "General",
		Position = nil,
	}

	local objectiveKeywords = {"objective", "objectives", "defend", "guard", "protect", "escort", "stall", "castle", "cart", "gate", "wall", "tower", "point", "base", "hq", "headquarters", "beacon", "supply", "supplies", "breach", "barricade", "district", "door"}
	local protectedObjectiveWords = {"titan", "titans", "nape", "humanoid", "root", "player", "character", "camera", "remote", "debris", "effect", "hitbox"}

	local function lowerText(value)
		local text = tostring(value or "")
		text = string.gsub(text, "<.->", "")
		text = string.gsub(text, "%s+", " ")
		return string.lower(text)
	end

	local function containsAny(text, words)
		text = lowerText(text)
		for _, word in ipairs(words) do
			if string.find(text, string.lower(word), 1, true) then return true end
		end
		return false
	end

	local function visibleTextObject(object)
		if not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then return false end
		if not object.Visible or object.AbsoluteSize.X <= 0 or object.AbsoluteSize.Y <= 0 then return false end
		local node = object.Parent
		while node and node ~= playerGui do
			if node:IsA("GuiObject") and not node.Visible then return false end
			if node:IsA("LayerCollector") and not node.Enabled then return false end
			node = node.Parent
		end
		return true
	end

	local function readObjectiveText()
		local lines = {}
		for _, object in ipairs(playerGui:GetDescendants()) do
            if screenGui and object:IsDescendantOf(screenGui) then
                continue
            end

			if visibleTextObject(object) then
				local raw = tostring(object.Text or "")
				local lower = lowerText(raw)
				if containsAny(lower, {"objectives", "objective", "defend", "guard", "protect", "escort", "stall", "breach", "hq", "headquarters", "beacon", "supply", "supplies", "repair", "capture", "slay", "execute", "blind", "grabs", "assist", "injure", "damage", "kills", "refills"}) then
					table.insert(lines, raw)
                    V3MissionIdentity.RememberMissionObjectiveLine(raw)
				end
			end
		end
		return table.concat(lines, " | ")
	end

	local function detectModeFromText(text)
		local lower = lowerText(text)
		if string.find(lower, "defend", 1, true) or string.find(lower, "guard", 1, true) or string.find(lower, "protect", 1, true) or string.find(lower, "escort", 1, true) or string.find(lower, "stall", 1, true) or string.find(lower, "breach", 1, true) or string.find(lower, "hq", 1, true) or string.find(lower, "headquarters", 1, true) or string.find(lower, "beacon", 1, true) or string.find(lower, "supply", 1, true) then return "Objective" end
		if string.find(lower, "slay", 1, true) or string.find(lower, "kill", 1, true) then return "Slay" end
		return "General"
	end

	local function objectLooksProtected(object)
		local node = object
		for _ = 1, 6 do
			if not node then break end
			if containsAny(node.Name, protectedObjectiveWords) then return true end
			node = node.Parent
		end
		return false
	end

	local function getObjectPosition(object)
		if object:IsA("BasePart") then return object.Position end
		if object:IsA("Model") then
			local ok, pivot = pcall(function() return object:GetPivot() end)
			if ok and pivot then return pivot.Position end
		end
		return nil
	end

	local function findObjectivePosition()
		local now = os.clock()
		if now - objectiveState.LastPositionScan < 2.0 then return objectiveState.Position end
		objectiveState.LastPositionScan = now
		local bestPosition, bestScore = nil, -math.huge
		local origin = rootPart and rootPart.Position or Vector3.zero
		for _, object in ipairs(Workspace:GetDescendants()) do
			if (object:IsA("BasePart") or object:IsA("Model")) and not objectLooksProtected(object) and containsAny(object.Name, objectiveKeywords) then
				local position = getObjectPosition(object)
				if position then
					local score = 0
					local name = lowerText(object.Name)
					if string.find(name, "headquarters", 1, true) or string.find(name, "hq", 1, true) or string.find(name, "beacon", 1, true) then score += 55 end
					if string.find(name, "breach", 1, true) or string.find(name, "gate", 1, true) or string.find(name, "wall", 1, true) then score += 42 end
					if string.find(name, "supply", 1, true) or string.find(name, "supplies", 1, true) then score += 40 end
					if string.find(name, "castle", 1, true) then score += 35 end
					if string.find(name, "objective", 1, true) then score += 30 end
					if string.find(name, "defend", 1, true) or string.find(name, "guard", 1, true) or string.find(name, "protect", 1, true) then score += 22 end
					if string.find(name, "cart", 1, true) or string.find(name, "escort", 1, true) then score += 18 end
					score -= math.min(120, (position - origin).Magnitude / 12)
					if score > bestScore then bestScore, bestPosition = score, position end
				end
			end
		end
		objectiveState.Position = bestPosition
		return bestPosition
	end

	updateObjectiveBrain = function(force)
		local now = os.clock()
		if not force and now - objectiveState.LastScan < 0.35 then return objectiveState end
		objectiveState.LastScan = now
		objectiveState.Text = readObjectiveText()
		objectiveState.Mode = detectModeFromText(objectiveState.Text)
		local priority = tostring(State.TargetPriority or "Balanced")
		local objectiveActive = priority == "Objective" or (priority == "Balanced" and objectiveState.Mode == "Objective")
		if objectiveActive then findObjectivePosition() end
		if applyObjectiveRuntimeTuning then pcall(applyObjectiveRuntimeTuning, objectiveActive) end
		if objectiveBrainStatusLabel then
			local text = objectiveState.Text ~= "" and objectiveState.Text or "No objective text detected"
            if not SliceHubUIShouldSleep() then
			    objectiveBrainStatusLabel.Text = string.format("Brain: %s  •  %s", objectiveState.Mode or "General", string.sub(text, 1, 70))
            end
		end
		return objectiveState
	end

	getObjectiveMode = function()
		return (updateObjectiveBrain(false).Mode or "General")
	end

	getObjectiveTargetScore = function(entry)
		if not entry then return math.huge end
		local score = tonumber(entry.DistanceSquared) or math.huge
		local state = updateObjectiveBrain(false)
		local priority = tostring(State.TargetPriority or "Balanced")
		local useObjective = priority == "Objective" or (priority == "Balanced" and state.Mode == "Objective")
		if useObjective and state.Position and entry.Part then
			local distanceToObjective = (entry.Part.Position - state.Position).Magnitude
			local distanceToPlayer = math.sqrt(tonumber(entry.DistanceSquared) or 0)
			score = distanceToObjective * distanceToObjective + distanceToPlayer * 0.45
		end
		return score
	end

end)()

---------------------------------------------------------------------
-- V2.1 OBJECTIVE DIRECTOR PROBE
-- Diagnostic only: does not move the player or interact with objectives.
---------------------------------------------------------------------

;(function()
    local Probe = {
        LastObjectiveSignature = "",
        LastFullScanAt = 0,
        Motion = setmetatable({}, {__mode = "k"}),
        PrintInterval = 7.5,
        MaxResults = 20,
    }

    local textKeywords = {
        "escort", "convoy", "supplies", "supply",
        "cart", "carts", "injure titans", "titan assists",
        "defend", "protect", "deliver", "delivery",
    }

    local objectKeywords = {
        supply = 90,
        supplies = 95,
        cargo = 80,
        package = 80,
        crate = 60,
        box = 25,
        cart = 95,
        carts = 95,
        convoy = 100,
        wagon = 85,
        escort = 70,
        delivery = 80,
        deliver = 75,
        dropoff = 90,
        drop = 35,
        pickup = 75,
        objective = 30,
        route = 25,
        checkpoint = 25,
    }

    local excludeWords = {
        "titan", "character", "player", "camera",
        "effect", "debris", "nape", "hitbox", "remote",
    }

    local function lower(value)
        return string.lower(tostring(value or ""))
    end

    local function containsAny(value, words)
        local l = lower(value)
        for _, word in ipairs(words) do
            if string.find(l, lower(word), 1, true) then
                return true
            end
        end
        return false
    end

    local function visibleTextObject(object)
        if not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then
            return false
        end
        if not object.Visible or object.AbsoluteSize.X <= 0 or object.AbsoluteSize.Y <= 0 then
            return false
        end

        local node = object.Parent
        while node and node ~= playerGui do
            if node:IsA("GuiObject") and not node.Visible then
                return false
            end
            if node:IsA("LayerCollector") and not node.Enabled then
                return false
            end
            node = node.Parent
        end
        return true
    end

    local function readObjectiveSnapshot()
        local lines = {}

        for _, object in ipairs(playerGui:GetDescendants()) do
            if visibleTextObject(object) then
                local raw = tostring(object.Text or "")
                if containsAny(raw, textKeywords) then
                    lines[#lines + 1] = raw
                end
            end
        end

        table.sort(lines)
        return table.concat(lines, " | ")
    end

    local function getPosition(object)
        if object:IsA("BasePart") then
            return object.Position
        end

        if object:IsA("Model") then
            local ok, pivot = pcall(function()
                return object:GetPivot()
            end)
            if ok and pivot then
                return pivot.Position
            end
        end

        return nil
    end

    local function getCandidateRoot(object)
        if object:IsA("Model") then
            return object
        end

        local model = object:FindFirstAncestorOfClass("Model")
        if model and model.Parent ~= nil and not containsAny(model:GetFullName(), excludeWords) then
            return model
        end

        return object
    end

    local function getInteractionFlags(root)
        local hasPrompt = false
        local hasClick = false
        local hasTouch = false
        local promptNames = {}

        local function inspect(object)
            if object:IsA("ProximityPrompt") then
                hasPrompt = true
                promptNames[#promptNames + 1] =
                    tostring(object.ObjectText or "") .. "/" .. tostring(object.ActionText or "")
            elseif object:IsA("ClickDetector") then
                hasClick = true
            elseif object:IsA("TouchTransmitter") then
                hasTouch = true
            end
        end

        inspect(root)
        for _, object in ipairs(root:GetDescendants()) do
            inspect(object)
        end

        return hasPrompt, hasClick, hasTouch, table.concat(promptNames, ",")
    end

    local function keywordScore(name)
        local l = lower(name)
        local score = 0

        for word, value in pairs(objectKeywords) do
            if string.find(l, word, 1, true) then
                score += value
            end
        end

        return score
    end

    local function getMotionScore(root, position, now)
        local previous = Probe.Motion[root]
        Probe.Motion[root] = {
            Position = position,
            Time = now,
        }

        if not previous or not previous.Position or not previous.Time then
            return 0, 0
        end

        local dt = math.max(0.01, now - previous.Time)
        local moved = (position - previous.Position).Magnitude
        local speed = moved / dt

        local score = 0
        if moved >= 2 then score += 20 end
        if moved >= 8 then score += 25 end
        if speed >= 5 then score += 20 end

        return score, moved
    end

    local function collectCandidates()
        local now = os.clock()
        local seen = {}
        local candidates = {}
        local origin = rootPart and rootPart.Position or Vector3.zero

        for _, object in ipairs(Workspace:GetDescendants()) do
            if object:IsA("Model")
                or object:IsA("BasePart")
                or object:IsA("ProximityPrompt")
                or object:IsA("ClickDetector")
                or object:IsA("TouchTransmitter") then

                local root = getCandidateRoot(object)
                if root
                    and not seen[root]
                    and root.Parent
                    and not containsAny(root:GetFullName(), excludeWords) then

                    seen[root] = true

                    local position = getPosition(root)
                    if position then
                        local nameScore = keywordScore(root:GetFullName())
                        local hasPrompt, hasClick, hasTouch, promptText = getInteractionFlags(root)

                        local interactionScore = 0
                        if hasPrompt then interactionScore += 65 end
                        if hasClick then interactionScore += 45 end
                        if hasTouch then interactionScore += 25 end

                        if nameScore > 0 or interactionScore > 0 then
                            local motionScore, moved = getMotionScore(root, position, now)
                            local distance = (position - origin).Magnitude
                            local distancePenalty = math.min(50, distance / 70)

                            local score = nameScore + interactionScore + motionScore - distancePenalty

                            candidates[#candidates + 1] = {
                                Object = root,
                                Position = position,
                                Score = score,
                                Distance = distance,
                                Moved = moved,
                                HasPrompt = hasPrompt,
                                HasClick = hasClick,
                                HasTouch = hasTouch,
                                PromptText = promptText,
                            }
                        end
                    end
                end
            end
        end

        table.sort(candidates, function(a, b)
            return a.Score > b.Score
        end)

        return candidates
    end

    local function printProbe(snapshot, reason)
        local candidates = collectCandidates()

        print(
            "[SliceHub V2.1.1][OBJECTIVE-PROBE]",
            "reason=" .. tostring(reason),
            "objective=" .. tostring(snapshot ~= "" and snapshot or "none"),
            "candidateCount=" .. tostring(#candidates)
        )

        for index = 1, math.min(#candidates, Probe.MaxResults) do
            local c = candidates[index]

            print(
                "[SliceHub V2.1.1][OBJECTIVE-CANDIDATE]",
                "#" .. tostring(index),
                "score=" .. string.format("%.1f", c.Score),
                "dist=" .. string.format("%.1f", c.Distance),
                "moved=" .. string.format("%.1f", c.Moved),
                "prompt=" .. tostring(c.HasPrompt),
                "click=" .. tostring(c.HasClick),
                "touch=" .. tostring(c.HasTouch),
                "promptText=" .. tostring(c.PromptText),
                "path=" .. c.Object:GetFullName()
            )
        end
    end

    task.spawn(function()
        while true do
            task.wait(0.75)

            if not State or not State.FarmEnabled then
                continue
            end

            local snapshot = readObjectiveSnapshot()
            local lowerSnapshot = lower(snapshot)
            local relevant =
                string.find(lowerSnapshot, "escort", 1, true)
                or string.find(lowerSnapshot, "convoy", 1, true)
                or string.find(lowerSnapshot, "suppl", 1, true)
                or string.find(lowerSnapshot, "cart", 1, true)

            if not relevant then
                continue
            end

            local now = os.clock()
            local signatureChanged = snapshot ~= Probe.LastObjectiveSignature
            local intervalElapsed = now - Probe.LastFullScanAt >= Probe.PrintInterval

            if signatureChanged or intervalElapsed then
                Probe.LastObjectiveSignature = snapshot
                Probe.LastFullScanAt = now
                printProbe(snapshot, signatureChanged and "objective changed" or "periodic")
            end
        end
    end)
end)()

---------------------------------------------------------------------
-- COLOSSAL HITBOX EXPANDER (1000x1000x1000 STUD OVERRIDE)
---------------------------------------------------------------------

-- Colossal Hitbox was removed in V9.8.2.5. No background expander is started.

---------------------------------------------------------------------
-- TARGET ACQUISITION & SKY-LOCK NAVIGATION
---------------------------------------------------------------------

local function getTitanTargetPart(titan)
	local nape = titan:FindFirstChild("Nape", true)
	if nape and nape:IsA("BasePart") then return nape end
	local titanRoot = titan:FindFirstChild("HumanoidRootPart")
	if titanRoot and titanRoot:IsA("BasePart") then return titanRoot end
	return nil
end

local function isTitanAlive(titan)
	if not titan:IsA("Model") then return false end
	local titanHumanoid = titan:FindFirstChildOfClass("Humanoid")
	return titanHumanoid ~= nil and titanHumanoid.Health > 0
end

local function isTitanBlacklisted(titan)
	local expiry = targetBlacklistedUntil[titan]
	if not expiry then return false end
	if os.clock() >= expiry then
		targetBlacklistedUntil[titan] = nil
		return false
	end
	return true
end


---------------------------------------------------------------------
-- V4 RAID DIRECTOR
---------------------------------------------------------------------

V4RaidDirector = V4RaidDirector or {
    Enabled = false,
    RaidName = "Unknown",
    Phase = "Idle",
    CombatPaused = false,
    BossTitan = nil,
    BossPart = nil,
    RawBossTitan = nil,
    RawBossPart = nil,
    BossName = nil,
    BossVulnerable = false,
    ShieldActive = false,
    ObjectiveAnchors = {},
    ObjectiveAnchorsAt = 0,
    ObjectiveRadius = 260,
    Phase2Latched = false,
    LastRaidName = "Unknown",
    LastTransitionAt = 0,
    LastBossSeenAt = 0,
    LockedBossTitan = nil,
    LockedBossPart = nil,
    WeakPointText = "Waiting for boss",
    Status = "Waiting for raid",
}

function V4RaidDirector.Lower(value)
    return string.lower(tostring(value or ""))
end

function V4RaidDirector.Contains(text, token)
    return string.find(
        V4RaidDirector.Lower(text),
        V4RaidDirector.Lower(token),
        1,
        true
    ) ~= nil
end

function V4RaidDirector.NameLooksBoss(value)
    local name = V4RaidDirector.Lower(value)

    return
        string.find(name, "armored", 1, true) ~= nil
        or string.find(name, "female", 1, true) ~= nil
        or string.find(name, "colossal", 1, true) ~= nil
        or string.find(name, "attack", 1, true) ~= nil
        or string.find(name, "reiner", 1, true) ~= nil
        or string.find(name, "eren", 1, true) ~= nil
        or string.find(name, "annie", 1, true) ~= nil
        or string.find(name, "bertholdt", 1, true) ~= nil
        or string.find(name, "bertolt", 1, true) ~= nil
        or string.find(name, "boss", 1, true) ~= nil
end

function V4RaidDirector.IsBossTitan(titan)
    if not titan then return false end

    if V4RaidDirector.NameLooksBoss(titan.Name) then
        return true
    end

    local bossAttribute = nil
    local titanType = nil

    pcall(function()
        bossAttribute = titan:GetAttribute("Boss")
        titanType = titan:GetAttribute("Type")
            or titan:GetAttribute("TitanType")
            or titan:GetAttribute("Variant")
    end)

    if bossAttribute == true then
        return true
    end

    return V4RaidDirector.NameLooksBoss(titanType)
end

function V4RaidDirector.ResolveObjectiveBossReference()
    local names = {
        ["Armored Raid"] = "Armored_Boss",
        ["Attack Raid"] = "Attack_Boss",
        ["Female Raid"] = "Female_Boss",
        ["Colossal Raid"] = "Colossal_Boss",
    }

    local objectiveName = names[V4RaidDirector.RaidName]
    local objective = objectiveName and Workspace:FindFirstChild(objectiveName, true) or nil
    local titansFolder = Workspace:FindFirstChild(Config.TitansFolderName)
    if not objective or not titansFolder then return nil, nil end

    for _, object in ipairs(objective:GetDescendants()) do
        if object:IsA("ObjectValue") then
            local value = object.Value
            if value and value:IsDescendantOf(titansFolder) then
                local titan = value
                while titan and titan.Parent ~= titansFolder do titan = titan.Parent end
                if titan and titan.Parent == titansFolder and isTitanAlive(titan) then
                    local part = getTitanTargetPart(titan)
                    if part then return titan, part end
                end
            end
        end
    end

    return nil, nil
end

function V4RaidDirector.RaidIdentityScore(titan)
    if not titan then return -math.huge end

    local pieces = {tostring(titan.Name or "")}
    pcall(function()
        pieces[#pieces + 1] = tostring(titan:GetAttribute("Type") or "")
        pieces[#pieces + 1] = tostring(titan:GetAttribute("TitanType") or "")
        pieces[#pieces + 1] = tostring(titan:GetAttribute("Variant") or "")
        pieces[#pieces + 1] = tostring(titan:GetAttribute("BossName") or "")
        pieces[#pieces + 1] = tostring(titan:GetAttribute("Character") or "")
    end)
    local identity = V4RaidDirector.Lower(table.concat(pieces, " "))

    local tokens = {}
    if V4RaidDirector.RaidName == "Armored Raid" then
        tokens = {"reiner", "armored"}
    elseif V4RaidDirector.RaidName == "Attack Raid" then
        tokens = {"eren", "attack"}
    elseif V4RaidDirector.RaidName == "Female Raid" then
        tokens = {"annie", "female"}
    elseif V4RaidDirector.RaidName == "Colossal Raid" then
        tokens = {"bertholdt", "bertolt", "colossal"}
    end

    local score = 0
    for _, token in ipairs(tokens) do
        if string.find(identity, token, 1, true) then
            score += 100000
        end
    end

    pcall(function()
        if titan:GetAttribute("Boss") == true then score += 80000 end
        if titan:GetAttribute("Shifter") == true then score += 60000 end
    end)

    local scale = 1
    pcall(function() scale = tonumber(titan:GetScale()) or 1 end)
    score += math.max(0, scale - 1) * 550

    local humanoid = titan:FindFirstChildOfClass("Humanoid")
    if humanoid then
        score += math.log(math.max(1, tonumber(humanoid.MaxHealth) or 1)) * 35
    end

    return score
end

function V4RaidDirector.TitanIdentityText(titan)
    if not titan then return "" end
    local pieces = {tostring(titan.Name or "")}
    pcall(function()
        pieces[#pieces + 1] = tostring(titan:GetAttribute("Type") or "")
        pieces[#pieces + 1] = tostring(titan:GetAttribute("TitanType") or "")
        pieces[#pieces + 1] = tostring(titan:GetAttribute("Variant") or "")
        pieces[#pieces + 1] = tostring(titan:GetAttribute("BossName") or "")
        pieces[#pieces + 1] = tostring(titan:GetAttribute("Character") or "")
        pieces[#pieces + 1] = tostring(titan:GetAttribute("ShifterName") or "")
    end)
    return V4RaidDirector.Lower(table.concat(pieces, " "))
end

function V4RaidDirector.FindTitanByIdentityTokens(tokens)
    local titansFolder = Workspace:FindFirstChild(Config.TitansFolderName)
    if not titansFolder then return nil, nil end

    local bestTitan, bestPart, bestScore = nil, nil, -math.huge

    for _, titan in ipairs(titansFolder:GetChildren()) do
        if isTitanAlive(titan) then
            local part = getTitanTargetPart(titan)
            if part and part.Parent then
                local identity = V4RaidDirector.TitanIdentityText(titan)
                local score = 0
                local hits = 0

                for index, token in ipairs(tokens or {}) do
                    if string.find(identity, V4RaidDirector.Lower(token), 1, true) then
                        hits += 1
                        score += index == 1 and 240000 or 150000
                    end
                end

                if hits > 0 then
                    pcall(function()
                        if titan:GetAttribute("Boss") == true then score += 80000 end
                        if titan:GetAttribute("Shifter") == true then score += 60000 end
                    end)

                    local humanoid = titan:FindFirstChildOfClass("Humanoid")
                    if humanoid then
                        score += math.log(math.max(1, tonumber(humanoid.MaxHealth) or 1)) * 30
                    end

                    if score > bestScore then
                        bestTitan, bestPart, bestScore = titan, part, score
                    end
                end
            end
        end
    end

    return bestTitan, bestPart
end

function V4RaidDirector.FemaleObjectiveStage()
    local stage = V521FemaleDirector and V521FemaleDirector.ComputeStage
        and V521FemaleDirector.ComputeStage()
        or "ANNIE P1"

    if V521FemaleDirector then
        V521FemaleDirector.Stage = stage
    end

    return stage
end

function V4RaidDirector.FindFemaleBossTitan()
    local stage = V4RaidDirector.FemaleObjectiveStage()

    if V4RaidDirector.FemaleStage ~= stage then
        V4RaidDirector.FemaleStage = stage
        V4RaidDirector.LockedBossTitan = nil
        V4RaidDirector.LockedBossPart = nil
        if clearCurrentTarget then clearCurrentTarget(false) end
        cachedTitanCandidatesAt = 0
    end

    if stage == "DONE" then
        return nil, nil
    end

    local tokens = stage == "EREN P2"
        and {"eren", "attack"}
        or {"annie", "female"}

    if V4RaidDirector.LockedBossTitan
        and isTitanAlive(V4RaidDirector.LockedBossTitan) then
        local identity = V4RaidDirector.TitanIdentityText(V4RaidDirector.LockedBossTitan)
        local matches = false
        for _, token in ipairs(tokens) do
            if string.find(identity, token, 1, true) then
                matches = true
                break
            end
        end
        if matches then
            local part = getTitanTargetPart(V4RaidDirector.LockedBossTitan)
            if part then return V4RaidDirector.LockedBossTitan, part end
        end
    end

    local titan, part = V4RaidDirector.FindTitanByIdentityTokens(tokens)
    if titan and part then
        V4RaidDirector.LockedBossTitan = titan
        V4RaidDirector.LockedBossPart = part
        return titan, part
    end

    return nil, nil
end

function V4RaidDirector.FindBossTitan()
    local titansFolder = Workspace:FindFirstChild(Config.TitansFolderName)
    if not titansFolder then return nil, nil end

    if V4RaidDirector.RaidName == "Female Raid" then
        return V4RaidDirector.FindFemaleBossTitan()
    end

    if V4RaidDirector.LockedBossTitan
        and V4RaidDirector.LockedBossTitan.Parent == titansFolder
        and isTitanAlive(V4RaidDirector.LockedBossTitan) then
        local lockedPart = getTitanTargetPart(V4RaidDirector.LockedBossTitan)
        if lockedPart then
            V4RaidDirector.LockedBossPart = lockedPart
            return V4RaidDirector.LockedBossTitan, lockedPart
        end
    end

    local refTitan, refPart = V4RaidDirector.ResolveObjectiveBossReference()
    if refTitan and refPart then return refTitan, refPart end

    local alive = {}
    for _, titan in ipairs(titansFolder:GetChildren()) do
        if isTitanAlive(titan) then
            local part = getTitanTargetPart(titan)
            if part and part.Parent then
                if V4RaidDirector.IsBossTitan(titan) then
                    return titan, part
                end
                alive[#alive + 1] = {Titan = titan, Part = part}
            end
        end
    end

    local objectiveActive =
        Workspace:FindFirstChild("Armored_Boss", true)
        or Workspace:FindFirstChild("Female_Boss", true)
        or Workspace:FindFirstChild("Colossal_Boss", true)
        or Workspace:FindFirstChild("Attack_Boss", true)
    if not objectiveActive then return nil, nil end

    local best, second = nil, nil
    for _, entry in ipairs(alive) do
        entry.Score = V4RaidDirector.RaidIdentityScore(entry.Titan)
        if not best or entry.Score > best.Score then
            second = best
            best = entry
        elseif not second or entry.Score > second.Score then
            second = entry
        end
    end

    if not best then return nil, nil end

    -- Identity/attributes are authoritative. Scale/health is only accepted when one
    -- candidate is clearly separated from the rest; otherwise fail closed and wait.
    if best.Score >= 50000 then
        return best.Titan, best.Part
    end

    local gap = best.Score - (second and second.Score or 0)
    local bestScale, secondScale = 1, 1
    pcall(function() bestScale = tonumber(best.Titan:GetScale()) or 1 end)
    if second then pcall(function() secondScale = tonumber(second.Titan:GetScale()) or 1 end) end

    if V4RaidDirector.Phase2Latched
        and bestScale >= 3.25
        and (not second or bestScale - secondScale >= 0.85 or gap >= 900) then
        return best.Titan, best.Part
    end

    return nil, nil
end

function V4RaidDirector.FindArmoredShield()
    local armoredObjective = Workspace:FindFirstChild("Armored_Boss", true)

    if not armoredObjective then
        return false, nil
    end

    local health = armoredObjective:FindFirstChild("Health")

    if not health then
        return false, nil
    end

    local shield = nil

    pcall(function()
        shield = health:GetAttribute("Shield")
    end)

    return shield ~= nil, shield
end

function V4RaidDirector.VisibleObjectiveText(force)
    local now = os.clock()
    if not force
        and V4RaidDirector.VisibleObjectiveCache
        and now - (V4RaidDirector.VisibleObjectiveCacheAt or 0) < 0.20 then
        return V4RaidDirector.VisibleObjectiveCache
    end

    local parts = {}

    pcall(function()
        parts[#parts + 1] = tostring(Workspace:GetAttribute("Objective") or "")
        parts[#parts + 1] = tostring(Workspace:GetAttribute("Phase") or "")
        parts[#parts + 1] = tostring(Workspace:GetAttribute("RaidPhase") or "")
    end)

    pcall(function()
        for _, object in ipairs(playerGui:GetDescendants()) do
            if screenGui and object:IsDescendantOf(screenGui) then
                continue
            end

            if object:IsA("TextLabel")
                or object:IsA("TextButton")
                or object:IsA("TextBox") then

                local visible = object.Visible
                    and object.AbsoluteSize.X > 0
                    and object.AbsoluteSize.Y > 0

                if visible then
                    local raw = V4RaidDirector.Lower(object.Text)
                    if string.find(raw, "boat", 1, true)
                        or string.find(raw, "ship", 1, true)
                        or string.find(raw, "eren", 1, true)
                        or string.find(raw, "annie", 1, true)
                        or string.find(raw, "female titan", 1, true)
                        or string.find(raw, "execute skills", 1, true)
                        or string.find(raw, "boulder", 1, true)
                        or string.find(raw, "armored", 1, true)
                        or string.find(raw, "attack titan", 1, true)
                        or string.find(raw, "colossal", 1, true)
                        or string.find(raw, "cannon", 1, true)
                        or string.find(raw, "stall", 1, true)
                        or string.find(raw, "defend", 1, true)
                        or string.find(raw, "protect", 1, true)
                        or string.find(raw, "kill", 1, true)
                        or string.find(raw, "defeat", 1, true)
                        or string.find(raw, "slay", 1, true)
                        or string.find(raw, "wake", 1, true)
                        or string.find(raw, "vulnerable", 1, true) then
                        parts[#parts + 1] = raw
                    end
                end
            end
        end
    end)

    local result = V4RaidDirector.Lower(table.concat(parts, " | "))
    V4RaidDirector.VisibleObjectiveCache = result
    V4RaidDirector.VisibleObjectiveCacheAt = now
    return result
end

function V4RaidDirector.ObjectiveText()
    local parts = {}

    local visible = V4RaidDirector.VisibleObjectiveText()
    if visible ~= "" then
        parts[#parts + 1] = visible
    end

    pcall(function()
        if V3MissionIdentity and V3MissionIdentity.CombinedTasksLower then
            parts[#parts + 1] = tostring(V3MissionIdentity.CombinedTasksLower() or "")
        end
    end)

    pcall(function()
        parts[#parts + 1] = tostring(Workspace:GetAttribute("Raid") or "")
        parts[#parts + 1] = tostring(Workspace:GetAttribute("RaidName") or "")
    end)

    return V4RaidDirector.Lower(table.concat(parts, " | "))
end


function V4RaidDirector.ActiveRaidBoss(markerName)
    local titansFolder = Workspace:FindFirstChild(Config.TitansFolderName)
    if not titansFolder then return nil end

    -- Direct active boss model under the live Titans folder.
    local direct = titansFolder:FindFirstChild(markerName, true)
    if direct then
        local model = direct:IsA("Model") and direct or direct:FindFirstAncestorOfClass("Model")
        while model and model.Parent ~= titansFolder do model = model.Parent end
        if model and model.Parent == titansFolder and isTitanAlive(model) and getTitanTargetPart(model) then
            return model
        end
    end

    -- Some raids expose a workspace objective wrapper whose ObjectValue points at
    -- the real live boss. The wrapper by itself is never sufficient evidence.
    local marker = Workspace:FindFirstChild(markerName, true)
    if marker then
        for _, object in ipairs(marker:GetDescendants()) do
            if object:IsA("ObjectValue") and object.Value and object.Value:IsDescendantOf(titansFolder) then
                local model = object.Value
                while model and model.Parent ~= titansFolder do model = model.Parent end
                if model and model.Parent == titansFolder and isTitanAlive(model) and getTitanTargetPart(model) then
                    return model
                end
            end
        end
    end

    return nil
end

function V4RaidDirector.ClearlyNormalMission()
    local taskText = ""
    pcall(function()
        taskText = V4RaidDirector.Lower(
            (V3MissionIdentity and V3MissionIdentity.CombinedTasksLower and V3MissionIdentity.CombinedTasksLower() or "")
            .. " | " .. tostring(V4RaidDirector.VisibleObjectiveText() or "")
        )
    end)

    local generic = {
        "slay titans", "most kills", "escape grabs", "heal injuries",
        "avoid damage", "one shot titans", "blind titans", "no refills",
    }
    local raidSpecific = {
        "armored titan", "attack titan", "female titan", "colossal",
        "annie", "reiner", "bertholdt", "bertolt", "cannon",
        "defend eren", "wake eren", "boulder", "boat", "ship", "raid",
    }

    local sawGeneric = false
    for _, phrase in ipairs(generic) do
        if string.find(taskText, phrase, 1, true) then sawGeneric = true break end
    end
    if not sawGeneric then return false end

    for _, phrase in ipairs(raidSpecific) do
        if string.find(taskText, phrase, 1, true) then return false end
    end

    return true
end

function V4RaidDirector.DetectRaidName()
    -- V9.8.2.6: a clearly normal objective board wins over stale raid state.
    -- This must run before workspace Raid/RaidName attributes because AOT:R can
    -- leave those attributes behind after returning from an Attack Raid.
    if V4RaidDirector.ClearlyNormalMission() then return "Unknown" end

    -- Explicit raid attributes and live boss references are authoritative only
    -- after the normal-mission rejection above.
    local raidAttribute = V4RaidDirector.Lower(
        Workspace:GetAttribute("Raid")
        or Workspace:GetAttribute("RaidName")
        or ""
    )

    if raidAttribute ~= "" then
        if string.find(raidAttribute, "armored", 1, true) then return "Armored Raid" end
        if string.find(raidAttribute, "female", 1, true) then return "Female Raid" end
        if string.find(raidAttribute, "colossal", 1, true) then return "Colossal Raid" end
        if string.find(raidAttribute, "attack titan", 1, true)
            or string.find(raidAttribute, "attack raid", 1, true) then
            return "Attack Raid"
        end
    end

    if V4RaidDirector.ActiveRaidBoss("Armored_Boss") then return "Armored Raid" end
    if V4RaidDirector.ActiveRaidBoss("Female_Boss") then return "Female Raid" end
    if V4RaidDirector.ActiveRaidBoss("Colossal_Boss") then return "Colossal Raid" end
    if V4RaidDirector.ActiveRaidBoss("Attack_Boss") then return "Attack Raid" end

    local taskText = V4RaidDirector.ObjectiveText()
    local freshRaidChoice = ""
    local metadataAge = math.huge
    pcall(function()
        if not MissionObjectiveHistory.SelectedCreateMode then readLastMissionInfoForWebhook() end
        local updatedAt = tonumber(MissionObjectiveHistory.MetadataUpdatedAt) or 0
        metadataAge = updatedAt > 0 and math.max(0, os.time() - updatedAt) or math.huge
        if tostring(MissionObjectiveHistory.SelectedCreateMode or "") == "Raid" and metadataAge <= 300 then
            freshRaidChoice = tostring(MissionObjectiveHistory.SelectedRaidChoice or "")
        end
    end)

    -- P1 raid phases may not have spawned the boss yet. Require fresh Raid launch
    -- metadata plus matching live raid text; never trust the saved selection alone.
    if freshRaidChoice == "Shiganshina (Arm)"
        and (string.find(taskText, "boat", 1, true) or string.find(taskText, "ship", 1, true) or string.find(taskText, "armored", 1, true)) then
        return "Armored Raid"
    end
    if freshRaidChoice == "Trost (Att)"
        and (string.find(taskText, "defend eren", 1, true) or string.find(taskText, "boulder", 1, true) or string.find(taskText, "attack titan", 1, true)) then
        return "Attack Raid"
    end
    if freshRaidChoice == "Stohess (Female)"
        and (string.find(taskText, "annie", 1, true) or string.find(taskText, "female titan", 1, true)) then
        return "Female Raid"
    end
    if freshRaidChoice == "Shiganshina (Col)"
        and (string.find(taskText, "cannon", 1, true) or string.find(taskText, "colossal", 1, true)) then
        return "Colossal Raid"
    end

    return "Unknown"
end

