function V43RaidChestAuto.OpenRemote(kind)
    local assets =
        ReplicatedStorage:FindFirstChild("Assets")
    local remotes =
        assets and assets:FindFirstChild("Remotes")
    local getRemote =
        remotes and remotes:FindFirstChild("GET")

    if not getRemote
        or not getRemote:IsA("RemoteFunction") then
        return false, "GET RemoteFunction missing"
    end

    local ok, rewards, updatedData = pcall(
        function()
            return getRemote:InvokeServer(
                "S_Rewards",
                "Chest",
                kind
            )
        end
    )

    if not ok then
        return false, tostring(rewards)
    end

    local rewardCount =
        type(rewards) == "table"
        and #rewards
        or 0

    return rewardCount > 0, rewardCount
end

function V43RaidChestAuto.RaidDetected()
    return V4RaidDirector
        and (
            V4RaidDirector.Enabled == true
            or tostring(
                V4RaidDirector.LastRaidName
                or "Unknown"
            ) ~= "Unknown"
            or (
                V4RaidDirector.DetectRaidName
                and V4RaidDirector
                    .DetectRaidName()
                    ~= "Unknown"
            )
        )
end

task.spawn(function()
    while true do
        task.wait(0.45)

        local visible =
            V43RaidChestAuto.ScreenVisible()

        if not visible then
            V43RaidChestAuto.ScreenActive = false
            V43RaidChestAuto.Attempted = false
            V43RaidChestAuto.Busy = false
            V43RaidChestAuto.Status = "Idle"
            continue
        end

        V43RaidChestAuto.ScreenActive = true

        local openFree =
            State.RaidOpenFreeChestEnabled
            == true
        local openEmperor =
            State.RaidOpenEmperorChestEnabled
            == true

        if (not openFree and not openEmperor)
            or not V43RaidChestAuto
                .RaidDetected()
            or V43RaidChestAuto.Attempted then
            continue
        end

        V43RaidChestAuto.Attempted = true
        V43RaidChestAuto.Busy = true
        V43RaidChestAuto.LastAttemptAt =
            os.clock()

        -- Give reward/webhook capture a short head start before changing
        -- the chest page or finishing the result flow.
        task.wait(0.65)

        local premiumRemote =
            SliceHubMissionFastChestOpenAllowed()

        if openFree then
            V43RaidChestAuto.Status =
                premiumRemote
                and "Opening Free remotely"
                or "Opening Free through UI"

            if premiumRemote then
                V43RaidChestAuto.OpenRemote(
                    "Free"
                )
            else
                V43RaidChestAuto
                    .OpenFreeViaUi()
            end

            task.wait(
                premiumRemote and 0.18 or 0.55
            )
        end

        if openEmperor then
            V43RaidChestAuto.Status =
                premiumRemote
                and "Opening Emperor remotely"
                or "Opening Emperor through UI"

            if premiumRemote then
                V43RaidChestAuto.OpenRemote(
                    "Premium"
                )
            else
                V43RaidChestAuto
                    .OpenEmperorViaUi()
            end

            task.wait(
                premiumRemote and 0.22 or 0.55
            )
        end

        V43RaidChestAuto.Status =
            "Finishing chest screen"
        task.wait(0.50)

        local finished = false
        for _ = 1, 5 do
            finished = select(
                1,
                V43RaidChestAuto.ClickFinish()
            )
            if finished then
                break
            end
            task.wait(0.30)
        end

        V43RaidChestAuto.Status =
            finished
            and "Done"
            or "FINISH not found"
        V43RaidChestAuto.Busy = false
    end
end)

local findClosestTitans

V52KillingEngine = V52KillingEngine or {
    ClusterRadius = 95,
    LastSeed = nil,
    LastSeedDensity = 0,
    LastWaveSize = 0,
    LastHandoffAt = 0,
    Status = "Learning targets",
}

function V9825NormalizeTargetPriority(value)
    value = tostring(value or "Balanced")
    local allowed = {Balanced = true, Nearest = true, Objective = true, Boss = true, Abnormal = true}
    return allowed[value] and value or "Balanced"
end

function V9825TitanDescriptor(titan)
    if not titan then return "" end
    local values = {tostring(titan.Name or "")}
    for _, attribute in ipairs({"Type", "TitanType", "Variant", "Class", "Boss", "Abnormal", "Aberrant"}) do
        local ok, value = pcall(function() return titan:GetAttribute(attribute) end)
        if ok and value ~= nil then values[#values + 1] = tostring(value) end
    end
    return string.lower(table.concat(values, " "))
end

function V9825TitanLooksBoss(titan)
    if not titan then return false end
    if V4RaidDirector and V4RaidDirector.BossTitan == titan then return true end
    local text = V9825TitanDescriptor(titan)
    return string.find(text, "boss", 1, true) ~= nil
        or string.find(text, "colossal", 1, true) ~= nil
        or string.find(text, "armored", 1, true) ~= nil
        or string.find(text, "female", 1, true) ~= nil
        or string.find(text, "attack titan", 1, true) ~= nil
end

function V9825TitanLooksAbnormal(titan)
    local text = V9825TitanDescriptor(titan)
    return string.find(text, "abnormal", 1, true) ~= nil
        or string.find(text, "aberrant", 1, true) ~= nil
        or string.find(text, "crawler", 1, true) ~= nil
        or string.find(text, "jumper", 1, true) ~= nil
end

function V52KillingEngine.ComputeDensity(entries, entry)
    if not entry or not entry.Part then return 0 end
    local radius = tonumber(V52KillingEngine.ClusterRadius) or 95
    local radiusSquared = radius * radius
    local count = 0
    for _, other in ipairs(entries or {}) do
        if other.Part and other.Part.Parent then
            local delta = other.Part.Position - entry.Part.Position
            if delta:Dot(delta) <= radiusSquared then count += 1 end
        end
    end
    return count
end

function V52KillingEngine.ScoreEntry(entry, entries)
    if not entry or not entry.Titan or not entry.Part then return math.huge end

    local hardBoss = V4RaidDirector
        and V4RaidDirector.BossVulnerable == true
        and V4RaidDirector.BossTitan
        or nil
    if hardBoss then
        return entry.Titan == hardBoss and -1e15 or 1e15
    end

    local mode = V9825NormalizeTargetPriority(State and State.TargetPriority)
    local distanceSquared = tonumber(entry.DistanceSquared) or math.huge
    local score = distanceSquared

    if mode == "Balanced" or mode == "Objective" then
        score = getObjectiveTargetScore and getObjectiveTargetScore(entry) or distanceSquared
    elseif mode == "Boss" and V9825TitanLooksBoss(entry.Titan) then
        score -= 500000000000
    elseif mode == "Abnormal" and V9825TitanLooksAbnormal(entry.Titan) then
        score -= 500000000000
    end

    local density = V52KillingEngine.ComputeDensity(entries, entry)
    entry.ClusterDensity = density

    -- Balanced preserves the proven dense-pack route. Explicit priority modes
    -- follow the requested order directly instead of allowing cluster density
    -- to pull ordinary Titans ahead of the selected class.
    if mode == "Balanced" then
        score -= math.max(0, density - 1) * 2300
        score += math.sqrt(math.max(0, distanceSquared)) * 4
    end

    if V4RaidDirector and V4RaidDirector.BossPriorityScore then
        score += V4RaidDirector.BossPriorityScore(entry.Titan)
    end

    local failed = BladeBurstFailureCounts and BladeBurstFailureCounts[entry.Titan] or 0
    score += tonumber(failed or 0) * 9000

    entry.KillScore = score
    return score
end

function V52KillingEngine.BuildBladeWave(limit, current)
    limit = math.max(1, math.floor(tonumber(limit) or 1))
    local candidates = findClosestTitans(math.min(40, math.max(limit * 3, limit + 4)))
    if #candidates == 0 then return {} end

    local priorityMode = V9825NormalizeTargetPriority(State and State.TargetPriority)
    if priorityMode ~= "Balanced" then
        local direct, seen = {}, {}
        for _, entry in ipairs(candidates) do
            if #direct >= limit then break end
            if entry.Titan and not seen[entry.Titan] and isTitanAlive(entry.Titan) then
                seen[entry.Titan] = true
                direct[#direct + 1] = entry.Titan
            end
        end
        V52KillingEngine.LastSeed = direct[1]
        V52KillingEngine.LastSeedDensity = 0
        V52KillingEngine.LastWaveSize = #direct
        V52KillingEngine.Status = priorityMode .. " priority • wave " .. tostring(#direct)
        return direct
    end

    local seed = nil
    if current and isTitanAlive(current) then
        for _, entry in ipairs(candidates) do
            if entry.Titan == current then seed = entry break end
        end
    end
    seed = seed or candidates[1]
    if not seed or not seed.Part then return {} end

    local radius = tonumber(V52KillingEngine.ClusterRadius) or 95
    local radiusSquared = radius * radius
    local near, far = {}, {}

    for _, entry in ipairs(candidates) do
        local delta = entry.Part.Position - seed.Part.Position
        if delta:Dot(delta) <= radiusSquared then
            near[#near + 1] = entry
        else
            far[#far + 1] = entry
        end
    end

    table.sort(near, function(a, b)
        local da = (a.Part.Position - seed.Part.Position).Magnitude
        local db = (b.Part.Position - seed.Part.Position).Magnitude
        if da == db then return (a.KillScore or 0) < (b.KillScore or 0) end
        return da < db
    end)

    local result, seen = {}, {}
    for _, bucket in ipairs({near, far}) do
        for _, entry in ipairs(bucket) do
            if #result >= limit then break end
            if entry.Titan and not seen[entry.Titan] and isTitanAlive(entry.Titan) then
                seen[entry.Titan] = true
                result[#result + 1] = entry.Titan
            end
        end
        if #result >= limit then break end
    end

    V52KillingEngine.LastSeed = seed.Titan
    V52KillingEngine.LastSeedDensity = tonumber(seed.ClusterDensity) or #near
    V52KillingEngine.LastWaveSize = #result
    V52KillingEngine.Status = "Seed density " .. tostring(V52KillingEngine.LastSeedDensity)
        .. " | wave " .. tostring(#result)

    return result
end

local function rebuildTitanCandidateCache()
	cachedTitanCandidates = {}
	cachedTitanCandidatesAt = os.clock()

	if not rootPart then return end
	local titansFolder = Workspace:FindFirstChild(Config.TitansFolderName)
	if not titansFolder then return end

	local origin = rootPart.Position
	local maximumDistanceSquared = Config.AttackRange * Config.AttackRange
	local hardBoss = nil

	if V4RaidDirector and V4RaidDirector.HardBossLock then
		hardBoss = select(1, V4RaidDirector.HardBossLock())
	end

	for _, instance in ipairs(titansFolder:GetChildren()) do
		if hardBoss and instance ~= hardBoss then continue end
        if V4RaidDirector
            and V4RaidDirector.AllowTitanTarget
            and not V4RaidDirector.AllowTitanTarget(instance) then
            continue
        end
		if not isTitanAlive(instance) then continue end
		local targetPart = getTitanTargetPart(instance)
		if not targetPart then continue end

		local difference = targetPart.Position - origin
		local distanceSquared = difference:Dot(difference)
		if distanceSquared <= maximumDistanceSquared then
			table.insert(cachedTitanCandidates, {
				Titan = instance,
				Part = targetPart,
				DistanceSquared = distanceSquared,
			})
		end
	end

    for _, entry in ipairs(cachedTitanCandidates) do
        V52KillingEngine.ScoreEntry(entry, cachedTitanCandidates)
    end

	table.sort(cachedTitanCandidates, function(a, b)
        local scoreA = tonumber(a.KillScore) or math.huge
        local scoreB = tonumber(b.KillScore) or math.huge
        if scoreA == scoreB then
            return (tonumber(a.DistanceSquared) or math.huge) < (tonumber(b.DistanceSquared) or math.huge)
        end
		return scoreA < scoreB
	end)
end

findClosestTitans = function(limit)
	if not rootPart then return {} end
	limit = math.clamp(math.floor(tonumber(limit) or 1), 1, 40)

	if os.clock() - cachedTitanCandidatesAt >= Config.TargetCacheLifetime then
		rebuildTitanCandidateCache()
	end

	local selected = {}
	for _, entry in ipairs(cachedTitanCandidates) do
		if #selected >= limit then break end
		if entry.Part and entry.Part.Parent and not isTitanBlacklisted(entry.Titan) and isTitanAlive(entry.Titan) then
			table.insert(selected, entry)
		end
	end
	return selected
end

local function findClosestTitan()
	local selected = findClosestTitans(1)
	local entry = selected[1]
	if not entry then return nil, nil end
	return entry.Titan, entry.Part
end

local function getCachedAliveTitanCount()
    if os.clock() - cachedTitanCandidatesAt >= Config.TargetCacheLifetime then
        rebuildTitanCandidateCache()
    end

    local count = 0
    for _, entry in ipairs(cachedTitanCandidates) do
        if entry
            and entry.Titan
            and entry.Part
            and entry.Part.Parent
            and isTitanAlive(entry.Titan) then

            count += 1
        end
    end

    return count
end

local function findClosestAliveTitanIgnoringBlacklist()
    local titansFolder = Workspace:FindFirstChild(Config.TitansFolderName)
    if not titansFolder or not rootPart then return nil, nil end

    local bestTitan, bestPart = nil, nil
    local bestDistanceSquared = math.huge

    for _, titan in ipairs(titansFolder:GetChildren()) do
        if isTitanAlive(titan)
            and (
                not V4RaidDirector
                or not V4RaidDirector.AllowTitanTarget
                or V4RaidDirector.AllowTitanTarget(titan)
            ) then
            local part = getTitanTargetPart(titan)
            if part and part.Parent then
                local delta = part.Position - rootPart.Position
                local distanceSquared = delta:Dot(delta)
                if distanceSquared < bestDistanceSquared then
                    bestDistanceSquared = distanceSquared
                    bestTitan = titan
                    bestPart = part
                end
            end
        end
    end

    return bestTitan, bestPart
end

function getBestTitanCluster(radius, scanLimit)
	local entries = findClosestTitans(math.clamp(math.floor(tonumber(scanLimit) or 20), 1, 40))
	if #entries == 0 then return nil, nil, 0 end

	radius = math.max(1, tonumber(radius) or 280)
	local radiusSquared = radius * radius
	local bestCenter, bestPart, bestCount, bestDistance = nil, nil, 0, math.huge

	for _, a in ipairs(entries) do
		local part = a and a.Part
		if part and part.Parent then
			local sum = Vector3.zero
			local members = {}
			for _, b in ipairs(entries) do
				local other = b and b.Part
				if other and other.Parent then
					local delta = other.Position - part.Position
					if delta:Dot(delta) <= radiusSquared then
						sum += other.Position
						table.insert(members, other)
					end
				end
			end

			local count = #members
			if count > 0 then
				local center = sum / count
				local centerPart, centerDistance = nil, math.huge
				for _, member in ipairs(members) do
					local d = member.Position - center
					local ds = d:Dot(d)
					if ds < centerDistance then
						centerPart, centerDistance = member, ds
					end
				end

				local distance = tonumber(a.DistanceSquared) or math.huge
				if count > bestCount or (count == bestCount and distance < bestDistance) then
					bestCenter, bestPart, bestCount, bestDistance = center, centerPart or part, count, distance
				end
			end
		end
	end

	return bestCenter, bestPart, bestCount
end

local function chooseRipperAimPart()
    if player and player:GetAttribute("Weapon") == "Spears"
        and V35Spears
        and V35Spears.GetBestCluster then

        local center, bestPart, bestCount = V35Spears.GetBestCluster()

        if center then
            return bestPart, tonumber(bestCount) or 0, center
        end
    end

	if not Config.RipperClusterEnabled then
		return currentTargetPart, 1, currentTargetPart and currentTargetPart.Position or nil
	end

	local center, bestPart, bestCount = getBestTitanCluster(Config.RipperClusterRadius, Config.RipperClusterScanLimit)
	if center and bestPart and bestCount >= math.max(1, tonumber(Config.RipperClusterMinTargets) or 5) then
		return bestPart, bestCount, center
	end

	local fallbackPart = currentTargetPart or bestPart
	return fallbackPart, bestCount, fallbackPart and fallbackPart.Position or center
end

local function getRipperOpportunity()
    if V4RaidDirector
        and V4RaidDirector.ShouldPauseCombat
        and V4RaidDirector.ShouldPauseCombat() then
        return false, 0, getCachedAliveTitanCount()
    end

    local aliveCount = getCachedAliveTitanCount()

    if player
        and player:GetAttribute("Weapon") == "Spears"
        and V35Spears
        and V35Spears.GetBestCluster then

        if aliveCount <= 1 then
            return false, 0, aliveCount
        end

        local _, _, spearPackCount = V35Spears.GetBestCluster()
        spearPackCount = tonumber(spearPackCount) or 0

        return
            spearPackCount >= math.max(1, tonumber(Config.TitanBlasterMinPack) or 2),
            spearPackCount,
            aliveCount
    end

    if aliveCount <= math.max(1, tonumber(Config.RipperNeverCastAtOrBelowAlive) or 5) then
        return false, 0, aliveCount
    end

    local _, _, packCount = getBestTitanCluster(
        Config.RipperClusterRadius,
        Config.RipperClusterScanLimit
    )

    packCount = tonumber(packCount) or 0
    local now = os.clock()
    local immediateMin = math.max(1, tonumber(Config.RipperImmediateClusterMin) or 12)
    local delayedMin = math.max(1, tonumber(Config.RipperDelayedClusterMin) or 8)

    if packCount >= immediateMin then
        RipperOpportunityReadySince = nil
        return true, packCount, aliveCount
    end

    if packCount >= delayedMin then
        RipperOpportunityReadySince = RipperOpportunityReadySince or now
        if now - RipperOpportunityReadySince >= (tonumber(Config.RipperOpportunityWait) or 1.0) then
            RipperOpportunityReadySince = nil
            return true, packCount, aliveCount
        end
        return false, packCount, aliveCount
    end

    RipperOpportunityReadySince = nil
    return false, packCount, aliveCount
end

local function getEffectiveTitansPerHit()
	return SliceHubMissionClampTPS(Config.TitansPerHit, SliceHubMissionTPSMax())
end


---------------------------------------------------------------------
-- V3.5 THUNDER SPEAR ENGINE
-- Validated protocol:
--   GET : InvokeServer("Spears", "S_Fire", spearName)
--   POST: FireServer("Spears", "S_Explode", Vector3 position)
-- Server S_Fire spends ammo and sets Current_Spear.
-- Server S_Explode applies blast damage and clears Current_Spear.
---------------------------------------------------------------------


---------------------------------------------------------------------
-- V9 RAID COMBAT MATRIX
-- Observable-behavior reconstruction from clean raid traces:
--   NORMAL PACKS  : unique exact weak points, max 10 per visible attack bank
--   RAID BOSSES   : same live weak point repeated x5 per visible attack
--   SPEAR PACKS   : one accepted S_Fire fans into up to 10 exact positions
--   SPEAR BOSSES  : same live weak point repeated x5, optional leftover-add fill
--
-- This is an independently implemented behavior profile. It keeps the existing
-- raid phase detector authoritative and only changes per-phase combat delivery.
---------------------------------------------------------------------

V941ObjectiveGuardian = {
    ActiveRoute = false,
    LastRouteKey = "",
    Anchors = {},
    AnchorsAt = 0,
    AnchorRaid = "",
    ThreatCount = 0,
    CriticalThreatCount = 0,
    LastThreatScanAt = 0,
    Status = "STANDBY",
}

function V941ObjectiveGuardian.ColossalMountedActive()
    if Config.V941ObjectiveGuardianEnabled ~= true then return false end
    if not V4RaidDirector
        or V4RaidDirector.RaidName ~= "Colossal Raid"
        or not V55ColossalDirector
        or V55ColossalDirector.Stage ~= "P1 CANNON STALL" then
        return false
    end

    -- V9.4.3: Blade-only P1 defense intentionally dismounts the cannon. Keep the
    -- Guardian route authoritative during that defense window so exact Blade banks
    -- continue targeting Eren-zone threats until the wave is actually clear.
    if V55ColossalDirector.DefenseMode == true then return true end
    if V55ColossalDirector.Entered ~= true then return false end

    local threats = tonumber(V55ColossalDirector.ThreatCount) or 0
    pcall(function()
        threats = tonumber(V55ColossalDirector.CountObjectiveThreats(false)) or threats
    end)
    local damaged = os.clock() < (tonumber(V55ColossalDirector.ErenDamagedPulseUntil) or 0)
    return threats > 0 or damaged
end

function V941ObjectiveGuardian.RouteActive()
    if Config.V941ObjectiveGuardianEnabled ~= true
        or not V4RaidDirector
        or V4RaidDirector.Enabled ~= true then
        if V941ObjectiveGuardian.ActiveRoute == true then
            V941ObjectiveGuardian.ActiveRoute = false
            V941ObjectiveGuardian.LastRouteKey = "DISABLED"
            V941ObjectiveGuardian.Status = "STANDBY"
            V941ObjectiveGuardian.Anchors = {}
            V941ObjectiveGuardian.AnchorsAt = 0
            if V6ExactBlade then V6ExactBlade.Targets = {} end
            if clearCurrentTarget then clearCurrentTarget(false) end
            cachedTitanCandidatesAt = 0
        end
        return false
    end

    local raid = tostring(V4RaidDirector.RaidName or "Unknown")
    local phase = tostring(V4RaidDirector.Phase or "Idle")
    local active = false

    if raid == "Colossal Raid" then
        active = V941ObjectiveGuardian.ColossalMountedActive()
    elseif phase == "P1 Objective"
        and (raid == "Armored Raid" or raid == "Attack Raid") then
        active = true
    end

    local routeKey = raid .. "|" .. phase .. "|" .. tostring(active)
    if routeKey ~= V941ObjectiveGuardian.LastRouteKey then
        V941ObjectiveGuardian.LastRouteKey = routeKey
        V941ObjectiveGuardian.ActiveRoute = active
        V941ObjectiveGuardian.AnchorsAt = 0
        V941ObjectiveGuardian.Anchors = {}
        if V4RaidDirector then V4RaidDirector.ObjectiveAnchorsAt = 0 end
        if V6ExactBlade then V6ExactBlade.Targets = {} end
        if clearCurrentTarget then clearCurrentTarget(false) end
        cachedTitanCandidatesAt = 0
        V94RunRecorder.Record("OBJECTIVE_GUARD_ROUTE", routeKey)
    end

    return active
end

function V941ObjectiveGuardian.DefenseRadius()
    local raid = V4RaidDirector and tostring(V4RaidDirector.RaidName or "") or ""
    if raid == "Armored Raid" then
        return math.max(180, tonumber(Config.V941ArmoredDefenseRadius) or 360)
    end
    if raid == "Attack Raid" then
        return math.max(180, tonumber(Config.V941AttackDefenseRadius) or 340)
    end
    return math.max(180, tonumber(Config.V941ColossalP1DefenseRadius) or 360)
end

function V941ObjectiveGuardian.ResolveAnchors(force)
    local now = os.clock()
    local raid = V4RaidDirector and tostring(V4RaidDirector.RaidName or "Unknown") or "Unknown"
    if not force
        and raid == V941ObjectiveGuardian.AnchorRaid
        and now - (tonumber(V941ObjectiveGuardian.AnchorsAt) or 0)
            < math.max(0.35, tonumber(Config.V941AnchorRefreshSeconds) or 0.65) then
        return V941ObjectiveGuardian.Anchors
    end

    local anchors = {}
    local function addPosition(position)
        if typeof(position) ~= "Vector3" then return end
        for _, existing in ipairs(anchors) do
            if (existing - position).Magnitude <= 8 then return end
        end
        anchors[#anchors + 1] = position
    end

    if raid == "Colossal Raid"
        and V55ColossalDirector
        and V55ColossalDirector.ResolveErenAnchor then
        local ok, position = pcall(V55ColossalDirector.ResolveErenAnchor, force == true)
        if ok then addPosition(position) end
    end

    if V4RaidDirector and V4RaidDirector.RefreshObjectiveAnchors then
        local ok, values = pcall(V4RaidDirector.RefreshObjectiveAnchors, force == true)
        if ok and type(values) == "table" then
            for _, position in ipairs(values) do addPosition(position) end
        end
    end

    -- Exact reference fallback: only used when name-based boat/Eren anchors failed.
    if #anchors == 0 then
        local titansFolder = Workspace:FindFirstChild(Config.TitansFolderName)
        local keywords = raid == "Armored Raid"
            and {"boat", "ship", "vessel", "defend", "protect"}
            or {"eren", "boulder", "defend", "protect"}
        local checked = 0

        for _, object in ipairs(Workspace:GetDescendants()) do
            checked += 1
            if checked > 20000 then break end

            if object:IsA("ObjectValue") and object.Value
                and object.Value:IsDescendantOf(Workspace)
                and not (titansFolder and object.Value:IsDescendantOf(titansFolder)) then

                local context = string.lower(
                    tostring(object.Name or "") .. " "
                    .. tostring(object.Parent and object.Parent.Name or "") .. " "
                    .. tostring(object.Value.Name or "")
                )
                local matched = false
                for _, keyword in ipairs(keywords) do
                    if string.find(context, keyword, 1, true) then
                        matched = true
                        break
                    end
                end

                if matched then
                    addPosition(V4RaidDirector.GetObjectPosition(object.Value))
                end
            end
        end
    end

    V941ObjectiveGuardian.Anchors = anchors
    V941ObjectiveGuardian.AnchorsAt = now
    V941ObjectiveGuardian.AnchorRaid = raid
    return anchors
end

function V941ObjectiveGuardian.ThreatEntries(limit)
    limit = math.max(1, math.floor(tonumber(limit) or 20))
    local folder = Workspace:FindFirstChild(Config.TitansFolderName)
    if not folder then return {} end

    local anchors = V941ObjectiveGuardian.ResolveAnchors(false)
    local radius = V941ObjectiveGuardian.DefenseRadius()
    local radiusSquared = radius * radius
    local criticalRadius = math.max(80, tonumber(Config.V941ObjectiveCriticalRadius) or 175)
    local criticalSquared = criticalRadius * criticalRadius
    local candidates = {}
    local critical = 0

    for _, titan in ipairs(folder:GetChildren()) do
        if isTitanAlive(titan)
            and not (V4RaidDirector.IsBossTitan and V4RaidDirector.IsBossTitan(titan)) then
            local part = V9RaidCombat and V9RaidCombat.ExactNape
                and (V9RaidCombat.ExactNape(titan) or getTitanTargetPart(titan))
                or getTitanTargetPart(titan)
            if part and part.Parent then
                local bestDistanceSquared = math.huge
                for _, anchor in ipairs(anchors) do
                    local delta = part.Position - anchor
                    bestDistanceSquared = math.min(bestDistanceSquared, delta:Dot(delta))
                end

                local allowed = #anchors > 0 and bestDistanceSquared <= radiusSquared
                    or (#anchors == 0 and (
                        not V4RaidDirector.AllowTitanTarget
                        or V4RaidDirector.AllowTitanTarget(titan)
                    ))

                if allowed then
                    if #anchors == 0 and rootPart then
                        local delta = part.Position - rootPart.Position
                        bestDistanceSquared = delta:Dot(delta)
                    end
                    local isCritical = bestDistanceSquared <= criticalSquared
                    if isCritical then critical += 1 end
                    candidates[#candidates + 1] = {
                        Titan = titan,
                        Part = part,
                        DistanceSquared = bestDistanceSquared,
                        Critical = isCritical,
                    }
                end
            end
        end
    end

    table.sort(candidates, function(a, b)
        if a.Critical ~= b.Critical then return a.Critical == true end
        return (tonumber(a.DistanceSquared) or math.huge)
            < (tonumber(b.DistanceSquared) or math.huge)
    end)

    local output = {}
    for index = 1, math.min(limit, #candidates) do output[index] = candidates[index] end

    V941ObjectiveGuardian.ThreatCount = #candidates
    V941ObjectiveGuardian.CriticalThreatCount = critical
    V941ObjectiveGuardian.LastThreatScanAt = os.clock()
    V941ObjectiveGuardian.Status = string.format(
        "%s • anchors %d • threats %d • critical %d",
        tostring(V4RaidDirector.RaidName or "OBJECTIVE GUARD"),
        #anchors,
        #candidates,
        critical
    )
    return output
end

V9RaidCombat = V9RaidCombat or {
    Version = "9.4.4",
    BladeMode = "BOOT",
    SpearMode = "BOOT",
    LastBladeRegisters = 0,
    LastBladeSlashes = 0,
    LastSpearExplodes = 0,
    LastColossalThreatFill = 0,
    LastColossalCriticalFill = 0,
    BossBladeCycles = 0,
    BossSpearShots = 0,
    PackBladeCycles = 0,
    PackSpearShots = 0,
}

function V9RaidCombat.Context()
    local raid = V4RaidDirector and tostring(V4RaidDirector.RaidName or "Unknown") or "Unknown"
    local phase = V4RaidDirector and tostring(V4RaidDirector.Phase or "Idle") or "Idle"
    local stage = V4RaidDirector and tostring(
        V4RaidDirector.FemaleStage
        or (V521FemaleDirector and V521FemaleDirector.Stage)
        or "WAITING"
    ) or "WAITING"
    return raid, phase, stage
end

function V9RaidCombat.ExactNape(titan)
    if not titan or not titan.Parent then return nil end
    local hitboxes = titan:FindFirstChild("Hitboxes")
    local hit = hitboxes and hitboxes:FindFirstChild("Hit")
    local nape = hit and hit:FindFirstChild("Nape")
    if nape and nape:IsA("BasePart") and nape.Parent then return nape end
    return nil
end

function V9RaidCombat.LiveBoss()
    if not V4RaidDirector or V4RaidDirector.Enabled ~= true then return nil, nil end
    if V4RaidDirector.HardBossLock then
        local ok, titan, part = pcall(V4RaidDirector.HardBossLock)
        if ok and titan and part and part.Parent and isTitanAlive(titan) then
            return titan, V9RaidCombat.ExactNape(titan) or part
        end
    end
    local titan = V4RaidDirector.BossTitan
    local part = titan and (V9RaidCombat.ExactNape(titan) or V4RaidDirector.BossPart)
    if titan and part and part.Parent and isTitanAlive(titan) then return titan, part end
    return nil, nil
end

function V9RaidCombat.RawP1Boss()
    if not V4RaidDirector then return nil, nil end
    local titan = V4RaidDirector.RawBossTitan
    local part = titan and (V9RaidCombat.ExactNape(titan) or V4RaidDirector.RawBossPart)
    if titan and part and part.Parent and isTitanAlive(titan) then return titan, part end
    return nil, nil
end

function V9RaidCombat.ColossalGuardianActive()
    return V4RaidDirector
        and V4RaidDirector.RaidName == "Colossal Raid"
        and V55ColossalDirector
        and V55ColossalDirector.Stage == "P2 BOSS"
        and V55ColossalDirector.DefenseMode == true
end

function V9RaidCombat.BossAddFillAllowed()
    local raid = V9RaidCombat.Context()
    if raid == "Female Raid" then return false end

    -- V9.4.2: Colossal P2 must never mix boss pressure with add cleanup.
    -- Outside Guardian the route is boss-only; inside Guardian the dedicated
    -- ColossalGuardianActive branch already builds an add-only defense plan.
    if raid == "Colossal Raid" then return false end

    if V9RaidCombat.ColossalGuardianActive() then return false end
    if V941ObjectiveGuardian and V941ObjectiveGuardian.RouteActive
        and V941ObjectiveGuardian.RouteActive() then return false end
    return raid == "Attack Raid" or raid == "Armored Raid"
end

function V9RaidCombat.OrdinaryTitans(limit, allowBossPhaseAdds)
    local output = {}
    local folder = Workspace:FindFirstChild(Config.TitansFolderName)
    if not folder then return output end

    for _, titan in ipairs(folder:GetChildren()) do
        if #output >= math.max(1, tonumber(limit) or 10) then break end
        if isTitanAlive(titan) and not (V4RaidDirector and V4RaidDirector.IsBossTitan and V4RaidDirector.IsBossTitan(titan)) then
            local allowed = true
            if V4RaidDirector and V4RaidDirector.Enabled == true and not allowBossPhaseAdds then
                allowed = not V4RaidDirector.AllowTitanTarget
                    or V4RaidDirector.AllowTitanTarget(titan)
            end
            local part = allowed and (V9RaidCombat.ExactNape(titan) or getTitanTargetPart(titan)) or nil
            if part and part.Parent then
                output[#output + 1] = {Titan = titan, Part = part}
            end
        end
    end

    return output
end

function V9RaidCombat.ColossalP2ThreatEntries(limit)
    local output = {}
    limit = math.max(0, math.floor(tonumber(limit) or 0))
    if limit <= 0
        or Config.V943ColossalSplitRouteEnabled ~= true
        or not V4RaidDirector
        or V4RaidDirector.RaidName ~= "Colossal Raid"
        or not V55ColossalDirector
        or V55ColossalDirector.Stage ~= "P2 BOSS" then
        V9RaidCombat.LastColossalThreatFill = 0
        V9RaidCombat.LastColossalCriticalFill = 0
        return output
    end

    local anchor = V55ColossalDirector.ResolveErenAnchor
        and V55ColossalDirector.ResolveErenAnchor(false)
        or nil
    local folder = Workspace:FindFirstChild(Config.TitansFolderName)
    if typeof(anchor) ~= "Vector3" or not folder then
        V9RaidCombat.LastColossalThreatFill = 0
        V9RaidCombat.LastColossalCriticalFill = 0
        return output
    end

    local radius = math.max(120, tonumber(Config.V943ColossalThreatRadius) or 300)
    local criticalRadius = math.max(60, tonumber(Config.V943ColossalCriticalRadius) or 175)
    local radiusSquared = radius * radius
    local criticalSquared = criticalRadius * criticalRadius
    local candidates = {}

    for _, titan in ipairs(folder:GetChildren()) do
        if isTitanAlive(titan)
            and not (V4RaidDirector.IsBossTitan and V4RaidDirector.IsBossTitan(titan)) then
            local part = V9RaidCombat.ExactNape(titan) or getTitanTargetPart(titan)
            if part and part.Parent then
                local delta = part.Position - anchor
                local distanceSquared = delta:Dot(delta)
                if distanceSquared <= radiusSquared then
                    candidates[#candidates + 1] = {
                        Titan = titan,
                        Part = part,
                        DistanceSquared = distanceSquared,
                        Critical = distanceSquared <= criticalSquared,
                    }
                end
            end
        end
    end

    table.sort(candidates, function(a, b)
        if a.Critical ~= b.Critical then return a.Critical == true end
        return (tonumber(a.DistanceSquared) or math.huge)
            < (tonumber(b.DistanceSquared) or math.huge)
    end)

    local critical = 0
    for index = 1, math.min(limit, #candidates) do
        local entry = candidates[index]
        output[#output + 1] = entry
        if entry.Critical == true then critical += 1 end
    end

    V9RaidCombat.LastColossalThreatFill = #output
    V9RaidCombat.LastColossalCriticalFill = critical
    return output
end

function V9RaidCombat.ColossalP2ThreatFillLimit()
    if not V55ColossalDirector or V55ColossalDirector.Stage ~= "P2 BOSS" then return 0 end
    if V55ColossalDirector.DefenseMode == true then
        if SliceHubIsPremium() then
            local hp =
                tonumber(
                    V55ColossalDirector
                        .ErenHealthPercent
                ) or 100

            if hp <= 20 then return 10 end
            if hp <= 40 then return 9 end
            if hp <= 70 then return 8 end
            return 7
        end

        return math.max(0, math.floor(tonumber(Config.V943ColossalGuardianThreatFill) or 5))
    end
    return math.max(0, math.floor(tonumber(Config.V943ColossalNormalThreatFill) or 2))
end

function V9RaidCombat.BuildBladePlan(queueTargets)
    local raid, phase, stage = V9RaidCombat.Context()
    local plan = {}
    local seen = {}

    local function add(titan, repeats)
        if not titan or seen[titan] or not isTitanAlive(titan) then return end
        if not V9RaidCombat.ExactNape(titan) then return end
        seen[titan] = true
        plan[#plan + 1] = {
            Titan = titan,
            Repeats = math.max(1, math.floor(tonumber(repeats) or 1)),
        }
    end

    if Config.V9RaidCombatEnabled ~= true
        or not V4RaidDirector
        or V4RaidDirector.Enabled ~= true then
        local maximum = math.min(
            getEffectiveTitansPerHit(),
            math.max(1, math.floor(tonumber(Config.V9BladeQueueMaxTargets) or SliceHubMissionTPSMax()))
        )
        for _, titan in ipairs(queueTargets or {}) do
            add(titan, 1)
            if #plan >= maximum then break end
        end
        return plan, "DUAL PACK BANK"
    end

    -- V9.4.1: protected objectives own Blades before every P1 boss/cannon route.
    -- Targets come from a fresh anchor-distance scan, not a stale combat queue.
    if V941ObjectiveGuardian
        and V941ObjectiveGuardian.RouteActive
        and V941ObjectiveGuardian.RouteActive() then
        local maximum = math.min(
            getEffectiveTitansPerHit(),
            math.max(
                1,
                math.floor(tonumber(Config.V941ObjectiveGuardianMaxTargets) or SliceHubMissionTPSMax())
            )
        )

        -- V9.4.4 Colossal P1 Blade Guardian consumes an explicit bank budget.
        -- One normal bank means at most 10 targets; heavy danger permits two.
        if raid == "Colossal Raid"
            and V55ColossalDirector
            and V55ColossalDirector.BladeGuardianAirborne == true then
            local bankSize = math.max(1, math.floor(tonumber(Config.V9BladeBankSize) or 10))
            local bankBudget = math.max(1, math.floor(tonumber(V55ColossalDirector.BladeGuardianBankBudget) or 1))
            maximum = math.min(maximum, bankSize * bankBudget)
        end

        for _, entry in ipairs(V941ObjectiveGuardian.ThreatEntries(maximum)) do
            add(entry.Titan, 1)
        end

        -- V9.4.2: live objective threats remain first, but Armored/Attack P1
        -- no longer devolves into one-Titan-at-a-time cleanup when only one add
        -- has crossed the defense radius. Fill the remaining exact Blade bank
        -- with ordinary non-boss Titans so the proven 10 + 10 bank throughput
        -- stays active while boats/Eren remain protected.
        if #plan < maximum
            and (raid == "Armored Raid" or raid == "Attack Raid") then
            for _, entry in ipairs(V9RaidCombat.OrdinaryTitans(maximum, true)) do
                add(entry.Titan, 1)
                if #plan >= maximum then break end
            end
        end

        return plan, raid .. " • OBJECTIVE GUARDIAN"
    end

    -- Female raid traces are pure staged boss pressure: ANNIE -> EREN -> ANNIE.
    if raid == "Female Raid" then
        local boss = V9RaidCombat.LiveBoss()
        if boss then add(boss, tonumber(Config.V9BossBladeRegistersPerSlash) or 5) end
        return plan, "FEMALE " .. stage .. " • BOSS x5"
    end

    if phase == "Boss" or phase == "Boss Shield" then
        -- V9.4.3: Colossal P2 never abandons boss pressure. One Blade cycle keeps
        -- boss x5 and appends only the nearest Eren-zone threats in the same Slash.
        if raid == "Colossal Raid" and Config.V943ColossalSplitRouteEnabled == true then
            local boss = V9RaidCombat.LiveBoss()
            if boss then add(boss, tonumber(Config.V9BossBladeRegistersPerSlash) or 5) end

            local fillLimit = V9RaidCombat.ColossalP2ThreatFillLimit()
            for _, entry in ipairs(V9RaidCombat.ColossalP2ThreatEntries(fillLimit)) do
                add(entry.Titan, 1)
            end

            return plan, string.format(
                "COLOSSAL SPLIT • BOSS x5 + EREN x%d",
                tonumber(V9RaidCombat.LastColossalThreatFill) or 0
            )
        end

        local boss = V9RaidCombat.LiveBoss()
        if boss then add(boss, tonumber(Config.V9BossBladeRegistersPerSlash) or 5) end

        if V9RaidCombat.BossAddFillAllowed() then
            local fill = raid == "Colossal Raid"
                and math.max(0, math.floor(tonumber(Config.V9ColossalBossAddFill) or 9))
                or math.max(0, math.floor(tonumber(Config.V9BossAddFill) or 6))
            for _, entry in ipairs(V9RaidCombat.OrdinaryTitans(fill, true)) do
                add(entry.Titan, 1)
            end
        end
        return plan, raid .. " • BOSS x5"
    end

    if phase == "P1 Objective" then
        local normalLimit = getEffectiveTitansPerHit()
        if raid == "Armored Raid" then
            normalLimit = math.max(1, normalLimit - 1)
        end
        for _, titan in ipairs(queueTargets or {}) do
            add(titan, 1)
            if #plan >= normalLimit then break end
        end

        -- Armored P1 traces mix objective adds with one light boss register.
        if raid == "Armored Raid" then
            local rawBoss = V9RaidCombat.RawP1Boss()
            if rawBoss then
                seen[rawBoss] = nil
                add(rawBoss, tonumber(Config.V9ArmoredP1BossRegisters) or 1)
            end
        end

        return plan, raid .. " • P1 OBJECTIVE"
    end

    local packLimit = getEffectiveTitansPerHit()
    for _, titan in ipairs(queueTargets or {}) do
        add(titan, 1)
        if #plan >= packLimit then break end
    end
    return plan, raid .. " • " .. phase
end


function V9RaidCombat.FreeSpearBurstTargets(entries, fallbackPosition)
    entries = type(entries) == "table" and entries or {}

    local spearProfile = PROFILE and PROFILE.Spears or {}
    local minimum = math.max(1, math.floor(tonumber(spearProfile.PackMinTargets) or 2))
    local maximum = math.max(minimum, math.floor(tonumber(spearProfile.PackMaxTargets) or 4))
    local valid = {}

    for _, entry in ipairs(entries) do
        local titan = entry and entry.Titan
        local part = titan and (V9RaidCombat.ExactNape(titan) or entry.Part) or (entry and entry.Part)

        if part and part.Parent then
            valid[#valid + 1] = {
                Part = part,
                Distance = typeof(fallbackPosition) == "Vector3"
                    and (part.Position - fallbackPosition).Magnitude
                    or 0,
            }
        end
    end

    table.sort(valid, function(a, b)
        return a.Distance < b.Distance
    end)

    local available = #valid
    if available <= 0 then
        return {}, 0
    end

    local targetCount = math.min(maximum, available)
    if available >= minimum then
        targetCount = math.max(minimum, targetCount)
    end

    local targets = {}
    for index = 1, targetCount do
        targets[index] = valid[index].Part
    end

    return targets, targetCount
end

function V9RaidCombat.BuildSpearBurstTargets(mode, exactTitan, fallbackPosition)
    local raid = V9RaidCombat.Context()
    local targets = {}

    local function addPart(part, repeats)
        if not part or not part.Parent then return end
        for _ = 1, math.max(1, math.floor(tonumber(repeats) or 1)) do
            targets[#targets + 1] = part
        end
    end

    if mode == "BOSS BURST" then
        local boss, part = V9RaidCombat.LiveBoss()
        if not boss and exactTitan and isTitanAlive(exactTitan) then
            boss = exactTitan
            part = V9RaidCombat.ExactNape(exactTitan) or getTitanTargetPart(exactTitan)
        end

        local splitFill = 0
        if part then
            local bossRepeats =
                tonumber(Config.V9SpearBossRepeats)
                or 5

            if raid == "Colossal Raid"
                and V55ColossalDirector
                and V55ColossalDirector.Stage == "P2 BOSS"
                and V55ColossalDirector.DefenseMode == true
                and SliceHubIsPremium() then
                local hp =
                    tonumber(
                        V55ColossalDirector
                            .ErenHealthPercent
                    ) or 100

                bossRepeats =
                    hp <= 20 and 1
                    or hp <= 40 and 2
                    or hp <= 70 and 3
                    or 4
            end

            addPart(part, bossRepeats)

            if raid == "Colossal Raid"
                and V55ColossalDirector
                and V55ColossalDirector.Stage == "P2 BOSS"
                and Config.V943ColossalSplitRouteEnabled == true then
                local fillLimit = V9RaidCombat.ColossalP2ThreatFillLimit()
                for _, entry in ipairs(V9RaidCombat.ColossalP2ThreatEntries(fillLimit)) do
                    if entry.Part and entry.Part.Parent then
                        targets[#targets + 1] = entry.Part
                        splitFill += 1
                    end
                end
            elseif V9RaidCombat.BossAddFillAllowed() then
                local fill = math.max(0, math.floor(tonumber(Config.V9SpearBossAddFill) or 6))
                for _, entry in ipairs(V9RaidCombat.OrdinaryTitans(fill, true)) do
                    if entry.Part and entry.Part.Parent then targets[#targets + 1] = entry.Part end
                end
            end
        end

        if raid == "Colossal Raid"
            and V55ColossalDirector
            and V55ColossalDirector.Stage == "P2 BOSS" then
            return targets, string.format("COLOSSAL SPLIT BOSS x5 + EREN x%d", splitFill)
        end
        return targets, raid .. " BOSS x5"
    end

    if mode == "SURVIVOR HUNT" and exactTitan then
        local part = V9RaidCombat.ExactNape(exactTitan) or getTitanTargetPart(exactTitan)
        if part then targets[1] = part end
        return targets, "SURVIVOR"
    end

    local entries = V35Spears and V35Spears.GetGlobalEntries and V35Spears.GetGlobalEntries() or {}
    if typeof(fallbackPosition) == "Vector3" then
        table.sort(entries, function(a, b)
            local ap = a.Part and a.Part.Position
            local bp = b.Part and b.Part.Position
            if not ap then return false end
            if not bp then return true end
            return (ap - fallbackPosition).Magnitude < (bp - fallbackPosition).Magnitude
        end)
    end

    if not SliceHubIsPremium() then
        local freeTargets, projectedCount =
            V9RaidCombat.FreeSpearBurstTargets(entries, fallbackPosition)
        return freeTargets, "BASIC PACK STRIKE", projectedCount
    end

    local spearProfile = PROFILE and PROFILE.Spears or {}
    local minimum = math.max(1, math.floor(tonumber(spearProfile.PackMinTargets) or 6))
    local maximum = math.max(minimum, math.floor(tonumber(spearProfile.PackMaxTargets) or 16))

    for _, entry in ipairs(entries) do
        local part = entry.Titan and (V9RaidCombat.ExactNape(entry.Titan) or entry.Part) or entry.Part
        if part and part.Parent then
            targets[#targets + 1] = part
            if #targets >= maximum then break end
        end
    end

    -- When six or more Titans remain, Premium always commits at least six exact
    -- weak-point registers. With fewer than six alive, it cleans the survivors.
    local plannedCount = #targets
    if #entries >= minimum then
        plannedCount = math.max(minimum, plannedCount)
    end

    return targets, "ADVANCED PACK STRIKE", math.min(maximum, plannedCount)
end

function V9RaidCombat.ResolveBurstPosition(target, fallbackPosition)
    if typeof(target) == "Instance" and target:IsA("BasePart") and target.Parent then
        return target.Position
    end
    if typeof(target) == "Vector3" then return target end
    return fallbackPosition
end

V35Spears = V35Spears or {
    Busy = false,
    NextFireAt = 0,
    Shots = 0,
    Serial = 0,
    LastRipperSerial = 0,
    LastPack = 0,
    LastTarget = nil,
    LastSpearName = nil,
    LastStatus = "Idle",
    LastError = nil,
    LastShotAt = 0,
}

function V35Spears.GetRemotes()
    local replicatedStorage = game:GetService("ReplicatedStorage")
    local assets = replicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")

    return
        remotes and remotes:FindFirstChild("GET"),
        remotes and remotes:FindFirstChild("POST")
end


function V35Spears.DirectReload(station)
    local _, postRemote = V35Spears.GetRemotes()

    if not postRemote or not postRemote:IsA("RemoteEvent") then
        V35Spears.LastStatus = "Reload POST missing"
        return false
    end

    local ok, err = pcall(function()
        postRemote:FireServer(
            "Attacks",
            "Reload",
            station
        )
    end)

    if not ok then
        V35Spears.LastError = tostring(err)
        V35Spears.LastStatus = "Direct reload failed"
        return false
    end

    V35Spears.LastStatus = "Station reload sent"
    return true
end

function V35Spears.IsEquipped()
    return player and player:GetAttribute("Weapon") == "Spears"
end

function V35Spears.LiveCharacter()
    local live = player and player.Character or nil
    if live and live.Parent then return live end
    if character and character.Parent then return character end
    return nil
end

function V35Spears.CountAvailableSpearObjects(liveCharacter)
    liveCharacter = liveCharacter or V35Spears.LiveCharacter()
    if not liveCharacter then return nil end

    local sawNumbered = false
    local available = 0

    for _, object in ipairs(liveCharacter:GetDescendants()) do
        if object.Name == "Spears" then
            for _, spear in ipairs(object:GetChildren()) do
                if tonumber(spear.Name) then
                    sawNumbered = true
                    local used = spear:GetAttribute("Used") == true
                    local visible = true
                    pcall(function()
                        if spear:IsA("BasePart") then visible = spear.Transparency < 1 end
                    end)
                    if not used and visible then available += 1 end
                end
            end
        end
    end

    return sawNumbered and available or nil
end

function V35Spears.ReadAmmo()
    local liveCharacter = V35Spears.LiveCharacter()
    if not liveCharacter then return nil end

    local attributeAmmo = tonumber(liveCharacter:GetAttribute("Spears"))
    local objectAmmo = V35Spears.CountAvailableSpearObjects(liveCharacter)

    if attributeAmmo == nil then return objectAmmo end
    if objectAmmo == nil then return attributeAmmo end

    -- The HUD and refill engine now share one conservative source. During Female
    -- transitions the old Character reference could survive briefly with stale ammo;
    -- numbered live spear objects provide a lower bound that catches that state.
    return math.max(0, math.min(attributeAmmo, objectAmmo))
end


function V35Spears.ReadCapacity()
    local liveCharacter = V35Spears.LiveCharacter()
    if not liveCharacter then return nil end

    local value = tonumber(liveCharacter:GetAttribute("Max_Spears"))
    if value and value > 0 then
        return math.floor(value + 0.5)
    end

    return nil
end

function V35Spears.FindAvailableSpearName()
    local liveCharacter = V35Spears.LiveCharacter()
    if not liveCharacter then return nil end

    local candidates = {}

    for _, object in ipairs(liveCharacter:GetDescendants()) do
        if object.Name == "Spears" then
            for _, spear in ipairs(object:GetChildren()) do
                local numericName = tonumber(spear.Name)

                if numericName then
                    local used = spear:GetAttribute("Used") == true
                    local visible = true

                    pcall(function()
                        if spear:IsA("BasePart") then
                            visible = spear.Transparency < 1
                        end
                    end)

                    if State.SpearInfiniteEnabled == true or (not used and visible) then
                        table.insert(candidates, {
                            Number = numericName,
                            Name = spear.Name,
                        })
                    end
                end
            end
        end
    end

    table.sort(candidates, function(a, b)
        return a.Number < b.Number
    end)

    return candidates[1] and candidates[1].Name or nil
end

V36PackDrain = V36PackDrain or {
    Center = nil,
    AnchorPart = nil,
    PackCount = 0,
    ShotsOnPack = 0,
    Misses = 0,
    ObservedKillCap = 3,
    LastKills = 0,
    LastGlobalAlive = 0,
    Serial = 0,
}

function V35Spears.GetGlobalEntries()
    local entries = {}
    local titansFolder = Workspace:FindFirstChild(Config.TitansFolderName)

    if not titansFolder then
        return entries
    end

    for _, titan in ipairs(titansFolder:GetChildren()) do
        if isTitanAlive(titan)
            and (
                not V4RaidDirector
                or not V4RaidDirector.AllowTitanTarget
                or V4RaidDirector.AllowTitanTarget(titan)
            ) then

            local part = getTitanTargetPart(titan)

            if part and part.Parent then
                entries[#entries + 1] = {
                    Titan = titan,
                    Part = part,
                }
            end
        end
    end

    return entries
end

function V35Spears.GlobalAliveCount()
    return #V35Spears.GetGlobalEntries()
end

function V35Spears.PackMembersNear(center, radius)
    if typeof(center) ~= "Vector3" then
        return {}
    end

    local entries = V35Spears.GetGlobalEntries()
    local members = {}
    local radiusSquared = math.max(10, tonumber(radius) or 95) ^ 2

    for _, entry in ipairs(entries) do
        local part = entry.Part

        if part and part.Parent then
            local delta = part.Position - center

            if delta:Dot(delta) <= radiusSquared then
                members[#members + 1] = entry
            end
        end
    end

    return members
end

function V35Spears.CenterForMembers(members)
    if type(members) ~= "table" or #members == 0 then
        return nil, nil
    end

    if #members <= 2 then
        local part = members[1] and members[1].Part
        return part and part.Position or nil, part
    end

    local sum = Vector3.zero

    for _, entry in ipairs(members) do
        sum += entry.Part.Position
    end

    local center = sum / #members
    local nearestPart = nil
    local nearestDistance = math.huge

    for _, entry in ipairs(members) do
        local delta = entry.Part.Position - center
        local distanceSquared = delta:Dot(delta)

        if distanceSquared < nearestDistance then
            nearestDistance = distanceSquared
            nearestPart = entry.Part
        end
    end

    return center, nearestPart
end

function V35Spears.SelectBestGlobalPack()
    if V4RaidDirector and V4RaidDirector.PreferredBossPart then
        local bossTitan, bossPart =
            V4RaidDirector.PreferredBossPart()

        if bossTitan and bossPart then
            return bossPart.Position, bossPart, 1
        end
    end

    local entries = V35Spears.GetGlobalEntries()

    if #entries == 0 then
        return nil, nil, 0
    end

    local radius = math.max(10, tonumber(Config.SpearClusterRadius) or 95)
    local radiusSquared = radius * radius
    local bestMembers = nil
    local bestCount = 0
    local bestCompactness = math.huge

    for _, anchor in ipairs(entries) do
        local anchorPart = anchor.Part

        if anchorPart and anchorPart.Parent then
            local members = {}
            local compactness = 0

            for _, candidate in ipairs(entries) do
                local part = candidate.Part

                if part and part.Parent then
                    local delta = part.Position - anchorPart.Position
                    local distanceSquared = delta:Dot(delta)

                    if distanceSquared <= radiusSquared then
                        members[#members + 1] = candidate
                        compactness += distanceSquared
                    end
                end
            end

            local count = #members
            local averageCompactness =
                count > 0 and (compactness / count) or math.huge

            if count > bestCount
                or (count == bestCount and averageCompactness < bestCompactness) then

                bestMembers = members
                bestCount = count
                bestCompactness = averageCompactness
            end
        end
    end

    local center, part = V35Spears.CenterForMembers(bestMembers)

    return center, part, bestCount
end

function V35Spears.ClearDrainPack(reason)
    V36PackDrain.Center = nil
    V36PackDrain.AnchorPart = nil
    V36PackDrain.PackCount = 0
    V36PackDrain.ShotsOnPack = 0
    V36PackDrain.Misses = 0
    V36PackDrain.Serial += 1

    if reason then
        V35Spears.LastStatus = "Rescan: " .. tostring(reason)
    end
end

function V35Spears.ResolveDrainPack()
    local radius = math.max(10, tonumber(Config.SpearClusterRadius) or 95)

    if V4RaidDirector and V4RaidDirector.HardBossLock then
        local bossTitan, bossPart = V4RaidDirector.HardBossLock()
        if bossTitan and bossPart then
            V36PackDrain.Center = bossPart.Position
            V36PackDrain.AnchorPart = bossPart
            V36PackDrain.PackCount = 1
            V36PackDrain.Misses = 0
            V35Spears.LastStatus = "Boss Drain Lock: " .. tostring(bossTitan.Name)
            return bossPart.Position, bossPart, 1
        end
    end

    if typeof(V36PackDrain.Center) == "Vector3" then
        local members = V35Spears.PackMembersNear(V36PackDrain.Center, radius)

        if #members > 0 and V36PackDrain.Misses < 2 then
            local center, part = V35Spears.CenterForMembers(members)

            V36PackDrain.Center = center or V36PackDrain.Center
            V36PackDrain.AnchorPart = part or V36PackDrain.AnchorPart
            V36PackDrain.PackCount = #members

            return
                V36PackDrain.Center,
                V36PackDrain.AnchorPart,
                V36PackDrain.PackCount
        end

        V35Spears.ClearDrainPack(
            #members == 0 and "pack drained" or "pack not responding"
        )
    end

    local center, part, count = V35Spears.SelectBestGlobalPack()

    V36PackDrain.Center = center
    V36PackDrain.AnchorPart = part
    V36PackDrain.PackCount = tonumber(count) or 0
    V36PackDrain.ShotsOnPack = 0
    V36PackDrain.Misses = 0
    V36PackDrain.Serial += 1

    return center, part, tonumber(count) or 0
end

function V35Spears.AfterDrainShot(targetPosition, previousPackCount, aliveBefore)
    task.wait(math.max(0.01, tonumber(PROFILE.Spears.PostShotSettle) or 0.08))

    local aliveAfter = V35Spears.GlobalAliveCount()
    local kills = math.max(
        0,
        (tonumber(aliveBefore) or aliveAfter) - aliveAfter
    )

    V36PackDrain.LastKills = kills
    V36PackDrain.LastGlobalAlive = aliveAfter
    V36PackDrain.ShotsOnPack += 1

    if kills > 0 then
        V36PackDrain.ObservedKillCap = math.max(
            tonumber(V36PackDrain.ObservedKillCap) or 3,
            kills
        )
        V36PackDrain.Misses = 0
    else
        V36PackDrain.Misses += 1
    end

    if V4RaidDirector and V4RaidDirector.HardBossLock then
        local bossTitan, bossPart = V4RaidDirector.HardBossLock()
        if bossTitan and bossPart then
            V36PackDrain.Center = bossPart.Position
            V36PackDrain.AnchorPart = bossPart
            V36PackDrain.PackCount = 1
            V36PackDrain.Misses = 0
            V35Spears.LastStatus =
                "Boss Drain Lock | last global kills " .. tostring(kills)
            return
        end
    end

    local radius = math.max(10, tonumber(Config.SpearClusterRadius) or 95)
    local remaining = V35Spears.PackMembersNear(
        V36PackDrain.Center or targetPosition,
        radius
    )

    V36PackDrain.PackCount = #remaining

    if #remaining <= 0 then
        V35Spears.ClearDrainPack("pack drained")
    elseif V36PackDrain.Misses >= 2 then
        V35Spears.ClearDrainPack("two no-kill blasts")
    else
        local center, part = V35Spears.CenterForMembers(remaining)

        V36PackDrain.Center = center or V36PackDrain.Center
        V36PackDrain.AnchorPart = part or V36PackDrain.AnchorPart

        V35Spears.LastStatus = string.format(
            "Drain pack %d | last kills %d | cap≥%d",
            #remaining,
            kills,
            tonumber(V36PackDrain.ObservedKillCap) or 3
        )
    end
end

function V35Spears.GetBestCluster()
    local center, part, count = V35Spears.ResolveDrainPack()

    V35Spears.LastPack = tonumber(count) or 0
    V35Spears.LastTarget = center

    return center, part, tonumber(count) or 0
end

function V35Spears.ShouldRun()
    if V4RaidDirector
        and V4RaidDirector.ShouldPauseCombat
        and V4RaidDirector.ShouldPauseCombat() then
        return false
    end

    return State
        and State.FarmEnabled == true
        and State.SpearSupportEnabled == true
        and State.SpearAutoFireEnabled ~= false
        and V35Spears.IsEquipped()
end

function V35Spears.FireDirect(targetPosition, packCount, burstTargets, burstLabel)
    local isBossBurst = string.find(tostring(burstLabel or ""), "BOSS", 1, true) ~= nil

    if not isBossBurst then
        local spearProfile = PROFILE and PROFILE.Spears or {}
        local maximum = math.max(
            1,
            math.floor(tonumber(spearProfile.PackMaxTargets)
                or (SliceHubIsPremium() and 16 or 4))
        )

        if type(burstTargets) ~= "table" or #burstTargets == 0 then
            V35Spears.LastStatus = SliceHubIsPremium()
                and "ADVANCED PACK • waiting for targets"
                or "BASIC PACK • waiting for exact targets"
            return false, "no planned pack targets"
        end

        while #burstTargets > maximum do
            table.remove(burstTargets)
        end

        packCount = math.min(math.max(1, tonumber(packCount) or #burstTargets), maximum)
    end

    if V4RaidDirector
        and V4RaidDirector.ShouldPauseCombat
        and V4RaidDirector.ShouldPauseCombat() then
        V35Spears.LastStatus = "Paused for raid transition"
        return false, "raid transition"
    end

    if V35Spears.Busy then
        return false, "busy"
    end

    local now = os.clock()
    if now < (V35Spears.NextFireAt or 0) then
        return false, "cooldown"
    end

    if typeof(targetPosition) ~= "Vector3" then
        return false, "invalid target"
    end

    local ammo = V35Spears.ReadAmmo()

    if State.SpearInfiniteEnabled ~= true
        and ammo ~= nil
        and State.SpearAutoRefillEnabled
        and ammo <= 1 then
        V35Spears.LastStatus = "Holding last spear — safety refill"
        return false, "refill safety"
    end

    if State.SpearInfiniteEnabled ~= true and ammo ~= nil and ammo <= 0 then
        V35Spears.LastStatus = "Empty — refill pending"
        return false, "empty"
    end

    local spearName = V35Spears.FindAvailableSpearName()
    if not spearName then
        V35Spears.LastStatus = "No available spear object"
        return false, "no spear"
    end

    local getRemote, postRemote = V35Spears.GetRemotes()
    if not getRemote or not getRemote:IsA("RemoteFunction") then
        V35Spears.LastStatus = "GET remote missing"
        return false, "GET missing"
    end
    if not postRemote or not postRemote:IsA("RemoteEvent") then
        V35Spears.LastStatus = "POST remote missing"
        return false, "POST missing"
    end

    local aliveBeforeShot = V35Spears.GlobalAliveCount()

    V35Spears.Busy = true
    V35Spears.LastStatus = "Arming spear " .. tostring(spearName)
    V35Spears.LastError = nil
    V35Spears.LastSpearName = spearName

    task.spawn(function()
        local okFire, fired = pcall(function()
            return getRemote:InvokeServer("Spears", "S_Fire", tostring(spearName))
        end)

        if not okFire or fired ~= true then
            V35Spears.LastError = okFire and "S_Fire rejected" or tostring(fired)
            V35Spears.LastStatus = "S_Fire failed"
            V35Spears.NextFireAt = os.clock() + 0.35
            V35Spears.Busy = false
            return
        end

        local armedStart = os.clock()
        while character
            and character.Parent
            and character:GetAttribute("Current_Spear") == nil
            and os.clock() - armedStart < (tonumber(Config.SpearArmTimeout) or 0.60) do
            task.wait(0.01)
        end

        -- Raid traces consistently place the first explosion roughly 0.10-0.12s
        -- after accepted S_Fire, then fan the whole burst with no scheduler wait.
        task.wait(math.max(
            0.03,
            tonumber(Config.V9SpearArmDelay)
            or tonumber(Config.SpearExplodeDelay)
            or 0.105
        ))

        local targets = type(burstTargets) == "table" and burstTargets or {}
        if #targets == 0 then targets = {targetPosition} end

        local sent = 0
        local firstPosition = nil
        local okExplode, explodeErr = pcall(function()
            for _, burstTarget in ipairs(targets) do
                local explodePosition = V9RaidCombat
                    and V9RaidCombat.ResolveBurstPosition
                    and V9RaidCombat.ResolveBurstPosition(burstTarget, targetPosition)
                    or targetPosition

                if typeof(explodePosition) == "Vector3" then
                    firstPosition = firstPosition or explodePosition
                    postRemote:FireServer("Spears", "S_Explode", explodePosition)
                    sent += 1
                end
            end
        end)

        if not okExplode or sent <= 0 then
            V35Spears.LastError = tostring(explodeErr or "no valid burst target")
            V35Spears.LastStatus = "S_Explode burst failed"
            V35Spears.NextFireAt = os.clock() + 0.35
            V35Spears.Busy = false
            return
        end

        V35Spears.Shots += 1
        V35Spears.Serial += 1
        V35Spears.LastShotAt = os.clock()
        V35Spears.LastPack = tonumber(packCount) or V35Spears.LastPack
        V35Spears.LastBurstCount = sent
        V35Spears.LastStatus = string.format(
            "%s • EXPLODE x%d",
            tostring(burstLabel or "V9 BURST"),
            sent
        )

        if V9RaidCombat then
            V9RaidCombat.LastSpearExplodes = sent
            V9RaidCombat.SpearMode = tostring(burstLabel or "V9 BURST")
            if string.find(V9RaidCombat.SpearMode, "BOSS", 1, true) then
                V9RaidCombat.BossSpearShots += 1
            else
                V9RaidCombat.PackSpearShots += 1
            end
        end

        local confirmStart = os.clock()
        while character
            and character.Parent
            and character:GetAttribute("Current_Spear") ~= nil
            and os.clock() - confirmStart
                < (tonumber(Config.SpearPostExplodeConfirmTimeout) or 0.45) do
            task.wait(0.015)
        end

        V35Spears.AfterDrainShot(
            firstPosition or targetPosition,
            tonumber(packCount) or 0,
            aliveBeforeShot
        )

        local directorMode = V56SpearDirector and V56SpearDirector.Mode or "PACK SWEEP"
        local directorCooldown = V56SpearDirector and V56SpearDirector.CooldownForMode
            and V56SpearDirector.CooldownForMode(directorMode)
            or math.max(0.12, tonumber(Config.SpearFireCooldown) or 0.24)
        V35Spears.NextFireAt = os.clock() + directorCooldown
        V35Spears.Busy = false
    end)

    return true, spearName
end


---------------------------------------------------------------------
-- V5.6 SPEAR ENGINE V2 DIRECTOR
-- Modes:
--   PACK SWEEP       : build multiple packs and rotate by angle around player.
--   OBJECTIVE DEFENSE: barrage packs threatening boats / Eren objective anchors.
--   BOSS BURST       : exact live raid boss weak point, refreshed every shot.
--   CANNON HOLD      : Colossal P1 remains cannon-owned unless defense mode opens.
---------------------------------------------------------------------

V56SpearDirector = V56SpearDirector or {
    Mode = "PACK SWEEP",
    Queue = {},
    QueueIndex = 1,
    QueueBuiltAt = 0,
    QueueLifetime = tonumber(PROFILE.Spears.QueueLifetime) or 0.45,
    QueueMode = nil,
    MaxPacks = tonumber(PROFILE.Spears.MaxPacks) or 10,
    PackRadius = tonumber(PROFILE.Spears.ClusterRadius) or 95,
    LastTargetLabel = "none",
    LastQueueSize = 0,
    SweepSerial = 0,
    BossShots = 0,
    DefenseShots = 0,
    PackShots = 0,
    SurvivorThreshold = 5,
    SurvivorTarget = nil,
    SurvivorPart = nil,
    SurvivorShots = 0,
    SurvivorLastShotAt = 0,
    SurvivorLastHealth = nil,
    SurvivorLastAlive = nil,
    SurvivorBlacklist = setmetatable({}, {__mode = "k"}),
    SurvivorRotations = 0,
    SurvivorPartIndex = 1,
    TravelHeight = 520,
    TravelMinDistance = 70,
    TravelCooldown = tonumber(PROFILE.Spears.TravelCooldown) or 0.075,
    LastTravelAt = 0,
    LastTravelPosition = nil,
}

function V56SpearDirector.RootPosition()
    local live = V35Spears.LiveCharacter()
    local root = live and live:FindFirstChild("HumanoidRootPart")
    return root and root.Position or nil
end

function V56SpearDirector.ObjectiveAnchors()
    local anchors = {}

    if V4RaidDirector
        and V4RaidDirector.RaidName == "Colossal Raid"
        and V55ColossalDirector
        and V55ColossalDirector.ResolveErenAnchor then
        local ok, anchor = pcall(V55ColossalDirector.ResolveErenAnchor, false)
        if ok and typeof(anchor) == "Vector3" then
            anchors[#anchors + 1] = anchor
        end
    end

    if #anchors == 0
        and V4RaidDirector
        and V4RaidDirector.RefreshObjectiveAnchors then
        local ok, values = pcall(V4RaidDirector.RefreshObjectiveAnchors, false)
        if ok and type(values) == "table" then
            for _, value in ipairs(values) do
                if typeof(value) == "Vector3" then
                    anchors[#anchors + 1] = value
                end
            end
        end
    end

    return anchors
end

function V56SpearDirector.DistanceToAnchors(position, anchors)
    if typeof(position) ~= "Vector3" then return math.huge end
    if type(anchors) ~= "table" or #anchors == 0 then return 0 end

    local best = math.huge
    for _, anchor in ipairs(anchors) do
        if typeof(anchor) == "Vector3" then
            best = math.min(best, (position - anchor).Magnitude)
        end
    end
    return best
end

function V56SpearDirector.ResolveMode()
    -- V9.4.3: Colossal P2 is always boss-lane movement. Eren defense is appended
    -- inside the same BOSS BURST payload, so Guardian state never pulls the
    -- character away from Bertholdt or turns the whole shot into add-only damage.
    if V4RaidDirector
        and V4RaidDirector.RaidName == "Colossal Raid"
        and V55ColossalDirector
        and V55ColossalDirector.Stage == "P2 BOSS" then
        local bossTitan, bossPart = nil, nil
        if V9RaidCombat and V9RaidCombat.LiveBoss then
            bossTitan, bossPart = V9RaidCombat.LiveBoss()
        end
        if bossTitan and bossPart and bossPart.Parent then
            return "BOSS BURST", bossTitan, bossPart
        end
        return "BOSS BURST", nil, nil
    end

    if V4RaidDirector and V4RaidDirector.HardBossLock then
        local bossTitan, bossPart = V4RaidDirector.HardBossLock()
        if bossTitan and bossPart and bossPart.Parent then
            return "BOSS BURST", bossTitan, bossPart
        end
    end

    if V4RaidDirector and V4RaidDirector.Enabled then
        if V4RaidDirector.RaidName == "Colossal Raid"
            and V4RaidDirector.Phase == "P1 Objective" then
            local defense = V55ColossalDirector
                and V55ColossalDirector.DefenseMode == true
            return defense and "OBJECTIVE DEFENSE" or "CANNON HOLD"
        end

        if V4RaidDirector.Phase == "P1 Objective"
            and (V4RaidDirector.RaidName == "Armored Raid"
                or V4RaidDirector.RaidName == "Attack Raid") then
            return "OBJECTIVE DEFENSE"
        end
    end

    return "PACK SWEEP"
end

function V56SpearDirector.BuildPacks(entries, mode)
    if type(entries) ~= "table" or #entries == 0 then return {} end

    local radius = math.max(30, tonumber(Config.SpearClusterRadius) or V56SpearDirector.PackRadius)
    local radiusSquared = radius * radius
    local anchors = mode == "OBJECTIVE DEFENSE" and V56SpearDirector.ObjectiveAnchors() or {}
    local source = {}

    for _, entry in ipairs(entries) do
        local part = entry.Part
        if part and part.Parent then
            local allowed = true
            if mode == "OBJECTIVE DEFENSE" and #anchors > 0 then
                local defenseRadius = 340
                if V4RaidDirector
                    and V4RaidDirector.RaidName == "Colossal Raid"
                    and V55ColossalDirector
                    and V55ColossalDirector.Stage == "P2 BOSS" then
                    defenseRadius = 300
                end
                allowed = V56SpearDirector.DistanceToAnchors(part.Position, anchors) <= defenseRadius
            end
            if allowed then source[#source + 1] = entry end
        end
    end

    if #source == 0 then return {} end

    local candidatePacks = {}
    for _, seed in ipairs(source) do
        local members = {}
        local compactness = 0
        local seedPos = seed.Part.Position

        for _, candidate in ipairs(source) do
            local part = candidate.Part
            if part and part.Parent then
                local delta = part.Position - seedPos
                local d2 = delta:Dot(delta)
                if d2 <= radiusSquared then
                    members[#members + 1] = candidate
                    compactness += d2
                end
            end
        end

        local center, anchorPart = V35Spears.CenterForMembers(members)
        if center and anchorPart then
            candidatePacks[#candidatePacks + 1] = {
                Center = center,
                Part = anchorPart,
                Members = members,
                Count = #members,
                Compactness = #members > 0 and compactness / #members or math.huge,
                ObjectiveDistance = V56SpearDirector.DistanceToAnchors(center, anchors),
            }
        end
    end

    table.sort(candidatePacks, function(a, b)
        if mode == "OBJECTIVE DEFENSE" and a.ObjectiveDistance ~= b.ObjectiveDistance then
            return a.ObjectiveDistance < b.ObjectiveDistance
        end
        if a.Count ~= b.Count then return a.Count > b.Count end
        return a.Compactness < b.Compactness
    end)

    local selected = {}
    local assigned = {}
    local maxPacks = math.max(1, tonumber(V56SpearDirector.MaxPacks) or 10)

    for _, pack in ipairs(candidatePacks) do
        local freshMembers = {}
        for _, member in ipairs(pack.Members) do
            if member.Titan and not assigned[member.Titan] then
                freshMembers[#freshMembers + 1] = member
            end
        end

        if #freshMembers > 0 then
            local center, part = V35Spears.CenterForMembers(freshMembers)
            if center and part then
                selected[#selected + 1] = {
                    Center = center,
                    Part = part,
                    Members = freshMembers,
                    Count = #freshMembers,
                    ObjectiveDistance = V56SpearDirector.DistanceToAnchors(center, anchors),
                }
                for _, member in ipairs(freshMembers) do
                    assigned[member.Titan] = true
                end
                if #selected >= maxPacks then break end
            end
        end
    end

    -- Spiral sweep ordering: once packs are chosen by value, walk around the
    -- battlefield in angular order instead of bouncing randomly left/right.
    local rootPosition = V56SpearDirector.RootPosition()
    if mode == "PACK SWEEP" and typeof(rootPosition) == "Vector3" then
        table.sort(selected, function(a, b)
            local da = a.Center - rootPosition
            local db = b.Center - rootPosition
            local aa = math.atan2(da.Z, da.X)
            local ab = math.atan2(db.Z, db.X)
            return aa < ab
        end)
    end

    return selected
end

function V56SpearDirector.RebuildQueue(mode)
    local entries = V35Spears.GetGlobalEntries()
    local queue = V56SpearDirector.BuildPacks(entries, mode)

    V56SpearDirector.Queue = queue
    V56SpearDirector.QueueIndex = 1
    V56SpearDirector.QueueBuiltAt = os.clock()
    V56SpearDirector.QueueMode = mode
    V56SpearDirector.LastQueueSize = #queue
    V56SpearDirector.SweepSerial += 1

    return queue
end

function V56SpearDirector.ResolvePackTarget(pack)
    if type(pack) ~= "table" then return nil, 0 end

    local liveMembers = {}
    for _, member in ipairs(pack.Members or {}) do
        local titan = member.Titan
        if titan and titan.Parent and isTitanAlive(titan)
            and (not V4RaidDirector
                or not V4RaidDirector.AllowTitanTarget
                or V4RaidDirector.AllowTitanTarget(titan)) then
            local part = getTitanTargetPart(titan)
            if part and part.Parent then
                liveMembers[#liveMembers + 1] = {Titan = titan, Part = part}
            end
        end
    end

    if #liveMembers == 0 then return nil, 0 end
    local center, part = V35Spears.CenterForMembers(liveMembers)
    pack.Center = center or pack.Center
    pack.Part = part or pack.Part
    pack.Members = liveMembers
    pack.Count = #liveMembers
    return pack.Center, pack.Count
end

function V56SpearDirector.NextPack(mode)
    local now = os.clock()
    local queue = V56SpearDirector.Queue

    if V56SpearDirector.QueueMode ~= mode
        or type(queue) ~= "table"
        or #queue == 0
        or now - (V56SpearDirector.QueueBuiltAt or 0) >= V56SpearDirector.QueueLifetime then
        queue = V56SpearDirector.RebuildQueue(mode)
    end

    if #queue == 0 then return nil, 0 end

    local attempts = #queue
    while attempts > 0 do
        if V56SpearDirector.QueueIndex > #queue then
            V56SpearDirector.QueueIndex = 1
        end

        local pack = queue[V56SpearDirector.QueueIndex]
        V56SpearDirector.QueueIndex += 1
        local center, count = V56SpearDirector.ResolvePackTarget(pack)
        if center and count > 0 then
            return center, count
        end
        attempts -= 1
    end

    V56SpearDirector.RebuildQueue(mode)
    return nil, 0
end

function V56SpearDirector.TitanHealth(titan)
    if not titan or not titan.Parent then return nil end
    local humanoid = titan:FindFirstChildOfClass("Humanoid")
    return humanoid and tonumber(humanoid.Health) or nil
end

function V56SpearDirector.SurvivorBlacklisted(titan)
    local expiry = V56SpearDirector.SurvivorBlacklist[titan]
    if not expiry then return false end
    if os.clock() >= expiry then
        V56SpearDirector.SurvivorBlacklist[titan] = nil
        return false
    end
    return true
end

function V56SpearDirector.ResetSurvivorTarget(reason)
    V56SpearDirector.SurvivorTarget = nil
    V56SpearDirector.SurvivorPart = nil
    V56SpearDirector.SurvivorShots = 0
    V56SpearDirector.SurvivorLastShotAt = 0
    V56SpearDirector.SurvivorLastHealth = nil
    V56SpearDirector.SurvivorLastAlive = nil
    V56SpearDirector.SurvivorPartIndex = 1
    if reason then V56SpearDirector.LastTargetLabel = tostring(reason) end
end

function V56SpearDirector.ResolveSurvivorPart(titan)
    if not titan or not titan.Parent then return nil end
    local order = {"Nape", "UpperTorso", "HumanoidRootPart", "Torso", "Head", "LowerTorso"}
    local startIndex = math.clamp(math.floor(tonumber(V56SpearDirector.SurvivorPartIndex) or 1), 1, #order)

    for offset = 0, #order - 1 do
        local index = ((startIndex + offset - 1) % #order) + 1
        local part = titan:FindFirstChild(order[index], true)
        if part and part:IsA("BasePart") and part.Parent then
            V56SpearDirector.SurvivorPartIndex = index
            return part
        end
    end

    return getTitanTargetPart(titan)
end

function V56SpearDirector.AdvanceSurvivorPart()
    local count = 6
    V56SpearDirector.SurvivorPartIndex = ((math.floor(tonumber(V56SpearDirector.SurvivorPartIndex) or 1)) % count) + 1
end

function V56SpearDirector.FastTravel(targetPosition, mode)
    if typeof(targetPosition) ~= "Vector3" then return false end
    if not character or not character.Parent or not rootPart or not humanoid or humanoid.Health <= 0 then return false end
    if V577MovementAuthority and not V577MovementAuthority.CanMove("NORMAL") then
        return false
    end

    local colossalMountedDefense = V55ColossalDirector
        and V4RaidDirector
        and V4RaidDirector.RaidName == "Colossal Raid"
        and V55ColossalDirector.Stage == "P1 CANNON STALL"
        and V55ColossalDirector.DefenseMode == true
        and V55ColossalDirector.Entered == true

    if mode == "CANNON HOLD" or colossalMountedDefense then
        return false
    end

    local now = os.clock()
    if now - (tonumber(V56SpearDirector.LastTravelAt) or 0)
        < math.max(0.03, tonumber(V56SpearDirector.TravelCooldown) or 0.075) then
        return false
    end

    local height = math.max(
        tonumber(Config.SpearSkyHeight) or 430,
        tonumber(V56SpearDirector.TravelHeight) or 520
    )
    local desired = targetPosition + Vector3.new(0, height, 0)
    if V4RaidDirector
        and V4RaidDirector.RaidName == "Colossal Raid"
        and V55ColossalDirector
        and V55ColossalDirector.Stage == "P2 BOSS"
        and mode == "BOSS BURST" then
        local glass = V55ColossalDirector.IsGlassCannonProfile and V55ColossalDirector.IsGlassCannonProfile()
        height = math.max(height, glass and 940 or 780)
        local radial = rootPart.Position - targetPosition
        radial = Vector3.new(radial.X, 0, radial.Z)
        if radial.Magnitude < 20 then radial = Vector3.new(1, 0, 0) end
        local lateral = glass and 560 or 420
        desired = targetPosition + radial.Unit * lateral + Vector3.new(0, height, 0)
    elseif V4RaidDirector
        and V4RaidDirector.RaidName == "Colossal Raid"
        and V55ColossalDirector
        and V55ColossalDirector.IsGlassCannonProfile
        and V55ColossalDirector.IsGlassCannonProfile() then
        height = math.max(height, 760)
        desired = targetPosition + Vector3.new(0, height, 0)
    end
    local distance = (rootPart.Position - desired).Magnitude
    if distance < math.max(20, tonumber(V56SpearDirector.TravelMinDistance) or 70) then
        return false
    end

    CombatAnchorRuntime.Position = desired
    CombatAnchorRuntime.GroundCenter = targetPosition
    CombatAnchorRuntime.AimPosition = targetPosition
    CombatAnchorRuntime.TargetCount = 1
    CombatAnchorRuntime.InitialResidents = 1
    CombatAnchorRuntime.LastRefresh = now
    CombatAnchorRuntime.LastCommit = now

    character:PivotTo(CFrame.lookAt(desired, targetPosition))
    rootPart.AssemblyAngularVelocity = Vector3.zero
    rootPart.AssemblyLinearVelocity = Vector3.zero

    V56SpearDirector.LastTravelAt = now
    V56SpearDirector.LastTravelPosition = targetPosition
    return true
end

function V56SpearDirector.PickSurvivor(entries)
    entries = type(entries) == "table" and entries or V35Spears.GetGlobalEntries()
    local now = os.clock()
    local aliveCount = #entries
    local current = V56SpearDirector.SurvivorTarget

    if current and current.Parent and isTitanAlive(current)
        and not V56SpearDirector.SurvivorBlacklisted(current) then
        local part = V56SpearDirector.ResolveSurvivorPart(current)
        local health = V56SpearDirector.TitanHealth(current)
        local lastHealth = tonumber(V56SpearDirector.SurvivorLastHealth)
        local lastAlive = tonumber(V56SpearDirector.SurvivorLastAlive)
        local shotAge = now - (tonumber(V56SpearDirector.SurvivorLastShotAt) or 0)

        if health and lastHealth and health < lastHealth then
            V56SpearDirector.SurvivorShots = 0
        elseif lastAlive and aliveCount < lastAlive then
            V56SpearDirector.SurvivorShots = 0
        elseif V56SpearDirector.SurvivorShots >= 3 and shotAge >= 0.45 then
            -- The final 1-5 Titans are often awkward ragdolls or expose a different
            -- damage part. Cycle exact body regions first; only blacklist the model
            -- after several rotations instead of tunneling one stale nape forever.
            V56SpearDirector.AdvanceSurvivorPart()
            V56SpearDirector.SurvivorShots = 0
            V56SpearDirector.SurvivorRotations += 1

            if V56SpearDirector.SurvivorRotations % 6 == 0 then
                V56SpearDirector.SurvivorBlacklist[current] = now + 1.2
                V56SpearDirector.SurvivorTarget = nil
                V56SpearDirector.SurvivorPart = nil
                current = nil
            else
                part = V56SpearDirector.ResolveSurvivorPart(current)
            end
        end

        if current and part and part.Parent then
            V56SpearDirector.SurvivorPart = part
            V56SpearDirector.SurvivorLastHealth = health
            V56SpearDirector.SurvivorLastAlive = aliveCount
            return part.Position, 1, current
        end
    end

    local rootPosition = V56SpearDirector.RootPosition()
    local candidates = {}
    for _, entry in ipairs(entries) do
        local titan = entry.Titan
        local part = titan and V56SpearDirector.ResolveSurvivorPart(titan) or nil
        if titan and part and part.Parent and isTitanAlive(titan)
            and not V56SpearDirector.SurvivorBlacklisted(titan) then
            local health = V56SpearDirector.TitanHealth(titan) or math.huge
            local distance = typeof(rootPosition) == "Vector3"
                and (part.Position - rootPosition).Magnitude or math.huge
            candidates[#candidates + 1] = {
                Titan = titan,
                Part = part,
                Health = health,
                Distance = distance,
            }
        end
    end

    if #candidates == 0 and aliveCount > 0 then
        -- All remaining survivors were briefly blacklisted. Clear the temporary
        -- rotation list and try again rather than idling forever.
        V56SpearDirector.SurvivorBlacklist = setmetatable({}, {__mode = "k"})
        for _, entry in ipairs(entries) do
            local titan = entry.Titan
            local part = titan and V56SpearDirector.ResolveSurvivorPart(titan) or nil
            if titan and part and part.Parent and isTitanAlive(titan) then
                candidates[#candidates + 1] = {
                    Titan = titan,
                    Part = part,
                    Health = V56SpearDirector.TitanHealth(titan) or math.huge,
                    Distance = typeof(rootPosition) == "Vector3"
                        and (part.Position - rootPosition).Magnitude or math.huge,
                }
            end
        end
    end

    table.sort(candidates, function(a, b)
        if a.Health ~= b.Health then return a.Health < b.Health end
        return a.Distance < b.Distance
    end)

    local chosen = candidates[1]
    if not chosen then
        V56SpearDirector.ResetSurvivorTarget("no live survivor")
        return nil, 0, nil
    end

    V56SpearDirector.SurvivorTarget = chosen.Titan
    V56SpearDirector.SurvivorPart = chosen.Part
    V56SpearDirector.SurvivorShots = 0
    V56SpearDirector.SurvivorLastShotAt = 0
    V56SpearDirector.SurvivorLastHealth = chosen.Health
    V56SpearDirector.SurvivorLastAlive = aliveCount
    return chosen.Part.Position, 1, chosen.Titan
end

function V56SpearDirector.Target()
    local mode, bossTitan, bossPart = V56SpearDirector.ResolveMode()
    V56SpearDirector.Mode = mode

    if mode == "CANNON HOLD" then
        V56SpearDirector.LastTargetLabel = "Colossal P1 cannon ownership"
        V56SpearDirector.ResetSurvivorTarget()
        return nil, 0, mode, nil
    end

    if mode == "BOSS BURST" then
        V56SpearDirector.ResetSurvivorTarget()
        if bossTitan and bossPart and bossPart.Parent then
            V56SpearDirector.LastTargetLabel = tostring(bossTitan.Name) .. " / " .. tostring(bossPart.Name)
            return bossPart.Position, 1, mode, bossTitan
        end
        V56SpearDirector.LastTargetLabel = "boss unresolved"
        return nil, 0, mode, nil
    end

    local entries = V35Spears.GetGlobalEntries()
    if #entries > 0 and #entries <= math.max(1, tonumber(V56SpearDirector.SurvivorThreshold) or 5) then
        local position, count, titan = V56SpearDirector.PickSurvivor(entries)
        V56SpearDirector.Mode = "SURVIVOR HUNT"
        V56SpearDirector.LastTargetLabel = titan
            and ("SURVIVOR HUNT • " .. tostring(titan.Name) .. " • " .. tostring(#entries) .. " left")
            or "SURVIVOR HUNT • rescanning"
        return position, count, "SURVIVOR HUNT", titan
    end

    V56SpearDirector.ResetSurvivorTarget()
    local center, count = V56SpearDirector.NextPack(mode)
    V56SpearDirector.LastTargetLabel = center and (mode .. " pack " .. tostring(count)) or "none"
    return center, count, mode, nil
end

function V56SpearDirector.CooldownForMode(mode)
    local premiumColossalGuard =
        SliceHubIsPremium()
        and V4RaidDirector
        and V4RaidDirector.RaidName
            == "Colossal Raid"
        and V55ColossalDirector
        and V55ColossalDirector.DefenseMode
            == true

    if premiumColossalGuard then
        local hp =
            tonumber(
                V55ColossalDirector
                    .ErenHealthPercent
            ) or 100

        if mode == "BOSS BURST" then
            if hp <= 20 then return 0.18 end
            if hp <= 40 then return 0.24 end
            if hp <= 70 then return 0.32 end
            return 0.45
        end

        if mode == "OBJECTIVE DEFENSE" then
            if hp <= 20 then return 0.07 end
            if hp <= 40 then return 0.08 end
            if hp <= 70 then return 0.09 end
            return 0.11
        end
    end

    if mode == "BOSS BURST" then
        return math.max(0.35, tonumber(Config.V9SpearBossCadence) or 1.0)
    end

    if State.SpearInfiniteEnabled == true then
        local base = math.max(0.05, tonumber(PROFILE.Spears.InfiniteCooldown) or 0.10)
        if mode == "SURVIVOR HUNT" then return math.max(0.05, base * 0.85) end
        if mode == "OBJECTIVE DEFENSE" then return math.max(0.05, base * 0.95) end
        return base
    end
    local minimum = SliceHubIsPremium() and 0.06 or 0.45
    return math.max(minimum, tonumber(Config.SpearFireCooldown) or 0.24)
end

V984Pacing = V984Pacing or {
    Key = "",
    StartedAt = 0,
    Completed = {},
    Status = "Ready",
}

function V984Pacing.Reset()
    V984Pacing.Key = ""
    V984Pacing.StartedAt = 0
    V984Pacing.Completed = {}
    V984Pacing.Status = "Ready"
end

function V984Pacing.BossHealthPercent(boss)
    if not boss or not boss.Parent then return nil end
    local humanoid = boss:FindFirstChildOfClass("Humanoid")
    if humanoid and humanoid.MaxHealth > 0 then
        return math.clamp((humanoid.Health / humanoid.MaxHealth) * 100, 0, 100)
    end
    local health = tonumber(boss:GetAttribute("Health") or boss:GetAttribute("HP"))
    local maximum = tonumber(boss:GetAttribute("MaxHealth") or boss:GetAttribute("MaxHP"))
    if health and maximum and maximum > 0 then return math.clamp((health / maximum) * 100, 0, 100) end
    return nil
end

function V984Pacing.ShouldPauseFinish()
    if not State or State.FarmEnabled ~= true then return false end
    if WavesRuntimeDirector and WavesRuntimeDirector.Busy == true then return false end

    local raidName = V4RaidDirector and tostring(V4RaidDirector.RaidName or "") or ""
    if raidName ~= "" and raidName ~= "Unknown" and raidName ~= "Colossal Raid" then
        local delay = math.clamp(math.floor((tonumber(State.WaitBeforeRaidBossFinish) or 0) + 0.5), 0, 160)
        if delay <= 0 then return false end
        local boss = V9RaidCombat and V9RaidCombat.LiveBoss and select(1, V9RaidCombat.LiveBoss()) or nil
        local percent = V984Pacing.BossHealthPercent(boss)
        if boss and percent and percent <= 8 then
            local key = "RAID:" .. raidName .. ":" .. tostring(boss)
            if V984Pacing.Completed[key] then return false end
            if V984Pacing.Key ~= key then
                V984Pacing.Key = key
                V984Pacing.StartedAt = os.clock()
            end
            local remaining = delay - (os.clock() - V984Pacing.StartedAt)
            if remaining > 0 then
                V984Pacing.Status = string.format("Waiting before finishing boss: %ds", math.ceil(remaining))
                statusText = V984Pacing.Status
                return true
            end
            V984Pacing.Completed[key] = true
            V984Pacing.Status = "Boss finish delay complete"
            return false
        end
        return false
    end

    local delay = math.clamp(math.floor((tonumber(State.WaitBeforeLastTitan) or 0) + 0.5), 0, 50)
    if delay <= 0 then return false end
    local alive = getCachedAliveTitanCount and getCachedAliveTitanCount() or 0
    if alive == 1 then
        local key = "MISSION_LAST_TITAN"
        if V984Pacing.Completed[key] then return false end
        if V984Pacing.Key ~= key then
            V984Pacing.Key = key
            V984Pacing.StartedAt = os.clock()
        end
        local remaining = delay - (os.clock() - V984Pacing.StartedAt)
        if remaining > 0 then
            V984Pacing.Status = string.format("Waiting before final Titan: %ds", math.ceil(remaining))
            statusText = V984Pacing.Status
            return true
        end
        V984Pacing.Completed[key] = true
        V984Pacing.Status = "Final Titan delay complete"
        return false
    elseif alive > 1 then
        V984Pacing.Completed["MISSION_LAST_TITAN"] = nil
        if V984Pacing.Key == "MISSION_LAST_TITAN" then
            V984Pacing.Key = ""
            V984Pacing.StartedAt = 0
        end
    end
    return false
end

function V35Spears.Step()
    if V984Pacing and V984Pacing.ShouldPauseFinish and V984Pacing.ShouldPauseFinish() then
        V35Spears.LastStatus = V984Pacing.Status
        return false, 0
    end

    if not V35Spears.ShouldRun() then
        return false, 0
    end

    if V91RaidBossGuard and V91RaidBossGuard.Blocked and V91RaidBossGuard.Blocked() then
        V35Spears.LastStatus = "Attack boss roar invulnerability"
        return false, 0
    end

    if V35Spears.Busy then
        return false, V35Spears.LastPack or 0
    end

    local center, packCount, mode, exactTitan = V56SpearDirector.Target()

    if not SliceHubIsPremium() then
        local freeCap = math.max(1, math.floor(tonumber(PROFILE.Spears.KillCap) or 6))
        packCount = math.min(math.max(0, tonumber(packCount) or 0), freeCap)
    end

    if not center or packCount <= 0 then
        V35Spears.LastStatus = mode == "CANNON HOLD"
            and "Colossal P1 cannon ownership"
            or ("Director " .. tostring(mode) .. " waiting for target")
        return false, 0
    end

    if mode == "PACK SWEEP"
        and State.BladesEnabled == true
        and packCount <= 1
        and State.SpearInfiniteEnabled ~= true then
        V35Spears.LastStatus = "Single survivor yielded to blades"
        return false, packCount
    end

    if mode == "BOSS BURST" then
        V56SpearDirector.BossShots += 1
        V35Spears.LastStatus = "BOSS BURST • live weak point • shot " .. tostring(V56SpearDirector.BossShots)
    elseif mode == "SURVIVOR HUNT" then
        V35Spears.LastStatus = "SURVIVOR HUNT • exact nape • " .. tostring(exactTitan and exactTitan.Name or "rescan")
    elseif mode == "OBJECTIVE DEFENSE" then
        V56SpearDirector.DefenseShots += 1
        V35Spears.LastStatus = "DEFENSE BARRAGE • active pack"
    else
        V56SpearDirector.PackShots += 1
        if SliceHubIsPremium() then
            V35Spears.LastStatus = "ADVANCED PACK SWEEP"
        else
            V35Spears.LastStatus = "BASIC PACK TARGET"
        end
    end

    V56SpearDirector.FastTravel(center, mode)

    local burstTargets, burstLabel, plannedCount = V9RaidCombat.BuildSpearBurstTargets(
        mode,
        exactTitan,
        center
    )

    if tonumber(plannedCount) and tonumber(plannedCount) > 0 then
        packCount = tonumber(plannedCount)
    end

    local fired = V35Spears.FireDirect(
        center,
        packCount,
        burstTargets,
        burstLabel
    )
    if fired == true and mode == "SURVIVOR HUNT" then
        V56SpearDirector.SurvivorTarget = exactTitan or V56SpearDirector.SurvivorTarget
        V56SpearDirector.SurvivorShots += 1
        V56SpearDirector.SurvivorLastShotAt = os.clock()
        V56SpearDirector.SurvivorLastHealth = V56SpearDirector.TitanHealth(V56SpearDirector.SurvivorTarget)
        V56SpearDirector.SurvivorLastAlive = V35Spears.GlobalAliveCount()
    end
    return fired == true, packCount
end

function V35Spears.Telemetry()
    local ammo = V35Spears.ReadAmmo()
    local weapon = player and tostring(player:GetAttribute("Weapon") or "Unknown") or "Unknown"
    local pack = V35Spears.LastPack or 0

    return {
        Weapon = weapon,
        Ammo = ammo,
        Pack = pack,
        Busy = V35Spears.Busy,
        Shots = V35Spears.Shots,
        LastKills = V36PackDrain.LastKills or 0,
        ObservedCap = V36PackDrain.ObservedKillCap or 3,
        Status = V35Spears.LastStatus,
    }
end


V35Spears.Refill = V35Spears.Refill or {
    LowSince = nil,
    Armed = true,
    LastAmmo = nil,
    LastAttemptAt = 0,
    MaxObserved = 0,
}

function V35Spears.RefillStep()
    -- V5.6 hybrid policy: Infinite Spears is a zero-ammo firing fallback, not a
    -- replacement for refill. Refill stays active so real ammo can restore
    -- Titan Blaster availability; if refill fails, basic infinite fire resumes.
    if not State.SpearAutoRefillEnabled then
        V35Spears.Refill.LowSince = nil
        return
    end

    if not V35Spears.IsEquipped() then
        V35Spears.Refill.LowSince = nil
        return
    end

    if StationRefill.Running or V35Spears.Busy then
        return
    end

    local ammo = V35Spears.ReadAmmo()
    V35Spears.Refill.LastAmmo = ammo

    if ammo == nil then
        V35Spears.Refill.LowSince = nil
        return
    end

    local exactCapacity = V35Spears.ReadCapacity()

    if ammo > 1 then
        V35Spears.Refill.MaxObserved = math.max(
            tonumber(V35Spears.Refill.MaxObserved) or 0,
            tonumber(exactCapacity) or 0,
            ammo
        )

        V35Spears.Refill.LowSince = nil
        V35Spears.Refill.Armed = true
        return
    end

    -- V3.6.1 safety trigger:
    -- preserve the final spear and start refill before the 0-ammo state can drop the character.
    if ammo > 1 or not V35Spears.Refill.Armed then
        return
    end

    V35Spears.Refill.LowSince =
        V35Spears.Refill.LowSince or os.clock()

    if os.clock() - V35Spears.Refill.LowSince < 0.10 then
        return
    end

    local verifyAmmo = V35Spears.ReadAmmo()

    if verifyAmmo == nil or verifyAmmo > 1 then
        V35Spears.Refill.LowSince = nil
        return
    end

    V35Spears.Refill.Armed = false
    V35Spears.Refill.LowSince = nil
    V35Spears.Refill.LastAttemptAt = os.clock()

    local target = math.clamp(
        math.floor(
            (
                tonumber(V35Spears.ReadCapacity())
                or tonumber(V35Spears.Refill.MaxObserved)
                or 8
            )
            + 0.5
        ),
        1,
        30
    )

    V35Spears.LastStatus =
        "Safety refill " .. tostring(verifyAmmo) .. " → " .. tostring(target)

    print(
        "[SliceHub V3.6.1][TS-REFILL]",
        "safety trigger ammo=" .. tostring(verifyAmmo),
        "target=" .. tostring(target)
    )

    beginStationRefill(
        "spears safety " .. tostring(verifyAmmo) .. " -> " .. tostring(target),
        false,
        "Spears",
        target
    )
end

task.spawn(function()
    while true do
        task.wait(0.05)
        pcall(V35Spears.RefillStep)
    end
end)

V58BladeEngine = V58BladeEngine or {
    Version = "6.0.0",
    Mode = "PACK SWEEP",
    Status = "Booting V6 Exact Blade Queue",
    LastModeAt = 0,
    LastWaveSize = 0,
    LastCleanupDamaged = 0,
    SurvivorTarget = nil,
    SurvivorPart = nil,
    SurvivorPartIndex = 1,
    SurvivorNoProgress = 0,
    SurvivorRotations = 0,
    SurvivorLastHealth = nil,
    SurvivorLastAlive = nil,
    SurvivorBlacklist = setmetatable({}, {__mode = "k"}),
    HybridBurstRequested = false,
    HybridBurstActive = false,
    HybridStatus = "Idle",

    Phase = "READY",
    PhaseDetail = "boot",
    NextActionAt = 0,
    BurstSerial = 0,
    LastBurst = {
        Requested = 0,
        Registered = 0,
        Kills = 0,
        Damaged = 0,
        Duration = 0,
        Mode = "PACK SWEEP",
        Source = "BLADE",
    },
    LastBurstAt = 0,
    LastTelemetryPrintAt = 0,
    LastBlasterName = "None",
    LastBlasterKills = 0,
    LastBlasterPack = 0,
    LastBlasterAt = 0,
}

function V58BladeEngine.AllowedTitan(titan)
    return titan
        and titan.Parent
        and isTitanAlive(titan)
        and (
            not V4RaidDirector
            or not V4RaidDirector.AllowTitanTarget
            or V4RaidDirector.AllowTitanTarget(titan)
        )
end

function V58BladeEngine.HealthInfo(titan)
    if not titan or not titan.Parent then return nil, nil, nil end
    local humanoid = titan:FindFirstChildOfClass("Humanoid")
    if not humanoid then return nil, nil, nil end
    local health = tonumber(humanoid.Health)
    local maximum = tonumber(humanoid.MaxHealth)
    local ratio = health and maximum and maximum > 0 and (health / maximum) or 1
    return health, maximum, ratio
end

function V58BladeEngine.SetPhase(phase, detail, nextActionAt)
    V58BladeEngine.Phase = tostring(phase or "READY")
    V58BladeEngine.PhaseDetail = tostring(detail or "")
    V58BladeEngine.NextActionAt = tonumber(nextActionAt) or 0
end

function V58BladeEngine.BeginBurstSnapshot(targets, mode, source)
    local snapshot = {
        StartedAt = os.clock(),
        Requested = #(targets or {}),
        Mode = tostring(mode or V58BladeEngine.Mode or "PACK SWEEP"),
        Source = tostring(source or "BLADE"),
        Before = {},
    }

    for _, titan in ipairs(targets or {}) do
        if titan then
            local health = select(1, V58BladeEngine.HealthInfo(titan))
            snapshot.Before[titan] = health
        end
    end

    V58BladeEngine.BurstSerial += 1
    V58BladeEngine.SetPhase(
        "BURST_ACTIVE",
        string.format("%s %d targets", snapshot.Source, snapshot.Requested),
        0
    )

    return snapshot
end

function V58BladeEngine.FinishBurstSnapshot(snapshot)
    snapshot = type(snapshot) == "table" and snapshot or {}
    local kills, damaged, registered = 0, 0, 0

    for titan, healthBefore in pairs(snapshot.Before or {}) do
        local dead = not titan or not titan.Parent or not isTitanAlive(titan)
        local healthAfter = titan and select(1, V58BladeEngine.HealthInfo(titan)) or nil
        local healthDrop =
            healthBefore ~= nil
            and healthAfter ~= nil
            and healthAfter < healthBefore - (tonumber(Config.HealthProgressEpsilon) or 0.01)

        if dead then
            kills += 1
            registered += 1
        elseif healthDrop then
            damaged += 1
            registered += 1
        end
    end

    local result = {
        Requested = tonumber(snapshot.Requested) or 0,
        Registered = registered,
        Kills = kills,
        Damaged = damaged,
        Duration = math.max(0, os.clock() - (tonumber(snapshot.StartedAt) or os.clock())),
        Mode = tostring(snapshot.Mode or V58BladeEngine.Mode or "PACK SWEEP"),
        Source = tostring(snapshot.Source or "BLADE"),
    }

    V58BladeEngine.LastBurst = result
    V58BladeEngine.LastBurstAt = os.clock()

    local now = os.clock()
    local printDelay = math.max(0.10, tonumber(Config.BladeV31TelemetryPrintDelay) or 0.35)
    if result.Registered > 0 or now - (tonumber(V58BladeEngine.LastTelemetryPrintAt) or 0) >= printDelay then
        V58BladeEngine.LastTelemetryPrintAt = now
        print(
            "[SliceHub V6.0.0][BLADE-BURST]",
            "source=" .. result.Source,
            "mode=" .. result.Mode,
            "requested=" .. tostring(result.Requested),
            "registered=" .. tostring(result.Registered),
            "kills=" .. tostring(result.Kills),
            "damaged=" .. tostring(result.Damaged),
            "duration=" .. string.format("%.2fs", result.Duration)
        )
    end

    return result
end

function V58BladeEngine.BurstSummary()
    local burst = V58BladeEngine.LastBurst or {}
    return string.format(
        "%s %d→%d reg • K%d D%d • %.2fs",
        tostring(burst.Source or "BLADE"),
        tonumber(burst.Requested) or 0,
        tonumber(burst.Registered) or 0,
        tonumber(burst.Kills) or 0,
        tonumber(burst.Damaged) or 0,
        tonumber(burst.Duration) or 0
    )
end

function V58BladeEngine.ReturnToSafeLane(reason)
    if Config.BladeV31SafeReturnEnabled ~= true then return false end
    if V577MovementAuthority and not V577MovementAuthority.CanMove("NORMAL") then return false end
    if not State or State.FarmEnabled ~= true then return false end
    if not character or not character.Parent or not rootPart or not rootPart.Parent then return false end

    local base = CombatAnchorRuntime and CombatAnchorRuntime.Position or nil
    local aim = CombatAnchorRuntime and CombatAnchorRuntime.AimPosition or nil
    if typeof(base) ~= "Vector3" then return false end

    local extra = math.max(0, tonumber(Config.BladeV31SafeReturnHeight) or 42)
    local safe = base + Vector3.new(0, extra, 0)
    aim = typeof(aim) == "Vector3" and aim or safe + Vector3.new(0, -1, 0)

    pcall(function()
        character:PivotTo(CFrame.lookAt(safe, aim))
        rootPart.AssemblyLinearVelocity = Vector3.zero
        rootPart.AssemblyAngularVelocity = Vector3.zero
    end)

    local now = os.clock()
    CombatSafetyBoostUntil = math.max(
        tonumber(CombatSafetyBoostUntil) or 0,
        now + math.max(0.05, tonumber(Config.BladeV31SafeReturnHold) or 0.24)
    )
    CombatSafetyBoostHeight = math.max(
        tonumber(CombatSafetyBoostHeight) or 0,
        extra
    )

    if reason then
        V58BladeEngine.PhaseDetail = tostring(reason)
    end

    return true
end

function V58BladeEngine.ResolveMode(aliveCount)
    aliveCount = tonumber(aliveCount) or getCachedAliveTitanCount()
    local mode = "PACK SWEEP"

    if V4RaidDirector and V4RaidDirector.HardBossLock then
        local bossTitan, bossPart = V4RaidDirector.HardBossLock()
        if bossTitan and bossPart then mode = "BOSS PRESSURE" end
    end

    if mode ~= "BOSS PRESSURE"
        and aliveCount <= math.max(1, tonumber(Config.FinisherTitanCount) or 5) then
        mode = "SURVIVOR HUNT"
    elseif mode ~= "BOSS PRESSURE"
        and V35Spears
        and V35Spears.ShouldRun
        and V35Spears.ShouldRun() then
        mode = "PACK CLEANUP"
    end

    if V58BladeEngine.Mode ~= mode then
        V58BladeEngine.Mode = mode
        V58BladeEngine.LastModeAt = os.clock()
    end

    return mode
end

function V58BladeEngine.SurvivorBlacklisted(titan)
    local expiry = V58BladeEngine.SurvivorBlacklist[titan]
    if not expiry then return false end
    if os.clock() >= expiry then
        V58BladeEngine.SurvivorBlacklist[titan] = nil
        return false
    end
    return true
end

function V58BladeEngine.ResetSurvivor(reason, keepBlacklist)
    V58BladeEngine.SurvivorTarget = nil
    V58BladeEngine.SurvivorPart = nil
    V58BladeEngine.SurvivorPartIndex = 1
    V58BladeEngine.SurvivorNoProgress = 0
    V58BladeEngine.SurvivorRotations = 0
    V58BladeEngine.SurvivorLastHealth = nil
    V58BladeEngine.SurvivorLastAlive = nil
    if keepBlacklist ~= true then
        V58BladeEngine.SurvivorBlacklist = setmetatable({}, {__mode = "k"})
    end
    if reason then V58BladeEngine.Status = tostring(reason) end
end

function V58BladeEngine.ResolveStrikePart(titan)
    if not titan or not titan.Parent then return nil end
    local order = {"Nape", "UpperTorso", "HumanoidRootPart", "Torso", "Head", "LowerTorso"}
    local startIndex = math.clamp(
        math.floor(tonumber(V58BladeEngine.SurvivorPartIndex) or 1),
        1,
        #order
    )

    for offset = 0, #order - 1 do
        local index = ((startIndex + offset - 1) % #order) + 1
        local part = titan:FindFirstChild(order[index], true)
        if part and part:IsA("BasePart") and part.Parent then
            V58BladeEngine.SurvivorPartIndex = index
            return part
        end
    end

    return getTitanTargetPart(titan)
end

function V58BladeEngine.AdvanceStrikePart()
    local partCount = 6
    V58BladeEngine.SurvivorPartIndex =
        ((math.floor(tonumber(V58BladeEngine.SurvivorPartIndex) or 1)) % partCount) + 1
end

function V58BladeEngine.PickSurvivor()
    local current = V58BladeEngine.SurvivorTarget
    if V58BladeEngine.AllowedTitan(current)
        and not V58BladeEngine.SurvivorBlacklisted(current) then
        local part = V58BladeEngine.ResolveStrikePart(current)
        if part and part.Parent then
            V58BladeEngine.SurvivorPart = part
            return current, part
        end
    end

    local titansFolder = Workspace:FindFirstChild(Config.TitansFolderName)
    if not titansFolder then return nil, nil end

    local origin = rootPart and rootPart.Position or Vector3.zero
    local candidates = {}

    local function collect(ignoreBlacklist)
        table.clear(candidates)
        for _, titan in ipairs(titansFolder:GetChildren()) do
            if V58BladeEngine.AllowedTitan(titan)
                and (ignoreBlacklist or not V58BladeEngine.SurvivorBlacklisted(titan)) then
                local part = V58BladeEngine.ResolveStrikePart(titan)
                if part and part.Parent then
                    local health = select(1, V58BladeEngine.HealthInfo(titan)) or math.huge
                    candidates[#candidates + 1] = {
                        Titan = titan,
                        Part = part,
                        Health = health,
                        Distance = (part.Position - origin).Magnitude,
                    }
                end
            end
        end
    end

    collect(false)
    if #candidates == 0 then
        V58BladeEngine.SurvivorBlacklist = setmetatable({}, {__mode = "k"})
        collect(true)
    end

    table.sort(candidates, function(a, b)
        if a.Health ~= b.Health then return a.Health < b.Health end
        return a.Distance < b.Distance
    end)

    local chosen = candidates[1]
    if not chosen then
        V58BladeEngine.ResetSurvivor("SURVIVOR HUNT • no live target", true)
        return nil, nil
    end

    V58BladeEngine.SurvivorTarget = chosen.Titan
    V58BladeEngine.SurvivorPart = chosen.Part
    V58BladeEngine.SurvivorPartIndex = 1
    V58BladeEngine.SurvivorNoProgress = 0
    V58BladeEngine.SurvivorRotations = 0
    V58BladeEngine.SurvivorLastHealth = chosen.Health
    V58BladeEngine.SurvivorLastAlive = getCachedAliveTitanCount()
    V58BladeEngine.Status = "SURVIVOR HUNT • " .. tostring(chosen.Titan.Name)
    return chosen.Titan, chosen.Part
end

function V58BladeEngine.BuildCleanupWave(limit, current)
    limit = math.max(1, math.floor(tonumber(limit) or 1))
    local scanLimit = math.max(limit, math.floor(tonumber(Config.BladeV3CleanupScanLimit) or 40))
    local candidates = findClosestTitans(scanLimit)
    local damaged = {}
    local threshold = math.clamp(tonumber(Config.BladeV3CleanupHealthRatio) or 0.985, 0.05, 1)

    for _, entry in ipairs(candidates or {}) do
        local titan = entry.Titan
        if V58BladeEngine.AllowedTitan(titan) then
            local health, _, ratio = V58BladeEngine.HealthInfo(titan)
            if health and ratio and ratio < threshold then
                damaged[#damaged + 1] = {
                    Titan = titan,
                    Ratio = ratio,
                    Health = health,
                    DistanceSquared = tonumber(entry.DistanceSquared) or math.huge,
                    Score = tonumber(entry.KillScore) or math.huge,
                }
            end
        end
    end

    table.sort(damaged, function(a, b)
        if a.Ratio ~= b.Ratio then return a.Ratio < b.Ratio end
        if a.Health ~= b.Health then return a.Health < b.Health end
        if a.Score ~= b.Score then return a.Score < b.Score end
        return a.DistanceSquared < b.DistanceSquared
    end)

    local result, seen = {}, {}
    local cleanupCap = math.min(
        limit,
        math.max(1, math.floor(tonumber(Config.BladeV3CleanupMaxTargets) or SliceHubMissionTPSMax()))
    )

    for _, entry in ipairs(damaged) do
        if #result >= cleanupCap then break end
        if entry.Titan and not seen[entry.Titan] and isTitanAlive(entry.Titan) then
            seen[entry.Titan] = true
            result[#result + 1] = entry.Titan
        end
    end

    if #result < limit then
        local fallback = V52KillingEngine.BuildBladeWave(limit, current)
        for _, titan in ipairs(fallback) do
            if #result >= limit then break end
            if titan and not seen[titan] and isTitanAlive(titan) then
                seen[titan] = true
                result[#result + 1] = titan
            end
        end
    end

    V58BladeEngine.LastCleanupDamaged = #damaged
    V58BladeEngine.LastWaveSize = #result
    V58BladeEngine.Status = string.format(
        "PACK CLEANUP • damaged %d • wave %d",
        #damaged,
        #result
    )
    return result
end

function V58BladeEngine.BuildWave(limit, current)
    local aliveCount = getCachedAliveTitanCount()
    local mode = V58BladeEngine.ResolveMode(aliveCount)

    if mode == "BOSS PRESSURE" and V4RaidDirector and V4RaidDirector.HardBossLock then
        local bossTitan, bossPart = V4RaidDirector.HardBossLock()
        if bossTitan and bossPart then
            V58BladeEngine.Status = "BOSS PRESSURE • " .. tostring(bossTitan.Name)
            V58BladeEngine.LastWaveSize = 1
            return {bossTitan}
        end
    end

    if mode == "SURVIVOR HUNT" then
        local titan, part = V58BladeEngine.PickSurvivor()
        if titan and part then
            currentTarget = titan
            currentTargetPart = part
            currentTargetHealth = select(1, V58BladeEngine.HealthInfo(titan))
            targetLastProgressTime = os.clock()
            V58BladeEngine.LastWaveSize = 1
            return {titan}
        end
        return {}
    end

    if mode == "PACK CLEANUP" then
        return V58BladeEngine.BuildCleanupWave(limit, current)
    end

    local wave = V52KillingEngine.BuildBladeWave(limit, current)
    V58BladeEngine.LastWaveSize = #wave
    V58BladeEngine.Status = "PACK SWEEP • wave " .. tostring(#wave)
    return wave
end

function V58BladeEngine.AimPartForTitan(titan)
    if V58BladeEngine.Mode == "SURVIVOR HUNT"
        and titan == V58BladeEngine.SurvivorTarget then
        local part = V58BladeEngine.ResolveStrikePart(titan)
        if part and part.Parent then
            V58BladeEngine.SurvivorPart = part
            return part
        end
    end
    return getTitanTargetPart(titan)
end

function V58BladeEngine.RecordSurvivorBurst(titan, healthBefore, aliveBefore, madeProgress)
    if V58BladeEngine.Mode ~= "SURVIVOR HUNT" or not titan then return end

    local healthAfter = select(1, V58BladeEngine.HealthInfo(titan))
    local aliveAfter = getCachedAliveTitanCount()
    local dead = not V58BladeEngine.AllowedTitan(titan)
    local healthProgress = healthBefore and healthAfter and healthAfter < healthBefore - Config.HealthProgressEpsilon
    local aliveProgress = tonumber(aliveBefore) and aliveAfter < tonumber(aliveBefore)

    if dead or healthProgress or aliveProgress or madeProgress == true then
        V58BladeEngine.SurvivorNoProgress = 0
        V58BladeEngine.SurvivorLastHealth = healthAfter
        V58BladeEngine.SurvivorLastAlive = aliveAfter
        if dead then
            V58BladeEngine.ResetSurvivor("SURVIVOR HUNT • kill confirmed", true)
        else
            V58BladeEngine.Status = "SURVIVOR HUNT • progress confirmed"
        end
        return
    end

    V58BladeEngine.SurvivorNoProgress += 1
    local attempts = math.max(1, math.floor(tonumber(Config.BladeV3SurvivorPartAttempts) or 1))
    if V58BladeEngine.SurvivorNoProgress < attempts then return end

    V58BladeEngine.SurvivorNoProgress = 0
    V58BladeEngine.AdvanceStrikePart()
    V58BladeEngine.SurvivorRotations += 1
    V58BladeEngine.SurvivorPart = V58BladeEngine.ResolveStrikePart(titan)
    V58BladeEngine.Status = string.format(
        "SURVIVOR HUNT • no progress • part %d/6",
        tonumber(V58BladeEngine.SurvivorPartIndex) or 1
    )

    local rotationLimit = math.max(2, math.floor(tonumber(Config.BladeV3SurvivorMaxRotations) or 6))
    if V58BladeEngine.SurvivorRotations >= rotationLimit then
        V58BladeEngine.SurvivorBlacklist[titan] =
            os.clock() + math.max(0.2, tonumber(Config.BladeV3SurvivorBlacklistTime) or 0.8)
        V58BladeEngine.ResetSurvivor("SURVIVOR HUNT • rotating stale Titan", true)
    end
end

function V58BladeEngine.CanFillSpearGap(spearTriggered)
    if Config.BladeV3Enabled ~= true or Config.BladeV3HybridEnabled ~= true then return false end
    if spearTriggered == true then
        V58BladeEngine.HybridStatus = "Spear shot owns frame"
        return false
    end
    if not State or State.BladesEnabled ~= true then return false end
    if not V35Spears or not V35Spears.ShouldRun or not V35Spears.ShouldRun() then return false end
    if V35Spears.Busy or bladeBurstRunning or refillSequenceRunning or ripperSequenceRunning then return false end
    if V577MovementAuthority and not V577MovementAuthority.CanMove("NORMAL") then return false end

    local now = os.clock()
    local readyAt = tonumber(V35Spears.NextFireAt) or 0
    local gap = readyAt - now
    if gap <= 0 then
        V58BladeEngine.HybridStatus = "Spear ready now"
        return false
    end
    if gap < math.max(0.08, tonumber(Config.BladeV3HybridMinWindow) or 0.145) then
        V58BladeEngine.HybridStatus = "Gap too short"
        return false
    end

    local shotAge = now - (tonumber(V35Spears.LastShotAt) or 0)
    if V35Spears.LastShotAt and V35Spears.LastShotAt > 0
        and shotAge < math.max(0.02, tonumber(Config.BladeV3HybridPostSpearSettle) or 0.055) then
        V58BladeEngine.HybridStatus = "Post-spear settle"
        return false
    end

    V58BladeEngine.HybridStatus = string.format("Blade gap %.3fs", gap)
    return true
end

local function getBladeAttackTargets()
    -- V5.7.6 Glass Cannon profile remains authoritative: Colossal P2 is remote-pressure
    -- only, so V5.8 never allows a blade dive to break the safe lane.
    if V4RaidDirector
        and V4RaidDirector.RaidName == "Colossal Raid"
        and V55ColossalDirector
        and V55ColossalDirector.Stage == "P2 BOSS"
        and V55ColossalDirector.IsGlassCannonProfile
        and V55ColossalDirector.IsGlassCannonProfile() then
        return {}
    end

    if Config.BladeV3Enabled == true then
        return V58BladeEngine.BuildWave(getEffectiveTitansPerHit(), currentTarget)
    end

    return V52KillingEngine.BuildBladeWave(getEffectiveTitansPerHit(), currentTarget)
end

function clearCurrentTarget(blacklist)
	if blacklist and currentTarget then
		targetBlacklistedUntil[currentTarget] = os.clock() + Config.TargetBlacklistTime
	end
	currentTarget = nil
	currentTargetPart = nil
	currentTargetHealth = nil
	targetLastProgressTime = 0
end

local function acquireCurrentTarget()
    if V4RaidDirector and V4RaidDirector.HardBossLock then
        local bossTitan, bossPart = V4RaidDirector.HardBossLock()
        if bossTitan and bossPart then
            targetBlacklistedUntil[bossTitan] = nil
            local bossHumanoid = bossTitan:FindFirstChildOfClass("Humanoid")
            currentTarget = bossTitan
            currentTargetPart = bossPart
            currentTargetHealth = bossHumanoid and bossHumanoid.Health or nil
            targetLastProgressTime = os.clock()
            return true
        end
    end

    local aliveCount = getCachedAliveTitanCount()
    local finisherThreshold = math.max(1, tonumber(Config.FinisherTitanCount) or 5)

    local titan, targetPart
    if aliveCount <= finisherThreshold then
        titan, targetPart = findClosestAliveTitanIgnoringBlacklist()
    else
        titan, targetPart = findClosestTitan()
    end

    if not titan or not targetPart then
        return false
    end

    -- Last-Titan cleanup owns the target directly.
    if aliveCount <= finisherThreshold then
        targetBlacklistedUntil[titan] = nil
    end

    local titanHumanoid = titan:FindFirstChildOfClass("Humanoid")
    currentTarget = titan
    currentTargetPart = targetPart
    currentTargetHealth = titanHumanoid and titanHumanoid.Health or nil
    targetLastProgressTime = os.clock()
    return true
end

local function updateAndValidateCurrentTarget()
    if currentTarget
        and V4RaidDirector
        and V4RaidDirector.AllowTitanTarget
        and not V4RaidDirector.AllowTitanTarget(currentTarget) then
        clearCurrentTarget(false)
        return false, "raid-phase-filter"
    end

	if V4RaidDirector and V4RaidDirector.HardBossLock then
		local bossTitan = select(1, V4RaidDirector.HardBossLock())
		if bossTitan and currentTarget ~= bossTitan then
			clearCurrentTarget(false)
			return false, "boss-switch"
		end
	end

	if not currentTarget or not currentTargetPart then return false, "missing" end
	if isTitanBlacklisted(currentTarget) or not isTitanAlive(currentTarget) then
		clearCurrentTarget(false)
		return false, "dead"
	end
	if not currentTargetPart.Parent then
		clearCurrentTarget(false)
		return false, "missing"
	end

	local titanHumanoid = currentTarget:FindFirstChildOfClass("Humanoid")
	if not titanHumanoid then
		clearCurrentTarget(true)
		return false, "invalid"
	end

	local now = os.clock()
	local health = titanHumanoid.Health
	if currentTargetHealth == nil or health < currentTargetHealth - Config.HealthProgressEpsilon then
		currentTargetHealth = health
		targetLastProgressTime = now
	elseif health > currentTargetHealth + Config.HealthProgressEpsilon then
		-- Some Titans regenerate. Track the new value without counting it as attack progress.
		currentTargetHealth = health
	end

	if now - targetLastProgressTime >= Config.TargetStallTimeout then
		local hardBoss = V4RaidDirector
			and V4RaidDirector.HardBossLock
			and select(1, V4RaidDirector.HardBossLock())

		if hardBoss and currentTarget == hardBoss then
			-- Boss health can remain flat while a raid shield/objective value is draining.
			-- Never blacklist or rotate away from the live P2 boss.
			targetLastProgressTime = now
			return true, nil
		end

		local stalledName = currentTarget.Name
		clearCurrentTarget(true)
		return false, stalledName
	end

	return true, nil
end

V577MovementAuthority = V577MovementAuthority or {
    LastMode = "NORMAL",
}

function V577MovementAuthority.Mode()
    if WavesRuntimeDirector and WavesRuntimeDirector.Busy == true then
        V577MovementAuthority.LastMode = "WAVE_CRATE"
        return "WAVE_CRATE"
    end
    if V55ColossalDirector and V55ColossalDirector.EvadeMode == true then
        V577MovementAuthority.LastMode = "EVADE"
        return "EVADE"
    end
    if V55ColossalDirector and V4RaidDirector
        and V4RaidDirector.RaidName == "Colossal Raid"
        and V55ColossalDirector.Stage == "P1 CANNON STALL"
        and (
            V55ColossalDirector.Entered == true
            or V55ColossalDirector.DismountPending == true
            or V55ColossalDirector.RemountPending == true
        ) then
        V577MovementAuthority.LastMode = "CANNON"
        return "CANNON"
    end
    if StationRefill and StationRefill.Running then
        V577MovementAuthority.LastMode = "REFILL"
        return "REFILL"
    end
    V577MovementAuthority.LastMode = "NORMAL"
    return "NORMAL"
end

function V577MovementAuthority.CanMove(requester)
    local mode = V577MovementAuthority.Mode()
    requester = tostring(requester or "NORMAL")
    return mode == "NORMAL" or mode == requester
end

function releaseCombatLock()
	clearCurrentTarget(false)
	speedPulseForward = false
	CombatAnchorRuntime.Position = nil
	CombatAnchorRuntime.GroundCenter = nil
	CombatAnchorRuntime.AimPosition = nil
	CombatAnchorRuntime.TargetCount = 0
	CombatAnchorRuntime.PulseUntil = 0
	CombatAnchorRuntime.PulseSerial += 1
	State.IsGrabbed = false

	local function pushDown()
		if State.FarmEnabled then return end
		if rootPart and rootPart.Parent then
			rootPart.Anchored = false
			rootPart.AssemblyAngularVelocity = Vector3.zero
			rootPart.AssemblyLinearVelocity = Vector3.new(0, -Config.DropSpeed, 0)
		end
	end

	if humanoid and humanoid.Health > 0 then
		humanoid.PlatformStand = false
		humanoid.Sit = false
		humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
	end

	-- Apply the drop immediately, then once more after other game scripts have had a frame to react.
	pushDown()
	task.delay(0.12, pushDown)
end

-- DEV14 anchor hysteresis: keep the player over one useful cluster until that cluster is actually depleted.
local function countAliveTitansNearPosition(center, radius)
	if typeof(center) ~= "Vector3" then return 0 end
	local titansFolder = Workspace:FindFirstChild(Config.TitansFolderName)
	if not titansFolder then return 0 end
	radius = math.max(1, tonumber(radius) or 360)
	local radiusSquared = radius * radius
	local count = 0

	for _, titan in ipairs(titansFolder:GetChildren()) do
		if isTitanAlive(titan) and not isTitanBlacklisted(titan) then
			local part = getTitanTargetPart(titan)
			if part and part.Parent then
				local delta = part.Position - center
				if delta:Dot(delta) <= radiusSquared then
					count += 1
				end
			end
		end
	end

	return count
end

local function currentCombatSkyHeight()
    if State
        and State.SpearSupportEnabled == true
        and V35Spears
        and V35Spears.IsEquipped
        and V35Spears.IsEquipped() then
        return tonumber(Config.SpearSkyHeight) or 430
    end

    return tonumber(Config.SkyHeight) or 300
end

-- DEV14 stable cluster anchor: movement anchor is separated from the tracked damage target.
function refreshCombatAnchor(force)
    if not Config.CombatAnchorEnabled then return nil, nil, 0 end
    local now = os.clock()

    if V4RaidDirector and V4RaidDirector.HardBossLock then
        local bossTitan, bossPart = V4RaidDirector.HardBossLock()
        if bossTitan and bossPart then
            local center = bossPart.Position
            CombatAnchorRuntime.Position =
                center + Vector3.new(0, currentCombatSkyHeight(), 0)
            CombatAnchorRuntime.GroundCenter = center
            CombatAnchorRuntime.AimPosition = center
            CombatAnchorRuntime.TargetCount = 1
            CombatAnchorRuntime.InitialResidents = 1
            CombatAnchorRuntime.LastRefresh = now
            CombatAnchorRuntime.LastCommit = now
            return CombatAnchorRuntime.Position, center, 1
        end
    end

    local aliveCount = getCachedAliveTitanCount()
    local finisherThreshold = math.max(1, tonumber(Config.FinisherTitanCount) or 5)
    if aliveCount <= finisherThreshold and currentTargetPart and currentTargetPart.Parent then
        local center = currentTargetPart.Position
        local finisherHeight = currentCombatSkyHeight()
        if not (State.SpearSupportEnabled and V35Spears and V35Spears.IsEquipped and V35Spears.IsEquipped()) then
            finisherHeight = tonumber(Config.FinisherSkyHeight) or 175
        end
        CombatAnchorRuntime.Position = center + Vector3.new(0, finisherHeight, 0)
        CombatAnchorRuntime.GroundCenter = center
        CombatAnchorRuntime.AimPosition = center
        CombatAnchorRuntime.TargetCount = aliveCount
        CombatAnchorRuntime.InitialResidents = aliveCount
        CombatAnchorRuntime.LastRefresh = now
        CombatAnchorRuntime.LastCommit = now
        return CombatAnchorRuntime.Position, CombatAnchorRuntime.AimPosition, aliveCount
    end
	local refreshDelay = math.max(0.05, tonumber(Config.CombatAnchorRefreshDelay) or 0.20)
	if not force and CombatAnchorRuntime.Position and now - CombatAnchorRuntime.LastRefresh < refreshDelay then
		return CombatAnchorRuntime.Position, CombatAnchorRuntime.AimPosition, CombatAnchorRuntime.TargetCount
	end

	CombatAnchorRuntime.LastRefresh = now
	local center, aimPart, count = getBestTitanCluster(Config.CombatAnchorClusterRadius, Config.CombatAnchorScanLimit)
	if not center then
		return CombatAnchorRuntime.Position, CombatAnchorRuntime.AimPosition, CombatAnchorRuntime.TargetCount
	end

	local candidatePosition = center + Vector3.new(0, currentCombatSkyHeight(), 0)
	local commit = force == true or CombatAnchorRuntime.Position == nil
	if not commit then
		local moved = (candidatePosition - CombatAnchorRuntime.Position).Magnitude
		local residents = countAliveTitansNearPosition(
			CombatAnchorRuntime.GroundCenter,
			Config.CombatAnchorReleaseRadius
		)
        local minimumResidents = math.max(1, math.floor(tonumber(Config.CombatAnchorMinResidents) or 3))
        local initialResidents = math.max(
            minimumResidents,
            tonumber(CombatAnchorRuntime.InitialResidents) or residents
        )
        local retentionThreshold = math.max(
            minimumResidents,
            math.ceil(initialResidents * (tonumber(Config.CombatAnchorRetentionRatio) or 0.35))
        )
        local betterClusterGain = math.max(1, math.floor(tonumber(Config.CombatAnchorBetterClusterGain) or 5))
        local emergencyDistance = math.max(
            math.max(8, tonumber(Config.CombatAnchorMoveThreshold) or 140),
            tonumber(Config.CombatAnchorEmergencyMoveDistance) or 520
        )

        local depleted = residents < retentionThreshold
        local clearlyBetter = count >= residents + betterClusterGain
            and moved >= math.max(8, tonumber(Config.CombatAnchorMoveThreshold) or 140)

        commit = depleted or clearlyBetter or moved >= emergencyDistance
    end

    if commit then
        CombatAnchorRuntime.Position = candidatePosition
        CombatAnchorRuntime.GroundCenter = center
        CombatAnchorRuntime.InitialResidents = count
        CombatAnchorRuntime.LastCommit = now
    end

	-- Aim may update while position stays fixed; this rotates toward action without lateral teleport jitter.
	CombatAnchorRuntime.AimPosition = center
	CombatAnchorRuntime.TargetCount = count
	return CombatAnchorRuntime.Position, CombatAnchorRuntime.AimPosition, count
end

function triggerCombatForcePulse(aimPosition, duration)
    if V577MovementAuthority and not V577MovementAuthority.CanMove("NORMAL") then return end
	if not State.FarmEnabled or not character or not character.Parent or not rootPart then return end
	local anchorPosition = select(1, refreshCombatAnchor(false))
	if anchorPosition and os.clock() < CombatSafetyBoostUntil then
		anchorPosition = anchorPosition + Vector3.new(0, CombatSafetyBoostHeight, 0)
	elseif os.clock() >= CombatSafetyBoostUntil then
		CombatSafetyBoostHeight = 0
	end
	if not anchorPosition then return end
	aimPosition = typeof(aimPosition) == "Vector3" and aimPosition or CombatAnchorRuntime.AimPosition
	if not aimPosition then return end

    local aliveCount = getCachedAliveTitanCount()
    local finisherMode = aliveCount <= math.max(1, tonumber(Config.FinisherTitanCount) or 5)

    local attackDirection = Vector3.new(0, -1, 0)
    if finisherMode and aimPosition then
        local delta = aimPosition - anchorPosition
        if delta.Magnitude > 0.1 then
            attackDirection = delta.Unit
        end
    end

	CombatAnchorRuntime.PulseSerial += 1
	local serial = CombatAnchorRuntime.PulseSerial
	local pulseDuration = math.max(0.025, tonumber(duration) or tonumber(Config.BladeForcePulseDuration) or 0.065)
	CombatAnchorRuntime.PulseUntil = os.clock() + pulseDuration

    local pulseDistance = finisherMode
        and (tonumber(Config.FinisherPulseDistance) or 34)
        or (tonumber(Config.SpeedPulseDistance) or 20)

    local killSpeed = finisherMode
        and (tonumber(Config.FinisherKillSpeed) or 1450)
        or (tonumber(Config.KillSpeed) or 1180)

    local pulsePosition = anchorPosition + attackDirection * pulseDistance
    character:PivotTo(CFrame.lookAt(pulsePosition, aimPosition))
    rootPart.AssemblyAngularVelocity = Vector3.zero
    rootPart.AssemblyLinearVelocity = attackDirection * killSpeed

	task.delay(pulseDuration, function()
		if serial ~= CombatAnchorRuntime.PulseSerial then return end
		CombatAnchorRuntime.PulseUntil = 0
		if not State.FarmEnabled or not character or not character.Parent or not rootPart then return end
		local stablePosition = CombatAnchorRuntime.Position or anchorPosition
		local stableAim = CombatAnchorRuntime.AimPosition or aimPosition
		character:PivotTo(CFrame.lookAt(stablePosition, stableAim))
		rootPart.AssemblyAngularVelocity = Vector3.zero
		rootPart.AssemblyLinearVelocity = Vector3.zero
	end)
end

-- V9.4.2 hard air-lock invariant. Target detection is not allowed to release
-- gravity ownership. The last safe aerial CFrame survives temporary 0-target scans.
V942AirLock = V942AirLock or {
    RootPart = nil,
    LastSafeCFrame = nil,
    LastHoldAt = 0,
    Status = "BOOT",
}

-- Stable anchor keeper. Force generation happens only when a blade burst is actually launched.
local function lockCharacterInSky(targetPart)
    if V577MovementAuthority and not V577MovementAuthority.CanMove("NORMAL") then return end
	if not character or not character.Parent or not humanoid or humanoid.Health <= 0 or not rootPart then return end
	if os.clock() < (CombatAnchorRuntime.PulseUntil or 0) then return end

    if V942AirLock.RootPart ~= rootPart then
        V942AirLock.RootPart = rootPart
        V942AirLock.LastSafeCFrame = nil
        V942AirLock.Status = "NEW CHARACTER"
    end

	local anchorPosition, aimPosition = refreshCombatAnchor(false)
	if anchorPosition and os.clock() < CombatSafetyBoostUntil then
		anchorPosition = anchorPosition + Vector3.new(0, CombatSafetyBoostHeight, 0)
	elseif os.clock() >= CombatSafetyBoostUntil then
		CombatSafetyBoostHeight = 0
	end

	if not anchorPosition then
        if targetPart and targetPart.Parent then
            aimPosition = targetPart.Position
            anchorPosition = aimPosition + Vector3.new(0, currentCombatSkyHeight(), 0)
        else
            -- Zero targets: hold the last proven combat CFrame instead of only
            -- zeroing velocity and letting gravity win between scan frames.
            local hold = V942AirLock.LastSafeCFrame
            if not hold then
                hold = rootPart.CFrame
                V942AirLock.LastSafeCFrame = hold
            end

            character:PivotTo(hold)
            rootPart.AssemblyAngularVelocity = Vector3.zero
            rootPart.AssemblyLinearVelocity = Vector3.zero
            V942AirLock.LastHoldAt = os.clock()
            V942AirLock.Status = "HOLD • 0 TARGETS"
            return
        end
	end

	aimPosition = aimPosition or (targetPart and targetPart.Position) or anchorPosition + Vector3.new(0, -1, 0)
    local desiredCFrame
	if (rootPart.Position - anchorPosition).Magnitude >= math.max(2, tonumber(Config.CombatAnchorSnapDistance) or 8) then
        desiredCFrame = CFrame.lookAt(anchorPosition, aimPosition)
	else
        desiredCFrame = CFrame.lookAt(rootPart.Position, aimPosition)
	end

    character:PivotTo(desiredCFrame)
	rootPart.AssemblyAngularVelocity = Vector3.zero
	rootPart.AssemblyLinearVelocity = Vector3.zero

    V942AirLock.LastSafeCFrame = desiredCFrame
    V942AirLock.LastHoldAt = os.clock()
    V942AirLock.Status = targetPart and "LOCKED • TARGET" or "LOCKED • ANCHOR"
end

-- Independent keeper: active Farm owns a safe aerial hold even when the main
-- targeting loop has no current target. Explicit movement owners remain authoritative.
task.spawn(function()
    while true do
        task.wait(0.06)

        if not State.FarmEnabled
            or State.IsGrabbed
            or ripperSequenceRunning
            or not character
            or not character.Parent
            or not humanoid
            or humanoid.Health <= 0
            or not rootPart then
            continue
        end

        local cutsceneBusy = V94CutsceneDirector
            and tostring(V94CutsceneDirector.State or "IDLE") ~= "IDLE"
        local colossalTransition = V55ColossalDirector
            and V55ColossalDirector.TransitionActive == true
        local femaleTransition = V521FemaleDirector
            and V521FemaleDirector.TransitionActive == true
        local movementMode = V577MovementAuthority
            and V577MovementAuthority.Mode
            and V577MovementAuthority.Mode()
            or "NORMAL"
        local raidPause = false
        if V4RaidDirector and V4RaidDirector.ShouldPauseCombat then
            pcall(function()
                raidPause = V4RaidDirector.ShouldPauseCombat() == true
            end)
        end

        if movementMode == "NORMAL"
            and not raidPause
            and not cutsceneBusy
            and not colossalTransition
            and not femaleTransition then
            pcall(lockCharacterInSky, nil)
        end
    end
end)

---------------------------------------------------------------------
-- BLADE FARM ENGINE
---------------------------------------------------------------------

local function fireBladeRemote(titan)
	if not CachedBladeRemote then
		CachedBladeRemote = resolvePath(ReplicatedStorage, Config.BladeRemotePath) or scanNetworkForRemote({"swing", "blade", "slash", "hit", "attack", "m1"})
	end
    if not CachedBladeRemote then
        BladeDiag.LastRemote = "optional:none"
        return false
    end
    BladeDiag.LastRemote = CachedBladeRemote:GetFullName()

	if CachedBladeRemote:IsA("RemoteEvent") then
		if Config.SendTitanToBladeRemote then CachedBladeRemote:FireServer(titan) else CachedBladeRemote:FireServer() end
		return true
	elseif CachedBladeRemote:IsA("RemoteFunction") then
		task.spawn(function() if Config.SendTitanToBladeRemote then CachedBladeRemote:InvokeServer(titan) else CachedBladeRemote:InvokeServer() end end)
		return true
	end
	return false
end

V6ExactBlade = V6ExactBlade or {
    Version = "9.0.0",
    Targets = {},
    NextCycleAt = 0,
    LastSlashAt = 0,
    LastCycleTargets = 0,
    LastCycleSlashes = 0,
    TotalSlashes = 0,
    TotalRegisters = 0,
    Status = "Booting V9 raid combat matrix",
}

function V6ExactBlade.GetPOST()
    local post = resolvePath(ReplicatedStorage, {"Assets", "Remotes", "POST"})
    if post and post:IsA("RemoteEvent") then return post end
    return nil
end

function V6ExactBlade.GetExactNape(titan)
    if V9RaidCombat and V9RaidCombat.ExactNape then
        return V9RaidCombat.ExactNape(titan)
    end
    if not titan or not titan.Parent then return nil end
    local hitboxes = titan:FindFirstChild("Hitboxes")
    local hit = hitboxes and hitboxes:FindFirstChild("Hit")
    local nape = hit and hit:FindFirstChild("Nape")
    if nape and nape:IsA("BasePart") and nape.Parent then return nape end
    return nil
end

function V6ExactBlade.TargetAllowed(titan)
    if not titan or not titan.Parent or not isTitanAlive(titan) then return false end
    if V58BladeEngine and V58BladeEngine.AllowedTitan and not V58BladeEngine.AllowedTitan(titan) then
        return false
    end
    return V6ExactBlade.GetExactNape(titan) ~= nil
end

function V6ExactBlade.PruneTargets()
    local kept = {}
    local seen = {}
    for _, titan in ipairs(V6ExactBlade.Targets or {}) do
        if V6ExactBlade.TargetAllowed(titan) and not seen[titan] then
            kept[#kept + 1] = titan
            seen[titan] = true
        end
    end
    V6ExactBlade.Targets = kept
    return seen
end

function V6ExactBlade.FillTargets()
    local maximum = math.min(
        getEffectiveTitansPerHit(),
        math.max(
            1,
            math.floor(
                tonumber(Config.V9BladeQueueMaxTargets)
                or tonumber(Config.V6ExactBladeMaxTargets)
                or SliceHubMissionTPSMax()
            )
        )
    )
    local seen = V6ExactBlade.PruneTargets()

    local function add(titan)
        if #V6ExactBlade.Targets >= maximum then return end
        if not seen[titan] and V6ExactBlade.TargetAllowed(titan) then
            seen[titan] = true
            V6ExactBlade.Targets[#V6ExactBlade.Targets + 1] = titan
        end
    end

    local requested = getBladeAttackTargets()
    for _, titan in ipairs(requested or {}) do
        add(titan)
        if #V6ExactBlade.Targets >= maximum then break end
    end

    if #V6ExactBlade.Targets < maximum then
        local folder = Workspace:FindFirstChild(Config.TitansFolderName)
        if folder then
            for _, titan in ipairs(folder:GetChildren()) do
                add(titan)
                if #V6ExactBlade.Targets >= maximum then break end
            end
        end
    end

    return V6ExactBlade.Targets
end

function V6ExactBlade.SendPlanBank(post, bank)
    if type(bank) ~= "table" or #bank == 0 then return 0, 0 end

    local low = math.floor(tonumber(Config.V6ExactBladeRegisterMin) or 625)
    local high = math.floor(tonumber(Config.V6ExactBladeRegisterMax) or 850)
    if high < low then low, high = high, low end

    post:FireServer("Attacks", "Slash", true)

    local registers = 0
    for _, item in ipairs(bank) do
        local titan = item and item.Titan
        local repeats = math.max(1, math.floor(tonumber(item and item.Repeats) or 1))
        for _ = 1, repeats do
            local nape = V6ExactBlade.GetExactNape(titan)
            if nape then
                post:FireServer(
                    "Hitboxes",
                    "Register",
                    nape,
                    math.random(low, high)
                )
                registers += 1
            end
        end
    end

    return 1, registers
end

function V6ExactBlade.PlanUniqueTitans(plan)
    local output = {}
    local seen = {}
    for _, item in ipairs(plan or {}) do
        local titan = item and item.Titan
        if titan and not seen[titan] then
            seen[titan] = true
            output[#output + 1] = titan
        end
    end
    return output
end

function V6ExactBlade.Cycle()
    if Config.V6ExactBladeEnabled ~= true then return false, 0 end
    if not State or State.BladesEnabled ~= true or State.FarmEnabled ~= true then return false, 0 end

    if Config.V93BladeAmmoDirectorEnabled == true
        and V93BladeAmmoDirector
        and V93BladeAmmoDirector.BladelessHold == true then
        V6ExactBlade.Status = "BLADELESS_HOLD"
        if V58BladeEngine then
            V58BladeEngine.SetPhase("WAIT_AMMO", tostring(V93BladeAmmoDirector.Status or "bladeless hold"), 0)
        end
        return false, 0
    end

    if refillSequenceRunning or (StationRefill and StationRefill.Running) then
        V6ExactBlade.Status = "REFILL_LOCK"
        if V58BladeEngine then V58BladeEngine.SetPhase("REFILL_LOCK", "V9.1 exact queue paused", 0) end
        return false, 0
    end

    if V91BladeRefillGuard
        and os.clock() < (tonumber(V91BladeRefillGuard.HoldUntil) or 0) then
        V6ExactBlade.Status = "BLADE_BREAK_RELOAD"
        if V58BladeEngine then V58BladeEngine.SetPhase("REFILL_LOCK", "V9.1 Break reload ownership", 0) end
        return false, 0
    end

    if V91RaidBossGuard and V91RaidBossGuard.Blocked and V91RaidBossGuard.Blocked() then
        V6ExactBlade.Status = "BOSS_INVULN_ROAR"
        V6ExactBlade.NextCycleAt = os.clock() + 0.08
        if V58BladeEngine then V58BladeEngine.SetPhase("WAIT_COOLDOWN", "Attack boss roar invulnerability", V6ExactBlade.NextCycleAt) end
        return false, 0
    end

    if V577MovementAuthority and V577MovementAuthority.Mode() == "CANNON" then
        if V55ColossalDirector
            and (V55ColossalDirector.DismountPending == true or V55ColossalDirector.RemountPending == true) then
            V6ExactBlade.Status = "CANNON_HANDSHAKE_LOCK"
            return false, 0
        end

        local mountedGuardian = V941ObjectiveGuardian
            and V941ObjectiveGuardian.ColossalMountedActive
            and V941ObjectiveGuardian.ColossalMountedActive() == true
        if not mountedGuardian then
            V6ExactBlade.Status = "CANNON_LOCK"
            return false, 0
        end
        V6ExactBlade.Status = "CANNON_GUARDIAN_REMOTE"
    end

    local now = os.clock()
    if now < (tonumber(V6ExactBlade.NextCycleAt) or 0) then
        if V58BladeEngine then
            V58BladeEngine.SetPhase(
                "WAIT_COOLDOWN",
                string.format("V9 matrix %.2fs", math.max(0, V6ExactBlade.NextCycleAt - now)),
                V6ExactBlade.NextCycleAt
            )
        end
        return false, 0
    end

    local post = V6ExactBlade.GetPOST()
    if not post then
        V6ExactBlade.Status = "POST missing"
        V6ExactBlade.NextCycleAt = now + 0.25
        return false, 0
    end

    local targets = V6ExactBlade.FillTargets()
    local plan, matrixMode = V9RaidCombat.BuildBladePlan(targets)

    if type(plan) ~= "table" or #plan == 0 then
        V6ExactBlade.Status = "NO_VALID_NAPES"
        V6ExactBlade.NextCycleAt = now + math.max(0.02, tonumber(Config.V6ExactBladeNoTargetDelay) or 0.05)
        if V58BladeEngine then
            V58BladeEngine.SetPhase("NO_VALID_WAVE", "V9 matrix empty", V6ExactBlade.NextCycleAt)
        end
        return false, 0
    end

    local uniqueTargets = V6ExactBlade.PlanUniqueTitans(plan)
    local snapshot = V58BladeEngine and V58BladeEngine.BeginBurstSnapshot(
        uniqueTargets,
        V58BladeEngine.Mode or "PACK SWEEP",
        "V9 RAID MATRIX"
    ) or nil

    bladeBurstRunning = true
    BladeDiag.BurstStartedAt = now

    local slashCount = 0
    local registerCount = 0
    local ok, err = pcall(function()
        local raidEnabled = V4RaidDirector and V4RaidDirector.Enabled == true
        local bankSize = math.min(
            getEffectiveTitansPerHit(),
            math.max(1, math.floor(tonumber(Config.V9BladeBankSize) or 10))
        )

        local objectiveGuardianPlan = string.find(
            tostring(matrixMode or ""),
            "OBJECTIVE GUARDIAN",
            1,
            true
        ) ~= nil

        if (not raidEnabled or objectiveGuardianPlan) and #plan > bankSize then
            -- V9.8.2.7: tier-aware exact banks. Free remains capped at one bank of up
            -- to 6 targets. Premium sends up to 10 targets per Slash, so a selected
            -- value of 20 becomes 10 + 10 with only tiny acceptance spacing.
            local bankStart = 1
            while bankStart <= #plan do
                local bankEnd = math.min(#plan, bankStart + bankSize - 1)
                local bank = {}
                for index = bankStart, bankEnd do
                    bank[#bank + 1] = plan[index]
                end

                local slashes, registers = V6ExactBlade.SendPlanBank(post, bank)
                slashCount += slashes
                registerCount += registers
                bankStart = bankEnd + 1

                if bankStart <= #plan then
                    task.wait(math.max(0.005, tonumber(Config.V9BladeSecondBankDelay) or 0.012))
                end
            end
        else
            local s, r = V6ExactBlade.SendPlanBank(post, plan)
            slashCount += s
            registerCount += r
        end
    end)

    bladeBurstRunning = false
    BladeDiag.BurstStartedAt = 0

    if not ok then
        V6ExactBlade.Status = "REMOTE_ERROR: " .. tostring(err)
        V6ExactBlade.NextCycleAt = os.clock() + 0.20
        return false, 0
    end

    BladeBurstSerial += 1
    lastBladeBurstCount = math.max(1, registerCount)
    lastBladeBurstFinishedAt = os.clock()
    V6ExactBlade.LastSlashAt = now
    V6ExactBlade.LastCycleTargets = registerCount
    V6ExactBlade.LastCycleSlashes = slashCount
    V6ExactBlade.TotalSlashes += slashCount
    V6ExactBlade.TotalRegisters += registerCount

    V9RaidCombat.BladeMode = tostring(matrixMode or "UNKNOWN")
    V9RaidCombat.LastBladeRegisters = registerCount
    V9RaidCombat.LastBladeSlashes = slashCount
    if string.find(V9RaidCombat.BladeMode, "BOSS", 1, true) then
        V9RaidCombat.BossBladeCycles += 1
    else
        V9RaidCombat.PackBladeCycles += 1
    end

    V6ExactBlade.Status = string.format(
        "%s • Slash x%d • Reg %d",
        tostring(matrixMode or "V9"),
        slashCount,
        registerCount
    )

    local bossMode = string.find(tostring(matrixMode or ""), "BOSS", 1, true) ~= nil
    local cadence = bossMode
        and math.max(0.12, tonumber(Config.V9BossBladeCadence) or 0.21)
        or math.max(0.12, tonumber(Config.V9BladeCycleCadence) or tonumber(Config.V6ExactBladeCadence) or 0.24)

    V6ExactBlade.NextCycleAt = now + cadence
    nextBladeAttack = V6ExactBlade.NextCycleAt

    if V58BladeEngine then
        V58BladeEngine.SetPhase("READY", V6ExactBlade.Status, V6ExactBlade.NextCycleAt)
        V58BladeEngine.Status = "V9 RAID MATRIX • " .. V6ExactBlade.Status
    end

    if snapshot and V58BladeEngine then
        task.delay(0.42, function()
            pcall(function()
                V58BladeEngine.FinishBurstSnapshot(snapshot)
            end)
        end)
    end

    return true, registerCount
end

local function swingBlades()
    if V984Pacing and V984Pacing.ShouldPauseFinish and V984Pacing.ShouldPauseFinish() then
        BladeDiag.Reason = "BLOCK:PACING"
        if V58BladeEngine then V58BladeEngine.SetPhase("PACING", V984Pacing.Status, 0) end
        return false, 0
    end

    if Config.V6ExactBladeEnabled == true then
        return V6ExactBlade.Cycle()
    end

    if ripperSequenceRunning then
        BladeDiag.Reason = "BLOCK:RIPPER"
        if V58BladeEngine then V58BladeEngine.SetPhase("BLASTER_LOCK", "ability window", 0) end
        return false, 0
    end
    if refillSequenceRunning then
        BladeDiag.Reason = "BLOCK:REFILL"
        if V58BladeEngine then V58BladeEngine.SetPhase("REFILL_LOCK", "blade refill", 0) end
        return false, 0
    end
    if bladeBurstRunning then
        BladeDiag.Reason = "BLOCK:BURST_RUNNING"
        if V58BladeEngine then V58BladeEngine.SetPhase("BURST_ACTIVE", "physical wave running", 0) end
        return false, 0
    end

    local currentTime = os.clock()
    if currentTime < nextBladeAttack then
        BladeDiag.Reason = "BLOCK:COOLDOWN"
        if V58BladeEngine then
            V58BladeEngine.SetPhase(
                "WAIT_COOLDOWN",
                string.format("%.2fs", math.max(0, nextBladeAttack - currentTime)),
                nextBladeAttack
            )
        end
        return false, 0
    end

	local requestedTargets = getBladeAttackTargets()
	local validTargets = {}
	local seen = {}
	local maximumTargets = getEffectiveTitansPerHit()
    local bladeV3Mode = V58BladeEngine and V58BladeEngine.Mode or "PACK SWEEP"
    local hybridBurst = V58BladeEngine and V58BladeEngine.HybridBurstRequested == true
    if hybridBurst then
        maximumTargets = math.min(
            maximumTargets,
            math.max(1, math.floor(tonumber(Config.BladeV3HybridMaxTargets) or 2))
        )
    end

	if State.AutoRefillEnabled and lastBladeSegments ~= nil then
		local segments = tonumber(lastBladeSegments) or 0
        if segments <= 0 then
            BladeDiag.Reason = "BLOCK:SEGMENTS_0"
            nextBladeAttack = currentTime + math.max(0.12, tonumber(Config.AutoRefillPostPressDelay) or 0.18)
            if V58BladeEngine then V58BladeEngine.SetPhase("WAIT_AMMO", "segments 0", nextBladeAttack) end
            return false, 0
		elseif segments <= (tonumber(Config.BladeBurstMinimumSegments) or 2) then
			maximumTargets = math.min(maximumTargets, math.max(1, tonumber(Config.BladeBurstLowSegmentCap) or 2))
		end
	end

	for _, titan in ipairs(requestedTargets) do
		if #validTargets >= maximumTargets then break end
		if titan and not seen[titan] and isTitanAlive(titan) and not isTitanBlacklisted(titan) then
			seen[titan] = true
			table.insert(validTargets, titan)
		end
	end

	if #validTargets == 0 then
        BladeDiag.Reason = "BLOCK:NO_TARGETS"
        cachedTitanCandidatesAt = 0
        nextBladeAttack = currentTime + math.max(0.015, tonumber(Config.BladeV31NoTargetRescanDelay) or 0.040)
        if V58BladeEngine then
            V58BladeEngine.SetPhase("NO_VALID_WAVE", "refreshing Titan cache", nextBladeAttack)
        end
        return false, 0
    end

	local targetCount = #validTargets
	local bladeOnlySaw = AdaptiveCombatMode ~= "Ripper"
	local burstRounds = bladeOnlySaw
		and math.clamp(math.floor((tonumber(Config.BladeOnlyBurstRounds) or 2) + 0.5), 1, 3)
		or math.clamp(math.floor((tonumber(Config.RipperBladeBurstRounds) or 2) + 0.5), 1, 3)
	local clickRepeats = bladeOnlySaw
		and math.clamp(math.floor((tonumber(Config.BladeOnlyClickRepeats) or 2) + 0.5), 1, 3)
		or math.clamp(math.floor((tonumber(Config.RipperBladeClickRepeats) or 1) + 0.5), 1, 3)

	local aliveCount = getCachedAliveTitanCount()
	local finisherMode = targetCount <= 3 or aliveCount <= math.max(1, tonumber(Config.FinisherTitanCount) or 5)
	if finisherMode then
		burstRounds = math.max(burstRounds, math.clamp(math.floor((tonumber(Config.FinisherBladeRounds) or 4) + 0.5), 3, 5))
		clickRepeats = math.max(clickRepeats, math.clamp(math.floor((tonumber(Config.FinisherClickRepeats) or 3) + 0.5), 2, 6))
		Config.TargetStallTimeout = math.min(tonumber(Config.TargetStallTimeout) or 0.75, tonumber(Config.FinisherTargetStallTimeout) or 0.45)
	end

    local waveSize = math.clamp(math.floor((tonumber(Config.BladeBurstWaveSize) or 4) + 0.5), 1, 20)
    local dynamicPhysicalClicks = math.max(1, math.floor(tonumber(Config.MainPhysicalClicksPerWave) or 2))

    if finisherMode then
        waveSize = 1
        dynamicPhysicalClicks = math.max(1, math.floor(tonumber(Config.FinisherPhysicalClicksPerWave) or 3))
        burstRounds = math.max(burstRounds, 5)
    elseif Config.DynamicSweepEnabled == true then
        if targetCount >= math.max(1, tonumber(Config.DenseSweepMinTargets) or 12) then
            waveSize = math.max(1, math.floor(tonumber(Config.DenseSweepWaveSize) or 6))
            dynamicPhysicalClicks = math.max(1, math.floor(tonumber(Config.DenseSweepClicks) or 3))
        elseif targetCount >= math.max(1, tonumber(Config.MediumSweepMinTargets) or 6) then
            waveSize = math.max(1, math.floor(tonumber(Config.MediumSweepWaveSize) or 4))
            dynamicPhysicalClicks = math.max(1, math.floor(tonumber(Config.MediumSweepClicks) or 2))
        else
            waveSize = math.max(1, math.floor(tonumber(Config.SparseSweepWaveSize) or 2))
            dynamicPhysicalClicks = math.max(1, math.floor(tonumber(Config.SparseSweepClicks) or 1))
        end
    end

    if bladeOnlySaw and not finisherMode then
        dynamicPhysicalClicks = math.min(
            math.max(dynamicPhysicalClicks + math.floor(tonumber(Config.BladeOnlyExtraClicksPerWave) or 1), 1),
            math.max(1, math.floor(tonumber(Config.BladeOnlyMaxPhysicalClicks) or 4))
        )
    end

    local bladePulseDuration = tonumber(Config.BladeForcePulseDuration) or 0.16
    local waveDelay = math.max(0.025, tonumber(Config.BladeBurstWaveDelay) or 0.034)
    if hybridBurst then
        waveSize = math.min(
            targetCount,
            math.max(1, math.floor(tonumber(Config.BladeV3HybridMaxTargets) or 2))
        )
        burstRounds = math.max(1, math.floor(tonumber(Config.BladeV3HybridRounds) or 1))
        clickRepeats = 1
        dynamicPhysicalClicks = math.max(1, math.floor(tonumber(Config.BladeV3HybridClicks) or 1))
        bladePulseDuration = math.max(0.025, tonumber(Config.BladeV3HybridPulseDuration) or 0.045)
        waveDelay = math.max(0.010, tonumber(Config.BladeV3HybridWaveDelay) or 0.018)
    end

	local waveCount = math.max(1, math.ceil(targetCount / waveSize))
	local burstDuration = math.max(
		Config.BladeCooldown,
		(targetCount * burstRounds) * Config.MultiTargetRemoteSpacing
			+ (waveCount * burstRounds) * (
                bladePulseDuration
				+ (tonumber(Config.BladeWaveReturnPadding) or 0.02)
			)
			+ Config.MultiTargetBurstPadding
	)

    -- V5.8.1 continuity: bladeBurstRunning already owns the real execution window.
    -- Keep only a tiny anti-double-fire guard here; completion/verification decides
    -- the next real action time from observed progress.
    nextBladeAttack = currentTime + math.max(
        tonumber(Config.BladeCooldown) or 0.105,
        tonumber(Config.BladeV31CooldownGuard) or 0.060
    )
	lastBladeBurstCount = targetCount
	BladeBurstSerial += 1

    local burstSnapshot = V58BladeEngine and V58BladeEngine.BeginBurstSnapshot(
        validTargets,
        bladeV3Mode,
        hybridBurst and "HYBRID" or "BLADE"
    ) or nil

	local verificationTitan =
        (bladeV3Mode == "SURVIVOR HUNT" and V58BladeEngine and V58BladeEngine.SurvivorTarget)
        or currentTarget
        or validTargets[1]
	local verificationHealth = nil
	local aliveBeforeBurst = getCachedAliveTitanCount()
	if verificationTitan then
		local verificationHumanoid = verificationTitan:FindFirstChildOfClass("Humanoid")
		verificationHealth = verificationHumanoid and verificationHumanoid.Health or nil
	end

	local function getWaveAim(startIndex, endIndex)
		local sum = Vector3.zero
		local count = 0
		local firstPart = nil

		for index = startIndex, endIndex do
			local titan = validTargets[index]
			if titan and isTitanAlive(titan) then
				local part = V58BladeEngine and V58BladeEngine.AimPartForTitan(titan) or getTitanTargetPart(titan)
				if part and part.Parent then
					firstPart = firstPart or part
					sum += part.Position
					count += 1
				end
			end
		end

		if count > 0 then
			return sum / count, firstPart
		end

		return CombatAnchorRuntime.AimPosition
			or (currentTargetPart and currentTargetPart.Position),
			currentTargetPart
	end

	-- V5.8: hybrid ownership is only asserted after a real target wave survives all gates.
    if V58BladeEngine then V58BladeEngine.HybridBurstActive = hybridBurst end
	bladeBurstRunning = true
    BladeDiag.BurstStartedAt = currentTime
	task.spawn(function()
		pcall(function()
			for round = 1, burstRounds do
				local waveStart = 1
				while waveStart <= targetCount and State.FarmEnabled do
					local waveEnd = math.min(targetCount, waveStart + waveSize - 1)
					local waveAimPosition, waveAimPart = getWaveAim(waveStart, waveEnd)

					-- DEV14 sustained blade route: reacquire/equip the actual blade Tool, then create
					-- force, then click while force is live, then fan out only this micro-wave.
                    local waveBladeTool = prepareBladeWaveTool()
                    if waveAimPosition then
                        triggerCombatForcePulse(
                            waveAimPosition,
                            bladePulseDuration
                        )
                        task.wait(math.max(
                            0.005,
                            tonumber(Config.BladeWavePulseLead) or 0.030
                        ))
                    end

                    local physicalClicks = dynamicPhysicalClicks

                    for clickIndex = 1, physicalClicks do
                        if not State.FarmEnabled then break end

                        if clickIndex > 1 then
                            task.wait(math.max(
                                0.015,
                                tonumber(Config.BladeWaveClickSpacing) or 0.026
                            ))
                        end

                        local chosenIndex
                        if physicalClicks <= 1 or waveEnd <= waveStart then
                            chosenIndex = waveStart
                        else
                            local alpha = (clickIndex - 1) / (physicalClicks - 1)
                            chosenIndex = math.floor(
                                waveStart + ((waveEnd - waveStart) * alpha) + 0.5
                            )
                        end

                        local clickTitan = validTargets[chosenIndex]
                        local clickPart = clickTitan and (V58BladeEngine and V58BladeEngine.AimPartForTitan(clickTitan) or getTitanTargetPart(clickTitan)) or nil

                        if waveBladeTool and waveBladeTool.Parent == character then
                            pcall(function()
                                waveBladeTool:Activate()
                            end)
                        end

                        simulateCenterMouseClick(
                            clickPart
                            or waveAimPart
                            or waveAimPosition
                            or currentTargetPart
                        )
                    end

					for index = waveStart, waveEnd do
						if not State.FarmEnabled then break end
						local titan = validTargets[index]
						if titan and isTitanAlive(titan) then
							fireBladeRemote(titan)
						end
						if index < waveEnd then
							task.wait(Config.MultiTargetRemoteSpacing)
						end
					end

					-- Give the pulse return a moment to settle before the next micro-wave.
					task.wait(math.max(0.005, tonumber(Config.BladeWaveReturnPadding) or 0.020))
					waveStart = waveEnd + 1
					if waveStart <= targetCount then
						task.wait(waveDelay)
					end
				end
			end
		end)

        if V58BladeEngine then
            V58BladeEngine.ReturnToSafeLane("post-burst safe lane")
            V58BladeEngine.SetPhase("VERIFY", "checking real HP / kills", 0)
        end

		bladeBurstRunning = false
        BladeDiag.BurstStartedAt = 0
        if V58BladeEngine then V58BladeEngine.HybridBurstActive = false end
		lastBladeBurstFinishedAt = os.clock()

		-- DEV14: verify both the primary target and total alive count. A burst that kills other Titans
		-- is still real progress. Repeated zero-progress bursts rebuild blade Tool/remote caches and back off briefly.
		task.wait(math.max(0.02, tonumber(Config.BladeProgressVerifyDelay) or 0.10))
		local burstMadeProgress = false
		local aliveAfterBurst = getCachedAliveTitanCount()
        local burstStats = V58BladeEngine and V58BladeEngine.FinishBurstSnapshot(burstSnapshot) or nil

        if burstStats and (
            (tonumber(burstStats.Registered) or 0) > 0
            or (tonumber(burstStats.Kills) or 0) > 0
        ) then
            burstMadeProgress = true
        end

		if aliveAfterBurst < aliveBeforeBurst then
			burstMadeProgress = true
		end

		if verificationTitan then
			local verificationHumanoid = verificationTitan:FindFirstChildOfClass("Humanoid")
			if not verificationHumanoid or verificationHumanoid.Health <= 0 or not verificationTitan.Parent then
				burstMadeProgress = true
				BladeBurstFailureCounts[verificationTitan] = nil
				if currentTarget == verificationTitan then clearCurrentTarget(false) end
			elseif verificationHealth ~= nil and verificationHumanoid.Health < verificationHealth - Config.HealthProgressEpsilon then
				burstMadeProgress = true
				BladeBurstFailureCounts[verificationTitan] = nil
				targetLastProgressTime = os.clock()
			elseif bladeV3Mode == "SURVIVOR HUNT" then
                -- Survivor Hunter owns no-progress recovery: switch exact body reference first,
                -- then rotate the stale Titan only after a complete part cycle.
                BladeBurstFailureCounts[verificationTitan] = nil
			else
				local failures = (BladeBurstFailureCounts[verificationTitan] or 0) + 1
				BladeBurstFailureCounts[verificationTitan] = failures
                if failures >= math.max(1, tonumber(Config.BladeFailedBurstLimit) or 2) then
                    BladeBurstFailureCounts[verificationTitan] = nil
                    if currentTarget == verificationTitan then
                        clearCurrentTarget(not finisherMode)
                    end
                    cachedTitanCandidatesAt = 0
                end
			end
		end

        if bladeV3Mode == "SURVIVOR HUNT" and V58BladeEngine then
            V58BladeEngine.RecordSurvivorBurst(
                verificationTitan,
                verificationHealth,
                aliveBeforeBurst,
                burstMadeProgress
            )
        end

        if burstMadeProgress then
            BladeEngineNoProgressBursts = 0
            cachedTitanCandidatesAt = 0
            V52KillingEngine.LastHandoffAt = os.clock()
            V52KillingEngine.Status = "Progress confirmed • immediate rescan"
            nextBladeAttack = os.clock() + math.max(
                0.005,
                tonumber(Config.BladeV31ImmediateRescanDelay) or 0.012
            )
            if V58BladeEngine then
                local kills = burstStats and tonumber(burstStats.Kills) or math.max(0, aliveBeforeBurst - aliveAfterBurst)
                local registered = burstStats and tonumber(burstStats.Registered) or kills
                V58BladeEngine.SetPhase(
                    "READY",
                    string.format("progress K%d / R%d", kills or 0, registered or 0),
                    nextBladeAttack
                )
            end
        else
			BladeEngineNoProgressBursts += 1
            CachedBladeTool = nil
            CachedBladeRemote = nil
            cachedTitanCandidatesAt = 0

            local recoveryLimit = math.max(1, tonumber(Config.BladeEngineRecoveryLimit) or 2)
            local hardRecovery = BladeEngineNoProgressBursts >= recoveryLimit
            if hardRecovery then
                BladeEngineNoProgressBursts = 0
            end

            local retryDelay = hardRecovery
                and math.max(0.08, tonumber(Config.BladeV31NoProgressHardBackoff) or 0.180)
                or math.max(0.02, tonumber(Config.BladeV31NoProgressRetryDelay) or 0.060)

            nextBladeAttack = os.clock() + retryDelay
            if V58BladeEngine then
                V58BladeEngine.SetPhase(
                    "RECOVERY_RETRY",
                    hardRecovery and "hard cache rebuild" or "quick tool/target rebuild",
                    nextBladeAttack
                )
            end
		end
	end)

	-- Extra real clicks are spaced independently from the remote fan-out. They support pure-blade alts
	-- without making Titan Ripper the main damage source.
	if clickRepeats > 1 then
		task.spawn(function()
			for i = 2, clickRepeats do
				task.wait(0.035)
				if not State.FarmEnabled then break end
				simulateCenterMouseClick(currentTargetPart)
			end
		end)
	end

	return true, targetCount
end


-- V2 quiet watchdog: only reports a genuinely stuck burst.
task.spawn(function()
    while true do
        task.wait(0.25)

        if State and State.FarmEnabled then
            local now = os.clock()
            if bladeBurstRunning
                and BladeDiag.BurstStartedAt > 0
                and now - BladeDiag.BurstStartedAt > 3.0 then

                BladeDiag.WatchdogResets += 1
                warn(
                    "[SliceHub V2][BLADE-WATCHDOG] clearing stale burst",
                    "age=" .. string.format("%.2f", now - BladeDiag.BurstStartedAt)
                )

                bladeBurstRunning = false
                BladeDiag.BurstStartedAt = 0
                BladeDiag.Reason = "WATCHDOG:BURST_RESET"
                nextBladeAttack = 0
            end
        end
    end
end)

---------------------------------------------------------------------
-- TITAN RIPPER HOTBAR ENGINE (AUTO SLOTS 1-5)
---------------------------------------------------------------------


---------------------------------------------------------------------
-- V4 TITAN BLASTER NAPE LOCK
---------------------------------------------------------------------

V4BlasterNapeLock = V4BlasterNapeLock or {
    Active = false,
    Token = 0,
    Queue = {},
    SkillId = nil,
    Status = "Idle",
    Center = nil,
    Dynamic = false,
    TargetCount = 0,
    LastRefreshAt = 0,
}

function V4BlasterNapeLock.BuildQueue(limit, center)
    local entries =
        V35Spears
        and V35Spears.GetGlobalEntries
        and V35Spears.GetGlobalEntries()
        or {}

    local candidates = {}

    for _, entry in ipairs(entries) do
        local titan = entry.Titan
        local part =
            titan
            and (
                titan:FindFirstChild("Nape", true)
                or entry.Part
            )
            or nil

        if part and part:IsA("BasePart") and part.Parent then
            local distanceSquared = 0

            if typeof(center) == "Vector3" then
                local delta = part.Position - center
                distanceSquared = delta:Dot(delta)
            end

            candidates[#candidates + 1] = {
                Titan = titan,
                Part = part,
                DistanceSquared = distanceSquared,
            }
        end
    end

    table.sort(candidates, function(a, b)
        return a.DistanceSquared < b.DistanceSquared
    end)

    local queue = {}
    local seen = {}

    for _, candidate in ipairs(candidates) do
        if #queue >= limit then
            break
        end

        if candidate.Titan
            and not seen[candidate.Titan] then

            seen[candidate.Titan] = true
            queue[#queue + 1] = candidate.Part
        end
    end

    return queue
end

function V4BlasterNapeLock.AimAt(part)
    if not part or not part.Parent then
        return false
    end

    local position = part.Position

    pcall(function()
        local camera = Workspace.CurrentCamera

        if camera then
            camera.CFrame = CFrame.lookAt(camera.CFrame.Position, position)

            -- Hellfire Barrage calls Spears.Get_Location() for every shot.
            -- That function reads UIS:GetMouseLocation(), so camera steering alone
            -- is not enough when the player's cursor is off-center. Move the real
            -- virtual cursor onto the projected live nape every lock tick.
            local screenPoint, onScreen = camera:WorldToScreenPoint(position)
            if onScreen then
                VirtualInputManager:SendMouseMoveEvent(
                    math.floor(screenPoint.X + 0.5),
                    math.floor(screenPoint.Y + 0.5),
                    game
                )
            end
        end

        if rootPart and rootPart.Parent then
            local flatTarget = Vector3.new(
                position.X,
                rootPart.Position.Y,
                position.Z
            )

            if (flatTarget - rootPart.Position).Magnitude > 0.1 then
                rootPart.CFrame = CFrame.lookAt(rootPart.Position, flatTarget)
            end
        end
    end)

    return true
end

function V4BlasterNapeLock.Start(skillId, duration, center)
    local id = tostring(skillId)
    local dynamicBladeSweep =
        Config.BladeBlasterDynamicSweepEnabled == true
        and (id == "14" or id == "23")

    local targetCount
    if id == "135" then
        targetCount = 4
    elseif id == "126" then
        targetCount = 3
    elseif id == "23" then
        targetCount = math.max(4, math.floor(tonumber(Config.BladeBlasterTorrentialTargets) or 18))
    elseif id == "14" then
        targetCount = math.max(3, math.floor(tonumber(Config.BladeBlasterDrillTargets) or 8))
    else
        targetCount = 3
    end

    local queue = V4BlasterNapeLock.BuildQueue(targetCount, center)

    if #queue == 0 then
        V4BlasterNapeLock.Status = "No live napes"
        return false
    end

    V4BlasterNapeLock.Token += 1
    local token = V4BlasterNapeLock.Token

    V4BlasterNapeLock.Active = true
    V4BlasterNapeLock.Queue = queue
    V4BlasterNapeLock.SkillId = id
    V4BlasterNapeLock.Center = center
    V4BlasterNapeLock.Dynamic = dynamicBladeSweep
    V4BlasterNapeLock.TargetCount = targetCount
    V4BlasterNapeLock.LastRefreshAt = os.clock()

    task.spawn(function()
        local started = os.clock()
        local totalDuration = math.max(0.6, tonumber(duration) or 1.8)
        local refreshDelay = math.max(0.04, tonumber(Config.BladeBlasterSweepRefresh) or 0.080)
        local minimumDwell = math.max(0.025, tonumber(Config.BladeBlasterTargetDwellMin) or 0.055)
        local activeQueue = queue
        local lastRefresh = 0

        local label =
            id == "135" and "Meteoric"
            or id == "126" and "Hellfire"
            or id == "23" and "Torrential"
            or id == "14" and "Drill"
            or ("Skill " .. id)

        while V4BlasterNapeLock.Active
            and V4BlasterNapeLock.Token == token
            and os.clock() - started < totalDuration do

            local now = os.clock()
            local elapsed = now - started

            if dynamicBladeSweep and now - lastRefresh >= refreshDelay then
                lastRefresh = now
                local rebuilt = V4BlasterNapeLock.BuildQueue(targetCount, center)
                if #rebuilt > 0 then
                    activeQueue = rebuilt
                    V4BlasterNapeLock.Queue = rebuilt
                    V4BlasterNapeLock.LastRefreshAt = now
                end
            end

            local shotCount = #activeQueue
            if shotCount <= 0 then
                V4BlasterNapeLock.Status = label .. " • no live napes"
                task.wait(0.016)
                continue
            end

            local index
            if dynamicBladeSweep then
                local idealDwell = totalDuration / math.max(1, targetCount)
                local dwell = math.max(minimumDwell, idealDwell)
                index = (math.floor(elapsed / dwell) % shotCount) + 1
            else
                local shotWindow = totalDuration / math.max(1, shotCount)
                index = math.clamp(math.floor(elapsed / shotWindow) + 1, 1, shotCount)
            end

            local part = activeQueue[index]
            if not part or not part.Parent then
                for _, fallback in ipairs(activeQueue) do
                    if fallback and fallback.Parent then
                        part = fallback
                        break
                    end
                end
            end

            if part then
                V4BlasterNapeLock.AimAt(part)
                V4BlasterNapeLock.Status = string.format(
                    "%s nape %d/%d%s",
                    label,
                    index,
                    shotCount,
                    dynamicBladeSweep and " LIVE" or ""
                )
            end

            task.wait(0.016)
        end

        if V4BlasterNapeLock.Token == token then
            V4BlasterNapeLock.Active = false
            V4BlasterNapeLock.Dynamic = false
            V4BlasterNapeLock.Status = "Idle"
        end
    end)

    print(
        "[SliceHub V6.0.0][BLASTER-SWEEP]",
        "skill=" .. id,
        "targets=" .. tostring(#queue),
        "dynamic=" .. tostring(dynamicBladeSweep)
    )

    return true
end

function V4BlasterNapeLock.Stop()
    V4BlasterNapeLock.Token += 1
    V4BlasterNapeLock.Active = false
    V4BlasterNapeLock.Queue = {}
    V4BlasterNapeLock.Dynamic = false
    V4BlasterNapeLock.TargetCount = 0
    V4BlasterNapeLock.Center = nil
    V4BlasterNapeLock.Status = "Idle"
end

;(function() -- scoped so Titan Blaster does not blow Luau's 200 local-register limit
    local TitanBlasterSkillInfo = {
        ["126"] = {
            Name = "Hellfire Barrage",
            Short = "HELLFIRE",
            Cooldown = 50,
            Cost = 3,
            Lock = Config.TitanBlasterHellfireLock or 1.72,
            Weapon = "Spears",
        },
        ["135"] = {
            Name = "Meteoric Rain",
            Short = "METEORIC",
            Cooldown = 50,
            Cost = 4,
            Lock = Config.TitanBlasterMeteoricLock or 3.10,
            Weapon = "Spears",
        },
        ["14"] = {
            Name = "Drill Thrust",
            Short = "DRILL",
            Cooldown = 45,
            Cost = 0,
            Lock = Config.TitanBlasterDrillLock or 1.82,
            Weapon = "Blades",
        },
        ["23"] = {
            Name = "Torrential Steel",
            Short = "TORRENTIAL",
            Cooldown = 50,
            Cost = 0,
            Lock = Config.TitanBlasterTorrentialLock or 2.42,
            Weapon = "Blades",
        },
    }

	local RipperUiRoots = {}
	local RipperUiState = {
		[1] = {RootFound = false, HasAbility = false, Ready = false, Remaining = nil, Source = "fallback"},
		[2] = {RootFound = false, HasAbility = false, Ready = false, Remaining = nil, Source = "fallback"},
		[3] = {RootFound = false, HasAbility = false, Ready = false, Remaining = nil, Source = "fallback"},
		[4] = {RootFound = false, HasAbility = false, Ready = false, Remaining = nil, Source = "fallback"},
		[5] = {RootFound = false, HasAbility = false, Ready = false, Remaining = nil, Source = "fallback"},
	}
	local RipperLearnedCooldown = {
		[1] = Config.TitanRipperDefaultCooldown,
		[2] = Config.TitanRipperDefaultCooldown,
		[3] = Config.TitanRipperSlot3Cooldown or Config.TitanRipperDefaultCooldown,
		[4] = Config.TitanRipperSlot4Cooldown or Config.TitanRipperDefaultCooldown,
		[5] = Config.TitanRipperDefaultCooldown,
	}
	local RipperLastCastAt = {}
	local RipperPendingLearn = {}
	local RipperSawCooldownAfterCast = {}
	local RipperEmptyUntil = {} -- v116: empty/failed slots get ignored so alt accounts enter BladeOnly fast.
	local LastRipperUiScanAt = 0
	local RipperUiScanDelay = 0.16

	local function getRipperSlotByNumber(slotNumber)
		for _, slot in ipairs(RipperSlots) do
			if slot.Number == slotNumber then
				return slot
			end
		end
		return nil
	end

	local function getRipperFallbackCooldown(slotNumber)
        local state = RipperUiState[slotNumber]
        local exactInfo =
            state
            and state.SkillId
            and TitanBlasterSkillInfo[state.SkillId]
            or nil

        if exactInfo and tonumber(exactInfo.Cooldown) then
            return tonumber(exactInfo.Cooldown)
        end

		local learned = tonumber(RipperLearnedCooldown[slotNumber])
		if learned and learned >= 8 and learned <= 90 then
			return learned
		end

		local slot = getRipperSlotByNumber(slotNumber)
		return (slot and tonumber(slot.Cooldown))
            or (tonumber(Config.TitanBlasterFallbackCooldown) or 50)
	end

	local function ripperSlotAllowed(slotNumber)
		local key = "AbilitySlot" .. tostring(slotNumber) .. "Enabled"
		local blockedUntil = tonumber(RipperEmptyUntil[slotNumber]) or 0
		if os.clock() < blockedUntil then return false end
		return not State or State[key] ~= false
	end

	local function ripperCleanText(value)
		local text = tostring(value or "")
		text = string.gsub(text, "<.->", "")
		text = string.gsub(text, "^%s+", "")
		text = string.gsub(text, "%s+$", "")
		return text
	end

	local function ripperLower(value)
		return string.lower(ripperCleanText(value))
	end

    local function titanBlasterSkillIdFromRoot(root)
        if not root then return nil end

        local node = root

        while node and node ~= playerGui do
            local skillId = nil

            pcall(function()
                skillId = node:GetAttribute("Skill")
            end)

            if skillId ~= nil and tostring(skillId) ~= "" then
                return tostring(skillId)
            end

            node = node.Parent
        end

        for _, object in ipairs(root:GetDescendants()) do
            local skillId = nil

            pcall(function()
                skillId = object:GetAttribute("Skill")
            end)

            if skillId ~= nil and tostring(skillId) ~= "" then
                return tostring(skillId)
            end
        end

        return nil
    end

    local function titanBlasterInfoForSlot(slotNumber)
        local state = RipperUiState[slotNumber]
        local skillId = state and state.SkillId or nil

        return skillId and TitanBlasterSkillInfo[skillId] or nil
    end

    local function titanBlasterAmmoAllows(info)
        if not info or info.Weapon ~= "Spears" then
            return true
        end

        local ammo = V35Spears and V35Spears.ReadAmmo and V35Spears.ReadAmmo() or nil

        if ammo == nil then
            return false
        end

        -- Preserve one spear so V3.6.1 safety refill never falls into the 0-ammo drop state.
        return ammo >= (tonumber(info.Cost) or 0) + 1
    end

	local function objectInsideTitanControlGui(object)
		local node = object
		while node do
			if node.Name == "TitanControlMenu" then
				return true
			end
			node = node.Parent
		end
		return false
	end

	local function hotbarRootLooksVisible(root)
		return root and root:IsA("GuiObject") and root.Parent and not objectInsideTitanControlGui(root) and guiObjectIsActuallyVisible(root)
	end

	local function rootHasSlotText(root, slotNumber)
		local targetText = tostring(slotNumber)
		for _, child in ipairs(root:GetDescendants()) do
			if (child:IsA("TextLabel") or child:IsA("TextButton") or child:IsA("TextBox")) and guiObjectIsActuallyVisible(child) then
				if ripperCleanText(child.Text) == targetText then
					return true
				end
			end
		end
		return false
	end

	local function candidateHotbarScore(object, slotNumber)
		if not object:IsA("GuiObject") or not guiObjectIsActuallyVisible(object) or objectInsideTitanControlGui(object) then
			return -math.huge
		end

		local size = object.AbsoluteSize
		if size.X < 24 or size.Y < 24 or size.X > 190 or size.Y > 190 then
			return -math.huge
		end

		local slotText = tostring(slotNumber)
		local score = 0
		local node = object
		for depth = 0, 5 do
			if not node or node == playerGui then break end
			local name = ripperLower(node.Name)
			if string.find(name, "hotbar", 1, true) or string.find(name, "ability", 1, true) or string.find(name, "skill", 1, true) or string.find(name, "slot", 1, true) or string.find(name, "toolbar", 1, true) then
				score += 7 - math.min(depth, 5)
			end
			if string.find(name, "slot" .. slotText, 1, true) or string.find(name, "slot_" .. slotText, 1, true) or name == slotText then
				score += 8
			end
			node = node.Parent
		end

		if object.Name == slotText then
			score += 8
		end
		if rootHasSlotText(object, slotNumber) then
			score += 10
		end

		return score
	end

	local function findHotbarSlotRoot(slotNumber)
		local cached = RipperUiRoots[slotNumber]
		if hotbarRootLooksVisible(cached) then
			return cached
		end

		local bestObject = nil
		local bestScore = -math.huge
		for _, object in ipairs(playerGui:GetDescendants()) do
			local score = candidateHotbarScore(object, slotNumber)
			if score > bestScore then
				bestObject = object
				bestScore = score
			end
		end

		if bestObject and bestScore >= 9 then
			RipperUiRoots[slotNumber] = bestObject
			return bestObject
		end
		return nil
	end

	local function parseCooldownNumber(text)
		text = ripperCleanText(text)
		text = string.gsub(text, "s$", "")
		local numberText = string.match(text, "^(%d+%.?%d*)$")
		local value = tonumber(numberText)
		if value and value > 0 and value <= 120 then
			return value
		end
		return nil
	end

	local function textLooksLikeReady(text)
		local lower = ripperLower(text)
		return lower == "ready" or lower == "rdy" or lower == "go" or lower == "0" or lower == "0.0"
	end

	local function slotRootHasAbilityVisual(root, slotNumber)
		if not root then return false end
		for _, object in ipairs(root:GetDescendants()) do
			if (object:IsA("ImageLabel") or object:IsA("ImageButton")) and guiObjectIsActuallyVisible(object) then
				local image = tostring(object.Image or "")
				local name = ripperLower(object.Name)
				local size = object.AbsoluteSize
				if image ~= "" and size.X >= 14 and size.Y >= 14 then
					if string.find(name, "icon", 1, true) or string.find(name, "skill", 1, true) or string.find(name, "ability", 1, true) or string.find(name, "image", 1, true) then
						return true
					end
					if size.X <= root.AbsoluteSize.X * 0.85 and size.Y <= root.AbsoluteSize.Y * 0.85 and (object.ImageTransparency or 0) < 0.95 then
						return true
					end
				end
			elseif (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) and guiObjectIsActuallyVisible(object) then
				local clean = ripperLower(object.Text)
				if clean ~= "" and clean ~= tostring(slotNumber) and not parseCooldownNumber(clean) and not textLooksLikeReady(clean) then
					if string.find(clean, "ripper", 1, true) or string.find(clean, "titan", 1, true) or string.find(clean, "skill", 1, true) then
						return true
					end
				end
			end
		end
		return false
	end

	local function getSlotCooldownRemainingFromRoot(root, slotNumber)
		if not root then return nil, false end
		local bestValue = nil
		local bestScore = -math.huge
		local slotText = tostring(slotNumber)
		local sawReadyText = false

		for _, object in ipairs(root:GetDescendants()) do
			if (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) and guiObjectIsActuallyVisible(object) then
				local text = ripperCleanText(object.Text)
				if textLooksLikeReady(text) then
					sawReadyText = true
				end

				local value = parseCooldownNumber(text)
				if value then
					local name = ripperLower(object.Name)
					local score = 0
					if string.find(name, "cool", 1, true) or string.find(name, "cd", 1, true) or string.find(name, "timer", 1, true) or string.find(name, "count", 1, true) then
						score += 10
					end
					if math.abs(value - slotNumber) < 0.01 and text == slotText then
						score -= 9
					end
					if object.TextSize and object.TextSize >= 13 then
						score += 2
					end
					local rootPos = root.AbsolutePosition
					local rootSize = root.AbsoluteSize
					local objectPos = object.AbsolutePosition
					local objectCenterX = objectPos.X + object.AbsoluteSize.X / 2
					local objectCenterY = objectPos.Y + object.AbsoluteSize.Y / 2
					local rootCenterX = rootPos.X + rootSize.X / 2
					local rootCenterY = rootPos.Y + rootSize.Y / 2
					if math.abs(objectCenterX - rootCenterX) <= rootSize.X * 0.35 and math.abs(objectCenterY - rootCenterY) <= rootSize.Y * 0.35 then
						score += 4
					end
					if score > bestScore then
						bestScore = score
						bestValue = value
					end
				end
			end
		end

		if bestValue and bestScore >= -1 then
			return bestValue, true
		end
		return nil, sawReadyText
	end

	local function hotbarSlotLooksSelected(slotNumber)
		local root = findHotbarSlotRoot(slotNumber)
		if not root then return false end

		for _, object in ipairs(root:GetDescendants()) do
			if object:IsA("UIStroke") then
				local thickness = tonumber(object.Thickness) or 0
				local transparency = tonumber(object.Transparency) or 1
				if thickness >= 1.5 and transparency <= 0.55 then
					return true
				end
			end
		end

		if character then
			local tool = character:FindFirstChildOfClass("Tool")
			if tool then
				local name = ripperLower(tool.Name)
				if string.find(name, "ripper", 1, true) or string.find(name, "titan", 1, true) or string.find(name, "skill", 1, true) then
					return true
				end
			end
		end

		return false
	end

	local function scanRipperSlotState(slotNumber, now)
		now = now or os.clock()
		local state = RipperUiState[slotNumber]
		local root = findHotbarSlotRoot(slotNumber)

		if root then
			local remaining, reliable = getSlotCooldownRemainingFromRoot(root, slotNumber)
			local hasVisual = slotRootHasAbilityVisual(root, slotNumber)
            local skillId = titanBlasterSkillIdFromRoot(root)
            local skillInfo = skillId and TitanBlasterSkillInfo[skillId] or nil
            local weapon = player and tostring(player:GetAttribute("Weapon") or "") or ""
            local exactWeaponMatch =
                skillInfo ~= nil
                and (
                    (weapon == "Spears" and skillInfo.Weapon == "Spears")
                    or (weapon ~= "Spears" and skillInfo.Weapon == "Blades")
                )

			state.RootFound = true
            state.SkillId = skillId
            state.AbilityName = skillInfo and skillInfo.Name or nil
			state.HasAbility = exactWeaponMatch
			state.Source = state.HasAbility
                and (reliable and "exact-ui" or "exact-ready")
                or (hasVisual and "other-skill" or "empty")
			state.Remaining = remaining
			state.Selected = hotbarSlotLooksSelected(slotNumber)
			if not state.HasAbility then
				state.Ready = false
				state.Remaining = nil
				nextRipperReadyAt[slotNumber] = now + 1.5
				return state
			end
			if remaining and remaining > 0.18 then
				state.Ready = false
				nextRipperReadyAt[slotNumber] = now + remaining
				if RipperPendingLearn[slotNumber] and RipperLastCastAt[slotNumber] then
					RipperSawCooldownAfterCast[slotNumber] = true
					local estimatedCooldown = (now - RipperLastCastAt[slotNumber]) + remaining
					if estimatedCooldown >= 8 and estimatedCooldown <= 90 then
						RipperLearnedCooldown[slotNumber] = estimatedCooldown
						local slot = getRipperSlotByNumber(slotNumber)
						if slot then slot.Cooldown = estimatedCooldown end
					end
				end
			else
				state.Ready = true
				state.Remaining = nil
				nextRipperReadyAt[slotNumber] = 0
				if RipperPendingLearn[slotNumber] and RipperSawCooldownAfterCast[slotNumber] and RipperLastCastAt[slotNumber] then
					local measuredCooldown = now - RipperLastCastAt[slotNumber]
					if measuredCooldown >= 8 and measuredCooldown <= 90 then
						RipperLearnedCooldown[slotNumber] = measuredCooldown
						local slot = getRipperSlotByNumber(slotNumber)
						if slot then slot.Cooldown = measuredCooldown end
					end
					RipperPendingLearn[slotNumber] = false
					RipperSawCooldownAfterCast[slotNumber] = false
				end
			end
		else
			local remaining = math.max(0, (nextRipperReadyAt[slotNumber] or 0) - now)
			state.RootFound = false
			state.HasAbility = false
            state.SkillId = nil
            state.AbilityName = nil
			state.Source = "missing"
			state.Remaining = remaining > 0 and remaining or nil
			state.Ready = false
			state.Selected = false
		end

		return state
	end

	local function refreshRipperUiState(force)
		local now = os.clock()
		if not force and now - LastRipperUiScanAt < RipperUiScanDelay then
			return
		end
		LastRipperUiScanAt = now
		for _, slot in ipairs(RipperSlots) do
			scanRipperSlotState(slot.Number, now)
		end
	end

	local function getReadyRipperSlot(now)
		refreshRipperUiState(false)
		now = now or os.clock()

        local weapon = player and tostring(player:GetAttribute("Weapon") or "") or ""
        local packCount = tonumber(V36PackDrain and V36PackDrain.PackCount) or 0

        local desiredSkillOrder

        if weapon == "Spears" then
            desiredSkillOrder =
                packCount >= 6
                and {"135", "126"}
                or {"126", "135"}
        else
            desiredSkillOrder =
                packCount >= 6
                and {"23", "14"}
                or {"14", "23"}
        end

        for _, desiredSkillId in ipairs(desiredSkillOrder) do
            for index, slot in ipairs(RipperSlots) do
                local state = RipperUiState[slot.Number]
                local fallbackReady = now >= (nextRipperReadyAt[slot.Number] or 0)
                local info = state and state.SkillId and TitanBlasterSkillInfo[state.SkillId] or nil

                if state
                    and state.SkillId == desiredSkillId
                    and state.HasAbility
                    and ripperSlotAllowed(slot.Number)
                    and (state.Ready or fallbackReady)
                    and titanBlasterAmmoAllows(info) then

                    ripperSlotCursor = (index % #RipperSlots) + 1
                    return slot
                end
            end
        end

		return nil
	end

	getRipperCooldownText = function()
		refreshRipperUiState(false)
		local now = os.clock()
		local parts = {}
		for _, slot in ipairs(RipperSlots) do
			local slotNumber = slot.Number
            local state = RipperUiState[slotNumber]
            local info = state and state.SkillId and TitanBlasterSkillInfo[state.SkillId] or nil

            if info then
                local label = tostring(info.Short or info.Name or ("S" .. tostring(slotNumber)))

                if not ripperSlotAllowed(slotNumber) then
                    table.insert(parts, label .. " OFF")
                else
                    local remaining =
                        state.Remaining
                        or math.max(0, (nextRipperReadyAt[slotNumber] or 0) - now)

                    if remaining and remaining > 0 then
                        table.insert(parts, string.format("%s %ds", label, math.ceil(remaining)))
                    else
                        table.insert(parts, label .. " READY")
                    end
                end
            end
		end
		return table.concat(parts, " | ")
	end

	TitanControlRipperAvailable = function()
		refreshRipperUiState(false)
		for _, slot in ipairs(RipperSlots) do
			local state = RipperUiState[slot.Number]
			if ripperSlotAllowed(slot.Number) and state and state.HasAbility then
				return true
			end
		end
		return false
	end

	local function waitForRipperSlotEquip(slotNumber, timeout)
		local started = os.clock()
		while os.clock() - started <= (timeout or 0.18) do
			if hotbarSlotLooksSelected(slotNumber) then
				return true
			end
			task.wait(0.025)
		end
		return false
	end

	useTitanRipper = function()
        -- V5.7.4: during a short Colossal P2 Eren-defense burst, preserve Titan
        -- Blaster cooldown/ammo for Bertholdt. Blades + Infinite Spears clear adds.
        if V4RaidDirector
            and V4RaidDirector.RaidName == "Colossal Raid"
            and V55ColossalDirector
            and V55ColossalDirector.Stage == "P2 BOSS"
            and V55ColossalDirector.DefenseMode == true then
            return nil
        end

		if not State.TitanRipperEnabled
            or ripperSequenceRunning
            or refillSequenceRunning
            or StationRefill.Running then
            return nil
        end

        if V35Spears and V35Spears.Busy then
            return nil
        end

		local now = os.clock()
		local slot = getReadyRipperSlot(now)
		if not slot then return nil end

		local slotNumber = slot.Number
        local state = RipperUiState[slotNumber]
        local skillId = state and state.SkillId or nil
        local skillInfo = skillId and TitanBlasterSkillInfo[skillId] or nil

        if not skillInfo then
            return nil
        end

        if not titanBlasterAmmoAllows(skillInfo) then
            return nil
        end

		local fallbackCooldown = getRipperFallbackCooldown(slotNumber)

		nextRipperReadyAt[slotNumber] = now + fallbackCooldown
		RipperUiState[slotNumber].Ready = false
		RipperUiState[slotNumber].Remaining = fallbackCooldown
		ripperSequenceRunning = true

		task.spawn(function()
            local weapon = player and tostring(player:GetAttribute("Weapon") or "") or ""
            local aimPart, packCount, aimPosition = chooseRipperAimPart()

            aimPosition =
                aimPosition
                or (aimPart and aimPart.Position)
                or (V36PackDrain and V36PackDrain.Center)
                or CombatAnchorRuntime.AimPosition

            if weapon == "Spears" and typeof(aimPosition) == "Vector3" then
                pcall(function()
                    local stageCFrame

                    if skillId == tostring(Config.TitanBlasterMeteoricSkillId or "135") then
                        local stagePosition =
                            aimPosition
                            + Vector3.new(
                                0,
                                tonumber(Config.TitanBlasterMeteoricStageHeight) or 58,
                                0
                            )

                        stageCFrame = CFrame.lookAt(stagePosition, aimPosition)
                    else
                        local stagePosition =
                            aimPosition
                            + Vector3.new(
                                0,
                                tonumber(Config.TitanBlasterHellfireStageHeight) or 82,
                                tonumber(Config.TitanBlasterHellfireBackOffset) or 120
                            )

                        stageCFrame = CFrame.lookAt(stagePosition, aimPosition)
                    end

                    if character and character.Parent then
                        character:PivotTo(stageCFrame)
                    end

                    if rootPart and rootPart.Parent then
                        rootPart.AssemblyLinearVelocity = Vector3.zero
                        rootPart.AssemblyAngularVelocity = Vector3.zero
                    end

                    local camera = Workspace.CurrentCamera

                    if camera then
                        camera.CFrame = CFrame.lookAt(camera.CFrame.Position, aimPosition)
                    end
                end)

                task.wait(0.04)
            elseif aimPosition then
                local camera = Workspace.CurrentCamera

                if camera then
                    pcall(function()
                        camera.CFrame = CFrame.lookAt(camera.CFrame.Position, aimPosition)
                    end)
                end

                task.wait(0.01)
            end

			if not State.FarmEnabled or not State.TitanRipperEnabled then
				nextRipperReadyAt[slotNumber] = 0
				ripperSequenceRunning = false
				return
			end

			local castTime = os.clock()
			RipperLastCastAt[slotNumber] = castTime
			RipperPendingLearn[slotNumber] = true
			RipperSawCooldownAfterCast[slotNumber] = false

            V35Spears.LastStatus =
                "Titan Blaster: "
                .. tostring(skillInfo.Name)
                .. " | Pack "
                .. tostring(packCount or 0)

            print(
                "[SliceHub V4][TITAN-BLASTER]",
                tostring(skillInfo.Name),
                "skill=" .. tostring(skillId),
                "slot=" .. tostring(slotNumber),
                "pack=" .. tostring(packCount or 0)
            )

            local blasterAliveBefore = getCachedAliveTitanCount()
            local shouldSweep =
                (skillId == "126" or skillId == "135")
                or (
                    Config.BladeBlasterDynamicSweepEnabled == true
                    and (skillId == "14" or skillId == "23")
                )

            if shouldSweep then
                V4BlasterNapeLock.Start(
                    skillId,
                    tonumber(skillInfo.Lock) or 1.8,
                    aimPosition
                )
            end

            if V58BladeEngine then
                V58BladeEngine.SetPhase(
                    "BLASTER_LOCK",
                    tostring(skillInfo.Short or skillInfo.Name),
                    os.clock() + math.max(0.25, tonumber(skillInfo.Lock) or 1.75)
                )
            end

            -- Hotbar keys invoke Core.Skills.Use directly. Nape Lock steers the viewport ray during the firing window.
			simulateHumanKeyPress(slot.KeyCode)

            local cooldownAttribute =
                "Skill_" .. tostring(slotNumber)

            local accepted = false
            local acceptedStarted = os.clock()

            while os.clock() - acceptedStarted < 0.36 do
                local value = nil

                pcall(function()
                    value = player:GetAttribute(cooldownAttribute)
                end)

                if value ~= nil then
                    accepted = true
                    break
                end

                task.wait(0.025)
            end

            if not accepted and State.FarmEnabled then
                simulateHumanKeyPress(slot.KeyCode)

                local retryStarted = os.clock()

                while os.clock() - retryStarted < 0.30 do
                    local value = nil

                    pcall(function()
                        value = player:GetAttribute(cooldownAttribute)
                    end)

                    if value ~= nil then
                        accepted = true
                        break
                    end

                    task.wait(0.025)
                end
            end

            if not accepted then
                V35Spears.LastStatus =
                    "Titan Blaster cast not confirmed: "
                    .. tostring(skillInfo.Name)

                RipperEmptyUntil[slotNumber] = os.clock() + 2.0
                nextRipperReadyAt[slotNumber] = os.clock() + 2.0
                RipperPendingLearn[slotNumber] = false

                if V4BlasterNapeLock then
                    V4BlasterNapeLock.Stop()
                end

                ripperSequenceRunning = false
                return
            end

			nextRipperReadyAt[slotNumber] =
                castTime
                + fallbackCooldown
                + Config.TitanRipperSafetyMargin

            local lockDuration =
                math.max(0.25, tonumber(skillInfo.Lock) or 1.75)

            task.wait(lockDuration)

            local blasterAliveAfter = getCachedAliveTitanCount()
            local blasterKills = math.max(0, blasterAliveBefore - blasterAliveAfter)
            if V58BladeEngine then
                V58BladeEngine.LastBlasterName = tostring(skillInfo.Short or skillInfo.Name)
                V58BladeEngine.LastBlasterKills = blasterKills
                V58BladeEngine.LastBlasterPack = tonumber(packCount) or 0
                V58BladeEngine.LastBlasterAt = os.clock()
                V58BladeEngine.SetPhase(
                    "READY",
                    string.format("%s K%d / P%d", tostring(skillInfo.Short or skillInfo.Name), blasterKills, tonumber(packCount) or 0),
                    os.clock()
                )
            end

            print(
                "[SliceHub V6.0.0][BLASTER-RESULT]",
                tostring(skillInfo.Name),
                "pack=" .. tostring(packCount or 0),
                "kills=" .. tostring(blasterKills),
                "alive=" .. tostring(blasterAliveBefore) .. "->" .. tostring(blasterAliveAfter)
            )

            if weapon == "Spears"
                and V35Spears
                and V35Spears.ClearDrainPack then

                V35Spears.ClearDrainPack(
                    "Titan Blaster " .. tostring(skillInfo.Short or skillInfo.Name)
                )
            end

			refreshRipperUiState(true)

            if V4BlasterNapeLock then
                V4BlasterNapeLock.Stop()
            end

            CachedBladeTool = nil
			ripperSequenceRunning = false
		end)

		return slotNumber
	end
end)()

---------------------------------------------------------------------
-- V5 EQUIPPED BUFF SKILL ENGINE
---------------------------------------------------------------------

V5BuffEngine = V5BuffEngine or {
    Skills = {
        ["93"] = {Name = "Order: Advance", StateKey = "BuffOrderAdvanceEnabled", Cooldown = 55},
        ["95"] = {Name = "Black Flare", StateKey = "BuffBlackFlareEnabled", Cooldown = 35},
        ["97"] = {Name = "Order: Rage", StateKey = "BuffOrderRageEnabled", Cooldown = 85},
        ["158"] = {Name = "Founder's Order", StateKey = "BuffFoundersOrderEnabled", Cooldown = 90},
        ["163"] = {Name = "Order: Revolution", StateKey = "BuffOrderRevolutionEnabled", Cooldown = 135},
    },
    Detected = {},
    LastCast = {},
    LastScanAt = 0,
    Status = "No equipped buff skills detected",
}

function V5BuffEngine.SlotFromObject(object)
    local node = object

    for _ = 1, 6 do
        if not node or node == playerGui then break end

        local lowerName = string.lower(tostring(node.Name or ""))
        local byName = string.match(lowerName, "slot[_%- ]*([1-5])")
            or string.match(lowerName, "^([1-5])$")

        if byName then
            return tonumber(byName)
        end

        if node:IsA("GuiObject") then
            local size = node.AbsoluteSize
            if size.X >= 24 and size.Y >= 24 and size.X <= 190 and size.Y <= 190 then
                for _, child in ipairs(node:GetDescendants()) do
                    if child:IsA("TextLabel") or child:IsA("TextButton") or child:IsA("TextBox") then
                        local clean = string.gsub(tostring(child.Text or ""), "%s+", "")
                        local slot = tonumber(clean)
                        if slot and slot >= 1 and slot <= 5 then
                            return slot
                        end
                    end
                end
            end
        end

        node = node.Parent
    end

    return nil
end

function V5BuffEngine.Scan(force)
    local now = os.clock()
    if not force and now - (V5BuffEngine.LastScanAt or 0) < 0.55 then
        return V5BuffEngine.Detected
    end

    V5BuffEngine.LastScanAt = now
    local detected = {}

    for _, object in ipairs(playerGui:GetDescendants()) do
        local skillId = nil
        pcall(function() skillId = object:GetAttribute("Skill") end)
        skillId = skillId ~= nil and tostring(skillId) or nil

        if skillId and V5BuffEngine.Skills[skillId] then
            local slot = V5BuffEngine.SlotFromObject(object)
            if slot then
                detected[skillId] = slot
            end
        end
    end

    V5BuffEngine.Detected = detected

    local parts = {}
    for skillId, slot in pairs(detected) do
        local info = V5BuffEngine.Skills[skillId]
        parts[#parts + 1] = tostring(info.Name) .. " [" .. tostring(slot) .. "]"
    end
    table.sort(parts)

    V5BuffEngine.Status = #parts > 0
        and ("Detected: " .. table.concat(parts, " • "))
        or "No equipped active buff skills detected"

    return detected
end

function V5BuffEngine.KeyForSlot(slot)
    local map = {
        [1] = Enum.KeyCode.One,
        [2] = Enum.KeyCode.Two,
        [3] = Enum.KeyCode.Three,
        [4] = Enum.KeyCode.Four,
        [5] = Enum.KeyCode.Five,
    }
    return map[tonumber(slot)]
end

function V5BuffEngine.CooldownValue(slot)
    if not slot then return nil end
    local value = nil
    pcall(function() value = player:GetAttribute("Skill_" .. tostring(slot)) end)
    return value
end

function V5BuffEngine.Ready(slot)
    local value = V5BuffEngine.CooldownValue(slot)
    if value == nil or value == false then return true end
    if type(value) == "number" then return value <= 0 end
    if type(value) == "string" then
        local clean = string.lower(string.gsub(value, "%s+", ""))
        if clean == "" or clean == "ready" or clean == "false" then return true end
        local numeric = tonumber(string.match(clean, "[-%d%.]+"))
        if numeric then return numeric <= 0 end
    end
    return false
end

function V5BuffEngine.CastPreCannonBurst()
    if not State.AutoUseBuffsEnabled then
        V5BuffEngine.Status = "Pre-cannon buffs disabled"
        return "Pre-cannon buffs disabled"
    end

    -- V5.7.6: Fritz / Founder's Order is prioritized first because live multi-run
    -- tests showed Black Flare + Rage were reliable while Founder's Order was
    -- the one being lost before cannon mount.
    -- V5.7.6 empirical sequence from live runs: Black Flare reliably primes the
    -- hotbar state, then Founder's Order, then remaining support, with Rage last.
    local order = {"95", "158", "93", "163", "97"}
    local castNames = {}
    V5BuffEngine.LastAttempt = V5BuffEngine.LastAttempt or {}

    local function waitForCooldownStart(slot, timeout)
        local started = os.clock()
        while os.clock() - started < timeout do
            if not V5BuffEngine.Ready(slot) then
                return true
            end
            task.wait(0.05)
        end
        return not V5BuffEngine.Ready(slot)
    end

    local function pressFor(key, holdSeconds)
        task.wait(0.02)
        VirtualInputManager:SendKeyEvent(true, key, false, game)
        task.wait(math.max(0.04, tonumber(holdSeconds) or 0.04))
        VirtualInputManager:SendKeyEvent(false, key, false, game)
    end

    for _, skillId in ipairs(order) do
        -- Re-scan before every cast. Some hotbar trees rebuild after a support
        -- skill fires, and keeping a stale slot map was enough to skip Fritz.
        local detected = V5BuffEngine.Scan(true)
        local slot = detected[skillId]
        local info = V5BuffEngine.Skills[skillId]

        if slot and info and State[info.StateKey] ~= false and V5BuffEngine.Ready(slot) then
            local key = V5BuffEngine.KeyForSlot(slot)
            if key then
                local isRage = skillId == "97"
                local isFounder = skillId == "158"
                local maxAttempts = isFounder and 4 or (isRage and 3 or 2)
                V5BuffEngine._Confirmed = false

                if isFounder then
                    task.wait(0.35)
                elseif isRage then
                    task.wait(0.55)
                end

                for attempt = 1, maxAttempts do
                    V5BuffEngine.Status = string.format(
                        "Pre-cannon cast: %s (%d/%d)",
                        tostring(info.Name), attempt, maxAttempts
                    )
                    V5BuffEngine.LastAttempt[skillId] = os.clock()

                    if isFounder then
                        -- Slightly longer held input for Fritz/Founder's Order.
                        -- Alternate the hold length on retries instead of spamming
                        -- identical 40ms taps that live tests showed could be ignored.
                        pressFor(key, attempt == 1 and 0.12 or 0.18)
                    else
                        simulateHumanKeyPress(key)
                    end

                    V5BuffEngine._Confirmed = waitForCooldownStart(slot, isFounder and 1.35 or (isRage and 1.05 or 0.75))
                    if V5BuffEngine._Confirmed then break end

                    -- Refresh slot mapping before retrying the same skill.
                    task.wait(isFounder and 0.60 or (isRage and 0.50 or 0.30))
                    detected = V5BuffEngine.Scan(true)
                    slot = detected[skillId] or slot
                    key = V5BuffEngine.KeyForSlot(slot) or key
                end

                if V5BuffEngine._Confirmed then
                    V5BuffEngine.LastCast[skillId] = os.clock()
                    castNames[#castNames + 1] = tostring(info.Name)
                else
                    castNames[#castNames + 1] = tostring(info.Name) .. "?"
                end

                if isFounder then
                    task.wait(0.75)
                elseif isRage then
                    task.wait(0.45)
                else
                    task.wait(0.30)
                end
            end
        end
    end

    if #castNames > 0 then task.wait(1.00) end

    local summary = #castNames > 0
        and ("Pre-cannon buffs: " .. table.concat(castNames, ", "))
        or "No enabled ready buffs before cannon"
    V5BuffEngine.Status = summary
    return summary
end

function V5BuffEngine.Step()
    local mountedColossalCannon = V55ColossalDirector
        and V4RaidDirector
        and V4RaidDirector.RaidName == "Colossal Raid"
        and V55ColossalDirector.Stage == "P1 CANNON STALL"
        and V55ColossalDirector.Entered == true

    if mountedColossalCannon then
        V5BuffEngine.Status = "Mounted: buffs were applied before cannon entry"
        return false
    end

    if not State.AutoUseBuffsEnabled or not State.FarmEnabled then
        return false
    end
    if V4RaidDirector
        and V4RaidDirector.ShouldPauseCombat
        and V4RaidDirector.ShouldPauseCombat() then
        V5BuffEngine.Status = "Paused for raid transition"
        return false
    end
    if ripperSequenceRunning
        or refillSequenceRunning
        or StationRefill.Running
        or ((V35Spears and V35Spears.Busy) and not mountedColossalCannon) then
        return false
    end

    local detected = V5BuffEngine.Scan(false)
    local now = os.clock()
    V5BuffEngine.LastAttempt = V5BuffEngine.LastAttempt or {}

    -- Deterministic order prevents table iteration from starving a later enabled buff.
    local order = {"93", "95", "97", "158", "163"}
    for _, skillId in ipairs(order) do
        local slot = detected[skillId]
        local info = V5BuffEngine.Skills[skillId]
        if slot and info then
            local allowed = State[info.StateKey] ~= false
            local lastCast = tonumber(V5BuffEngine.LastCast[skillId]) or 0
            local lastAttempt = tonumber(V5BuffEngine.LastAttempt[skillId]) or 0
            local localGap = math.max(2.0, math.min(8.0, (tonumber(info.Cooldown) or 35) * 0.08))

            if allowed
                and now - lastCast >= localGap
                and now - lastAttempt >= 1.25
                and V5BuffEngine.Ready(slot) then

                local key = V5BuffEngine.KeyForSlot(slot)
                if key then
                    V5BuffEngine.LastAttempt[skillId] = now
                    V5BuffEngine.Status = "Casting " .. tostring(info.Name) .. " [" .. tostring(slot) .. "]"
                    task.spawn(function()
                        simulateHumanKeyPress(key)
                        task.wait(0.28)

                        if not V5BuffEngine.Ready(slot) then
                            V5BuffEngine.LastCast[skillId] = os.clock()
                            V5BuffEngine.Status = "Cast confirmed: " .. tostring(info.Name)
                        else
                            -- Input was ignored or the skill was not actually ready; retry soon.
                            V5BuffEngine.Status = "Retry pending: " .. tostring(info.Name)
                        end
                    end)
                    return true
                end
            end
        end
    end

    return false
end

task.spawn(function()
    while true do
        task.wait(0.35)
        local ok, err = pcall(V5BuffEngine.Step)
        if not ok then
            V5BuffEngine.Status = "Buff engine error: " .. tostring(err)
        end
    end
end)

---------------------------------------------------------------------
-- EMERGENCY GRAB ESCAPE ENGINE
---------------------------------------------------------------------

local lastEmergencyGrabSnapAt = 0
local GrabSnapDebounce = 0.85

local function titanFolderNow()
    return Workspace:FindFirstChild(Config.TitansFolderName)
end

local function partBelongsToTitan(part)
    local folder = titanFolderNow()
    return folder ~= nil and part ~= nil and part:IsDescendantOf(folder)
end

local function partBelongsToCharacter(part)
    return character ~= nil and part ~= nil and part:IsDescendantOf(character)
end

local function isGrabJoint(instance)
    return instance
        and (
            instance:IsA("Weld")
            or instance:IsA("WeldConstraint")
            or instance:IsA("ManualWeld")
            or instance:IsA("Motor6D")
            or instance:IsA("Constraint")
        )
end

local function grabLinkParts(instance)
    if not instance then return nil, nil end

    local p0, p1 = nil, nil

    pcall(function()
        p0 = instance.Part0
        p1 = instance.Part1
    end)

    if p0 or p1 then
        return p0, p1
    end

    pcall(function()
        local a0 = instance.Attachment0
        local a1 = instance.Attachment1
        p0 = a0 and a0.Parent or nil
        p1 = a1 and a1.Parent or nil
    end)

    return p0, p1
end

local function breakGrabJoint(instance)
    if not isGrabJoint(instance) then return false end

    local p0, p1 = grabLinkParts(instance)
    local crossLinked =
        (partBelongsToCharacter(p0) and partBelongsToTitan(p1))
        or (partBelongsToCharacter(p1) and partBelongsToTitan(p0))

    if crossLinked then
        pcall(function()
            instance:Destroy()
        end)
        return true
    end

    return false
end

local function grabFlagActive(container)
    if not container then return false end

    local attributes = {}
    pcall(function()
        attributes = container:GetAttributes()
    end)

    for name, value in pairs(attributes) do
        local lowerName = string.lower(tostring(name or ""))
        local relevant =
            string.find(lowerName, "grab", 1, true)
            or string.find(lowerName, "held", 1, true)
            or string.find(lowerName, "captur", 1, true)
            or string.find(lowerName, "caught", 1, true)

        if relevant then
            if value == true then
                return true
            end

            if type(value) == "string" then
                local lowerValue = string.lower(value)
                if lowerValue == "true"
                    or string.find(lowerValue, "grab", 1, true)
                    or string.find(lowerValue, "held", 1, true)
                    or string.find(lowerValue, "captur", 1, true)
                    or string.find(lowerValue, "caught", 1, true) then
                    return true
                end
            end
        end
    end

    return false
end

local function grabValueStateActive(container)
    if not container then return false end

    for _, item in ipairs(container:GetDescendants()) do
        if item:IsA("BoolValue") and item.Value == true then
            local lowerName = string.lower(item.Name)
            if string.find(lowerName, "grab", 1, true)
                or string.find(lowerName, "held", 1, true)
                or string.find(lowerName, "captur", 1, true)
                or string.find(lowerName, "caught", 1, true) then
                return true
            end
        end
    end

    return false
end

local function emergencyGrabSnap(reason)
    if not rootPart or not rootPart.Parent or not character or not character.Parent then
        return
    end
    if V577MovementAuthority and V577MovementAuthority.Mode() == "CANNON" then
        statusText = "Grab joint cleared • cannon mount position preserved"
        return
    end

    local now = os.clock()
    if now - (tonumber(lastEmergencyGrabSnapAt) or 0) < GrabSnapDebounce then
        return
    end
    lastEmergencyGrabSnapAt = now

    CombatSafetyBoostUntil = now + (tonumber(Config.GrabSafetyBoostDuration) or 0.65)
    CombatSafetyBoostHeight = math.max(
        CombatSafetyBoostHeight,
        tonumber(Config.GrabSafetyBoostHeight) or 48
    )

    local anchorPosition, aimPosition = refreshCombatAnchor(false)
    if anchorPosition then
        local snapPosition = anchorPosition
            + Vector3.new(0, tonumber(Config.GrabEmergencySnapHeight) or 85, 0)

        character:PivotTo(
            aimPosition and CFrame.lookAt(snapPosition, aimPosition)
            or CFrame.new(snapPosition)
        )
    else
        rootPart.CFrame = rootPart.CFrame
            + Vector3.new(0, tonumber(Config.GrabEmergencySnapHeight) or 85, 0)
    end

    rootPart.AssemblyAngularVelocity = Vector3.zero
    rootPart.AssemblyLinearVelocity =
        Vector3.new(0, tonumber(Config.GrabEmergencyUpVelocity) or 70, 0)

    if humanoid then
        humanoid.Sit = false
        humanoid.PlatformStand = false
        pcall(function()
            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
        end)
    end

    statusText = "Grab broken: " .. tostring(reason or "detected")
end

-- Anti-Grab Escape was removed in V9.8.2.5. No polling or descendant guards are connected.

local SpearSupport = nil

---------------------------------------------------------------------
-- MAIN PROCESSING LOOP
---------------------------------------------------------------------

task.spawn(function()
	while true do
		task.wait(Config.LoopDelay)

        local uiSleeping = SliceHubUIShouldSleep()
		if not uiSleeping and statusLabel and statusLabel.Text ~= "Status: " .. statusText then
			statusLabel.Text = "Status: " .. statusText
		end

		if not uiSleeping and statusDetailLabel then
			local bladeText = lastBladeSegments ~= nil
				and string.format("Segments %d/%d", lastBladeSegments, Config.BladeSegmentMaximum)
				or string.format("Segments ?/%d", Config.BladeSegmentMaximum)
			if lastBladeSets ~= nil then bladeText = bladeText .. string.format(" | Sets %d/%d", lastBladeSets, Config.BladeSetMaximum) end
			local targetText = string.format("Targets %d/%d", math.clamp(tonumber(lastBladeBurstCount) or 0, 0, getEffectiveTitansPerHit()), getEffectiveTitansPerHit())
			local farmText = string.format(
                "Blades %s • TS %s",
                State.BladesEnabled and "ON" or "OFF",
                (State.SpearSupportEnabled and State.SpearAutoFireEnabled ~= false) and "ON" or "OFF"
            )
			local detailText = string.format("%s  •  %s  •  %s  •  Kit %d blades + %d refill", farmText, targetText, bladeText, Config.BladeStockMaximum, Config.BladeRefillMaximum)
			if statusDetailLabel.Text ~= detailText then
				statusDetailLabel.Text = detailText
			end
		end

		if not uiSleeping and MiniHUD and MiniHUD.Update then
            pcall(MiniHUD.Update)
        end


		if updateObjectiveBrain then
			pcall(updateObjectiveBrain, false)
		end
		if updateAdaptiveCombatMode then
			pcall(updateAdaptiveCombatMode)
		end

		if State.IsGrabbed then
			continue
		end

		if not State.FarmEnabled then
			-- Farm controls the sky lock. Titan Ripper is an optional add-on while Farm is active.
			-- Do not zero velocity here: doing that every frame cancels gravity.
			if StationRefill.Running then
				statusText = "Gas station refill: " .. tostring(StationRefill.LastReason or "running")
			elseif refillSequenceRunning then
				statusText = "Auto Refill: pulling new blades"
			elseif State.AutoRefillEnabled and lastBladeSegments ~= nil then
				statusText = string.format("Farm disabled | Blade segments %d/%d", lastBladeSegments, Config.BladeSegmentMaximum)
			else
				statusText = "Disabled"
			end
			continue
		end

		if not character or not character.Parent or not humanoid or humanoid.Health <= 0 or not rootPart then
			statusText = "Waiting for character"
			continue
		end

        if V4RaidDirector
            and V4RaidDirector.ShouldPauseCombat
            and V4RaidDirector.ShouldPauseCombat() then

            statusText =
                V4RaidDirector.Status
                or "Raid transition lock"

            rootPart.AssemblyLinearVelocity = Vector3.zero
            rootPart.AssemblyAngularVelocity = Vector3.zero

            continue
        end

        local colossalEvadeActive = V55ColossalDirector
            and V4RaidDirector
            and V4RaidDirector.RaidName == "Colossal Raid"
            and V55ColossalDirector.Stage == "P2 BOSS"
            and V55ColossalDirector.EvadeMode == true

        if colossalEvadeActive then
            statusText = "Colossal EVADE • " .. tostring(V55ColossalDirector.LastHazardSignal or "hazard")
            if V35Spears and V35Spears.ShouldRun and V35Spears.ShouldRun() then
                pcall(V35Spears.Step)
            end
            continue
        end

        local colossalMountedDefense = V941ObjectiveGuardian
            and V941ObjectiveGuardian.ColossalMountedActive
            and V941ObjectiveGuardian.ColossalMountedActive() == true
        local objectiveGuardianActive = V941ObjectiveGuardian
            and V941ObjectiveGuardian.RouteActive
            and V941ObjectiveGuardian.RouteActive() == true

        if not objectiveGuardianActive then
		    local targetValid, targetProblem = updateAndValidateCurrentTarget()
		    if not targetValid then
			    if targetProblem and targetProblem ~= "missing" and targetProblem ~= "dead" and targetProblem ~= "invalid" then
				    statusText = "Skipping stalled Titan: " .. targetProblem
			    end

			    if not acquireCurrentTarget() then
				    statusText = "Scanning map for Titans... • AIR-LOCK HOLD"
                    lockCharacterInSky(nil)
				    continue
			    end
		    end

		    -- Active combat modes share targeting, sky locking, speed generation, and stalled-target skipping.
		    lockCharacterInSky(currentTargetPart)
        else
            -- Objective Guardian is remote-first, but Armored/Attack P1 still need
            -- the same hard aerial hold as normal farming. Actual Colossal cannon
            -- ownership is protected by MovementAuthority.CANNON, so this call no-ops
            -- while physically mounted instead of dragging cannon geometry.
            lockCharacterInSky(nil)
            statusText = "Objective Guardian: "
                .. tostring(V941ObjectiveGuardian.Status or "scanning protected target")
        end

		if StationRefill.Running then
			statusText = "Gas station refill: " .. tostring(StationRefill.LastReason or "running")
			continue
		end

		if refillSequenceRunning then
			statusText = "Auto Refill: pulling new blades"
			continue
		end

		-- V3.5 weapon router:
        -- blades remain the default engine; equipped Spears use the TS cluster engine.
		local bladeSwingTriggered, bladeHitCount = false, 0
        local spearTriggered, spearPackCount = false, 0
        local spearModeActive = V35Spears and V35Spears.ShouldRun()
		local ripperSlotUsed = nil
		local ripperAvailableNow = titanControlRipperAvailableNow and titanControlRipperAvailableNow()
        if objectiveGuardianActive then ripperAvailableNow = false end

		if State.FarmEnabled
            and (not ripperSequenceRunning or Config.V6ExactBladeOverlapBlaster == true) then
            if spearModeActive then
                if not bladeBurstRunning then
                    spearTriggered, spearPackCount = V35Spears.Step()
                end

                if State.BladesEnabled and Config.V6ExactBladeEnabled == true then
                    -- V6 exact queue is remote-first and can continue independently of Spear
                    -- cooldowns and Titan Blaster animation ownership.
                    bladeSwingTriggered, bladeHitCount = swingBlades()
                elseif State.BladesEnabled
                    and V58BladeEngine
                    and V58BladeEngine.CanFillSpearGap(spearTriggered) then
                    V58BladeEngine.HybridBurstRequested = true
                    bladeSwingTriggered, bladeHitCount = swingBlades()
                    V58BladeEngine.HybridBurstRequested = false
                end
            elseif State.BladesEnabled then
			    bladeSwingTriggered, bladeHitCount = swingBlades()
            end
		end

        local ripperGapReady = os.clock() - (lastRipperAssistAt or 0) >= (tonumber(Config.RipperAssistMinGap) or 0.10)
        local bladeBurstEarnedAssist =
            spearModeActive
            and (V35Spears.Serial > (V35Spears.LastRipperSerial or 0))
            or (BladeBurstSerial > LastRipperBladeSerial)

        local ripperOpportunity = false
        if State.TitanRipperEnabled and ripperAvailableNow then
            ripperOpportunity = getRipperOpportunity()
        else
            RipperOpportunityReadySince = nil
        end

        if not bladeSwingTriggered
            and not bladeBurstRunning
            and State.TitanRipperEnabled
            and ripperAvailableNow
            and ripperGapReady
            and bladeBurstEarnedAssist
            and ripperOpportunity then

            ripperSlotUsed = useTitanRipper()
            if ripperSlotUsed then
                lastRipperAssistAt = os.clock()

                if spearModeActive then
                    V35Spears.LastRipperSerial = V35Spears.Serial
                else
                    LastRipperBladeSerial = BladeBurstSerial
                end
            end
        end

		local displayedTargetCount =
            spearModeActive
            and math.max(1, tonumber(spearPackCount) or tonumber(V35Spears.LastPack) or 1)
            or (bladeSwingTriggered and bladeHitCount or lastBladeBurstCount)

        if not spearModeActive then
		    displayedTargetCount = math.clamp(displayedTargetCount, 1, getEffectiveTitansPerHit())
        end

		local bladeCounterText = ""
		if State.AutoRefillEnabled and lastBladeSegments ~= nil then
			bladeCounterText = string.format(" | Segments %d/%d", lastBladeSegments, Config.BladeSegmentMaximum)
		end

        if spearModeActive then
            local ammo = V35Spears.ReadAmmo()
            local ammoText = ammo ~= nil and tostring(ammo) or "?"
            local ripperText = ""

            if State.TitanRipperEnabled and ripperAvailableNow then
                ripperText = " | Blaster " .. (
                    ripperSlotUsed
                    and ("slot " .. tostring(ripperSlotUsed))
                    or getRipperCooldownText()
                )
            end

            local bladeRouteText = State.BladesEnabled
                and (" | Blade " .. tostring(V58BladeEngine and V58BladeEngine.Mode or "PACK CLEANUP"))
                or ""
            statusText = string.format(
                "TS Engine | Pack %d | Ammo %s | %s%s",
                displayedTargetCount,
                ammoText,
                tostring(V35Spears.LastStatus or "Idle"),
                ripperText .. bladeRouteText
            )
		elseif State.TitanRipperEnabled and ripperAvailableNow then
			local ripperState
			if ripperSlotUsed then
				ripperState = string.format("activated slot %d", ripperSlotUsed)
			else
				ripperState = getRipperCooldownText()
			end
			statusText = string.format("Blade Main + Titan Blaster | Wave %d/%d | %s%s", displayedTargetCount, getEffectiveTitansPerHit(), ripperState, bladeCounterText)
		else
			local noun = displayedTargetCount == 1 and "Titan" or "Titans"
			local modeText = State.TitanRipperEnabled and "BladeOnly: Blaster skill missing" or "BladeOnly"
			statusText = string.format("%s | Burst %d/%d %s | Speed %d%s", modeText, displayedTargetCount, getEffectiveTitansPerHit(), noun, Config.KillSpeed, bladeCounterText)
		end
	end
end)


---------------------------------------------------------------------
-- V5.1 10-SECOND RECOVERY BRAIN
---------------------------------------------------------------------

V51RecoveryBrain = V51RecoveryBrain or {
    Threshold = 10,
    LastProgressAt = os.clock(),
    LastAlive = nil,
    LastTarget = nil,
    LastPosition = nil,
    Recoveries = 0,
    Consecutive = 0,
    Status = "Monitoring",
}

function V51RecoveryBrain.MarkProgress(reason)
    V51RecoveryBrain.LastProgressAt = os.clock()
    V51RecoveryBrain.Consecutive = 0
    V51RecoveryBrain.Status = tostring(reason or "Progress")
end

function V51RecoveryBrain.Recover(reason)
    V51RecoveryBrain.Recoveries += 1
    V51RecoveryBrain.Consecutive += 1
    V51RecoveryBrain.LastProgressAt = os.clock()
    V51RecoveryBrain.Status = "RECOVERY #" .. tostring(V51RecoveryBrain.Recoveries) .. ": " .. tostring(reason)

    pcall(function() if V4RaidDirector and V4RaidDirector.Refresh then V4RaidDirector.Refresh() end end)
    pcall(function() clearCurrentTarget(false) end)
    pcall(function() if V35Spears and V35Spears.ClearDrainPack then V35Spears.ClearDrainPack("10s recovery") end end)
    pcall(function() if V4BlasterNapeLock and V4BlasterNapeLock.Stop then V4BlasterNapeLock.Stop() end end)
    pcall(function()
        CombatAnchorRuntime.Position = nil
        CombatAnchorRuntime.GroundCenter = nil
        CombatAnchorRuntime.AimPosition = nil
        CombatAnchorRuntime.TargetCount = 0
        CombatAnchorRuntime.LastRefresh = 0
        CombatAnchorRuntime.PulseUntil = 0
        CombatAnchorRuntime.PulseSerial += 1
    end)
    cachedTitanCandidates = {}
    cachedTitanCandidatesAt = 0
    print("[SliceHub V5.1][RECOVERY]", reason)
end

task.spawn(function()
    while true do
        task.wait(1.0)
        pcall(function()
            if not State.FarmEnabled or (V3ResultGuard and V3ResultGuard.Processing) or StationRefill.Running or refillSequenceRunning or ripperSequenceRunning then
                V51RecoveryBrain.MarkProgress("Paused/non-combat")
                return
            end

            if V4RaidDirector
                and V4RaidDirector.ShouldPauseCombat
                and V4RaidDirector.ShouldPauseCombat() then
                V51RecoveryBrain.MarkProgress(
                    V4RaidDirector.RaidName == "Colossal Raid"
                    and "Colossal cannon/transition ownership"
                    or "Raid transition"
                )
                return
            end

            local alive = getCachedAliveTitanCount()
            local pos = rootPart and rootPart.Position or nil
            local target = currentTarget
            local progress = false

            if V51RecoveryBrain.LastAlive == nil or alive < V51RecoveryBrain.LastAlive then progress = true end
            if target ~= nil and target ~= V51RecoveryBrain.LastTarget then progress = true end
            if typeof(pos) == "Vector3" and typeof(V51RecoveryBrain.LastPosition) == "Vector3" then
                if (pos - V51RecoveryBrain.LastPosition).Magnitude >= 18 then progress = true end
            elseif typeof(pos) == "Vector3" then
                progress = true
            end

            V51RecoveryBrain.LastAlive = alive
            V51RecoveryBrain.LastTarget = target
            V51RecoveryBrain.LastPosition = pos

            if progress then
                V51RecoveryBrain.MarkProgress("Combat progress")
                return
            end

            local stalledFor = os.clock() - (V51RecoveryBrain.LastProgressAt or os.clock())
            if stalledFor >= V51RecoveryBrain.Threshold then
                local bossLocked = V4RaidDirector and V4RaidDirector.HardBossLock and select(1, V4RaidDirector.HardBossLock())
                V51RecoveryBrain.Recover(bossLocked and "boss-lock rescan" or "10s no-progress rescan")
            else
                V51RecoveryBrain.Status = string.format("Watching %.1fs / %ss", stalledFor, V51RecoveryBrain.Threshold)
            end
        end)
    end
end)

---------------------------------------------------------------------
-- MISSION / RAID / WAVES CONFIG STORAGE
---------------------------------------------------------------------

local ProfileStore = {}
V98342RuntimeConfig_ProfileAutoLoadNames = {Mission = "", Raid = "", Waves = ""}
local ProfileStorageMode = "Session"
local ProfileStorageDetail = "Configs reset when this script stops."
V98342RuntimeConfig_RuntimeConfigFileName = "SH/config/runtime_configs_v3.json"
V98342RuntimeConfig_LegacyRuntimeConfigFileName = "TitanControlProfiles_v75.json"

local function getOptionalGlobalFunction(name)
    local environment = nil
    pcall(function()
        if type(getgenv) == "function" then environment = getgenv() end
    end)
    if type(environment) == "table" and type(environment[name]) == "function" then
        return environment[name]
    end
    if type(_G) == "table" and type(_G[name]) == "function" then
        return _G[name]
    end
    return nil
end

local executorReadFile = getOptionalGlobalFunction("readfile")
local executorWriteFile = getOptionalGlobalFunction("writefile")
V98342RuntimeConfig_executorMakeFolder = getOptionalGlobalFunction("makefolder")
V98342RuntimeConfig_executorIsFolder = getOptionalGlobalFunction("isfolder")
V98342RuntimeConfig_executorSetClipboard = getOptionalGlobalFunction("setclipboard")
    or getOptionalGlobalFunction("toclipboard")
V98342RuntimeConfig_executorGetClipboard = getOptionalGlobalFunction("getclipboard")
    or getOptionalGlobalFunction("fromclipboard")
V98342RuntimeConfig_executorRequest = getOptionalGlobalFunction("request")
    or getOptionalGlobalFunction("http_request")
    or getOptionalGlobalFunction("httprequest")

function V98342RuntimeConfig_ensureRuntimeConfigFolders()
    if type(V98342RuntimeConfig_executorMakeFolder) ~= "function" then return false end
    for _, folder in ipairs({"SH", "SH/config", "SH/configs"}) do
        local exists = false
        if type(V98342RuntimeConfig_executorIsFolder) == "function" then
            local ok, value = pcall(V98342RuntimeConfig_executorIsFolder, folder)
            exists = ok and value == true
        end
        if not exists then pcall(V98342RuntimeConfig_executorMakeFolder, folder) end
    end
    return true
end

if executorReadFile and executorWriteFile then
    ProfileStorageMode = "File"
    ProfileStorageDetail = "Configs persist between sessions."
    V98342RuntimeConfig_ensureRuntimeConfigFolders()
end

function V98342RuntimeConfig_currentRuntimeConfigType()
    local waves = Workspace:FindFirstChild("Waves")
    local unclimbable = Workspace:FindFirstChild("Unclimbable")
    local objective = unclimbable and unclimbable:FindFirstChild("Objective")
    if waves and objective and objective:FindFirstChild("Waves") then return "Waves" end

    local raidName = ""
    pcall(function()
        raidName = tostring(V4RaidDirector and V4RaidDirector.RaidName or "")
    end)
    if raidName ~= "" and raidName ~= "Unknown" and raidName ~= "None" then
        return "Raid"
    end

    for _, root in ipairs({Workspace, objective}) do
        if root then
            for _, key in ipairs({"Type", "Mode", "MissionType"}) do
                local value = string.lower(tostring(root:GetAttribute(key) or ""))
                if string.find(value, "wave", 1, true) then return "Waves" end
                if string.find(value, "raid", 1, true) then return "Raid" end
            end
        end
    end
    return "Mission"
end

function V98342RuntimeConfig_normalizeRuntimeConfigType(value, data)
    local text = string.lower(tostring(value or ""))
    if text == "waves" or text == "wave" then return "Waves" end
    if text == "raid" or text == "raids" then return "Raid" end
    if text == "mission" or text == "missions" then return "Mission" end
    if type(data) == "table" and data.WavesAutoFarmEnabled == true then return "Waves" end
    return "Mission"
end

function V98342RuntimeConfig_runtimeConfigCategory(value)
    local resolved = V98342RuntimeConfig_normalizeRuntimeConfigType(value)
    return string.lower(resolved)
end

local function sanitizeProfileName(value)
    local raw = tostring(value or "")
    local kept = {}
    for index = 1, #raw do
        local byte = string.byte(raw, index)
        if byte and byte >= 32 and byte ~= 127 then kept[#kept + 1] = string.sub(raw, index, index) end
    end
    local name = table.concat(kept):gsub("^%s+", ""):gsub("%s+$", "")
    return string.sub(name, 1, Config.ProfileNameMaxLength)
end

local function resolveProfileKey(name, expectedType)
    local wanted = string.lower(sanitizeProfileName(name))
    if wanted == "" then return nil end
    expectedType = expectedType and V98342RuntimeConfig_normalizeRuntimeConfigType(expectedType) or nil
    for existingName, data in pairs(ProfileStore) do
        if string.lower(existingName) == wanted
            and (not expectedType or V98342RuntimeConfig_normalizeRuntimeConfigType(data.ConfigType, data) == expectedType) then
            return existingName
        end
    end
    return nil
end

local function normalizeProfile(data)
    if type(data) ~= "table" then return nil end
    local function booleanOr(value, fallback)
        if typeof(value) == "boolean" then return value end
        return fallback == true
    end
    local wavesAllowed = type(SliceHubWaveAutomationAllowed) == "function"
        and SliceHubWaveAutomationAllowed() == true
    local configType = V98342RuntimeConfig_normalizeRuntimeConfigType(
        data.ConfigType or data.category or data.type,
        data
    )

    return {
        Version = 3,
        ConfigType = configType,
        OriginTier = string.upper(tostring(data.OriginTier or data.originTier or "FREE")) == "PREMIUM" and "PREMIUM" or "FREE",
        CreatedAt = tonumber(data.CreatedAt or data.createdAt) or os.time(),
        UpdatedAt = tonumber(data.UpdatedAt or data.updatedAt) or os.time(),
        BladesEnabled = booleanOr(data.BladesEnabled, booleanOr(data.FarmEnabled, false)),
        FarmEnabled = booleanOr(data.FarmEnabled, booleanOr(data.BladesEnabled, false)),
        SpearSupportEnabled = booleanOr(data.SpearSupportEnabled, false),
        SpearAutoFireEnabled = booleanOr(data.SpearAutoFireEnabled, true),
        SpearAutoRefillEnabled = booleanOr(data.SpearAutoRefillEnabled, true),
        SpearInfiniteEnabled = booleanOr(data.SpearInfiniteEnabled, false),
        AutoUseBuffsEnabled = booleanOr(data.AutoUseBuffsEnabled, false),
        BuffOrderAdvanceEnabled = booleanOr(data.BuffOrderAdvanceEnabled, true),
        BuffBlackFlareEnabled = booleanOr(data.BuffBlackFlareEnabled, true),
        BuffOrderRageEnabled = booleanOr(data.BuffOrderRageEnabled, true),
        BuffFoundersOrderEnabled = booleanOr(data.BuffFoundersOrderEnabled, true),
        BuffOrderRevolutionEnabled = booleanOr(data.BuffOrderRevolutionEnabled, true),
        RaidOpenFreeChestEnabled = booleanOr(data.RaidOpenFreeChestEnabled, booleanOr(data.RaidAutoOpenChestsEnabled, true)),
        RaidOpenEmperorChestEnabled = booleanOr(data.RaidOpenEmperorChestEnabled, false),
        TitanRipperEnabled = booleanOr(data.TitanRipperEnabled, false),
        TargetPriority = ({Balanced=true, Nearest=true, Objective=true, Boss=true, Abnormal=true})[tostring(data.TargetPriority or "Balanced")]
            and tostring(data.TargetPriority or "Balanced") or "Balanced",
        AutoRefillEnabled = booleanOr(data.AutoRefillEnabled, true),
        AutoSkipCutsceneEnabled = SliceHubClampAutoSkipCutscene(booleanOr(data.AutoSkipCutsceneEnabled, false)),
        PerformanceModeEnabled = booleanOr(data.PerformanceModeEnabled, false),
        DisableEffectsEnabled = booleanOr(data.DisableEffectsEnabled, false),
        EcoLoopModeEnabled = booleanOr(data.EcoLoopModeEnabled, false),
        MapPropsHiddenEnabled = booleanOr(data.MapPropsHiddenEnabled, false),
        RemoveInjuryKillFlashEnabled = booleanOr(data.RemoveInjuryKillFlashEnabled, false),
        RemoveDamageTextEnabled = booleanOr(data.RemoveDamageTextEnabled, false),
        OptimizationPreset = tostring(data.OptimizationPreset or "Default"),
        CleanupDeadTitansEnabled = booleanOr(data.CleanupDeadTitansEnabled, false),
        RemoveFogEnabled = booleanOr(data.RemoveFogEnabled, false),
        DisablePostProcessingEnabled = booleanOr(data.DisablePostProcessingEnabled, false),
        Disable3DRenderingEnabled = booleanOr(data.Disable3DRenderingEnabled, false),
        SimpleLightingEnabled = booleanOr(data.SimpleLightingEnabled, false),
        LowDetailMapMaterialsEnabled = booleanOr(data.LowDetailMapMaterialsEnabled, false),
        SleepUIWhenHiddenEnabled = booleanOr(data.SleepUIWhenHiddenEnabled, false),
        DisableCameraEffectsEnabled = booleanOr(data.DisableCameraEffectsEnabled, false),
        WavesAutoFarmEnabled = wavesAllowed and booleanOr(data.WavesAutoFarmEnabled, false) or false,
        WavesAutoSkipEnabled = wavesAllowed and booleanOr(data.WavesAutoSkipEnabled, data.AutoSkipEnabled ~= false) or false,
        WavesAutoPickupEnabled = wavesAllowed and booleanOr(data.WavesAutoPickupEnabled, false) or false,
        WavesAutoDeliverEnabled = wavesAllowed and booleanOr(data.WavesAutoDeliverEnabled, false) or false,
        WavesAutoUpgradeGearEnabled = wavesAllowed and booleanOr(data.WavesAutoUpgradeGearEnabled, false) or false,
        WavesGearTarget = ({Blades = true, ["Thunder Spears"] = true, Both = true})[tostring(data.WavesGearTarget or data.GearTarget or "Both")]
            and tostring(data.WavesGearTarget or data.GearTarget or "Both")
            or "Both",
        WavesAutoUpgradeHQEnabled = wavesAllowed and booleanOr(data.WavesAutoUpgradeHQEnabled, false) or false,
        WavesHQMaxEnabled = booleanOr(data.WavesHQMaxEnabled, data.HQMaxEnabled ~= false),
        WavesHQRegenEnabled = booleanOr(data.WavesHQRegenEnabled, data.HQRegenEnabled ~= false),
        WavesHQRefillsEnabled = booleanOr(data.WavesHQRefillsEnabled, data.HQRefillsEnabled ~= false),
        WavesHQReplenishEnabled = booleanOr(data.WavesHQReplenishEnabled, data.HQReplenishEnabled ~= false),
        FPSCap = math.clamp(math.floor((tonumber(data.FPSCap) or 60) + 0.5), 30, 999),
        AutoRetryEnabled = booleanOr(data.AutoRetryEnabled, false),
        AutoMissionLimit = math.clamp(math.floor((tonumber(data.AutoMissionLimit) or 0) + 0.5), 0, 10),
        WaitBeforeLastTitan = math.clamp(math.floor((tonumber(data.WaitBeforeLastTitan) or 0) + 0.5), 0, 50),
        WaitBeforeRaidBossFinish = math.clamp(math.floor((tonumber(data.WaitBeforeRaidBossFinish) or 0) + 0.5), 0, 160),
        TitansPerHit = SliceHubMissionClampTPS(data.TitansPerHit, SliceHubMissionTPSMax()),
    }
end

local function loadProfileStore()
    if not executorReadFile then return end
    local document = nil
    for _, path in ipairs({V98342RuntimeConfig_RuntimeConfigFileName, V98342RuntimeConfig_LegacyRuntimeConfigFileName, Config.ProfileFileName}) do
        local readOk, encoded = pcall(executorReadFile, path)
        if readOk and type(encoded) == "string" and encoded ~= "" then
            local decodeOk, decoded = pcall(function() return HttpService:JSONDecode(encoded) end)
            if decodeOk and type(decoded) == "table" then
                document = decoded
                break
            end
        end
    end
    if type(document) ~= "table" then return end

    local configs = type(document.Configs) == "table" and document.Configs
        or type(document.Profiles) == "table" and document.Profiles
        or document
    for name, data in pairs(configs) do
        if type(name) == "string" and type(data) == "table" then
            local cleanName = sanitizeProfileName(name)
            local normalized = normalizeProfile(data)
            if cleanName ~= "" and normalized then ProfileStore[cleanName] = normalized end
        end
    end

    local auto = type(document.AutoLoad) == "table" and document.AutoLoad or {}
    for _, configType in ipairs({"Mission", "Raid", "Waves"}) do
        local name = sanitizeProfileName(auto[configType] or auto[string.lower(configType)] or "")
        if name ~= "" and resolveProfileKey(name, configType) then
            V98342RuntimeConfig_ProfileAutoLoadNames[configType] = resolveProfileKey(name, configType)
        end
    end

    -- Migrate the old single auto-load setting into the current runtime type.
    if PersistentSettings.AutoLoadProfile == true
        and tostring(PersistentSettings.AutoLoadProfileName or "") ~= "" then
        local runtimeType = V98342RuntimeConfig_currentRuntimeConfigType()
        local oldName = resolveProfileKey(PersistentSettings.AutoLoadProfileName, runtimeType)
        if oldName and V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] == "" then
            V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] = oldName
        end
    end
end

local function persistProfileStore()
    if not executorWriteFile then return true, "Saved for this session" end
    V98342RuntimeConfig_ensureRuntimeConfigFolders()
    local encodeOk, encoded = pcall(function()
        return HttpService:JSONEncode({
            Format = "SliceHubRuntimeConfigs",
            Version = 3,
            AutoLoad = V98342RuntimeConfig_ProfileAutoLoadNames,
            Configs = ProfileStore,
        })
    end)
    if not encodeOk then return false, "JSON encode failed" end
    local writeOk, writeError = pcall(executorWriteFile, V98342RuntimeConfig_RuntimeConfigFileName, encoded)
    if not writeOk then return false, "File write failed: " .. tostring(writeError) end
    return true, "Saved to " .. V98342RuntimeConfig_RuntimeConfigFileName
end

local function captureCurrentProfile()
    return normalizeProfile({
        Version = 3,
        ConfigType = V98342RuntimeConfig_currentRuntimeConfigType(),
        OriginTier = SliceHubIsPremium() and "PREMIUM" or "FREE",
        CreatedAt = os.time(),
        UpdatedAt = os.time(),
        BladesEnabled = State.BladesEnabled == true,
        FarmEnabled = State.BladesEnabled == true,
        SpearSupportEnabled = State.SpearSupportEnabled == true,
        SpearAutoFireEnabled = State.SpearAutoFireEnabled ~= false,
        SpearAutoRefillEnabled = State.SpearAutoRefillEnabled == true,
        SpearInfiniteEnabled = State.SpearInfiniteEnabled == true,
        AutoUseBuffsEnabled = State.AutoUseBuffsEnabled == true,
        BuffOrderAdvanceEnabled = State.BuffOrderAdvanceEnabled ~= false,
        BuffBlackFlareEnabled = State.BuffBlackFlareEnabled ~= false,
        BuffOrderRageEnabled = State.BuffOrderRageEnabled ~= false,
        BuffFoundersOrderEnabled = State.BuffFoundersOrderEnabled ~= false,
        BuffOrderRevolutionEnabled = State.BuffOrderRevolutionEnabled ~= false,
        RaidOpenFreeChestEnabled = State.RaidOpenFreeChestEnabled == true,
        RaidOpenEmperorChestEnabled = State.RaidOpenEmperorChestEnabled == true,
        TitanRipperEnabled = State.TitanRipperEnabled == true,
        TargetPriority = tostring(State.TargetPriority or "Balanced"),
        AutoRefillEnabled = State.AutoRefillEnabled == true,
        AutoSkipCutsceneEnabled = SliceHubClampAutoSkipCutscene(State.AutoSkipCutsceneEnabled),
        PerformanceModeEnabled = State.PerformanceModeEnabled == true,
        DisableEffectsEnabled = State.DisableEffectsEnabled == true,
        EcoLoopModeEnabled = State.EcoLoopModeEnabled == true,
        MapPropsHiddenEnabled = State.MapPropsHiddenEnabled == true,
        RemoveInjuryKillFlashEnabled = State.RemoveInjuryKillFlashEnabled == true,
        RemoveDamageTextEnabled = State.RemoveDamageTextEnabled == true,
        OptimizationPreset = tostring(State.OptimizationPreset or "Default"),
        CleanupDeadTitansEnabled = State.CleanupDeadTitansEnabled == true,
        RemoveFogEnabled = State.RemoveFogEnabled == true,
        DisablePostProcessingEnabled = State.DisablePostProcessingEnabled == true,
        Disable3DRenderingEnabled = State.Disable3DRenderingEnabled == true,
        SimpleLightingEnabled = State.SimpleLightingEnabled == true,
        LowDetailMapMaterialsEnabled = State.LowDetailMapMaterialsEnabled == true,
        SleepUIWhenHiddenEnabled = State.SleepUIWhenHiddenEnabled == true,
        DisableCameraEffectsEnabled = State.DisableCameraEffectsEnabled == true,
        FPSCap = tonumber(State.FPSCap) or 60,
        WavesAutoFarmEnabled = State.WavesAutoFarmEnabled == true,
        WavesAutoSkipEnabled = State.WavesAutoSkipEnabled == true,
        WavesAutoPickupEnabled = State.WavesAutoPickupEnabled == true,
        WavesAutoDeliverEnabled = State.WavesAutoDeliverEnabled == true,
        WavesAutoUpgradeGearEnabled = State.WavesAutoUpgradeGearEnabled == true,
        WavesGearTarget = tostring(State.WavesGearTarget or "Both"),
        WavesAutoUpgradeHQEnabled = State.WavesAutoUpgradeHQEnabled == true,
        WavesHQMaxEnabled = State.WavesHQMaxEnabled ~= false,
        WavesHQRegenEnabled = State.WavesHQRegenEnabled ~= false,
        WavesHQRefillsEnabled = State.WavesHQRefillsEnabled ~= false,
        WavesHQReplenishEnabled = State.WavesHQReplenishEnabled ~= false,
        AutoRetryEnabled = State.AutoRetryEnabled == true,
        AutoMissionLimit = math.clamp(math.floor((tonumber(State.AutoMissionLimit) or 0) + 0.5), 0, 10),
        WaitBeforeLastTitan = math.clamp(math.floor((tonumber(State.WaitBeforeLastTitan) or 0) + 0.5), 0, 50),
        WaitBeforeRaidBossFinish = math.clamp(math.floor((tonumber(State.WaitBeforeRaidBossFinish) or 0) + 0.5), 0, 160),
        TitansPerHit = SliceHubMissionClampTPS(Config.TitansPerHit, SliceHubMissionTPSMax()),
    })
end

local function saveNamedProfile(name)
    local cleanName = sanitizeProfileName(name)
    if cleanName == "" then return false, "Enter a config name" end
    local runtimeType = V98342RuntimeConfig_currentRuntimeConfigType()
    local existingKey = resolveProfileKey(cleanName, runtimeType)
    if existingKey and existingKey ~= cleanName then ProfileStore[existingKey] = nil end
    local profile = captureCurrentProfile()
    local previous = existingKey and ProfileStore[existingKey] or nil
    if previous then profile.CreatedAt = previous.CreatedAt or profile.CreatedAt end
    profile.UpdatedAt = os.time()
    ProfileStore[cleanName] = profile
    local persisted, message = persistProfileStore()
    return persisted, message, cleanName
end

local function getNamedProfile(name)
    local key = resolveProfileKey(name, V98342RuntimeConfig_currentRuntimeConfigType())
    if not key then return nil, nil end
    return normalizeProfile(ProfileStore[key]), key
end

local function deleteNamedProfile(name)
    local runtimeType = V98342RuntimeConfig_currentRuntimeConfigType()
    local key = resolveProfileKey(name, runtimeType)
    if not key then return false, "Config not found" end
    ProfileStore[key] = nil
    if V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] == key then V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] = "" end
    local persisted, message = persistProfileStore()
    return persisted, persisted and ("Deleted " .. key) or message
end

local function getSortedProfileNames()
    local runtimeType = V98342RuntimeConfig_currentRuntimeConfigType()
    local names = {}
    for name, data in pairs(ProfileStore) do
        if V98342RuntimeConfig_normalizeRuntimeConfigType(data.ConfigType, data) == runtimeType then names[#names + 1] = name end
    end
    table.sort(names, function(a, b) return string.lower(a) < string.lower(b) end)
    return names
end

function V98342RuntimeConfig_runtimeBase64UrlEncode(data)
    data = tostring(data or "")
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local binary = data:gsub(".", function(character)
        local byte = character:byte()
        local bits = ""
        for index = 8, 1, -1 do
            bits = bits .. (byte % 2 ^ index - byte % 2 ^ (index - 1) > 0 and "1" or "0")
        end
        return bits
    end) .. "0000"
    local encoded = binary:gsub("%d%d%d?%d?%d?%d?", function(chunk)
        if #chunk < 6 then return "" end
        local value = 0
        for index = 1, 6 do if chunk:sub(index, index) == "1" then value += 2 ^ (6 - index) end end
        return alphabet:sub(value + 1, value + 1)
    end)
    encoded = encoded .. ({"", "==", "="})[#data % 3 + 1]
    return encoded:gsub("%+", "-"):gsub("/", "_"):gsub("=+$", "")
end

function V98342RuntimeConfig_runtimeBase64UrlDecode(data)
    data = tostring(data or ""):gsub("-", "+"):gsub("_", "/")
    local remainder = #data % 4
    if remainder > 0 then data = data .. string.rep("=", 4 - remainder) end
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    data = data:gsub("[^" .. alphabet .. "=]", "")
    local binary = data:gsub(".", function(character)
        if character == "=" then return "" end
        local position = alphabet:find(character, 1, true)
        if not position then return "" end
        local value = position - 1
        local bits = ""
        for index = 6, 1, -1 do bits = bits .. (value % 2 ^ index - value % 2 ^ (index - 1) > 0 and "1" or "0") end
        return bits
    end)
    return binary:gsub("%d%d%d?%d?%d?%d?%d?%d?", function(chunk)
        if #chunk ~= 8 then return "" end
        local value = 0
        for index = 1, 8 do if chunk:sub(index, index) == "1" then value += 2 ^ (8 - index) end end
        return string.char(value)
    end)
end

function V98342RuntimeConfig_buildRuntimeConfigRecord(name, profile)
    profile = normalizeProfile(profile or captureCurrentProfile())
    local configType = V98342RuntimeConfig_normalizeRuntimeConfigType(profile.ConfigType, profile)
    return {
        format = "SliceHubConfig",
        schema = 1,
        category = V98342RuntimeConfig_runtimeConfigCategory(configType),
        name = sanitizeProfileName(name) ~= "" and sanitizeProfileName(name) or (configType .. " Config"),
        description = "",
        originTier = profile.OriginTier,
        sliceHubVersion = "9.8.4",
        createdAt = profile.CreatedAt or os.time(),
        settings = {MissionRuntime = profile},
    }
end

function V98342RuntimeConfig_encodeRuntimeConfigRecord(record)
    local ok, json = pcall(function() return HttpService:JSONEncode(record) end)
    if not ok then return nil, "Config JSON encode failed" end
    return "SHCFG-DRAFT1:" .. V98342RuntimeConfig_runtimeBase64UrlEncode(json)
end

function V98342RuntimeConfig_runtimeConfigIdentity()
    local env = type(getgenv) == "function" and getgenv() or _G
    local key = tostring(env.SCRIPT_KEY or "")
    if key == "" and executorReadFile then
        local ok, raw = pcall(executorReadFile, "SH/license.json")
        if ok and type(raw) == "string" and raw ~= "" then
            local decodedOk, decoded = pcall(function() return HttpService:JSONDecode(raw) end)
            if decodedOk and type(decoded) == "table" then key = tostring(decoded.key or "") end
        end
    end
    local deviceId = ""
    local getHwid = env.gethwid or (type(gethwid) == "function" and gethwid or nil)
    if type(getHwid) == "function" then pcall(function() deviceId = tostring(getHwid()) end) end
    if deviceId == "" then
        pcall(function() deviceId = tostring(game:GetService("RbxAnalyticsService"):GetClientId()) end)
    end
    if deviceId == "" then deviceId = "roblox-user:" .. tostring(player.UserId) end
    return key, deviceId
end

function V98342RuntimeConfig_runtimeApiRequest(path, method, body)
    local key, deviceId = V98342RuntimeConfig_runtimeConfigIdentity()
    if key == "" then return nil, "Saved SliceHub key is unavailable" end
    local payload = type(body) == "table" and body or {}
    payload.key = key
    payload.scriptKey = key
    payload.deviceId = deviceId
    payload.hwid = deviceId
    payload.clientId = deviceId
    payload.userId = tostring(player.UserId)
    payload.requestedTier = SliceHubIsPremium() and "PREMIUM" or "FREE"
    payload.buildTier = payload.requestedTier

    local url = "https://slicebot-production.up.railway.app" .. tostring(path)
    local responseBody = nil
    if type(V98342RuntimeConfig_executorRequest) == "function" then
        local ok, response = pcall(V98342RuntimeConfig_executorRequest, {
            Url = url,
            Method = tostring(method or "POST"),
            Headers = {['Content-Type'] = 'application/json', ['Accept'] = 'application/json'},
            Body = HttpService:JSONEncode(payload),
        })
        if not ok then return nil, tostring(response) end
        responseBody = type(response) == "table" and (response.Body or response.body or response.Response) or response
    else
        local query = {
            "key=" .. HttpService:UrlEncode(key),
            "deviceId=" .. HttpService:UrlEncode(deviceId),
            "userId=" .. HttpService:UrlEncode(player.UserId),
            "requestedTier=" .. HttpService:UrlEncode(payload.requestedTier),
        }
        if payload.token then query[#query + 1] = "token=" .. HttpService:UrlEncode(payload.token) end
        local ok, value = pcall(game.HttpGet, game, url .. "?" .. table.concat(query, "&"))
        if not ok then return nil, tostring(value) end
        responseBody = value
    end

    local okDecode, decoded = pcall(function() return HttpService:JSONDecode(tostring(responseBody or "")) end)
    if not okDecode or type(decoded) ~= "table" then return nil, "Config server returned invalid JSON" end
    if decoded.ok ~= true then return nil, tostring(decoded.message or "Config server rejected request") end
    return decoded, nil
end

function V98342RuntimeConfig_decodeRuntimeConfigInput(value)
    local text = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    local fenced = string.match(text, "^```[%w]*%s*(.-)%s*```$")
    if fenced then text = fenced end

    local record = nil
    if string.match(string.upper(text), "^SHCFG1:") then
        local response, errorMessage = V98342RuntimeConfig_runtimeApiRequest("/api/configs/resolve", "POST", {token = text})
        if not response then return nil, nil, errorMessage end
        record = response.config and response.config.payload or nil
    elseif string.sub(string.upper(text), 1, 14) == "SHCFG-DRAFT1:" then
        local raw = V98342RuntimeConfig_runtimeBase64UrlDecode(string.sub(text, 15))
        local ok, decoded = pcall(function() return HttpService:JSONDecode(raw) end)
        if ok then record = decoded end
    else
        local ok, decoded = pcall(function() return HttpService:JSONDecode(text) end)
        if ok then record = decoded end
    end

    if type(record) ~= "table" then return nil, nil, "Config code could not be decoded" end
    if type(record.payload) == "table" then record = record.payload end
    local category = V98342RuntimeConfig_normalizeRuntimeConfigType(record.category or record.type)
    local currentType = V98342RuntimeConfig_currentRuntimeConfigType()
    if category ~= currentType then
        return nil, record, "This is a " .. category .. " config; current runtime is " .. currentType
    end

    local settings = type(record.settings) == "table" and record.settings
        or type(record.Settings) == "table" and record.Settings
        or record
    local rawProfile = type(settings.MissionRuntime) == "table" and settings.MissionRuntime
        or type(settings.Runtime) == "table" and settings.Runtime
        or settings
    local normalized = normalizeProfile(rawProfile)
    if not normalized then return nil, record, "Config has no mission-runtime settings" end
    normalized.ConfigType = currentType
    normalized.OriginTier = string.upper(tostring(record.originTier or normalized.OriginTier or "FREE")) == "PREMIUM" and "PREMIUM" or "FREE"
    return normalized, record, nil
end

function V98342RuntimeConfig_runtimeConfigAdjustments(rawProfile, normalized)
    local adjustments = {}
    local rawTPS = tonumber(rawProfile and rawProfile.TitansPerHit)
    if rawTPS and rawTPS ~= normalized.TitansPerHit then
        adjustments[#adjustments + 1] = "Titans per hit " .. tostring(rawTPS) .. " → " .. tostring(normalized.TitansPerHit)
    end
    if not SliceHubIsPremium() then
        if rawProfile and (
            rawProfile.WavesAutoFarmEnabled == true
            or rawProfile.WavesAutoSkipEnabled == true
            or rawProfile.WavesAutoPickupEnabled == true
            or rawProfile.WavesAutoDeliverEnabled == true
            or rawProfile.WavesAutoUpgradeGearEnabled == true
            or rawProfile.WavesAutoUpgradeHQEnabled == true
        ) then
            adjustments[#adjustments + 1] = "Premium Waves automation disabled"
        end
        if normalized.TitanRipperEnabled == true and not (BUILD and BUILD.Flags and BUILD.Flags.PremiumCombat == true) then
            normalized.TitanRipperEnabled = false
            adjustments[#adjustments + 1] = "Premium Titan Blaster disabled"
        end
    end
    return adjustments
end

function V98342RuntimeConfig_importRuntimeConfigText(value, applyNow)
    local normalized, record, errorMessage = V98342RuntimeConfig_decodeRuntimeConfigInput(value)
    if not normalized then return false, errorMessage end
    local settings = type(record.settings) == "table" and record.settings or record
    local rawProfile = type(settings.MissionRuntime) == "table" and settings.MissionRuntime or settings
    local adjustments = V98342RuntimeConfig_runtimeConfigAdjustments(rawProfile, normalized)
    local name = sanitizeProfileName(record.name or record.Name or (normalized.ConfigType .. " Imported"))
    if name == "" then name = normalized.ConfigType .. " Imported" end
    local existing = resolveProfileKey(name, normalized.ConfigType)
    if existing and existing ~= name then ProfileStore[existing] = nil end
    normalized.UpdatedAt = os.time()
    ProfileStore[name] = normalized
    local saved, saveMessage = persistProfileStore()
    if not saved then return false, saveMessage end
    if applyNow and type(applyProfile) == "function" then applyProfile(normalized, false) end
    local detail = #adjustments > 0 and (" • " .. table.concat(adjustments, " • ")) or ""
    return true, "Imported " .. name .. detail, name
end

function V98342RuntimeConfig_copyRuntimeConfig(name, profile)
    if type(V98342RuntimeConfig_executorSetClipboard) ~= "function" then return false, "Clipboard writing unavailable" end
    local code, errorMessage = V98342RuntimeConfig_encodeRuntimeConfigRecord(V98342RuntimeConfig_buildRuntimeConfigRecord(name, profile))
    if not code then return false, errorMessage end
    local ok, result = pcall(V98342RuntimeConfig_executorSetClipboard, code)
    return ok, ok and "Config copied to clipboard" or tostring(result)
end

function V98342RuntimeConfig_pasteRuntimeConfig(applyNow)
    if type(V98342RuntimeConfig_executorGetClipboard) ~= "function" then return false, "Clipboard reading unavailable" end
    local ok, value = pcall(V98342RuntimeConfig_executorGetClipboard)
    if not ok then return false, tostring(value) end
    return V98342RuntimeConfig_importRuntimeConfigText(value, applyNow)
end

function V98342RuntimeConfig_safeRuntimeConfigFileName(name)
    local value = sanitizeProfileName(name):gsub("[^%w%-%_ ]", ""):gsub("%s+", "_")
    return value ~= "" and value or "SliceHub_Config"
end

function V98342RuntimeConfig_exportRuntimeConfigFile(name, profile)
    if type(executorWriteFile) ~= "function" then return false, "File writing unavailable" end
    V98342RuntimeConfig_ensureRuntimeConfigFolders()
    local code, errorMessage = V98342RuntimeConfig_encodeRuntimeConfigRecord(V98342RuntimeConfig_buildRuntimeConfigRecord(name, profile))
    if not code then return false, errorMessage end
    local path = "SH/configs/" .. V98342RuntimeConfig_safeRuntimeConfigFileName(name) .. ".shcfg"
    local ok, result = pcall(executorWriteFile, path, code)
    return ok, ok and ("Exported " .. path) or tostring(result)
end

function V98342RuntimeConfig_importRuntimeConfigFile(name, applyNow)
    if type(executorReadFile) ~= "function" then return false, "File reading unavailable" end
    local path = "SH/configs/" .. V98342RuntimeConfig_safeRuntimeConfigFileName(name) .. ".shcfg"
    local ok, value = pcall(executorReadFile, path)
    if not ok then return false, "Could not read " .. path end
    return V98342RuntimeConfig_importRuntimeConfigText(value, applyNow)
end

function V98342RuntimeConfig_publishRuntimeConfig(name, profile)
    local record = V98342RuntimeConfig_buildRuntimeConfigRecord(name, profile)
    local response, errorMessage = V98342RuntimeConfig_runtimeApiRequest("/api/configs/publish", "POST", {
        category = record.category,
        name = record.name,
        description = record.description,
        payload = record,
    })
    if not response then return false, errorMessage end
    local config = response.config or {}
    return true, "Published " .. tostring(config.id or record.name) .. " to Discord"
end

loadProfileStore()

---------------------------------------------------------------------
-- BASIC PERFORMANCE OPTIMIZER
---------------------------------------------------------------------
---------------------------------------------------------------------
-- BASIC PERFORMANCE OPTIMIZER
---------------------------------------------------------------------

local Performance = {}

do
	Performance.OriginalLighting = {}
	Performance.OriginalTerrain = {}
	Performance.OriginalEffects = setmetatable({}, {__mode = "k"})
    Performance.OriginalPostEffects = setmetatable({}, {__mode = "k"})
    Performance.OriginalAtmospheres = setmetatable({}, {__mode = "k"})
    Performance.OriginalLowDetail = setmetatable({}, {__mode = "k"})
    Performance.OriginalCameraEffects = setmetatable({}, {__mode = "k"})
    Performance.CameraBaseFOV = nil
    Performance.EffectsModule = nil
    Performance.DeadTitanSeenAt = setmetatable({}, {__mode = "k"})
	Performance.HiddenMapProps = {}
    Performance.ColossalCullSuspended = false
	Performance.LightingSaved = false
	Performance.TerrainSaved = false
	Performance.DefaultConfig = {
		LoopDelay = Config.LoopDelay,
		TargetCacheLifetime = Config.TargetCacheLifetime,
		CutsceneCheckDelay = Config.CutsceneCheckDelay,
		AutoRefillCheckDelay = Config.AutoRefillCheckDelay,
	}

	function Performance.SafeGet(object, property)
		local ok, value = pcall(function()
			return object[property]
		end)
		if ok then return value end
		return nil
	end

	function Performance.SafeSet(object, property, value)
		pcall(function()
			object[property] = value
		end)
	end

	function Performance.RememberProperty(bucket, object, property)
		if bucket[property] ~= nil then return end
		local value = Performance.SafeGet(object, property)
		if value ~= nil then
			bucket[property] = value
		end
	end

	function Performance.GetTerrain()
		return Workspace:FindFirstChildOfClass("Terrain") or Workspace:FindFirstChild("Terrain")
	end

	function Performance.IsVisualEffect(object)
		return object:IsA("ParticleEmitter")
			or object:IsA("Trail")
			or object:IsA("Beam")
			or object:IsA("Smoke")
			or object:IsA("Fire")
			or object:IsA("Sparkles")
	end

	Performance.MapPropKeywords = {
		"house", "building", "wall", "roof", "door", "window", "fence", "tree", "bush", "rock",
		"prop", "props", "decor", "decoration", "foliage", "grass", "lamp", "barrel",
		"crate", "cart", "wood", "plank", "chimney", "bench", "sign", "tower", "pillar"
	}

	Performance.MapPropProtectedKeywords = {
		"titan", "enemy", "npc", "player", "spawn", "checkpoint", "objective", "quest", "mission",
		"hitbox", "nape", "humanoid", "root", "camera", "terrain", "baseplate", "ground", "floor",
		"road", "path", "water", "safe", "zone", "barrier", "invisible", "kill", "damage", "remote",
        "debris", "characters", "effects", "particles", "projectiles", "attacks", "runtime", "interactions", "cannon", "boss", "waves", "wave", "cutscene", "refill", "gastank", "station", "prompt", "interactable", "bertholdt", "eren"
	}

	function Performance.NameHasKeyword(name, keywords)
		local lowerName = string.lower(tostring(name or ""))
		for _, keyword in ipairs(keywords) do
			if string.find(lowerName, keyword, 1, true) then
				return true
			end
		end
		return false
	end

	function Performance.HasHumanoidAncestor(object)
		local node = object
		while node and node ~= Workspace do
			if node:IsA("Model") and node:FindFirstChildOfClass("Humanoid") then
				return true
			end
			node = node.Parent
		end
		return false
	end

	function Performance.IsProtectedMapObject(object)
		if not object or object == Workspace or object == Workspace.CurrentCamera then return true end
		if object:IsA("Terrain") then return true end
		if character and object:IsDescendantOf(character) then return true end
		if Performance.HasHumanoidAncestor(object) then return true end

        -- V5.5: preserve the selected/available cannon and any ancestor container.
        -- Otherwise a generic "building/prop" cull can remove the cannon with its parent.
        local okCannons, cannons = pcall(function()
            return game:GetService("CollectionService"):GetTagged("Cannon")
        end)
        if okCannons and type(cannons) == "table" then
            for _, cannon in ipairs(cannons) do
                if cannon == object
                    or cannon:IsDescendantOf(object)
                    or object:IsDescendantOf(cannon) then
                    return true
                end
            end
        end

        -- V3.5.1: never cull live runtime containers used by game systems.
        local top = object
        while top and top.Parent and top.Parent ~= Workspace do
            top = top.Parent
        end

        if top and top.Parent == Workspace then
            local topName = string.lower(tostring(top.Name or ""))
            if topName == "debris"
                or topName == "characters"
                or topName == "titans"
                or topName == "effects"
                or topName == "particles"
                or topName == "projectiles"
                or topName == "attacks"
                or topName == "runtime"
                or topName == "interactions" then
                return true
            end

            if topName == "climbable" or topName == "unclimbable" then
                local objectName = string.lower(tostring(object.Name or ""))
                if objectName == "buildings"
                    or objectName == "cutscene_buildings"
                    or objectName == "gastanks"
                    or objectName == "refill" then
                    return true
                end

                local criticalNode = object.Parent
                while criticalNode and criticalNode ~= top do
                    local criticalName = string.lower(tostring(criticalNode.Name or ""))
                    if criticalName == "cutscene_buildings"
                        or criticalName == "gastanks" then
                        return true
                    end
                    criticalNode = criticalNode.Parent
                end
            end
        end

		local node = object
		while node and node ~= Workspace do
			if node.Name == Config.TitansFolderName then return true end
			if Performance.NameHasKeyword(node.Name, Performance.MapPropProtectedKeywords) then return true end
			node = node.Parent
		end
		return false
	end

	function Performance.IsMapPropCandidate(object)
		if Performance.IsProtectedMapObject(object) then return false end
		if object:IsA("Model") or object:IsA("Folder") then
			return Performance.NameHasKeyword(object.Name, Performance.MapPropKeywords)
		end
		if object:IsA("BasePart") then
			if object:IsA("SpawnLocation") then return false end
			return Performance.NameHasKeyword(object.Name, Performance.MapPropKeywords)
		end
		return false
	end

    function Performance.IsColossalRaidActive()
        local active = false
        pcall(function()
            active = V4RaidDirector
                and V4RaidDirector.RaidName == "Colossal Raid"
        end)
        if active then return true end

        return Workspace:FindFirstChild("Colossal_Boss", true) ~= nil
            or Workspace:FindFirstChild("Colossal Titan", true) ~= nil
    end

	function Performance:ApplyMapPropCull()
        Performance.RestoreCriticalRuntimeFolders()

        -- Colossal P1 cannons are physically mounted on wall geometry. Never cull
        -- map props during this raid: deleting/restoring the wall after mounting can
        -- remove the cannon or drag the restored wall assembly with the player.
        if Performance.IsColossalRaidActive() then
            self:RestoreMapProps()
            Performance.ColossalCullSuspended = true
            return 0
        end

		local moved = 0
		local limit = math.max(1, tonumber(Config.MapPropCullMaxPerPass) or 900)

		for _, object in ipairs(Workspace:GetDescendants()) do
			if moved >= limit then break end
			if object and object.Parent and object:IsDescendantOf(Workspace) and Performance.IsMapPropCandidate(object) then
				if self.HiddenMapProps[object] == nil then
					self.HiddenMapProps[object] = {Parent = object.Parent}
				end
				pcall(function()
					object.Parent = nil
				end)
				moved += 1
			end
		end

		return moved
	end

	function Performance:RestoreMapProps()
		for object, data in pairs(self.HiddenMapProps) do
			if object and data and data.Parent then
				pcall(function()
					if object.Parent == nil then
						object.Parent = data.Parent
					end
				end)
			end
			self.HiddenMapProps[object] = nil
		end
	end

    function Performance.RestoreCriticalRuntimeFolders()
        for object, data in pairs(Performance.HiddenMapProps or {}) do
            if object and data and data.Parent and object.Parent == nil then
                local objectName = string.lower(tostring(object.Name or ""))
                local mustRestore = objectName == "debris"
                    or objectName == "buildings"
                    or objectName == "cutscene_buildings"
                    or objectName == "gastanks"
                    or objectName == "refill"

                local node = data.Parent
                while node and node ~= Workspace do
                    local lowerName = string.lower(tostring(node.Name or ""))
                    if lowerName == "cutscene_buildings" or lowerName == "gastanks" then
                        mustRestore = true
                        break
                    end
                    node = node.Parent
                end

                if mustRestore then
                    pcall(function() object.Parent = data.Parent end)
                    Performance.HiddenMapProps[object] = nil
                end
            end
        end
    end

	function Performance:SetMapPropCull(enabled)
        Performance.RestoreCriticalRuntimeFolders()
		State.MapPropsHiddenEnabled = enabled == true
        if Performance.IsColossalRaidActive() then
            self:RestoreMapProps()
            Performance.ColossalCullSuspended = true
            return 0
        end
		if State.MapPropsHiddenEnabled then
			return self:ApplyMapPropCull()
		else
			self:RestoreMapProps()
			return 0
		end
	end

    do
        local env = _G
        pcall(function()
            if type(getgenv) == "function" then env = getgenv() end
        end)

        if type(env) == "table" then
            env.SliceHubRestoreColossalMapProps = function()
                Performance:RestoreMapProps()
                Performance.RestoreCriticalRuntimeFolders()
                Performance.ColossalCullSuspended = true
                return true
            end
        end

        task.spawn(function()
            local wasColossal = false
            while true do
                task.wait(0.35)
                local active = Performance.IsColossalRaidActive()

                if active then
                    if not wasColossal or next(Performance.HiddenMapProps) ~= nil then
                        Performance:RestoreMapProps()
                        Performance.RestoreCriticalRuntimeFolders()
                    end
                    Performance.ColossalCullSuspended = true
                elseif wasColossal then
                    Performance.ColossalCullSuspended = false
                    if State.MapPropsHiddenEnabled then
                        Performance:ApplyMapPropCull()
                    end
                end

                wasColossal = active
            end
        end)
    end

	function Performance:ApplyLowGraphics()
		local lighting = game:GetService("Lighting")
		if lighting then
			if not self.LightingSaved then
				Performance.RememberProperty(self.OriginalLighting, lighting, "GlobalShadows")
				Performance.RememberProperty(self.OriginalLighting, lighting, "ShadowSoftness")
				Performance.RememberProperty(self.OriginalLighting, lighting, "EnvironmentDiffuseScale")
				Performance.RememberProperty(self.OriginalLighting, lighting, "EnvironmentSpecularScale")
				self.LightingSaved = true
			end

			Performance.SafeSet(lighting, "GlobalShadows", false)
			Performance.SafeSet(lighting, "ShadowSoftness", 0)
			Performance.SafeSet(lighting, "EnvironmentDiffuseScale", 0)
			Performance.SafeSet(lighting, "EnvironmentSpecularScale", 0)
		end

		local terrain = Performance.GetTerrain()
		if terrain then
			if not self.TerrainSaved then
				Performance.RememberProperty(self.OriginalTerrain, terrain, "Decoration")
				Performance.RememberProperty(self.OriginalTerrain, terrain, "WaterWaveSize")
				Performance.RememberProperty(self.OriginalTerrain, terrain, "WaterWaveSpeed")
				Performance.RememberProperty(self.OriginalTerrain, terrain, "WaterReflectance")
				Performance.RememberProperty(self.OriginalTerrain, terrain, "WaterTransparency")
				self.TerrainSaved = true
			end

			Performance.SafeSet(terrain, "Decoration", false)
			Performance.SafeSet(terrain, "WaterWaveSize", 0)
			Performance.SafeSet(terrain, "WaterWaveSpeed", 0)
			Performance.SafeSet(terrain, "WaterReflectance", 0)
			Performance.SafeSet(terrain, "WaterTransparency", 1)
		end
	end

	function Performance:RestoreLowGraphics()
		local lighting = game:GetService("Lighting")
		if lighting then
			for property, value in pairs(self.OriginalLighting) do
				Performance.SafeSet(lighting, property, value)
			end
		end

		local terrain = Performance.GetTerrain()
		if terrain then
			for property, value in pairs(self.OriginalTerrain) do
				Performance.SafeSet(terrain, property, value)
			end
		end
	end

	function Performance:SetLowGraphics(enabled)
		State.PerformanceModeEnabled = enabled == true
		if State.PerformanceModeEnabled then
			self:ApplyLowGraphics()
		else
			self:RestoreLowGraphics()
		end
        self:ReconcileLighting()
	end

	function Performance:ApplyNoEffects()
		for _, object in ipairs(Workspace:GetDescendants()) do
			if Performance.IsVisualEffect(object) then
				if self.OriginalEffects[object] == nil then
					self.OriginalEffects[object] = Performance.SafeGet(object, "Enabled")
				end
				Performance.SafeSet(object, "Enabled", false)
			end
		end
	end

	function Performance:RestoreNoEffects()
		for object, wasEnabled in pairs(self.OriginalEffects) do
			if object and object.Parent then
				Performance.SafeSet(object, "Enabled", wasEnabled)
			end
			self.OriginalEffects[object] = nil
		end
	end

	function Performance:SetNoEffects(enabled)
		State.DisableEffectsEnabled = enabled == true
		if State.DisableEffectsEnabled then
			self:ApplyNoEffects()
		else
			self:RestoreNoEffects()
		end
	end


    Performance.VisualConnections = Performance.VisualConnections or {}
    Performance.VisualWatched = Performance.VisualWatched or setmetatable({}, {__mode = "k"})

    function Performance.HasAncestorNamed(object, tokens)
        local node = object
        while node do
            local lower = string.lower(tostring(node.Name or ""))
            for _, token in ipairs(tokens) do
                if string.find(lower, token, 1, true) then return true end
            end
            node = node.Parent
        end
        return false
    end

    function Performance.IsDamageNumberLabel(object)
        if not object or not object:IsA("TextLabel") then return false end
        local text = tostring(object.Text or "")
        local compact = string.gsub(text, "[,%s]", "")
        if not string.match(compact, "^%-?%d+%.?%d*$") then return false end
        if tonumber(object.TextSize) and object.TextSize < 16 then return false end

        -- Damage popups are normally large world-space BillboardGui labels. The
        -- TextSize guard preserves small distance/objective markers such as 706m.
        -- explicit Damage/Hit/Critical containers, but never blanket-hide HUD stats.
        local node = object.Parent
        while node do
            if node:IsA("BillboardGui") then return true end
            local lower = string.lower(tostring(node.Name or ""))
            if string.find(lower, "damage", 1, true)
                or string.find(lower, "critical", 1, true)
                or string.find(lower, "hitnumber", 1, true)
                or string.find(lower, "hit_number", 1, true) then
                return true
            end
            node = node.Parent
        end
        return false
    end

    function Performance.IsInjuryKillFlashObject(object)
        if not object then return false end
        if not (object:IsA("GuiObject")
            or object:IsA("ColorCorrectionEffect")
            or object:IsA("BloomEffect")) then
            return false
        end

        local lower = string.lower(tostring(object.Name or ""))
        if string.find(lower, "injuryflash", 1, true)
            or string.find(lower, "injury_flash", 1, true)
            or string.find(lower, "killflash", 1, true)
            or string.find(lower, "kill_flash", 1, true)
            or string.find(lower, "damageflash", 1, true)
            or string.find(lower, "damage_flash", 1, true) then
            return true
        end

        -- The game's injury screen is exposed as Interface.Injury. Suppress only
        -- descendants of that branch, not generic Flash effects such as Black Flash.
        return Performance.HasAncestorNamed(object, {"injury"})
    end

    function Performance.ApplyVisualSuppressorTo(object)
        local damageMatch = State.RemoveDamageTextEnabled and Performance.IsDamageNumberLabel(object)
        local flashMatch = State.RemoveInjuryKillFlashEnabled and Performance.IsInjuryKillFlashObject(object)

        if damageMatch then
            Performance.SafeSet(object, "Visible", false)
            Performance.SafeSet(object, "TextTransparency", 1)
            Performance.SafeSet(object, "TextStrokeTransparency", 1)
        end

        if flashMatch then
            if object:IsA("GuiObject") then
                Performance.SafeSet(object, "Visible", false)
                Performance.SafeSet(object, "BackgroundTransparency", 1)
                if object:IsA("ImageLabel") or object:IsA("ImageButton") then
                    Performance.SafeSet(object, "ImageTransparency", 1)
                end
            else
                Performance.SafeSet(object, "Enabled", false)
            end
        end

        if (damageMatch or flashMatch) and not Performance.VisualWatched[object] then
            Performance.VisualWatched[object] = true
            if object:IsA("GuiObject") then
                object:GetPropertyChangedSignal("Visible"):Connect(function()
                    if object.Parent then task.defer(Performance.ApplyVisualSuppressorTo, object) end
                end)
            elseif object:IsA("ColorCorrectionEffect") or object:IsA("BloomEffect") then
                object:GetPropertyChangedSignal("Enabled"):Connect(function()
                    if object.Parent then task.defer(Performance.ApplyVisualSuppressorTo, object) end
                end)
            end
        end
    end

    function Performance:ApplyVisualSuppressors()
        local containers = {playerGui, Workspace, game:GetService("Lighting")}
        for _, container in ipairs(containers) do
            if container then
                for _, object in ipairs(container:GetDescendants()) do
                    Performance.ApplyVisualSuppressorTo(object)
                end
            end
        end
    end

    function Performance:SetRemoveInjuryKillFlash(enabled)
        State.RemoveInjuryKillFlashEnabled = enabled == true
        if State.RemoveInjuryKillFlashEnabled then self:ApplyVisualSuppressors() end
    end

    function Performance:SetRemoveDamageText(enabled)
        State.RemoveDamageTextEnabled = enabled == true
        if State.RemoveDamageTextEnabled then self:ApplyVisualSuppressors() end
    end

    do
        local function connect(container)
            if not container or Performance.VisualConnections[container] then return end
            Performance.VisualConnections[container] = container.DescendantAdded:Connect(function(object)
                task.defer(function()
                    if object and object.Parent then Performance.ApplyVisualSuppressorTo(object) end
                end)
            end)
        end
        connect(playerGui)
        connect(Workspace)
        connect(game:GetService("Lighting"))

        Workspace.DescendantAdded:Connect(function(object)
            if State.LowDetailMapMaterialsEnabled == true then
                task.defer(function()
                    if object and object.Parent then
                        Performance:ApplyLowDetailObject(object)
                    end
                end)
            end
        end)
    end



    function Performance:CaptureLightingDefaults()
        local lighting = game:GetService("Lighting")
        if not self.LightingSaved then
            for _, property in ipairs({
                "GlobalShadows", "ShadowSoftness",
                "EnvironmentDiffuseScale", "EnvironmentSpecularScale",
                "FogStart", "FogEnd", "FogColor",
            }) do
                Performance.RememberProperty(self.OriginalLighting, lighting, property)
            end
            self.LightingSaved = true
        end

        for _, object in ipairs(lighting:GetChildren()) do
            if object:IsA("PostEffect") and self.OriginalPostEffects[object] == nil then
                self.OriginalPostEffects[object] = self.SafeGet(object, "Enabled")
            elseif object:IsA("Atmosphere") and self.OriginalAtmospheres[object] == nil then
                self.OriginalAtmospheres[object] = {
                    Density = self.SafeGet(object, "Density"),
                    Haze = self.SafeGet(object, "Haze"),
                    Glare = self.SafeGet(object, "Glare"),
                }
            end
        end
    end

    function Performance:ReconcileLighting()
        self:CaptureLightingDefaults()
        local lighting = game:GetService("Lighting")
        local simple = State.SimpleLightingEnabled == true
        local low = State.PerformanceModeEnabled == true
        local noFog = State.RemoveFogEnabled == true or simple
        local noPost = State.DisablePostProcessingEnabled == true or simple

        self.SafeSet(lighting, "GlobalShadows",
            (simple or low) and false or self.OriginalLighting.GlobalShadows)
        self.SafeSet(lighting, "ShadowSoftness",
            (simple or low) and 0 or self.OriginalLighting.ShadowSoftness)
        self.SafeSet(lighting, "EnvironmentDiffuseScale",
            (simple or low) and 0 or self.OriginalLighting.EnvironmentDiffuseScale)
        self.SafeSet(lighting, "EnvironmentSpecularScale",
            (simple or low) and 0 or self.OriginalLighting.EnvironmentSpecularScale)

        self.SafeSet(lighting, "FogStart",
            noFog and 100000 or self.OriginalLighting.FogStart)
        self.SafeSet(lighting, "FogEnd",
            noFog and 100000 or self.OriginalLighting.FogEnd)
        if not noFog and self.OriginalLighting.FogColor ~= nil then
            self.SafeSet(lighting, "FogColor", self.OriginalLighting.FogColor)
        end

        for object, values in pairs(self.OriginalAtmospheres) do
            if object and object.Parent and type(values) == "table" then
                self.SafeSet(object, "Density", noFog and 0 or values.Density)
                self.SafeSet(object, "Haze", noFog and 0 or values.Haze)
                self.SafeSet(object, "Glare", noFog and 0 or values.Glare)
            end
        end

        for object, wasEnabled in pairs(self.OriginalPostEffects) do
            if object and object.Parent then
                self.SafeSet(object, "Enabled", noPost and false or wasEnabled)
            end
        end
    end

    function Performance:SetSimpleLighting(enabled)
        State.SimpleLightingEnabled = enabled == true
        self:ReconcileLighting()
    end

    function Performance:IsStrictVisualProtection(object)
        if self.IsProtectedMapObject(object) then return true end
        if object:IsA("ProximityPrompt") or object:IsA("ClickDetector") then return true end

        local collection = game:GetService("CollectionService")
        local ok, tags = pcall(function() return collection:GetTags(object) end)
        if ok and type(tags) == "table" then
            for _, tag in ipairs(tags) do
                local lower = string.lower(tostring(tag))
                if string.find(lower, "objective", 1, true)
                    or string.find(lower, "cannon", 1, true)
                    or string.find(lower, "interact", 1, true)
                    or string.find(lower, "refill", 1, true)
                    or string.find(lower, "boss", 1, true)
                    or string.find(lower, "wave", 1, true) then
                    return true
                end
            end
        end

        local node = object
        while node and node ~= Workspace do
            local lower = string.lower(tostring(node.Name or ""))
            if string.find(lower, "objective", 1, true)
                or string.find(lower, "cutscene", 1, true)
                or string.find(lower, "cannon", 1, true)
                or string.find(lower, "refill", 1, true)
                or string.find(lower, "gastank", 1, true)
                or string.find(lower, "interact", 1, true)
                or string.find(lower, "waves", 1, true)
                or string.find(lower, "boss", 1, true) then
                return true
            end
            node = node.Parent
        end
        return false
    end

    function Performance:IsLowDetailCandidate(object)
        if not object or not object.Parent then return false end
        if not (object:IsA("BasePart")
            or object:IsA("Decal")
            or object:IsA("Texture")
            or object:IsA("SurfaceAppearance")) then
            return false
        end
        if self:IsStrictVisualProtection(object) then return false end

        local node = object
        while node and node ~= Workspace do
            if self.NameHasKeyword(node.Name, self.MapPropKeywords) then
                return true
            end
            node = node.Parent
        end
        return false
    end

    function Performance:ApplyLowDetailObject(object)
        if not self:IsLowDetailCandidate(object) then return false end
        if self.OriginalLowDetail[object] == nil then
            if object:IsA("BasePart") then
                self.OriginalLowDetail[object] = {
                    Class = "BasePart",
                    Material = object.Material,
                    Reflectance = object.Reflectance,
                }
            elseif object:IsA("Decal") or object:IsA("Texture") then
                self.OriginalLowDetail[object] = {
                    Class = object.ClassName,
                    Transparency = object.Transparency,
                }
            else
                self.OriginalLowDetail[object] = {
                    Class = "SurfaceAppearance",
                    ColorMap = self.SafeGet(object, "ColorMap"),
                    MetalnessMap = self.SafeGet(object, "MetalnessMap"),
                    NormalMap = self.SafeGet(object, "NormalMap"),
                    RoughnessMap = self.SafeGet(object, "RoughnessMap"),
                }
            end
        end

        if object:IsA("BasePart") then
            self.SafeSet(object, "Material", Enum.Material.SmoothPlastic)
            self.SafeSet(object, "Reflectance", 0)
        elseif object:IsA("Decal") or object:IsA("Texture") then
            self.SafeSet(object, "Transparency", 1)
        else
            for _, property in ipairs({"ColorMap", "MetalnessMap", "NormalMap", "RoughnessMap"}) do
                self.SafeSet(object, property, "")
            end
        end
        return true
    end

    function Performance:ApplyLowDetailMapMaterials()
        local changed = 0
        for index, object in ipairs(Workspace:GetDescendants()) do
            if State.LowDetailMapMaterialsEnabled ~= true then break end
            if self:ApplyLowDetailObject(object) then changed += 1 end
            if index % 500 == 0 then task.wait() end
        end
        return changed
    end

    function Performance:RestoreLowDetailMapMaterials()
        for object, values in pairs(self.OriginalLowDetail) do
            if object and object.Parent and type(values) == "table" then
                if values.Class == "BasePart" then
                    self.SafeSet(object, "Material", values.Material)
                    self.SafeSet(object, "Reflectance", values.Reflectance)
                elseif values.Class == "Decal" or values.Class == "Texture" then
                    self.SafeSet(object, "Transparency", values.Transparency)
                else
                    for _, property in ipairs({"ColorMap", "MetalnessMap", "NormalMap", "RoughnessMap"}) do
                        self.SafeSet(object, property, values[property])
                    end
                end
            end
            self.OriginalLowDetail[object] = nil
        end
    end

    function Performance:SetLowDetailMapMaterials(enabled)
        State.LowDetailMapMaterialsEnabled = enabled == true
        if State.LowDetailMapMaterialsEnabled then
            task.spawn(function() self:ApplyLowDetailMapMaterials() end)
        else
            self:RestoreLowDetailMapMaterials()
        end
    end

    function Performance:ResolveEffectsModule()
        if type(self.EffectsModule) == "table" then return self.EffectsModule end
        local modules = game:GetService("ReplicatedStorage"):FindFirstChild("Modules")
        local utilities = modules and modules:FindFirstChild("Utilities")
        local source = utilities and utilities:FindFirstChild("Effects")
        if source and source:IsA("ModuleScript") then
            local ok, value = pcall(require, source)
            if ok and type(value) == "table" then
                self.EffectsModule = value
                return value
            end
        end
        return nil
    end

    function Performance:ApplyCameraEffectsPolicy()
        if State.DisableCameraEffectsEnabled ~= true then return end
        local effects = self:ResolveEffectsModule()
        if effects then
            effects.Shake_Amount = 0
            local tween = effects.FOV_Tween
            if tween then pcall(function() tween:Cancel() end) end
            effects.FOV_Tween = nil
        end

        local camera = Workspace.CurrentCamera
        if camera and camera.CameraType ~= Enum.CameraType.Scriptable then
            if self.CameraBaseFOV == nil then
                self.CameraBaseFOV = math.clamp(tonumber(camera.FieldOfView) or 70, 55, 90)
            end
            self.SafeSet(camera, "FieldOfView", self.CameraBaseFOV)
        end

        local lighting = game:GetService("Lighting")
        for _, object in ipairs(lighting:GetChildren()) do
            local lower = string.lower(tostring(object.Name or ""))
            local cameraVisual = object:IsA("BlurEffect")
                or string.find(lower, "flash", 1, true)
                or string.find(lower, "damage", 1, true)
                or string.find(lower, "injury", 1, true)
            if cameraVisual and object:IsA("PostEffect") then
                if self.OriginalCameraEffects[object] == nil then
                    self.OriginalCameraEffects[object] = self.SafeGet(object, "Enabled")
                end
                self.SafeSet(object, "Enabled", false)
            end
        end
    end

    function Performance:SetDisableCameraEffects(enabled)
        State.DisableCameraEffectsEnabled = enabled == true
        if State.DisableCameraEffectsEnabled then
            local camera = Workspace.CurrentCamera
            self.CameraBaseFOV = camera and math.clamp(tonumber(camera.FieldOfView) or 70, 55, 90) or 70
            self:ApplyCameraEffectsPolicy()
        else
            for object, wasEnabled in pairs(self.OriginalCameraEffects) do
                if object and object.Parent then self.SafeSet(object, "Enabled", wasEnabled) end
                self.OriginalCameraEffects[object] = nil
            end
            local camera = Workspace.CurrentCamera
            if camera and self.CameraBaseFOV then self.SafeSet(camera, "FieldOfView", self.CameraBaseFOV) end
        end
    end

    function Performance:SetSleepUIWhenHidden(enabled)
        State.SleepUIWhenHiddenEnabled = enabled == true
    end

    function Performance:SetRemoveFog(enabled)
        State.RemoveFogEnabled = enabled == true
        self:ReconcileLighting()
    end

    function Performance:SetPostProcessingDisabled(enabled)
        State.DisablePostProcessingEnabled = enabled == true
        self:ReconcileLighting()
    end
    function Performance:IsDeadTitanModel(model)
        if not model or not model:IsA("Model") or not model.Parent then return false end
        local lower = string.lower(model.Name)
        if string.find(lower, "boss", 1, true) then return false end
        local humanoid = model:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health > 0 then return false end
        if string.find(lower, "titan", 1, true) then return true end
        local parentName = model.Parent and string.lower(model.Parent.Name) or ""
        return string.find(parentName, "titan", 1, true) ~= nil
    end

    function Performance:CleanupDeadTitans()
        if State.CleanupDeadTitansEnabled ~= true then return 0 end
        local now = os.clock()
        local removed = 0
        for _, object in ipairs(Workspace:GetDescendants()) do
            if object:IsA("Model") and self:IsDeadTitanModel(object) then
                local firstSeen = self.DeadTitanSeenAt[object]
                if not firstSeen then
                    self.DeadTitanSeenAt[object] = now
                elseif now - firstSeen >= 2.0 then
                    self.DeadTitanSeenAt[object] = nil
                    pcall(function() object:Destroy() end)
                    removed += 1
                end
            end
        end
        return removed
    end

    function Performance:SetCleanupDeadTitans(enabled)
        State.CleanupDeadTitansEnabled = enabled == true
        if not State.CleanupDeadTitansEnabled then
            self.DeadTitanSeenAt = setmetatable({}, {__mode = "k"})
        end
    end

    function Performance:SetFPSCap(value)
        value = math.clamp(math.floor((tonumber(value) or 60) + 0.5), 30, 999)
        State.FPSCap = value
        local env = type(getgenv) == "function" and getgenv() or _G
        local setter = env.setfpscap or setfpscap
        if type(setter) ~= "function" then return false end
        return pcall(setter, value)
    end

    function Performance:Set3DRenderingDisabled(enabled)
        State.Disable3DRenderingEnabled = enabled == true
        local runService = game:GetService("RunService")
        return pcall(function()
            runService:Set3dRenderingEnabled(not State.Disable3DRenderingEnabled)
        end)
    end

	function Performance:SetEcoLoops(enabled)
		State.EcoLoopModeEnabled = enabled == true
		if State.EcoLoopModeEnabled then
			Config.LoopDelay = 0.05
			Config.TargetCacheLifetime = 0.35
			Config.CutsceneCheckDelay = 0.14
			Config.AutoRefillCheckDelay = 0.10
		else
			for key, value in pairs(self.DefaultConfig) do
				Config[key] = value
			end
		end
	end

	task.spawn(function()
		local lastPropCullAt = 0
        local lastDeadCleanupAt = 0
		while true do
			task.wait(Config.PerformanceRefreshDelay)
			if State.PerformanceModeEnabled then
				Performance:ApplyLowGraphics()
			end
			if State.DisableEffectsEnabled then
				Performance:ApplyNoEffects()
			end
            if State.RemoveFogEnabled then Performance:SetRemoveFog(true) end
            if State.DisablePostProcessingEnabled or State.SimpleLightingEnabled then Performance:ReconcileLighting() end
            if State.DisableCameraEffectsEnabled then Performance:ApplyCameraEffectsPolicy() end
            if State.CleanupDeadTitansEnabled and os.clock() - lastDeadCleanupAt >= 2.0 then
                lastDeadCleanupAt = os.clock()
                Performance:CleanupDeadTitans()
            end
			if State.MapPropsHiddenEnabled and os.clock() - lastPropCullAt >= Config.MapPropCullRefreshDelay then
				lastPropCullAt = os.clock()
				Performance:ApplyMapPropCull()
			end
		end
	end)
end


pcall(function()
    if State.RemoveInjuryKillFlashEnabled then Performance:SetRemoveInjuryKillFlash(true) end
    if State.RemoveDamageTextEnabled then Performance:SetRemoveDamageText(true) end
    if State.RemoveFogEnabled then Performance:SetRemoveFog(true) end
    if State.DisablePostProcessingEnabled then Performance:SetPostProcessingDisabled(true) end
    if State.SimpleLightingEnabled then Performance:SetSimpleLighting(true) end
    if State.LowDetailMapMaterialsEnabled then Performance:SetLowDetailMapMaterials(true) end
    if State.SleepUIWhenHiddenEnabled then Performance:SetSleepUIWhenHidden(true) end
    if State.DisableCameraEffectsEnabled then Performance:SetDisableCameraEffects(true) end
    if State.CleanupDeadTitansEnabled then Performance:SetCleanupDeadTitans(true) end
    Performance:SetFPSCap(State.FPSCap)
    if State.Disable3DRenderingEnabled then Performance:Set3DRenderingDisabled(true) end
end)

