local function applyThemePresetValues(name)
	local presetName = tostring(name or "Blue")
	local preset = ThemePresets[presetName] or ThemePresets.Blue
	PersistentSettings.ThemeName = ThemePresets[presetName] and presetName or "Blue"

	for key, value in pairs(preset) do
		Theme[key] = value
	end
	Theme.AccentColor = Theme.Accent
end

