local QuietMissionToastTitles = {
    ["teleport failed"] = true,
    ["out of blades"] = true,
    ["refill failed"] = true,
    ["premium only"] = true,
    ["premium feature"] = true,
    ["save failed"] = true,
    ["load failed"] = true,
    ["delete failed"] = true,
    ["unsupported"] = true,
    ["webhook failed"] = true,
    ["no config selected"] = true,
    ["waves upgrade"] = true,
    ["blade recovery"] = true,
}

local function normalizeMissionToast(title, message, kind)
    local resolvedTitle = tostring(title or "")
    local lowerTitle = string.lower(resolvedTitle)

    if lowerTitle == "teleport failed" then
        return "Teleport failed",
            "Could not return to the lobby.",
            "error"
    end

    if not QuietMissionToastTitles[lowerTitle] then
        return nil
    end

    return resolvedTitle, tostring(message or ""), kind
end

local notificationOrder = 0
showNotification = function(title, message, kind)
    title, message, kind = normalizeMissionToast(title, message, kind)
    if title == nil then return end
	notificationOrder += 1
	local isError = kind == "error"
	local isSuccess = kind == "success"
	local accent = isError and Color3.fromRGB(238, 105, 125)
		or (isSuccess and Color3.fromRGB(87, 206, 154) or Theme.AccentLight)

	local toast = Instance.new("CanvasGroup")
	toast.Name = "Toast"
	toast.LayoutOrder = notificationOrder
	toast.Size = UDim2.fromOffset(286, 58)
	toast.Position = UDim2.fromOffset(28, 0)
	toast.BackgroundColor3 = Color3.fromRGB(20, 18, 26)
	toast.BackgroundTransparency = 0.02
	toast.GroupTransparency = 1
	toast.BorderSizePixel = 0
	toast.ZIndex = 51
	toast.Parent = notificationHolder

	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 5)
	corner.Parent = toast

	local stroke = Instance.new("UIStroke")
	stroke.Color = accent
	stroke.Transparency = 0.28
	stroke.Thickness = 1
	stroke.Parent = toast

	local strip = Instance.new("Frame")
	strip.Size = UDim2.fromOffset(4, 42)
	strip.Position = UDim2.fromOffset(0, 10)
	strip.BackgroundColor3 = accent
	strip.BorderSizePixel = 0
	strip.ZIndex = 52
	strip.Parent = toast
	local stripCorner = Instance.new("UICorner")
	stripCorner.CornerRadius = UDim.new(1, 0)
	stripCorner.Parent = strip

	local titleText = Instance.new("TextLabel")
	titleText.Position = UDim2.fromOffset(15, 8)
	titleText.Size = UDim2.new(1, -28, 0, 20)
	titleText.BackgroundTransparency = 1
	titleText.Font = Enum.Font.GothamBold
	titleText.Text = tostring(title or "Notification")
	titleText.TextColor3 = Theme.Text
	titleText.TextSize = 12
	titleText.TextXAlignment = Enum.TextXAlignment.Left
	titleText.ZIndex = 52
	titleText.Parent = toast

	local messageText = Instance.new("TextLabel")
	messageText.Position = UDim2.fromOffset(15, 29)
	messageText.Size = UDim2.new(1, -28, 0, 24)
	messageText.BackgroundTransparency = 1
	messageText.Font = Enum.Font.Gotham
	messageText.Text = tostring(message or "")
	messageText.TextColor3 = Theme.TextMuted
	messageText.TextSize = 10
	messageText.TextWrapped = true
	messageText.TextXAlignment = Enum.TextXAlignment.Left
	messageText.TextYAlignment = Enum.TextYAlignment.Top
	messageText.ZIndex = 52
	messageText.Parent = toast

	TweenService:Create(toast, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
		GroupTransparency = 0,
		Position = UDim2.fromOffset(0, 0),
	}):Play()

	task.delay(2.8, function()
		if not toast.Parent then return end
		TweenService:Create(toast, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
			GroupTransparency = 1,
			Position = UDim2.fromOffset(24, 0),
		}):Play()
		task.delay(0.24, function()
			if toast.Parent then toast:Destroy() end
		end)
	end)
end


V51PhaseStats = V51PhaseStats or {
    SessionStartedAt = os.clock(),
    CurrentRaid = "Unknown",
    CurrentPhase = "Idle",
    PhaseStartedAt = os.clock(),
    Completed = 0,
    Failed = 0,
    TotalSeconds = 0,
    FastestSeconds = nil,
}

function V51PhaseStats.CurrentPhaseSeconds()
    return math.max(0, os.clock() - (V51PhaseStats.PhaseStartedAt or os.clock()))
end

function V51PhaseStats.Observe()
    if not V4RaidDirector or not V4RaidDirector.Enabled then return end
    local raid = tostring(V4RaidDirector.RaidName or "Unknown")
    local phase = tostring(V4RaidDirector.Phase or "Idle")
    if raid ~= V51PhaseStats.CurrentRaid or phase ~= V51PhaseStats.CurrentPhase then
        V51PhaseStats.CurrentRaid = raid
        V51PhaseStats.CurrentPhase = phase
        V51PhaseStats.PhaseStartedAt = os.clock()
    end
end

task.spawn(function()
    while true do
        task.wait(0.5)
        pcall(V51PhaseStats.Observe)
    end
end)

