    WavesRuntimeDirector.GearLastLevels = type(WavesRuntimeDirector.GearLastLevels) == "table" and WavesRuntimeDirector.GearLastLevels or {}
    WavesRuntimeDirector.HQNoProgress = type(WavesRuntimeDirector.HQNoProgress) == "table" and WavesRuntimeDirector.HQNoProgress or {}
    WavesRuntimeDirector.HQNextByKey = type(WavesRuntimeDirector.HQNextByKey) == "table" and WavesRuntimeDirector.HQNextByKey or {}
    WavesRuntimeDirector.GearKeys = WavesRuntimeDirector.GearKeys or {
        Blades = {
            "Crit_Chance",
            "Blade_Durability",
            "ODM_Damage",
            "Crit_Damage",
            "ODM_Speed",
            "ODM_Control",
