        },
    }
    WavesRuntimeDirector.HQKeys = WavesRuntimeDirector.HQKeys or {
        "Max",
        "Regen",
        "Refills",
        "Replenish",
    }

    local VirtualInputManager = game:GetService("VirtualInputManager")
    local GuiService = game:GetService("GuiService")

    local function premiumAllowed()
        return type(SliceHubWaveAutomationAllowed) == "function"
            and SliceHubWaveAutomationAllowed() == true
    end

    local function liveCharacter()
        local characterModel = player.Character
        local humanoidObject = characterModel and characterModel:FindFirstChildOfClass("Humanoid")
        local root = characterModel
            and (
                characterModel:FindFirstChild("HumanoidRootPart")
                or characterModel.PrimaryPart
            )
        if not characterModel or not humanoidObject or humanoidObject.Health <= 0 or not root then
            return nil, nil, nil
        end
        return characterModel, humanoidObject, root
    end

    local function waitUntil(predicate, timeout, interval)
        local started = os.clock()
        repeat
            local ok, result = pcall(predicate)
            if ok and result then return true end
            task.wait(interval or 0.04)
        until os.clock() - started >= (timeout or 2)
        return false
    end

    local function setStatus(value)
        WavesRuntimeDirector.Status = tostring(value or "Idle")
        local label = WavesRuntimeDirector.UIStatusLabel
        if label and label.Parent and not SliceHubUIShouldSleep() then
            label.Text = "Runtime: " .. WavesRuntimeDirector.Status
        end
    end

    function WavesRuntimeDirector.SetUpgradeStatus(value)
        WavesRuntimeDirector.UpgradeStatus = tostring(value or "Upgrades idle")
        local label = WavesRuntimeDirector.UIUpgradeStatusLabel
        if label and label.Parent and not SliceHubUIShouldSleep() then
            label.Text = "Upgrades: " .. WavesRuntimeDirector.UpgradeStatus
        end
    end

    function WavesRuntimeDirector.FormatUpgradeNumber(value)
        local number = tonumber(value)
        if number == nil then return tostring(value or "?") end
        if math.abs(number - math.floor(number + 0.5)) < 0.001 then
            return tostring(math.floor(number + 0.5))
        end
        return string.format("%.1f", number)
    end

    function WavesRuntimeDirector.FriendlyGearStat(key)
        local names = {
            Crit_Chance = "Crit Chance",
            Blade_Durability = "Blade Durability",
            ODM_Damage = "ODM Damage",
            Crit_Damage = "Crit Damage",
            ODM_Speed = "ODM Speed",
            ODM_Control = "ODM Control",
            ODM_Range = "ODM Range",
            ODM_Gas = "ODM Gas",
            TS_Damage = "Thunder Spear Damage",
            TS_Speed = "Thunder Spear Speed",
            TS_Control = "Thunder Spear Control",
            TS_Range = "Thunder Spear Range",
            TS_Gas = "Thunder Spear Gas",
            Blast_Radius = "Blast Radius",
        }
        return names[tostring(key or "")]
            or tostring(key or "Gear"):gsub("_", " ")
    end

    function WavesRuntimeDirector.FriendlyHQKey(key)
        local names = {
            Max = "Max Health",
            Regen = "Regen",
            Refills = "Refills",
            Replenish = "Replenish",
        }
        return names[tostring(key or "")]
            or tostring(key or "HQ")
    end

    function WavesRuntimeDirector.NotifyUpgrade(message, dedupeKey)
        local now = os.clock()
        local key = tostring(dedupeKey or message or "upgrade")
        if key == tostring(WavesRuntimeDirector.LastUpgradeNoticeKey or "")
            and now - (tonumber(WavesRuntimeDirector.LastUpgradeNoticeAt) or 0) < 0.80 then
            return false
        end

        WavesRuntimeDirector.LastUpgradeNoticeAt = now
        WavesRuntimeDirector.LastUpgradeNoticeKey = key
        showNotification(
            "Waves upgrade",
            tostring(message or "Upgrade confirmed"),
            "success"
        )
        return true
    end

    function WavesRuntimeDirector.ReadHQHealth()
        if not playerGui then return nil, nil end

        for _, object in ipairs(playerGui:GetDescendants()) do
            if (
                object:IsA("TextLabel")
                or object:IsA("TextButton")
                or object:IsA("TextBox")
            )
                and object.Visible == true
                and object.AbsoluteSize.X > 0
                and object.AbsoluteSize.Y > 0 then

                local text = string.lower(
                    tostring(object.Text or "")
                )
                text = string.gsub(text, "<.->", "")
                text = string.gsub(text, ",", "")
                text = string.gsub(text, "%s+", " ")

                local current, maximum = string.match(
                    text,
                    "defend%s+hq%s*%[%s*([%d%.]+)%s*/%s*([%d%.]+)%s*%]"
                )

                if current and maximum then
                    return tonumber(current), tonumber(maximum)
                end
            end
        end

        return nil, nil
    end

    function WavesRuntimeDirector.LiveTitanCount()
        local ok, count = pcall(getCachedAliveTitanCount)
        if ok and tonumber(count) ~= nil then
            return math.max(0, math.floor(tonumber(count) + 0.5))
        end

        local folder = Workspace:FindFirstChild(Config.TitansFolderName or "Titans")
        if not folder then return 0 end
        local total = 0
        for _, titan in ipairs(folder:GetChildren()) do
            local alive = false
            pcall(function() alive = isTitanAlive(titan) == true end)
            if alive then total += 1 end
        end
        return total
    end

    function WavesRuntimeDirector.CutsceneBusy()
        -- Live Titans and a visible READY phase are authoritative. Some Waves
        -- attributes remain stale after transitions and used to pause combat
        -- or upgrades indefinitely.
        if WavesRuntimeDirector.LiveTitanCount() > 0 then
            return false
        end
        if type(WavesRuntimeDirector.FindReadyGui) == "function" then
            local ready = WavesRuntimeDirector.FindReadyGui()
            if ready and ready.Visible then
                return false
            end
        end

        if V94CutsceneDirector
            and tostring(V94CutsceneDirector.State or "IDLE") ~= "IDLE" then
            return true
        end

        local objective = WavesRuntimeDirector.GetObjective()
        if objective then
            local countdown = tonumber(objective:GetAttribute("Countdown"))
            local show = objective:GetAttribute("Show")
            local phase = string.lower(tostring(objective:GetAttribute("Phase") or ""))
            if countdown and countdown > 0 then return true end
            if show == true and (phase == "start" or phase == "skip" or phase == "ready") then
                return true
            end
        end
        return false
    end

    function WavesRuntimeDirector.ResetCombat(reason)
        local now = os.clock()
        if now - (tonumber(WavesRuntimeDirector.LastCacheResetAt) or 0) < 0.12 then
            return false
        end
        WavesRuntimeDirector.LastCacheResetAt = now

        pcall(function()
            cachedTitanCandidates = {}
            cachedTitanCandidatesAt = 0
        end)
        pcall(function() clearCurrentTarget(false) end)
        pcall(function()
            if V6ExactBlade then
                V6ExactBlade.Targets = {}
                V6ExactBlade.NextCycleAt = 0
                V6ExactBlade.Status = "WAVES_RESET"
            end
        end)
        pcall(function()
            if V58BladeEngine then
                V58BladeEngine.LastWave = {}
                V58BladeEngine.LastRefreshAt = 0
            end
        end)
        WavesRuntimeDirector.LastCombatProgressAt = now
        setStatus(tostring(reason or "Wave combat reset"))
        return true
    end

    function WavesRuntimeDirector.TitanCenter()
        local folder = Workspace:FindFirstChild(Config.TitansFolderName or "Titans")
        if not folder then return nil end
        local sum = Vector3.zero
        local count = 0
        for _, titan in ipairs(folder:GetChildren()) do
            local part = nil
            local alive = false
            pcall(function()
                alive = isTitanAlive(titan) == true
                if alive then part = getTitanTargetPart(titan) end
            end)
            if alive and part and part.Parent then
                sum += part.Position
                count += 1
            end
        end
        return count > 0 and (sum / count) or nil
    end

    function WavesRuntimeDirector.CaptureHold(force)
        local characterModel, _, root = liveCharacter()
        if not characterModel or not root then return nil end
        if not force and typeof(WavesRuntimeDirector.HoldCFrame) == "CFrame" then
            return WavesRuntimeDirector.HoldCFrame
        end

        local candidate = nil
        pcall(function()
            if V942AirLock and typeof(V942AirLock.LastSafeCFrame) == "CFrame"
                and V942AirLock.LastSafeCFrame.Position.Y > 25 then
                candidate = V942AirLock.LastSafeCFrame
            end
        end)

        local center = WavesRuntimeDirector.TitanCenter()
        if center then
            local height = math.clamp(tonumber(Config.SkyHeight) or 170, 95, 220)
            candidate = CFrame.lookAt(center + Vector3.new(0, height, 0), center)
        elseif not candidate then
            local position = root.Position
            if position.Y < 35 then position += Vector3.new(0, 125, 0) end
            candidate = CFrame.new(position) * (root.CFrame - root.CFrame.Position)
        end

        WavesRuntimeDirector.HoldCFrame = candidate
        return candidate
    end

    function WavesRuntimeDirector.HoldCharacter(reason)
        if WavesRuntimeDirector.Busy or State.WavesAutoFarmEnabled ~= true then return false end
        if V577MovementAuthority and V577MovementAuthority.Mode
            and V577MovementAuthority.Mode() ~= "NORMAL" then return false end

        local characterModel, humanoidObject, root = liveCharacter()
        if not characterModel or not root then return false end
        local hold = WavesRuntimeDirector.CaptureHold(false)
        if typeof(hold) ~= "CFrame" then return false end

        local needsSnap = (root.Position - hold.Position).Magnitude > 7
            or root.Position.Y < 25
            or root.AssemblyLinearVelocity.Y < -12
        if needsSnap or os.clock() - (tonumber(WavesRuntimeDirector.LastHoldAt) or 0) >= 0.14 then
            pcall(function()
                characterModel:PivotTo(hold)
                root.AssemblyAngularVelocity = Vector3.zero
                root.AssemblyLinearVelocity = Vector3.zero
                humanoidObject.Sit = false
                humanoidObject.PlatformStand = false
            end)
            WavesRuntimeDirector.LastHoldAt = os.clock()
        end

        pcall(function()
            if V942AirLock then V942AirLock.LastSafeCFrame = hold end
        end)
        if reason then setStatus(reason) end
        return true
    end

    function WavesRuntimeDirector.ObserveCombatProgress(alive)
        alive = math.max(0, tonumber(alive) or 0)
        local previous = math.max(0, tonumber(WavesRuntimeDirector.LastAliveCount) or 0)
        local now = os.clock()

        if alive > 0 and previous <= 0 then
            WavesRuntimeDirector.WaveSerial += 1
            WavesRuntimeDirector.HoldCFrame = nil
            WavesRuntimeDirector.CaptureHold(true)
            WavesRuntimeDirector.ResetCombat("Wave " .. tostring(WavesRuntimeDirector.WaveSerial) .. " detected")
        elseif alive < previous then
            WavesRuntimeDirector.LastCombatProgressAt = now
            WavesRuntimeDirector.CaptureHold(true)
        elseif alive > 0 and now - (tonumber(WavesRuntimeDirector.LastCombatProgressAt) or now) >= 4.0 then
            WavesRuntimeDirector.ResetCombat("No-target recovery • reacquiring live Titans")
            State.FarmEnabled = true
        end

        if alive <= 0 and previous > 0 then
            WavesRuntimeDirector.CaptureHold(true)
            WavesRuntimeDirector.LastCombatProgressAt = now
        end
        WavesRuntimeDirector.LastAliveCount = alive
    end

    if not WavesRuntimeDirector.CharacterConnection then
        WavesRuntimeDirector.CharacterConnection = player.CharacterAdded:Connect(function(newCharacter)
            WavesRuntimeDirector.LastCharacter = newCharacter
            WavesRuntimeDirector.HoldCFrame = nil
            WavesRuntimeDirector.RoundActiveSince = nil
            WavesRuntimeDirector.LastAliveCount = 0
            WavesRuntimeDirector.LastCombatProgressAt = os.clock()
            task.delay(1.0, function()
                if State.WavesAutoFarmEnabled == true and premiumAllowed() then
                    WavesRuntimeDirector.ResetCombat("Respawn recovery")
                    WavesRuntimeDirector.CaptureHold(true)
                end
            end)
        end)
    end

    function WavesRuntimeDirector.IsRuntime()
        local waves = Workspace:FindFirstChild("Waves")
        local unclimbable = Workspace:FindFirstChild("Unclimbable")
        local objective = unclimbable and unclimbable:FindFirstChild("Objective")
        local waveObjective = objective and objective:FindFirstChild("Waves")
        return waves ~= nil and waveObjective ~= nil
    end

    function WavesRuntimeDirector.GetObjective()
        local unclimbable = Workspace:FindFirstChild("Unclimbable")
        local objective = unclimbable and unclimbable:FindFirstChild("Objective")
        return objective and objective:FindFirstChild("Waves")
    end

    function WavesRuntimeDirector.GetCratesFolder()
        local waves = Workspace:FindFirstChild("Waves")
        return waves and waves:FindFirstChild("Crates")
    end

    -- Combat readiness and crate readiness are separate.
    -- A late-loaded script can enter after READY was already pressed, while
    -- Workspace.Waves.Crates is absent or between crate cycles. That must not
    -- disable the proven blade engine or incorrectly demand a rejoin.
    function WavesRuntimeDirector.IsServerSetupReady()
        local waves = Workspace:FindFirstChild("Waves")
        if not waves then
            return false, "Waiting for Workspace.Waves"
        end

        local objective = WavesRuntimeDirector.GetObjective()
        if not objective then
            return false, "Waiting for Waves objective"
        end

        return true, "Waves runtime ready"
    end

    function WavesRuntimeDirector.IsCrateSetupReady(requireDropoff)
        local waves = Workspace:FindFirstChild("Waves")
        if not waves then
            return false, "Waiting for Workspace.Waves"
        end

        local crates = waves:FindFirstChild("Crates")
        if not crates or not crates:IsA("Folder") then
            return false, "Waiting for live crate system"
        end

        if requireDropoff == true then
            local props = waves:FindFirstChild("Props")
            local dropoff = props and props:FindFirstChild("Dropoff")
            if not dropoff then
                return false, "Waiting for crate delivery station"
            end
        end

        return true, "Crate system ready"
    end

    -- The Waves map creates a temporary/pre-wave crate while the READY
    -- countdown and cutscene are still active. Moving to that crate can leave
    -- the character on a roof or at an unloaded spawn when the server deletes
    -- it at round start. Combat and crate movement are therefore armed only
    -- after the READY/countdown state has fully cleared and remained stable.
    function WavesRuntimeDirector.IsRoundActive()
        if not WavesRuntimeDirector.IsRuntime() then
            WavesRuntimeDirector.RoundActiveSince = nil
            WavesRuntimeDirector.RoundGateReason = "Waiting for Waves runtime"
            return false, WavesRuntimeDirector.RoundGateReason
        end

        local setupReady, setupReason = WavesRuntimeDirector.IsServerSetupReady()
        if not setupReady then
            WavesRuntimeDirector.RoundActiveSince = nil
            WavesRuntimeDirector.RoundGateReason = setupReason or "Waiting for Waves server setup"
            return false, WavesRuntimeDirector.RoundGateReason
        end

        local alive = WavesRuntimeDirector.LiveTitanCount()
        if alive <= 0 then
            WavesRuntimeDirector.RoundActiveSince = nil
            WavesRuntimeDirector.RoundGateReason = WavesRuntimeDirector.CutsceneBusy()
                and "Wave transition / cutscene"
                or "Waiting for next wave"
            return false, WavesRuntimeDirector.RoundGateReason
        end

        -- Live server Titans are authoritative. The Ready/Show attributes can
        -- remain stale between rounds, which previously disabled blades forever.
        if WavesRuntimeDirector.CutsceneBusy() then
            WavesRuntimeDirector.RoundActiveSince = nil
            WavesRuntimeDirector.RoundGateReason = "Waiting for cutscene release"
            return false, WavesRuntimeDirector.RoundGateReason
        end

        local now = os.clock()
        if not WavesRuntimeDirector.RoundActiveSince then
            WavesRuntimeDirector.RoundActiveSince = now
            WavesRuntimeDirector.RoundGateReason = "Wave spawned; stabilizing"
            return false, WavesRuntimeDirector.RoundGateReason
        end
        if now - WavesRuntimeDirector.RoundActiveSince < 0.20 then
            WavesRuntimeDirector.RoundGateReason = "Wave spawned; stabilizing"
            return false, WavesRuntimeDirector.RoundGateReason
        end

        WavesRuntimeDirector.RoundGateReason = "Wave active • " .. tostring(alive) .. " Titans"
        return true, WavesRuntimeDirector.RoundGateReason
    end

    function WavesRuntimeDirector.GetDropoff()
        local waves = Workspace:FindFirstChild("Waves")
        local props = waves and waves:FindFirstChild("Props")
        return props and props:FindFirstChild("Dropoff")
    end

    function WavesRuntimeDirector.GetPlayerCrate()
        local folder = WavesRuntimeDirector.GetCratesFolder()
        if not folder then return nil end

        -- Waves creates one server-owned crate per player. Never fall back to
        -- another player's crate in multiplayer servers.
        local exact = folder:FindFirstChild("Crate_" .. tostring(player.Name))
        return exact and exact:IsA("Model") and exact or nil
    end

    function WavesRuntimeDirector.GetCrateHitbox(crate)
        if not crate then return nil end
        local hitbox = crate:FindFirstChild("Hitbox")
        if hitbox and hitbox:IsA("BasePart") then return hitbox end
        return crate:FindFirstChildWhichIsA("BasePart", true)
    end

    function WavesRuntimeDirector.MoveCharacter(targetPosition, lookPosition)
        if typeof(targetPosition) ~= "Vector3" then return false end
        local characterModel, humanoidObject, root = liveCharacter()
        if not characterModel then return false end

        local look = typeof(lookPosition) == "Vector3"
            and lookPosition
            or targetPosition + Vector3.new(0, 0, -1)
        if (look - targetPosition).Magnitude < 0.05 then
            look = targetPosition + Vector3.new(0, 0, -1)
        end

        characterModel:PivotTo(CFrame.lookAt(targetPosition, look))
        root.AssemblyAngularVelocity = Vector3.zero
        root.AssemblyLinearVelocity = Vector3.zero
        humanoidObject.Sit = false
        humanoidObject.PlatformStand = false
        return true
    end

    function WavesRuntimeDirector.BeginMovement(reason)
        if WavesRuntimeDirector.Busy then return false end

        local _, _, root = liveCharacter()
        WavesRuntimeDirector.MovementOriginCFrame = root and root.CFrame or nil
        WavesRuntimeDirector.Busy = true
        WavesRuntimeDirector.ResumeFarmAfterMove = State.FarmEnabled == true
        State.FarmEnabled = false
        pcall(function() clearCurrentTarget(false) end)
        setStatus(reason or "Crate movement")
        return true
    end

    function WavesRuntimeDirector.EndMovement(reason, restoreOrigin)
        local resume = WavesRuntimeDirector.ResumeFarmAfterMove == true
        local origin = WavesRuntimeDirector.MovementOriginCFrame

        WavesRuntimeDirector.ResumeFarmAfterMove = false
        WavesRuntimeDirector.MovementOriginCFrame = nil
        WavesRuntimeDirector.Busy = false
        WavesRuntimeDirector.CurrentCrate = nil

        -- Failed/pre-wave crate attempts must not strand the character at the
        -- temporary crate spawn. Successful pickup/delivery keeps its live
        -- position so the blade engine can naturally reacquire a target.
        if restoreOrigin == true and typeof(origin) == "CFrame" then
            local characterModel, humanoidObject, root = liveCharacter()
            if characterModel and root then
                pcall(function()
                    characterModel:PivotTo(origin)
                    root.AssemblyAngularVelocity = Vector3.zero
                    root.AssemblyLinearVelocity = Vector3.zero
                    humanoidObject.Sit = false
                    humanoidObject.PlatformStand = false
                end)
            end
        end

        if State.WavesAutoFarmEnabled == true
            and premiumAllowed()
            and WavesRuntimeDirector.IsRuntime() then
            local active = WavesRuntimeDirector.IsRoundActive()
            State.FarmEnabled = active == true
        elseif resume then
            State.FarmEnabled = true
        end

        setStatus(reason or "Idle")
    end

    function WavesRuntimeDirector.EnsureBladeFarm()
        if not premiumAllowed()
            or State.WavesAutoFarmEnabled ~= true
            or not WavesRuntimeDirector.IsRuntime()
            or WavesRuntimeDirector.Busy then
            return false
        end

        local alive = WavesRuntimeDirector.LiveTitanCount()
        WavesRuntimeDirector.ObserveCombatProgress(alive)
        local roundActive, gateReason = WavesRuntimeDirector.IsRoundActive()
        if not roundActive then
            if State.FarmEnabled == true then
                State.FarmEnabled = false
                pcall(function() clearCurrentTarget(false) end)
            end
            WavesRuntimeDirector.HoldCharacter(gateReason or "Waiting for next wave")
            return false
        end

        if State.BladesEnabled ~= true then
            WavesRuntimeDirector.OwnedBlades = true
            State.BladesEnabled = true
            if Controls and Controls.Farm and Controls.Farm.Set then
                pcall(function() Controls.Farm:Set(true, true) end)
            end
        end

        if V5FarmRouter and V5FarmRouter.Sync then
            V5FarmRouter.Sync("waves controller active")
        else
            State.FarmEnabled = true
        end
        State.FarmEnabled = true

        if WavesRuntimeDirector.LastResetSerial ~= WavesRuntimeDirector.WaveSerial then
            WavesRuntimeDirector.LastResetSerial = WavesRuntimeDirector.WaveSerial
            WavesRuntimeDirector.ResetCombat("Wave combat armed")
        end

        WavesRuntimeDirector.CaptureHold(true)
        setStatus("Auto farming Waves • " .. tostring(alive) .. " Titans")
        return true
    end

    function WavesRuntimeDirector.DisableOwnedBladeFarm()
        if not WavesRuntimeDirector.OwnedBlades then return end
        WavesRuntimeDirector.OwnedBlades = false

        if Controls and Controls.Farm and Controls.Farm.Set then
            pcall(function() Controls.Farm:Set(false, true) end)
        else
            State.BladesEnabled = false
            if V5FarmRouter and V5FarmRouter.Sync then
                V5FarmRouter.Sync("waves auto farm disabled")
            else
                State.FarmEnabled = false
            end
        end
        WavesRuntimeDirector.HoldCFrame = nil
        WavesRuntimeDirector.LastAliveCount = 0
        WavesRuntimeDirector.RoundActiveSince = nil
    end

    function WavesRuntimeDirector.FindReadyGui()
        local function buttonText(button)
            local output = tostring(button.Text or "")
            for _, child in ipairs(button:GetDescendants()) do
                if child:IsA("TextLabel") or child:IsA("TextButton") then
                    output = output .. " " .. tostring(child.Text or "")
                end
            end
            output = string.upper(string.gsub(output, "%s+", " "))
            return output
        end

        local function eligible(object)
            if not object:IsA("GuiButton")
                or not object.Visible
                or object.AbsoluteSize.X <= 0
                or object.AbsoluteSize.Y <= 0 then
                return false
            end
            local text = buttonText(object)
            return string.find(text, "READY", 1, true) ~= nil
                or string.find(text, "VOTE SKIP", 1, true) ~= nil
                or string.find(text, "SKIP WAVE", 1, true) ~= nil
        end

        local interface = playerGui:FindFirstChild("Interface")
        local wavesGui = interface and interface:FindFirstChild("Waves")
        if wavesGui then
            for _, object in ipairs(wavesGui:GetDescendants()) do
                if eligible(object) then return object end
            end
        end

        for _, object in ipairs(playerGui:GetDescendants()) do
            if eligible(object) then return object end
        end
        return nil
    end

    function WavesRuntimeDirector.ReadyVoteAccepted()
        local interface = playerGui:FindFirstChild("Interface")
        local roots = {}
        local wavesGui = interface and interface:FindFirstChild("Waves")
        if wavesGui then roots[#roots + 1] = wavesGui end
        roots[#roots + 1] = playerGui

        for _, root in ipairs(roots) do
            local seen = 0
            for _, object in ipairs(root:GetDescendants()) do
                seen += 1
                if seen > 700 then break end
                if (object:IsA("TextLabel") or object:IsA("TextButton"))
                    and object.Visible then
                    local text = string.upper(string.gsub(tostring(object.Text or ""), "%s+", " "))
                    if string.find(text, "1/1", 1, true)
                        or string.find(text, "1 / 1", 1, true)
                        or string.find(text, "VOTE ACCEPTED", 1, true)
                        or string.find(text, "READY ACCEPTED", 1, true) then
                        return true
                    end
                end
            end
        end
        return false
    end

    function WavesRuntimeDirector.ObserveReadyPhase(alive)
        alive = math.max(0, tonumber(alive) or 0)
        local target = alive <= 0 and WavesRuntimeDirector.FindReadyGui() or nil
        if alive > 0 or not target or not target.Visible then
            WavesRuntimeDirector.ReadyPhaseLocked = false
            WavesRuntimeDirector.ReadyTarget = nil
            return nil
        end

        if WavesRuntimeDirector.ReadyTarget ~= target then
            WavesRuntimeDirector.ReadyTarget = target
            WavesRuntimeDirector.ReadyPhaseLocked = false
        end
        return target
    end

    function WavesRuntimeDirector.TryReady(target)
        if not premiumAllowed()
            or State.WavesAutoSkipEnabled ~= true
            or not WavesRuntimeDirector.IsRuntime()
            or WavesRuntimeDirector.LiveTitanCount() > 0 then
            return false
        end

        target = target or WavesRuntimeDirector.ObserveReadyPhase(0)
        if not target or not target.Visible then return false end

        if WavesRuntimeDirector.ReadyVoteAccepted() then
            WavesRuntimeDirector.ReadyPhaseLocked = true
            WavesRuntimeDirector.ReadyLastAcceptedAt = os.clock()
            setStatus("READY vote accepted • waiting for next wave")
            return true
        end
        if WavesRuntimeDirector.ReadyPhaseLocked == true then
            return false
        end

        local now = os.clock()
        if now - (WavesRuntimeDirector.LastReadyAttempt or 0) < 0.85 then
            return false
        end
        WavesRuntimeDirector.LastReadyAttempt = now
        WavesRuntimeDirector.ReadyPhaseLocked = true
        WavesRuntimeDirector.ReadyTarget = target

        local activated = pcall(function()
            target.Selectable = true
            GuiService.SelectedObject = target
            task.wait()
            VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
            task.wait(0.055)
            VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
        end)

        if not activated then
            WavesRuntimeDirector.ReadyPhaseLocked = false
            setStatus("READY UI navigation failed • retrying")
            return false
        end

        setStatus("READY selected through UI navigation")
        task.spawn(function()
            local accepted = waitUntil(function()
                return WavesRuntimeDirector.LiveTitanCount() > 0
                    or not target.Parent
                    or not target.Visible
                    or WavesRuntimeDirector.ReadyVoteAccepted()
            end, 1.35, 0.05)

            if accepted then
                WavesRuntimeDirector.ReadyLastAcceptedAt = os.clock()
                setStatus(
                    WavesRuntimeDirector.LiveTitanCount() > 0
                        and "Next wave detected"
                        or "READY vote accepted • waiting for next wave"
                )
            else
                setStatus("READY sent • awaiting vote confirmation")
            end
        end)
        return true
    end

    function WavesRuntimeDirector.Pickup(crate)
        if not crate or not crate.Parent then return false, "crate missing" end
        if crate:GetAttribute("Occupied") == true then return true, "already occupied" end
        if State.WavesAutoPickupEnabled ~= true then return false, "pickup disabled" end

        local hitbox = WavesRuntimeDirector.GetCrateHitbox(crate)
        if not hitbox then return false, "crate hitbox missing" end

        for attempt = 1, 6 do
            if not crate.Parent then return false, "crate removed" end
            if crate:GetAttribute("Occupied") == true then return true, "picked up" end

            local target = hitbox.Position + Vector3.new(0, 0.45, 0)
            WavesRuntimeDirector.MoveCharacter(target, hitbox.Position)

            local _, _, root = liveCharacter()
            local env = type(getgenv) == "function" and getgenv() or _G
            local touch = env and env.firetouchinterest or nil
            if root and type(touch) == "function" then
                pcall(function()
                    touch(root, hitbox, 0)
                    task.wait(0.03)
                    touch(root, hitbox, 1)
                end)
            end

            if waitUntil(function()
                return crate.Parent == nil
                    or crate:GetAttribute("Occupied") == true
            end, 0.48, 0.025) then
                return crate.Parent ~= nil, crate.Parent and "picked up" or "crate removed"
            end
        end

        return crate:GetAttribute("Occupied") == true, "pickup timeout"
    end

    function WavesRuntimeDirector.DropoffTargets(dropoff)
        local output = {}
        local pivot = dropoff:GetPivot()
        local center = pivot.Position

        -- Two confirmed deliveries landed roughly 8-13 studs from this live model.
        output[#output + 1] = center + Vector3.new(-10, 4, 2)
        output[#output + 1] = center + Vector3.new(-14, 4, 0)
        output[#output + 1] = center + Vector3.new(-7, 4, 6)
        output[#output + 1] = center + Vector3.new(0, 4, 0)
        output[#output + 1] = (pivot * CFrame.new(-10, 4, 2)).Position
        output[#output + 1] = (pivot * CFrame.new(-14, 4, 0)).Position

        local added = 0
        for _, object in ipairs(dropoff:GetDescendants()) do
            if object:IsA("BasePart") and object.Name == "Crate" then
                output[#output + 1] = object.Position + Vector3.new(0, 3.5, 0)
                added += 1
                if added >= 5 then break end
            end
        end

        return output, center
    end

    function WavesRuntimeDirector.Deliver(crate)
        if not crate or not crate.Parent then return true, "already removed" end
        if State.WavesAutoDeliverEnabled ~= true then return false, "delivery disabled" end
        if crate:GetAttribute("Occupied") ~= true then return false, "crate is not occupied" end

        local dropoff = WavesRuntimeDirector.GetDropoff()
        if not dropoff then return false, "Workspace.Waves.Props.Dropoff missing" end

        local targets, center = WavesRuntimeDirector.DropoffTargets(dropoff)
        for _, target in ipairs(targets) do
            if not crate.Parent then return true, "delivered" end
            WavesRuntimeDirector.MoveCharacter(target, center)

            if waitUntil(function()
                local folder = WavesRuntimeDirector.GetCratesFolder()
                return crate.Parent == nil
                    or not crate:IsDescendantOf(Workspace)
                    or (folder and not crate:IsDescendantOf(folder))
            end, 0.55, 0.025) then
                return true, "delivered"
            end
        end

        return not crate.Parent, crate.Parent and "dropoff timeout" or "delivered"
    end

    function WavesRuntimeDirector.ProcessCrate(crate)
        if not premiumAllowed()
            or WavesRuntimeDirector.Busy
            or not WavesRuntimeDirector.IsRuntime()
            or not crate
            or not crate.Parent then
            return false
        end

        local roundActive, gateReason = WavesRuntimeDirector.IsRoundActive()
        if not roundActive then
            setStatus((gateReason or "Waiting for wave start") .. " • crates paused")
            return false
        end

        local wantsPickup = State.WavesAutoPickupEnabled == true
        local wantsDeliver = State.WavesAutoDeliverEnabled == true
        local occupied = crate:GetAttribute("Occupied") == true

        if not occupied and not wantsPickup then return false end
        if occupied and not wantsDeliver then return false end
        if not WavesRuntimeDirector.BeginMovement("Claiming supply crate") then return false end

        WavesRuntimeDirector.CurrentCrate = crate

        task.spawn(function()
            local ok, success, reason = pcall(function()
                if crate:GetAttribute("Occupied") ~= true and wantsPickup then
                    setStatus("Picking up supply crate")
                    local picked, pickupReason = WavesRuntimeDirector.Pickup(crate)
                    if not picked then
                        return false, pickupReason
                    end
                end

                if crate.Parent
                    and crate:GetAttribute("Occupied") == true
                    and State.WavesAutoDeliverEnabled == true then
                    setStatus("Delivering supply crate")
                    return WavesRuntimeDirector.Deliver(crate)
                end

                return true, "crate picked up"
            end)

            if not ok then
                local restore = not crate.Parent
                    or crate:GetAttribute("Occupied") ~= true
                WavesRuntimeDirector.EndMovement(
                    "Crate error: " .. tostring(success),
                    restore
                )
            elseif success then
                if not crate.Parent then
                    WavesRuntimeDirector.EndMovement("Crate delivered")
                elseif crate:GetAttribute("Occupied") == true then
                    WavesRuntimeDirector.EndMovement(
                        State.WavesAutoDeliverEnabled == true
                            and "Crate delivery finished"
                            or "Crate picked up; delivery disabled"
                    )
                else
                    WavesRuntimeDirector.EndMovement(tostring(reason or "Crate action finished"))
                end
            else
                local restore = not crate.Parent
                    or crate:GetAttribute("Occupied") ~= true
                WavesRuntimeDirector.EndMovement(
                    "Crate failed: " .. tostring(reason or "unknown"),
                    restore
                )
            end
        end)

        return true
    end

    function WavesRuntimeDirector.GetUpgradeRemote()
        local assets = game:GetService("ReplicatedStorage"):FindFirstChild("Assets")
        local remotes = assets and assets:FindFirstChild("Remotes")
        local remote = remotes and remotes:FindFirstChild("GET")
        return remote and remote:IsA("RemoteFunction") and remote or nil
    end

    function WavesRuntimeDirector.NormalizeGearTarget(value)
        value = tostring(value or "Both")
        if value == "Blades" or value == "Thunder Spears" or value == "Both" then
            return value
        end
        return "Both"
    end

    function WavesRuntimeDirector.ResetUpgradeBackoff(reason)
        WavesRuntimeDirector.GearNextAt = 0
        WavesRuntimeDirector.HQNextAt = 0
        WavesRuntimeDirector.GearNoProgress = 0
        WavesRuntimeDirector.HQNoProgress = {}
        WavesRuntimeDirector.HQNextByKey = {}
        if reason then WavesRuntimeDirector.SetUpgradeStatus(reason) end
    end

    function WavesRuntimeDirector.GearTargetForPass()
        local selected = WavesRuntimeDirector.NormalizeGearTarget(State.WavesGearTarget)
        State.WavesGearTarget = selected
        if selected == "Blades" then return "Blades" end
        if selected == "Thunder Spears" then return "Spears" end
        WavesRuntimeDirector.GearBothIndex = (tonumber(WavesRuntimeDirector.GearBothIndex) or 0) + 1
        return WavesRuntimeDirector.GearBothIndex % 2 == 1 and "Blades" or "Spears"
    end

    function WavesRuntimeDirector.GearLevelGain(profile)
        if type(profile) ~= "table" then return nil, {} end
        local gain = 0
        local saw = false
        local changes = {}

        for _, weapon in ipairs({"Blades", "Spears"}) do
            local levels = type(profile[weapon]) == "table"
                and profile[weapon]
                or nil
            local previous =
                type(WavesRuntimeDirector.GearLastLevels[weapon]) == "table"
                and WavesRuntimeDirector.GearLastLevels[weapon]
                or nil

            if levels then
                local snapshot = {}
                for key, value in pairs(levels) do
                    local level = tonumber(value)
                    if level ~= nil then
                        snapshot[key] = level
                        local before = previous
                            and tonumber(previous[key])
                            or nil
                        if before ~= nil and level > before then
                            gain += level - before
                            changes[#changes + 1] = {
                                Weapon = weapon,
                                Key = tostring(key),
                                Before = before,
                                After = level,
                            }
                        end
                        saw = true
                    end
                end
                WavesRuntimeDirector.GearLastLevels[weapon] =
                    snapshot
            end
        end

        return saw and gain or nil, changes
    end

    function WavesRuntimeDirector.GearDetail(detail)
        if type(detail) ~= "table" then return nil, nil end
        local gold = tonumber(detail.Gold)
        local upgraded = nil
        for key, value in pairs(detail) do
            if key ~= "Gold" and (type(value) == "table" or tonumber(value) ~= nil) then
                upgraded = tostring(key)
                break
            end
        end
        return upgraded, gold
    end

    function WavesRuntimeDirector.RunGearUpgrade()
        local remote = WavesRuntimeDirector.GetUpgradeRemote()
        if not remote then
            WavesRuntimeDirector.GearNextAt = os.clock() + 12
            WavesRuntimeDirector.SetUpgradeStatus(
                "Gear paused • GET remote missing"
            )
            return
        end

        local weapon = WavesRuntimeDirector.GearTargetForPass()
        local keys = WavesRuntimeDirector.GearKeys[weapon]
        if type(keys) ~= "table" or #keys == 0 then
            WavesRuntimeDirector.GearNextAt = os.clock() + 12
            WavesRuntimeDirector.SetUpgradeStatus(
                "Gear paused • stat list missing"
            )
            return
        end

        local displayWeapon = weapon == "Spears"
            and "Thunder Spears"
            or "Blades"
        WavesRuntimeDirector.SetUpgradeStatus(
            "Gear • checking " .. displayWeapon
        )

        local ok, profile, detail = pcall(function()
            return remote:InvokeServer(
                "Equipment",
                "Upgrade",
                keys
            )
        end)

        if not ok then
            WavesRuntimeDirector.GearNextAt = os.clock() + 12
            WavesRuntimeDirector.SetUpgradeStatus(
                "Gear remote error • retrying later"
            )
            return
        end

        local gain, changes =
            WavesRuntimeDirector.GearLevelGain(profile)
        local upgraded, gold =
            WavesRuntimeDirector.GearDetail(detail)
        if gold ~= nil then
            WavesRuntimeDirector.GearLastGold = gold
        end

        if upgraded or (tonumber(gain) or 0) > 0 then
            WavesRuntimeDirector.GearNoProgress = 0
            WavesRuntimeDirector.GearNextAt = os.clock() + 1.25

            local change = type(changes) == "table"
                and changes[1]
                or nil
            local noticeWeapon = change
                and tostring(change.Weapon)
                or weapon
            local noticeWeaponName = noticeWeapon == "Spears"
                and "Thunder Spears"
                or "Blades"
            local statKey = tostring(
                upgraded
                or (change and change.Key)
                or ""
            )
            local statName = statKey ~= ""
                and WavesRuntimeDirector.FriendlyGearStat(statKey)
                or nil
            local notice = noticeWeaponName .. " upgraded"

            if statName then
                notice = noticeWeaponName
                    .. " • "
                    .. statName
                    .. " upgraded"
            end

            if change
                and tonumber(change.Before) ~= nil
                and tonumber(change.After) ~= nil then
                notice = noticeWeaponName
                    .. " • "
                    .. WavesRuntimeDirector.FriendlyGearStat(
                        change.Key
                    )
                    .. " "
                    .. WavesRuntimeDirector.FormatUpgradeNumber(
                        change.Before
                    )
                    .. " → "
                    .. WavesRuntimeDirector.FormatUpgradeNumber(
                        change.After
                    )
            end

            local goldText = gold ~= nil
                and (
                    " • Gold "
                    .. tostring(math.floor(gold + 0.5))
                )
                or ""
            WavesRuntimeDirector.SetUpgradeStatus(
                notice .. goldText
            )
            WavesRuntimeDirector.NotifyUpgrade(
                notice,
                noticeWeaponName .. ":" .. statKey
            )
            return
        end

        WavesRuntimeDirector.GearNoProgress = math.min(
            6,
            (tonumber(WavesRuntimeDirector.GearNoProgress) or 0) + 1
        )
        local delay = math.min(
            24,
            4 + WavesRuntimeDirector.GearNoProgress * 3
        )
        WavesRuntimeDirector.GearNextAt = os.clock() + delay
        local goldText = WavesRuntimeDirector.GearLastGold ~= nil
            and (
                " • Gold "
                .. tostring(
                    math.floor(
                        tonumber(WavesRuntimeDirector.GearLastGold)
                        + 0.5
                    )
                )
            )
            or ""
        WavesRuntimeDirector.SetUpgradeStatus(
            "Gear waiting • maxed or unaffordable • retry "
            .. tostring(delay)
            .. "s"
            .. goldText
        )
    end

    function WavesRuntimeDirector.HQFingerprint()
        local entries = {}
        local function relevant(name)
            name = string.lower(tostring(name or ""))
            return string.find(name, "max", 1, true)
                or string.find(name, "health", 1, true)
                or string.find(name, "hp", 1, true)
                or string.find(name, "regen", 1, true)
                or string.find(name, "refill", 1, true)
                or string.find(name, "replen", 1, true)
                or string.find(name, "upgrade", 1, true)
                or string.find(name, "fund", 1, true)
                or string.find(name, "cash", 1, true)
                or string.find(name, "money", 1, true)
                or string.find(name, "point", 1, true)
                or string.find(name, "resource", 1, true)
        end
        local function collect(root, label)
            if not root then return end
            pcall(function()
                for name, value in pairs(root:GetAttributes()) do
                    if relevant(name) and (type(value) == "number" or type(value) == "boolean" or type(value) == "string") then
                        entries[#entries + 1] = label .. ":A:" .. tostring(name) .. "=" .. tostring(value)
                    end
                end
            end)
            local seen = 0
            pcall(function()
                for _, object in ipairs(root:GetDescendants()) do
                    seen += 1
                    if seen > 180 then break end
                    if relevant(object.Name) then
                        if object:IsA("NumberValue") or object:IsA("IntValue") or object:IsA("StringValue") or object:IsA("BoolValue") then
                            entries[#entries + 1] = label .. ":V:" .. object:GetFullName() .. "=" .. tostring(object.Value)
                        end
                        for name, value in pairs(object:GetAttributes()) do
                            if relevant(name) and (type(value) == "number" or type(value) == "boolean" or type(value) == "string") then
                                entries[#entries + 1] = label .. ":D:" .. object:GetFullName() .. ":" .. tostring(name) .. "=" .. tostring(value)
                            end
                        end
                    end
                end
            end)
        end
        collect(player, "P")
        collect(Workspace:FindFirstChild("Waves"), "W")
        collect(WavesRuntimeDirector.GetObjective(), "O")
        table.sort(entries)
        return table.concat(entries, "|")
    end

    function WavesRuntimeDirector.HQKeyEnabled(key)
        local map = {
            Max = State.WavesHQMaxEnabled ~= false,
            Regen = State.WavesHQRegenEnabled ~= false,
            Refills = State.WavesHQRefillsEnabled ~= false,
            Replenish = State.WavesHQReplenishEnabled ~= false,
        }
        return map[tostring(key or "")] == true
    end

    function WavesRuntimeDirector.HasEnabledHQUpgrade()
        for _, key in ipairs(WavesRuntimeDirector.HQKeys) do
            if WavesRuntimeDirector.HQKeyEnabled(key) then return true end
        end
        return false
    end

    function WavesRuntimeDirector.RunHQUpgrade()
        local remote = WavesRuntimeDirector.GetUpgradeRemote()
        if not remote then
            WavesRuntimeDirector.HQNextAt = os.clock() + 12
            WavesRuntimeDirector.SetUpgradeStatus(
                "HQ paused • GET remote missing"
            )
            return
        end

        local now = os.clock()
        if not WavesRuntimeDirector.HasEnabledHQUpgrade() then
            WavesRuntimeDirector.HQNextAt = now + 3
            WavesRuntimeDirector.SetUpgradeStatus(
                "HQ armed • select at least one upgrade"
            )
            return
        end

        local count = #WavesRuntimeDirector.HQKeys
        local key = nil
        for _ = 1, count do
            WavesRuntimeDirector.HQIndex = (
                (tonumber(WavesRuntimeDirector.HQIndex) or 0)
                % count
            ) + 1
            local candidate =
                WavesRuntimeDirector.HQKeys[
                    WavesRuntimeDirector.HQIndex
                ]
            if WavesRuntimeDirector.HQKeyEnabled(candidate)
                and now >= (
                    tonumber(
                        WavesRuntimeDirector.HQNextByKey[candidate]
                    ) or 0
                ) then
                key = candidate
                break
            end
        end

        if not key then
            WavesRuntimeDirector.HQNextAt = now + 1.0
            return
        end

        local friendlyKey =
            WavesRuntimeDirector.FriendlyHQKey(key)
        WavesRuntimeDirector.SetUpgradeStatus(
            "HQ • checking " .. friendlyKey
        )

        local beforeCurrent, beforeMax =
            WavesRuntimeDirector.ReadHQHealth()
        local beforeFingerprint =
            WavesRuntimeDirector.HQFingerprint()
        local ok = pcall(function()
            remote:InvokeServer(
                "Waves",
                "Upgrade",
                {key}
            )
        end)

        if not ok then
            WavesRuntimeDirector.HQNextByKey[key] =
                os.clock() + 12
            WavesRuntimeDirector.HQNextAt =
                os.clock() + 2
            WavesRuntimeDirector.SetUpgradeStatus(
                "HQ "
                .. friendlyKey
                .. " remote error • backed off"
            )
            return
        end

        local changed = false
        local afterCurrent = beforeCurrent
        local afterMax = beforeMax
        local changedBy = nil
        local verifyUntil = os.clock() + 1.65

        repeat
            task.wait(0.08)
            afterCurrent, afterMax =
                WavesRuntimeDirector.ReadHQHealth()

            if key == "Max"
                and beforeMax ~= nil
                and afterMax ~= nil
                and afterMax > beforeMax + 0.01 then
                changed = true
                changedBy = "MAX"
                break
            end

            if key == "Replenish"
                and beforeCurrent ~= nil
                and afterCurrent ~= nil
                and afterCurrent > beforeCurrent + 0.25 then
                changed = true
                changedBy = "CURRENT"
                break
            end

            if (
                key ~= "Max"
                and key ~= "Replenish"
            )
                or (
                    key == "Max"
                    and beforeMax == nil
                )
                or (
                    key == "Replenish"
                    and beforeCurrent == nil
                ) then
                if beforeFingerprint
                    ~= WavesRuntimeDirector.HQFingerprint() then
                    changed = true
                    changedBy = "FINGERPRINT"
                    break
                end
            end
        until os.clock() >= verifyUntil

        if changed then
            WavesRuntimeDirector.HQNoProgress[key] = 0
            WavesRuntimeDirector.HQNextByKey[key] =
                os.clock() + 2.2
            WavesRuntimeDirector.HQNextAt =
                os.clock() + 1.35

            local notice = "HQ " .. friendlyKey .. " upgraded"
            if changedBy == "MAX" then
                notice = "HQ Max Health "
                    .. WavesRuntimeDirector.FormatUpgradeNumber(
                        beforeMax
                    )
                    .. " → "
                    .. WavesRuntimeDirector.FormatUpgradeNumber(
                        afterMax
                    )
            elseif changedBy == "CURRENT" then
                notice = "HQ replenished "
                    .. WavesRuntimeDirector.FormatUpgradeNumber(
                        beforeCurrent
                    )
                    .. " → "
                    .. WavesRuntimeDirector.FormatUpgradeNumber(
                        afterCurrent
                    )
            end

            WavesRuntimeDirector.SetUpgradeStatus(notice)
            WavesRuntimeDirector.NotifyUpgrade(
                notice,
                "HQ:" .. tostring(key)
            )
            return
        end

        local misses = math.min(
            5,
            (
                tonumber(
                    WavesRuntimeDirector.HQNoProgress[key]
                ) or 0
            ) + 1
        )
        WavesRuntimeDirector.HQNoProgress[key] = misses
        local delay = math.min(24, 3 + misses * 4)
        WavesRuntimeDirector.HQNextByKey[key] =
            os.clock() + delay
        WavesRuntimeDirector.HQNextAt =
            os.clock() + 1.35
        WavesRuntimeDirector.SetUpgradeStatus(
            "HQ "
            .. friendlyKey
            .. " sent • no confirmed change • retry "
            .. tostring(delay)
            .. "s"
        )
    end

    function WavesRuntimeDirector.TickUpgrades()
        local gear = State.WavesAutoUpgradeGearEnabled == true
        local hqRequested = State.WavesAutoUpgradeHQEnabled == true
        local hq = hqRequested and WavesRuntimeDirector.HasEnabledHQUpgrade()
        if hqRequested and not hq and not gear then
            WavesRuntimeDirector.SetUpgradeStatus("HQ armed • select at least one upgrade")
            return false
        end
        if not gear and not hq then
            if WavesRuntimeDirector.UpgradeStatus ~= "Upgrades idle" then
                WavesRuntimeDirector.SetUpgradeStatus("Upgrades idle")
            end
            return false
        end
        if WavesRuntimeDirector.UpgradeBusy or WavesRuntimeDirector.Busy then return false end
        if WavesRuntimeDirector.CutsceneBusy() then
            WavesRuntimeDirector.SetUpgradeStatus("Paused during wave transition")
            return false
        end

        local now = os.clock()
        local gearDue = gear and now >= (tonumber(WavesRuntimeDirector.GearNextAt) or 0)
        local hqDue = hq and now >= (tonumber(WavesRuntimeDirector.HQNextAt) or 0)
        if not gearDue and not hqDue then return false end

        local kind
        if gearDue and hqDue then
            kind = WavesRuntimeDirector.UpgradeTurn == "Gear" and "Gear" or "HQ"
        elseif gearDue then
            kind = "Gear"
        else
            kind = "HQ"
        end
        WavesRuntimeDirector.UpgradeTurn = kind == "Gear" and "HQ" or "Gear"
        WavesRuntimeDirector.UpgradeBusy = true
        task.spawn(function()
            local ok, err = pcall(function()
                if kind == "Gear" then
                    WavesRuntimeDirector.RunGearUpgrade()
                else
                    WavesRuntimeDirector.RunHQUpgrade()
                end
            end)
            if not ok then
                if kind == "Gear" then
                    WavesRuntimeDirector.GearNextAt = os.clock() + 12
                else
                    WavesRuntimeDirector.HQNextAt = os.clock() + 12
                end
                WavesRuntimeDirector.SetUpgradeStatus(kind .. " error • " .. string.sub(tostring(err), 1, 90))
            end
            WavesRuntimeDirector.UpgradeBusy = false
        end)
        return true
    end

    function WavesRuntimeDirector.BindCratesFolder(folder)
        if WavesRuntimeDirector.BoundFolder == folder then return end
        if WavesRuntimeDirector.FolderConnection then
            pcall(function() WavesRuntimeDirector.FolderConnection:Disconnect() end)
        end

        WavesRuntimeDirector.BoundFolder = folder
        WavesRuntimeDirector.FolderConnection = folder.ChildAdded:Connect(function(child)
            if not child:IsA("Model")
                or child.Name ~= ("Crate_" .. tostring(player.Name)) then
                return
            end

            task.defer(function()
                task.wait(0.03)
                if State.WavesAutoPickupEnabled == true then
                    WavesRuntimeDirector.ProcessCrate(child)
                end
            end)
        end)
    end

    task.spawn(function()
        while true do
            task.wait(0.08)

            if not premiumAllowed() then
                State.WavesAutoFarmEnabled = false
                State.WavesAutoSkipEnabled = false
                State.WavesAutoPickupEnabled = false
                State.WavesAutoDeliverEnabled = false
                State.WavesAutoUpgradeGearEnabled = false
                State.WavesAutoUpgradeHQEnabled = false
                WavesRuntimeDirector.SetUpgradeStatus("Premium only")
                WavesRuntimeDirector.DisableOwnedBladeFarm()
                continue
            end

            if not WavesRuntimeDirector.IsRuntime() then
                if not WavesRuntimeDirector.Busy then setStatus("Waiting for Waves runtime") end
                if State.WavesAutoUpgradeGearEnabled == true or State.WavesAutoUpgradeHQEnabled == true then
                    WavesRuntimeDirector.SetUpgradeStatus("Waiting for Waves runtime")
                end
                continue
            end

            local characterModel = select(1, liveCharacter())
            if not characterModel then
                State.FarmEnabled = false
                setStatus("Waiting for respawn")
                if State.WavesAutoUpgradeGearEnabled == true or State.WavesAutoUpgradeHQEnabled == true then
                    WavesRuntimeDirector.SetUpgradeStatus("Waiting for respawn")
                end
                continue
            end

            local setupReady, setupReason = WavesRuntimeDirector.IsServerSetupReady()
            local folder = WavesRuntimeDirector.GetCratesFolder()
            if folder then WavesRuntimeDirector.BindCratesFolder(folder) end

            if not setupReady then
                if not WavesRuntimeDirector.Busy then
                    setStatus(setupReason or "Waiting for Waves runtime")
                end
                State.FarmEnabled = false
                pcall(function() clearCurrentTarget(false) end)
                WavesRuntimeDirector.HoldCharacter(setupReason)
                if State.WavesAutoUpgradeGearEnabled == true or State.WavesAutoUpgradeHQEnabled == true then
                    WavesRuntimeDirector.SetUpgradeStatus(setupReason or "Waiting for Waves runtime")
                end
                continue
            end

            WavesRuntimeDirector.TickUpgrades()

            local alive = WavesRuntimeDirector.LiveTitanCount()
            local readyTarget = WavesRuntimeDirector.ObserveReadyPhase(alive)
            if State.WavesAutoSkipEnabled == true and readyTarget then
                WavesRuntimeDirector.TryReady(readyTarget)
            end

            if State.WavesAutoFarmEnabled == true then
                WavesRuntimeDirector.ObserveCombatProgress(alive)
                if alive <= 0 then
                    State.FarmEnabled = false
                    pcall(function() clearCurrentTarget(false) end)
                    WavesRuntimeDirector.HoldCharacter(
                        readyTarget
                            and (
                                State.WavesAutoSkipEnabled == true
                                    and "READY visible • UI navigation armed"
                                    or "READY visible • Auto Wave Skip off"
                            )
                            or (
                                WavesRuntimeDirector.CutsceneBusy()
                                    and "Holding safely through wave transition"
                                    or "Holding safely • waiting for next wave"
                            )
                    )
                else
                    WavesRuntimeDirector.EnsureBladeFarm()
                end
            elseif WavesRuntimeDirector.OwnedBlades then
                WavesRuntimeDirector.DisableOwnedBladeFarm()
            end

            if not WavesRuntimeDirector.Busy then
                local roundActive, gateReason = WavesRuntimeDirector.IsRoundActive()
                local crateAutomation = State.WavesAutoPickupEnabled == true
                    or State.WavesAutoDeliverEnabled == true

                if crateAutomation and not roundActive then
                    if State.WavesAutoFarmEnabled ~= true then
                        setStatus((gateReason or "Waiting for wave start") .. " • crates paused")
                    end
                elseif crateAutomation then
                    local crateReady, crateReason =
                        WavesRuntimeDirector.IsCrateSetupReady(
                            State.WavesAutoDeliverEnabled == true
                        )

                    if not crateReady then
                        if State.WavesAutoFarmEnabled == true and roundActive then
                            setStatus(
                                "Auto farming Waves • "
                                .. tostring(crateReason or "waiting for crates")
                            )
                        else
                            setStatus(crateReason or "Waiting for live crate system")
                        end
                    else
                        local crate = WavesRuntimeDirector.GetPlayerCrate()
                        if crate then
                            local occupied = crate:GetAttribute("Occupied") == true
                            if (not occupied and State.WavesAutoPickupEnabled == true)
                                or (occupied and State.WavesAutoDeliverEnabled == true) then
                                WavesRuntimeDirector.ProcessCrate(crate)
                            end
                        elseif State.WavesAutoFarmEnabled ~= true then
                            setStatus("Waiting for supply crate")
                        end
                    end
                elseif State.WavesAutoFarmEnabled ~= true then
                    setStatus("Waves runtime ready")
                end
            end
        end
    end)
end)()

