    -- V9.8.2.9.8 mobile viewport guard.
    -- The Settings slider used to overwrite this fitted scale with 0.8-1.2,
    -- restoring the full desktop canvas on phones. Keep one authoritative
    -- scale calculation and bound the requested desktop scale to the viewport.
    function updateV1Scale()
        local camera = Workspace.CurrentCamera
        if not camera then return end

        local viewport = camera.ViewportSize
        if viewport.X < 240 or viewport.Y < 200 then return end

        local isCompact =
            UserInputService.TouchEnabled
            or viewport.Y < 560
            or viewport.X < 760

        local horizontalMargin = isCompact and 18 or 42
        local verticalMargin = isCompact and 18 or 42

        local maxViewportScale = math.min(
            math.max(0.25, (viewport.X - horizontalMargin) / 920),
            math.max(0.25, (viewport.Y - verticalMargin) / 600)
        )

        local requestedScale = math.clamp(
            (tonumber(PersistentSettings.MenuScale) or 100) / 100,
            0.8,
            1.2
        )

        local resolvedScale
        if isCompact then
            -- Mobile always fits the complete 920x600 shell inside the usable
            -- viewport. Menu Scale remains saved but cannot force overflow.
            resolvedScale = math.min(1, maxViewportScale)
        else
            resolvedScale = math.min(requestedScale, maxViewportScale)
        end

        resolvedScale = math.max(0.25, resolvedScale)
        windowScale.Scale = resolvedScale
        shadowScale.Scale = resolvedScale
    end
    updateV1Scale()
    if Workspace.CurrentCamera then
        Workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(updateV1Scale)
    end
    Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        task.defer(updateV1Scale)
    end)

