    local lastLockedPageNoticeAt = 0
    function setV1Page(name)
        if name == "Waves" and not SliceHubWaveAutomationAllowed() then
            local now = os.clock()
            if now - lastLockedPageNoticeAt >= 0.75 then
                lastLockedPageNoticeAt = now
                showNotification("Premium only", "This tab unlocks only when you have Premium.", "info")
            end
            return
        end
        local target = V1Pages[name]
        if not target then return end
        activeV1Page = name
        for pageName, page in pairs(V1Pages) do
            page.Visible = pageName == name
            if pageName == name then page.CanvasPosition = Vector2.zero end
        end
        for buttonName, button in pairs(V1NavButtons) do
            local selected = buttonName == name
            button.BackgroundTransparency = 1
            button.BackgroundColor3 = Theme.CardSoft
            button.TextColor3 = selected and Theme.Text or Theme.TextDim
            local indicator = button:FindFirstChild("Indicator")
            if indicator then indicator.BackgroundTransparency = selected and 0 or 1 end
        end
        activePageTitle.Text = name == "Welcome" and "OVERVIEW" or string.upper(({Farm="MISSIONS", Config="CONFIGS"})[name] or name)
        print("[SliceHub V3] page ->", name)
    end

    local tabNames = {"Welcome", "Farm", "Raids", "Waves", "Blades", "Spears", "Combat", "Stats", "Webhook", "Optimization", "Config", "Settings", "Discord"}
    for index, name in ipairs(tabNames) do
        createV1Page(name)
        if name == "Welcome" or name == "Blades" or name == "Stats" or name == "Config" then
            local group = Instance.new("TextLabel")
            group.Name = name .. "GroupLabel"
            group.LayoutOrder = index * 10 - 1
            group.Size = UDim2.new(1, 0, 0, 26)
            group.BackgroundTransparency = 1
            group.Font = Enum.Font.GothamBold
            group.Text = ({Welcome="FARMING", Blades="COMBAT", Stats="UTILITY", Config="CONFIGURATION"})[name]
            group.TextColor3 = Color3.fromRGB(126, 126, 134)
            group.TextSize = 11
            group.TextXAlignment = Enum.TextXAlignment.Left
            group.Parent = navHolder
        end
        local button = createNavButton(name, index)
        local function activatePage()
            setV1Page(name)
        end
        button.Activated:Connect(activatePage)
        button.MouseEnter:Connect(function()
            if activeV1Page ~= name then
                tween(button, 0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, {
                    BackgroundTransparency = 0.35,
                    BackgroundColor3 = Theme.CardSoft,
                })
            end
        end)
        button.MouseLeave:Connect(function()
            if activeV1Page ~= name then
                tween(button, 0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, {
                    BackgroundTransparency = 1,
                })
            end
        end)
    end


