ReturnToLobby = {
    Running = false,
    Locked = false,
    LastMessage = "Idle",
    LobbyPlaceId = LOBBY_PLACE_ID,
    Attempt = 0,
}

;(function() -- V9.8.4 exact remote-only lobby return
    local teleportStarted = false
    local teleportFailure = nil

    pcall(function()
        player.OnTeleport:Connect(function(state)
            if state == Enum.TeleportState.Started
                or state == Enum.TeleportState.InProgress
                or state == Enum.TeleportState.WaitingForServer then
                teleportStarted = true
            end
        end)
    end)

    pcall(function()
        TeleportService.TeleportInitFailed:Connect(function(failedPlayer, result, message)
            if failedPlayer == player then
                teleportFailure = tostring(result) .. ": " .. tostring(message or "teleport failed")
            end
        end)
    end)

    local function stopFarmBeforeReturning()
        State.AutoRetrySuppressed = true
        State.FarmEnabled = false
        State.IsGrabbed = false
        statusText = "Returning to lobby..."

        if Controls and Controls.Farm and Controls.Farm.Set then
            pcall(function()
                Controls.Farm:Set(false, true)
            end)
        end

        if rootPart and rootPart.Parent then
            pcall(function()
                rootPart.Anchored = false
                rootPart.AssemblyAngularVelocity = Vector3.zero
                rootPart.AssemblyLinearVelocity = Vector3.zero
            end)
        end
    end

    local function waitForTeleportStart(timeout)
        local startedAt = os.clock()
        repeat
            if teleportStarted or not player.Parent then
                return true
            end
            if teleportFailure then
                return false, teleportFailure
            end
            task.wait(0.08)
        until os.clock() - startedAt >= timeout
        return false, "Lobby teleport was not accepted"
    end

    local function invokeExactLobbyTeleport()
        local assets = ReplicatedStorage:FindFirstChild("Assets")
        local remotes = assets and assets:FindFirstChild("Remotes")
        local remote = remotes and remotes:FindFirstChild("GET")

        if not remote or not remote:IsA("RemoteFunction") then
            return false, "Teleport remote is unavailable"
        end

        teleportStarted = false
        teleportFailure = nil

        local ok, response = pcall(function()
            return remote:InvokeServer("Functions", "Teleport", "Lobby")
        end)

        if not ok then
            return false, tostring(response)
        end

        local started, reason = waitForTeleportStart(4.0)
        if started then
            return true, "exact lobby teleport"
        end

        return false, tostring(reason or response or "Lobby teleport was not accepted")
    end

    function ReturnToLobby.Run(reason)
        if ReturnToLobby.Running then
            return false, "already running"
        end

        ReturnToLobby.Running = true
        ReturnToLobby.Locked = true
        ReturnToLobby.Attempt += 1
        State.AutoRetrySuppressed = true
        stopFarmBeforeReturning()

        pcall(function()
            if type(makefolder) == "function" then
                if type(isfolder) ~= "function" or not isfolder("SH") then makefolder("SH") end
                if type(isfolder) ~= "function" or not isfolder("SH/state") then makefolder("SH/state") end
            end
            if type(writefile) == "function" then
                writefile("SH/state/relaunch_after_limit_v984.json", game:GetService("HttpService"):JSONEncode({
                    Version = "9.8.4",
                    RequestedAt = os.time(),
                    Reason = tostring(reason or "Mission limit reached"),
                }))
            end
        end)

        task.spawn(function()
            local success, message = invokeExactLobbyTeleport()

            if success then
                ReturnToLobby.LastMessage = message
                State.AutoMissionCount = 0
                if refreshAutoMissionStatus then pcall(refreshAutoMissionStatus) end
                if saveSettingsIfReady then pcall(saveSettingsIfReady) end
                return
            end

            ReturnToLobby.Running = false
            ReturnToLobby.Locked = false
            State.AutoRetrySuppressed = false
            pcall(function()
                if type(delfile) == "function" then delfile("SH/state/relaunch_after_limit_v984.json") end
            end)
            ReturnToLobby.LastMessage = tostring(message)
            warn("[SliceHub V9.8.4][RETURN] failed:", ReturnToLobby.LastMessage)
            showNotification("Teleport failed", ReturnToLobby.LastMessage, "error")
        end)

        return true
    end
end)()


