function setProfileMessage(message, success)
	profileMessage.Text = tostring(message or "")
	profileMessage.TextColor3 = success == false and Color3.fromRGB(255, 188, 198) or Color3.fromRGB(210, 238, 225)
end

function getProfileNameFromUi()
	local requestedName = sanitizeProfileName(profileNameBox.Text)
	if requestedName == "" and selectedProfileIndex >= 1 and profileNames[selectedProfileIndex] then
		requestedName = profileNames[selectedProfileIndex]
	end
	return requestedName
end

function refreshAutoLoadProfileButton()
    if not autoLoadProfileButton then return end
    local runtimeType = V98342RuntimeConfig_currentRuntimeConfigType()
    local autoName = tostring(V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] or "")
    if autoName ~= "" and resolveProfileKey(autoName, runtimeType) then
        autoLoadProfileButton.Text = "AUTO LOAD " .. string.upper(runtimeType) .. ": " .. autoName
        autoLoadProfileButton.BackgroundColor3 = Theme.Button
    else
        V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] = ""
        autoLoadProfileButton.Text = "AUTO LOAD " .. string.upper(runtimeType) .. ": OFF"
        autoLoadProfileButton.BackgroundColor3 = Theme.CardActive
    end
end

function refreshProfileSelector(preferredName)
	profileNames = getSortedProfileNames()

	if #profileNames == 0 then
		selectedProfileIndex = 0
		selectedProfileLabel.Text = "No saved " .. string.lower(V98342RuntimeConfig_currentRuntimeConfigType()) .. " configs"
		selectedProfileLabel.TextColor3 = Theme.TextMuted
		refreshAutoLoadProfileButton()
		return
	end

	local preferredKey = resolveProfileKey(preferredName, V98342RuntimeConfig_currentRuntimeConfigType())
	if preferredKey then
		for index, name in ipairs(profileNames) do
			if name == preferredKey then
				selectedProfileIndex = index
				break
			end
		end
	end

	if selectedProfileIndex < 1 or selectedProfileIndex > #profileNames then
		selectedProfileIndex = 1
	end

	selectedProfileLabel.Text = profileNames[selectedProfileIndex]
	selectedProfileLabel.TextColor3 = Theme.Text
	refreshAutoLoadProfileButton()
end

function moveProfileSelection(direction)
	if #profileNames == 0 then return end
	selectedProfileIndex = ((selectedProfileIndex - 1 + direction) % #profileNames) + 1
	local selectedName = profileNames[selectedProfileIndex]
	selectedProfileLabel.Text = selectedName
	profileNameBox.Text = selectedName
	refreshAutoLoadProfileButton()
end

previousProfile.Activated:Connect(function()
	moveProfileSelection(-1)
end)

nextProfile.Activated:Connect(function()
	moveProfileSelection(1)
end)

selectedProfileLabel.Activated:Connect(function()
	if selectedProfileIndex >= 1 and profileNames[selectedProfileIndex] then
		profileNameBox.Text = profileNames[selectedProfileIndex]
	end
end)

function applyProfile(profile, autoLoadMode)
	if not profile then return false end

	Controls.TitansPerHit:Set(SliceHubMissionClampTPS(profile.TitansPerHit, Config.TitansPerHit), true)
	Controls.TitanRipper:Set(profile.TitanRipperEnabled, true)
    if Controls.SpearSupport then Controls.SpearSupport:Set(profile.SpearSupportEnabled == true, true) end
    if Controls.SpearAutoFire then Controls.SpearAutoFire:Set(profile.SpearAutoFireEnabled ~= false, true) end
    if Controls.SpearAutoRefill then Controls.SpearAutoRefill:Set(profile.SpearAutoRefillEnabled == true, true) end
    if Controls.SpearInfinite then Controls.SpearInfinite:Set(profile.SpearInfiniteEnabled == true, true) end
    if Controls.AutoUseBuffs then Controls.AutoUseBuffs:Set(profile.AutoUseBuffsEnabled == true, true) end
    if Controls.BuffOrderAdvance then Controls.BuffOrderAdvance:Set(profile.BuffOrderAdvanceEnabled ~= false, true) end
    if Controls.BuffBlackFlare then Controls.BuffBlackFlare:Set(profile.BuffBlackFlareEnabled ~= false, true) end
    if Controls.BuffOrderRage then Controls.BuffOrderRage:Set(profile.BuffOrderRageEnabled ~= false, true) end
    if Controls.BuffFoundersOrder then Controls.BuffFoundersOrder:Set(profile.BuffFoundersOrderEnabled ~= false, true) end
    if Controls.BuffOrderRevolution then Controls.BuffOrderRevolution:Set(profile.BuffOrderRevolutionEnabled ~= false, true) end
    if Controls.RaidOpenFreeChest then
        Controls.RaidOpenFreeChest:Set(
            profile.RaidOpenFreeChestEnabled ~= false,
            true
        )
    end
    if Controls.RaidOpenEmperorChest then
        Controls.RaidOpenEmperorChest:Set(
            profile.RaidOpenEmperorChestEnabled == true,
            true
        )
    end
	State.TargetPriority = ({Balanced=true, Nearest=true, Objective=true, Boss=true, Abnormal=true})[tostring(profile.TargetPriority or "Balanced")] and tostring(profile.TargetPriority or "Balanced") or "Balanced"
	if refreshTargetPriorityUI then refreshTargetPriorityUI() end
	cachedTitanCandidatesAt = 0
	Controls.AutoRefill:Set(profile.AutoRefillEnabled, true)
	if Controls.AutoSkipCutscene then
		Controls.AutoSkipCutscene:Set(SliceHubClampAutoSkipCutscene(profile.AutoSkipCutsceneEnabled), true)
	end
	if Controls.LowGraphics then
		Controls.LowGraphics:Set(profile.PerformanceModeEnabled, true)
	end
	if Controls.NoEffects then
		Controls.NoEffects:Set(profile.DisableEffectsEnabled, true)
	end
	if Controls.EcoLoops then
		Controls.EcoLoops:Set(profile.EcoLoopModeEnabled, true)
	end
	if Controls.MapProps then
		Controls.MapProps:Set(profile.MapPropsHiddenEnabled, true)
	end
	if Controls.RemoveInjuryKillFlash then
		Controls.RemoveInjuryKillFlash:Set(profile.RemoveInjuryKillFlashEnabled == true, true)
	end
	if Controls.RemoveDamageText then
		Controls.RemoveDamageText:Set(profile.RemoveDamageTextEnabled == true, true)
	end
    State.OptimizationPreset = tostring(profile.OptimizationPreset or "Default")
    if Controls.CleanupDeadTitans then Controls.CleanupDeadTitans:Set(profile.CleanupDeadTitansEnabled == true, true) end
    if Controls.RemoveFog then Controls.RemoveFog:Set(profile.RemoveFogEnabled == true, true) end
    if Controls.DisablePostProcessing then Controls.DisablePostProcessing:Set(profile.DisablePostProcessingEnabled == true, true) end
    if Controls.Disable3DRendering then Controls.Disable3DRendering:Set(profile.Disable3DRenderingEnabled == true, true) end
    if Controls.SimpleLighting then Controls.SimpleLighting:Set(profile.SimpleLightingEnabled == true, true) end
    if Controls.LowDetailMaterials then Controls.LowDetailMaterials:Set(profile.LowDetailMapMaterialsEnabled == true, true) end
    if Controls.SleepHiddenUI then Controls.SleepHiddenUI:Set(profile.SleepUIWhenHiddenEnabled == true, true) end
    if Controls.DisableCameraEffects then Controls.DisableCameraEffects:Set(profile.DisableCameraEffectsEnabled == true, true) end
    if Controls.WavesGearTarget then Controls.WavesGearTarget:Set(profile.WavesGearTarget or "Both", true) end
    if Controls.WavesAutoFarm then Controls.WavesAutoFarm:Set(profile.WavesAutoFarmEnabled == true, true) end
    if Controls.WavesAutoSkip then Controls.WavesAutoSkip:Set(profile.WavesAutoSkipEnabled == true, true) end
    if Controls.WavesAutoPickup then Controls.WavesAutoPickup:Set(profile.WavesAutoPickupEnabled == true, true) end
    if Controls.WavesAutoDeliver then Controls.WavesAutoDeliver:Set(profile.WavesAutoDeliverEnabled == true, true) end
    if Controls.WavesAutoUpgradeGear then Controls.WavesAutoUpgradeGear:Set(profile.WavesAutoUpgradeGearEnabled == true, true) end
    if Controls.WavesAutoUpgradeHQ then Controls.WavesAutoUpgradeHQ:Set(profile.WavesAutoUpgradeHQEnabled == true, true) end
    if Controls.WavesHQMax then Controls.WavesHQMax:Set(profile.WavesHQMaxEnabled ~= false, true) end
    if Controls.WavesHQRegen then Controls.WavesHQRegen:Set(profile.WavesHQRegenEnabled ~= false, true) end
    if Controls.WavesHQRefills then Controls.WavesHQRefills:Set(profile.WavesHQRefillsEnabled ~= false, true) end
    if Controls.WavesHQReplenish then Controls.WavesHQReplenish:Set(profile.WavesHQReplenishEnabled ~= false, true) end
    State.FPSCap = math.clamp(math.floor((tonumber(profile.FPSCap) or 60) + 0.5), 30, 999)
    Performance:SetFPSCap(State.FPSCap)
    Controls.RefreshOptimizationUi()
	if Controls.AutoMissionLimit then
		Controls.AutoMissionLimit:Set(profile.AutoMissionLimit or 0, true)
	end
	if Controls.AutoRetry then
		Controls.AutoRetry:Set(profile.AutoRetryEnabled == true, true)
	end
        -- A typed config is an explicit automation request. Apply Farm last so
        -- every support option is ready, including during type-specific autoload.
        Controls.Farm:Set(profile.BladesEnabled == true or profile.FarmEnabled == true, true)
	return true
end

autoLoadProfileButton.Activated:Connect(function()
    local runtimeType = V98342RuntimeConfig_currentRuntimeConfigType()
    local requestedName = getProfileNameFromUi()
    local profile, resolvedName = getNamedProfile(requestedName)
    if resolvedName and V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] == resolvedName then
        V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] = ""
        local ok, message = persistProfileStore()
        refreshAutoLoadProfileButton()
        setProfileMessage(ok and (runtimeType .. " auto-load disabled") or tostring(message), ok)
        showNotification(ok and "Auto-load off" or "Save failed", ok and ("No " .. runtimeType .. " config will auto-load.") or tostring(message), ok and "info" or "error")
        return
    end
    if not profile then
        setProfileMessage("Select or save a " .. runtimeType .. " config first", false)
        showNotification("Auto-load failed", "Select or save a matching config first.", "error")
        return
    end
    V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] = resolvedName
    local ok, message = persistProfileStore()
    profileNameBox.Text = resolvedName
    refreshProfileSelector(resolvedName)
    refreshAutoLoadProfileButton()
    setProfileMessage(ok and ("Auto-load set: " .. resolvedName) or tostring(message), ok)
    showNotification(ok and "Auto-load set" or "Save failed", ok and (resolvedName .. " loads in " .. runtimeType .. ".") or tostring(message), ok and "success" or "error")
end)

saveProfileButton.Activated:Connect(function()
	local success, message, savedName = saveNamedProfile(profileNameBox.Text)
	if savedName then
		profileNameBox.Text = savedName
		refreshProfileSelector(savedName)
	end
	setProfileMessage(message, success)
	if success then
		showNotification("Config saved", savedName or "Profile", "success")
	else
		showNotification("Save failed", message, "error")
	end
end)

loadProfileButton.Activated:Connect(function()
	local requestedName = sanitizeProfileName(profileNameBox.Text)
	if requestedName == "" and selectedProfileIndex >= 1 then
		requestedName = profileNames[selectedProfileIndex]
	end

	local profile, resolvedName = getNamedProfile(requestedName)
	if not profile then
		setProfileMessage("Config not found", false)
		showNotification("Load failed", "Config not found", "error")
		return
	end

	applyProfile(profile)
	profileNameBox.Text = resolvedName
	refreshProfileSelector(resolvedName)
	setProfileMessage("Loaded " .. resolvedName, true)
	showNotification("Config loaded", resolvedName, "success")
end)

deleteProfileButton.Activated:Connect(function()
	local requestedName = sanitizeProfileName(profileNameBox.Text)
	if requestedName == "" and selectedProfileIndex >= 1 then
		requestedName = profileNames[selectedProfileIndex]
	end

	local success, message = deleteNamedProfile(requestedName)
	if success then
                local runtimeType = V98342RuntimeConfig_currentRuntimeConfigType()
                if V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] == requestedName then
                    V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] = ""
                    persistProfileStore()
                end
		profileNameBox.Text = ""
		refreshProfileSelector()
	end
	setProfileMessage(message, success)
	if success then
		showNotification("Config deleted", requestedName, "success")
	else
		showNotification("Delete failed", message, "error")
	end
end)

copyConfigButton.Activated:Connect(function()
    local requestedName = getProfileNameFromUi()
    local profile, resolvedName = getNamedProfile(requestedName)
    profile = profile or captureCurrentProfile()
    resolvedName = resolvedName or (sanitizeProfileName(profileNameBox.Text) ~= "" and sanitizeProfileName(profileNameBox.Text) or (V98342RuntimeConfig_currentRuntimeConfigType() .. " Config"))
    local ok, message = V98342RuntimeConfig_copyRuntimeConfig(resolvedName, profile)
    setProfileMessage(message, ok)
    showNotification(ok and "Config copied" or "Copy failed", message, ok and "success" or "error")
end)

pasteConfigButton.Activated:Connect(function()
    local ok, message, importedName = V98342RuntimeConfig_pasteRuntimeConfig(true)
    if importedName then
        profileNameBox.Text = importedName
        refreshProfileSelector(importedName)
    end
    setProfileMessage(message, ok)
    showNotification(ok and "Config imported" or "Import failed", message, ok and "success" or "error")
end)

exportConfigButton.Activated:Connect(function()
    local requestedName = getProfileNameFromUi()
    local profile, resolvedName = getNamedProfile(requestedName)
    profile = profile or captureCurrentProfile()
    resolvedName = resolvedName or (sanitizeProfileName(profileNameBox.Text) ~= "" and sanitizeProfileName(profileNameBox.Text) or (V98342RuntimeConfig_currentRuntimeConfigType() .. " Config"))
    local ok, message = V98342RuntimeConfig_exportRuntimeConfigFile(resolvedName, profile)
    setProfileMessage(message, ok)
    showNotification(ok and "Config exported" or "Export failed", message, ok and "success" or "error")
end)

importConfigButton.Activated:Connect(function()
    local requestedName = sanitizeProfileName(profileNameBox.Text)
    if requestedName == "" then
        setProfileMessage("Enter the .shcfg file name first", false)
        showNotification("Import failed", "Enter the exported config file name in the box.", "error")
        return
    end
    local ok, message, importedName = V98342RuntimeConfig_importRuntimeConfigFile(requestedName, true)
    if importedName then
        profileNameBox.Text = importedName
        refreshProfileSelector(importedName)
    end
    setProfileMessage(message, ok)
    showNotification(ok and "Config imported" or "Import failed", message, ok and "success" or "error")
end)

shareConfigButton.Activated:Connect(function()
    local requestedName = getProfileNameFromUi()
    local profile, resolvedName = getNamedProfile(requestedName)
    profile = profile or captureCurrentProfile()
    resolvedName = resolvedName or (sanitizeProfileName(profileNameBox.Text) ~= "" and sanitizeProfileName(profileNameBox.Text) or (V98342RuntimeConfig_currentRuntimeConfigType() .. " Config"))
    shareConfigButton.Text = "PUBLISHING..."
    task.spawn(function()
        local ok, message = V98342RuntimeConfig_publishRuntimeConfig(resolvedName, profile)
        shareConfigButton.Text = "SHARE TO DISCORD"
        setProfileMessage(message, ok)
        showNotification(ok and "Config published" or "Publish failed", message, ok and "success" or "error")
    end)
end)

profileNameBox.FocusLost:Connect(function()
        profileNameBox.Text = sanitizeProfileName(profileNameBox.Text)
end)

refreshProfileSelector()
refreshAutoLoadProfileButton()
task.defer(function()
    local runtimeType = V98342RuntimeConfig_currentRuntimeConfigType()
    local autoName = tostring(V98342RuntimeConfig_ProfileAutoLoadNames[runtimeType] or "")
    if autoName == "" then return end
    local profile, resolvedName = getNamedProfile(autoName)
    if not profile then
        setProfileMessage("Auto-load config missing: " .. autoName, false)
        showNotification("Auto-load missing", autoName .. " was not found for " .. runtimeType .. ".", "error")
        return
    end
    applyProfile(profile, true)
    profileNameBox.Text = resolvedName
    refreshProfileSelector(resolvedName)
    setProfileMessage("Auto-loaded " .. runtimeType .. " config " .. resolvedName, true)
    showNotification("Config auto-loaded", resolvedName, "success")
end)
end)()

