		PersistentSettings.AutoSave = value == true
		if settingsUiReady and settingsSaveReady then
			local ok, message = saveAllSettings(true)
			showNotification(ok and "Settings saved" or "Save failed", tostring(message), ok and "success" or "error")
		end
	end)


	Controls.AutoExecuteTeleport = createToggle(settingsPage, 2, "Auto Execute On Teleport", "Queues the encrypted SH cache before mission/raid retry or any server teleport, then reloads saved settings.", PersistentSettings.AutoExecuteOnTeleport == true, function(value)
        PersistentSettings.AutoExecuteOnTeleport = value == true
        if settingsUiReady and settingsSaveReady then
            local ok, message = saveAllSettings(true)
            showNotification(ok and "Auto execute saved" or "Save failed", ok and (value and "V5 will queue itself on the next teleport." or "Auto execute disabled.") or tostring(message), ok and "success" or "error")
        end
    end)

	Controls.AutoHideGuiLaunch = createToggle(settingsPage, 3, "Auto Hide UI On Launch", "Optional. Starts the mission hub closed; leave this off when you want to confirm SliceHub loaded.", PersistentSettings.AutoHideGuiOnLaunch == true, function(value)
		PersistentSettings.AutoHideGuiOnLaunch = value == true
		if settingsUiReady and settingsSaveReady then
			local ok, message = saveAllSettings(true)
			showNotification(ok and "Auto hide saved" or "Save failed", ok and (value and "Mission GUI will start closed." or "Mission GUI will start open.") or tostring(message), ok and "success" or "error")
		end
	end)

	Controls.MenuScale = createIntegerSlider(settingsPage, 4, "Menu Scale", "Changes the menu size without touching game resolution. Mobile is always bounded to the viewport.", 80, 120, PersistentSettings.MenuScale or 100, function(value)
		PersistentSettings.MenuScale = math.clamp(math.floor((tonumber(value) or 100) + 0.5), 80, 120)
		-- Never assign UIScale directly here. This callback runs while the
		-- Settings UI is being built and previously erased the mobile fit.
		if type(updateV1Scale) == "function" then
			updateV1Scale()
		else
			local fallbackScale = PersistentSettings.MenuScale / 100
			windowScale.Scale = fallbackScale
			shadowScale.Scale = fallbackScale
		end
		if settingsUiReady and settingsSaveReady then
			saveAllSettings(false)
