	local themeNames = {"Blue", "Purple", "Dark", "Green"}
	local themeButtons = {}

	local function renderThemeButtons()
		for name, button in pairs(themeButtons) do
			local selected = tostring(PersistentSettings.ThemeName or "Blue") == name
			button.BackgroundColor3 = selected and Theme.Accent or Theme.Button
			button.TextColor3 = selected and Theme.Text or Theme.TextMuted
		end
	end

	for index, name in ipairs(themeNames) do
		local button = Instance.new("TextButton")
		button.Name = name .. "ThemeButton"
		button.Position = UDim2.new((index - 1) / 4, 16 - ((index - 1) * 2), 0, 52)
