---------------------------------------------------------------------
-- V9.8.4 SERVER REWARD SNAPSHOT • PASSIVE FALLBACK
---------------------------------------------------------------------

RewardScannerV1 = RewardScannerV1 or {}
do
    local Scanner = RewardScannerV1
    Scanner.SchemaVersion = 4
    Scanner.BuildVersion = tostring(BUILD and BUILD.Version or "9.8.3.4.5")
    Scanner.Started = Scanner.Started == true
    Scanner.Active = false
    Scanner.Run = nil
    Scanner.LastDumpPath = Scanner.LastDumpPath
    Scanner.Connections = Scanner.Connections or setmetatable({}, {__mode = "k"})

    local environment = (type(getgenv) == "function" and getgenv()) or _G
    environment.SliceHubRewardAssetNames = type(environment.SliceHubRewardAssetNames) == "table"
        and environment.SliceHubRewardAssetNames or {}
    local LearnedRewardAssetNames = environment.SliceHubRewardAssetNames
    local writeFileFn = type(environment.writefile) == "function" and environment.writefile
        or (type(writefile) == "function" and writefile or nil)
    local makeFolderFn = type(environment.makefolder) == "function" and environment.makefolder
        or (type(makefolder) == "function" and makefolder or nil)
    local isFolderFn = type(environment.isfolder) == "function" and environment.isfolder
        or (type(isfolder) == "function" and isfolder or nil)

    local RewardWords = {
        "reward", "rewards", "drop", "drops", "loot", "chest", "item", "items",
        "inventory", "obtained", "grant", "serum", "perk", "material", "result",
        "complete", "completed", "finish", "mission", "raid",
    }

    local StrongContextWords = {
        "reward", "drop", "loot", "chest", "inventory", "item", "owned",
        "material", "perk", "serum", "storage", "grant",
    }

    local GenericNames = {
        ["reward"] = true, ["rewards"] = true, ["drop"] = true, ["drops"] = true,
        ["item"] = true, ["items"] = true, ["inventory"] = true, ["data"] = true,
        ["count"] = true, ["amount"] = true, ["quantity"] = true, ["value"] = true,
        ["result"] = true, ["results"] = true, ["mission"] = true, ["raid"] = true,
        ["completed"] = true, ["complete"] = true, ["success"] = true,
        ["free"] = true, ["premium"] = true, ["normal"] = true, ["hard"] = true,
        ["severe"] = true, ["aberrant"] = true, ["easy"] = true,
        ["exp"] = true, ["xp"] = true, ["experience"] = true,
        ["gold"] = true, ["gems"] = true, ["gem"] = true, ["money"] = true,
        ["main"] = true, ["inner"] = true, ["fade"] = true,
        ["gradient"] = true, ["stroke"] = true, ["icon"] = true,
        ["equipped"] = true, ["checkmark"] = true, ["frame"] = true,
        ["button"] = true, ["buttons"] = true, ["title"] = true,
        ["rarity"] = true, ["grid"] = true, ["list"] = true,
    }

    local function lower(value)
        return string.lower(tostring(value or ""))
    end

    local function safePath(object)
        if typeof(object) ~= "Instance" then return tostring(object) end
        local ok, result = pcall(function() return object:GetFullName() end)
        return ok and tostring(result) or tostring(object.Name or object.ClassName)
    end

    local function hasWord(value, words)
        local textValue = lower(value)
        for _, word in ipairs(words) do
            if string.find(textValue, word, 1, true) then return true end
        end
        return false
    end

    local function keywordScore(value)
        local score = 0
        local textValue = lower(value)
        for _, word in ipairs(RewardWords) do
            if string.find(textValue, word, 1, true) then score += 1 end
        end
        return score
    end

    local function cleanName(value)
        local name = tostring(value or "")
        name = string.gsub(name, "<.->", "")
        name = string.gsub(name, "^%s+", "")
        name = string.gsub(name, "%s+$", "")
        if name == "" or #name > 96 then return nil end
        local normalized = lower(name)
        if GenericNames[normalized] then return nil end
        if string.match(normalized, "^%d+$") then return nil end
        if string.find(normalized, "http", 1, true)
            or string.find(normalized, "rbxasset", 1, true)
            or string.find(normalized, "workspace", 1, true)
            or string.find(normalized, "replicatedstorage", 1, true) then
            return nil
        end
        if string.gsub(normalized, "[%d_%-%s]", "") == "" then return nil end
        return name
    end

    local function primitive(value)
        local kind = typeof(value)
        if kind == "nil" then return nil end
        if kind == "string" or kind == "boolean" then return value end
        if kind == "number" then
            if value ~= value or value == math.huge or value == -math.huge then
                return tostring(value)
            end
            return value
        end
        return nil
    end

    local function serialize(value, depth, seen, limit)
        depth = tonumber(depth) or 0
        seen = seen or {}
        limit = limit or {count = 0, max = 900}
        if limit.count >= limit.max then return "<limit>" end
        limit.count += 1

        local direct = primitive(value)
        if direct ~= nil then return direct end

        local kind = typeof(value)
        if kind == "Instance" then
            local entry = {
                __type = "Instance",
                class = value.ClassName,
                name = value.Name,
                path = safePath(value),
            }
            if value:IsA("ValueBase") then
                local ok, current = pcall(function() return value.Value end)
                if ok then entry.value = serialize(current, depth + 1, seen, limit) end
            elseif value:IsA("ObjectValue") and value.Value then
                entry.valuePath = safePath(value.Value)
            end
            local okAttr, attrs = pcall(function() return value:GetAttributes() end)
            if okAttr and type(attrs) == "table" and next(attrs) ~= nil then
                entry.attributes = serialize(attrs, depth + 1, seen, limit)
            end
            return entry
        end

        if kind == "table" then
            if seen[value] then return "<cycle>" end
            if depth >= 5 then return "<depth>" end
            seen[value] = true

            local length = #value
            local output
            if length > 0 then
                output = {}
                for index = 1, math.min(length, 80) do
                    output[index] = serialize(value[index], depth + 1, seen, limit)
                end
                if length > 80 then output[#output + 1] = "<truncated>" end
            else
                output = {}
                local count = 0
                for key, item in pairs(value) do
                    count += 1
                    if count > 100 then
                        output.__truncated = true
                        break
                    end
                    output[tostring(key)] = serialize(item, depth + 1, seen, limit)
                end
            end
            seen[value] = nil
            return output
        end

        return {
            __type = kind,
            value = tostring(value),
        }
    end

    local function compactText(value, depth, seen)
        depth = depth or 0
        seen = seen or {}
        if depth > 2 then return "..." end
        local direct = primitive(value)
        if direct ~= nil then return tostring(direct) end
        local kind = typeof(value)
        if kind == "Instance" then return safePath(value) end
        if kind ~= "table" then return tostring(value) end
        if seen[value] then return "<cycle>" end
        seen[value] = true
        local parts = {}
        local count = 0
        for key, item in pairs(value) do
            count += 1
            if count > 14 then break end
            parts[#parts + 1] = tostring(key) .. "=" .. compactText(item, depth + 1, seen)
        end
        seen[value] = nil
        return table.concat(parts, ";")
    end

    local function pushRing(list, value, maxCount)
        list[#list + 1] = value
        while #list > maxCount do table.remove(list, 1) end
    end

    local function addCandidate(run, name, quantity, source, confidence, id, rarity, evidence)
        name = cleanName(name or id)
        if not name then return end
        local amount = tonumber(quantity) or 1
        amount = math.max(1, math.floor(amount + 0.5))
        run.Candidates[#run.Candidates + 1] = {
            name = name,
            id = id and tostring(id) or nil,
            rarity = rarity and tostring(rarity) or nil,
            quantity = amount,
            source = tostring(source or "Unknown"),
            confidence = tonumber(confidence) or 0.5,
            evidence = evidence and tostring(evidence) or nil,
        }
    end

    local NameKeys = {
        name = true, itemname = true, rewardname = true, dropname = true,
        displayname = true, perkname = true, traitname = true, materialname = true,
        itemid = true, rewardid = true, dropid = true, perkid = true,
    }
    local QuantityKeys = {
        quantity = true, amount = true, count = true, qty = true,
        stack = true, stacks = true, total = true,
    }
    local RarityKeys = {rarity = true, tier = true, grade = true}

    local function extractCandidates(value, run, source, path, depth, seen)
        depth = depth or 0
        seen = seen or {}
        if depth > 5 then return end

        if typeof(value) == "Instance" then
            local attrs = {}
            pcall(function() attrs = value:GetAttributes() end)
            if next(attrs) ~= nil then
                extractCandidates(attrs, run, source, path .. ".attributes", depth + 1, seen)
            end
            if value:IsA("ValueBase") then
                local ok, current = pcall(function() return value.Value end)
                if ok then extractCandidates({name = value.Name, quantity = current}, run, source, path, depth + 1, seen) end
            end
            return
        end

        if type(value) ~= "table" then return end
        if seen[value] then return end
        seen[value] = true

        local foundName, foundId, foundQuantity, foundRarity = nil, nil, nil, nil
        local explicitName = false
        for key, item in pairs(value) do
            local keyName = string.gsub(lower(key), "[^%w]", "")
            if NameKeys[keyName] and (type(item) == "string" or type(item) == "number") then
                if string.find(keyName, "id", 1, true) then
                    foundId = tostring(item)
                    if not foundName then foundName = tostring(item) end
                else
                    foundName = tostring(item)
                end
                explicitName = true
            elseif QuantityKeys[keyName] and tonumber(item) then
                foundQuantity = tonumber(item)
            elseif RarityKeys[keyName] and (type(item) == "string" or type(item) == "number") then
                foundRarity = tostring(item)
            end
        end

        local contextStrong = hasWord(path, StrongContextWords)
        if explicitName and (foundQuantity ~= nil or contextStrong) then
            addCandidate(
                run,
                foundName,
                foundQuantity or 1,
                source,
                foundQuantity ~= nil and 0.96 or 0.90,
                foundId,
                foundRarity,
                path
            )
        end

        local count = 0
        for key, item in pairs(value) do
            count += 1
            if count > 140 then break end
            extractCandidates(item, run, source, path .. "." .. tostring(key), depth + 1, seen)
        end
        seen[value] = nil
    end

    local function getRemoteEventPath(remote)
        return safePath(remote)
    end

    function Scanner.HookRemote(remote)
        if not remote or not remote:IsA("RemoteEvent") or Scanner.Connections[remote] then return end
        local ok, connection = pcall(function()
            return remote.OnClientEvent:Connect(function(...)
                if not Scanner.Active or type(Scanner.Run) ~= "table" then return end
                local run = Scanner.Run
                local args = table.pack(...)
                local remotePath = getRemoteEventPath(remote)
                run.RemoteCounts[remotePath] = (run.RemoteCounts[remotePath] or 0) + 1

                local previewParts = {}
                for index = 1, math.min(args.n or #args, 10) do
                    previewParts[#previewParts + 1] = compactText(args[index])
                end
                local preview = table.concat(previewParts, " | ")
                local sample = {
                    at = os.clock() - run.StartClock,
                    remote = remotePath,
                    preview = string.sub(preview, 1, 900),
                    args = {},
                }
                for index = 1, math.min(args.n or #args, 12) do
                    sample.args[index] = serialize(args[index], 0, {}, {count = 0, max = 260})
                end
                pushRing(run.RecentRemoteEvents, sample, 60)

                local score = keywordScore(remotePath .. " " .. preview)
                if score > 0 then
                    sample.score = score
                    run.RelevantRemoteEvents[#run.RelevantRemoteEvents + 1] = sample
                    while #run.RelevantRemoteEvents > 100 do table.remove(run.RelevantRemoteEvents, 1) end
                    for index = 1, math.min(args.n or #args, 12) do
                        extractCandidates(args[index], run, "RemotePayload", remotePath .. ".arg" .. tostring(index), 0, {})
                    end
                end
            end)
        end)
        if ok and connection then Scanner.Connections[remote] = connection end
    end

    function Scanner.Start()
        if Scanner.Started then return end
        Scanner.Started = true
        for _, object in ipairs(ReplicatedStorage:GetDescendants()) do
            if object:IsA("RemoteEvent") then Scanner.HookRemote(object) end
        end
        Scanner.DescendantConnection = ReplicatedStorage.DescendantAdded:Connect(function(object)
            if object:IsA("RemoteEvent") then Scanner.HookRemote(object) end
        end)
        print("[SliceHub V9.8.4][REWARD SCANNER] passive fallback observer ready")
    end

    local function attributesOf(object)
        local result = {}
        local ok, attributes = pcall(function() return object:GetAttributes() end)
        if ok and type(attributes) == "table" then
            for key, value in pairs(attributes) do
                result[tostring(key)] = serialize(value, 0, {}, {count = 0, max = 80})
            end
        end
        return result
    end

    local function addRoot(roots, seen, object, label)
        if not object or seen[object] then return end
        seen[object] = true
        roots[#roots + 1] = {object = object, label = label or safePath(object)}
    end

    local function candidateRoots()
        local roots, seen = {}, {}
        addRoot(roots, seen, player, "Player")
        local backpack = player:FindFirstChildOfClass("Backpack")
        if backpack then addRoot(roots, seen, backpack, "Backpack") end

        for _, name in ipairs({"Data", "Stats", "Inventory", "Inventories", "Items", "OwnedItems", "Profile", "PlayerData"}) do
            addRoot(roots, seen, player:FindFirstChild(name), "Player." .. name)
        end

        for _, rootName in ipairs({"PlayerData", "Players", "Profiles", "Data", "Stats", "PlayerStats", "Inventories", "Inventory"}) do
            local root = ReplicatedStorage:FindFirstChild(rootName)
            if root then
                local userRoot = root:FindFirstChild(tostring(player.UserId))
                    or root:FindFirstChild(player.Name)
                if userRoot then
                    addRoot(roots, seen, userRoot, "ReplicatedStorage." .. rootName .. ".User")
                end
            end
        end
        return roots
    end

    local function snapshotInventory()
        local snapshot = {
            capturedAt = os.time(),
            entries = {},
            truncated = false,
        }
        local maxEntries = 1400
        local count = 0
        local character = player.Character
        local playerScripts = player:FindFirstChild("PlayerScripts")

        local function capture(object, rootLabel)
            if count >= maxEntries then snapshot.truncated = true return false end
            if character and (object == character or object:IsDescendantOf(character)) then return true end
            if playerGui and (object == playerGui or object:IsDescendantOf(playerGui)) then return true end
            if playerScripts and (object == playerScripts or object:IsDescendantOf(playerScripts)) then return true end
            if screenGui and object:IsDescendantOf(screenGui) then return true end
            if object:IsA("GuiObject") or object:IsA("LayerCollector") or object:IsA("UIComponent") then return true end

            local attrs = attributesOf(object)
            local isValue = object:IsA("ValueBase") or object:IsA("ObjectValue")
            local context = hasWord(safePath(object), StrongContextWords)
            if not isValue and next(attrs) == nil and not context then return true end

            count += 1
            local path = safePath(object)
            local entry = {
                root = rootLabel,
                path = path,
                class = object.ClassName,
                name = object.Name,
                attributes = next(attrs) and attrs or nil,
                childCount = #object:GetChildren(),
            }
            if object:IsA("ObjectValue") then
                entry.value = object.Value and safePath(object.Value) or nil
            elseif object:IsA("ValueBase") then
                local ok, current = pcall(function() return object.Value end)
                if ok then entry.value = serialize(current, 0, {}, {count = 0, max = 60}) end
            end
            snapshot.entries[path] = entry
            return true
        end

        for _, rootInfo in ipairs(candidateRoots()) do
            if count >= maxEntries then break end
            capture(rootInfo.object, rootInfo.label)
            -- The Player root is captured only for its own attributes. Traversing
            -- it pulled PlayerGui result tiles into InventoryDelta and created
            -- fake drops such as Main / Fade / Equipped.
            if rootInfo.object ~= player then
                for _, object in ipairs(rootInfo.object:GetDescendants()) do
                    if not capture(object, rootInfo.label) then break end
                end
            end
        end
        snapshot.count = count
        return snapshot
    end

    local function stableValue(value)
        if type(value) == "table" then
            local ok, encoded = pcall(function() return HttpService:JSONEncode(value) end)
            return ok and encoded or tostring(value)
        end
        return tostring(value)
    end

    local function snapshotSignature(snapshot)
        if type(snapshot) ~= "table" or type(snapshot.entries) ~= "table" then return "none" end
        local keys = {}
        for path in pairs(snapshot.entries) do keys[#keys + 1] = path end
        table.sort(keys)
        local parts = {tostring(#keys)}
        for index = 1, math.min(#keys, 1000) do
            local path = keys[index]
            local entry = snapshot.entries[path]
            parts[#parts + 1] = path .. "=" .. stableValue(entry.value) .. ":" .. stableValue(entry.attributes)
        end
        return table.concat(parts, "|")
    end

    local function diffSnapshots(before, after)
        local changes = {}
        local beforeEntries = type(before) == "table" and before.entries or {}
        local afterEntries = type(after) == "table" and after.entries or {}

        for path, afterEntry in pairs(afterEntries) do
            local beforeEntry = beforeEntries[path]
            if not beforeEntry then
                changes[#changes + 1] = {kind = "added", path = path, after = afterEntry}
            else
                local beforeValue = stableValue(beforeEntry.value)
                local afterValue = stableValue(afterEntry.value)
                local beforeAttrs = stableValue(beforeEntry.attributes)
                local afterAttrs = stableValue(afterEntry.attributes)
                if beforeValue ~= afterValue or beforeAttrs ~= afterAttrs or beforeEntry.childCount ~= afterEntry.childCount then
                    local numericDelta = nil
                    if tonumber(beforeEntry.value) and tonumber(afterEntry.value) then
                        numericDelta = tonumber(afterEntry.value) - tonumber(beforeEntry.value)
                    end
                    changes[#changes + 1] = {
                        kind = "changed",
                        path = path,
                        before = beforeEntry,
                        after = afterEntry,
                        delta = numericDelta,
                    }
                end
            end
        end

        for path, beforeEntry in pairs(beforeEntries) do
            if not afterEntries[path] then
                changes[#changes + 1] = {kind = "removed", path = path, before = beforeEntry}
            end
        end
        table.sort(changes, function(a, b) return tostring(a.path) < tostring(b.path) end)
        return changes
    end

    local function nameFromPath(path, fallback)
        local name = cleanName(fallback)
        if name and not GenericNames[lower(name)] then return name end
        local segments = {}
        for segment in string.gmatch(tostring(path or ""), "[^%.]+") do segments[#segments + 1] = segment end
        for index = #segments, 1, -1 do
            local candidate = cleanName(segments[index])
            if candidate and not GenericNames[lower(candidate)] then return candidate end
        end
        return nil
    end

    local function inventoryCandidates(run, changes)
        for _, change in ipairs(changes or {}) do
            local entry = change.after or change.before
            local path = tostring(change.path or "")
            local pathLower = lower(path)

            if entry
                and not string.find(pathLower, ".playergui.", 1, true)
                and not string.find(pathLower, ".playerscripts.", 1, true)
                and hasWord(path, StrongContextWords) then

                local className = tostring(entry.class or "")
                local currentValue = tonumber(entry.value)
                local candidateName = nameFromPath(path, entry.name)

                -- InventoryDelta is now quantity confirmation only. It accepts
                -- real numeric ValueBase changes from non-GUI data containers;
                -- added Frames, gradients and result-tile children are ignored.
                if change.kind == "added"
                    and string.find(className, "Value", 1, true)
                    and currentValue
                    and currentValue > 0 then

                    addCandidate(
                        run,
                        candidateName,
                        currentValue,
                        "InventoryDelta",
                        0.88,
                        nil,
                        nil,
                        path
                    )
                elseif change.kind == "changed"
                    and tonumber(change.delta)
                    and change.delta > 0
                    and string.find(className, "Value", 1, true) then

                    addCandidate(
                        run,
                        candidateName,
                        change.delta,
                        "InventoryDelta",
                        0.92,
                        nil,
                        nil,
                        path
                    )
                end

                if type(entry.attributes) == "table" and candidateName then
                    for key, value in pairs(entry.attributes) do
                        local numeric = tonumber(value)
                        if numeric
                            and numeric > 0
                            and hasWord(key, {"count", "amount", "quantity", "owned"}) then

                            addCandidate(
                                run,
                                candidateName,
                                numeric,
                                "InventoryDelta",
                                0.84,
                                nil,
                                nil,
                                path .. "." .. tostring(key)
                            )
                        end
                    end
                end
            end
        end
    end

    local function objectVisible(object)
        if not object or not object:IsA("GuiObject") then return false end
        local node = object
        while node and node ~= playerGui do
            if node:IsA("GuiObject") and not node.Visible then return false end
            if node:IsA("LayerCollector") and not node.Enabled then return false end
            node = node.Parent
        end
        return true
    end

    local function guiText(object)
        if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
            local value = tostring(object.Text or "")
            value = string.gsub(value, "<.->", "")
            value = string.gsub(value, "%s+", " ")
            return value
        end
        return nil
    end

    local function rewardGuiRoot()
        local best = nil
        for _, object in ipairs(playerGui:GetDescendants()) do
            local value = guiText(object)
            if value and objectVisible(object) then
                local textValue = lower(value)
                if string.find(textValue, "obtained", 1, true)
                    or textValue == "chests"
                    or string.find(textValue, "mission completed", 1, true)
                    or string.find(textValue, "raid completed", 1, true) then
                    best = object.Parent or object
                    break
                end
            end
        end
        return best
    end

    local function chestVisible()
        for _, object in ipairs(playerGui:GetDescendants()) do
            local value = guiText(object)
            if value and objectVisible(object) then
                local textValue = lower(value)
                if textValue == "chests" or string.find(textValue, "open (", 1, true) then return true end
            end
        end
        return false
    end

    local function captureGui(root, label)
        if not root then root = rewardGuiRoot() end
        if not root then return {label = label, entries = {}, count = 0} end
        local result = {label = label, root = safePath(root), entries = {}, count = 0}
        local objects = {root}
        for _, object in ipairs(root:GetDescendants()) do objects[#objects + 1] = object end
        for _, object in ipairs(objects) do
            if result.count >= 750 then result.truncated = true break end
            if screenGui and object:IsDescendantOf(screenGui) then continue end
            local attrs = attributesOf(object)
            local textValue = guiText(object)
            local image = nil
            if object:IsA("ImageLabel") or object:IsA("ImageButton") then image = tostring(object.Image or "") end
            local value = nil
            if object:IsA("ValueBase") then
                local ok, current = pcall(function() return object.Value end)
                if ok then value = serialize(current, 0, {}, {count = 0, max = 40}) end
            end
            if (textValue and textValue ~= "") or (image and image ~= "") or value ~= nil or next(attrs) ~= nil then
                result.count += 1
                local entry = {
                    path = safePath(object),
                    class = object.ClassName,
                    name = object.Name,
                    text = textValue,
                    image = image,
                    value = value,
                    attributes = next(attrs) and attrs or nil,
                }
                if object:IsA("GuiObject") then
                    entry.visible = objectVisible(object)
                    entry.position = {x = object.AbsolutePosition.X, y = object.AbsolutePosition.Y}
                    entry.size = {x = object.AbsoluteSize.X, y = object.AbsoluteSize.Y}
                end
                result.entries[#result.entries + 1] = entry
            end
        end
        return result
    end


    local CurrencyIconKinds = {
        ["15296242924"] = "EXP",
        ["15147178963"] = "Gold",
        ["15147184586"] = "Gems",
    }

    local IconNameAttributeKeys = {
        "ItemName", "RewardName", "DisplayName", "PerkName",
        "TraitName", "MaterialName", "SerumName", "Name",
        "ItemId", "RewardId",
    }

    local function normalizeAssetId(value)
        return string.match(tostring(value or ""), "(%d+)")
    end

    local function parseQuantityText(value)
        local cleaned = string.gsub(tostring(value or ""), "[,%s]", "")
        local number = tonumber(cleaned)
        if not number or number <= 0 then return 1 end
        return math.max(1, math.floor(number + 0.5))
    end

    local function passiveIconNameFromObject(imageObject, rewardRoot)
        if not imageObject then return nil, nil end
        if rewardRoot and (imageObject == rewardRoot or imageObject:IsDescendantOf(rewardRoot)) then
            return nil, nil
        end
        if screenGui and imageObject:IsDescendantOf(screenGui) then return nil, nil end

        local bestName = nil
        local bestScore = -math.huge
        local bestEvidence = nil
        local node = imageObject.Parent

        for depth = 1, 5 do
            if not node then break end

            local attributes = {}
            pcall(function() attributes = node:GetAttributes() end)
            for _, key in ipairs(IconNameAttributeKeys) do
                local candidate = cleanName(attributes[key])
                if candidate then
                    local score = 120 - depth
                    if score > bestScore then
                        bestName = candidate
                        bestScore = score
                        bestEvidence = safePath(node) .. ".attributes." .. key
                    end
                end
            end

            for _, object in ipairs(node:GetDescendants()) do
                if object:IsA("StringValue") then
                    local candidate = cleanName(object.Value)
                    if candidate then
                        local score = 100 - depth
                        if score > bestScore then
                            bestName = candidate
                            bestScore = score
                            bestEvidence = safePath(object)
                        end
                    end
                elseif object:IsA("TextLabel") or object:IsA("TextButton") then
                    local candidate = cleanName(guiText(object))
                    if candidate then
                        local lowered = lower(candidate)
                        local score = 65 - depth
                        if string.find(lowered, "equip", 1, true)
                            or string.find(lowered, "unequip", 1, true)
                            or string.find(lowered, "sell", 1, true)
                            or string.find(lowered, "locked", 1, true)
                            or string.find(lowered, "common", 1, true)
                            or string.find(lowered, "rare", 1, true)
                            or string.find(lowered, "epic", 1, true)
                            or string.find(lowered, "legendary", 1, true)
                            or string.find(lowered, "mythic", 1, true) then
                            score -= 45
                        end
                        if score > bestScore then
                            bestName = candidate
                            bestScore = score
                            bestEvidence = safePath(object)
                        end
                    end
                end
            end

            node = node.Parent
        end

        if bestScore >= 55 then
            return bestName, bestEvidence
        end
        return nil, nil
    end

    local function buildPassiveIconIndex(rewardRoot, wantedIds)
        local index = {}
        for _, object in ipairs(playerGui:GetDescendants()) do
            if object:IsA("ImageLabel") or object:IsA("ImageButton") then
                local assetId = normalizeAssetId(object.Image)
                if assetId
                    and wantedIds[assetId]
                    and not CurrencyIconKinds[assetId]
                    and not (rewardRoot and (object == rewardRoot or object:IsDescendantOf(rewardRoot)))
                    and not (screenGui and object:IsDescendantOf(screenGui)) then

                    local name, evidence = passiveIconNameFromObject(object, rewardRoot)
                    if name then
                        local current = index[assetId]
                        if not current then
                            index[assetId] = {
                                name = name,
                                evidence = evidence,
                                matches = 1,
                            }
                        elseif lower(current.name) == lower(name) then
                            current.matches += 1
                        end
                    end
                end
            end
        end
        return index
    end

    local PassiveRegistryMisses = environment.SliceHubRewardRegistryMisses
    if type(PassiveRegistryMisses) ~= "table" then
        PassiveRegistryMisses = {}
        environment.SliceHubRewardRegistryMisses = PassiveRegistryMisses
    end

    local RegistryNameKeys = {
        name = true, displayname = true, itemname = true, rewardname = true,
        perkname = true, traitname = true, materialname = true, serumname = true,
        title = true, dropname = true,
    }

    local function registryValueContainsAsset(value, assetId)
        local kind = typeof(value)
        if kind == "number" then return tostring(math.floor(value + 0.5)) == tostring(assetId) end
        if kind == "string" then return string.find(value, tostring(assetId), 1, true) ~= nil end
        return false
    end

    local function inspectRegistryTable(tbl, wantedIds, output, evidencePrefix)
        local iconMatches = {}
        local names = {}
        local count = 0
        local ok = pcall(function()
            for key, value in pairs(tbl) do
                count += 1
                if count > 90 then break end
                local keyLower = lower(key)
                local candidate = RegistryNameKeys[keyLower] and cleanName(value) or nil
                if candidate then names[#names + 1] = {name = candidate, key = tostring(key)} end
                for assetId in pairs(wantedIds) do
                    if registryValueContainsAsset(value, assetId)
                        and (string.find(keyLower, "icon", 1, true)
                            or string.find(keyLower, "image", 1, true)
                            or string.find(keyLower, "asset", 1, true)
                            or string.find(keyLower, "texture", 1, true)
                            or keyLower == "id") then
                        iconMatches[assetId] = tostring(key)
                    end
                end
            end
        end)
        if not ok then return end

        for assetId, iconKey in pairs(iconMatches) do
            local best = names[1]
            if best and not output[assetId] then
                output[assetId] = {
                    name = best.name,
                    evidence = tostring(evidencePrefix) .. "." .. tostring(iconKey) .. "+" .. tostring(best.key),
                    matches = 1,
                }
            end
        end
    end

    local function buildPassiveLoadedRegistry(wantedIds)
        local output = {}
        local unresolved = {}
        for assetId in pairs(wantedIds) do
            local cached = cleanName(LearnedRewardAssetNames[assetId])
            if cached then
                output[assetId] = {name = cached, evidence = "asset-cache", matches = 1}
            elseif not PassiveRegistryMisses[assetId] then
                unresolved[assetId] = true
            end
        end
        if next(unresolved) == nil then return output end

        local getGcFn = type(environment.getgc) == "function" and environment.getgc
            or (type(getgc) == "function" and getgc or nil)
        if type(getGcFn) ~= "function" then return output end

        local ok, objects = pcall(getGcFn, true)
        if not ok or type(objects) ~= "table" then return output end

        local inspected = 0
        for index, object in ipairs(objects) do
            if type(object) == "table" then
                inspected += 1
                inspectRegistryTable(object, unresolved, output, "getgc[" .. tostring(index) .. "]")
                local allFound = true
                for assetId in pairs(unresolved) do
                    if not output[assetId] then
                        allFound = false
                        break
                    end
                end
                if allFound or inspected >= 9000 then break end
            end
        end

        for assetId in pairs(unresolved) do
            local entry = output[assetId]
            if entry and cleanName(entry.name) then
                LearnedRewardAssetNames[assetId] = entry.name
            else
                PassiveRegistryMisses[assetId] = true
            end
        end
        return output
    end

    local function collectPassiveGuiTiles(run, rewardRoot)
        local byPrefix = {}

        for _, snapshot in ipairs(run.GuiSnapshots or {}) do
            for _, entry in ipairs(snapshot.entries or {}) do
                local path = tostring(entry.path or "")
                local iconPrefix = string.match(
                    path,
                    "^(.-%.Items%.[^%.]+%.Main%.Inner)%.Icon$"
                )
                local quantityPrefix = string.match(
                    path,
                    "^(.-%.Items%.[^%.]+%.Main%.Inner)%.Quantity$"
                )

                if iconPrefix and entry.visible ~= false then
                    local tile = byPrefix[iconPrefix] or {prefix = iconPrefix}
                    tile.image = tostring(entry.image or "")
                    tile.assetId = normalizeAssetId(tile.image)
                    tile.iconPath = path
                    byPrefix[iconPrefix] = tile
                elseif quantityPrefix and entry.visible ~= false then
                    local tile = byPrefix[quantityPrefix] or {prefix = quantityPrefix}
                    tile.quantityText = tostring(entry.text or "")
                    tile.quantity = parseQuantityText(tile.quantityText)
                    tile.quantityPath = path
                    byPrefix[quantityPrefix] = tile
                end
            end
        end

        local wantedIds = {}
        for _, tile in pairs(byPrefix) do
            if tile.assetId and not CurrencyIconKinds[tile.assetId] then
                wantedIds[tile.assetId] = true
            end
        end
        local registryIndex = buildPassiveLoadedRegistry(wantedIds)
        local iconIndex = buildPassiveIconIndex(rewardRoot, wantedIds)

        local tiles = {}
        for prefix, tile in pairs(byPrefix) do
            if tile.assetId then
                tile.slot = string.match(prefix, "%.Items%.([^%.]+)%.Main%.Inner$") or "?"
                tile.quantity = tonumber(tile.quantity) or 1
                tile.kind = CurrencyIconKinds[tile.assetId] or "Item"

                if tile.kind == "Item" then
                    local learnedName = cleanName(LearnedRewardAssetNames[tile.assetId])
                    local indexed = iconIndex[tile.assetId]
                    if learnedName then
                        tile.name = learnedName
                        tile.nameEvidence = "SliceHubRewardAssetNames[" .. tile.assetId .. "]"
                        tile.nameMatches = 1
                        addCandidate(
                            run,
                            tile.name,
                            tile.quantity,
                            "ResultTooltipAssetCache",
                            0.96,
                            tile.assetId,
                            nil,
                            tile.iconPath
                        )
                    elseif registryIndex[tile.assetId] and cleanName(registryIndex[tile.assetId].name) then
                        local registry = registryIndex[tile.assetId]
                        tile.name = registry.name
                        tile.nameEvidence = registry.evidence
                        tile.nameMatches = registry.matches
                        LearnedRewardAssetNames[tile.assetId] = tile.name
                        addCandidate(
                            run,
                            tile.name,
                            tile.quantity,
                            "ResultPassiveRegistry",
                            0.93,
                            tile.assetId,
                            nil,
                            tile.nameEvidence
                        )
                    elseif indexed and cleanName(indexed.name) then
                        tile.name = indexed.name
                        tile.nameEvidence = indexed.evidence
                        tile.nameMatches = indexed.matches
                        addCandidate(
                            run,
                            tile.name,
                            tile.quantity,
                            "ResultGUIAsset",
                            0.86,
                            tile.assetId,
                            nil,
                            tile.iconPath
                        )
                    else
                        tile.name = "Unresolved Reward [" .. tile.assetId .. "]"
                        addCandidate(
                            run,
                            tile.name,
                            tile.quantity,
                            "ResultGUIAsset",
                            0.74,
                            tile.assetId,
                            nil,
                            tile.iconPath
                        )
                    end
                end

                tiles[#tiles + 1] = tile
            end
        end

        table.sort(tiles, function(a, b)
            return tostring(a.slot) < tostring(b.slot)
        end)
        return tiles
    end

    local function mergeCandidates(run, passiveDrops)
        local best = {}
        local order = {}
        local function accept(candidate)
            local name = cleanName(candidate.name)
            if not name then return end
            local normalizedName = lower(name)
            if normalizedName == "unknown reward"
                or normalizedName == "unknown drop"
                or normalizedName == "unknown item"
                or normalizedName == "none detected" then
                return
            end
            local key = normalizedName
            local quantity = math.max(1, math.floor((tonumber(candidate.quantity) or 1) + 0.5))
            local confidence = tonumber(candidate.confidence) or 0.5
            local existing = best[key]
            if not existing then
                existing = {
                    name = name,
                    quantity = quantity,
                    source = candidate.source,
                    confidence = confidence,
                    id = candidate.id,
                    rarity = candidate.rarity,
                    evidence = candidate.evidence,
                }
                best[key] = existing
                order[#order + 1] = key
            elseif confidence > (existing.confidence or 0) then
                existing.name = name
                existing.quantity = quantity
                existing.source = candidate.source
                existing.confidence = confidence
                existing.id = candidate.id or existing.id
                existing.rarity = candidate.rarity or existing.rarity
                existing.evidence = candidate.evidence or existing.evidence
            elseif confidence == (existing.confidence or 0) then
                existing.quantity = math.max(existing.quantity or 1, quantity)
            end
        end

        for _, candidate in ipairs(run.Candidates or {}) do accept(candidate) end
        for _, drop in ipairs(type(passiveDrops) == "table" and passiveDrops or {}) do
            accept({
                name = drop.name,
                quantity = drop.quantity,
                source = "ResultGUI",
                confidence = 0.60,
            })
        end

        local output = {}
        for _, key in ipairs(order) do output[#output + 1] = best[key] end
        table.sort(output, function(a, b)
            if (a.confidence or 0) ~= (b.confidence or 0) then return (a.confidence or 0) > (b.confidence or 0) end
            return tostring(a.name) < tostring(b.name)
        end)
        return output
    end

    local function ensureFolder(path)
        if type(makeFolderFn) ~= "function" then return false end
        if type(isFolderFn) == "function" then
            local ok, exists = pcall(isFolderFn, path)
            if ok and exists then return true end
        end
        return pcall(makeFolderFn, path)
    end

    local function writeDump(dump)
        environment.SliceHubRewardDumpLatest = dump
        if type(writeFileFn) ~= "function" then return nil, "writefile unavailable" end
        ensureFolder("SH")
        ensureFolder("SH/reward_dumps")
        local okJson, encoded = pcall(function() return HttpService:JSONEncode(dump) end)
        if not okJson then return nil, "JSON encode failed: " .. tostring(encoded) end
        local stamp = os.date("!%Y%m%d_%H%M%S")
        local jobShort = string.sub(string.gsub(tostring(game.JobId or "local"), "[^%w]", ""), 1, 10)
        if jobShort == "" then jobShort = "local" end
        local path = "SH/reward_dumps/reward_" .. stamp .. "_" .. jobShort .. ".json"
        local okWrite, writeError = pcall(writeFileFn, path, encoded)
        if not okWrite then return nil, tostring(writeError) end
        pcall(writeFileFn, "SH/reward_dump_latest.json", encoded)
        Scanner.LastDumpPath = path
        environment.SliceHubRewardDumpPath = path
        return path
    end

    function Scanner.Begin(meta)
        if WebhookConfig.rewardScannerEnabled == false then
            Scanner.Active = false
            Scanner.Run = nil
            return false
        end
        Scanner.Start()
        Scanner.Active = true
        Scanner.Run = {
            SchemaVersion = Scanner.SchemaVersion,
            BuildVersion = Scanner.BuildVersion,
            Tier = tostring(BUILD and BUILD.Tier or "FREE"),
            PlaceId = tonumber(game.PlaceId) or 0,
            JobId = tostring(game.JobId or ""),
            Player = {name = player.Name, userId = player.UserId},
            StartedAt = os.time(),
            StartClock = os.clock(),
            Metadata = serialize(meta or {}, 0, {}, {count = 0, max = 180}),
            RemoteCounts = {},
            RecentRemoteEvents = {},
            RelevantRemoteEvents = {},
            Candidates = {},
            GuiSnapshots = {},
            InventoryBefore = snapshotInventory(),
        }
        print("[SliceHub V9.8.4][REWARD SCANNER] armed", tostring(meta and meta.runType or "run"))
        return true
    end

    function Scanner.Finalize(root, statusLower, data)
        if WebhookConfig.rewardScannerEnabled == false then return nil end
        if not Scanner.Active or type(Scanner.Run) ~= "table" then
            Scanner.Begin({
                runType = data and data.runType,
                raid = data and data.raidName,
                mission = data and data.missionDisplay,
                difficulty = data and data.difficulty,
            })
        end
        local run = Scanner.Run
        if type(run) ~= "table" then return nil end

        run.GuiSnapshots[#run.GuiSnapshots + 1] = captureGui(root, "result-initial")
        local isRaid = tostring(data and data.runType or "Mission") == "Raid"
        local maxWait = isRaid and 8.0 or 3.0
        local minWait = isRaid and 2.5 or 0.9
        local started = os.clock()
        local lastSignature = nil
        local stableReads = 0
        local lastSnapshot = nil
        local sawChest = false
        local chestClosed = false
        local lastGuiCapture = 0

        repeat
            task.wait(0.34)
            lastSnapshot = snapshotInventory()
            local signature = snapshotSignature(lastSnapshot)
            if signature == lastSignature then stableReads += 1 else stableReads = 1; lastSignature = signature end

            local chestNow = chestVisible()
            if chestNow then sawChest = true end
            if sawChest and not chestNow then chestClosed = true end

            if os.clock() - lastGuiCapture >= 0.9 then
                local dynamicRoot = rewardGuiRoot() or root
                run.GuiSnapshots[#run.GuiSnapshots + 1] = captureGui(dynamicRoot, chestNow and "chest-live" or "result-live")
                while #run.GuiSnapshots > 8 do table.remove(run.GuiSnapshots, 1) end
                lastGuiCapture = os.clock()
            end

            local elapsed = os.clock() - started
            if elapsed >= minWait and stableReads >= 3 then
                if not isRaid or (sawChest and chestClosed) then break end
            end
        until os.clock() - started >= maxWait

        run.FinishedAt = os.time()
        run.DurationObserved = os.clock() - run.StartClock
        run.ResultStatus = tostring(statusLower or "")
        run.InventoryAfter = lastSnapshot or snapshotInventory()
        run.InventoryDelta = diffSnapshots(run.InventoryBefore, run.InventoryAfter)
        inventoryCandidates(run, run.InventoryDelta)

        run.ServerRewardCapture = serialize(
            data and data.serverRewardCapture or nil,
            0,
            {},
            {count = 0, max = 520}
        )
        run.ServerRewardsRaw = serialize(
            data and data.serverRewardsRaw or nil,
            0,
            {},
            {count = 0, max = 520}
        )

        if data and data.serverRewardCaptureOk == true then
            for _, drop in ipairs(type(data.drops) == "table" and data.drops or {}) do
                addCandidate(
                    run,
                    drop.name,
                    drop.quantity,
                    "S_Rewards/Get",
                    1.0,
                    drop.id,
                    drop.category,
                    "S_Rewards.Get.Obtained"
                )
            end
        end

        run.GuiRewardTiles = collectPassiveGuiTiles(run, root)
        run.PassiveGuiDrops = serialize(data and data.drops or {}, 0, {}, {count = 0, max = 160})
        run.ResolvedDrops = mergeCandidates(run, data and data.drops or {})
        run.ScannerSummary = {
            remotePaths = (function() local n = 0 for _ in pairs(run.RemoteCounts) do n += 1 end return n end)(),
            relevantRemoteEvents = #run.RelevantRemoteEvents,
            recentRemoteEvents = #run.RecentRemoteEvents,
            inventoryChanges = #run.InventoryDelta,
            guiRewardTiles = #run.GuiRewardTiles,
            candidates = #run.Candidates,
            resolvedDrops = #run.ResolvedDrops,
            sawChest = sawChest,
            chestClosed = chestClosed,
            stableReads = stableReads,
            serverSnapshot = data and data.serverRewardCaptureOk == true or false,
            serverNamedRewards = data and data.serverNamedRewardsConfirmed == true or false,
        }

        local strongestSource = "ResultGUI"
        local strongestConfidence = 0
        for _, drop in ipairs(run.ResolvedDrops) do
            if (drop.confidence or 0) > strongestConfidence then
                strongestConfidence = drop.confidence or 0
                strongestSource = tostring(drop.source or "Unknown")
            end
        end
        run.Resolver = {source = strongestSource, confidence = strongestConfidence}

        local path, writeError = writeDump(run)
        Scanner.Active = false
        Scanner.Run = nil

        print(
            "[SliceHub V9.8.4][REWARD SCANNER] finalized",
            strongestSource,
            "drops=", #run.ResolvedDrops,
            "delta=", #run.InventoryDelta,
            path or writeError or "session-only"
        )

        return {
            drops = run.ResolvedDrops,
            source = strongestSource,
            confidence = strongestConfidence,
            path = path,
            writeError = writeError,
            inventoryChanges = #run.InventoryDelta,
            relevantRemoteEvents = #run.RelevantRemoteEvents,
            sawChest = sawChest,
            serverSnapshot = data and data.serverRewardCaptureOk == true or false,
            serverNamedRewards = data and data.serverNamedRewardsConfirmed == true or false,
        }
    end

    Scanner.Start()
end

---------------------------------------------------------------------
-- V9.8.4 EXACT S_REWARDS SNAPSHOT
---------------------------------------------------------------------

SRewardsWebhookV1 = SRewardsWebhookV1 or {}
do
    local Module = SRewardsWebhookV1
    Module.Version = 1

    local KnownCurrencyLabels = {
        XP = "EXP",
        Gold = "Gold",
        Gems = "Gems",
        BP_XP = "BP XP",
        Shards = "Shards",
        Silver = "Silver",
        Canes = "Canes",
    }

    local ReservedNames = {
        ["perk"] = true,
        ["perks"] = true,
        ["drop"] = true,
        ["drops"] = true,
        ["reward"] = true,
        ["rewards"] = true,
        ["item"] = true,
        ["items"] = true,
        ["chest"] = true,
        ["chests"] = true,
        ["quantity"] = true,
        ["amount"] = true,
        ["count"] = true,
        ["name"] = true,
        ["id"] = true,
        ["true"] = true,
        ["false"] = true,
    }

    local NameKeys = {
        name = true,
        itemname = true,
        rewardname = true,
        dropname = true,
        displayname = true,
        perkname = true,
        cosmeticname = true,
        serumname = true,
        artifactname = true,
        title = true,
    }

    local IdKeys = {
        id = true,
        itemid = true,
        rewardid = true,
        dropid = true,
        perkid = true,
        cosmeticid = true,
        serumid = true,
        artifactid = true,
    }

    local QuantityKeys = {
        quantity = true,
        amount = true,
        count = true,
        qty = true,
        stack = true,
        stacks = true,
        total = true,
    }

    local function trim(value)
        return tostring(value or "")
            :gsub("<.->", "")
            :gsub("\r", "")
            :gsub("^%s+", "")
            :gsub("%s+$", "")
    end

    local function normalizedKey(value)
        return string.lower(trim(value)):gsub("[^%w]", "")
    end

    local function cleanName(value)
        local name = trim(value)
        if name == "" or #name > 120 then return nil end

        local lower = string.lower(name)
        if ReservedNames[lower] then return nil end
        if string.match(lower, "^%d+$") then return nil end
        if string.find(lower, "rbxasset", 1, true)
            or string.find(lower, "http://", 1, true)
            or string.find(lower, "https://", 1, true)
            or string.find(lower, "workspace.", 1, true)
            or string.find(lower, "replicatedstorage.", 1, true) then
            return nil
        end

        return name
    end

    local function isNonEmpty(value)
        local kind = typeof(value)
        if kind == "table" then return next(value) ~= nil end
        if kind == "number" then return value ~= 0 end
        if kind == "boolean" then return value == true end
        if kind == "string" then return trim(value) ~= "" end
        return value ~= nil
    end

    local function addNamed(output, name, quantity, category, id)
        name = cleanName(name)
        if not name then return end

        local amount = tonumber(quantity) or 1
        amount = math.max(1, math.floor(amount + 0.5))

        output[#output + 1] = {
            name = name,
            quantity = amount,
            category = cleanName(category) or tostring(category or "Reward"),
            id = id ~= nil and tostring(id) or nil,
            source = "S_Rewards/Get",
            confidence = 1.0,
        }
    end

    local function collectNamed(value, category, output, depth, seen, hintName, hintId)
        depth = tonumber(depth) or 0
        seen = seen or {}
        if depth > 7 then return end

        local kind = typeof(value)
        if kind == "string" then
            addNamed(output, value, 1, category, hintId)
            return
        end
        if kind ~= "table" then return end
        if seen[value] then return end
        seen[value] = true

        local explicitName = nil
        local explicitId = hintId
        local explicitQuantity = nil

        for key, item in pairs(value) do
            local keyName = normalizedKey(key)
            if NameKeys[keyName] and (type(item) == "string" or type(item) == "number") then
                explicitName = item
            elseif IdKeys[keyName] and (type(item) == "string" or type(item) == "number") then
                explicitId = item
            elseif QuantityKeys[keyName] and tonumber(item) then
                explicitQuantity = tonumber(item)
            end
        end

        if not explicitName and hintName and explicitQuantity then
            explicitName = hintName
        end

        if explicitName then
            addNamed(output, explicitName, explicitQuantity or 1, category, explicitId)
        end

        local arrayLength = #value
        if arrayLength > 0 then
            for index = 1, arrayLength do
                collectNamed(value[index], category, output, depth + 1, seen, nil, nil)
            end
        else
            local inspected = 0
            for key, item in pairs(value) do
                inspected += 1
                if inspected > 160 then break end

                local keyName = normalizedKey(key)
                if not NameKeys[keyName] and not IdKeys[keyName] and not QuantityKeys[keyName] then
                    local keyText = cleanName(key)
                    local keyIsNumeric = tonumber(key) ~= nil
                    local itemKind = typeof(item)

                    if itemKind == "number" then
                        if keyText and not keyIsNumeric and item > 0 then
                            addNamed(output, keyText, item, category, nil)
                        end
                    elseif itemKind == "boolean" then
                        if item == true and keyText and not keyIsNumeric then
                            addNamed(output, keyText, 1, category, nil)
                        end
                    elseif itemKind == "string" then
                        local itemName = cleanName(item)
                        local itemNumber = tonumber(item)

                        if itemName and not itemNumber then
                            addNamed(
                                output,
                                itemName,
                                1,
                                category,
                                keyIsNumeric and tostring(key) or nil
                            )
                        elseif itemNumber and keyText and not keyIsNumeric then
                            addNamed(output, keyText, 1, category, tostring(item))
                        end
                    elseif itemKind == "table" then
                        collectNamed(
                            item,
                            category,
                            output,
                            depth + 1,
                            seen,
                            keyText and not keyIsNumeric and keyText or nil,
                            keyIsNumeric and tostring(key) or nil
                        )
                    end
                end
            end
        end

        seen[value] = nil
    end

    local function aggregateNamed(entries)
        local output = {}
        local byName = {}

        for _, entry in ipairs(type(entries) == "table" and entries or {}) do
            local name = cleanName(entry.name)
            local quantity = math.max(1, math.floor((tonumber(entry.quantity) or 1) + 0.5))
            if name then
                local key = string.lower(name)
                local existing = byName[key]
                if not existing then
                    existing = {
                        name = name,
                        quantity = 0,
                        category = entry.category,
                        id = entry.id,
                        source = "S_Rewards/Get",
                        confidence = 1.0,
                    }
                    byName[key] = existing
                    output[#output + 1] = existing
                end
                existing.quantity += quantity
            end
        end

        return output
    end

    local function normalizeChests(value)
        local output = {}
        if type(value) ~= "table" then return output end

        for key, item in pairs(value) do
            local name = cleanName(key)
            local available = item == true
                or (type(item) == "number" and item > 0)
                or (type(item) == "string" and trim(item) ~= "" and string.lower(trim(item)) ~= "false")

            if name and available then
                output[#output + 1] = {
                    name = name,
                    quantity = type(item) == "number" and math.max(1, math.floor(item + 0.5)) or 1,
                    state = item,
                }
            end
        end

        table.sort(output, function(a, b)
            return tostring(a.name) < tostring(b.name)
        end)

        return output
    end

    local function actuallyVisible(object, playerGui)
        if not object or not object:IsA("GuiObject") then return false end

        local current = object
        while current and current ~= playerGui do
            if current:IsA("GuiObject") and current.Visible == false then return false end
            if current:IsA("ScreenGui") and current.Enabled == false then return false end
            current = current.Parent
        end

        return true
    end

    local function exactResultState(playerGui)
        local interface = playerGui and playerGui:FindFirstChild("Interface")
        local rewards = interface and interface:FindFirstChild("Rewards")
        local main = rewards and rewards:FindFirstChild("Main")
        local info = main and main:FindFirstChild("Info")
        local state = info and info:FindFirstChild("State")

        if not (state and actuallyVisible(state, playerGui)) then
            return nil
        end

        local stateText = trim(state.Text)
        local lower = string.lower(stateText)
        if lower == "mission completed"
            or lower == "raid completed"
            or lower == "mission failed"
            or lower == "raid failed" then
            return stateText
        end

        return nil
    end

    local function findGetRemote(repStorage)
        local assets = repStorage and repStorage:FindFirstChild("Assets")
        local remotes = assets and assets:FindFirstChild("Remotes")
        local exact = remotes and remotes:FindFirstChild("GET")

        if exact and exact:IsA("RemoteFunction") then
            return exact
        end

        local fallback = repStorage and repStorage:FindFirstChild("GET", true)
        if fallback and fallback:IsA("RemoteFunction") then
            return fallback
        end

        return nil
    end

    function Module.Capture(playerGui, repStorage)
        local stateText = exactResultState(playerGui)
        if not stateText then
            return {
                ok = false,
                error = "exact result state unavailable",
                source = "S_Rewards/Get",
            }
        end

        local remote = findGetRemote(repStorage)
        if not remote then
            return {
                ok = false,
                error = "GET RemoteFunction unavailable",
                state = stateText,
                source = "S_Rewards/Get",
            }
        end

        local startedAt = os.clock()
        local invokeOk, response = pcall(function()
            return remote:InvokeServer("S_Rewards", "Get", true)
        end)

        if not invokeOk then
            return {
                ok = false,
                error = tostring(response),
                state = stateText,
                duration = os.clock() - startedAt,
                source = "S_Rewards/Get",
            }
        end

        if type(response) ~= "table" or type(response.Obtained) ~= "table" then
            return {
                ok = false,
                error = "response missing Obtained table",
                state = stateText,
                duration = os.clock() - startedAt,
                raw = response,
                source = "S_Rewards/Get",
            }
        end

        local obtained = response.Obtained
        local named = {}
        local extraCurrencies = {}
        local unknownCategories = {}

        for key, value in pairs(obtained) do
            local keyText = tostring(key)
            local normalized = normalizedKey(keyText)

            if normalized == "perks" then
                collectNamed(value, "Perk", named, 0, {}, nil, nil)
            elseif normalized == "drops" then
                collectNamed(value, "Drop", named, 0, {}, nil, nil)
            elseif normalized == "chests" then
                -- Chest choices are reported separately; they are never treated
                -- as opened contents.
            elseif KnownCurrencyLabels[keyText] ~= nil then
                if keyText ~= "XP" and keyText ~= "Gold" and keyText ~= "Gems" then
                    local numberValue = tonumber(value)
                    if numberValue and numberValue ~= 0 then
                        extraCurrencies[keyText] = numberValue
                    end
                end
            elseif type(value) == "number" then
                if value ~= 0 then
                    extraCurrencies[keyText] = value
                    unknownCategories[keyText] = value
                end
            elseif isNonEmpty(value) then
                collectNamed(value, keyText, named, 0, {}, nil, nil)
                unknownCategories[keyText] = value
            end
        end

        return {
            ok = true,
            source = "S_Rewards/Get",
            state = stateText,
            duration = os.clock() - startedAt,
            raw = response,
            obtained = obtained,
            namedRewards = aggregateNamed(named),
            namedRewardInstances = named,
            chests = normalizeChests(obtained.Chests),
            extraCurrencies = extraCurrencies,
            unknownCategories = unknownCategories,
            stats = type(response.Stats) == "table" and response.Stats or {},
            claimed = response.Claimed,
            completed = response.Completed,
        }
    end

    function Module.Apply(data, capture)
        if type(data) ~= "table" or type(capture) ~= "table" or capture.ok ~= true then
            return false
        end

        local obtained = capture.obtained or {}
        local stats = capture.stats or {}

        if tonumber(obtained.XP) ~= nil then data.exp = math.max(0, tonumber(obtained.XP) or 0) end
        if tonumber(obtained.Gold) ~= nil then data.gold = math.max(0, tonumber(obtained.Gold) or 0) end
        if tonumber(obtained.Gems) ~= nil then data.gems = math.max(0, tonumber(obtained.Gems) or 0) end

        if tonumber(stats.Damage) ~= nil then data.damageDealt = math.max(0, tonumber(stats.Damage) or 0) end
        if tonumber(stats.Kills) ~= nil then data.titanKills = math.max(0, tonumber(stats.Kills) or 0) end
        if tonumber(stats.Crits) ~= nil then data.criticalHits = math.max(0, tonumber(stats.Crits) or 0) end
        if tonumber(stats.Boss_Damage) ~= nil then data.bossDamage = math.max(0, tonumber(stats.Boss_Damage) or 0) end

        data.serverRewardCapture = capture
        data.serverRewardsRaw = capture.raw
        data.serverRewardInstances = type(capture.namedRewardInstances) == "table"
            and capture.namedRewardInstances or {}
        data.serverRewardCaptureOk = true
        data.serverNamedRewardsConfirmed = type(capture.namedRewards) == "table"
            and #capture.namedRewards > 0
        data.chests = type(capture.chests) == "table" and capture.chests or {}
        data.extraCurrencies = type(capture.extraCurrencies) == "table"
            and capture.extraCurrencies or {}
        data.rewardSource = "S_Rewards/Get"

        if data.serverNamedRewardsConfirmed then
            data.drops = capture.namedRewards
        end

        return true
    end

    local function classifyValue(value)
        if type(value) == "boolean" then
            return value and "Raid" or nil
        end

        local lower = string.lower(trim(value))
        if lower == "" then return nil end
        if string.find(lower, "raid", 1, true) then return "Raid" end
        if string.find(lower, "mission", 1, true) then return "Mission" end
        return nil
    end

    local function inspectTypeObject(object, scanDescendants)
        if not object then return nil end

        local attributes = {}
        pcall(function() attributes = object:GetAttributes() end)

        for _, key in ipairs({
            "Type", "RunType", "Mode", "MapType", "MissionType", "Category",
            "IsRaid", "Raid",
        }) do
            local value = attributes[key]
            if value ~= nil then
                if (key == "IsRaid" or key == "Raid") and type(value) == "boolean" then
                    return value and "Raid" or "Mission"
                end
                local resolved = classifyValue(value)
                if resolved then return resolved end
            end
        end

        if scanDescendants == true then
            local inspected = 0
            for _, child in ipairs(object:GetDescendants()) do
                inspected += 1
                if inspected > 80 then break end

                if child:IsA("StringValue")
                    or child:IsA("BoolValue")
                    or child:IsA("IntValue")
                    or child:IsA("NumberValue") then
                    local keyName = normalizedKey(child.Name)
                    if keyName == "type"
                        or keyName == "runtype"
                        or keyName == "mode"
                        or keyName == "maptype"
                        or keyName == "missiontype"
                        or keyName == "category"
                        or keyName == "israid"
                        or keyName == "raid" then
                        if (keyName == "israid" or keyName == "raid") and type(child.Value) == "boolean" then
                            return child.Value and "Raid" or "Mission"
                        end
                        local resolved = classifyValue(child.Value)
                        if resolved then return resolved end
                    end
                end
            end
        end

        return nil
    end

    function Module.ResolveReplicatedRunType(repStorage, workspaceService)
        local data = repStorage and repStorage:FindFirstChild("Data")
        local copy = data and data:FindFirstChild("Copy")
        local fromCopy = inspectTypeObject(copy, true)
        if fromCopy then return fromCopy, "Data.Copy" end

        local fromWorkspace = inspectTypeObject(workspaceService, false)
        if fromWorkspace then return fromWorkspace, "Workspace.Type" end

        return nil, nil
    end

    function Module.FormatCurrencyLine(data, formatter)
        formatter = type(formatter) == "function" and formatter or tostring

        local parts = {
            "EXP **" .. formatter(data and data.exp or 0) .. "**",
            "Gold **" .. formatter(data and data.gold or 0) .. "**",
            "Gems **" .. formatter(data and data.gems or 0) .. "**",
        }

        local extras = data and data.extraCurrencies
        if type(extras) == "table" then
            local keys = {}
            for key, value in pairs(extras) do
                if tonumber(value) and tonumber(value) ~= 0 then
                    keys[#keys + 1] = tostring(key)
                end
            end
            table.sort(keys)

            for _, key in ipairs(keys) do
                local label = KnownCurrencyLabels[key] or key:gsub("_", " ")
                parts[#parts + 1] = tostring(label) .. " **" .. formatter(extras[key]) .. "**"
            end
        end

        return table.concat(parts, "  •  ")
    end

    function Module.FormatChests(chests)
        if type(chests) ~= "table" or #chests == 0 then return nil end

        local names = {}
        for _, chest in ipairs(chests) do
            local name = cleanName(chest.name)
            if name then names[#names + 1] = "**" .. name .. "**" end
        end

        if #names == 0 then return nil end
        return "Detected options: " .. table.concat(names, ", ")
            .. "\nContents were not opened or claimed by SliceHub."
    end
end

---------------------------------------------------------------------
-- MISSION COMPLETION & WEBHOOK DETECTION
---------------------------------------------------------------------

;(function() -- webhook mission monitor scoped to avoid Luau's 200 local-register limit
	local function startMissionWebhookMonitor()
	local resultScreenActive = false
	local lastWebhookSignature = ""
	local lastWebhookSentAt = 0
	local lastAutoRetryAt = 0

    V3ResultGuard = {
        Armed = false,
        Processing = false,
        ResultSeenSince = nil,
        ActiveEvidenceSince = nil,
        LastAcceptedAt = 0,
    }

	local function getPlayerStats()
		-- v114: safe account-stat scan. No result GUI guessing; only exact ValueBase/Attribute names
		-- under player/player-data containers are accepted. Unknown fields are omitted in the embed.
		local stats = {
			level = nil,
			prestige = nil,
			gold = nil,
			gems = nil,
			trusted = false,
		}

		local function fmt(value)
			local number = tonumber(value)
			if not number then return nil end
			local text = tostring(math.floor(number))
			local sign = ""
			if string.sub(text, 1, 1) == "-" then
				sign = "-"
				text = string.sub(text, 2)
			end
			local result = text
			while true do
				local nextText, replaced = string.gsub(result, "^(%d+)(%d%d%d)", "%1,%2")
				result = nextText
				if replaced == 0 then break end
			end
			return sign .. result
		end

		local function canonicalName(name)
			local lower = string.lower(tostring(name or ""))
			lower = string.gsub(lower, "[^%w]", "")
			if lower == "level" or lower == "lvl" or lower == "playerlevel" or lower == "currentlevel" then return "level" end
			if lower == "prestige" or lower == "prestiges" or lower == "prestigelevel" or lower == "prestigelvl" or lower == "p" then return "prestige" end
			if lower == "gold" or lower == "coins" or lower == "coin" or lower == "money" or lower == "cash" or lower == "currency" then return "gold" end
			if lower == "gems" or lower == "gem" or lower == "crystals" or lower == "crystal" or lower == "shards" then return "gems" end
			return nil
		end

		local function betterNumber(currentText, newValue)
			local current = tonumber(string.gsub(tostring(currentText or ""), ",", ""))
			local newNumber = tonumber(newValue)
			if not newNumber then return false end
			if current == nil then return true end
			-- Prefer non-zero if a previous weak scan found zero.
			if current == 0 and newNumber > 0 then return true end
			return false
		end

		local function applyStat(name, value)
			local key = canonicalName(name)
			if not key then return end
			local text = fmt(value)
			if not text then return end
			if key == "level" then
				if betterNumber(stats.level, value) then stats.level = text; stats.trusted = true end
			elseif key == "prestige" then
				if betterNumber(stats.prestige, value) then stats.prestige = text; stats.trusted = true end
			elseif key == "gold" then
				if betterNumber(stats.gold, value) then stats.gold = text; stats.trusted = true end
			elseif key == "gems" then
				if betterNumber(stats.gems, value) then stats.gems = text; stats.trusted = true end
			end
		end

		local function scanAttributes(object)
			if not object or type(object.GetAttributes) ~= "function" then return end
			local ok, attributes = pcall(function() return object:GetAttributes() end)
			if ok and type(attributes) == "table" then
				for name, value in pairs(attributes) do applyStat(name, value) end
			end
		end

		local function scanValues(root, depthLimit)
			if not root then return end
			scanAttributes(root)
			local rootDepth = 0
			local rootPath = root:GetFullName()
			for _, object in ipairs(root:GetDescendants()) do
				local full = object:GetFullName()
				if not string.find(full, "PlayerGui", 1, true) and not string.find(full, "TitanControlMenu", 1, true) then
					if object:IsA("IntValue") or object:IsA("NumberValue") or object:IsA("StringValue") then
						applyStat(object.Name, object.Value)
					end
					scanAttributes(object)
				end
			end
		end

		scanValues(player)

		-- Some games replicate account stats in ReplicatedStorage.PlayerData/<UserId or Name>.
		local dataRoots = {"PlayerData", "Players", "Profiles", "Data", "Stats", "PlayerStats"}
		for _, rootName in ipairs(dataRoots) do
			local root = ReplicatedStorage:FindFirstChild(rootName)
			if root then
				local userFolder = root:FindFirstChild(tostring(player.UserId)) or root:FindFirstChild(player.Name)
				if userFolder then scanValues(userFolder) end
			end
		end

		return stats
	end

	local ResultKeywords = {
		"mission failed",
		"mission fail",
		"mission complete",
		"mission completed",
        "raid failed",
        "raid fail",
        "raid complete",
        "raid completed",
		"victory",
		"defeat",
	}

	local function cleanGuiText(value)
		local raw = tostring(value or "")
		local out = {}
		local inTag = false
		local lastWasSpace = false

		for index = 1, #raw do
			local ch = string.sub(raw, index, index)
			local byte = string.byte(ch)

			if ch == "<" then
				inTag = true
			elseif ch == ">" then
				inTag = false
			elseif not inTag then
				local isSpace = byte == 9 or byte == 10 or byte == 13 or byte == 32
				if isSpace then
					if not lastWasSpace and #out > 0 then
						out[#out + 1] = " "
						lastWasSpace = true
					end
				else
					out[#out + 1] = ch
					lastWasSpace = false
				end
			end
		end

		local text = table.concat(out)
		while #text > 0 and string.sub(text, -1) == " " do
			text = string.sub(text, 1, #text - 1)
		end
		return text
	end

	local function hasAnyKeyword(lowerText, keywords)
		for _, keyword in ipairs(keywords) do
			if string.find(lowerText, keyword, 1, true) then
				return true
			end
		end
		return false
	end

	local function getTextFromObject(object)
		if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
			return cleanGuiText(object.Text)
		end
		return nil
	end

	local function isVisibleTextObject(object)
		if not object:IsA("GuiObject") then return false end
		local ok, visible = pcall(guiObjectIsActuallyVisible, object)
		return ok and visible == true
	end

	local function guiTextDescendantHas(root, keywords)
		if not root then return false end

		for _, descendant in ipairs(root:GetDescendants()) do
			local text = getTextFromObject(descendant)
			if text and text ~= "" and isVisibleTextObject(descendant) then
				if hasAnyKeyword(string.lower(text), keywords) then
					return true
				end
			end
		end

		return false
	end

	local function findMissionResultRoot()
		for _, object in ipairs(playerGui:GetDescendants()) do
			local text = getTextFromObject(object)
			if text and text ~= "" and isVisibleTextObject(object) then
				local lower = string.lower(text)
				if hasAnyKeyword(lower, ResultKeywords) then
					local node = object
					for _ = 1, 10 do
						if not node or node == playerGui then break end

						if node:IsA("GuiObject") then
							local hasStats = guiTextDescendantHas(node, {"stats"})
							local hasObtained = guiTextDescendantHas(node, {"obtained"})
							local hasButtons = guiTextDescendantHas(node, {"leave", "modifiers", "retry"})
							if hasStats and (hasObtained or hasButtons) then
								return node, lower
							end
						end

						node = node.Parent
					end

					return object.Parent, lower
				end
			end
		end
		return nil, nil
	end


	local function findGuiButtonAncestor(object)
		local node = object
		for _ = 1, 8 do
			if not node or node == playerGui then break end
			if node:IsA("GuiButton") then
				return node
			end
			node = node.Parent
		end
		return nil
	end

	local function clickVisibleGuiObject(object)
		if not object or not object:IsA("GuiObject") then
			return false, "invalid retry target"
		end

		local originalTarget = findGuiButtonAncestor(object) or object
		if not originalTarget:IsA("GuiObject") then
			return false, "retry target is not a GuiObject"
		end

		-- V9.8.2.8.2: Retry must not depend on SliceHub being closed or on a
		-- physical cursor landing on the Roblox button. Prefer the result GUI's
		-- own callback, then keyboard activation, and use a mouse click only as
		-- the final fallback while SliceHub is fully disabled.
		local env = type(getgenv) == "function" and getgenv() or _G
		local getConnections = type(env) == "table" and env.getconnections or nil
		if type(getConnections) ~= "function" and type(getconnections) == "function" then
			getConnections = getconnections
		end

		local teleportStarted = false
		local teleportConnection = nil
		pcall(function()
			teleportConnection = player.OnTeleport:Connect(function()
				teleportStarted = true
			end)
		end)

		local function disconnectTeleportWatcher()
			if teleportConnection then
				pcall(function() teleportConnection:Disconnect() end)
				teleportConnection = nil
			end
		end

		local initialRoot = findMissionResultRoot()
		local initialText = string.lower(tostring(getTextFromObject(originalTarget) or ""))

		local function resultTransitioned()
			if teleportStarted or not player.Parent then return true end

			local currentRoot = findMissionResultRoot()
			if currentRoot == nil or currentRoot ~= initialRoot then return true end
			if not originalTarget.Parent then return true end

			local currentText = string.lower(tostring(getTextFromObject(originalTarget) or ""))
			if currentText ~= "" and currentText ~= initialText then
				if string.find(currentText, "start", 1, true)
					or string.find(currentText, "load", 1, true)
					or string.find(currentText, "join", 1, true)
					or not string.find(currentText, "retry", 1, true) then
					return true
				end
			end

			for _, child in ipairs(currentRoot:GetDescendants()) do
				local value = getTextFromObject(child)
				if value and value ~= "" and isVisibleTextObject(child) then
					local lower = string.lower(value)
					if string.find(lower, "starting", 1, true)
						or string.find(lower, "teleporting", 1, true)
						or string.find(lower, "loading", 1, true)
						or string.find(lower, "joining", 1, true) then
						return true
					end
				end
			end

			return false
		end

		local function waitForTransition(timeout)
			local started = os.clock()
			while os.clock() - started < timeout do
				if resultTransitioned() then return true end
				task.wait(0.08)
			end
			return resultTransitioned()
		end

		local function closeRobloxMenu()
			local menuOpen = false
			pcall(function() menuOpen = GuiService.MenuIsOpen == true end)
			if not menuOpen then return true end

			pcall(function()
				VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Escape, false, game)
				task.wait(0.045)
				VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Escape, false, game)
			end)

			local started = os.clock()
			while os.clock() - started < 1.25 do
				local stillOpen = false
				pcall(function() stillOpen = GuiService.MenuIsOpen == true end)
				if not stillOpen then return true end
				task.wait(0.05)
			end
			return false
		end

		pcall(function()
			local focused = UserInputService:GetFocusedTextBox()
			if focused then focused:ReleaseFocus(false) end
		end)
		closeRobloxMenu()

		local oldScreenEnabled = screenGui and screenGui.Enabled
		local oldWindowVisible = window and window.Visible
		local oldShadowVisible = shadow and shadow.Visible
		local oldCursorVisible = guiCursor and guiCursor.Visible
		local hideOwnGui = screenGui and not originalTarget:IsDescendantOf(screenGui)

		local function hideSliceHub()
			if not hideOwnGui then return end
			if screenGui then screenGui.Enabled = false end
			if window then window.Visible = false end
			if shadow then shadow.Visible = false end
			if guiCursor then guiCursor.Visible = false end
			task.wait(0.04)
		end

		local function restoreSliceHub()
			if not hideOwnGui then return end
			if screenGui then screenGui.Enabled = oldScreenEnabled ~= false end
			if window then window.Visible = oldWindowVisible == true end
			if shadow then shadow.Visible = oldShadowVisible == true end
			if guiCursor then guiCursor.Visible = oldCursorVisible == true end
		end

		hideSliceHub()

		local pos = originalTarget.AbsolutePosition
		local size = originalTarget.AbsoluteSize
		local x = math.floor(pos.X + size.X / 2 + 0.5)
		local y = math.floor(pos.Y + size.Y / 2 + 0.5)
		local target = originalTarget

		-- Re-resolve the actual topmost Roblox button after SliceHub is disabled.
		pcall(function()
			local objects = playerGui:GetGuiObjectsAtPosition(x, y)
			for _, candidate in ipairs(objects) do
				if not screenGui or not candidate:IsDescendantOf(screenGui) then
					local button = findGuiButtonAncestor(candidate)
					if button then
						target = button
						break
					end
				end
			end
		end)

		local function fireConnectionList(signal, activatedSignal)
			if type(getConnections) ~= "function" then return false end
			local okList, list = pcall(getConnections, signal)
			if not okList or type(list) ~= "table" then return false end

			for _, connection in ipairs(list) do
				local enabled = true
				pcall(function()
					if connection.Enabled == false then enabled = false end
				end)
				if enabled then
					local fired = false
					local okFireMember, fireMember = pcall(function() return connection.Fire end)
					if okFireMember and type(fireMember) == "function" then
						local okFire = activatedSignal
							and pcall(fireMember, connection, nil, 1)
							or pcall(fireMember, connection)
						fired = okFire == true
					end

					if not fired then
						local okFunctionMember, callback = pcall(function() return connection.Function end)
						if okFunctionMember and type(callback) == "function" then
							local okCallback = activatedSignal
								and pcall(callback, nil, 1)
								or pcall(callback)
							fired = okCallback == true
						end
					end

					if fired then
						print("[SliceHub V9.8.4][AUTO RETRY] direct callback fired")
						if waitForTransition(0.85) then return true end
					end
				end
			end
			return false
		end

		-- Attempt 1: normal signal activation plus direct callback invocation.
		if target:IsA("GuiButton") then
			pcall(function() target:Activate() end)
			if type(firesignal) == "function" then
				pcall(function() firesignal(target.Activated, nil, 1) end)
				pcall(function() firesignal(target.MouseButton1Click) end)
			end
			if waitForTransition(0.50) then
				restoreSliceHub()
				disconnectTeleportWatcher()
				print("[SliceHub V9.8.4][AUTO RETRY] success via Activate/firesignal")
				return true, "signal"
			end

			if fireConnectionList(target.Activated, true)
				or fireConnectionList(target.MouseButton1Click, false) then
				restoreSliceHub()
				disconnectTeleportWatcher()
				return true, "callback"
			end
		end

		-- Attempt 2: select the real Roblox button and activate it by keyboard.
		local oldSelected = nil
		pcall(function()
			oldSelected = GuiService.SelectedObject
			GuiService.SelectedObject = target
		end)
		pcall(function()
			VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
			task.wait(0.06)
			VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
		end)
		if waitForTransition(0.80) then
			restoreSliceHub()
			disconnectTeleportWatcher()
			print("[SliceHub V9.8.4][AUTO RETRY] success via keyboard activation")
			return true, "keyboard"
		end
		pcall(function() GuiService.SelectedObject = oldSelected end)

		-- Attempt 3: final physical click, but SliceHub is disabled and the Roblox
		-- menu has already been closed, so neither can intercept or drag.
		closeRobloxMenu()
		local inset = Vector2.new(0, 0)
		pcall(function() inset = GuiService:GetGuiInset() end)
		pcall(function()
			VirtualInputManager:SendMouseMoveEvent(x + inset.X, y + inset.Y, game)
			task.wait(0.04)
			VirtualInputManager:SendMouseButtonEvent(x + inset.X, y + inset.Y, 0, true, game, 0)
			task.wait(0.075)
			VirtualInputManager:SendMouseButtonEvent(x + inset.X, y + inset.Y, 0, false, game, 0)
		end)

		local transitioned = waitForTransition(2.75)
		restoreSliceHub()
		disconnectTeleportWatcher()

		if transitioned then
			print("[SliceHub V9.8.4][AUTO RETRY] success via protected mouse fallback")
			return true, "mouse"
		end

		warn("[SliceHub V9.8.4][AUTO RETRY] all activation methods failed")
		return false, "retry was not accepted"
	end

	local function findRetryButton(root)
		local bestObject = nil
		local bestY = -math.huge

		local function scanRetryText(scanRoot)
			if not scanRoot then return end
			for _, object in ipairs(scanRoot:GetDescendants()) do
				if screenGui and object:IsDescendantOf(screenGui) then
					continue
				end
				local text = getTextFromObject(object)
				if text and text ~= "" and isVisibleTextObject(object) then
					local lower = string.lower(text)
					if string.find(lower, "retry", 1, true) then
						local candidate = findGuiButtonAncestor(object) or object
						if candidate:IsA("GuiObject") and candidate.AbsolutePosition.Y > bestY then
							bestY = candidate.AbsolutePosition.Y
							bestObject = candidate
						end
					end
				end
			end
		end

		scanRetryText(root)
		if not bestObject then
			scanRetryText(playerGui)
		end
		return bestObject
	end

	local function autoRetryFromResultGui(root)
		if not State.AutoRetryEnabled then return end
        if V43RaidChestAuto
            and V43RaidChestAuto.Busy == true then
            return
        end
		local now = tick()
		if now - lastAutoRetryAt < 2.5 then return end
		lastAutoRetryAt = now
		task.wait(0.18)
		local refreshedRoot = findMissionResultRoot()
		root = refreshedRoot or root
		local retryButton = findRetryButton(root)
		if retryButton then
			local success, method = clickVisibleGuiObject(retryButton)
			if not success then
				State.AutoRetryLastStatus =
					tostring(method or "Retry did not start.")
			else
				State.AutoRetryLastStatus = "Transition accepted"
			end
		else
			State.AutoRetryLastStatus =
				"Retry button was not available."
		end
	end

	local function handleAutoCycleFromResultGui(root)
		if not State.AutoRetryEnabled then return end
        if V43RaidChestAuto
            and V43RaidChestAuto.Busy == true then
            return
        end
        if State.AutoRetrySuppressed == true
            or (ReturnToLobby and (ReturnToLobby.Running or ReturnToLobby.Locked)) then
            return
        end
		local now = tick()
		if now - lastAutoRetryAt < 2.5 then return end
		lastAutoRetryAt = now

		State.AutoMissionCount = math.clamp(math.floor((tonumber(State.AutoMissionCount) or 0) + 1.5), 0, 99)
		refreshAutoMissionStatus()
		saveSettingsIfReady()

		task.wait(0.18)

		local limit = math.clamp(math.floor((tonumber(State.AutoMissionLimit) or 0) + 0.5), 0, 10)
		if limit > 0 and State.AutoMissionCount >= limit then
            State.AutoRetrySuppressed = true
            ReturnToLobby.Locked = true
			State.AutoRetryLastStatus = "Returning to lobby"
			refreshAutoMissionStatus()
			saveSettingsIfReady()
			ReturnToLobby.Run("Mission limit " .. tostring(limit) .. " reached")
			return
		end

		local refreshedRoot = findMissionResultRoot()
		root = refreshedRoot or root
		local retryButton = findRetryButton(root)
		if retryButton then
			local success, method = clickVisibleGuiObject(retryButton)
			if not success then
				State.AutoRetryLastStatus =
					tostring(method or "Retry did not start.")
			else
				State.AutoRetryLastStatus = "Transition accepted"
			end
		else
			State.AutoRetryLastStatus =
				"Retry button was not available."
		end
	end

	triggerAutoRetryNow = function()
		if not State.AutoRetryEnabled then return end
        if V43RaidChestAuto
            and V43RaidChestAuto.Busy == true then
            return
        end
        if State.AutoRetrySuppressed == true
            or (ReturnToLobby and (ReturnToLobby.Running or ReturnToLobby.Locked)) then
            return
        end
		local root = findMissionResultRoot()
		if root then
			handleAutoCycleFromResultGui(root)
		end
	end

	local function parseNumber(text)
		local compact = string.gsub(tostring(text or ""), ",", "")
		local numberText = string.match(compact, "%d+")
		return numberText and tonumber(numberText) or nil
	end

	local function parseClock(text)
		return string.match(tostring(text or ""), "%d+:%d+")
	end

	local function getVisibleTextItems(root)
		local items = {}
		if not root then return items end

		for _, object in ipairs(root:GetDescendants()) do
			local text = getTextFromObject(object)
			if text and text ~= "" and isVisibleTextObject(object) then
				local position = object.AbsolutePosition
				table.insert(items, {
					text = text,
					lower = string.lower(text),
					number = parseNumber(text),
					clock = parseClock(text),
					x = position.X,
					y = position.Y,
					object = object,
				})
			end
		end

		table.sort(items, function(a, b)
			if math.abs(a.y - b.y) > 8 then
				return a.y < b.y
			end
			return a.x < b.x
		end)

		return items
	end

	local function findClockValue(items)
		for _, item in ipairs(items) do
			if item.clock and item.clock ~= "" then
				return item.clock
			end
		end
		return "Unknown"
	end

	local function findMetricValue(items, keywords)
		for index, item in ipairs(items) do
			if hasAnyKeyword(item.lower, keywords) then
				if item.number then
					return item.number
				end

				for lookAhead = index + 1, math.min(#items, index + 12) do
					local candidate = items[lookAhead]
					if candidate.number then
						local sameRow = math.abs(candidate.y - item.y) <= 34 and candidate.x >= item.x
						local nearbyBelow = candidate.y >= item.y and candidate.y - item.y <= 90
						if sameRow or nearbyBelow then
							return candidate.number
						end
					end
				end
			end
		end
		return 0
	end

	local function formatNumber(value)
		local number = tonumber(value)
		if not number then return "Unknown" end

		local text = tostring(math.floor(number))
		local sign = ""
		if string.sub(text, 1, 1) == "-" then
			sign = "-"
			text = string.sub(text, 2)
		end

		local result = text
		while true do
			local replaced
			result, replaced = string.gsub(result, "^(%d+)(%d%d%d)", "%1,%2")
			if replaced == 0 then break end
		end

		return sign .. result
	end

	local function isOnlyNumberText(text)
		local compact = string.gsub(tostring(text or ""), ",", "")
		compact = string.gsub(compact, "%s+", "")
		return string.match(compact, "^%d+$") ~= nil
	end

	local function isStandardResultText(lowerText)
		local textValue = tostring(lowerText or "")
		if textValue == "" then return true end
		if isOnlyNumberText(textValue) then return true end

		local exactIgnored = {
			["mission completed"] = true,
			["mission complete"] = true,
			["mission failed"] = true,
			["mission fail"] = true,
			["stats"] = true,
			["time taken"] = true,
			["damage dealt"] = true,
			["titans killed"] = true,
			["critical hits"] = true,
			["obtained"] = true,
			["leave"] = true,
			["modifiers"] = true,
			["retry"] = true,
			[">"] = true,
			["<"] = true,
			["exp"] = true,
			["xp"] = true,
			["gold"] = true,
			["gems"] = true,
			["gem"] = true,
			["achievement"] = true,
		}

		if exactIgnored[textValue] then return true end
		if string.find(textValue, "retry", 1, true) then return true end
		if string.find(textValue, "your streak", 1, true) then return true end
		return false
	end

	local function findFirstItemWithKeyword(items, keywords)
		for _, item in ipairs(items) do
			if hasAnyKeyword(item.lower, keywords) then
				return item
			end
		end
		return nil
	end

	local function findButtonStartY(items)
		local lowest = math.huge
		for _, item in ipairs(items) do
			if item.lower == "leave" or item.lower == "modifiers" or string.find(item.lower, "retry", 1, true) then
				if item.y < lowest then
					lowest = item.y
				end
			end
		end
		return lowest ~= math.huge and lowest or nil
	end

	local function collectRewardNumberItems(items)
		local obtainedItem = findFirstItemWithKeyword(items, {"obtained"})
		if not obtainedItem then return {} end

		local buttonY = findButtonStartY(items) or math.huge
		local rewardItems = {}

		for _, item in ipairs(items) do
			if item.number and item.y > obtainedItem.y + 6 and item.y < buttonY - 3 then
				if item.lower ~= ">" and item.lower ~= "<" and not string.find(item.lower, "retry", 1, true) then
					table.insert(rewardItems, item)
				end
			end
		end

		table.sort(rewardItems, function(a, b)
			if math.abs(a.y - b.y) > 10 then
				return a.y < b.y
			end
			return a.x < b.x
		end)

		-- Some result screens expose a tiny hidden/count label right after "OBTAINED".
		-- If it appears before the real reward row, drop it so EXP/Gold/Gems line up correctly.
		while #rewardItems >= 4
			and (rewardItems[1].number or 0) < 1000
			and (rewardItems[2].number or 0) >= 1000
			and (rewardItems[3].number or 0) >= 1000 do
			table.remove(rewardItems, 1)
		end

		return rewardItems
	end

	local function cleanCandidateName(value)
		local name = cleanGuiText(value)
		if name == "" then return nil end

		local lower = string.lower(name)
		local genericNames = {
			["frame"] = true,
			["imagelabel"] = true,
			["imagebutton"] = true,
			["textlabel"] = true,
			["textbutton"] = true,
			["textbox"] = true,
			["uicorner"] = true,
			["uistroke"] = true,
			["reward"] = true,
			["rewards"] = true,
			["item"] = true,
			["icon"] = true,
			["amount"] = true,
			["quantity"] = true,
			["count"] = true,
			["label"] = true,
			["background"] = true,
			["container"] = true,
			["slot"] = true,
			["inner"] = true,
			["outer"] = true,
			["border"] = true,
			["outline"] = true,
			["shadow"] = true,
			["glow"] = true,
			["stroke"] = true,
			["gradient"] = true,
			["star"] = true,
			["rarity"] = true,
			["check"] = true,
			["checkmark"] = true,
			["tick"] = true,
			["mark"] = true,
			["selected"] = true,
			["enabled"] = true,
			["disabled"] = true,
			["button"] = true,
			["hover"] = true,
            ["main"] = true,
            ["root"] = true,
            ["content"] = true,
            ["holder"] = true,
            ["perk"] = true,
            ["drop"] = true,
            ["common perk"] = true,
            ["rare perk"] = true,
            ["epic perk"] = true,
            ["legendary perk"] = true,
            ["mythic perk"] = true,
            ["inventory"] = true,
            ["equipment"] = true,
            ["market"] = true,
            ["rankings"] = true,
            ["regiment"] = true,
            ["battlepass"] = true,
            ["missions"] = true,
            ["quests"] = true,
			["shine"] = true,
			["sparkle"] = true,
		}

		if genericNames[lower] or isStandardResultText(lower) then
			return nil
		end

        -- Reject structural GUI/object ids such as "2_1", "3-2", "1_4".
        if string.match(lower, "^%d+[_%-]%d+$")
            or string.match(lower, "^%d+[_%-]%d+[_%-]%d+$")
            or string.match(lower, "^slot[_%-]?%d+$")
            or string.match(lower, "^item[_%-]?%d+$") then
            return nil
        end

        -- Names made mostly from digits/underscores are never useful reward names.
        local strippedStructure = string.gsub(lower, "[%d_%-%s]", "")
        if strippedStructure == "" then
            return nil
        end
		if string.len(name) <= 1 then
			return nil
		end
		if string.find(lower, "roblox", 1, true) or string.find(lower, "rbxasset", 1, true) then
			return nil
		end

		return name
	end

	local function rarityNameFromText(value)
		local lower = string.lower(tostring(value or ""))
		if string.find(lower, "mythic", 1, true) then return "Mythic" end
		if string.find(lower, "legendary", 1, true) then return "Legendary" end
		if string.find(lower, "epic", 1, true) then return "Epic" end
		if string.find(lower, "rare", 1, true) then return "Rare" end
		if string.find(lower, "common", 1, true) then return "Common" end
		return nil
	end


    V914WebhookRarity = V914WebhookRarity or {
        Cache = nil,
    }

    function V914WebhookRarity.LoadAuthoritative()
        if type(V914WebhookRarity.Cache) == "table" then
            return V914WebhookRarity.Cache
        end

        local output = {}
        local storage = game:GetService("ReplicatedStorage")
            :FindFirstChild("Modules")
        storage = storage and storage:FindFirstChild("Storage")

        for _, moduleName in ipairs({"Perks", "Artifacts"}) do
            local module = storage and storage:FindFirstChild(moduleName)
            if module and module:IsA("ModuleScript") then
                local ok, data = pcall(require, module)
                if ok and type(data) == "table" then
                    for _, rarity in ipairs({"Common", "Rare", "Epic", "Legendary", "Mythic"}) do
                        local bucket = data[rarity]
                        if type(bucket) == "table" then
                            for itemName in pairs(bucket) do
                                output[string.lower(tostring(itemName))] = {
                                    rarity = rarity,
                                    category = moduleName == "Perks" and "Perk" or "Artifact",
                                }
                            end
                        end
                    end
                end
            end
        end

        V914WebhookRarity.Cache = output
        return output
    end

    function V914WebhookRarity.Get(name)
        return V914WebhookRarity.LoadAuthoritative()[
            string.lower(tostring(name or ""))
        ]
    end

	local function inspectRewardRarity(numberItem)
		local object = numberItem.object
		if not object then return nil end

		local container = object.Parent
		for _ = 1, 5 do
			if not container then break end

			local fromName = rarityNameFromText(container.Name)
			if fromName then return fromName end

			for _, descendant in ipairs(container:GetDescendants()) do
				local nameRarity = rarityNameFromText(descendant.Name)
				if nameRarity then return nameRarity end
                if descendant:IsA("TextLabel") or descendant:IsA("TextButton") then
                    local textRarity = rarityNameFromText(descendant.Text)
                    if textRarity then return textRarity end
                end
                for _, key in ipairs({"Rarity", "Tier", "Quality"}) do
                    local value = descendant:GetAttribute(key)
                    local attributeRarity = rarityNameFromText(value)
                    if attributeRarity then return attributeRarity end
                end
			end

			container = container.Parent
		end

		return nil
	end

	local function findNearbyRewardText(numberItem, items)
		if type(items) ~= "table" then return nil end

		local bestText = nil
		local bestScore = math.huge

		for _, item in ipairs(items) do
			if item ~= numberItem and not item.number then
				local candidate = cleanCandidateName(item.text)
				if candidate then
					local dx = math.abs((item.x or 0) - (numberItem.x or 0))
					local dy = math.abs((item.y or 0) - (numberItem.y or 0))
					if dx <= 110 and dy <= 85 then
						local score = dx + dy * 1.4
						if score < bestScore then
							bestScore = score
							bestText = candidate
						end
					end
				end
			end
		end

		return bestText
	end


    local RewardHoverCache = setmetatable({}, {__mode = "k"})
    local RewardEnvironment = (type(getgenv) == "function" and getgenv()) or _G
    RewardEnvironment.SliceHubRewardAssetNames = type(RewardEnvironment.SliceHubRewardAssetNames) == "table"
        and RewardEnvironment.SliceHubRewardAssetNames or {}
    local RewardAssetNameCache = RewardEnvironment.SliceHubRewardAssetNames
    local ResultCurrencyAssetIds = {
        ["15296242924"] = true, -- EXP
        ["15147178963"] = true, -- Gold
        ["15147184586"] = true, -- Gems
    }

    local function rewardAssetIdFromTile(tile)
        if not tile then return nil end

        local bestId = nil
        local bestScore = -math.huge
        local objects = {tile}
        for _, descendant in ipairs(tile:GetDescendants()) do
            if descendant:IsA("ImageLabel") or descendant:IsA("ImageButton") then
                objects[#objects + 1] = descendant
            end
        end

        for _, object in ipairs(objects) do
            if object:IsA("ImageLabel") or object:IsA("ImageButton") then
                local assetId = string.match(tostring(object.Image or ""), "(%d+)")
                if assetId then
                    local lowerName = string.lower(tostring(object.Name or ""))
                    local parentName = object.Parent and string.lower(tostring(object.Parent.Name or "")) or ""
                    local score = 0
                    if lowerName == "icon" then score += 150 end
                    if parentName == "inner" then score += 35 end
                    if string.find(lowerName, "check", 1, true)
                        or string.find(lowerName, "stroke", 1, true)
                        or string.find(lowerName, "gradient", 1, true)
                        or string.find(lowerName, "background", 1, true)
                        or string.find(lowerName, "fade", 1, true) then
                        score -= 120
                    end
                    pcall(function()
                        if object.Visible then score += 8 end
                        if object.ImageTransparency < 0.95 then score += 5 end
                    end)
                    if score > bestScore then
                        bestScore = score
                        bestId = assetId
                    end
                end
            end
        end

        return bestId
    end

    local function rememberRewardAssetName(tile, name)
        local candidate = cleanCandidateName(name)
        local assetId = rewardAssetIdFromTile(tile)
        if candidate and assetId then
            RewardAssetNameCache[assetId] = candidate
        end
        return candidate
    end

    local RewardAttributePriority = {
        "PerkName",
        "RewardName",
        "ItemName",
        "DisplayName",
        "TraitName",
        "DropName",
        "Perk",
        "Item",
        "Title",
    }

    local function findRewardTileContainer(numberItem)
        local object = numberItem and numberItem.object
        if not object then return nil end

        local best = nil
        local bestArea = math.huge
        local node = object.Parent

        for _ = 1, 6 do
            if not node then break end

            if node:IsA("GuiObject") then
                local size = node.AbsoluteSize
                local area = size.X * size.Y

                if size.X >= 24 and size.X <= 220
                    and size.Y >= 24 and size.Y <= 220
                    and area < bestArea then

                    local hasImage = false
                    for _, descendant in ipairs(node:GetDescendants()) do
                        if descendant:IsA("ImageLabel") or descendant:IsA("ImageButton") then
                            hasImage = true
                            break
                        end
                    end

                    if hasImage then
                        best = node
                        bestArea = area
                    end
                end
            end

            node = node.Parent
        end

        return best or object.Parent
    end

    local function rewardNameFromMetadata(container)
        if not container then return nil end

        local objects = {container}
        for _, descendant in ipairs(container:GetDescendants()) do
            objects[#objects + 1] = descendant
        end

        for _, object in ipairs(objects) do
            local attributes = {}
            pcall(function()
                attributes = object:GetAttributes()
            end)

            for _, key in ipairs(RewardAttributePriority) do
                local candidate = cleanCandidateName(attributes[key])
                if candidate then return candidate end
            end

            for _, value in pairs(attributes) do
                local candidate = cleanCandidateName(value)
                if candidate then return candidate end
            end

            if object:IsA("StringValue") then
                local candidate = cleanCandidateName(object.Value)
                if candidate then return candidate end
            elseif object:IsA("ObjectValue") and object.Value then
                local candidate = cleanCandidateName(object.Value.Name)
                if candidate then return candidate end
            end
        end

        return nil
    end

    local function visibleTextSnapshot()
        local snapshot = {}
        for _, object in ipairs(playerGui:GetDescendants()) do
            if screenGui and object:IsDescendantOf(screenGui) then
                continue
            end

            local value = getTextFromObject(object)
            if value and value ~= "" and isVisibleTextObject(object) then
                snapshot[value] = true
            end
        end
        return snapshot
    end

    local function scoreTooltipCandidate(textValue, object, cursorX, cursorY)
        local candidate = cleanCandidateName(textValue)
        if not candidate then return nil, -math.huge end

        local lower = string.lower(candidate)
        local length = string.len(candidate)
        local score = 0

        if length <= 32 then score += 20 else score -= math.min(40, length - 32) end
        if length >= 3 and length <= 18 then score += 12 end
        if string.find(lower, "chance", 1, true) then score -= 30 end
        if string.find(lower, "rarity", 1, true) then score -= 25 end
        if string.find(lower, "%", 1, true) then score -= 25 end

        -- Result tooltips are normally close to the hovered reward tile.
        if object and object:IsA("GuiObject") then
            local pos = object.AbsolutePosition
            local size = object.AbsoluteSize
            local centerX = pos.X + size.X * 0.5
            local centerY = pos.Y + size.Y * 0.5
            local distance = math.sqrt(
                (centerX - (cursorX or centerX)) ^ 2
                + (centerY - (cursorY or centerY)) ^ 2
            )

            if distance <= 220 then
                score += 45
            elseif distance <= 420 then
                score += 18
            else
                score -= math.min(35, distance / 50)
            end

            local node = object
            for _ = 1, 5 do
                if not node then break end
                local nodeName = string.lower(tostring(node.Name or ""))
                if string.find(nodeName, "tooltip", 1, true)
                    or string.find(nodeName, "hover", 1, true)
                    or string.find(nodeName, "perk", 1, true)
                    or string.find(nodeName, "reward", 1, true)
                    or string.find(nodeName, "info", 1, true) then
                    score += 18
                    break
                end
                node = node.Parent
            end
        end

        -- Names like CRIPPLE / GEAR BEGINNER are commonly rendered uppercase.
        local letters = string.gsub(candidate, "[^%a]", "")
        if letters ~= "" and letters == string.upper(letters) then
            score += 10
        end

        return candidate, score
    end

    local function rewardNameFromHover(container)
        -- V9.8.2.9.8: deliberately disabled. Reward resolution must never move the
        -- cursor, hover tiles, fire MouseEnter/MouseLeave, or synthesize clicks.
        return nil
    end

    local function findObtainedY(items)
        for _, item in ipairs(items or {}) do
            local lower = string.lower(tostring(item.text or ""))
            if lower == "obtained" or string.find(lower, "obtained", 1, true) then
                return tonumber(item.y) or 0
            end
        end
        return nil
    end

    local function tileQuantity(tile)
        if not tile then return 1 end

        local best = nil
        for _, object in ipairs(tile:GetDescendants()) do
            local value = getTextFromObject(object)
            if value and value ~= "" and isVisibleTextObject(object) then
                local cleaned = cleanGuiText(value)
                local number = parseNumber(cleaned)

                if number and number > 0 and number <= 999 then
                    -- Reward tile count labels are normally tiny values.
                    if not best or number < best then
                        best = number
                    end
                end
            end
        end

        return best or 1
    end

    local function collectRewardTiles(root, items)
        if not root then return {} end

        local exactItems = resolvePath(playerGui, {"Interface", "Rewards", "Main", "Info", "Main", "Items"})
        if exactItems then
            local exactTiles = {}
            for _, slot in ipairs(exactItems:GetChildren()) do
                if slot:IsA("GuiObject") and slot.Visible then
                    local inner = resolvePath(slot, {"Main", "Inner"})
                    local icon = inner and inner:FindFirstChild("Icon")
                    if icon and (icon:IsA("ImageLabel") or icon:IsA("ImageButton")) then
                        exactTiles[#exactTiles + 1] = slot
                    end
                end
            end
            table.sort(exactTiles, function(a, b)
                local ay = a.AbsolutePosition.Y
                local by = b.AbsolutePosition.Y
                if math.abs(ay - by) > 10 then return ay < by end
                return a.AbsolutePosition.X < b.AbsolutePosition.X
            end)
            if #exactTiles > 0 then return exactTiles end
        end

        local obtainedY = findObtainedY(items) or 0
        local candidates = {}

        for _, object in ipairs(root:GetDescendants()) do
            if object:IsA("GuiObject")
                and object.Visible
                and object.AbsoluteSize.X >= 35
                and object.AbsoluteSize.X <= 180
                and object.AbsoluteSize.Y >= 35
                and object.AbsoluteSize.Y <= 180 then

                local hasIcon = false
                for _, descendant in ipairs(object:GetDescendants()) do
                    if descendant:IsA("ImageLabel")
                        or descendant:IsA("ImageButton") then
                        hasIcon = true
                        break
                    end
                end

                if hasIcon then
                    local centerY = object.AbsolutePosition.Y + object.AbsoluteSize.Y * 0.5
                    if centerY > obtainedY + 12 then
                        candidates[#candidates + 1] = object
                    end
                end
            end
        end

        -- Keep smallest leaf-like tile candidates.
        table.sort(candidates, function(a, b)
            local areaA = a.AbsoluteSize.X * a.AbsoluteSize.Y
            local areaB = b.AbsoluteSize.X * b.AbsoluteSize.Y
            return areaA < areaB
        end)

        local deduped = {}
        for _, candidate in ipairs(candidates) do
            local overlapsExisting = false

            for _, existing in ipairs(deduped) do
                if candidate:IsDescendantOf(existing)
                    or existing:IsDescendantOf(candidate) then
                    overlapsExisting = true
                    break
                end

                local a = candidate.AbsolutePosition
                local as = candidate.AbsoluteSize
                local b = existing.AbsolutePosition
                local bs = existing.AbsoluteSize

                local centerAX = a.X + as.X * 0.5
                local centerAY = a.Y + as.Y * 0.5
                local centerBX = b.X + bs.X * 0.5
                local centerBY = b.Y + bs.Y * 0.5

                if math.abs(centerAX - centerBX) < 12
                    and math.abs(centerAY - centerBY) < 12 then
                    overlapsExisting = true
                    break
                end
            end

            if not overlapsExisting then
                deduped[#deduped + 1] = candidate
            end
        end

        -- Group every reward row below OBTAINED. V5.2 only returned the widest
        -- row, which dropped lower-row rewards from the webhook scan.
        local rows = {}
        for _, tile in ipairs(deduped) do
            local centerY = tile.AbsolutePosition.Y + tile.AbsoluteSize.Y * 0.5
            local placed = false

            for _, row in ipairs(rows) do
                if math.abs(row.CenterY - centerY) <= 28 then
                    row.Tiles[#row.Tiles + 1] = tile
                    row.CenterY = (row.CenterY * (row.Count or 1) + centerY) / ((row.Count or 1) + 1)
                    row.Count = (row.Count or 1) + 1
                    placed = true
                    break
                end
            end

            if not placed then
                rows[#rows + 1] = {CenterY = centerY, Count = 1, Tiles = {tile}}
            end
        end

        table.sort(rows, function(a, b) return a.CenterY < b.CenterY end)

        local allTiles = {}
        for _, row in ipairs(rows) do
            table.sort(row.Tiles, function(a, b)
                return a.AbsolutePosition.X < b.AbsolutePosition.X
            end)
            for _, tile in ipairs(row.Tiles) do
                allTiles[#allTiles + 1] = tile
            end
        end

        return allTiles
    end

    local function findRewardNameForTile(tile)
        if not tile then return nil end

        local metadataName = rewardNameFromMetadata(tile)
        if metadataName then
            return rememberRewardAssetName(tile, metadataName)
        end

        local assetId = rewardAssetIdFromTile(tile)
        local cachedName = assetId and cleanCandidateName(RewardAssetNameCache[assetId]) or nil
        if cachedName then return cachedName end

        -- Hidden/preloaded labels inside the exact result slot are safe to read and
        -- often already contain the tooltip title before any hover occurs.
        for _, descendant in ipairs(tile:GetDescendants()) do
            if descendant.Name ~= "Quantity" then
                local textValue = getTextFromObject(descendant)
                if textValue and textValue ~= "" then
                    local candidate = cleanCandidateName(textValue)
                    if candidate then
                        return rememberRewardAssetName(tile, candidate)
                    end
                end
            end
        end

        if assetId then
            return "Unresolved Reward [" .. tostring(assetId) .. "]"
        end

        local rarity = inspectRewardRarity({
            object = tile,
            x = tile.AbsolutePosition.X,
            y = tile.AbsolutePosition.Y,
        })
        if rarity then return "Unresolved " .. rarity .. " Reward" end
        return nil
    end

    local function tileLooksLikeResource(tile)
        if not tile then return false end
        local assetId = rewardAssetIdFromTile(tile)
        if assetId and ResultCurrencyAssetIds[assetId] then return true end
        local keywords = {"exp", "experience", "gold", "money", "cash", "gem"}
        local function matches(value)
            local lower = string.lower(tostring(value or ""))
            for _, keyword in ipairs(keywords) do
                if string.find(lower, keyword, 1, true) then return true end
            end
            return false
        end

        if matches(tile.Name) then return true end
        for _, object in ipairs(tile:GetDescendants()) do
            if matches(object.Name) then return true end
            local value = getTextFromObject(object)
            if value and matches(value) then return true end
        end
        return false
    end

    local function extractRewardsFromTiles(root, items)
        local tiles = collectRewardTiles(root, items)
        if #tiles <= 2 then return {} end

        local drops = {}

        for index, tile in ipairs(tiles) do
            -- Result layouts always begin with EXP and Gold. Gems are optional;
            -- only skip later resource tiles when their metadata/text actually says so.
            local resourceTile = index <= 2 or tileLooksLikeResource(tile)
            if not resourceTile then
                local name = findRewardNameForTile(tile) or "Unknown reward"
                local quantity = tileQuantity(tile)

                drops[#drops + 1] = {
                    name = name,
                    quantity = quantity,
                }
            end
        end

        return drops
    end

    local function findRewardNameNearNumber(numberItem, items)
        local object = numberItem.object
        if not object then return nil end

        local tile = findRewardTileContainer(numberItem)

        local metadataName = rewardNameFromMetadata(tile)
        if metadataName then return metadataName end

        -- V9.8.2.9.8: no cursor movement or tooltip probing.

        local nearbyText = findNearbyRewardText(numberItem, items)
        if nearbyText then return nearbyText end

        local container = tile or object.Parent
        for _ = 1, 4 do
            if not container then break end

            for _, descendant in ipairs(container:GetDescendants()) do
                if descendant ~= object then
                    local textValue = getTextFromObject(descendant)
                    if textValue and textValue ~= "" then
                        local candidate = cleanCandidateName(textValue)
                        if candidate then return candidate end
                    end
                end
            end

            for _, descendant in ipairs(container:GetDescendants()) do
                if descendant:IsA("ImageLabel") or descendant:IsA("ImageButton") then
                    local candidate = cleanCandidateName(descendant.Name)
                    if candidate then return candidate end
                end
            end

            local containerName = cleanCandidateName(container.Name)
            if containerName then return containerName end
            container = container.Parent
        end

        local rarity = inspectRewardRarity(numberItem)
        if rarity then
            return "Unknown " .. rarity .. " reward"
        end

        return "Unknown reward"
    end

	local function extractRewards(root, items)
		local rewardNumberItems = collectRewardNumberItems(items)
		local rewards = {
			exp = 0,
			gold = 0,
			gems = 0,
			drops = {},
		}

		if #rewardNumberItems >= 3 then
			rewards.exp = rewardNumberItems[1].number or 0
			rewards.gold = rewardNumberItems[2].number or 0
			rewards.gems = rewardNumberItems[3].number or 0

            local tileDrops = extractRewardsFromTiles(root, items)
            if #tileDrops > 0 then
                rewards.drops = tileDrops
                return rewards
            end

			for index = 4, #rewardNumberItems do
				local item = rewardNumberItems[index]
				local quantity = tonumber(item.number) or 0
				if quantity > 0 then
					local dropName = findRewardNameNearNumber(item, items) or "Unknown drop"
					table.insert(rewards.drops, {
						name = dropName,
						quantity = quantity,
					})
				end
			end
		else
			-- Fallback for alternate result UIs that label EXP/Gold/Gems directly.
			rewards.exp = findMetricValue(items, {"exp", "xp", "experience"})
			rewards.gold = findMetricValue(items, {"gold", "money", "cash"})
			rewards.gems = findMetricValue(items, {"gems", "gem"})
		end

		return rewards
	end


    V100WebhookRarityFromTile = function(tile)
        if not tile or not tile:IsA("GuiObject") then
            return nil
        end

        local function explicitFromObject(object)
            if not object then
                return nil
            end

            local byName =
                rarityNameFromText(object.Name)
            if byName then
                return byName
            end

            local attributes = {}
            pcall(function()
                attributes = object:GetAttributes()
            end)

            for _, key in ipairs({
                "Rarity",
                "Tier",
                "Grade",
                "ItemRarity",
                "PerkRarity",
                "ArtifactRarity",
            }) do
                local rarity =
                    rarityNameFromText(attributes[key])
                if rarity then
                    return rarity
                end
            end

            if object:IsA("TextLabel")
                or object:IsA("TextButton") then

                local rarity =
                    rarityNameFromText(object.Text)
                if rarity then
                    return rarity
                end
            end

            return nil
        end

        local explicit =
            explicitFromObject(tile)
        if explicit then
            return explicit
        end

        for _, object in ipairs(
            tile:GetDescendants()
        ) do
            explicit =
                explicitFromObject(object)

            if explicit then
                return explicit
            end
        end

        local rarityObject =
            resolvePath(
                tile,
                {"Main", "Inner", "Quantity"}
            )
            or resolvePath(
                tile,
                {"Main", "Inner", "Icon"}
            )
            or tile

        return inspectRewardRarity({
            object = rarityObject,
            x = tile.AbsolutePosition.X,
            y = tile.AbsolutePosition.Y,
        })
    end

    -- Pairs the trusted S_Rewards item sequence with passive result-tile rarity
    -- evidence. Names always remain server-authoritative; uncertain rarity is
    -- simply omitted rather than guessed.
    V100ApplyWebhookRarities = function(root, rewards)
        if type(rewards) ~= "table" or #rewards == 0 then
            return rewards
        end

        local tiles = collectRewardTiles(root, {})
        local itemTiles = {}

        for index, tile in ipairs(tiles) do
            if index > 2 and not tileLooksLikeResource(tile) then
                itemTiles[#itemTiles + 1] = tile
            end
        end

        local output = {}
        local byKey = {}
        local tileIndex = 1

        for _, reward in ipairs(rewards) do
            local name = cleanCandidateName(reward.name)
            local quantity = math.max(
                1,
                math.floor((tonumber(reward.quantity) or 1) + 0.5)
            )

            if name then
                local authoritative = V914WebhookRarity.Get(name)
                if authoritative then
                    reward.category = authoritative.category
                    reward.rarity = authoritative.rarity
                end
                local categoryLower = string.lower(tostring(reward.category or ""))
                local isPerk = categoryLower == "perk" or categoryLower == "perks"
                local isArtifact = categoryLower == "artifact" or categoryLower == "artifacts"

                for _ = 1, quantity do
                    -- Consume every server-ordered item tile so later Perks stay
                    -- aligned, but only Perks may inherit Common/Rare/Epic/etc.
                    local tile = itemTiles[tileIndex]
                    tileIndex += 1

                    local rarity = nil
                    if isPerk or isArtifact then
                        rarity = rarityNameFromText(reward.rarity)
                        if not rarity and tile and type(V100WebhookRarityFromTile) == "function" then
                            rarity = V100WebhookRarityFromTile(tile)
                        end
                        rarity = rarityNameFromText(rarity) or "Unknown"
                    end

                    local key = string.lower(name) .. "|" .. string.lower(tostring(rarity or ""))
                    local entry = byKey[key]

                    if not entry then
                        entry = {
                            name = name,
                            quantity = 0,
                            category = reward.category,
                            id = reward.id,
                            rarity = rarity,
                            source = reward.source or "S_Rewards/Get",
                            confidence = reward.confidence or 1.0,
                        }
                        byKey[key] = entry
                        output[#output + 1] = entry
                    end

                    entry.quantity += 1
                end
            end
        end

        return #output > 0 and output or rewards
    end

	local function formatDrops(drops)
		if type(drops) ~= "table" or #drops == 0 then
			return "None detected"
		end

		local totals = {}
		local order = {}
		for _, drop in ipairs(drops) do
			local name = tostring(drop.name or "Unknown drop")
			if name == "" then name = "Unknown drop" end
            local categoryLower = string.lower(tostring(drop.category or ""))
            local classified = categoryLower == "perk" or categoryLower == "perks"
                or categoryLower == "artifact" or categoryLower == "artifacts"
            local rarity = classified and (rarityNameFromText(drop.rarity) or "Unknown") or nil
            local displayName = rarity and (name .. " (" .. rarity .. ")") or name
			local quantity = tonumber(drop.quantity) or 0
			if quantity > 0 then
				if not totals[displayName] then
					table.insert(order, displayName)
					totals[displayName] = 0
				end
				totals[displayName] += quantity
			end
		end

		if #order == 0 then
			return "None detected"
		end

		local lines = {}
		for _, name in ipairs(order) do
			table.insert(lines, "• **" .. name .. "** x" .. tostring(totals[name]))
		end

		return table.concat(lines, "\n")
	end

	local function sanitizeDrops(drops)
		local clean = {}
		local seen = {}
		for _, drop in ipairs(type(drops) == "table" and drops or {}) do
			local name = cleanCandidateName(drop.name)
			local lower = string.lower(tostring(name or ""))
			local quantity = math.max(0, math.floor((tonumber(drop.quantity) or 0) + 0.5))
			local untrusted = name == nil
				or lower == "unknown drop"
				or lower == "unknown reward"
				or string.find(lower, "unknown ", 1, true) == 1
                or string.find(lower, "unresolved reward", 1, true) == 1
                or string.find(lower, "unresolved drop", 1, true) == 1
                or string.find(lower, "unresolved item", 1, true) == 1

			if not untrusted and quantity > 0 then
                local categoryLower = string.lower(tostring(drop.category or ""))
                local isPerk = categoryLower == "perk" or categoryLower == "perks"
                local rarity = isPerk and rarityNameFromText(drop.rarity) or nil
				local key = string.lower(name) .. "|" .. string.lower(tostring(rarity or ""))
				if not seen[key] then
					seen[key] = {
                        name = name,
                        quantity = 0,
                        rarity = rarity,
                        category = drop.category,
                        source = drop.source,
                        confidence = drop.confidence,
                    }
					clean[#clean + 1] = seen[key]
				end
				seen[key].quantity += quantity
			end
		end
		return clean
	end

	local function rewardSnapshotSignature(data)
		local parts = {
			tostring(math.max(0, tonumber(data and data.exp) or 0)),
			tostring(math.max(0, tonumber(data and data.gold) or 0)),
			tostring(math.max(0, tonumber(data and data.gems) or 0)),
		}

        local extraKeys = {}
        for key, value in pairs(type(data and data.extraCurrencies) == "table" and data.extraCurrencies or {}) do
            if tonumber(value) ~= nil then extraKeys[#extraKeys + 1] = tostring(key) end
        end
        table.sort(extraKeys)
        for _, key in ipairs(extraKeys) do
            parts[#parts + 1] = "currency:" .. string.lower(key)
                .. "=" .. tostring(tonumber(data.extraCurrencies[key]) or 0)
        end

		for _, drop in ipairs(data and data.drops or {}) do
			parts[#parts + 1] = string.lower(tostring(drop.name or ""))
                .. ":" .. string.lower(tostring(drop.rarity or ""))
				.. "=" .. tostring(tonumber(drop.quantity) or 0)
		end

        for _, chest in ipairs(type(data and data.chests) == "table" and data.chests or {}) do
            parts[#parts + 1] = "chest:" .. string.lower(tostring(chest.name or ""))
                .. "=" .. tostring(tonumber(chest.quantity) or 1)
        end

		return table.concat(parts, "|")
	end

	local function containsRareNamedDrop(drops)
		for _, drop in ipairs(type(drops) == "table" and drops or {}) do
			local lowerName = string.lower(tostring(drop.name or ""))
            local category = string.lower(tostring(drop.category or ""))
            local rarity = rarityNameFromText(drop.rarity)

            local isSerum = category == "serum"
                or category == "serums"
                or string.find(lowerName, "serum", 1, true) ~= nil

            local mythicClassified =
                rarity == "Mythic"
                and (
                    category == "perk"
                    or category == "perks"
                    or category == "artifact"
                    or category == "artifacts"
                )

            if isSerum or mythicClassified then
				return true
			end
		end
		return false
	end

	local function collectUniqueLines(items)
		local lines = {}
		local seen = {}

		for _, item in ipairs(items) do
			local text = item.text
			if text ~= "" and not seen[text] then
				seen[text] = true
				table.insert(lines, text)
			end
		end

		return lines
	end

	local function makeSignature(resultType, lines)
		local signature = resultType
		for index = 1, math.min(#lines, 12) do
			signature = signature .. "|" .. lines[index]
		end
		return signature
	end

	local function trimForDiscord(text, limit)
		text = tostring(text or "")
		limit = limit or 1000
		if string.len(text) <= limit then return text end
		return string.sub(text, 1, limit - 3) .. "..."
	end

	local function detectResultType(statusLower, lines)
		local joined = string.lower(table.concat(lines, " "))
		local source = tostring(statusLower or "") .. " " .. joined

		if string.find(source, "failed", 1, true) or string.find(source, "defeat", 1, true) then
			return "failed"
		end
		if string.find(source, "complete", 1, true) or string.find(source, "victory", 1, true) then
			return "completed"
		end
		return "result"
	end

    function V3ResultGuard.PanelStarting(root)
        if not root then return false end

        for _, object in ipairs(root:GetDescendants()) do
            local value = getTextFromObject(object)
            if value and value ~= "" and isVisibleTextObject(object) then
                local lower = string.lower(value)
                if string.find(lower, "starting", 1, true)
                    or string.find(lower, "loading mission", 1, true)
                    or string.find(lower, "teleporting", 1, true) then
                    return true
                end
            end
        end

        return false
    end

    function V3ResultGuard.ActiveMissionEvidence()
        if V4RaidDirector and V4RaidDirector.Enabled == true then
            return true
        end

        local alive = 0
        pcall(function()
            alive = getCachedAliveTitanCount()
        end)

        if alive > 0 then
            return true
        end

        -- Objective history alone is weak evidence; require a live progress row.
        for _, key in ipairs(MissionObjectiveHistory.Order) do
            local value = tostring(MissionObjectiveHistory.LatestByKey[key] or "")
            if string.match(value, "%[%s*%d+%s*/%s*[1-9]%d*%s*%]") then
                return true
            end
        end

        return false
    end

    function V3ResultGuard.ValidData(data)
        if type(data) ~= "table" then return false end
        if tostring(data.timeTaken or "Unknown") == "Unknown" then return false end

        -- A real result panel can be a 0-kill failure, but it must at least have
        -- a populated result clock and a recognized result type.
        return data.resultType == "completed"
            or data.resultType == "failed"
            or data.resultType == "result"
    end

    function V3ResultGuard.ResetTaskHistoryForRun()
        MissionObjectiveHistory.Order = {}
        MissionObjectiveHistory.LatestByKey = {}
        MissionObjectiveHistory.LastUpdatedAt = 0
    end

    function V9146WebhookShadowbanStatus()
        local deadline = os.clock() + 1.20

        repeat
            local blacklisted = nil
            local exploiter = nil

            pcall(function()
                blacklisted =
                    player:GetAttribute("Blacklisted")
                exploiter =
                    player:GetAttribute("Exploiter")
            end)

            if blacklisted == true
                or exploiter == true then
                return "True"
            end

            if blacklisted == false
                and exploiter == false then
                return "False"
            end

            if os.clock() >= deadline then
                break
            end

            task.wait(0.15)
        until false

        -- The game does not replicate these attributes in every place.
        -- Missing evidence is omitted instead of shown as Unknown.
        return nil
    end

	local function createMissionResultEmbed(data)
		local isFailed = data.resultType == "failed"
        local isRaid = tostring(data.runType or "Mission") == "Raid"
		local title = isFailed
            and (isRaid and "❌ Raid Failed" or "❌ Mission Failed")
            or (isRaid and "✅ Raid Completed" or "✅ Mission Completed")
		local color = isFailed and 15158332 or 3066993

		local rewardLine = SRewardsWebhookV1.FormatCurrencyLine(data, formatNumber)
        local chestLine = SRewardsWebhookV1.FormatChests(data.chests)

		local embed = {
			title = title,
			color = color,
			timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
			fields = {},
			footer = {text = "SliceHub V" .. tostring(BUILD and BUILD.Version or "9.8.3.4.5") .. " • Server Reward Snapshot"},
			pingRare = containsRareNamedDrop(data.drops),
		}

        table.insert(embed.fields, {
            name = isRaid and "⚔️ Raid" or "🧭 Mission",
            value = trimForDiscord(isRaid and ((data.raidName or "Unknown raid") .. "\n" .. tostring(data.missionDisplay or "Unknown map")) or (data.missionDisplay or "Unknown mission"), 1000),
            inline = false,
        })

        local shadowbanStatus =
            V9146WebhookShadowbanStatus()

        if shadowbanStatus ~= nil then
            table.insert(embed.fields, {
                name = "🛡️ Shadowban",
                value = "**"
                    .. shadowbanStatus
                    .. "**",
                inline = true,
            })
        end

		table.insert(embed.fields, {
			name = "⏱️ Performance",
			value = "Time **" .. tostring(data.timeTaken or "Unknown")
				.. "**  •  Kills **" .. formatNumber(data.titanKills or 0)
				.. "**  •  Damage **" .. formatNumber(data.damageDealt or 0)
				.. "**  •  Crits **" .. formatNumber(data.criticalHits or 0) .. "**",
			inline = false,
		})

		table.insert(embed.fields, {
			name = "💰 Verified Rewards",
			value = rewardLine,
			inline = false,
		})

        local queueActive, queueState = V51QueueRuntime.IsActive()
        if isRaid and queueActive and type(queueState) == "table" then
            table.insert(embed.fields, {
                name = "🔁 Raid Queue",
                value = "Entry " .. tostring(queueState.Index or 1) .. "/" .. tostring(type(queueState.Entries) == "table" and #queueState.Entries or 0)
                    .. " • Entry progress " .. tostring(queueState.EntryDone or 0)
                    .. " • Total clears " .. tostring(queueState.TotalCompleted or 0)
                    .. " • Failures " .. tostring(queueState.TotalFailed or 0),
                inline = false,
            })
        end

        table.insert(embed.fields, {
            name = isRaid and "📋 Raid Objectives" or "📋 Mission Tasks",
            value = trimForDiscord(data.objectives or "No tasks detected", 1000),
            inline = false,
        })

		table.insert(embed.fields, {
			name = "🎁 Named Rewards",
			value = trimForDiscord(formatDrops(data.drops), 1000),
			inline = false,
		})

        if isRaid and chestLine then
            table.insert(embed.fields, {
                name = "🧰 Raid Chests",
                value = trimForDiscord(chestLine, 1000),
                inline = false,
            })
        end

		if WebhookConfig.includeRawDebug then
			local scannerDebug = ""
            if type(data.rewardScanner) == "table" then
                scannerDebug = "\n\nReward scanner:"
                    .. "\nSource: " .. tostring(data.rewardScanner.source or "Unknown")
                    .. "\nServer snapshot: " .. tostring(data.rewardScanner.serverSnapshot == true)
                    .. "\nServer named rewards: " .. tostring(data.rewardScanner.serverNamedRewards == true)
                    .. "\nInventory changes: " .. tostring(data.rewardScanner.inventoryChanges or 0)
                    .. "\nRelevant remote events: " .. tostring(data.rewardScanner.relevantRemoteEvents or 0)
                    .. "\nDump: " .. tostring(data.rewardScanner.path or data.rewardScanner.writeError or "session-only")
            end
			local rawText = table.concat(data.lines or {}, "\n")
				.. scannerDebug
				.. "\n\nRun recorder:\n" .. V94RunRecorder.Summary(10)
			if rawText ~= "" then
				table.insert(embed.fields, {
					name = "Raw GUI Debug",
					value = trimForDiscord(rawText, 1000),
					inline = false,
				})
			end
		end

		if WebhookConfig.enableStats then
			local statsOk, stats = pcall(getPlayerStats)
			if statsOk and type(stats) == "table" and stats.trusted == true then
				local statParts = {}
				if stats.level then table.insert(statParts, "**Level:** " .. tostring(stats.level)) end
				if stats.prestige then table.insert(statParts, "**Prestige:** " .. tostring(stats.prestige)) end
				if stats.gold then table.insert(statParts, "**Gold:** " .. tostring(stats.gold)) end
				if stats.gems then table.insert(statParts, "**Gems:** " .. tostring(stats.gems)) end
				if #statParts > 0 then
					table.insert(embed.fields, {
						name = "Player Stats",
						value = table.concat(statParts, " | "),
						inline = false,
					})
				end
			end
		end

		return embed
	end

	local function detectExplicitRunType(statusLower, lines, root)
        local sourceParts = {tostring(statusLower or ""), table.concat(lines or {}, " ")}

        local knownRewardsRoot = resolvePath(playerGui, {"Interface", "Rewards"})
        local scanRoot = knownRewardsRoot or root
        if scanRoot then
            local objects = {scanRoot}
            for _, object in ipairs(scanRoot:GetDescendants()) do
                objects[#objects + 1] = object
            end
            for _, object in ipairs(objects) do
                if (object:IsA("TextLabel") or object:IsA("TextButton"))
                    and isVisibleTextObject(object) then
                    local textValue = getTextFromObject(object)
                    if textValue and textValue ~= "" then
                        sourceParts[#sourceParts + 1] = textValue
                    end
                end
            end
        end

        local source = string.lower(table.concat(sourceParts, " "))

        -- A visible result title is authoritative. Mission wins precedence so a
        -- stale raid name/objective elsewhere in PlayerGui cannot relabel it.
        if string.find(source, "mission completed", 1, true)
            or string.find(source, "mission complete", 1, true)
            or string.find(source, "mission failed", 1, true)
            or string.find(source, "mission fail", 1, true) then
            return "Mission"
        end

        if string.find(source, "raid completed", 1, true)
            or string.find(source, "raid complete", 1, true)
            or string.find(source, "raid failed", 1, true)
            or string.find(source, "raid fail", 1, true) then
            return "Raid"
        end

        return nil
	end

	local function extractMissionResultData(root, statusLower)
		local items = getVisibleTextItems(root)
		local lines = collectUniqueLines(items)
		local resultType = detectResultType(statusLower, lines)
		local rewards = extractRewards(root, items)
		local trustedDrops = sanitizeDrops(rewards.drops)
        local runMeta = V3MissionIdentity.GetRunMetadataForWebhook()
        local explicitRunType = detectExplicitRunType(statusLower, lines, root)
        local replicatedRunType, replicatedRunSource =
            SRewardsWebhookV1.ResolveReplicatedRunType(ReplicatedStorage, workspace)
        local resolvedRunType = explicitRunType
            or replicatedRunType
            or tostring(runMeta.RunType or "Mission")
        local resolvedRaidName = resolvedRunType == "Raid" and runMeta.RaidName or nil
        local resolvedRaidChoice = resolvedRunType == "Raid" and runMeta.RaidChoice or ""

		return {
            runType = resolvedRunType,
            raidName = resolvedRaidName,
            difficulty = runMeta.Difficulty,
            raidChoice = resolvedRaidChoice,
            runTypeSource = explicitRunType and "VisibleResultTitle"
                or replicatedRunSource
                or "SavedLobbySelection",
			resultType = resultType,
			timeTaken = findClockValue(items),
			damageDealt = findMetricValue(items, {"damage dealt", "damage"}),
			titanKills = findMetricValue(items, {"titans killed", "titan killed", "titans", "titan"}),
			criticalHits = findMetricValue(items, {"critical hits", "critical", "crit"}),
			exp = rewards.exp,
			gold = rewards.gold,
			gems = rewards.gems,
			drops = trustedDrops,
			rewardSignature = table.concat({
				tostring(rewards.exp or 0),
				tostring(rewards.gold or 0),
				tostring(rewards.gems or 0),
				tostring(#trustedDrops),
			}, "|"),
            missionDisplay = V3MissionIdentity.GetMissionDisplayForWebhook(),
            objectives = V3MissionIdentity.GetMissionObjectiveSummary(),
			lines = lines,
		}
	end

	local function updateLastRunTracker(data)
		if type(data) ~= "table" then return end
		local outcome = tostring(data.resultType or "result")
		local kills = tonumber(data.titanKills) or 0
		local timeTaken = tostring(data.timeTaken or "Unknown")
		local damage = tonumber(data.damageDealt) or 0
		State.LastRunOutcome = outcome
		State.LastRunKills = kills
		State.LastRunTime = timeTaken
		State.LastRunSummary = string.format("%s | %d kills | %s | %s dmg", string.upper(outcome), kills, timeTaken, formatNumber(damage))
		if lastRunStatusLabel then
			lastRunStatusLabel.Text = "Last run: " .. State.LastRunSummary
		end
		refreshAutoMissionStatus()
		saveSettingsIfReady()
	end

	local function clearFinishedRunContext()
		MissionObjectiveHistory.Order = {}
		MissionObjectiveHistory.LatestByKey = {}
		MissionObjectiveHistory.LastUpdatedAt = 0
		MissionObjectiveHistory.SelectedObjective = nil
		MissionObjectiveHistory.SelectedMap = nil
		MissionObjectiveHistory.MetadataUpdatedAt = 0
		V3MissionIdentity.MapTracker.ObservedMap = nil
		V3MissionIdentity.MapTracker.ObservedAt = 0
	end

	local function sendMissionResultFromGui(root, statusLower)
        -- V9.4: poll until both the result identity and reward snapshot are stable.
        -- Never send the first half-populated animation frame.
        local data = nil
        local startedAt = os.clock()
        local lastRewardSnapshot = nil
        local stableRewardReads = 0

        repeat
            local refreshedRoot, refreshedStatus = findMissionResultRoot()
            root = refreshedRoot or root
            statusLower = refreshedStatus or statusLower

            if not root or V3ResultGuard.PanelStarting(root) then
                return false
            end

            data = extractMissionResultData(root, statusLower)
            if V3ResultGuard.ValidData(data) then
				local snapshot = rewardSnapshotSignature(data)
				if snapshot == lastRewardSnapshot then
					stableRewardReads += 1
				else
					lastRewardSnapshot = snapshot
					stableRewardReads = 1
				end

				V94Webhook.LastRewardSignature = snapshot
				V94Webhook.LastStableReads = stableRewardReads
				V94Webhook.Status = "VERIFYING RESULT • stable " .. tostring(stableRewardReads) .. "/2"

				if os.clock() - startedAt >= 0.80 and stableRewardReads >= 2 then
					data.rewardVerified = true
					break
				end
            end

			task.wait(0.22)
		until os.clock() - startedAt >= 4.2

        if not V3ResultGuard.ValidData(data) then
			V94Webhook.Status = "RESULT REJECTED • incomplete panel"
			V94RunRecorder.Record("RESULT_REJECTED", V94Webhook.Status)
            return false
        end

		data.rewardVerified = data.rewardVerified == true
		V94Webhook.Status = data.rewardVerified
			and "RESULT VERIFIED • stable reward snapshot"
			or "RESULT VERIFIED • reward stability timeout"

        -- V9.8.4: one exact getter call per real result screen. Capture and
        -- cache it before the passive scanner waits and before Auto Retry can
        -- transition away from the result panel.
        if WebhookConfig.rewardScannerEnabled ~= false then
            local serverCapture = SRewardsWebhookV1.Capture(playerGui, ReplicatedStorage)
            data.serverRewardCapture = serverCapture
            data.serverRewardsRaw = type(serverCapture) == "table" and serverCapture.raw or nil

            if SRewardsWebhookV1.Apply(data, serverCapture) then
                data.rewardVerified = true
                V94Webhook.Status = "RESULT VERIFIED • S_Rewards/Get snapshot"
                V94RunRecorder.Record("SERVER_REWARD_CAPTURE", V94Webhook.Status, {
                    state = serverCapture.state,
                    namedRewards = type(serverCapture.namedRewards) == "table"
                        and #serverCapture.namedRewards or 0,
                    chests = type(serverCapture.chests) == "table"
                        and #serverCapture.chests or 0,
                })
                print(
                    "[SliceHub V9.8.4][REWARDS] S_Rewards/Get captured",
                    tostring(serverCapture.state or "result"),
                    "named=" .. tostring(type(serverCapture.namedRewards) == "table" and #serverCapture.namedRewards or 0)
                )
            else
                V94RunRecorder.Record(
                    "SERVER_REWARD_CAPTURE_MISS",
                    tostring(type(serverCapture) == "table" and serverCapture.error or "capture unavailable")
                )
            end
        end

        if RewardScannerV1 and RewardScannerV1.Finalize then
            local scannerOk, scannerResult = pcall(RewardScannerV1.Finalize, root, statusLower, data)
            if scannerOk and type(scannerResult) == "table" then
                data.rewardScanner = scannerResult
                data.rewardDumpPath = scannerResult.path

                local strongDrops = {}
                for _, drop in ipairs(type(scannerResult.drops) == "table" and scannerResult.drops or {}) do
                    local confidence = tonumber(drop.confidence) or 0
                    local source = tostring(drop.source or "")
                    if confidence >= 0.80
                        or source == "ResultGUIAsset"
                        or source == "ResultPassiveRegistry"
                        or source == "ResultTooltipAssetCache"
                        or source == "S_Rewards/Get" then
                        strongDrops[#strongDrops + 1] = drop
                    end
                end

                -- Server names are authoritative. The passive resolver may still
                -- keep asset IDs in the dump, but it cannot append barcode-style
                -- or guessed GUI names beside confirmed S_Rewards names.
                if data.serverNamedRewardsConfirmed ~= true and #strongDrops > 0 then
                    data.drops = sanitizeDrops(strongDrops)
                end

                if data.serverRewardCaptureOk == true then
                    data.rewardSource = data.serverNamedRewardsConfirmed == true
                        and "S_Rewards/Get"
                        or (#sanitizeDrops(strongDrops) > 0
                            and "S_Rewards/Get + ResultGUI fallback"
                            or "S_Rewards/Get")
                else
                    data.rewardSource = tostring(scannerResult.source or "ResultGUI")
                end
            elseif not scannerOk then
                V94RunRecorder.Record("REWARD_SCANNER_ERROR", tostring(scannerResult))
            end
        end

        if data.serverNamedRewardsConfirmed == true
            and type(V100ApplyWebhookRarities) == "function" then
            local orderedRewards = type(data.serverRewardInstances) == "table"
                and data.serverRewardInstances
                or data.drops
            local rarityOk, rarityRewards = pcall(
                V100ApplyWebhookRarities,
                root,
                orderedRewards
            )
            if rarityOk and type(rarityRewards) == "table" and #rarityRewards > 0 then
                data.drops = rarityRewards
            elseif not rarityOk then
                V94RunRecorder.Record("REWARD_RARITY_ERROR", tostring(rarityRewards))
            end
        end

        local finalExplicitRunType = detectExplicitRunType(statusLower, data.lines, root)
        if finalExplicitRunType then
            data.runType = finalExplicitRunType
            if finalExplicitRunType == "Mission" then
                data.raidName = nil
                data.raidChoice = ""
            end
        end

        V94RunRecorder.Finish(data)
		V94RunRecorder.Record("WEBHOOK_PARSE", V94Webhook.Status, {
			stableReads = stableRewardReads,
			drops = type(data.drops) == "table" and #data.drops or 0,
		})
        V51LastParsedResultData = data
        if tostring(data.runType or "Mission") == "Raid" and V51PhaseStats then
            local seconds = 0
            local m, s = string.match(tostring(data.timeTaken or ""), "(%d+):(%d+)")
            if m and s then seconds = tonumber(m) * 60 + tonumber(s) end
            if tostring(data.resultType) == "failed" then
                V51PhaseStats.Failed += 1
            else
                V51PhaseStats.Completed += 1
            end
            if seconds > 0 then
                V51PhaseStats.TotalSeconds += seconds
                if not V51PhaseStats.FastestSeconds or seconds < V51PhaseStats.FastestSeconds then V51PhaseStats.FastestSeconds = seconds end
            end
        end
		updateLastRunTracker(data)
		if StatsTracker and StatsTracker.AddResult then
			StatsTracker:AddResult(data)
		end
		if data.resultType == "failed" and WebhookConfig.sendFailed == false then
			V94Webhook.Status = "SKIPPED • failed-result webhooks disabled"
			V94RunRecorder.Record("WEBHOOK_SKIPPED", V94Webhook.Status)
			clearFinishedRunContext()
			return true
		end
		if data.resultType ~= "failed" and WebhookConfig.sendCompleted == false then
			V94Webhook.Status = "SKIPPED • completed-result webhooks disabled"
			V94RunRecorder.Record("WEBHOOK_SKIPPED", V94Webhook.Status)
			clearFinishedRunContext()
			return true
		end

        local signature = table.concat({
			tostring(data.runType or "Mission"),
			tostring(data.missionDisplay or "Unknown"),
            tostring(data.resultType or "result"),
            tostring(data.timeTaken or "Unknown"),
            tostring(data.titanKills or 0),
            tostring(data.damageDealt or 0),
            tostring(data.exp or 0),
            tostring(data.gold or 0),
			rewardSnapshotSignature(data),
        }, "|")

		if signature == lastWebhookSignature and tick() - lastWebhookSentAt < 90 then
			V94Webhook.Status = "SKIPPED • duplicate result snapshot"
			V94RunRecorder.Record("WEBHOOK_SKIPPED", V94Webhook.Status)
			clearFinishedRunContext()
			return false
		end

		lastWebhookSignature = signature
		lastWebhookSentAt = tick()
		V94Webhook.LastSentSignature = signature

		local embedOk, embedOrError = pcall(createMissionResultEmbed, data)
		if not embedOk then
			showNotification("Webhook failed", "Embed build error: " .. tostring(embedOrError), "error")
			V94Webhook.Status = "FAILED • embed build"
			V94RunRecorder.Record("WEBHOOK_FAILED", V94Webhook.Status)
			clearFinishedRunContext()
			return
		end

		local ok, result = sendWebhook(embedOrError)
		if ok then
			V94Webhook.Status = "SENT • verified " .. tostring(data.runType or "Mission") .. " result"
			V94RunRecorder.Record("WEBHOOK_SENT", V94Webhook.Status)
			showNotification("Webhook V2 sent", tostring(data.runType or "Mission") .. " stable result snapshot sent.", "success")
		else
			V94Webhook.Status = "FAILED • " .. tostring(result or "request error")
			V94RunRecorder.Record("WEBHOOK_FAILED", V94Webhook.Status)
			showNotification("Webhook failed", tostring(result or "Unknown request error"), "error")
		end

        -- Preserve the finished run's objectives through report creation, then clear for retry.
		clearFinishedRunContext()

        -- Result processing and Auto Retry must never depend on Discord accepting
        -- the webhook. A network failure is not a failed mission parse.
        return true
	end

    function V3ResultGuard.ProcessResult(root, statusLower)
        if V3ResultGuard.Processing then return end

        V3ResultGuard.Processing = true
        V3ResultGuard.Armed = false
        V3ResultGuard.ResultSeenSince = nil
        V3ResultGuard.LastAcceptedAt = os.clock()

        local okProcess, processError = xpcall(function()
            V51LastParsedResultData = nil
            local parsed = sendMissionResultFromGui(root, statusLower)

            local queueHandled = false
            local parsedData = V51LastParsedResultData
            if parsedData and tostring(parsedData.runType or "Mission") == "Raid" then
                queueHandled = V51QueueRuntime.HandleResult(parsedData) == true
            end

            -- Queue owns post-result travel only for an explicitly identified raid.
            -- Normal mission Auto Retry remains independent from webhook/scanner success.
            if queueHandled then
                task.spawn(function()
                    task.wait(0.8)
                    ReturnToLobby.Run()
                end)
            elseif parsed and State.AutoRetryEnabled
                and State.AutoRetrySuppressed ~= true
                and not (ReturnToLobby and (ReturnToLobby.Running or ReturnToLobby.Locked)) then
                handleAutoCycleFromResultGui(root)
            end
        end, function(err)
            return tostring(err)
        end)

        V3ResultGuard.Processing = false

        if not okProcess then
            V94Webhook.Status = "RESULT PROCESS ERROR • retry guard recovered"
            V94RunRecorder.Record("RESULT_PROCESS_ERROR", tostring(processError))
            warn("[SliceHub V9.8.4][RESULT]", tostring(processError))

            -- Last-resort reliability path: if the result GUI is still present,
            -- let Auto Retry attempt the proven native button route.
            if State.AutoRetryEnabled
                and State.AutoRetrySuppressed ~= true
                and not (ReturnToLobby and (ReturnToLobby.Running or ReturnToLobby.Locked)) then
                task.spawn(function()
                    task.wait(0.35)
                    local liveRoot = findMissionResultRoot()
                    if liveRoot then
                        handleAutoCycleFromResultGui(liveRoot)
                    end
                end)
            end
        end
    end

	local function monitorMissionCompletion()
		while true do
			task.wait(0.20)

            local now = os.clock()
			local root, statusLower = findMissionResultRoot()

			if root then
                V3ResultGuard.ActiveEvidenceSince = nil

                if V3ResultGuard.PanelStarting(root) then
                    -- Old result GUI is still visible while the next run is counting down.
                    resultScreenActive = false
                    V3ResultGuard.Armed = false
                    V3ResultGuard.ResultSeenSince = nil
                    continue
                end

                resultScreenActive = true

                if V3ResultGuard.Armed and not V3ResultGuard.Processing then
                    V3ResultGuard.ResultSeenSince =
                        V3ResultGuard.ResultSeenSince or now

                    if now - V3ResultGuard.ResultSeenSince >= 0.45 then
                        task.spawn(V3ResultGuard.ProcessResult, root, statusLower)
                    end
                end
			else
				resultScreenActive = false
                V3ResultGuard.ResultSeenSince = nil

                if not V3ResultGuard.Armed and not V3ResultGuard.Processing then
                    if V3ResultGuard.ActiveMissionEvidence() then
                        V3ResultGuard.ActiveEvidenceSince =
                            V3ResultGuard.ActiveEvidenceSince or now

                        if now - V3ResultGuard.ActiveEvidenceSince >= 0.80 then
                            V3ResultGuard.ResetTaskHistoryForRun()
                            V3ResultGuard.Armed = true
                            V3ResultGuard.ActiveEvidenceSince = nil
							local runMeta = V3MissionIdentity.GetRunMetadataForWebhook()
							V94RunRecorder.Begin({
								runType = runMeta.RunType,
								raid = runMeta.RaidName,
								difficulty = runMeta.Difficulty,
								mission = V3MissionIdentity.GetMissionDisplayForWebhook(),
							})
                            if RewardScannerV1 and RewardScannerV1.Begin then
                                pcall(RewardScannerV1.Begin, {
                                    runType = runMeta.RunType,
                                    raid = runMeta.RaidName,
                                    difficulty = runMeta.Difficulty,
                                    mission = V3MissionIdentity.GetMissionDisplayForWebhook(),
                                    raidChoice = runMeta.RaidChoice,
                                })
                            end
                            print("[SliceHub V9.8.4][RESULT] armed for current mission")
                        end
                    else
                        V3ResultGuard.ActiveEvidenceSince = nil
                    end
                end
			end
		end
	end

	task.spawn(monitorMissionCompletion)
	end

	startMissionWebhookMonitor()
end)()

