local function SHSerializeLua(value, depth)
    depth = depth or 0
    if depth > 16 then return "nil" end

    local valueType = type(value)
    if valueType == "nil" then return "nil" end
    if valueType == "boolean" or valueType == "number" then return tostring(value) end
    if valueType == "string" then return string.format("%q", value) end
    if valueType ~= "table" then return "nil" end

    local keys = {}
    for key in pairs(value) do keys[#keys + 1] = key end
    table.sort(keys, function(a, b)
        if type(a) == type(b) then return tostring(a) < tostring(b) end
        return type(a) < type(b)
    end)

    local parts = {"{"}
    for _, key in ipairs(keys) do
        local encodedKey
        if type(key) == "string" and string.match(key, "^[%a_][%w_]*$") then
            encodedKey = key
        else
            encodedKey = "[" .. SHSerializeLua(key, depth + 1) .. "]"
        end
        parts[#parts + 1] = encodedKey
            .. "="
            .. SHSerializeLua(value[key], depth + 1)
            .. ","
    end
    parts[#parts + 1] = "}"
    return table.concat(parts)
end

local function V5WriteBootstrap()
    local environment = nil

    pcall(function()
        if type(getgenv) == "function" then
            environment = getgenv()
        end
    end)

    local writeFn =
        environment and environment.writefile
        or type(writefile) == "function" and writefile
        or nil

    local makeFolderFn =
        environment and environment.makefolder
        or type(makefolder) == "function" and makefolder
        or nil

    local isFolderFn =
        environment and environment.isfolder
        or type(isfolder) == "function" and isfolder
        or nil

    local deleteFn =
        environment and environment.delfile
        or type(delfile) == "function" and delfile
        or nil

    if type(writeFn) ~= "function"
        or type(makeFolderFn) ~= "function" then
        return false, "file APIs unavailable"
    end

    local folderExists = false

    if type(isFolderFn) == "function" then
        local okFolder, result =
            pcall(isFolderFn, SH_CACHE_FOLDER)

        folderExists = okFolder and result == true
    end

    if not folderExists then
        pcall(makeFolderFn, SH_CACHE_FOLDER)
    end

    local bootstrap = table.concat({
        "local LOBBY_SOURCE = ",
        string.format("%q", LOBBY_SOURCE),
        "\n",
        "local MAINMENU_SOURCE = ",
        string.format("%q", MAINMENU_SOURCE),
        "\n",
        "local MISSION_SOURCE = ",
        string.format("%q", MISSION_SOURCE),
        "\n",
        "local KEY_GATE_SOURCE = ",
        string.format("%q", SLICEHUB_KEY_GATE_SOURCE),
        "\n",
        "local BUILD_TIER = ",
        string.format("%q", tostring(BUILD.Tier or "FREE")),
        "\n",
        "local BUILD_VERSION = ",
        string.format("%q", tostring(BUILD.Version or "9.8.3.4.5")),
        "\n",
        "local BUILD_PROFILE = ",
        SHSerializeLua(PROFILE),
        "\n",
        "local KEY_API_DEFAULT = ",
        string.format("%q", SLICEHUB_KEY_API_DEFAULT),
        "\n",
        "local DISCORD_INVITE = ",
        string.format("%q", SLICEHUB_DISCORD_INVITE),
        "\n",
        [=[
local pid = tonumber(game.PlaceId) or 0
local lobby = pid == 14916516914 or pid == 15393230099
local menu = pid == 13379208636 or pid == 15393224326
local selected =
    lobby and LOBBY_SOURCE
    or (menu and MAINMENU_SOURCE or MISSION_SOURCE)

local loader = loadstring or load
local environment =
    type(getgenv) == "function"
    and getgenv()
    or _G

local expectedTier = string.upper(tostring(environment.SliceHubExpectedTier or ""))
if expectedTier == "PREMIUM" and BUILD_TIER == "FREE" then
    warn("[SliceHub encrypted cache] ignored stale Free teleport payload")
    return
end

environment.SliceHub = type(environment.SliceHub) == "table" and environment.SliceHub or {}
environment.SliceHub.BuildTier = BUILD_TIER
environment.SliceHub.IsPremium = BUILD_TIER == "PREMIUM"
environment.SliceHub.Profile = BUILD_PROFILE
environment.SliceHubExpectedTier = BUILD_TIER

environment.SliceHubKeyGateConfig = {
    Source = selected,
    SourceName =
        lobby and "SliceHub Lobby Creator"
        or (
            menu
            and "AOT MainMenu Director"
            or "SliceHub AOT:R"
        ),
    BuildTier = BUILD_TIER,
    Version = BUILD_VERSION,
    ApiUrl = KEY_API_DEFAULT,
    DiscordInvite = DISCORD_INVITE,
}

if type(loader) == "function" then
    local gateChunk, gateError =
        loader(KEY_GATE_SOURCE)

    if type(gateChunk) == "function" then
        task.spawn(function()
            local ok, runtimeError =
                pcall(gateChunk)

            if not ok then
                warn(
                    "[SliceHub encrypted cache] key gate runtime error",
                    runtimeError
                )
            end
        end)
    else
        warn(
            "[SliceHub encrypted cache] key gate compile failed",
            gateError
        )
    end
end
]=],
    })

    local wrapper = SHBuildEncryptedWrapper(bootstrap)
    local okWrite, writeError =
        pcall(writeFn, SH_CACHE_FILE, wrapper)

    if okWrite and type(deleteFn) == "function" then
        -- V9.8.2.9.8: the old shared cache could be overwritten by the Free
        -- build and then downgrade a Premium teleport. Remove it after the
        -- active tier-specific cache is safely written.
        pcall(deleteFn, SH_LEGACY_SHARED_CACHE)
        pcall(deleteFn, SH_LEGACY_BOOTSTRAP)
        if BUILD.IsPremium == true then
            pcall(deleteFn, "SH/bootstrap_free.shc")
        end
    end

    return okWrite, writeError
end

pcall(V5WriteBootstrap)

local selectedName
local selectedSource
if isLobby then
    selectedName = "SliceHub Lobby Creator V9.4 • Unified Remaster"
    selectedSource = LOBBY_SOURCE
elseif isLikelyMainMenu then
    selectedName = "AOT MainMenu Director V5"
    selectedSource = MAINMENU_SOURCE
else
    selectedName = "SliceHub AOT:R V9.4.3 • Colossal Route Stability Hotfix"
    selectedSource = MISSION_SOURCE
end

if isLobby then
    MISSION_SOURCE = nil
    MAINMENU_SOURCE = nil
elseif isLikelyMainMenu then
    LOBBY_SOURCE = nil
    MISSION_SOURCE = nil
else
    LOBBY_SOURCE = nil
    MAINMENU_SOURCE = nil
end
if type(gcinfo) == "function" then
    print("[AOT All-In-One V9] memory KB", gcinfo())
end

local loader = loadstring or load
if type(loader) ~= "function" then
    __SliceHubCritical("[AOT All-In-One V9] loadstring/load is unavailable.")
    return
end

local environment =
    type(getgenv) == "function"
    and getgenv()
    or _G

environment.SliceHubKeyGateConfig = {
    Source = selectedSource,
    SourceName = selectedName,
    BuildTier = tostring(BUILD.Tier or "FREE"),
    Version = tostring(BUILD.Version or "9.8.3.4.5"),
    ApiUrl = SLICEHUB_KEY_API_DEFAULT,
    DiscordInvite = SLICEHUB_DISCORD_INVITE,
}

local sourcePreflight, sourceCompileError =
    loader(selectedSource)

if type(sourcePreflight) ~= "function" then
    __SliceHubCritical(
        "[AOT All-In-One V9] "
        .. selectedName
        .. " compile failed: "
        .. tostring(sourceCompileError)
    )
    return
end

sourcePreflight = nil

local gateCompiled, gateCompileError =
    loader(SLICEHUB_KEY_GATE_SOURCE)

if type(gateCompiled) ~= "function" then
    __SliceHubCritical(
        "[AOT All-In-One V9] Key gate compile failed: "
        .. tostring(gateCompileError)
    )
    return
end

print(
    "[AOT All-In-One V9] waiting for key approval",
    selectedName
)

task.spawn(function()
    local ok, runtimeError =
        pcall(gateCompiled)

    if not ok then
        __SliceHubCritical(
            "[AOT All-In-One V9] Key gate runtime error: "
            .. tostring(runtimeError)
        )
    end
end)
